window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["农业农村部"] = {"nongyezhiwupinzhongbaohuminglu-11":[],"nongyezhiwupinzhongbaohuminglu-5":[],"nongyezhiwupinzhongbaohuminglu-9":[],"nongyezhiwupinzhongbaohuminglu-3":[],"nongyezhiwupinzhongbaohuminglu-10":[],"nongyezhiwupinzhongbaohuminglu-7":[],"nongyezhiwupinzhongbaohuminglu-4":[],"nongyezhiwupinzhongbaohuminglu-6":[],"nongyezhiwupinzhongbaohuminglu":[],"nongyezhiwupinzhongbaohuminglu-2":[],"nongyezhiwupinzhongbaohuminglu-8":[],"nongcuntudichengbaojingyingquanzhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为稳定和完善农村土地承包关系，维护承包方依法取得的土地承包经营权，加强农村土地承包经营权证管理，根据《中华人民共和国农村土地承包法》，制定本办法。"},{"i":2,"n":"第二条","txt":"农村土地承包经营权证是农村土地承包合同生效后，国家依法确认承包方享有土地承包经营权的法律凭证。 农村土地承包经营权证只限承包方使用。"},{"i":3,"n":"第三条","txt":"承包耕地、园地、荒山、荒沟、荒丘、荒滩等农村土地从事种植业生产活动，承包方依法取得农村土地承包经营权后，应颁发农村土地承包经营权证予以确认。 承包草原、水面、滩涂从事养殖业生产活动的，依照《中华人民共和国草原法》、《中华人民共和国渔业法》等有关规定确权发证。"},{"i":4,"n":"第四条","txt":"实行家庭承包经营的承包方，由县级以上地方人民政府颁发农村土地承包经营权证。 实行其它方式承包经营的承包方，经依法登记，由县级以上地方人民政府颁发农村土地承包经营权证。 县级以上地方人民政府农业行政主管部门负责农村土地承包经营权证的备案、登记、发放等具体工作。"},{"i":5,"n":"第五条","txt":"农村土地承包经营权证所载明的权利有效期限，应与依法签订的土地承包合同约定的承包期一致。"},{"i":6,"n":"第六条","txt":"农村土地承包经营权证应包括以下内容： （一）名称和编号； （二）发证机关及日期； （三）承包期限和起止日期； （四）承包土地名称、坐落、面积、用途； （五）农村土地承包经营权变动情况； （六）其他应当注明的事项。"},{"i":7,"n":"第七条","txt":"实行家庭承包的，按下列程序颁发农村土地承包经营权证： （一）土地承包合同生效后，发包方应在30个工作日内，将土地承包方案、承包方及承包土地的详细情况、土地承包合同等材料一式两份报乡（镇）人民政府农村经营管理部门。 （二）乡（镇）人民政府农村经营管理部门对发包方报送的材料予以初审。材料符合规定的，及时登记造册，由乡（镇）人 民政府向县级以上地方人民政府提出颁发农村土地承包经营权证的书面申请；材料不符合规定的，应在15个工作日内补正。 （三）县级以上地方人民政府农业行政主管部门对乡（镇）人民政府报送的申请材料予以审核。申请材料符合规定的，编制 农村土地承包经营权证登记簿，报同级人民政府颁发农村土地承包经营权证；申请材料不符合规定的，书面通知乡（镇）人民政府补正。"},{"i":8,"n":"第八条","txt":"实行招标、拍卖、公开协商等方式承包农村土地的，按下列程序办理农村土地承包经营权证： （一）土地承包合同生效后，承包方填写农村土地承包经营权证登记申请书，报承包土地所在乡（镇）人民政府农村经营管理部门。 （二）乡（镇）人民政府农村经营管理部门对发包方和承包方的资格、发包程序、承包期限、承包地用途等予以初审，并在农村土地承包经营权证登记申请书上签署初审意见。 （三）承包方持乡（镇）人民政府初审通过的农村土地承包经营权登记申请书，向县级以上地方人民政府申请农村土地承包经营权证登记。 （四）县级以上地方人民政府农业行政主管部门对登记申请予以审核。申请材料符合规定的，编制农村土地承包经营权证登记簿，报请同级人民政府颁发农村土地承包经营权证；申请材料不符合规定的，书面通知申请人补正。"},{"i":9,"n":"第九条","txt":"农村土地承包经营权证登记簿记载农村土地承包经营权的基本内容。农村土地承包经营权证、农村土地承包合同、农 村土地承包经营权证登记簿记载的事项应一致。"},{"i":10,"n":"第十条","txt":"农村土地承包经营权证登记簿、承包合同登记及其他登记材料，由县级以上地方农业行政主管部门管理。 农村土地承包方有权查阅、复制农村土地承包经营权证登记簿和其他登记材料。县级以上农业行政主管部门不得限制和阻挠。"},{"i":11,"n":"第十一条","txt":"农村土地承包当事人认为农村土地承包经营权证和登记簿记载错误的，有权申请更正。"},{"i":12,"n":"第十二条","txt":"乡（镇）农村经营管理部门和县级以上地方人民政府农业行政主管部门在办理农村土地承包经营权证过程中应当履行下列职责： （一）查验申请人提交的有关材料； （二）就有关登记事项询问申请人； （三）如实、及时地登记有关事项； （四）需要实地查看的，应进行查验。在实地查验过程中，申请人有义务给予协助。"},{"i":13,"n":"第十三条","txt":"乡（镇）人民政府农村经营管理部门领取农村土地承包经营权证后，应在30个工作日内将农村土地承包经营权证发给承包方。发包方不得为承包方保存农村土地承包经营权证。"},{"i":14,"n":"第十四条","txt":"承包期内，承包方采取转包、出租、入股方式流转土地承包经营权的，不须办理农村土地承包经营权证变更。 采取转让、互换方式流转土地承包经营权的，当事人可以要求办理农村土地承包经营权证变更登记。 因转让、互换以外的其他方式导致农村土地承包经营权分立、合并的，应当办理农村土地承包经营权证变更。"},{"i":15,"n":"第十五条","txt":"办理农村土地承包经营权变更申请应提交以下材料： （一）变更的书面请求； （二）已变更的农村土地承包合同或其它证明材料； （三）农村土地承包经营权证原件。"},{"i":16,"n":"第十六条","txt":"乡（镇）人民政府农村经营管理部门受理变更申请后，应及时对申请材料进行审核。符合规定的，报请原发证机关办理变更手续，并在农村土地承包经营权证登记簿上记载。"},{"i":17,"n":"第十七条","txt":"农村土地承包经营权证严重污损、毁坏、遗失的，承包方应向乡（镇）人民政府农村经营管理部门申请换发、补发。 经乡（镇）人民政府农村经营管理部门审核后，报请原发证机关办理换发、补发手续。"},{"i":18,"n":"第十八条","txt":"办理农村土地承包经营权证换发、补发手续，应以农村土地经营权证登记簿记载的内容为准。"},{"i":19,"n":"第十九条","txt":"农村土地承包经营权证换发、补发，应当在农村土地承包经营权证上注明“换发”、“补发”字样。"},{"i":20,"n":"第二十条","txt":"承包期内，发生下列情形之一的，应依法收回农村土地承包经营权证： （一）承包期内，承包方全家迁入设区的市，转为非农业户口的。 （二）承包期内，承包方提出书面申请，自愿放弃全部承包土地的。 （三）承包土地被依法征用、占用，导致农村土地承包经营权全部丧失的。 （四）其他收回土地承包经营权证的情形。"},{"i":21,"n":"第二十一条","txt":"符合本办法第二十条规定，承包方无正当理由拒绝交回农村土地承包经营权证的，由原发证机关注销该证（包括编号），并予以公告。"},{"i":22,"n":"第二十二条","txt":"收回的农村土地承包经营权证，应退回原发证机关，加盖“作废”章。"},{"i":23,"n":"第二十三条","txt":"县级人民政府农业行政主管部门和乡（镇）人民政府要完善农村土地承包方案、农村土地承包合同、农村土地承 包经营权证及其相关文件档案的管理制度，建立健全农村土地承包信息化管理系统。"},{"i":24,"n":"第二十四条","txt":"地方各级人民政府农业行政主管部门要加强对农村土地承包经营权证的发放管理，确保农村土地承包经营权证全部落实到户。"},{"i":25,"n":"第二十五条","txt":"对不按规定及时发放农村土地承包经营权证的责任人，予以批评教育；造成严重后果的，应追究行政责任。"},{"i":26,"n":"第二十六条","txt":"颁发农村土地承包经营权证，除工本费外，不得向承包方收取任何费用。 农村土地承包经营权证工本费的支出要严格执行国家有关财务管理的规定。"},{"i":27,"n":"第二十七条","txt":"本办法实施以前颁发的农村土地承包经营权证，符合《农村土地承包法》有关规定，并已加盖县级以上地方人民政府印章的，继续有效。个别条款如承包期限、承包方承担义务等违反《农村土地承包法》规定的，该条款无效，是否换发新证，由承包方决定。 未加盖县级以上地方人民政府印章的，应按本《办法》规定重新颁发。重新颁发农村土地承包经营权证，土地承包期限应符合 《农村土地承包法》的有关规定，不得借机调整土地。"},{"i":28,"n":"第二十八条","txt":"农村土地承包经营权证由农业部监制，由省级人民政府农业行政主管部门统一组织印制，加盖县级以上地方人民政府印章。"},{"i":29,"n":"第二十九条","txt":"本办法由农业部负责解释。"},{"i":30,"n":"第三十条","txt":"本办法自2004年1月1日起正式施行"}],"zhiwuxinpinzhongbaohutiaolishishixize-2":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国植物新品种保护条例》（以下简称《条例》），制定本细则。"},{"i":2,"n":"第二条","txt":"农业植物新品种包括粮食、棉花、油料、麻类、糖料、蔬菜（含西甜瓜）、烟草、桑树、茶树、果树（干果除外）、观赏植物（木本除外）、草类、绿肥、草本药材、食用菌、藻类和橡胶树等植物的新品种。"},{"i":3,"n":"第三条","txt":"依据《条例》第三条的规定，农业部为农业植物新品种权的审批机关，依照《条例》规定授予农业植物新品种权（以下简称品种权）。 农业部植物新品种保护办公室（以下简称品种保护办公室），承担品种权申请的受理、审查等事务，负责植物新品种测试和繁殖材料保藏的组织工作。"},{"i":4,"n":"第四条","txt":"对危害公共利益、生态环境的植物新品种不授予品种权。"},{"i":5,"n":"第五条","txt":"《条例》所称繁殖材料是指可繁殖植物的种植材料或植物体的其他部分，包括籽粒、果实和根、茎、苗、芽、叶等。"},{"i":6,"n":"第六条","txt":"申请品种权的单位或者个人统称为品种权申请人；获得品种权的单位或者个人统称为品种权人。"},{"i":7,"n":"第七条","txt":"《条例》第七条所称执行本单位任务所完成的职务育种是指下列情形之一： （一）在本职工作中完成的育种； （二）履行本单位交付的本职工作之外的任务所完成的育种； （三）退职、退休或者调动工作后，3年内完成的与其在原单位承担的工作或者原单位分配的任务有关的育种。 《条例》第七条所称本单位的物质条件是指本单位的资金、仪器设备、试验场地以及单位所有的尚未允许公开的育种材料和技术资料等。"},{"i":8,"n":"第八条","txt":"《条例》第八条所称完成新品种育种的人是指完成新品种育种的单位或者个人（以下简称育种者）。"},{"i":9,"n":"第九条","txt":"完成新品种培育的人员（以下简称培育人）是指对新品种培育作出创造性贡献的人。仅负责组织管理工作、为物质条件的利用提供方便或者从事其他辅助工作的人不能被视为培育人。"},{"i":10,"n":"第十条","txt":"一个植物新品种只能被授予一项品种权。 一个植物新品种由两个以上申请人分别于同一日内提出品种权申请的，由申请人自行协商确定申请权的归属；协商不能达成一致意见的，品种保护办公室可以要求申请人在指定期限内提供证据，证明自己是最先完成该新品种育种的人。逾期未提供证据的，视为撤回申请；所提供证据不足以作为判定依据的，品种保护办公室驳回申请。"},{"i":11,"n":"第十一条","txt":"中国的单位或者个人就其在国内培育的新品种向外国人转让申请权或者品种权的，应当向农业部申请审批。 转让申请权或者品种权的，当事人应当订立书面合同，向农业部登记，由农业部予以公告，并自公告之日起生效。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，农业部可以作出实施品种权的强制许可决定： （一）为了国家利益或者公共利益的需要； （二）品种权人无正当理由自己不实施，又不许可他人以合理条件实施的； （三）对重要农作物品种，品种权人虽已实施，但明显不能满足国内市场需求，又不许可他人以合理条件实施的。 申请强制许可的，应当向农业部提交强制许可请求书，说明理由并附具有关证明文件各一式两份。 农业部自收到请求书之日起20个工作日内作出决定。需要组织专家调查论证的，调查论证时间不得超过3个月。同意强制许可请求的，由农业部通知品种权人和强制许可请求人，并予以公告；不同意强制许可请求的，通知请求人并说明理由。"},{"i":13,"n":"第十三条","txt":"依照《条例》第十一条第二款规定，申请农业部裁决使用费数额的，当事人应当提交裁决申请书，并附具未能达成协议的证明文件。农业部自收到申请书之日起3个月内作出裁决并通知当事人。"},{"i":14,"n":"第十四条","txt":"依照《条例》第四十五条的规定，列入植物新品种保护名录的植物属或者种，从名录公布之日起1年内提出的品种权申请，凡经过育种者许可，申请日前在中国境内销售该品种的繁殖材料未超过4年，符合《条例》规定的特异性、一致性和稳定性及命名要求的，农业部可以授予品种权。"},{"i":15,"n":"第十五条","txt":"具有下列情形之一的，属于《条例》第十四条规定的销售： （一）以买卖方式将申请品种的繁殖材料转移他人； （二）以易货方式将申请品种的繁殖材料转移他人； （三）以入股方式将申请品种的繁殖材料转移他人； （四）以申请品种的繁殖材料签订生产协议； （五）以其他方式销售的情形。 具有下列情形之一的，视为《条例》第十四条规定的育种者许可销售： （一）育种者自己销售； （二）育种者内部机构销售； （三）育种者的全资或者参股企业销售； （四）农业部规定的其他情形。"},{"i":16,"n":"第十六条","txt":"《条例》第十五条所称“已知的植物品种”，包括品种权申请初审合格公告、通过品种审定或者已推广应用的品种。"},{"i":17,"n":"第十七条","txt":"《条例》第十六条、第十七条所称“相关的特征或者特性”是指至少包括用于特异性、一致性和稳定性测试的性状或者授权时进行品种描述的性状。"},{"i":18,"n":"第十八条","txt":"有下列情形之一的，不得用于新品种命名： （一）仅以数字组成的； （二）违反国家法律或者社会公德或者带有民族歧视性的； （三）以国家名称命名的； （四）以县级以上行政区划的地名或者公众知晓的外国地名命名的； （五）同政府间国际组织或者其他国际国内知名组织及标识名称相同或者近似的； （六）对植物新品种的特征、特性或者育种者的身份等容易引起误解的； （七）属于相同或相近植物属或者种的已知名称的； （八）夸大宣传的。 已通过品种审定的品种，或获得《农业转基因生物安全证书（生产应用）》的转基因植物品种，如品种名称符合植物新品种命名规定，申请品种权的品种名称应当与品种审定或农业转基因生物安全审批的品种名称一致。"},{"i":19,"n":"第十九条","txt":"中国的单位和个人申请品种权的，可以直接或者委托代理机构向品种保护办公室提出申请。 在中国没有经常居所的外国人、外国企业或其他外国组织，向品种保护办公室提出品种权申请的，应当委托代理机构办理。 申请人委托代理机构办理品种权申请等相关事务时，应当与代理机构签订委托书，明确委托办理事项与权责。代理机构在向品种保护办公室提交申请时，应当同时提交申请人委托书。品种保护办公室在上述申请的受理与审查程序中，直接与代理机构联系。"},{"i":20,"n":"第二十条","txt":"申请品种权的，申请人应当向品种保护办公室提交请求书、说明书和品种照片各一式两份，同时提交相应的请求书和说明书的电子文档。 请求书、说明书按照品种保护办公室规定的统一格式填写。"},{"i":21,"n":"第二十一条","txt":"申请人提交的说明书应当包括下列内容： （一）申请品种的暂定名称，该名称应当与请求书的名称一致； （二）申请品种所属的属或者种的中文名称和拉丁文名称； （三）育种过程和育种方法，包括系谱、培育过程和所使用的亲本或者其他繁殖材料来源与名称的详细说明； （四）有关销售情况的说明； （五）选择的近似品种及理由； （六）申请品种特异性、一致性和稳定性的详细说明； （七）适于生长的区域或者环境以及栽培技术的说明； （八）申请品种与近似品种的性状对比表。 前款第（五）、（八）项所称近似品种是指在所有已知植物品种中，相关特征或者特性与申请品种最为相似的品种。"},{"i":22,"n":"第二十二条","txt":"申请人提交的照片应当符合以下要求： （一）照片有利于说明申请品种的特异性； （二）申请品种与近似品种的同一种性状对比应在同一张照片上； （三）照片应为彩色，必要时，品种保护办公室可以要求申请人提供黑白照片； （四）照片规格为8.5厘米×12.5厘米或者10厘米×15厘米； （五）关于照片的简要文字说明。"},{"i":23,"n":"第二十三条","txt":"品种权申请文件有下列情形之一的，品种保护办公室不予受理： （一）未使用中文的； （二）缺少请求书、说明书或者照片之一的； （三）请求书、说明书和照片不符合本细则规定格式的； （四）文件未打印的； （五）字迹不清或者有涂改的； （六）缺少申请人和联系人姓名（名称）、地址、邮政编码的或者不详的； （七）委托代理但缺少代理委托书的。"},{"i":24,"n":"第二十四条","txt":"中国的单位或者个人将国内培育的植物新品种向国外申请品种权的，应当向所在地省级人民政府农业行政主管部门申请登记。"},{"i":25,"n":"第二十五条","txt":"申请人依照《条例》第二十三条的规定要求优先权的，应当在申请中写明第一次提出品种权申请的申请日、申请号和受理该申请的国家或组织；未写明的，视为未要求优先权。申请人提交的第一次品种权申请文件副本应当经原受理机关确认。"},{"i":26,"n":"第二十六条","txt":"在中国没有经常居所或者营业所的外国人、外国企业和外国其他组织，申请品种权或者要求优先权的，品种保护办公室认为必要时，可以要求其提供下列文件： （一）申请人是个人的，其国籍证明； （二）申请人是企业或者其他组织的，其营业所或者总部所在地的证明； （三）外国人、外国企业、外国其他组织的所属国，承认中国单位和个人可以按照该国国民的同等条件，在该国享有品种申请权、优先权和其他与品种权有关的权利的证明文件。"},{"i":27,"n":"第二十七条","txt":"申请人在向品种保护办公室提出品种权申请12个月内，又向国外申请品种权的，依照该国或组织同中华人民共和国签订的协议或者共同参加的国际条约，或者根据相互承认优先权的原则，可以请求品种保护办公室出具优先权证明文件。"},{"i":28,"n":"第二十八条","txt":"依照《条例》第十九条第二款规定，中国的单位和个人申请品种权的植物新品种涉及国家安全或者重大利益需要保密的，申请人应当在申请文件中说明，品种保护办公室经过审查后作出是否按保密申请处理的决定，并通知申请人；品种保护办公室认为需要保密而申请人未注明的，仍按保密申请处理，并通知申请人。"},{"i":29,"n":"第二十九条","txt":"申请人送交的申请品种繁殖材料应当与品种权申请文件中所描述的繁殖材料相一致，并符合下列要求： （一）未遭受意外损害； （二）未经过药物处理； （三）无检疫性的有害生物； （四）送交的繁殖材料为籽粒或果实的，籽粒或果实应当是最近收获的。"},{"i":30,"n":"第三十条","txt":"品种保护办公室认为必要的，申请人应当送交申请品种和近似品种的繁殖材料，用于申请品种的审查和检测。申请品种属于转基因品种的，应当附具生产性试验阶段的《农业转基因生物安全审批书》或《农业转基因生物安全证书（生产应用）》复印件。 申请人应当自收到品种保护办公室通知之日起3个月内送交繁殖材料。送交繁殖材料为籽粒或果实的，应当送至品种保护办公室植物新品种保藏中心（以下简称保藏中心）；送交种苗、种球、块茎、块根等无性繁殖材料的，应当送至品种保护办公室指定的测试机构。 申请人送交的繁殖材料数量少于品种保护办公室规定的，保藏中心或者测试机构应当通知申请人，申请人应自收到通知之日起1个月内补足。特殊情况下，申请人送交了规定数量的繁殖材料后仍不能满足测试或者检测需要时，品种保护办公室有权要求申请人补交。"},{"i":31,"n":"第三十一条","txt":"繁殖材料应当依照有关规定实施植物检疫。检疫不合格或者未经检疫的，保藏中心或者测试机构不予接收。 保藏中心或者测试机构收到申请人送交的繁殖材料后应当出具书面证明，并在收到繁殖材料之日起20个工作日内（有休眠期的植物除外）完成生活力等内容的检测。检测合格的，应当向申请人出具书面检测合格证明；检测不合格的，应当通知申请人自收到通知之日起1个月内重新送交繁殖材料并取回检测不合格的繁殖材料，申请人到期不取回的，保藏中心或者测试机构应当销毁。 申请人未按规定送交繁殖材料的，视为撤回申请。"},{"i":32,"n":"第三十二条","txt":"保藏中心和测试机构对申请品种的繁殖材料负有保密的责任，应当防止繁殖材料丢失、被盗等事故的发生，任何人不得更换检验合格的繁殖材料。发生繁殖材料丢失、被盗、更换的，依法追究有关人员的责任。"},{"i":33,"n":"第三十三条","txt":"在初步审查、实质审查、复审和无效宣告程序中进行审查和复审人员有下列情形之一的，应当自行回避，当事人或者其他利害关系人可以要求其回避： （一）是当事人或者其代理人近亲属的； （二）与品种权申请或者品种权有直接利害关系的； （三）与当事人或者其代理人有其他关系，可能影响公正审查和审理的。 审查人员的回避由品种保护办公室决定，复审人员的回避由植物新品种复审委员会主任决定。"},{"i":34,"n":"第三十四条","txt":"一件植物品种权申请包括两个以上新品种的，品种保护办公室应当要求申请人提出分案申请。申请人在指定期限内对其申请未进行分案修正或者期满未答复的，视为撤回申请。 申请人按照品种保护办公室要求提出的分案申请，可以保留原申请日；享有优先权的，可保留优先权日。但不得超出原申请文件已有内容的范围。 分案申请应当依照《条例》及本细则的规定办理相关手续。 分案申请的请求书中应当写明原申请的申请号和申请日。原申请享有优先权的，应当提交原申请的优先权文件副本。"},{"i":35,"n":"第三十五条","txt":"品种保护办公室对品种权申请的下列内容进行初步审查： （一）是否符合《条例》第二十七条规定； （二）选择的近似品种是否适当；申请品种的亲本或其他繁殖材料来源是否公开。 品种保护办公室应当将审查意见通知申请人。品种保护办公室有疑问的，可要求申请人在指定期限内陈述意见或者补正；申请人期满未答复的，视为撤回申请。申请人陈述意见或者补正后，品种保护办公室认为仍然不符合规定的，应当驳回其申请。"},{"i":36,"n":"第三十六条","txt":"除品种权申请文件外，任何人向品种保护办公室提交的与品种权申请有关的材料，有下列情形之一的，视为未提出： （一）未使用规定的格式或者填写不符合要求的； （二）未按照规定提交证明材料的。 当事人当面提交材料的，受理人员应当当面说明材料存在的缺陷后直接退回；通过邮局提交的，品种保护办公室应当将视为未提出的审查意见和原材料一起退回；邮寄地址不清的，采用公告方式退回。"},{"i":37,"n":"第三十七条","txt":"自品种权申请之日起至授予品种权之日前，任何人均可以对不符合《条例》第八条、第十三至第十八条以及本细则第四条规定的品种权申请，向品种保护办公室提出异议，并提供相关证据和说明理由。未提供相关证据的，品种保护办公室不予受理。"},{"i":38,"n":"第三十八条","txt":"未经品种保护办公室批准，申请人在品种权授予前不得修改申请文件的下列内容： （一）申请品种的名称、申请品种的亲本或其他繁殖材料名称、来源以及申请品种的育种方法； （二）申请品种的最早销售时间； （三）申请品种的特异性、一致性和稳定性内容。 品种权申请文件的修改部分，除个别文字修改或者增删外，应当按照规定格式提交替换页。"},{"i":39,"n":"第三十九条","txt":"品种保护办公室负责对品种权申请进行实质审查，并将审查意见通知申请人。品种保护办公室可以根据审查的需要，要求申请人在指定期限内陈述意见或者补正。申请人期满未答复的，视为撤回申请。"},{"i":40,"n":"第四十条","txt":"依照《条例》和本细则的规定，品种权申请经实质审查应当予以驳回的情形是指： （一）不符合《条例》第八条、第十三条至第十七条规定之一的； （二）属于本细则第四条规定的； （三）不符合命名规定，申请人又不按照品种保护办公室要求修改的； （四）申请人陈述意见或者补正后，品种保护办公室认为仍不符合规定的。"},{"i":41,"n":"第四十一条","txt":"品种保护办公室发出办理授予品种权手续的通知后，申请人应当自收到通知之日起2个月内办理相关手续和缴纳第1年年费。对按期办理的，农业部授予品种权，颁发品种权证书，并予以公告。品种权自授权公告之日起生效。 期满未办理的，视为放弃取得品种权的权利。"},{"i":42,"n":"第四十二条","txt":"农业部植物新品种复审委员会，负责审理驳回品种权申请的复审案件、品种权无效宣告案件和授权品种更名案件。具体规定由农业部另行制定。"},{"i":43,"n":"第四十三条","txt":"依照《条例》和本细则规定提交的各种文件应当使用中文，并采用国家统一规定的科学技术术语和规范词。外国人名、地名和科学技术术语没有统一中文译文的，应当注明原文。 依照《条例》和本细则规定提交的各种证件和证明文件是外文的，应当附送中文译文；未附送的，视为未提交该证明文件。"},{"i":44,"n":"第四十四条","txt":"当事人向品种保护办公室提交的各种文件应当打印或者印刷，字迹呈黑色，并整齐清晰。申请文件的文字部分应当横向书写，纸张只限单面使用。"},{"i":45,"n":"第四十五条","txt":"当事人提交的各种文件和办理的其他手续，应当由申请人、品种权人、其他利害关系人或者其代表人签字或者盖章；委托代理机构的，由代理机构盖章。请求变更培育人姓名、品种权申请人和品种权人的姓名或者名称、国籍、地址、代理机构的名称和代理人姓名的，应当向品种保护办公室办理著录事项变更手续，并附具变更理由的证明材料。"},{"i":46,"n":"第四十六条","txt":"当事人提交各种材料时，可以直接提交，也可以邮寄。邮寄时，应当使用挂号信函，不得使用包裹，一件信函中应当只包含同一申请的相关材料。邮寄的，以寄出的邮戳日为提交日。信封上寄出的邮戳日不清晰的，除当事人能够提供证明外，以品种保护办公室的收到日期为提交日。 品种保护办公室的各种文件，可以通过邮寄、直接送交或者以公告的方式送达当事人。当事人委托代理机构的，文件送交代理机构；未委托代理机构的，文件送交请求书中收件人地址及收件人或者第一署名人或者代表人。当事人拒绝接收文件的，该文件视为已经送达。 品种保护办公室邮寄的各种文件，自文件发出之日起满15日，视为当事人收到文件之日。 根据规定应当直接送交的文件，以交付日为送达日。文件送达地址不清，无法邮寄的，可以通过公告的方式送达当事人。自公告之日起满2个月，该文件视为已经送达。"},{"i":47,"n":"第四十七条","txt":"《条例》和本细则规定的各种期限的第一日不计算在期限内。期限以年或者月计算的，以其最后一月的相应日为期限届满日；该月无相应日的，以该月最后一日为期限届满日。期限届满日是法定节假日的，以节假日后的第一个工作日为期限届满日。"},{"i":48,"n":"第四十八条","txt":"当事人因不可抗力而耽误《条例》或者本细则规定的期限或者品种保护办公室指定的期限，导致其权利丧失的，自障碍消除之日起2个月内，最迟自期限届满之日起2年内，可以向品种保护办公室说明理由并附具有关证明文件，请求恢复其权利。 当事人因正当理由而耽误《条例》或者本细则规定的期限或者品种保护办公室指定的期限，造成其权利丧失的，可以自收到通知之日起2个月内向品种保护办公室说明理由，请求恢复其权利。 当事人请求延长品种保护办公室指定期限的，应当在期限届满前，向品种保护办公室说明理由并办理有关手续。 本条第一款和第二款的规定不适用《条例》第十四条、第二十三条、第三十二条第二、三款、第三十四条、第三十七条第二款规定的期限。"},{"i":49,"n":"第四十九条","txt":"除《条例》第二十二条的规定外，《条例》所称申请日，有优先权的，指优先权日。"},{"i":50,"n":"第五十条","txt":"申请品种权和办理其他手续时，应当按照国家有关规定向农业部缴纳申请费、审查费、年费。"},{"i":51,"n":"第五十一条","txt":"《条例》和本细则规定的各种费用，可以直接缴纳，也可以通过邮局或者银行汇付。 通过邮局或者银行汇付的，应当注明品种名称，同时将汇款凭证的复印件传真或者邮寄至品种保护办公室，并说明该费用的申请号或者品种权号、申请人或者品种权人的姓名或名称、费用名称。 通过邮局或者银行汇付的，以汇出日为缴费日。"},{"i":52,"n":"第五十二条","txt":"依照《条例》第二十四条的规定，申请人可以在提交品种权申请的同时缴纳申请费，但最迟自申请之日起1个月内缴纳申请费，期满未缴纳或者未缴足的，视为撤回申请。"},{"i":53,"n":"第五十三条","txt":"经初步审查合格的品种权申请，申请人应当按照品种保护办公室的通知，在规定的期限内缴纳审查费。期满未缴纳或者未缴足的，视为撤回申请。"},{"i":54,"n":"第五十四条","txt":"申请人在领取品种权证书前，应当缴纳授予品种权第1年的年费。以后的年费应当在前1年度期满前1个月内预缴。"},{"i":55,"n":"第五十五条","txt":"品种权人未按时缴纳授予品种权第1年以后的年费，或者缴纳的数额不足的，品种保护办公室应当通知申请人自应当缴纳年费期满之日起6个月内补缴；期满未缴纳的，自应当缴纳年费期满之日起，品种权终止。"},{"i":56,"n":"第五十六条","txt":"品种保护办公室定期发布植物新品种保护公报，公告品种权有关内容。"},{"i":57,"n":"第五十七条","txt":"《条例》第四十条、第四十一条所称的假冒授权品种行为是指下列情形之一： （一）印制或者使用伪造的品种权证书、品种权申请号、品种权号或者其他品种权申请标记、品种权标记； （二）印制或者使用已经被驳回、视为撤回或者撤回的品种权申请的申请号或者其他品种权申请标记； （三）印制或者使用已经被终止或者被宣告无效的品种权的品种权证书、品种权号或者其他品种权标记； （四）生产或者销售本条第（一）项、第（二）项和第（三）项所标记的品种； （五）生产或销售冒充品种权申请或者授权品种名称的品种； （六）其他足以使他人将非品种权申请或者非授权品种误认为品种权申请或者授权品种的行为。"},{"i":58,"n":"第五十八条","txt":"农业行政部门根据《条例》第四十一条的规定对封存或者扣押的植物品种繁殖材料，应当在30日内做出处理；情况复杂的，经农业行政部门负责人批准可以延长，延长期限不超过30日。"},{"i":59,"n":"第五十九条","txt":"当事人因品种申请权或者品种权发生纠纷，向人民法院提起诉讼并且人民法院已受理的，可以向品种保护办公室请求中止有关程序。 依照前款规定申请中止有关程序的，应当向品种保护办公室提交申请书，并附具人民法院的有关受理文件副本。 在人民法院作出的判决生效后，当事人应当向品种保护办公室请求恢复有关程序。自请求中止之日起1年内，有关品种申请权或者品种权归属的纠纷未能结案，需要继续中止有关程序的，请求人应当在该期限内请求延长中止。期满未请求延长的，品种保护办公室可以自行恢复有关程序。"},{"i":60,"n":"第六十条","txt":"已被视为撤回、驳回和主动撤回的品种权申请的案卷，自该品种权申请失效之日起满2年后不予保存。 已被宣告无效的品种权案卷自该品种权无效宣告之日起，终止的品种权案卷自该品种权失效之日起满3年后不予保存。"},{"i":61,"n":"第六十一条","txt":"本细则自2008年1月1日起施行。1999年6月16日农业部发布的《中华人民共和国植物新品种保护条例实施细则（农业部分）》同时废止。"}],"shuishengyeshengdongwuliyongtexubanfa":[{"i":1,"n":"第一条","txt":"为保护、发展和合理利用水生野生动物资源，加强水生野生动物的保护与管理，规范水生野生动物利用特许证件的发放及使用，根据《中华人民共和国野生动物保护法》、《中华人民共和国水生野生动物保护实施条例》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"凡需要捕捉、人工繁育以及展览、表演、出售、收购、进出口等利用水生野生动物或其制品的，按照本办法实行特许管理。 除第二十九条、第三十一条外，本办法所称水生野生动物，是指珍贵、濒危的水生野生动物；所称水生野生动物制品，是指珍贵、濒危水生野生动物的任何部分及其衍生物。"},{"i":3,"n":"第三条","txt":"农业部主管全国水生野生动物利用特许管理工作，负责国家一级保护水生野生动物的捕捉、水生野生动物或其制品进出口和国务院规定由农业部负责的国家重点水生野生动物的人工繁育和出售购买利用其活体及制品活动的审批。 省级人民政府渔业主管部门负责本行政区域内除国务院对审批机关另有规定的国家重点保护水生野生动物或其制品利用特许审批；县级以上地方人民政府渔业行政主管部门负责本行政区域内水生野生动物或其制品特许申请的审核。"},{"i":4,"n":"第四条","txt":"农业部组织国家濒危水生野生动物物种科学委员会，对水生野生动物保护与管理提供咨询和评估。 审批机关在批准人工繁育、经营利用以及重要的进出口水生野生动物或其制品等特许申请前，应当委托国家濒危水生野生动物物种科学委员会对特许申请进行评估。评估未获通过的，审批机关不得批准。"},{"i":5,"n":"第五条","txt":"申请水生野生动物或其制品利用特许的单位和个人，必须填报《水生野生动物利用特许证件申请表》（以下简称《申请表》）。《申请表》可向所在地县级以上渔业行政主管部门领取。"},{"i":6,"n":"第六条","txt":"经审批机关批准的，可以按规定领取水生野生动物利用特许证件。 水生野生动物利用特许证件包括《水生野生动物特许猎捕证》（以下简称《猎捕证》）、《水生野生动物人工繁育许可证》（以下简称《人工繁育证》）、《水生野生动物经营利用许可证》（以下简称《经营利用证》）。"},{"i":7,"n":"第七条","txt":"各级渔业行政主管部门及其所属的渔政监督管理机构，有权对本办法的实施情况进行监督检查，被检查的单位和个人应当给予配合。"},{"i":8,"n":"第八条","txt":"禁止捕捉、杀害水生野生动物。因科研、教学、人工繁育、展览、捐赠等特殊情况需要捕捉水生野生动物的，必须办理《猎捕证》。"},{"i":9,"n":"第九条","txt":"申请捕捉国家一级保护水生野生动物的，申请人应当将《申请表》和证明材料报所在地省级人民政府渔业行政主管部门签署意见。省级人民政府渔业行政主管部门应当在20日内签署意见，并报农业部审批。 需要跨省捕捉国家一级保护水生野生动物的，申请人应当将《申请表》和证明材料报所在地省级人民政府渔业行政主管部门签署意见。所在地省级人民政府渔业行政主管部门应当在20日内签署意见，并转送捕捉地省级人民政府渔业行政主管部门签署意见。捕捉地省级人民政府渔业行政主管部门应当在20日内签署意见，并报农业部审批。 农业部自收到省级人民政府渔业行政主管部门报送的材料之日起40日内作出是否发放特许猎捕证的决定。"},{"i":10,"n":"第十条","txt":"申请捕捉国家二级保护水生野生动物的，申请人应当将《申请表》和证明材料报所在地县级人民政府渔业行政主管部门签署意见。所在地县级人民政府渔业行政主管部门应当在20日内签署意见，并报省级人民政府渔业行政主管部门审批。 省级人民政府渔业行政主管部门应该自收到县级人民政府渔业行政主管部门报送的材料之日起40日内作出是否发放猎捕证的决定。 需要跨省捕捉国家二级保护水生野生动物的，申请人应该将《申请表》和证明材料报所在地省级人民政府渔业行政主管部门签署意见。所在地省级人民政府渔业行政主管部门应当在20日内签署意见，并转送捕捉地省级人民政府渔业行政主管部门审批。 捕捉地省级人民政府渔业行政主管部门应当自收到所在地省级人民政府渔业行政主管部门报送的材料之日起40日内作出是否发放猎捕证的决定。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，不予发放《猎捕证》： （一）申请人有条件以合法的非捕捉方式获得申请捕捉对象或者达到其目的； （二）捕捉申请不符合国家有关规定，或者申请使用的捕捉工具、方法以及捕捉时间、地点不当的； （三）根据申请捕捉对象的资源现状不宜捕捉的。"},{"i":12,"n":"第十二条","txt":"取得《猎捕证》的单位和个人，在捕捉作业以前，必须向捕捉地县级渔业行政主管部门报告，并由其所属的渔政监督管理机构监督进行。 捕捉作业必须按照《猎捕证》规定的种类、数量、地点、期限、工具和方法进行，防止误伤水生野生动物或破坏其生存环境。"},{"i":13,"n":"第十三条","txt":"捕捉作业完成后，捕捉者应当立即向捕捉地县级渔业行政主管部门或其所属的渔政监督管理机构申请查验。捕捉地县级渔业行政主管部门或渔政监督管理机构应及时对捕捉情况进行查验，收回《猎捕证》，并及时向发证机关报告查验结果、交回《猎捕证》。"},{"i":14,"n":"第十四条","txt":"国家支持有关科学研究机构因物种保护目的人工繁育国家重点保护水生野生动物。 前款规定以外的人工繁育国家重点保护水生野生动物实行许可制度。人工繁育国家重点保护水生野生动物的，应当经省级人民政府渔业主管部门批准，取得《人工繁育许可证》，但国务院对批准机关另有规定的除外。"},{"i":15,"n":"第十五条","txt":"申请《人工繁育证》，应当具备以下条件： （一）有适宜人工繁育水生野生动物的固定场所和必要的设施； （二）具备与人工繁育水生野生动物种类、数量相适应的资金、技术和人员； （三）具有充足的人工繁育水生野生动物的饲料来源。"},{"i":16,"n":"第十六条","txt":"国务院规定由农业部批准的国家重点保护水生野生动物的人工繁育许可，向省级人民政府渔业行政主管部门提出申请。省级人民政府渔业行政主管部门应当自申请受理之日起20日内完成初步审查，并将审查意见和申请人的全部申请材料报农业部审批。 农业部应当自收到省级人民政府渔业行政主管部门报送的材料之日起15日内作出是否发放人工繁育许可证的决定。 除国务院规定由农业部批准以外的国家重点保护水生野生动物的人工繁育许可，应当向省级人民政府渔业主管部门申请。 省级人民政府渔业行政主管部门应当自申请受理之日起20日内作出是否发放人工繁育证的决定。"},{"i":17,"n":"第十七条","txt":"人工繁育水生野生动物的单位和个人，必须按照《人工繁育证》的规定进行人工繁育活动。 需要变更人工繁育种类的，应当按照本办法第十七条规定的程序申请变更手续。经批准后，由审批机关在《人工繁育证》上作变更登记。"},{"i":18,"n":"第十八条","txt":"禁止将人工繁育的水生野生动物或其制品进行捐赠、转让、交换。因特殊情况需要捐赠、转让、交换的，申请人应当向《人工繁育证》发证机关提出申请，由发证机关签署意见后，按本办法第三条的规定报批。"},{"i":19,"n":"第十九条","txt":"接受捐赠、转让、交换的单位和个人，应当凭批准文件办理有关手续，并妥善养护与管理接受的水生野生动物或其制品。"},{"i":20,"n":"第二十条","txt":"取得《人工繁育证》的单位和个人，应当遵守以下规定： （一）遵守国家和地方野生动物保护法律法规和政策； （二）用于人工繁育的水生野生动物来源符合国家规定； （三）建立人工繁育物种档案和统计制度； （四）定期向审批机关报告水生野生动物的生长、繁殖、死亡等情况； （五）不得非法利用其人工繁育的水生野生动物或其制品； （六）接受当地渔业行政主管部门的监督检查和指导。"},{"i":21,"n":"第二十一条","txt":"禁止出售、购买、利用国家重点保护水生野生动物及其制品。因科学研究、人工繁育、公众展示展演、文物保护或者其他特殊情况，需要出售、购买、利用水生野生动物及其制品的，应当经省级人民政府渔业主管部门或其授权的渔业主管部门审核批准，并按照规定取得和使用专用标识，保证可追溯。"},{"i":22,"n":"第二十二条","txt":"国务院规定由农业部批准的国家重点保护水生野生动物或者其制品的出售、购买、利用许可，申请人应当将《申请表》和证明材料报所在地省级人民政府渔业行政主管部门签署意见。所在地省级人民政府渔业行政主管部门应当在20日内签署意见，并报农业部审批。 农业部应当自接到省级人民政府渔业行政主管部门报送的材料之日起20日内作出是否发放经营利用证的决定。 除国务院规定由农业部批准以外的国家重点保护水生野生动物或者其制品的出售、购买、利用许可，应当向省级人民政府渔业主管部门申请。 省级人民政府渔业行政主管部门应当自受理之日起20日内作出是否发放经营利用证的决定。"},{"i":23,"n":"第二十三条","txt":"申请《经营利用证》，应当具备下列条件： （一）出售、购买、利用的水生野生动物物种来源清楚或稳定； （二）不会造成水生野生动物物种资源破坏； （三）不会影响国家野生动物保护形象和对外经济交往。"},{"i":24,"n":"第二十四条","txt":"经批准出售、购买、利用水生野生动物或其制品的单位和个人，应当持《经营利用证》到出售、收购所在地的县级以上渔业行政主管部门备案后方可进行出售、购买、利用活动。"},{"i":25,"n":"第二十五条","txt":"出售、购买、利用水生野生动物或其制品的单位和个人，应当遵守以下规定： （一）遵守国家和地方有关野生动物保护法律法规和政策； （二）利用的水生野生动物或其制品来源符合国家规定； （三）建立出售、购买、利用水生野生动物或其制品档案； （四）接受当地渔业行政主管部门的监督检查和指导。"},{"i":26,"n":"第二十六条","txt":"地方各级渔业行政主管部门应当对水生野生动物或其制品的经营利用建立监督检查制度，加强对经营利用水生野生动物或其制品的监督管理。"},{"i":27,"n":"第二十七条","txt":"出口国家重点保护的水生野生动物或者其产品，进出口中国参加的国际公约所限制进出口的水生野生动物或者其产品的，应当向农业部申请，农业部应当自申请受理之日起20日内作出是否同意进出口的决定。 动物园因交换动物需要进口第一款规定的野生动物的，农业部在批准前，应当经国务院建设行政主管部门审核同意。"},{"i":28,"n":"第二十八条","txt":"属于贸易性进出口活动的，必须由具有商品进出口权的单位承担，并取得《经营利用证》后方可进行。没有商品进出口权和《经营利用证》的单位，审批机关不得受理其申请。"},{"i":29,"n":"第二十九条","txt":"从国外引进水生野生动物的，应当向农业部申请，农业部应当自申请受理之日起20日内作出是否同意引进的决定。"},{"i":30,"n":"第三十条","txt":"出口水生野生动物或其制品的，应当具备下列条件： （一）出口的水生野生动物物种和含水生野生动物成分制品中物种原料的来源清楚； （二）出口的水生野生动物是合法取得； （三）不会影响国家野生动物保护形象和对外经济交往； （四）出口的水生野生动物资源量充足，适宜出口； （五）符合我国水产种质资源保护规定。"},{"i":31,"n":"第三十一条","txt":"进口水生野生动物或其制品的，应当具备下列条件： （一）进口的目的符合我国法律法规和政策； （二）具备所进口水生野生动物活体生存必需的养护设施和技术条件； （三）引进的水生野生动物活体不会对我国生态平衡造成不利影响或产生破坏作用； （四）不影响国家野生动物保护形象和对外经济交往。"},{"i":32,"n":"第三十二条","txt":"违反本办法规定的，由县级以上渔业行政主管部门或其所属的渔政监督管理机构依照野生动物保护法律、法规进行查处。"},{"i":33,"n":"第三十三条","txt":"经批准捕捉、人工繁育以及展览、表演、出售、收购、进出口等利用水生野生动物或其制品的单位和个人，应当依法缴纳水生野生动物资源保护费。缴纳办法按国家有关规定执行。 水生野生动物资源保护费专用于水生野生动物资源的保护管理、科学研究、调查监测、宣传教育、人工繁育与增殖放流等。"},{"i":34,"n":"第三十四条","txt":"外国人在我国境内进行有关水生野生动物科学考察、标本采集、拍摄电影、录像等活动的，应当向水生野生动物所在地省级渔业行政主管部门提出申请。省级渔业行政主管部门应当自申请受理之日起20日内作出是否准予其活动的决定。"},{"i":35,"n":"第三十五条","txt":"本办法规定的《申请表》和水生野生动物利用特许证件由农业部统一制订。已发放仍在使用的许可证件由原发证机关限期统一进行更换。 除监督《猎捕证》一次有效外，其他特许证件应按年度进行审验，有效期最长不超过五年。有效期届满后，应按规定程序重新报批。 各省、自治区、直辖市渔业行政主管部门应当根据本办法制定特许证件发放管理制度，建立档案，严格管理。"},{"i":36,"n":"第三十六条","txt":"《濒危野生动植物国际贸易公约》附录一中的水生野生动物或其制品的国内管理，按照本办法对国家一级保护水生野生动物的管理规定执行。 《濒危野生动植物种国际贸易公约》附录二、附录三中的水生野生动物或其制品的国内管理，按照本办法对国家二级保护水生野生动物的管理规定执行。 地方重点保护的水生野生动物或其制品的管理，可参照本办法对国家二级保护水生野生动物的管理规定执行。"},{"i":37,"n":"第三十七条","txt":"本办法由农业部负责解释。"},{"i":38,"n":"第三十八条","txt":"本办法自1999年9月1日起施行。"}],"yuyeganghangjianduxingzhengchufaguiding":[{"i":1,"n":"第一条","txt":"为加强渔业船舶安全监督管理，规范渔业港航法规行政处罚，保障渔业港航法规的执行和渔业生产者的合法权益，根据《中华人民共和国海上交通安全法》、《中华人民共和国海洋环境保护法》、《中华人民共和国渔港水域交通安全管理条例》和《中华人民共和国内河交通安全管理条例》等有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于中国籍渔业船舶及其船员、所有者和经营者，以及在中华人民共和国渔港和渔港水域内航行、停泊和作业的其他船舶、设施及其船员、所有者和经营者。"},{"i":3,"n":"第三条","txt":"中华人民共和国渔政渔港监督管理机关(以下简称渔政渔港监督管理机关)依据本规定行使渔业港航监督行政处罚权。"},{"i":4,"n":"第四条","txt":"渔政渔港监督管理机关对违反渔业港航法律、法规的行政处罚分为： （一）警告； （二）罚款； （三）扣留或吊销船舶证书或船员证书； （四）法律、法规规定的其他行政处罚。"},{"i":5,"n":"第五条","txt":"有下列行为之一的，可免予处罚： （一）因不可抗力或以紧急避险为目的的行为； （二）渔业港航违法行为显著轻微并及时纠正，没有造成危害性后果。"},{"i":6,"n":"第六条","txt":"有下列行为之一的，可从轻、减轻处罚： （一）主动消除或减轻渔业港航违法行为后果； （二）配合渔政渔港监督管理机关查处渔业港航违法行为； （三）依法可以从轻、减轻的其他渔业港航违法行为。"},{"i":7,"n":"第七条","txt":"有下列行为之一的，可从重处罚： （一）违法情节严重，影响较大； （二）多次违法或违法行为造成重大损失; （三）损失虽然不大，但事后既不向渔政渔港监督管理机关报告，又不采取措施，放任损失扩大； （四）逃避、抗拒渔政渔港监督管理机关检查和管理； （五）依法可以从重处罚的其他渔业港航违法行为。"},{"i":8,"n":"第八条","txt":"渔政渔港监督管理机关管辖本辖区发生的案件和上级渔政渔港监督管理机关指定管辖的渔业港航违法案件。 渔业港航违法行为有下列情况的，适用“谁查获谁处理”的原则： （一）违法行为发生在共管区、叠区； （二）违法行为发生在管辖权不明或有争议的区域； （三）违法行为地与查获地不一致。 法律、法规或规章另有规定的，按规定管辖。"},{"i":9,"n":"第九条","txt":"有下列行为之一的，对船长予以警告，并可处50元以上500元以下罚款；情节严重的，扣留其职务船员证书3至6个月；情节特别严重的，吊销船长证书： （一）船舶进出渔港应当按照有关规定到渔政渔港监督管理机关办理签证而未办理签证的； （二）在渔港内不服从渔政渔港监督管理机关对渔港水域交通安全秩序管理的； （三）在渔港内停泊期间，未留足值班人员的。"},{"i":10,"n":"第十条","txt":"有下列违反渔港管理规定行为之一的，渔政渔港监督管理机关应责令其停止作业，并对船长或直接责任人予以警告，并可处500元以上1000元以下罚款： （一）未经渔政渔港监督管理机关批准或未按批准文件的规定，在渔港内装卸易燃、易爆、有毒等危险货物的； （二）未经渔政渔港监督管理机关批准，在渔港内新建、改建、扩建各种设施，或者进行其他水上、水下施工作业的； （三）在渔港内的航道、港池、锚地和停泊区从事有碍海上交通安全的捕捞、养殖等生产活动的。"},{"i":11,"n":"第十一条","txt":"停泊或进行装卸作业时，有下列行为之一的，应责令船舶所有者或经营者支付消除污染所需的费用，并可处500元以上10000元以下罚款： （一）造成腐蚀、有毒或放射性等有害物质散落或溢漏，污染渔港或渔港水域的； （二）排放油类或油性混合物造成渔港或渔港水域污染的。"},{"i":12,"n":"第十二条","txt":"有下列行为之一的，对船长予以警告，情节严重的，并处100元以上1000元以下罚款： （一）未经批准，擅自使用化学消油剂； （二）未按规定持有防止海洋环境污染的证书与文书，或不如实记录涉及污染物排放及操作。"},{"i":13,"n":"第十三条","txt":"未经渔政渔港监督管理机关批准，有下列行为之一者，应责令当事责任人限期清除、纠正，并予以警告；情节严重的，处100元以上1000元以下罚款： （一）在渔港内进行明火作业； （二）在渔港内燃放烟花爆竹。"},{"i":14,"n":"第十四条","txt":"向渔港港池内倾倒污染物、船舶垃圾及其他有害物质，应责令当事责任人立即清除，并予以警告。情节严重的，400总吨(含400总吨)以下船舶，处5000元以上50000元以下罚款；400总吨以上船舶处50000元以上100000元以下罚款。"},{"i":15,"n":"第十五条","txt":"已办理渔业船舶登记手续，但未按规定持有船舶国籍证书、船舶登记证书、船舶检验证书、船舶航行签证簿的，予以警告，责令其改正，并可处200元以上1000元以下罚款。"},{"i":16,"n":"第十六条","txt":"无有效的渔业船舶船名、船号、船舶登记证书（或船舶国籍证书）、检验证书的船舶，禁止其离港，并对船舶所有者或者经营者处船价2倍以下的罚款。有下列行为之一的，从重处罚： （一）无有效的渔业船舶登记证书（或渔业船舶国籍证书）和检验证书，擅自刷写船名、船号、船籍港的； （二）伪造渔业船舶登记证书（或国籍证书）、船舶所有权证书或船舶检验证书的； （三）伪造事实骗取渔业船舶登记证书或渔业船舶国籍证书的； （四）冒用他船船名、船号或船舶证书的。"},{"i":17,"n":"第十七条","txt":"渔业船舶改建后，未按规定办理变更登记，应禁止其离港，责令其限期改正，并可对船舶所有者处5000元以上20000元以下罚款。 变更主机功率未按规定办理变更登记的，从重处罚。"},{"i":18,"n":"第十八条","txt":"将船舶证书转让他船使用，一经发现，应立即收缴，对转让船舶证书的船舶所有者或经营者处1000元以下罚款；对借用证书的船舶所有者或经营者处船价2倍以下罚款。"},{"i":19,"n":"第十九条","txt":"使用过期渔业船舶登记证书或渔业船舶国籍证书的，登记机关应通知船舶所有者限期改正，过期不改的，责令其停航，并对船舶所有者或经营者处1000元以上10000元以下罚款。"},{"i":20,"n":"第二十条","txt":"有下列行为之一的，责令其限期改正，对船舶所有者或经营者处200元以上1000元以下罚款： （一）未按规定标写船名、船号、船籍港，没有悬挂船名牌的； （二）在非紧急情况下，未经渔政渔港监督管理机关批准，滥用烟火信号、信号枪、无线电设备、号笛及其他遇险求救信号的； （三）没有配备、不正确填写或污损、丢弃航海日志、轮机日志的。"},{"i":21,"n":"第二十一条","txt":"未按规定配备救生、消防设备，责令其在离港前改正，逾期不改的，处200元以上1000元以下罚款。"},{"i":22,"n":"第二十二条","txt":"未按规定配齐职务船员，责令其限期改正，对船舶所有者或经营者并处200元以上1000元以下罚款。 普通船员未取得专业训练合格证或基础训练合格证的，责令其限期改正，对船舶所有者或经营者并处1000元以下罚款。"},{"i":23,"n":"第二十三条","txt":"有下列行为之一的，对船长或直接责任人处200元以上1000元以下罚款： （一）未经渔政渔港监督管理机关批准，违章装载货物且影响船舶适航性能的； （二）未经渔政渔港监督管理机关批准违章载客的； （三）超过核定航区航行和超过抗风等级出航的。 违章装载危险货物的，应当从重处罚。"},{"i":24,"n":"第二十四条","txt":"对拒不执行渔政渔港监督管理机关作出的离港、禁止离港、停航、改航、停止作业等决定的船舶，可对船长或直接责任人并处1000元以上10000元以下罚款、扣留或吊销船长职务证书。"},{"i":25,"n":"第二十五条","txt":"冒用、租借他人或涂改职务船员证书、普通船员证书的，应责令其限期改正，并收缴所用证书，对当事人或直接责任人并处50元以上200元以下罚款。"},{"i":26,"n":"第二十六条","txt":"对因违规被扣留或吊销船员证书而谎报遗失，申请补发的，可对当事人或直接责任人处200元以上1000元以下罚款。"},{"i":27,"n":"第二十七条","txt":"向渔政渔港监督管理机关提供虚假证明材料、伪造资历或以其他舞弊方式获取船员证书的，应收缴非法获取的船员证书，对提供虚假材料的单位或责任人处500元以上3000元以下罚款。"},{"i":28,"n":"第二十八条","txt":"船员证书持证人与证书所载内容不符的，应收缴所持证书，对当事人或直接责任人处50元以上200元以下罚款。"},{"i":29,"n":"第二十九条","txt":"到期未办理证件审验的职务船员，应责令其限期办理，逾期不办理的，对当事人并处50元以上100元以下罚款。"},{"i":30,"n":"第三十条","txt":"对损坏航标或其他助航、导航标志和设施，或造成上述标志、设施失效、移位、流失的船舶或人员，应责令其照价赔偿，并对责任船舶或责任人员处500元以上1000元以下罚款。 故意造成第一款所述结果或虽不是故意但事情发生后隐瞒不向渔政渔港监督管理机关报告的，应当从重处罚。"},{"i":31,"n":"第三十一条","txt":"违反港航法律、法规造成水上交通事故的，对船长或直接责任人按以下规定处罚： （一）造成特大事故的，处以3000元以上5000元以下罚款，吊销职务船员证书； （二）造成重大事故的，予以警告，处以1000元以上3000元以下罚款，扣留其职务船员证书3至6个月； （三）造成一般事故的，予以警告，处以100元以上1000元以下罚款,扣留职务船员证书1至3个月。 事故发生后，不向渔政渔港监督管理机关报告、拒绝接受渔政渔港监督管理机关调查或在接受调查时故意隐瞒事实、提供虚假证词或证明的，从重处罚。"},{"i":32,"n":"第三十二条","txt":"有下列行为之一的，对船长处500元以上1000元以下罚款，扣留职务船员证书3至6个月；造成严重后果的，吊销职务船员证书： （一）发现有人遇险、遇难或收到求救信号，在不危及自身安全的情况下，不提供救助或不服从渔政渔港监督管理机关救助指挥； （二）发生碰撞事故，接到渔政渔港监督管理机关守候现场或到指定地点接受调查的指令后，擅离现场或拒不到指定地点。"},{"i":33,"n":"第三十三条","txt":"发生水上交通事故的船舶，有下列行为之一的，对船长处50元以上500元以下罚款： （一）未按规定时间向渔政渔港监督管理机关提交《海事报告书》的； （二）《海事报告书》内容不真实，影响海损事故的调查处理工作的。 发生涉外海事，有上述情况的，从重处罚。"},{"i":34,"n":"第三十四条","txt":"对内陆水域渔业船舶和12米以下的海洋渔业船舶可依照本规定从轻或减轻处罚。"},{"i":35,"n":"第三十五条","txt":"渔政渔港监督管理机关的执法人员，在调查处理违规案件和实施处罚决定时，应严格遵守有关行政处罚程序规定。"},{"i":36,"n":"第三十六条","txt":"拒绝、阻碍渔政渔港监督管理机关工作人员依法执行公务，应当给予治安管理处罚的，由公安机关依照《中华人民共和国治安管理处罚条例》有关规定处罚；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"当事人对渔政渔港监督管理机关处罚不服的，可在接到处罚通知之日起，60日内向该渔政渔港监督管理机关所属的渔业行政主管部门申请复议，对复议决定不服的，可以向人民法院提起行政诉讼；当事人也可在接到处罚通知之日起30日内直接向人民法院提起行政诉讼。在此期限内当事人既不履行处罚，又不申请复议，也不提起行政诉讼的，处罚机关可申请法院强制执行。但是，在海上的处罚，被查处的渔业船舶应当先执行处罚决定。"},{"i":38,"n":"第三十八条","txt":"本规定由中华人民共和国农业部负责解释。"},{"i":39,"n":"第三十九条","txt":"本规定自下发之日起施行。"}],"yuyechuanyuanguanlibanfa":[{"i":1,"n":"第一条","txt":"加强渔业船员管理，维护渔业船员合法权益，保障渔业船舶及船上人员的生命财产安全，根据《中华人民共和国船员条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国国籍渔业船舶上工作的渔业船员的管理。"},{"i":3,"n":"第三条","txt":"农业农村部负责全国渔业船员管理工作。 县级以上地方人民政府渔业主管部门及其所属的渔政渔港监督管理机构，依照各自职责负责渔业船员管理工作。"},{"i":4,"n":"第四条","txt":"渔业船员实行持证上岗制度。渔业船员应当按照本办法的规定接受培训，经考试或考核合格、取得相应的渔业船员证书后，方可在渔业船舶上工作。 在远洋渔业船舶上工作的中国籍船员，还应当按照有关规定取得中华人民共和国海员证。"},{"i":5,"n":"第五条","txt":"渔业船员分为职务船员和普通船员。 职务船员是负责船舶管理的人员，包括以下五类： （一）驾驶人员，职级包括船长、船副、助理船副； （二）轮机人员，职级包括轮机长、管轮、助理管轮； （三）机驾长； （四）电机员； （五）无线电操作员。 职务船员证书分为海洋渔业职务船员证书和内陆渔业职务船员证书，具体等级职级划分见附件1。 普通船员是职务船员以外的其他船员。普通船员证书分为海洋渔业普通船员证书和内陆渔业普通船员证书。"},{"i":6,"n":"第六条","txt":"渔业船员培训包括基本安全培训、职务船员培训和其他培训。 基本安全培训是指渔业船员都应当接受的任职培训，包括水上求生、船舶消防、急救、应急措施、防止水域污染、渔业安全生产操作规程等内容。 职务船员培训是指职务船员应当接受的任职培训，包括拟任岗位所需的专业技术知识、专业技能和法律法规等内容。 其他培训是指远洋渔业专项培训和其他与渔业船舶安全和渔业生产相关的技术、技能、知识、法律法规等培训。"},{"i":7,"n":"第七条","txt":"申请渔业普通船员证书应当具备以下条件： （一）年满18周岁（在船实习、见习人员年满16周岁）且初次申请不超过60周岁； （二）符合渔业船员健康标准（见附件2）； （三）经过基本安全培训。 符合以上条件的，由申请者向渔政渔港监督管理机构提出书面申请。渔政渔港监督管理机构应当组织考试或考核，对考试或考核合格的，自考试成绩或考核结果公布之日起10个工作日内发放渔业普通船员证书。"},{"i":8,"n":"第八条","txt":"申请渔业职务船员证书应当具备以下条件： （一）持有渔业普通船员证书或下一级相应职务船员证书； （二）初次申请不超过60周岁； （三）符合任职岗位健康条件要求； （四）具备相应的任职资历条件（见附件3），且任职表现和安全记录良好； （五）完成相应的职务船员培训，在远洋渔业船舶上工作的驾驶和轮机人员，还应当接受远洋渔业专项培训。 符合以上条件的，由申请者向渔政渔港监督管理机构提出书面申请。渔政渔港监督管理机构应当组织考试或考核，对考试或考核合格的，自考试成绩或考核结果公布之日起10个工作日内发放相应的渔业职务船员证书。"},{"i":9,"n":"第九条","txt":"航海、海洋渔业、轮机管理、机电、船舶通信等专业的院校毕业生申请渔业职务船员证书，具备本办法第八条规定的健康及任职资历条件的，可申请考核。经考核合格，按以下规定分别发放相应的渔业职务船员证书： （一）高等院校本科毕业生按其所学专业签发一级船副、一级管轮、电机员、无线电操作员证书； （二）高等院校专科（含高职）毕业生按其所学专业签发二级船副、二级管轮、电机员、无线电操作员证书； （三）中等专业学校毕业生按其所学专业签发助理船副、助理管轮、电机员、无线电操作员证书。 内陆渔业船舶接收相应专业毕业生任职的，参照前款规定执行。"},{"i":10,"n":"第十条","txt":"曾在军用船舶、交通运输船舶等非渔业船舶上任职的船员申请渔业船员证书，应当参加考核。经考核合格，由渔政渔港监督管理机构换发相应的渔业普通船员证书或渔业职务船员证书。"},{"i":11,"n":"第十一条","txt":"申请海洋渔业船舶一级驾驶人员、一级轮机人员、电机员、无线电操作员证书以及远洋渔业职务船员证书的，由省级以上渔政渔港监督管理机构组织考试、考核、发证；其他渔业船员证书的考试、考核、发证权限由省级渔政渔港监督管理机构制定并公布，报农业农村部备案。"},{"i":12,"n":"第十二条","txt":"渔业船员考试包括理论考试和实操评估。海洋渔业船员考试大纲由农业农村部统一制定并公布。内陆渔业船员考试大纲由省级渔政渔港监督管理机构根据本辖区的具体情况制定并公布。 渔业船员考核可由渔政渔港监督管理机构根据实际需要和考试大纲，选取适当科目和内容进行。"},{"i":13,"n":"第十三条","txt":"渔业船员证书的有效期不超过5年。证书有效期满，持证人需要继续从事相应工作的，应当向有相应管理权限的渔政渔港监督管理机构申请换发证书。渔政渔港监督管理机构可以根据实际需要和职务知识技能更新情况组织考核，对考核合格的，换发相应渔业船员证书。 渔业船员证书期满5年后，持证人需要从事渔业船员工作的，应当重新申请原等级原职级证书。"},{"i":14,"n":"第十四条","txt":"有效期内的渔业船员证书损坏或丢失的，应当凭损坏的证书原件或在原发证机关所在地报纸刊登的遗失声明，向原发证机关申请补发。补发的渔业船员证书有效期应当与原证书有效期一致。"},{"i":15,"n":"第十五条","txt":"渔业船员证书格式由农业农村部统一制定。远洋渔业职务船员证书由农业农村部印制；其他渔业船员证书由省级渔政渔港监督管理机构印制。"},{"i":16,"n":"第十六条","txt":"禁止伪造、变造、转让渔业船员证书。"},{"i":17,"n":"第十七条","txt":"海洋渔业船舶应当满足本办法规定的职务船员最低配员标准（附件4）。内陆渔业船舶船员最低配员标准由各省级人民政府渔业主管部门根据本地情况制定，报农业农村部备案。 持有高等级职级船员证书的船员可以担任低等级职级船员职务。 渔业船舶所有人或经营人可以根据作业安全和管理的需要，增加职务船员的配员。"},{"i":18,"n":"第十八条","txt":"渔业船舶在境外遇有不可抗力或其他持证人不能履行职务的特殊情况，导致无法满足本办法规定的职务船员最低配员标准时，具备以下条件的船员，可以由船舶所有人或经营人向船籍港所在地省级渔政渔港监督管理机构申请临时担任上一职级职务： （一）持有下一职级相应证书； （二）申请之日前5年内，具有6个月以上不低于其船员证书所记载船舶、水域、职务的任职资历； （三）任职表现和安全记录良好。 渔政渔港监督管理机构根据拟担任上一级职务船员的任职情况签发特免证明。特免证明有效期不得超过6个月，不得延期，不得连续申请。渔业船舶抵达中国第一个港口后，特免证明自动失效。失效的特免证明应当及时缴回签发机构。 一艘渔业船舶上同时持有特免证明的船员不得超过2人。"},{"i":19,"n":"第十九条","txt":"中国籍渔业船舶的船长应当由中国籍公民担任。 外国籍公民在中国籍渔业船舶上工作，应当持有所属国政府签发的相关身份证件，在我国依法取得就业许可，并按本办法的规定取得渔业船员证书。持有中华人民共和国缔结或者加入的国际条约的缔约国签发的外国职务船员证书的，应当按照国家有关规定取得承认签证。承认签证的有效期不得超过被承认职务船员证书的有效期，当被承认职务船员证书失效时，相应的承认签证自动失效。"},{"i":20,"n":"第二十条","txt":"渔业船舶所有人或经营人应当为在渔业船舶上工作的渔业船员建立基本信息档案，并报船籍港所在地渔政渔港监督管理机构或渔政渔港监督管理机构委托的服务机构备案。 渔业船员变更的，渔业船舶所有人或经营人应当在出港前10个工作日内报船籍港所在地渔政渔港监督管理机构或渔政渔港监督管理机构委托的服务机构备案，并及时变更渔业船员基本信息档案。"},{"i":21,"n":"第二十一条","txt":"渔业船员在船工作期间，应当符合下列要求： （一）携带有效的渔业船员证书； （二）遵守法律法规和安全生产管理规定，遵守渔业生产作业及防治船舶污染操作规程； （三）执行渔业船舶上的管理制度和值班规定； （四）服从船长及上级职务船员在其职权范围内发布的命令； （五）参加渔业船舶应急训练、演习，落实各项应急预防措施； （六）及时报告发现的险情、事故或者影响航行、作业安全的情况； （七）在不严重危及自身安全的情况下，尽力救助遇险人员； （八）不得利用渔业船舶私载、超载人员和货物，不得携带违禁物品； （九）职务船员不得在生产航次中擅自辞职、离职或者中止职务。"},{"i":22,"n":"第二十二条","txt":"渔业船员在船舶航行、作业、锚泊时应当按照规定值班。值班船员应当履行以下职责： （一）熟悉并掌握船舶的航行与作业环境、航行与导航设施设备的配备和使用、船舶的操控性能、本船及邻近船舶使用的渔具特性，随时核查船舶的航向、船位、船速及作业状态； （二）按照有关的船舶避碰规则以及航行、作业环境要求保持值班瞭望，并及时采取预防船舶碰撞和污染的相应措施； （三）如实填写有关船舶法定文书； （四）在确保航行与作业安全的前提下交接班。"},{"i":23,"n":"第二十三条","txt":"船长是渔业安全生产的直接责任人，在组织开展渔业生产、保障水上人身与财产安全、防治渔业船舶污染水域和处置突发事件方面，具有独立决定权，并履行以下职责： （一）确保渔业船舶和船员携带符合法定要求的证书、文书以及有关航行资料； （二）确保渔业船舶和船员在开航时处于适航、适任状态，保证渔业船舶符合最低配员标准，保证渔业船舶的正常值班； （三）服从渔政渔港监督管理机构依据职责对渔港水域交通安全和渔业生产秩序的管理，执行有关水上交通安全和防治船舶污染等规定； （四）确保渔业船舶依法进行渔业生产，正确合法使用渔具渔法，在船人员遵守相关资源养护法律法规，按规定填写渔捞日志，并按规定开启和使用安全通导设备； （五）在渔业船员证书内如实记载渔业船员的履职情况； （六）按规定办理渔业船舶进出港报告手续； （七）船舶进港、出港、靠泊、离泊，通过交通密集区、危险航区等区域，或者遇有恶劣天气和海况，或者发生水上交"},{"i":24,"n":"第二十四条","txt":"船长履行职责时，可以行使下列权力： （一）当渔业船舶不具备安全航行条件时，拒绝开航或者续航； （二）对渔业船舶所有人或经营人下达的违法指令，或者可能危及船员、财产或船舶安全，以及造成渔业资源破坏和水域环境污染的指令，可以拒绝执行； （三）当渔业船舶遇险并严重危及船上人员的生命安全时，决定船上人员撤离渔业船舶； （四）在渔业船舶的沉没、毁灭不可避免的情况下，报经渔业船舶所有人或经营人同意后弃船，紧急情况除外； （五）责令不称职的船员离岗。 船长在其职权范围内发布的命令，船舶上所有人员必须执行。"},{"i":25,"n":"第二十五条","txt":"渔业船员培训机构开展培训业务，应当具备开展相应培训所需的场地、设施、设备和教学人员条件。"},{"i":26,"n":"第二十六条","txt":"海洋渔业船员培训机构分为以下三级，应当具备的具体条件由农业农村部另行规定： 一级渔业船员培训机构，可以承担海洋渔业船舶各类各级职务船员培训、远洋渔业专项培训和基本安全培训； 二级渔业船员培训机构，可以承担海洋渔业船舶二级以下驾驶和轮机人员培训、机驾长培训和基本安全培训； 三级渔业船员培训机构，可以承担海洋渔业船舶机驾长培训和基本安全培训。 内陆渔业船员培训机构应当具备的具体条件，由省级人民政府渔业主管部门根据渔业船员管理需要制定。"},{"i":27,"n":"第二十七条","txt":"渔业船员培训机构应当在每期培训班开班前，将学员名册、培训内容和教学计划报所在地渔政渔港监督管理机构备案。"},{"i":28,"n":"第二十八条","txt":"渔业船员培训机构应当建立渔业船员培训档案。学员参加培训课时达到规定培训课时80％的，渔业船员培训机构方可出具渔业船员培训证明。"},{"i":29,"n":"第二十九条","txt":"国家鼓励建立渔业船员服务机构。 渔业船员服务机构可以为渔业船员代理申请考试、申领证书等有关手续，代理船舶所有人或经营人管理渔业船员事务，提供渔业船员船舶配员等服务。 渔业船员服务机构为船员提供服务，应当订立书面合同。"},{"i":30,"n":"第三十条","txt":"渔业船舶所有人或经营人应当依法与渔业船员订立劳动合同。 渔业船舶所有人或经营人，不得招用未持有相应有效渔业船员证书的人员上船工作。"},{"i":31,"n":"第三十一条","txt":"渔业船舶所有人或经营人应当依法为渔业船员办理保险。"},{"i":32,"n":"第三十二条","txt":"渔业船舶所有人或经营人应当保障渔业船员的生活和工作场所符合《渔业船舶法定检验规则》对船员生活环境、作业安全和防护的要求，并为船员提供必要的船上生活用品、防护用品、医疗用品，建立船员健康档案，为船员定期进行健康检查和心理辅导，防治职业疾病。"},{"i":33,"n":"第三十三条","txt":"渔业船员在船上工作期间受伤或者患病的，渔业船舶所有人或经营人应当及时给予救治；渔业船员失踪或者死亡的，渔业船舶所有人或经营人应当及时做好善后工作。"},{"i":34,"n":"第三十四条","txt":"渔业船舶所有人或经营人是渔业安全生产的第一责任人，应当保证安全生产所需的资金投入，建立健全安全生产责任制，按照规定配备船员和安全设备，确保渔业船舶符合安全适航条件，并保证船员足够的休息时间。"},{"i":35,"n":"第三十五条","txt":"渔政渔港监督管理机构应当健全渔业船员管理及监督检查制度，建立渔业船员档案，督促渔业船舶所有人或经营人完善船员安全保障制度，落实相应的保障措施。"},{"i":36,"n":"第三十六条","txt":"渔政渔港监督管理机构应当依法对渔业船员持证情况、任职资格和资历、履职情况、安全记录，船员培训机构培训质量，船员服务机构诚实守信情况等进行监督检查，必要时可对船员进行现场考核。 渔政渔港监督管理机构依法实施监督检查时，船员、渔业船舶所有人和经营人、船员培训机构和服务机构应当予以配合，如实提供证书、材料及相关情况。"},{"i":37,"n":"第三十七条","txt":"渔业船员违反有关法律、法规、规章的，除依法给予行政处罚外，各省级人民政府渔业主管部门可根据本地实际情况实行累计记分制度。"},{"i":38,"n":"第三十八条","txt":"渔政渔港监督管理机构应当对渔业船员培训机构的条件、培训情况、培训质量等进行监督检查，检查内容包括教学计划的执行情况、承担本期培训教学任务的师资情况和教学情况、培训设施设备和教材的使用及补充情况、培训规模与师资配备要求的符合情况、学员的出勤情况、培训档案等。"},{"i":39,"n":"第三十九条","txt":"渔政渔港监督管理机构应当公开有关渔业船员管理的事项、办事程序、举报电话号码、通信地址、电子邮件信箱等信息，自觉接受社会的监督。"},{"i":40,"n":"第四十条","txt":"违反本办法规定，以欺骗、贿赂等不正当手段取得渔业船员证书的，由渔政渔港监督管理机构吊销渔业船员证书，并处2000元以上2万元以下罚款，三年内不再受理申请人渔业船员证书申请。"},{"i":41,"n":"第四十一条","txt":"伪造、变造、买卖渔业船员证书的，由渔政渔港监督管理机构收缴有关证书，处2万元以上10万元以下罚款，有违法所得的，还应当没收违法所得。 隐匿、篡改或者销毁有关渔业船舶、渔业船员法定证书、文书的，由渔政渔港监督管理机构处1000元以上1万元以下罚款；情节严重的，并处暂扣渔业船员证书6个月以上2年以下直至吊销渔业船员证书的处罚。"},{"i":42,"n":"第四十二条","txt":"渔业船员违反本办法第二十一条第一项规定，责令改正，可以处2000元以下罚款。 违反本办法第二十一条第三项、第四项、第五项规定的，予以警告，情节严重的，处200元以上2000元以下罚款。 违反本办法第二十一条第九项规定的，处1000元以上2万元以下罚款。"},{"i":43,"n":"第四十三条","txt":"渔业船员违反本办法第二十一条第二项、第六项、第七项、第八项和第二十二条规定的，处1000元以上1万元以下罚款；情节严重的，并处暂扣渔业船员证书6个月以上2年以下直至吊销渔业船员证书的处罚。"},{"i":44,"n":"第四十四条","txt":"渔业船舶的船长违反本办法第二十三条第一项、第二项、第五项、第七项、第十项规定的，由渔政渔港监督管理机构处2000元以上2万元以下罚款；情节严重的，并处暂扣渔业船员证书6个月以上2年以下直至吊销渔业船员证书的处罚。违反第二十三条第三项、第六项规定的，责令改正，并可以处警告、2000元以上2万元以下罚款；情节严重的，并处暂扣渔业船员证书6个月以下，直至吊销渔业船员证书的处罚。违反第二十三条第四项、第八项、第九项、第十一项规定的，由渔政渔港监督管理机构处2000元以上2万元以下罚款。"},{"i":45,"n":"第四十五条","txt":"渔业船员因违规造成责任事故，涉嫌犯罪的，及时将案件移送司法机关，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"渔业船员证书被吊销的，自被吊销之日起2年内，不得申请渔业船员证书。"},{"i":47,"n":"第四十七条","txt":"渔业船舶所有人或经营人有下列行为之一的，由渔政渔港监督管理机构责令改正，处3万元以上15万元以下罚款： （一）未按规定配齐渔业职务船员，或招用未取得本办法规定证件的人员在渔业船舶上工作的； （二）渔业船员在渔业船舶上生活和工作的场所不符合相关要求的； （三）渔业船员在船工作期间患病或者受伤，未及时给予救助的。"},{"i":48,"n":"第四十八条","txt":"渔业船员培训机构有下列情形之一的，由渔政渔港监督管理机构责令改正，并按以下规定处罚： （一）不具备规定条件开展渔业船员培训的，处5万元以上25万元以下罚款，有违法所得的，还应当没收违法所得； （二）未按规定的渔业船员考试大纲和水上交通安全、防治船舶污染等内容要求进行培训的，可以处2万元以上10万元以下罚款。 未按规定出具培训证明或者出具虚假培训证明的，由渔政渔港监督管理机构给予警告，责令改正；拒不改正或者再次出现同类违法行为的，可处3万元以下罚款。"},{"i":49,"n":"第四十九条","txt":"渔业主管部门或渔政渔港监督管理机构工作人员有下列情形之一的，依法给予处分： （一）违反规定发放渔业船员证书的； （二）不依法履行监督检查职责的； （三）滥用职权、玩忽职守的其他行为。"},{"i":50,"n":"第五十条","txt":"本办法中下列用语的含义是： 渔业船员，是指服务于渔业船舶，具有固定工作岗位的人员。 船舶长度，是指公约船长，即《渔业船舶国籍证书》所登记的“船长”。 主机总功率，是指所有用于推进的发动机持续功率总和，即《渔业船舶国籍证书》所登记“主机总功率”。"},{"i":51,"n":"第五十一条","txt":"海洋渔业船舶的所有人、经营人、船长、船员违反《中华人民共和国海上交通安全法》相关规定的处罚，按《中华人民共和国海上交通安全法》执行。"},{"i":52,"n":"第五十二条","txt":"非机动渔业船舶的船员管理办法，由各省级人民政府渔业主管部门根据本地实际情况制定。"},{"i":53,"n":"第五十三条","txt":"渔业船员培训、考试、发证，应当按国家有关规定缴纳相关费用。"},{"i":54,"n":"第五十四条","txt":"本办法自2015年1月1日起施行。农业部1994年8月18日公布的《内河渔业船舶船员考试发证规则》、1998年3月2日公布的《中华人民共和国渔业船舶普通船员专业基础训练考核发证办法》、2006年3月27日公布的《中华人民共和国海洋渔业船员发证规定》同时废止。 附件： 1.渔业职务船员证书等级划分； 2.渔业船员健康标准； 3.渔业职务船员证书申请资历条件； 4.海洋渔业船舶职务船员最低配员标准。"}],"yuyechuanbodengjibanfa":[{"i":1,"n":"第一条","txt":"为加强渔业船舶监督管理，确定渔业船舶的所有权、国籍、船籍港及其他有关法律关系，保障渔业船舶登记有关各方的合法权益，根据《中华人民共和国海上交通安全法》、《中华人民共和国渔业法》、《中华人民共和国海商法》等有关法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国公民、法人或非法人组织所有的渔业船舶，以及中华人民共和国公民、法人或非法人组织以光船条件从境外租进的渔业船舶，应当依照本办法进行登记。"},{"i":3,"n":"第三条","txt":"农业部主管全国渔业船舶登记工作。中华人民共和国渔政局具体负责全国渔业船舶登记及其监督管理工作。 县级以上地方人民政府渔业行政主管部门主管本行政区域内的渔业船舶登记工作。县级以上地方人民政府渔业行政主管部门所属的渔港监督机关（以下称登记机关）依照规定权限负责本行政区域内的渔业船舶登记及其监督管理工作。"},{"i":4,"n":"第四条","txt":"渔业船舶依照本办法进行登记，取得中华人民共和国国籍，方可悬挂中华人民共和国国旗航行。"},{"i":5,"n":"第五条","txt":"渔业船舶不得具有双重国籍。凡在境外登记的渔业船舶，未中止或者注销原登记国籍的，不得取得中华人民共和国国籍。"},{"i":6,"n":"第六条","txt":"渔业船舶所有人应当向户籍所在地或企业注册地的县级以上登记机关申请办理渔业船舶登记。 远洋渔业船舶登记由渔业船舶所有人向所在地省级登记机关申请办理。中央在京直属企业所属远洋渔业船舶登记由渔业船舶所有人向船舶所在地的省级登记机关申请办理。 渔业船舶登记的港口是渔业船舶的船籍港。每艘渔业船舶只能有一个船籍港。 省级登记机关应当根据本行政区域渔业船舶管理实际确定省级以下登记机关的登记权限和船籍港名称，并对外公告。"},{"i":7,"n":"第七条","txt":"登记机关应当建立渔业船舶登记簿，并将渔业船舶登记的内容载入渔业船舶登记簿。 权利人和利害关系人有权依法查阅渔业船舶登记簿。"},{"i":8,"n":"第八条","txt":"登记机关应当将登记的事项、依据、条件、程序、期限以及需要提交的全部材料目录和申请书示范文本在办公场所进行公示。 登记机关应当自受理申请之日起二十个工作日内作出是否准予渔业船舶登记的决定。不予登记的，书面通知当事人并说明理由。"},{"i":9,"n":"第九条","txt":"渔业船舶只能有一个船名。 远洋渔业船舶、科研船和教学实习船的船名由申请人在申请渔业船网工具指标时提出，经省级登记机关通过全国海洋渔船动态管理系统查询，无重名、同音且符合规范的，在《渔业船网工具指标申请书》上标注其船名、船籍港。渔业行政主管部门核发的《渔业船网工具指标批准书》应当载明上述船名、船籍港。公务船舶的船名按照农业部的规定办理。 前款规定以外的其他渔业船舶的船名由登记机关按照农业部的统一规定核定。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，渔业船舶所有人或承租人应当向登记机关申请船名： （一）制造、进口渔业船舶的； （二）因继承、赠与、购置、拍卖或法院生效判决取得渔业船舶所有权，需要变更船名的； （三）以光船条件从境外租进渔业船舶的。"},{"i":11,"n":"第十一条","txt":"申请渔业船舶船名核定，申请人应当填写渔业船舶船名申请表，交验渔业船舶所有人或承租人的户口簿或企业法人营业执照，并提交下列材料： （一）捕捞渔船和捕捞辅助船应当提交省级以上人民政府渔业行政主管部门签发的渔业船网工具指标批准书； （二）养殖渔船应当提交渔业船舶所有人持有的养殖证； （三）从境外租进的渔业船舶，应当提交农业部同意租赁的批准文件； （四）申请变更渔业船舶船名的，应当提供变更理由及相关证明材料。"},{"i":12,"n":"第十二条","txt":"登记机关应当自受理申请之日起七个工作日内作出核定决定。予以核定的，向申请人核发渔业船舶船名核定书，同时确定该渔业船舶的船籍港。不予核定的，书面通知当事人并说明理由。"},{"i":13,"n":"第十三条","txt":"渔业船舶船名核定书的有效期为十八个月。 超过有效期未使用船名的，渔业船舶船名核定书作废，渔业船舶所有人应当按照本办法规定重新提出申请。"},{"i":14,"n":"第十四条","txt":"渔业船舶所有权的取得、转让和消灭，应当依照本办法进行登记；未经登记的，不得对抗善意第三人。"},{"i":15,"n":"第十五条","txt":"渔业船舶所有权登记，由渔业船舶所有人申请。共有的渔业船舶，由持股比例最大的共有人申请；持股比例相同的，由约定的共有人一方申请。 申请渔业船舶所有权登记，应当填写渔业船舶所有权登记申请表，并提交下列材料： （一）渔业船舶所有人户口簿或企业法人营业执照； （二）取得渔业船舶所有权的证明文件： 1.制造渔业船舶，提交建造合同和交接文件； 2.购置渔业船舶，提交买卖合同和交接文件； 3.渔业船舶检验证书、依法需要取得的渔业船舶船名核定书； 4.渔业船舶共有的，提交共有协议； 5.其他证明渔业船舶合法来源的文件。 （三）渔业船舶检验证书、依法需要取得的渔业船舶船名核定书； （四）反映船舶全貌和主要特征的渔业船舶照片； （五）原船籍港登记机关出具的渔业船舶所有权注销登记证明书（制造渔业船舶除外）； （六）捕捞渔船和捕捞辅助船的渔业船网工具指标批准书； （七）养殖渔船所有人持有的养殖证； （八）进口"},{"i":16,"n":"第十六条","txt":"渔业船舶应当依照本办法进行渔业船舶国籍登记，方可取得航行权。"},{"i":17,"n":"第十七条","txt":"渔业船舶国籍登记，由渔业船舶所有人申请。 申请国籍登记，应当填写渔业船舶国籍登记申请表，并提交下列材料： （一）渔业船舶所有人的户口簿或企业法人营业执照； （二）渔业船舶所有权登记证书； （三）渔业船舶检验证书； （四）捕捞渔船和捕捞辅助船的渔业船网工具指标批准书； （五）养殖渔船所有人持有的养殖证； （六）进口渔业船舶的准予进口批准文件和办结海关手续的证明； （七）渔业船舶委托其他渔业企业代理经营的，提交代理协议和代理企业的营业执照； （八）原船籍港登记机关出具的渔业船舶国籍注销或者中止证明书（制造渔业船舶除外）； （九）农业部规定的其他材料。 国籍登记与所有权登记同时申请的，免予提交前款规定的第一、二、三、四、五、六项材料。 登记机关准予登记的，向船舶所有人核发渔业船舶国籍证书，同时核发渔业船舶航行签证簿，载明船舶主要技术参数。"},{"i":18,"n":"第十八条","txt":"从事国内作业的渔业船舶经批准从事远洋渔业的，渔业船舶所有人应当持有关批准文件和国际渔船安全证书向省级登记机关申请换发渔业船舶国籍证书，并将原渔业船舶国籍证书交由省级登记机关暂存。"},{"i":19,"n":"第十九条","txt":"经农业部批准从事远洋渔业的渔业船舶，需要加入他国国籍方可在他国管辖海域作业的，渔业船舶所有人应当持有关批准文件和国际渔船安全证书向省级登记机关申请中止渔业船舶国籍。登记机关准予中止国籍的，应当封存该渔业船舶国籍证书和航行签证簿，并核发渔业船舶国籍中止证明书。 依照前款规定中止国籍的渔业船舶申请恢复国籍的，应当持有关批准文件和他国登记机关出具的注销该国国籍证明书或者将于重新登记时立即注销该国国籍的证明书，向省级登记机关提出申请。登记机关准予恢复国籍的，应当发还该渔业船舶国籍证书和航行签证簿，并收回渔业船舶国籍中止证明书。"},{"i":20,"n":"第二十条","txt":"以光船条件从境外租进渔业船舶的，承租人应当持光船租赁合同、渔业船舶检验证书或报告、农业部批准租进的文件和原登记机关出具的中止或者注销原国籍的证明书，或者将于重新登记时立即中止或者注销原国籍的证明书，向省级登记机关申请办理临时渔业船舶国籍证书。"},{"i":21,"n":"第二十一条","txt":"渔业船舶国籍证书有效期为五年。 对达到农业部规定的老旧渔业船舶船龄的渔业船舶，登记机关核发渔业船舶国籍证书时，其证书有效期限不得超过渔业船舶检验证书记载的有效期限。"},{"i":22,"n":"第二十二条","txt":"以光船租赁条件从境外租进的渔业船舶，临时渔业船舶国籍证书的有效期根据租赁合同期限确定，但是最长不得超过两年。 租赁合同期限超过两年的，承租人应当在证书有效期届满三十日前，持渔业船舶租赁登记证书、原临时渔业船舶国籍证书和租赁合同，向原登记机关申请换发临时渔业船舶国籍证书。"},{"i":23,"n":"第二十三条","txt":"渔业船舶国籍证书或临时渔业船舶国籍证书必须随船携带。"},{"i":24,"n":"第二十四条","txt":"渔业船舶抵押权的设定、转移和消灭，抵押权人和抵押人应当共同依照本办法进行登记；未经登记的，不得对抗善意第三人。"},{"i":25,"n":"第二十五条","txt":"渔业船舶所有人或其授权的人可以设定船舶抵押权。 渔业船舶共有人就共有渔业船舶设定抵押权时，应当提供三分之二以上份额或者约定份额的共有人同意的证明文件。 渔业船舶抵押权的设定，应当签订书面合同。"},{"i":26,"n":"第二十六条","txt":"同一渔业船舶可以依法设定两个以上抵押权，抵押关系设定顺序，以抵押登记的先后为准。"},{"i":27,"n":"第二十七条","txt":"抵押权人和抵押人共同申请渔业船舶抵押权登记，应当填写渔业船舶抵押权登记申请表，并提交下列材料： （一）抵押权人和抵押人的户口簿或企业法人营业执照； （二）渔业船舶所有权登记证书； （三）抵押合同及其主合同； （四）农业部规定的其他材料。 登记机关准予登记的，应当将抵押权登记情况载入渔业船舶所有权登记证书，并向抵押权人核发渔业船舶抵押权登记证书。"},{"i":28,"n":"第二十八条","txt":"抵押权人依法转移船舶抵押权的，应当和承转人持渔业船舶所有权登记证书、渔业船舶抵押权登记证书和船舶抵押权转移合同，向原登记机关申请办理抵押权转移登记。 办理渔业船舶抵押权转移登记，抵押权人应当事先通知抵押人。 登记机关准予登记的，应当将有关抵押权转移情况载入渔业船舶所有权登记证书，封存原渔业船舶抵押权登记证书，并向承转人核发渔业船舶抵押权登记证书。"},{"i":29,"n":"第二十九条","txt":"以光船条件出租渔业船舶，或者以光船条件租进境外渔业船舶的，出租人和承租人应当依照本办法进行光船租赁登记；未经登记的，不得对抗善意第三人。"},{"i":30,"n":"第三十条","txt":"中国籍渔业船舶以光船条件出租给中国籍公民或法人的，出租人和承租人应当共同填写渔业船舶租赁登记申请表，向船籍港登记机关申请办理光船租赁登记，并提交下列材料： （一）承租人的户口簿或企业法人营业执照； （二）渔业船舶所有权登记证书、渔业船舶国籍证书、渔业船舶检验证书和渔业船舶航行签证簿； （三）租赁合同； （四）租赁捕捞渔船和捕捞辅助船的，提交出租人所在地渔业行政主管部门出具的捕捞许可证注销证明、承租人所在地渔业行政主管部门同意租赁渔业船舶的证明文件；租赁远洋渔业船舶或者跨省租赁渔业船舶的，还应当经出租人和承租人双方所在地省级人民政府渔业行政主管部门同意后报农业部批准； （五）渔业船舶已设定抵押权的，提供抵押权人同意出租该渔业船舶的证明文件； （六）农业部规定的其他材料。 登记机关准予登记的，应当将租赁情况载入渔业船舶所有权登记证书和国籍证书，并向出租人和承租人核发渔业船舶租赁登记证书各一"},{"i":31,"n":"第三十一条","txt":"中国籍渔业船舶以光船条件出租到境外的，出租人应当持本办法第三十条第一款第二、三、五、六项规定的文件，向船籍港登记机关申请办理光船租赁登记。捕捞渔船和捕捞辅助船还应当提供省级以上人民政府渔业行政主管部门出具的渔业捕捞许可证暂存证明。 登记机关准予登记的，应当中止该渔业船舶国籍，封存渔业船舶国籍证书和航行签证簿，将租赁情况载入渔业船舶所有权登记证书和国籍证书，并向出租人核发渔业船舶租赁登记证书和渔业船舶国籍中止证明书。"},{"i":32,"n":"第三十二条","txt":"中国籍公民、法人或非法人组织以光船条件租进境外渔业船舶的，承租人应当填写渔业船舶租赁登记申请表，向所在地省级登记机关申请办理光船租赁登记，并提交下列材料： （一）承租人的户口簿或企业法人营业执照； （二）租赁合同； （三）国家渔业船舶检验机构签发的渔业船舶检验证书或检验报告； （四）境外登记机关出具的中止或注销该船国籍的文件，或者将于重新登记时立即中止或注销船舶国籍的文件； （五）农业部批准租进的文件； （六）农业部规定的其他材料。 登记机关准予登记的，应当向承租人核发渔业船舶租赁登记证书，并将租赁登记内容载入临时渔业船舶国籍证书。"},{"i":33,"n":"第三十三条","txt":"下列登记事项发生变更的，渔业船舶所有人应当向原登记机关申请变更登记∶ （一）船名； （二）船舶主尺度、吨位或船舶种类； （三）船舶主机类型、数量或功率； （四）船舶所有人姓名、名称或地址（船舶所有权发生转移的除外）； （五）船舶共有情况； （六）船舶抵押合同、租赁合同（解除合同的除外）。"},{"i":34,"n":"第三十四条","txt":"渔业船舶所有人申请变更登记，应当填写渔业船舶变更登记申请表，并提交下列材料： （一）渔业船舶所有人的户口簿或企业法人营业执照； （二）渔业船舶所有权登记证书、渔业船舶国籍证书、渔业船舶检验证书和航行签证簿； （三）变更登记证明材料： 1.远洋渔业船舶、科研船和教学实习船以外的渔业船舶船名变更的，提交渔业船舶船名核定书； 2.更新改造捕捞渔船和捕捞辅助船的，提交渔业船网工具指标批准书； 3.渔业船舶所有人姓名、名称或地址变更的，提交公安部门或者工商行政管理部门核发的变更证明文件； 4.船舶抵押合同变更的，提交抵押合同及补充协议和抵押权登记证书；船舶租赁合同变更的，提交租赁合同及补充协议和租赁登记证书； 5.船舶共有情况变更的，提交共有协议和共有各方同意变更的书面证明。 （四）农业部规定的其他材料。 登记机关受理变更登记申请，经审查发现申请变更事项将导致登记机关发生变更的，应当书面通知渔业"},{"i":35,"n":"第三十五条","txt":"渔业船舶有下列情形之一的，渔业船舶所有人应当向登记机关申请办理渔业船舶所有权注销登记： （一）所有权转移的； （二）灭失或失踪满六个月的； （三）拆解或销毁的； （四）自行终止渔业生产活动的。"},{"i":36,"n":"第三十六条","txt":"渔业船舶所有人申请注销登记，应当填写渔业船舶注销登记申请表，并提交下列材料： （一）渔业船舶所有人的户口簿或企业法人营业执照； （二）渔业船舶所有权登记证书、国籍证书和航行签证簿。因证书灭失无法交回的，应当提交书面说明和在当地报纸上公告声明的证明材料； （三）捕捞渔船和捕捞辅助船的捕捞许可证注销证明； （四）注销登记证明材料： 1.渔业船舶所有权转移的，提交渔业船舶买卖协议或所有权转移的其他法律文件； 2.渔业船舶灭失或失踪六个月以上的，提交有关渔港监督机构出具的证明文件； 3.渔业船舶拆解或销毁的，提交有关渔业行政主管部门出具的渔业船舶拆解、销毁或处理证明； 4.渔业船舶已办理抵押权登记或租赁登记的，提交相应登记注销证明书； 5.自行终止渔业生产活动的，提交不再从事渔业生产活动的书面声明。 （五）农业部规定的其他材料。 登记机关准予注销登记的，应当收回前款第二项所列证书，并向渔业船舶"},{"i":37,"n":"第三十七条","txt":"渔业船舶所有权因依法拍卖和法院生效判决发生转移，但原所有人未申请注销的，依法取得该渔业船舶所有权的所有人可以向登记机关申请注销所有权登记，并提交第三十六条第一项、第三项、第四项第一目、第五项所列材料。登记机关经审查准予注销登记的，应当向申请人出具渔业船舶注销登记证明书。 渔业船舶灭失或失踪、拆解或销毁的，依法取得渔业船舶相关权利的权利人可以依照前款规定向登记机关申请注销登记。 登记机关准予注销渔业船舶所有权登记和国籍的，应当予以公告。"},{"i":38,"n":"第三十八条","txt":"渔业船舶有第三十五条第二、三项情形之一，但所有人或者依法取得渔业船舶相关权利的权利人未申请注销所有权登记的，登记机关经查明，可在上述情形发生六个月后，在当地报纸上发布拟注销登记公告。自公告发布之日起三十日内无异议或异议不成立的，登记机关可注销该渔业船舶所有权登记和国籍登记，并予以公告。"},{"i":39,"n":"第三十九条","txt":"有下列情形之一的，登记机关可直接注销该渔业船舶国籍： （一）国籍证书有效期满未延续的； （二）渔业船舶检验证书有效期满未依法延续的； （三）以贿赂、欺骗等不正当手段取得渔业船舶国籍的； （四）依法应当注销的其他情形。"},{"i":40,"n":"第四十条","txt":"已经办理注销登记的灭失或失踪的渔业船舶，经打捞或寻找，原船恢复后，渔业船舶所有人应当书面说明理由，持有关证明文件，依照本办法向原登记机关重新申请办理渔业船舶登记。"},{"i":41,"n":"第四十一条","txt":"船舶抵押合同解除，抵押权人和抵押人应当填写渔业船舶抵押权注销登记申请表，持渔业船舶所有权登记证书、渔业船舶抵押权登记证书、经抵押权人签字的解除抵押合同的文件和双方身份证明文件，向登记机关申请办理船舶抵押权注销登记。 登记机关准予注销登记的，应当注销其在渔业船舶所有权登记证书上的抵押登记记录，收回渔业船舶抵押权登记证书，存入该船登记档案。"},{"i":42,"n":"第四十二条","txt":"中国籍渔业船舶以光船条件出租给中国籍公民或法人的光船租赁合同期满或光船租赁关系终止，出租人和承租人应当自光船租赁合同期满或光船租赁关系终止之日起三十日内，填写渔业船舶租赁登记注销申请表，向登记机关申请办理光船租赁注销登记，并提交下列材料： （一）渔业船舶所有权登记证书、国籍证书； （二）渔业船舶租赁登记证书； （三）光船租赁合同或者终止光船租赁关系的证明文件； （四）捕捞渔船和捕捞辅助船的捕捞许可证注销证明； （五）农业部规定的其他材料。 登记机关准予注销登记的，应当注销渔业船舶所有权登记证书和国籍证书上的光船租赁登记记录，收回渔业船舶租赁登记证书，向出租人、承租人分别出具渔业船舶租赁登记注销证明书。"},{"i":43,"n":"第四十三条","txt":"中国籍渔业船舶以光船条件出租到境外的光船租赁合同期满或光船租赁关系终止，出租人应当自光船租赁合同期满或光船租赁关系终止之日起三十日内，填写渔业船舶租赁登记注销申请表，向登记机关申请办理光船租赁注销登记，并提交下列材料： （一）渔业船舶所有权登记证书； （二）渔业船舶租赁登记证书； （三）光船租赁合同或者终止光船租赁关系的证明文件； （四）境外登记机关出具的国籍登记注销证明书或者将于重新登记时立即注销船舶国籍的证明书； 登记机关准予注销登记的，应当注销渔业船舶所有权登记证书和国籍证书上的光船租赁登记记录，收回渔业船舶租赁登记证书，向出租人出具渔业船舶租赁登记注销证明书，并发还封存的渔业船舶国籍证书和航行签证簿，依法恢复该船国籍。"},{"i":44,"n":"第四十四条","txt":"中国籍公民、法人或非法人组织以光船租赁条件从境外租进渔业船舶的光船租赁合同期满或光船租赁关系终止，承租人应当自光船租赁合同期满或光船租赁关系终止之日起三十日内，填写渔业船舶租赁登记注销申请表，向登记机关申请办理光船租赁注销登记，并提交下列材料： （一）渔业船舶租赁登记证书； （二）光船租赁合同或者终止光船租赁关系的证明文件； （三）临时渔业船舶国籍证书和航行签证簿； （四）捕捞渔船和捕捞辅助船的捕捞许可证注销证明； （五）农业部规定的其他材料。 登记机关准予注销登记的，应当注销该光船租赁登记记录，收回临时渔业船舶国籍证书和渔业船舶租赁登记证书，向承租人出具渔业船舶租赁登记注销证明书。"},{"i":45,"n":"第四十五条","txt":"渔业船舶所有人应当在渔业船舶国籍证书有效期届满三个月前，持渔业船舶国籍证书和渔业船舶检验证书到登记机关申请换发国籍证书。 渔业船舶登记证书污损不能使用的，渔业船舶所有人应当持原证书向登记机关申请换发。"},{"i":46,"n":"第四十六条","txt":"渔业船舶登记相关证书、证明遗失或者灭失的，渔业船舶所有人应当在当地报纸上公告声明，并自公告发布之日起十五日后凭有关证明材料向登记机关申请补发证书、证明。 申请补发渔业船舶国籍证书期间需要航行作业的，渔业船舶所有人可以向原登记机关申请办理有效期不超过一个月的临时渔业船舶国籍证书。"},{"i":47,"n":"第四十七条","txt":"渔业船舶国籍证书在境外遗失、灭失或者损坏的，渔业船舶所有人应当向中华人民共和国驻外使（领）馆申请办理临时渔业船舶国籍证书，并同时向原登记机关申请补发渔业船舶国籍证书。"},{"i":48,"n":"第四十八条","txt":"县级以上人民政府渔业行政主管部门应当加强渔业船舶登记管理信息系统建设，建立健全渔业船舶数据库，提高渔业船舶登记管理和服务水平，保障渔业船舶当事人合法权益。"},{"i":49,"n":"第四十九条","txt":"登记机关应当建立渔业船舶登记档案。 渔业船舶所有权、国籍登记注销后，登记档案应当保存不少于五年。"},{"i":50,"n":"第五十条","txt":"禁止涂改、伪造、变造、转让渔业船舶登记证书。 有前款情形的，渔业船舶登记证书无效。"},{"i":51,"n":"第五十一条","txt":"违反本办法规定的，依照有关法律、行政法规和规章进行处罚。"},{"i":52,"n":"第五十二条","txt":"本办法所称渔业船舶，系指《中华人民共和国渔港水域交通安全管理条例》第四条规定的渔业船舶。"},{"i":53,"n":"第五十三条","txt":"港澳流动渔船的登记备案，按照农业部有关港澳流动渔船管理的规定执行。"},{"i":54,"n":"第五十四条","txt":"渔业船舶登记费的收取、使用和管理，按照国家有关规定执行。"},{"i":55,"n":"第五十五条","txt":"渔业船舶船名核定书、渔业船舶登记簿、渔业船舶所有权登记证书、渔业船舶国籍证书、临时渔业船舶国籍证书、渔业船舶抵押权登记证书、渔业船舶租赁登记证书、渔业船舶注销或中止证明书由农业部统一印制。 渔业船舶登记申请表由各省、自治区、直辖市登记机关按农业部规定的统一格式印制。"},{"i":56,"n":"第五十六条","txt":"各省、自治区、直辖市人民政府渔业行政主管部门可依据本办法，结合本地实际情况，制定实施办法，报农业部备案。 船长在十二米以下的小型渔业船舶的登记程序可适当简化，具体办法由各省、自治区、直辖市人民政府渔业行政主管部门在制定实施办法时规定。"},{"i":57,"n":"第五十七条","txt":"本办法自2013年1月1日起施行。农业部1996年1月22日发布，1997年12月25日、2004年7月1日、2010年11月26日修订的《中华人民共和国渔业船舶登记办法》（农渔发[1996]2号）同时废止。"}],"guanxiahaiyuwaiguorenwaiguochuanboyuyehuodongguanla05e71":[{"i":1,"n":"第一条","txt":"为加强中华人民共和国管辖海域内渔业活动的管理，维护国家海洋权益，根据《中华人民共和国渔业法》、《中华人民共和国专属经济区和大陆架法》、《中华人民共和国领海及毗连区法》等法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于外国人、外国船舶在中华人民共和国管辖海域内从事渔业生产、生物资源调查等涉及渔业的有关活动。"},{"i":3,"n":"第三条","txt":"任何外国人、外国船舶在中华人民共和国管辖海域内从事渔业生产、生物资源调查等活动的，必须经中华人民共和国渔政渔港监督管理局批准，并遵守中华人民共和国的法律、法规以及中华人民共和国缔结或参加的国际条约与协定。"},{"i":4,"n":"第四条","txt":"中华人民共和国内水、领海内禁止外国人、外国船舶从事渔业生产活动；经批准从事生物资源调查活动必须采用与中方合作的方式进行。"},{"i":5,"n":"第五条","txt":"中华人民共和国渔政渔港监督管理局根据以下条件对外国人的入渔申请进行审批： 1.申请的活动，不危害中华人民共和国国家安全，不妨碍中华人民共和国缔结或参加的国际条约与协定的执行； 2.申请的活动，不对中华人民共和国实施的海洋生物资源养护措施和海洋环境造成不利影响； 3.申请的船舶数量、作业类型和渔获量等符合中华人民共和国管辖海域内的资源状况。"},{"i":6,"n":"第六条","txt":"外国渔业船舶申请在中华人民共和国管辖水域从事渔业生产的，应当向中华人民共和国渔政渔港监督管理局提出。中华人民共和国渔政渔港监督管理局应当自申请受理之日起20日内作出是否发放捕捞许可证的决定。 外国人、外国渔业船舶申请在中华人民共和国管辖水域从事渔业资源调查活动的，应当向农业农村部提出。农业农村部应当自申请受理之日起20日内作出是否批准其从事渔业活动的决定。"},{"i":7,"n":"第七条","txt":"外国人、外国船舶入渔申请获得批准后，应当向中华人民共和国渔政渔港监督管理局缴纳入渔费并领取许可证。如有特殊情况，经批准机关同意，入渔费可予以减免。 经批准进入中华人民共和国渔港的，应按规定缴纳港口费用。"},{"i":8,"n":"第八条","txt":"经批准作业的外国人、外国船舶领取许可证后，按许可证确定的作业船舶、作业区域、作业时间、作业类型、渔获数量等有关事项作业，并按照中华人民共和国渔政渔港监督管理局的有关规定填写捕捞日志、悬挂标志和执行报告制度。"},{"i":9,"n":"第九条","txt":"在中华人民共和国管辖海域内的外国人、外国船舶，未经中华人民共和国渔政渔港监督管理局批准，不得在船舶间转载渔获物及其制品或补给物品。"},{"i":10,"n":"第十条","txt":"经批准转载的外国鱼货运输船、补给船，必须按规定向中华人民共和国有关海区渔政渔港监督管理机构申报进入中华人民共和国管辖海域过驳鱼货或补给的时间、地点，被驳鱼货或补给的船舶船名、鱼种、驳运量，或主要补给物品和数量。过驳或补给结束，应申报确切过驳数量。"},{"i":11,"n":"第十一条","txt":"外国人、外国船舶在中华人民共和国管辖海域内从事渔业生产、生物资源调查等活动以及进入中华人民共和国渔港的，应当接受中华人民共和国渔政渔港监督管理机构的监督检查和管理。 中华人民共和国渔政渔港监督管理机构及其检查人员在必要时，可以对外国船舶采取登临、检查、驱逐、扣留等必要措施，并可行使紧追权。"},{"i":12,"n":"第十二条","txt":"外国人、外国船舶在中华人民共和国内水、领海内有下列行为之一的，责令其离开或者将其驱逐，可处以没收渔获物、渔具、并处以罚款；情节严重的，可以没收渔船。罚款按下列数额执行： 1.从事捕捞、补给或转载渔获等渔业生产活动的，可处50万元以下罚款； 2.未经批准从事生物资源调查活动的，可处40万元以下罚款。"},{"i":13,"n":"第十三条","txt":"外国人、外国船舶在中华人民共和国专属经济区和大陆架有下列行为之一的，责令其离开或者将其驱逐，可处以没收渔获物、渔具，并处以罚款；情节严重的，可以没收渔船。罚款按下列数额执行： 1.从事捕捞、补给或转载渔获等渔业生产活动的，可处40万元以下罚款； 2.从事生物资源调查活动的，可处30万元以下罚款。"},{"i":14,"n":"第十四条","txt":"外国人、外国船舶经批准在中华人民共和国专属经济区和大陆架从事渔业生产、生物资源调查活动，有下列行为之一的，可处以没收渔获物、没收渔具和30万元以下罚款的处罚： 1.未按许可的作业区域、时间、类型、船舶功率或吨位作业的； 2.超过核定捕捞配额的。"},{"i":15,"n":"第十五条","txt":"外国人、外国船舶经批准在中华人民共和国专属经济区和大陆架从事渔业生产、生物资源调查活动，有下列行为之一的，没收渔获物和违法所得，可以并处5万元以下的罚款；情节严重的，并可以没收渔具，吊销捕捞许可证： 1.未按规定填写渔捞日志的； 2.未按规定向指定的监督机构报告船位、渔捞情况等信息的； 3.未按规定标识作业船舶的； 4.未按规定的网具规格和网目尺寸作业的。"},{"i":16,"n":"第十六条","txt":"未取得入渔许可进入中华人民共和国管辖水域，或取得入渔许可但航行于许可作业区域以外的外国船舶，未将渔具收入舱内或未按规定捆扎、覆盖的，中华人民共和国渔政渔港监督管理机构可处以3万元以下罚款的处罚。"},{"i":17,"n":"第十七条","txt":"外国船舶进出中华人民共和国渔港，有下列行为之一的，中华人民共和国渔政渔港监督管理机构有权禁止其进、离港口，或者令其停航、改航、停止作业，并可处以3万元以下罚款的处罚： 1.未经批准进出中华人民共和国渔港的； 2.违反船舶装运、装卸危险品规定的； 3.拒不服从渔政渔港监督管理机构指挥调度的； 4.拒不执行渔政渔港监督管理机构作出的离港、停航、改航、停止作业和禁止进、离港等决定的。"},{"i":18,"n":"第十八条","txt":"外国人、外国船舶对中华人民共和国渔港及渔港水域造成污染的，中华人民共和国渔政渔港监督管理机构可视情节及危害程度，处以警告或10万元以下的罚款。对造成渔港水域环境污染损害的，可责令其支付消除污染费用，赔偿损失。"},{"i":19,"n":"第十九条","txt":"中华人民共和国渔政渔港监督管理局和各海区渔政渔港监督管理局可决定50万元以下罚款的处罚。 省（自治区、直辖市）渔政渔港监督管理机构可决定20万元以下罚款的处罚。 市、县渔政渔港监督管理机构可决定5万元以下罚款的处罚。 作出超过本级机构权限的行政处罚决定的，必须事先报经具有相应处罚权的上级渔政渔港监督管理机构批准。"},{"i":20,"n":"第二十条","txt":"受到罚款处罚的外国船舶及其人员，必须在离港或开航前缴清罚款。不能在离港或开航前缴清罚款的，应当提交相当于罚款额的保证金或处罚决定机关认可的其他担保，否则不得离港。"},{"i":21,"n":"第二十一条","txt":"外国人、外国船舶违反本规定和中华人民共和国有关法律、法规，情节严重的，除依法给予行政处罚或移送有关部门追究法律责任外，中华人民共和国渔政渔港监督管理局并可取消其入渔资格。"},{"i":22,"n":"第二十二条","txt":"外国人、外国船舶对渔业行政处罚不服的，可依据中华人民共和国法律、法规的有关规定申请复议或提起诉讼。"},{"i":23,"n":"第二十三条","txt":"本规定与我国缔结或参加的有关国际渔业条约有不同规定的，适用国际条约的规定，但我国声明保留的除外。"},{"i":24,"n":"第二十四条","txt":"本规定未尽事项，按照中华人民共和国有关法律、法规的规定办理。"},{"i":25,"n":"第二十五条","txt":"本规定由农业农村部负责解释。"},{"i":26,"n":"第二十六条","txt":"本规定自发布之日起施行。"}],"zhongriyuyexiedingzandingcuoshishuiyuguanlizanxinga792ca":[{"i":1,"n":"第一条","txt":"为了养护和合理利用海洋渔业资源，维护《中华人民共和国和日本国渔业协定》（以下称《中日渔业协定》）规定的暂定措施水域的正常渔业生产秩序，根据《中华人民共和国渔业法》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法运用于在《中日渔业协定》第七条第一款规定的暂定措施水域从事渔业活动的我国渔船。 暂定措施水域为下列各点顺次用直线连结而围成的水域： 1、北纬30度40分、东经124度10.1分； 2、北纬30度、东经123度56.4分； 3、北纬29度、东经123度25.5分； 4、北纬28度、东经122度47.9分； 5、北纬27度、东经121度57.4分； 6、北纬27度、东经125度58.3分； 7、北纬28度、东经127度15.1分； 8、北纬29度、东经128度0.9分； 9、北纬30度、东经128度32.2分； 10、北纬30度40分、东经128度26.1分； ll、北纬30度40分、东经124度10.1分。"},{"i":3,"n":"第三条","txt":"中华人民共和国渔政渔港监督管理局是实施《中日渔业协定》的主管机关。负责对暂定措施水域的渔业活动进行管理。 农业农村部东海区渔政渔港监督管理局负责暂定措施水域渔船生产情况的汇总、统计和分析，对暂定措施水域的渔业活动进行现场指导和监督检查。"},{"i":4,"n":"第四条","txt":"中华人民共和国渔政渔港监督管理局根据中日渔业联合委员会每年商定的作业规模，确定当年我国渔船进入暂定措施水域作业的船数和类型，并下达给东海区、黄渤海区渔政渔港监督管理局，由其分配各有关省、市。"},{"i":5,"n":"第五条","txt":"申请到暂定措施水域从事渔业活动的申请人或渔船，必须具备以下条件： （一）持有有效的渔业捕捞许可证。 （二）船舶处于适航状态，并持有与作业航区相适应的船舶检验证书、船舶登记证书（或船舶国籍证书），航行签证簿。主机额定功率在300千瓦以上的渔船，还应备有油类记录簿。 （三）按规定配齐船员，职务船员应持有有效的职务船员证书（或适任证书）。 （四）按规定填写和上交上一年度的捕捞日志。 （五）渔船按规定进行标记。"},{"i":6,"n":"第六条","txt":"申请进入中日渔业协定暂定措施水域作业的渔业捕捞许可证，应当于每年4月10日前向所在地省、自治区、直辖市人民政府渔业主管部门提出。省、自治区、直辖市人民政府渔业主管部门应当自受理申请之日起20日内完成审核，并报农业农村部审批。 农业农村部自收到省、自治区、直辖市人民政府渔业主管部门报送的材料之日起20日内作出是否发放捕捞许可证的决定。申请表由农业农村部统一印制。"},{"i":7,"n":"第七条","txt":"经批准在暂定措施水域从事渔业活动的渔船，必须按规定填写\"《中日渔业协定》暂定措施水域捕捞日志\"（附件二），并在申请下一年度作业资格时，连同作业申请表一并交送船籍港所在地的县级渔业主管部门。 各级渔业主管部门在向申请人递交特许证时，必须同时发给申请人空白捕捞日志，并就捕捞日志的填写对申请人进行必要的培训和指导。"},{"i":8,"n":"第八条","txt":"县级渔业主管部门负责本辖区渔船捕捞日志的收集、统计工作，并逐级上报地（市）、省（直辖市）渔业主管部门和海区渔政渔港监督管理局汇总。黄渤海区渔船在暂定措施水域的生产情况由黄渤海区渔政渔港监督管理局交东海区渔政渔港监督管理局汇总。 捕捞日志的数据处理方法，由中华人民共和国渔政渔港监督管理局另行规定。"},{"i":9,"n":"第九条","txt":"经批准在暂定措施水域从事渔业活动的渔船，必须按规定进行标记。具体标记方式由中华人民共和国渔政渔港监督管理局另行规定。"},{"i":10,"n":"第十条","txt":"经批准在暂定措施水域从事渔业活动的渔船，必须遵守《中华人民共和国渔业法》和国家在暂定措施水域内实施的各项渔业资源养护的规定。"},{"i":11,"n":"第十一条","txt":"在暂定措施水域从事渔业活动的渔船发生渔事纠纷的，按现行的有关规定处理。"},{"i":12,"n":"第十二条","txt":"违反本办法的，按《中华人民共和国渔业法实施细则》和国家有关规定予以处罚。"},{"i":13,"n":"第十三条","txt":"本办法由农业农村部负责解释。"},{"i":14,"n":"第十四条","txt":"本办法自《中日渔业协定》正式生效之日起实施。"}],"zhonghanyuyexiedingzandingcuoshishuiyuheguodushuiy58f196":[{"i":1,"n":"第一条","txt":"为了养护和合理利用海洋渔业资源，维护《中华人民共和国政府和大韩民国政府渔业协定》（以下称《中韩渔业协定》）规定的“暂定措施水域”和“过渡水域”的正常渔业秩序，根据《中华人民共和国渔业法》等法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在《中韩渔业协定》第七条第一款规定的“暂定措施水域”和第八条第一款规定的“韩方一侧过渡水域”（以下称“过渡水域”）从事渔业活动的我国渔船。"},{"i":3,"n":"第三条","txt":"中华人民共和国农业部是实施《中韩渔业协定》的主管机关，中华人民共和国渔政渔港监督管理局负责对暂定措施水域和过渡水域的渔业活动进行管理。 农业部黄渤海区渔政渔港监督管理局负责暂定措施水域和过渡水域管理的组织实施、现场指导和监督检查，并对我国渔船的生产情况进行汇总、统计和分析，东海区渔政渔港监督管理局协助。 沿渤海、黄海、东海各省（直辖市）、地（市）、县级渔业行政主管部门负责本辖区在暂定措施水域和过渡水域从事渔业活动渔船申请资格、渔船条件的审核，有关证件、材料的转发、发放和收集工作，并对申请人和渔船进行必要的指导和管理。"},{"i":4,"n":"第四条","txt":"中华人民共和国渔政渔港监督管理局每年根据中韩渔业联合委员会商定的作业规模（作业类型、船数、渔获量等），确定下一年度我国渔船进入暂定措施水域和过渡水域的作业规模，并下达给黄渤海区、东海区渔政渔港监督管理局，由其分配给本海区有关省（市）。"},{"i":5,"n":"第五条","txt":"凡需进入暂定措施水域和过渡水域从事渔业活动的渔船，必须由船舶所有人向其船籍所在地的县级渔业行政主管部门提出申请，并填写《中韩渔业协定暂定措施水域／过渡水域渔船作业申请表》（以下称《申请表》，格式见附件一）。 申请表由县级渔业行政主管部门审核、汇总后，逐级上报地（市）、省（直辖市）渔业行政主管部门审核，报所在海区渔政渔港监督管理局审批。省（直辖市）渔业行政主管部门负责对本省（市）渔船的申请作业规模进行控制，上报作业规模不得超过海区渔政渔港监督管理局分配的作业规模。"},{"i":6,"n":"第六条","txt":"申请进入暂定措施水域和过渡水域从事渔业活动的渔船必须具备下列条件： 1、持有有效的渔业捕捞许可证书、船舶检验证书、船舶登记证书（或船舶国籍证书）、电台执照及其他必备证书。 2、适航航区在Ⅱ类以上，并处于适航状态，装备有全球卫星定位仪（GPS）。 3、按规定配齐船员，职务船员应持有有效的职务船员证书。"},{"i":7,"n":"第七条","txt":"经审查符合条件的渔船，黄渤海区、东海区渔政渔港监督管理局发给有效期为1年的专项（特许）渔业捕捞许可证（以下称《专项证》）。《专项证》由受理申请的县级渔业行政主管部门向申请人转交。转交《专项证》时，须同时发给申请人空白《中华人民共和国 渔捞日志》（以下称《渔捞日志》，格式见附件二），并就《渔捞日志》的填写、收集、管理等对申请人进行必要的培训和指导。"},{"i":8,"n":"第八条","txt":"黄渤海区、东海区渔政渔港监督管理局每年编制暂定措施水域和过渡水域许可渔船名录，报中华人民共和国渔政渔港监督管理局备案。"},{"i":9,"n":"第九条","txt":"经批准在暂定措施水域和过渡水域从事渔业活动的渔船，必须认真、如实填写《渔捞日志》。申请人在申请下一年度作业资格时，须将《申请表》和上一年度的《渔捞日志》同时交送受理申请的县级渔业行政主管部门。"},{"i":10,"n":"第十条","txt":"受理申请的县级渔业行政主管部门负责申请渔船《渔捞日志》的收集、统计工作，并逐级上报地（市）、省（直辖市）渔业行政主管部门，由省（直辖市）渔业行政主管部门统一报所在海区渔政渔港监督管理局。东海区渔船的《渔捞日志》和生产情况由东海区渔政渔港监督管理局交黄渤海区渔政渔港监督管理局汇总。 《渔捞日志》数据的处理方法，由中华人民共和国渔政渔港监督管理局另行规定。"},{"i":11,"n":"第十一条","txt":"经批准在暂定措施水域和过渡水域从事渔业活动的渔船必须按规定标记。具体标记方式由中华人民共和国渔政渔港监督管理局另行规定。"},{"i":12,"n":"第十二条","txt":"经批准在暂定措施水域和过渡水域从事渔业活动的渔船，必须遵守我国渔业法律、法规，遵守中韩双方商定的暂定措施水域、过渡水域资源养护和管理规定。"},{"i":13,"n":"第十三条","txt":"在暂定措施水域和过渡水域从事渔业活动的我国渔船与韩国渔船发生渔事纠纷，或需到韩国港口紧急避难的，应按照《中韩渔业协定》及两国有关规定处理。"},{"i":14,"n":"第十四条","txt":"违反本办法的渔船，取消其当年或下一年度在暂定措施水域和过渡水域的作业资格，并按《中华人民共和国渔业法》和国家有关规定予以处罚。"},{"i":15,"n":"第十五条","txt":"《申请表》和《渔捞日志》由黄渤海区渔政渔港监督管理局根据本办法规定的格式统一印制。"},{"i":16,"n":"第十六条","txt":"本办法自《中韩渔业协定》生效之日起实施。有关过渡水域的规定，有效期为自协定生效之日起至满四年之日止。"},{"i":17,"n":"第十七条","txt":"本规定由农业部负责解释。"}],"zhuyaonongzuowupinzhongshendingbanfa":[{"i":1,"n":"第一条","txt":"为科学、公正、及时地审定主要农作物品种，根据《中华人民共和国种子法》（以下简称《种子法》），制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内的主要农作物品种审定，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称主要农作物，是指稻、小麦、玉米、棉花、大豆。"},{"i":4,"n":"第四条","txt":"省级以上人民政府农业农村主管部门应当采取措施，加强品种审定工作监督管理。省级人民政府农业农村主管部门应当完善品种选育、审定工作的区域协作机制，促进优良品种的选育和推广。"},{"i":5,"n":"第五条","txt":"农业农村部设立国家农作物品种审定委员会，负责国家级农作物品种审定工作。省级人民政府农业农村主管部门设立省级农作物品种审定委员会，负责省级农作物品种审定工作。 农作物品种审定委员会建立包括申请文件、品种审定试验数据、种子样品、审定意见和审定结论等内容的审定档案，保证可追溯。"},{"i":6,"n":"第六条","txt":"品种审定委员会由科研、教学、生产、推广、管理、使用等方面的专业人员组成。委员应当具有高级专业技术职称或处级以上职务，年龄一般在55岁以下。每届任期5年，连任不得超过两届。 品种审定委员会设主任1名，副主任2-5名。"},{"i":7,"n":"第七条","txt":"品种审定委员会设立办公室，负责品种审定委员会的日常工作，设主任1名，副主任1-2名。"},{"i":8,"n":"第八条","txt":"品种审定委员会按作物种类设立专业委员会，各专业委员会由9-23人的单数组成，设主任1名，副主任1-2名。 省级品种审定委员会对本辖区种植面积小的主要农作物，可以合并设立专业委员会。"},{"i":9,"n":"第九条","txt":"品种审定委员会设立主任委员会，由品种审定委员会主任和副主任、各专业委员会主任、办公室主任组成。"},{"i":10,"n":"第十条","txt":"申请品种审定的单位、个人（以下简称申请者），可以直接向国家农作物品种审定委员会或省级农作物品种审定委员会提出申请。 申请转基因主要农作物（不含棉花）品种审定的，应当直接向国家农作物品种审定委员会提出申请。 在中国境内没有经常居所或者营业场所的境外机构和个人在境内申请品种审定的，应当委托具有法人资格的境内种子企业代理。"},{"i":11,"n":"第十一条","txt":"申请者可以单独申请国家级审定或省级审定，也可以同时申请国家级审定和省级审定，还可以同时向几个省、自治区、直辖市申请审定。"},{"i":12,"n":"第十二条","txt":"申请审定的品种应当具备下列条件： （一）人工选育或发现并经过改良； （二）与现有品种（已审定通过或本级品种审定委员会已受理的其他品种）有明显区别； （三）形态特征和生物学特性一致； （四）遗传性状稳定； （五）具有符合《农业植物品种命名规定》的名称； （六）已完成同一生态类型区2个生产周期以上、多点的品种比较试验。其中，申请国家级品种审定的，稻、小麦、玉米品种比较试验每年不少于20个点，棉花、大豆品种比较试验每年不少于10个点，或具备省级品种审定试验结果报告；申请省级品种审定的，品种比较试验每年不少于5个点。"},{"i":13,"n":"第十三条","txt":"申请品种审定的，应当向品种审定委员会办公室提交以下材料： （一）申请表，包括作物种类和品种名称，申请者名称、地址、邮政编码、联系人、电话号码、传真、国籍，品种选育的单位或者个人（以下简称育种者）等内容； （二）品种选育报告，包括亲本组合以及杂交种的亲本血缘关系、选育方法、世代和特性描述；品种（含杂交种亲本）特征特性描述、标准图片，建议的试验区域和栽培要点；品种主要缺陷及应当注意的问题； （三）品种比较试验报告，包括试验品种、承担单位、抗性表现、品质、产量结果及各试验点数据、汇总结果等； （四）品种和申请材料真实性承诺书。 转基因主要农作物品种，除应当提交前款规定的材料外，还应当提供以下材料： （一）转化体相关信息，包括目的基因、转化体特异性检测方法； （二）转化体所有者许可协议； （三）依照《农业转基因生物安全管理条例》第十六条规定取得的农业转基因生物安全证书； （四）有检测条件和能力"},{"i":14,"n":"第十四条","txt":"品种审定委员会办公室在收到申请材料45日内作出受理或不予受理的决定，并书面通知申请者。 对于符合本办法第十二条、第十三条规定的，应当受理，并通知申请者在30日内提供试验种子。对于提供试验种子的，由办公室安排品种试验。逾期不提供试验种子的，视为撤回申请。 对于不符合本办法第十二条、第十三条规定的，不予受理。申请者可以在接到通知后30日内陈述意见或者对申请材料予以修正，逾期未陈述意见或者修正的，视为撤回申请；修正后仍然不符合规定的，驳回申请。"},{"i":15,"n":"第十五条","txt":"品种审定委员会办公室应当在申请者提供的试验种子中留取标准样品，交农业农村部指定的植物品种标准样品库保存。"},{"i":16,"n":"第十六条","txt":"品种试验包括以下内容： （一）区域试验； （二）生产试验； （三）品种特异性、一致性和稳定性测试（以下简称DUS测试）。"},{"i":17,"n":"第十七条","txt":"国家级品种区域试验、生产试验由全国农业技术推广服务中心组织实施，省级品种区域试验、生产试验由省级种子管理机构组织实施。 品种试验组织实施单位应当充分听取品种审定申请人和专家意见，合理设置试验组别，优化试验点布局，建立健全管理制度，科学制定试验实施方案，并向社会公布。"},{"i":18,"n":"第十八条","txt":"区域试验应当对品种丰产性、稳产性、适应性、抗逆性等进行鉴定，并进行品质分析、DNA指纹检测等。对非转基因品种进行转基因成分检测；对转基因品种进行转化体真实性检测，并对转基因目标性状与转化体特征特性一致性检测报告进行验证。 每一个品种的区域试验，试验时间不少于两个生产周期，田间试验设计采用随机区组或间比法排列。同一生态类型区试验点，国家级不少于10个，省级不少于5个。"},{"i":19,"n":"第十九条","txt":"生产试验在区域试验完成后，在同一生态类型区，按照当地主要生产方式，在接近大田生产条件下对品种的丰产性、稳产性、适应性、抗逆性等进一步验证。 每一个品种的生产试验点数量不少于区域试验点，每一个品种在一个试验点的种植面积不少于300平方米，不大于3000平方米，试验时间不少于一个生产周期。 第一个生产周期综合性状突出的品种，生产试验可与第二个生产周期的区域试验同步进行。"},{"i":20,"n":"第二十条","txt":"区域试验、生产试验对照品种应当是同一生态类型区同期生产上推广应用的已审定品种，具备良好的代表性。 对照品种由品种试验组织实施单位提出，品种审定委员会相关专业委员会确认，并根据农业生产发展的需要适时更换。 省级农作物品种审定委员会应当将省级区域试验、生产试验对照品种报国家农作物品种审定委员会备案。"},{"i":21,"n":"第二十一条","txt":"区域试验、生产试验、DUS测试承担单位应当具备独立法人资格，具有稳定的试验用地、仪器设备、技术人员。 品种试验技术人员应当具有相关专业大专以上学历或中级以上专业技术职称、品种试验相关工作经历,并定期接受相关技术培训。 抗逆性鉴定由品种审定委员会指定的鉴定机构承担，品质检测、DNA指纹检测、转基因检测由具有资质的检测机构承担。 品种试验、测试、鉴定承担单位与个人应当对数据的真实性负责。 转基因品种试验承担单位应当依照《农业转基因生物安全管理条例》及相关法律、行政法规和部门规章等的规定，采取相应的安全管理、防范措施。"},{"i":22,"n":"第二十二条","txt":"品种试验组织实施单位应当会同品种审定委员会办公室，定期组织开展品种试验考察，检查试验质量、鉴评试验品种表现，并形成考察报告，对田间表现出严重缺陷的品种保留现场图片资料。"},{"i":23,"n":"第二十三条","txt":"品种试验组织实施单位应当在每个生产周期结束后45日内召开品种试验总结会议。品种审定委员会专业委员会根据试验汇总结果、试验考察情况，确定品种是否终止试验、继续试验、提交审定，由品种审定委员会办公室将品种处理结果及时通知申请者。"},{"i":24,"n":"第二十四条","txt":"申请者具备试验能力并且试验品种是自有品种的，可以按照下列要求自行开展品种试验： （一）在国家级或省级品种区域试验基础上，自行开展生产试验； （二）自有品种属于特殊用途品种的，自行开展区域试验、生产试验，生产试验可与第二个生产周期区域试验合并进行。特殊用途品种的范围、试验要求由同级品种审定委员会确定； （三）申请者属于企业联合体、科企联合体和科研单位联合体的，组织开展相应区组的品种试验。联合体成员数量应当不少于5家，并且签订相关合作协议，按照同权同责原则，明确责任义务。一个法人单位在同一试验区组内只能参加一个试验联合体。 前款规定自行开展品种试验的实施方案应当在播种前30日内报国家级或省级品种试验组织实施单位，符合条件的纳入国家级或省级品种试验统一管理。"},{"i":25,"n":"第二十五条","txt":"申请审定的转基因品种，除目标性状外，其他特征特性与受体品种无变化，受体品种已通过审定且未撤销审定，按以下两种情形进行品种试验： （一）申请审定的适宜种植区域在受体品种适宜种植区域范围内，可简化试验程序，只需开展一年的生产试验； （二）申请审定的适宜种植区域不在受体品种适宜种植区域范围内的，应当开展两年区域试验、一年生产试验。 对于转育的新品种，应当开展两年区域试验、一年生产试验和DUS测试。"},{"i":26,"n":"第二十六条","txt":"DUS测试由申请者自主或委托农业农村部授权的测试机构开展，接受农业农村部科技发展中心指导。 申请者自主测试的，应当在播种前30日内，按照审定级别将测试方案报农业农村部科技发展中心或省级种子管理机构。农业农村部科技发展中心、省级种子管理机构分别对国家级审定、省级审定DUS测试过程进行监督检查，对样品和测试报告的真实性进行抽查验证。 DUS测试所选择近似品种应当为特征特性最为相似的品种，DUS测试依据相应主要农作物DUS测试指南进行。测试报告应当由法人代表或法人代表授权签字。"},{"i":27,"n":"第二十七条","txt":"符合农业农村部规定条件、获得选育生产经营相结合许可证的种子企业（以下简称育繁推一体化种子企业），对其自主研发的主要农作物非转基因品种可以在相应生态区自行开展品种试验，完成试验程序后提交申请材料。 试验实施方案应当在播种前30日内报国家级或省级品种试验组织实施单位备案。 育繁推一体化种子企业应当建立包括品种选育过程、试验实施方案、试验原始数据等相关信息的档案，并对试验数据的真实性负责，保证可追溯，接受省级以上人民政府农业农村主管部门和社会的监督。"},{"i":28,"n":"第二十八条","txt":"对于完成试验程序的品种，申请者、品种试验组织实施单位、育繁推一体化种子企业应当在2月底和9月底前分别将稻、玉米、棉花、大豆品种和小麦品种各试验点数据、汇总结果、DNA指纹检测报告、DUS测试报告、转化体真实性检测报告等提交品种审定委员会办公室。 品种审定委员会办公室在30日内提交品种审定委员会相关专业委员会初审，专业委员会应当在30日内完成初审。"},{"i":29,"n":"第二十九条","txt":"初审品种时，各专业委员会应当召开全体会议，到会委员达到该专业委员会委员总数三分之二以上的，会议有效。对品种的初审，根据审定标准，采用无记名投票表决，赞成票数达到该专业委员会委员总数二分之一以上的品种，通过初审。 专业委员会对育繁推一体化种子企业提交的品种试验数据等材料进行审核，达到审定标准的，通过初审。"},{"i":30,"n":"第三十条","txt":"初审实行回避制度。专业委员会主任的回避，由品种审定委员会办公室决定；其他委员的回避，由专业委员会主任决定。"},{"i":31,"n":"第三十一条","txt":"初审通过的品种，由品种审定委员会办公室在30日内将初审意见及各试点试验数据、汇总结果，在同级农业农村主管部门官方网站公示，公示期不少于30日。"},{"i":32,"n":"第三十二条","txt":"公示期满后，品种审定委员会办公室应当将初审意见、公示结果，提交品种审定委员会主任委员会审核。主任委员会应当在30日内完成审核。审核同意的，通过审定。 育繁推一体化种子企业自行开展自主研发品种试验，品种通过初审后，应当在公示期内将品种标准样品提交至农业农村部指定的植物品种标准样品库保存。"},{"i":33,"n":"第三十三条","txt":"审定通过的品种，由品种审定委员会编号、颁发证书，同级农业农村主管部门公告。 省级审定的农作物品种在公告前，应当由省级人民政府农业农村主管部门将品种名称等信息报农业农村部公示，公示期为15个工作日。"},{"i":34,"n":"第三十四条","txt":"审定编号为审定委员会简称、作物种类简称、年号、序号，其中序号为四位数。"},{"i":35,"n":"第三十五条","txt":"审定公告内容包括：审定编号、品种名称、申请者、育种者、品种来源、形态特征、生育期（组）、产量、品质、抗逆性、栽培技术要点、适宜种植区域及注意事项等。 转基因品种还应当包括转化体所有者、转化体名称、农业转基因生物安全证书编号、转基因目标性状等。 省级品种审定公告，应当在发布后30日内报国家农作物品种审定委员会备案。 审定公告公布的品种名称为该品种的通用名称。禁止在生产、经营、推广过程中擅自更改该品种的通用名称。"},{"i":36,"n":"第三十六条","txt":"审定证书内容包括：审定编号、品种名称、申请者、育种者、品种来源、审定意见、公告号、证书编号。 转基因品种还应当包括转化体所有者、转化体名称、农业转基因生物安全证书编号。"},{"i":37,"n":"第三十七条","txt":"审定未通过的品种，由品种审定委员会办公室在30日内书面通知申请者。申请者对审定结果有异议的，可以自接到通知之日起30日内，向原品种审定委员会或者国家级品种审定委员会申请复审。品种审定委员会应当在下一次审定会议期间对复审理由、原审定文件和原审定程序进行复审。对病虫害鉴定结果提出异议的，品种审定委员会认为有必要的，安排其他单位再次鉴定。 品种审定委员会办公室应当在复审后30日内将复审结果书面通知申请者。"},{"i":38,"n":"第三十八条","txt":"品种审定标准，由同级农作物品种审定委员会制定。审定标准应当有利于产量、品质、抗性等的提高与协调，有利于适应市场和生活消费需要的品种的推广。 省级品种审定标准，应当在发布后30日内报国家农作物品种审定委员会备案。 制定品种审定标准，应当公开征求意见。"},{"i":39,"n":"第三十九条","txt":"省级人民政府农业农村主管部门应当建立同一适宜生态区省际间品种试验数据共享互认机制，开展引种备案。"},{"i":40,"n":"第四十条","txt":"通过省级审定的品种，其他省、自治区、直辖市属于同一适宜生态区的地域引种的，引种者应当报所在省、自治区、直辖市人民政府农业农村主管部门备案。 备案时，引种者应当填写引种备案表，包括作物种类、品种名称、引种者名称、联系方式、审定品种适宜种植区域、拟引种区域等信息。"},{"i":41,"n":"第四十一条","txt":"引种者应当在拟引种区域开展不少于1年的适应性、抗病性试验，对品种的真实性、安全性和适应性负责。具有植物新品种权的品种，还应当经过品种权人的同意。"},{"i":42,"n":"第四十二条","txt":"省、自治区、直辖市人民政府农业农村主管部门及时发布引种备案公告，公告内容包括品种名称、引种者、育种者、审定编号、引种适宜种植区域等内容。公告号格式为：（X）引种〔X〕第X号，其中，第一个“X”为省、自治区、直辖市简称，第二个“X”为年号，第三个“X”为序号。"},{"i":43,"n":"第四十三条","txt":"国家审定品种同一适宜生态区，由国家农作物品种审定委员会确定。省级审定品种同一适宜生态区，由省级农作物品种审定委员会依据国家农作物品种审定委员会确定的同一适宜生态区具体确定。"},{"i":44,"n":"第四十四条","txt":"审定通过的品种，有下列情形之一的，应当撤销审定： （一）在使用过程中出现不可克服严重缺陷的； （二）种性严重退化或失去生产利用价值的； （三）未按要求提供品种标准样品或者标准样品不真实的； （四）以欺骗、伪造试验数据等不正当方式通过审定的； （五）农业转基因生物安全证书已过期的。"},{"i":45,"n":"第四十五条","txt":"拟撤销审定的品种，由品种审定委员会办公室在书面征求品种审定申请者意见后提出建议，经专业委员会初审后，在同级农业农村主管部门官方网站公示，公示期不少于30日。 公示期满后，品种审定委员会办公室应当将初审意见、公示结果，提交品种审定委员会主任委员会审核，主任委员会应当在30日内完成审核。审核同意撤销审定的，由同级农业农村主管部门予以公告。"},{"i":46,"n":"第四十六条","txt":"公告撤销审定的品种，自撤销审定公告发布之日起停止生产、广告，自撤销审定公告发布一个生产周期后停止推广、销售。品种审定委员会认为有必要的，可以决定自撤销审定公告发布之日起停止推广、销售。 省级品种撤销审定公告，应当在发布后30日内报国家农作物品种审定委员会备案。"},{"i":47,"n":"第四十七条","txt":"农业农村部建立全国农作物品种审定数据信息系统，实现国家和省两级品种试验与审定网上申请、受理、审核、发布，品种试验数据、审定通过品种、撤销审定品种、引种备案品种、标准样品、转化体等信息互联共享，审定证书网上统一打印。审定证书格式由国家农作物品种审定委员会统一制定。 省级以上人民政府农业农村主管部门应当在统一的政府信息发布平台上发布品种审定、撤销审定、引种备案、监督管理等信息，接受监督。"},{"i":48,"n":"第四十八条","txt":"品种试验、审定单位及工作人员，对在试验、审定过程中获知的申请者的商业秘密负有保密义务，不得对外提供申请品种审定的种子或者谋取非法利益。"},{"i":49,"n":"第四十九条","txt":"品种审定委员会委员和工作人员应当忠于职守，公正廉洁。品种审定委员会委员、工作人员不依法履行职责，弄虚作假、徇私舞弊的，依法给予处分；自处分决定作出之日起五年内不得从事品种审定工作。"},{"i":50,"n":"第五十条","txt":"申请者在申请品种审定过程中有欺骗、贿赂等不正当行为的，三年内不受理其申请。 联合体成员单位弄虚作假的，终止联合体品种试验审定程序；弄虚作假成员单位三年内不得申请品种审定，不得再参加联合体试验；其他成员单位应当承担连带责任，三年内不得参加其他联合体试验。"},{"i":51,"n":"第五十一条","txt":"品种测试、试验、鉴定机构伪造试验数据或者出具虚假证明的，按照《种子法》第七十二条及有关法律行政法规的规定进行处罚。"},{"i":52,"n":"第五十二条","txt":"育繁推一体化种子企业自行开展品种试验和申请审定有造假行为的，由省级以上人民政府农业农村主管部门处一百万元以上五百万元以下罚款；不得再自行开展品种试验；给种子使用者和其他种子生产经营者造成损失的，依法承担赔偿责任。"},{"i":53,"n":"第五十三条","txt":"农业农村部对省级人民政府农业农村主管部门的品种审定工作进行监督检查，未依法开展品种审定、引种备案、撤销审定的，责令限期改正，依法给予处分。"},{"i":54,"n":"第五十四条","txt":"违反本办法规定，构成犯罪的，依法追究刑事责任。"},{"i":55,"n":"第五十五条","txt":"农作物品种审定所需工作经费和品种试验经费，列入同级农业农村主管部门财政专项经费预算。"},{"i":56,"n":"第五十六条","txt":"育繁推一体化企业自行开展试验的品种和联合体组织开展试验的品种，不再参加国家级和省级试验组织实施单位组织的相应区组品种试验。"},{"i":57,"n":"第五十七条","txt":"本办法自2016年8月15日起施行，农业部2001年2月26日发布、2007年11月8日和2014年2月1日修订的《主要农作物品种审定办法》，以及2001年2月26日发布的《主要农作物范围规定》同时废止。"}],"youliangzhongchudengjiguize":[{"i":1,"n":"第一条","txt":"为了培育优良种畜，提高种畜遗传质量，向社会推荐优良种畜，根据《中华人民共和国畜牧法》的有关规定，制定本规则。"},{"i":2,"n":"第二条","txt":"本规则所称优良种畜，是指个体符合品种标准，综合鉴定等级为一级以上的种畜。"},{"i":3,"n":"第三条","txt":"农业部主管全国优良种畜登记管理工作。省级人民政府畜牧行政主管部门主管本行政区域内优良种畜登记管理工作。 全国畜牧总站组织开展全国性优良种畜登记。省级畜牧技术推广机构组织开展本行政区域内的优良种畜登记。 畜牧行业协会配合畜牧技术推广机构实施优良种畜登记工作。"},{"i":4,"n":"第四条","txt":"饲养《中国畜禽遗传资源目录》中牛、羊、猪、马、驴、骆驼、鹿、兔、犬等家畜的单位和个人，可以自愿申请优良种畜登记，任何机构不得强制。"},{"i":5,"n":"第五条","txt":"申请优良种畜登记的单位和个人应当符合下列条件： （一）取得种畜禽生产经营许可资格； （二）畜牧主管部门备案的养殖场或者养殖小区； （三）国家和省级畜禽遗传资源保护区内的养殖户； （四）其他符合条件的单位和个人。"},{"i":6,"n":"第六条","txt":"申请登记的种畜应当符合下列条件之一： （一）双亲已登记的纯种； （二）从国外引进已登记或者注册的原种； （三）三代系谱记录完整的个体； （四）其他符合优良种畜条件的个体。"},{"i":7,"n":"第七条","txt":"申请优良种畜登记的单位和个人，应当向省级以上畜牧技术推广机构（以下简称登记机构）报送下列材料： （一）申请表； （二）申请报告和种畜系谱等资料； （三）种畜照片； （四）《种畜禽生产经营许可证》复印件。"},{"i":8,"n":"第八条","txt":"登记机构应当自收到申请之日起30个工作日内完成审定，必要时可以组织现场审验或者技术检测。 通过审定的，予以登记公告，并由登记机构发放优良种畜证书；未通过审定的，登记机构应当书面通知申请人，并说明理由。"},{"i":9,"n":"第九条","txt":"优良种畜登记实行一畜一卡，记录内容包括： （一）基本情况：场（小区、站、户）名、品种、类型、个体编号、出生日期、 出生地、综合鉴（评）定等级、登记时间、登记人等基础信息； （二）系谱档案：三代系谱完整，并具有父本母本生产性能或遗传力评估的完整资料； （三）外貌特征：种畜头部正面及左、右体侧照片各一张； （四）生产性能：按各畜种登记卡的内容进行登记； （五）优良种畜转让、出售、死亡、淘汰等情况。"},{"i":10,"n":"第十条","txt":"优良种畜登记卡由专人负责填写和管理，登记信息应当录入计算机管理系统，不得随意涂改。 优良种畜登记卡等书面信息资料，至少保存5年；电子信息资料应当长期保存。"},{"i":11,"n":"第十一条","txt":"登记的优良种畜淘汰、死亡的，畜主应当在30日内向登记机构报告。 登记的优良种畜转让、出售的，应当附优良种畜登记卡等相关资料，并办理变更手续。"},{"i":12,"n":"第十二条","txt":"申请单位和个人以欺诈、贿赂等手段骗取登记的，撤销优良种畜登记。 已登记的种畜不再符合规定条件的，注销优良种畜登记。"},{"i":13,"n":"第十三条","txt":"登记机构及其工作人员弄虚作假、玩忽职守造成后果的，依法给予处分；造成损失的，依法承担赔偿责任。"},{"i":14,"n":"第十四条","txt":"本规则自2006年7月1日起施行。"}],"guanyushishiqingliqudisanwuchuanbotonggaoyouguansh34c7c0":[],"guanyujinzhizaigonghaishiyongdaxingliuwangzuoyedet0de8bf":[],"shouyongchufangyaohefeichufangyaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强兽药监督管理，促进兽医临床合理用药，保障动物产品安全，根据《兽药管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"国家对兽药实行分类管理，根据兽药的安全性和使用风险程度，将兽药分为兽用处方药和非处方药。 兽用处方药是指凭兽医处方笺方可购买和使用的兽药。 兽用非处方药是指不需要兽医处方笺即可自行购买并按照说明书使用的兽药。 兽用处方药目录由农业部制定并公布。兽用处方药目录以外的兽药为兽用非处方药。"},{"i":3,"n":"第三条","txt":"农业部主管全国兽用处方药和非处方药管理工作。 县级以上地方人民政府兽医行政管理部门负责本行政区域内兽用处方药和非处方药的监督管理，具体工作可以委托所属执法机构承担。"},{"i":4,"n":"第四条","txt":"兽用处方药的标签和说明书应当标注“兽用处方药”字样，兽用非处方药的标签和说明书应当标注“兽用非处方药”字样。 前款字样应当在标签和说明书的右上角以宋体红色标注，背景应当为白色，字体大小根据实际需要设定，但必须醒目、清晰。"},{"i":5,"n":"第五条","txt":"兽药生产企业应当跟踪本企业所生产兽药的安全性和有效性，发现不适合按兽用非处方药管理的，应当及时向农业部报告。 兽药经营者、动物诊疗机构、行业协会或者其他组织和个人发现兽用非处方药有前款规定情形的，应当向当地兽医行政管理部门报告。"},{"i":6,"n":"第六条","txt":"兽药经营者应当在经营场所显著位置悬挂或者张贴“兽用处方药必须凭兽医处方购买”的提示语。 兽药经营者对兽用处方药、兽用非处方药应当分区或分柜摆放。兽用处方药不得采用开架自选方式销售。"},{"i":7,"n":"第七条","txt":"兽用处方药凭兽医处方笺方可买卖，但下列情形除外： （一）进出口兽用处方药的； （二）向动物诊疗机构、科研单位、动物疫病预防控制机构和其他兽药生产企业、经营者销售兽用处方药的； （三）向聘有依照《执业兽医管理办法》规定注册的专职执业兽医的动物饲养场（养殖小区）、动物园、实验动物饲育场等销售兽用处方药的。"},{"i":8,"n":"第八条","txt":"兽医处方笺由依法注册的执业兽医按照其注册的执业范围开具。"},{"i":9,"n":"第九条","txt":"兽医处方笺应当记载下列事项： （一）畜主姓名或动物饲养场名称； （二）动物种类、年（日）龄、体重及数量； （三）诊断结果； （四）兽药通用名称、规格、数量、用法、用量及休药期； （五）开具处方日期及开具处方执业兽医注册号和签章。 处方笺一式三联，第一联由开具处方药的动物诊疗机构或执业兽医保存，第二联由兽药经营者保存，第三联由畜主或动物饲养场保存。动物饲养场（养殖小区）、动物园、实验动物饲育场等单位专职执业兽医开具的处方签由专职执业兽医所在单位保存。 处方笺应当保存二年以上。"},{"i":10,"n":"第十条","txt":"兽药经营者应当对兽医处方笺进行查验，单独建立兽用处方药的购销记录，并保存二年以上。"},{"i":11,"n":"第十一条","txt":"兽用处方药应当依照处方笺所载事项使用。"},{"i":12,"n":"第十二条","txt":"乡村兽医应当按照农业部制定、公布的《乡村兽医基本用药目录》使用兽药。"},{"i":13,"n":"第十三条","txt":"兽用麻醉药品、精神药品、毒性药品等特殊药品的生产、销售和使用，还应当遵守国家有关规定。"},{"i":14,"n":"第十四条","txt":"违反本办法第四条规定的，依照《兽药管理条例》第六十条第二款的规定进行处罚。"},{"i":15,"n":"第十五条","txt":"违反本办法规定，未经注册执业兽医开具处方销售、购买、使用兽用处方药的，依照《兽药管理条例》第六十六条的规定进行处罚。"},{"i":16,"n":"第十六条","txt":"违反本办法规定，有下列情形之一的，依照《兽药管理条例》第五十九条第一款的规定进行处罚： （一）兽药经营者未在经营场所明显位置悬挂或者张贴提示语的； （二）兽用处方药与兽用非处方药未分区或分柜摆放的； （三）兽用处方药采用开架自选方式销售的； （四）兽医处方笺和兽用处方药购销记录未按规定保存的。"},{"i":17,"n":"第十七条","txt":"违反本办法其他规定的，依照《中华人民共和国动物防疫法》、《兽药管理条例》有关规定进行处罚。"},{"i":18,"n":"第十八条","txt":"本办法自2014年3月1日起施行。"}],"shouyongannakaguanliguiding":[],"shouyongshengwuzhipinjingyingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强兽用生物制品经营管理，保证兽用生物制品质量，根据《兽药管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事兽用生物制品的分发、经营和监督管理，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称兽用生物制品，是指以天然或者人工改造的微生物、寄生虫、生物毒素或者生物组织及代谢产物等为材料，采用生物学、分子生物学或者生物化学、生物工程等相应技术制成的，用于预防、治疗、诊断动物疫病或者有目的地调节动物生理机能的兽药，主要包括血清制品、疫苗、诊断制品和微生态制品等。"},{"i":4,"n":"第四条","txt":"兽用生物制品分为国家强制免疫计划所需兽用生物制品（以下简称国家强制免疫用生物制品）和非国家强制免疫计划所需兽用生物制品（以下简称非国家强制免疫用生物制品）。 国家强制免疫用生物制品品种名录由农业农村部确定并公布。非国家强制免疫用生物制品是指农业农村部确定的强制免疫用生物制品以外的兽用生物制品。"},{"i":5,"n":"第五条","txt":"农业农村部负责全国兽用生物制品的监督管理工作。县级以上地方人民政府畜牧兽医主管部门负责本行政区域内兽用生物制品的监督管理工作。"},{"i":6,"n":"第六条","txt":"兽用生物制品生产企业可以将本企业生产的兽用生物制品销售给各级人民政府畜牧兽医主管部门或养殖场（户）、动物诊疗机构等使用者，也可以委托经销商销售。 发生重大动物疫情、灾情或者其他突发事件时，根据工作需要，国家强制免疫用生物制品由农业农村部统一调用，生产企业不得自行销售。"},{"i":7,"n":"第七条","txt":"从事兽用生物制品经营的企业，应当依法取得《兽药经营许可证》。《兽药经营许可证》的经营范围应当具体载明国家强制免疫用生物制品、非国家强制免疫用生物制品等产品类别和委托的兽用生物制品生产企业名称。经营范围发生变化的，应当办理变更手续。"},{"i":8,"n":"第八条","txt":"兽用生物制品生产企业可自主确定、调整经销商，并与经销商签订销售代理合同，明确代理范围等事项。 经销商只能经营所代理兽用生物制品生产企业生产的兽用生物制品，不得经营未经委托的其他企业生产的兽用生物制品。经销商可以将所代理的产品销售给使用者和获得生产企业委托的其他经销商。"},{"i":9,"n":"第九条","txt":"省级人民政府畜牧兽医主管部门对国家强制免疫用生物制品可以依法组织实行政府采购、分发。 承担国家强制免疫用生物制品政府采购、分发任务的单位，应当建立国家强制免疫用生物制品贮存、运输、分发等管理制度，建立真实、完整的分发和冷链运输记录，记录应当保存至制品有效期满2年后。"},{"i":10,"n":"第十条","txt":"向国家强制免疫用生物制品生产企业或其委托的经销商采购自用的国家强制免疫用生物制品的养殖场（户），在申请强制免疫补助经费时，应当按要求将采购的品种、数量、生产企业及经销商等信息提供给所在地县级地方人民政府畜牧兽医主管部门。 养殖场（户）应当建立真实、完整的采购、贮存、使用记录，并保存至制品有效期满2年后。"},{"i":11,"n":"第十一条","txt":"兽用生物制品生产、经营企业应当遵守兽药生产质量管理规范和兽药经营质量管理规范各项规定，建立真实、完整的贮存、销售、冷链运输记录，经营企业还应当建立真实、完整的采购记录。贮存记录应当每日记录贮存设施设备温度；销售记录和采购记录应当载明产品名称、产品批号、产品规格、产品数量、生产日期、有效期、供货单位或收货单位和地址、发货日期等内容；冷链运输记录应当记录起运和到达时的温度。"},{"i":12,"n":"第十二条","txt":"兽用生物制品生产、经营企业自行配送兽用生物制品的，应当具备相应的冷链贮存、运输条件，也可以委托具备相应冷链贮存、运输条件的配送单位配送，并对委托配送的产品质量负责。冷链贮存、运输全过程应当处于规定的贮藏温度环境下。"},{"i":13,"n":"第十三条","txt":"兽用生物制品生产、经营企业以及承担国家强制免疫用生物制品政府采购、分发任务的单位，应当按照兽药产品追溯要求及时、准确、完整地上传制品入库、出库追溯数据至国家兽药追溯系统。"},{"i":14,"n":"第十四条","txt":"县级以上地方人民政府畜牧兽医主管部门应当依法加强对兽用生物制品生产、经营企业和使用者监督检查，发现有违反《兽药管理条例》和本办法规定情形的，应当依法做出处理决定或者报告上级畜牧兽医主管部门。"},{"i":15,"n":"第十五条","txt":"各级畜牧兽医主管部门、兽药检验机构、动物卫生监督机构、动物疫病预防控制机构及其工作人员，不得参与兽用生物制品生产、经营活动，不得以其名义推荐或者监制、监销兽用生物制品和进行广告宣传。"},{"i":16,"n":"第十六条","txt":"养殖场（户）、动物诊疗机构等使用者采购的或者经政府分发获得的兽用生物制品只限自用，不得转手销售。 养殖场（户）、动物诊疗机构等使用者转手销售兽用生物制品的，或者兽用生物制品经营企业超出《兽药经营许可证》载明的经营范围经营兽用生物制品的，属于无证经营，按照《兽药管理条例》第五十六条的规定处罚；属于国家强制免疫用生物制品的，依法从重处罚。"},{"i":17,"n":"第十七条","txt":"兽用生物制品生产、经营企业未按照要求实施兽药产品追溯，以及未按照要求建立真实、完整的贮存、销售、冷链运输记录或未实施冷链贮存、运输的，按照《兽药管理条例》第五十九条的规定处罚。"},{"i":18,"n":"第十八条","txt":"进口兽用生物制品的经营管理，还应当适用《兽药进口管理办法》。"},{"i":19,"n":"第十九条","txt":"本办法自2021年5月15日起施行。农业部2007年3月29日发布的《兽用生物制品经营管理办法》（农业部令第3号）同时废止。"}],"shouyongmazuiyaopindegongyingshiyongguanlibanfa":[],"shouyaochanpinpizhunwenhaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强兽药产品批准文号的管理，根据《兽药管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"兽药产品批准文号的申请、核发和监督管理适用本办法。"},{"i":3,"n":"第三条","txt":"兽药生产企业生产兽药，应当取得农业农村部核发的兽药产品批准文号。 兽药产品批准文号是农业农村部根据兽药国家标准、生产工艺和生产条件批准特定兽药生产企业生产特定兽药产品时核发的兽药批准证明文件。"},{"i":4,"n":"第四条","txt":"农业农村部负责全国兽药产品批准文号的核发和监督管理工作。 县级以上地方人民政府兽医主管部门负责本行政区域内的兽药产品批准文号的监督管理工作。"},{"i":5,"n":"第五条","txt":"申请兽药产品批准文号的兽药，应当符合以下条件： （一）在《兽药生产许可证》载明的生产范围内； （二）申请前三年内无被撤销该产品批准文号的记录。 申请兽药产品批准文号连续2次复核检验结果不符合规定的，1年内不再受理该兽药产品批准文号的申请。"},{"i":6,"n":"第六条","txt":"申请本企业研制的已获得《新兽药注册证书》的兽药产品批准文号，且新兽药注册时的复核样品系申请人生产的，申请人应当向农业农村部提交下列资料： （一）《兽药产品批准文号申请表》一式一份； （二）《新兽药注册证书》复印件一式一份； （三）复核检验报告复印件一式一份； （四）标签和说明书样本一式二份； （五）产品的生产工艺、配方等资料一式一份。 农业农村部自受理之日起5个工作日内将申请资料送中国兽医药品监察所进行专家评审，并自收到评审意见之日起15个工作日内作出审批决定。符合规定的，核发兽药产品批准文号，批准标签和说明书；不符合规定的，书面通知申请人，并说明理由。 申请本企业研制的已获得《新兽药注册证书》的兽药产品批准文号，但新兽药注册时的复核样品非申请人生产的，分别按照本办法第七条、第九条规定办理，申请人无需提交知识产权转让合同或授权书复印件。"},{"i":7,"n":"第七条","txt":"申请他人转让的已获得《新兽药注册证书》或《进口兽药注册证书》的生物制品类兽药产品批准文号的，申请人应当向农业农村部提交本企业生产的连续三个批次的样品和下列资料： （一）《兽药产品批准文号申请表》一式一份； （二）《新兽药注册证书》复印件一式一份； （三） 标签和说明书样本一式二份； （四）所提交样品的自检报告一式一份； （五）产品的生产工艺、配方等资料一式一份； （六）知识产权转让合同或授权书一式一份（首次申请提供原件，换发申请提供复印件并加盖申请人公章）。 提交的样品应当由省级兽药检验机构现场抽取，并加贴封签。 农业农村部自受理之日起5个工作日内将样品及申请资料送中国兽医药品监察所按规定进行复核检验和专家评审，并自收到检验结论和评审意见之日起15个工作日内作出审批决定。符合规定的，核发兽药产品批准文号，批准标签和说明书；不符合规定的，书面通知申请人，并说明理由。"},{"i":8,"n":"第八条","txt":"申请第六条、第七条规定之外的生物制品类兽药产品批准文号的，申请人应当向农业农村部提交本企业生产的连续三个批次的样品和下列资料： （一）《兽药产品批准文号申请表》一式一份； （二）标签和说明书样本一式二份； （三）所提交样品的自检报告一式一份； （四）产品的生产工艺、配方等资料一式一份； （五）菌（毒、虫）种合法来源证明复印件（加盖申请人公章）一式一份。 提交的样品应当由省级兽药检验机构现场抽取，并加贴封签。 农业农村部自受理之日起5个工作日内将样品及申请资料送中国兽医药品监察所按规定进行复核检验和专家评审，并自收到检验结论和评审意见之日起15个工作日内作出审批决定。符合规定的，核发兽药产品批准文号，批准标签和说明书；不符合规定的，书面通知申请人，并说明理由。"},{"i":9,"n":"第九条","txt":"申请他人转让的已获得《新兽药注册证书》或《进口兽药注册证书》的非生物制品类的兽药产品批准文号的，申请人应当向所在地省级人民政府兽医主管部门提交本企业生产的连续三个批次的样品和下列资料： （一）《兽药产品批准文号申请表》一式二份； （二）《新兽药注册证书》复印件一式二份； （三）标签和说明书样本一式二份； （四）所提交样品的批生产、批检验原始记录复印件及自检报告一式二份； （五）产品的生产工艺、配方等资料一式二份； （六）知识产权转让合同或授权书一式二份（首次申请提供原件，换发申请提供复印件并加盖申请人公章）。 省级人民政府兽医主管部门自收到有关资料和样品之日起5个工作日内将样品送省级兽药检验机构进行复核检验，并自收到复核检验结论之日起10个工作日内完成初步审查，将审查意见和复核检验报告及全部申请材料一式一份报送农业农村部。 农业农村部自收到省级人民政府兽医主管部门审查意见之日起5个工作"},{"i":10,"n":"第十条","txt":"申请第六条、第九条规定之外的非生物制品类兽药产品批准文号的，农业农村部逐步实行比对试验管理。 实行比对试验管理的兽药品种目录及比对试验的要求由农业农村部制定。开展比对试验的检验机构应当遵守兽药非临床研究质量管理规范和兽药临床试验质量管理规范，其名单由农业农村部公布。"},{"i":11,"n":"第十一条","txt":"第十条规定的兽药尚未列入比对试验品种目录的，申请人应当向所在地省级人民政府兽医主管部门提交下列资料： （一）《兽药产品批准文号申请表》一式二份； （二）标签和说明书样本一式二份； （三）产品的生产工艺、配方等资料一式二份； （四）《现场核查申请单》一式二份。 省级人民政府兽医主管部门应当自收到有关资料之日起5个工作日内组织对申请资料进行审查。符合规定的，应当与申请人商定现场核查时间，并自商定的现场核查日期起5个工作日内组织完成现场核查；核查结果符合要求的，当场抽取三批样品，加贴封签后送省级兽药检验机构进行复核检验。 省级人民政府兽医主管部门自资料审查、现场核查或复核检验完成之日起10个工作日内将上述有关审查意见、复核检验报告及全部申请材料一式一份报送农业农村部。 农业农村部自收到省级人民政府兽医主管部门审查意见之日起5个工作日内，将申请资料送中国兽医药品监察所进行专家评审，并自收到评审"},{"i":12,"n":"第十二条","txt":"第十条规定的兽药已列入比对试验品种目录的，按照第十一条规定提交申请资料、进行现场核查、抽样和复核检验，但抽取的三批样品中应当有一批在线抽样。 省级人民政府兽医主管部门自收到复核检验结论之日起10个工作日内完成初步审查。通过初步审查的，通知申请人将相关药学研究资料及加贴封签的在线抽样样品送至其自主选定的比对试验机构。比对试验机构应当严格按照药物比对试验指导原则开展比对试验，并将比对试验报告分送省级人民政府兽医主管部门和申请人。 省级人民政府兽医主管部门将现场核查报告、复核检验报告、比对试验方案、比对试验协议、比对试验报告、相关药学研究资料及全部申请资料一式一份报农业农村部。 农业农村部自收到申请资料之日起5个工作日内送中国兽医药品监察所进行专家评审，并自收到评审意见之日起10个工作日内作出审批决定。符合规定的，核发兽药产品批准文号，批准标签和说明书；不符合规定的，书面通知申请人，并说明理"},{"i":13,"n":"第十三条","txt":"资料审查、现场核查、复核检验或比对试验不符合要求的，省级人民政府兽医主管部门可根据申请人意愿将申请资料退回申请人。"},{"i":14,"n":"第十四条","txt":"实行比对试验管理的兽药品种目录发布前已获得兽药产品批准文号的兽药，应当在规定期限内按照本办法第十二条规定补充比对试验并提供相关材料，未在规定期限内通过审查的，依照《兽药管理条例》第六十九条第一款第二项规定撤销该产品批准文号。"},{"i":15,"n":"第十五条","txt":"农业农村部在核发新兽药的兽药产品批准文号时，可以设立不超过5年的监测期。在监测期内，不批准其他企业生产或者进口该新兽药。 生产企业应当在监测期内收集该新兽药的疗效、不良反应等资料，并及时报送农业农村部。 兽药监测期届满后，其他兽药生产企业可根据本办法第七、九或十二条的规定申请兽药产品批准文号，但应当提交与知识产权人签订的转让合同或授权书，或者对他人专利权不构成侵权的声明。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，兽药生产企业应当按照本办法第八条或第十一条规定重新申请兽药产品批准文号，兽药产品已进行过比对试验且结果符合规定的，不再进行比对试验： （一）迁址重建的； （二）异地新建车间的； （三）其他改变生产场地的情形。"},{"i":17,"n":"第十七条","txt":"兽药产品批准文号有效期届满需要继续生产的，兽药生产企业应当在有效期届满前6个月内按原批准程序申请兽药产品批准文号的换发。 同一兽药生产许可证下同一生产地址原生产车间生产的兽药产品申请批准文号换发，在兽药产品批准文号有效期内，经省级以上人民政府兽医主管部门监督抽检不合格1批次以上的，应当进行复核检验，其他情形不需要进行复核检验。 已进行过比对试验且结果符合规定的兽药产品，兽药产品批准文号换发时不再进行比对试验。"},{"i":18,"n":"第十八条","txt":"对有证据表明存在安全性隐患的兽药产品，农业农村部暂停受理该兽药产品批准文号的申请；已受理的，中止该兽药产品批准文号的核发。"},{"i":19,"n":"第十九条","txt":"对国内突发重大动物疫病防控急需的兽药产品，必要时农业农村部可以核发临时兽药产品批准文号。 临时兽药产品批准文号有效期不超过2年。"},{"i":20,"n":"第二十条","txt":"兽药检验机构应当自收到样品之日起90个工作日内完成检验，对样品应当根据规定留样观察。样品属于生物制品的，检验期限不得超过120个工作日。 中国兽医药品监察所专家评审时限不得超过30个工作日；实行比对试验的，专家评审时限不得超过90个工作日。"},{"i":21,"n":"第二十一条","txt":"省级人民政府兽医主管部门负责组织现场核查和抽样工作，应当根据工作需要成立2-4人组成的现场核查抽样组。"},{"i":22,"n":"第二十二条","txt":"现场核查抽样人员进行现场抽样，应当按照兽药抽样相关规定进行，保证抽样的科学性和公正性。 样品应当按检验用量和比对试验方案载明数量的3-5倍抽取，并单独封签。《兽药封签》由抽样人员和被抽样单位有关人员签名，并加盖抽样单位兽药检验抽样专用章和被抽样单位公章。"},{"i":23,"n":"第二十三条","txt":"现场核查应当包括以下内容： （一）管理制度制定与执行情况； （二）研制、生产、检验人员相关情况； （三）原料购进和使用情况； （四）研制、生产、检验设备和仪器状况是否符合要求； （五）研制、生产、检验条件是否符合有关要求； （六）相关生产、检验记录； （七）其他需要现场核查的内容。 现场核查人员可以对研制、生产、检验现场场地、设备、仪器情况和原料、中间体、成品、研制记录等照相或者复制，作为现场核查报告的附件。"},{"i":24,"n":"第二十四条","txt":"县级以上地方人民政府兽医主管部门应当对辖区内兽药生产企业进行现场检查。 现场检查中，发现兽药生产企业有下列情形之一的，由县级以上地方人民政府兽医主管部门依法作出处理决定，应当撤销、吊销、注销兽药产品批准文号或者兽药生产许可证的，及时报发证机关处理： （一）生产条件发生重大变化的； （二）没有按照《兽药生产质量管理规范》的要求组织生产的； （三）产品质量存在隐患的； （四）其他违反《兽药管理条例》及本办法规定情形的。"},{"i":25,"n":"第二十五条","txt":"县级以上地方人民政府兽医主管部门应当对上市兽药产品进行监督检查，发现有违反本办法规定情形的，依法作出处理决定，应当撤销、吊销、注销兽药产品批准文号或者兽药生产许可证的，及时报发证机关处理。"},{"i":26,"n":"第二十六条","txt":"买卖、出租、出借兽药产品批准文号的，按照《兽药管理条例》第五十八条规定处罚。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一的，由农业农村部注销兽药产品批准文号，并予以公告： （一）兽药生产许可证有效期届满未申请延续或者申请后未获得批准的； （二）兽药生产企业停止生产超过6个月或者关闭的； （三）核发兽药产品批准文号所依据的兽药国家质量标准被废止的； （四）应当注销的其他情形。"},{"i":28,"n":"第二十八条","txt":"生产的兽药有下列情形之一的，按照《兽药管理条例》第六十九条第一款第二项的规定撤销兽药产品批准文号： （一）改变组方添加其他成分的； （二）除生物制品以及未规定上限的中药类产品外，主要成分含量在兽药国家标准150%以上，或主要成分含量在兽药国家标准120%以上且累计2批次的； （三）主要成分含量在兽药国家标准50%以下，或主要成分含量在兽药国家标准80%以下且累计2批次以上的； （四）其他药效不确定、不良反应大以及可能对养殖业、人体健康造成危害或者存在潜在风险的情形。"},{"i":29,"n":"第二十九条","txt":"申请人隐瞒有关情况或者提供虚假材料、样品申请兽药产品批准文号的，农业农村部不予受理或者不予核发兽药产品批准文号；申请人1年内不得再次申请该兽药产品批准文号。"},{"i":30,"n":"第三十条","txt":"申请人提供虚假资料、样品或者采取其他欺骗手段取得兽药产品批准文号的，根据《兽药管理条例》第五十七条的规定予以处罚，申请人3年内不得再次申请该兽药产品批准文号。"},{"i":31,"n":"第三十一条","txt":"发生兽药知识产权纠纷的，由当事人按照有关知识产权法律法规解决。知识产权管理部门生效决定或人民法院生效判决认定侵权行为成立的，由农业农村部依法注销已核发的兽药产品批准文号。"},{"i":32,"n":"第三十二条","txt":"兽药产品批准文号的编制格式为兽药类别简称＋企业所在地省（自治区、直辖市）序号＋企业序号＋兽药品种编号。 格式如下： （一）兽药类别简称。药物饲料添加剂的类别简称为“兽药添字”；血清制品、疫苗、诊断制品、微生态制品等类别简称为“兽药生字”；中药材、中成药、化学药品、抗生素、生化药品、放射性药品、外用杀虫剂和消毒剂等类别简称为“兽药字”；原料药简称为“兽药原字”；农业农村部核发的临时兽药产品批准文号简称为“兽药临字”。 （二）企业所在地省（自治区、直辖市）序号用2位阿拉伯数字表示，由农业农村部规定并公告。 （三）企业序号按省排序，用3位阿拉伯数字表示，由省级人民政府兽医主管部门发布。 （四）兽药品种编号用4位阿拉伯数字表示，由农业农村部规定并公告。"},{"i":33,"n":"第三十三条","txt":"本办法自2016年5月1日起施行，2004年11月24日农业部公布的《兽药产品批准文号管理办法》（农业部令第45号）同时废止。"}],"shouyaobiaoqianheshuomingshuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强兽药监督管理，规范兽药标签和说明书的内容、印制、使用活动，保障兽药使用的安全有效，根据《兽药管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"农业部主管全国的兽药标签和说明书的管理工作，县级以上地方人民政府畜牧兽医行政管理部门主管所辖地区的兽药标签和说明书的管理工作。"},{"i":3,"n":"第三条","txt":"凡在中国境内生产、经营、使用的兽药的标签和说明书必须符合本办法的规定。"},{"i":4,"n":"第四条","txt":"兽药产品（原料药除外）必须同时使用内包装标签和外包装标签。"},{"i":5,"n":"第五条","txt":"内包装标签必须注明兽用标识、兽药名称、适应症（或功能与主治）、含量/包装规格、批准文号或《进口兽药登记许可证》证号、生产日期、生产批号、有效期、生产企业信息等内容。 安瓿、西林瓶等注射或内服产品由于包装尺寸的限制而无法注明上述全部内容的，可适当减少项目，但至少须标明兽药名称、含量规格、生产批号。"},{"i":6,"n":"第六条","txt":"外包装标签必须注明兽用标识、兽药名称、主要成分、适应症（或功能与主治）、用法与用量、含量/包装规格、批准文号或《进口兽药登记许可证》证号、生产日期、生产批号、有效期、停药期、贮藏、包装数量、生产企业信息等内容。"},{"i":7,"n":"第七条","txt":"兽用原料药的标签必须注明兽药名称、包装规格、生产批号、生产日期、有效期、贮藏、批准文号、运输注意事项或其它标记、生产企业信息等内容。"},{"i":8,"n":"第八条","txt":"对贮藏有特殊要求的必须在标签的醒目位置标明。"},{"i":9,"n":"第九条","txt":"兽药有效期按年月顺序标注。年份用四位数表示，月份用两位数表示，如“有效期至2002年09月”，或“有效期至2002．09”。"},{"i":10,"n":"第十条","txt":"兽用化学药品、抗生素产品的单方、复方及中西复方制剂的说明书必须注明以下内容：兽用标识、兽药名称、主要成分、性状、药理作用、适应症（或功能与主治）、用法与用量、不良反应、注意事项、停药期、外用杀虫药及其他对人体或环境有毒有害的废弃包装的处理措施、有效期、含量/包装规格、贮藏、批准文号、生产企业信息等。"},{"i":11,"n":"第十一条","txt":"中兽药说明书必须注明以下内容：兽用标识、兽药名称、主要成分、性状、功能与主治、用法与用量、不良反应、注意事项、有效期、规格、贮藏、批准文号、生产企业信息等。"},{"i":12,"n":"第十二条","txt":"兽用生物制品说明书必须注明以下内容：兽用标识、兽药名称、主要成分及含量（型、株及活疫苗的最低活菌数或病毒滴度）、性状、接种对象、用法与用量（冻干疫苗须标明稀释方法）、注意事项（包括不良反应与急救措施）、有效期、规格（容量和头份）、包装、贮藏、废弃包装处理措施、批准文号、生产企业信息等。"},{"i":13,"n":"第十三条","txt":"兽药标签和说明书应当经农业部批准后方可使用。农业部制定兽药标签和说明书编写细则、范本，作为兽药标签和说明书编制、审批和监督执法的依据。"},{"i":14,"n":"第十四条","txt":"兽药标签和说明书必须按照本规定的统一要求印制，其文字及图案不得擅自加入任何未经批准的内容。"},{"i":15,"n":"第十五条","txt":"兽药标签和说明书的内容必须真实、准确，不得虚假和夸大，也不得印有任何带有宣传、广告色彩的文字和标识。"},{"i":16,"n":"第十六条","txt":"兽药标签和说明书的内容不得超出或删减规定的项目内容；不得印有未获批准的专利、兽药GMP、商标等标识。"},{"i":17,"n":"第十七条","txt":"兽药标签和说明书所用文字必须是中文，并使用国家语言文字工作委员会公布的现行规范化汉字。根据需要可有外文对照。"},{"i":18,"n":"第十八条","txt":"兽药标签或最小销售包装上应当按照农业部的规定印制兽药产品电子追溯码，电子追溯码以二维码标注；已获批准的专利产品，可标注专利标记和专利号，并标明专利许可种类；注册商标应印制在标签和说明书的左上角或右上角；已获兽药GMP合格证的，必须按照兽药GMP标识使用有关规定正确地使用兽药GMP标识。"},{"i":19,"n":"第十九条","txt":"兽药标签和说明书的字迹必须清晰易辨，兽用标识及外用药标识应清楚醒目，不得有印字脱落或粘贴不牢等现象，并不得用粘贴、剪切的方式进行修改或补充。"},{"i":20,"n":"第二十条","txt":"兽药标签和说明书内容对产品作用与用途项目的表述不得违反法定兽药标准的规定，并不得有扩大疗效和应用范围的内容；其用法与用量、停药期、有效期等项目内容必须与法定兽药标准一致，并使用符合兽药国家标准要求的规范性用语。"},{"i":21,"n":"第二十一条","txt":"兽药标签和说明书上必须标识兽药通用名称，可同时标识商品名称。商品名称不得与通用名称连写，两者之间应有一定空隙并分行。通用名称与商品名称用字的比例不得小于1：2（指面积），并不得小于注册商标用字。"},{"i":22,"n":"第二十二条","txt":"兽药最小销售单元的包装必须印有或贴有符合外包装标签规定内容的标签并附有说明书。兽药外包装箱上必须印有或粘贴有外包装标签。"},{"i":23,"n":"第二十三条","txt":"凡违反本办法规定的，按照《兽药管理条例》有关规定进行处罚。兽药产品标签未按要求使用电子追溯码的，按照《兽药管理条例》第六十条第二款处罚。"},{"i":24,"n":"第二十四条","txt":"本办法下列用语的含义是： 兽药通用名：国家标准、农业部行业标准、地方标准及进口兽药注册的正式品名。 兽药商品名：系指某一兽药产品的专有商品名称。 内包装标签：系指直接接触兽药的包装上的标签。 外包装标签：系指直接接触内包装的外包装上的标签。 兽药最小销售单元：系指直接供上市销售的兽药最小包装。 兽药说明书：系指包含兽药有效成分、疗效、使用以及注意事项等基本信息的技术资料。 生产企业信息：包括企业名称、邮编、地址、电话、传真、电子邮址、网址等。"},{"i":25,"n":"第二十五条","txt":"本办法由农业部负责解释。"},{"i":26,"n":"第二十六条","txt":"本办法自2003年3月1日起施行。"}],"shouyaozhucebanfa":[{"i":1,"n":"第一条","txt":"为保证兽药安全、有效和质量可控，规范兽药注册行为，根据《兽药管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事新兽药注册和进口兽药注册，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"农业部负责全国兽药注册工作。 农业部兽药审评委员会负责新兽药和进口兽药注册资料的评审工作。 中国兽医药品监察所和农业部指定的其他兽药检验机构承担兽药注册的复核检验工作。"},{"i":4,"n":"第四条","txt":"新兽药注册申请人应当在完成临床试验后，向农业部提出申请，并按《兽药注册资料要求》提交相关资料。"},{"i":5,"n":"第五条","txt":"联合研制的新兽药，可以由其中一个单位申请注册或联合申请注册，但不得重复申请注册；联合申请注册的，应当共同署名作为该新兽药的申请人。"},{"i":6,"n":"第六条","txt":"申请新兽药注册所报送的资料应当完整、规范，数据必须真实、可靠。引用文献资料应当注明著作名称、刊物名称及卷、期、页等；未公开发表的文献资料应当提供资料所有者许可使用的证明文件；外文资料应当按照要求提供中文译本。 申请新兽药注册时，申请人应当提交保证书，承诺对他人的知识产权不构成侵权并对可能的侵权后果负责，保证自行取得的试验数据的真实性。 申报资料含有境外兽药试验研究资料的，应当附具境外研究机构提供的资料项目、页码情况说明和该机构经公证的合法登记证明文件。"},{"i":7,"n":"第七条","txt":"有下列情形之一的新兽药注册申请，不予受理： （一）农业部已公告在监测期，申请人不能证明数据为自己取得的兽药； （二）经基因工程技术获得，未通过生物安全评价的灭活疫苗、诊断制品之外的兽药； （三）申请材料不符合要求，在规定期间内未补正的； （四）不予受理的其他情形。"},{"i":8,"n":"第八条","txt":"农业部自收到申请之日起10个工作日内，将决定受理的新兽药注册申请资料送农业部兽药审评委员会进行技术评审，并通知申请人提交复核检验所需的连续3个生产批号的样品和有关资料，送指定的兽药检验机构进行复核检验。 申请的新兽药属于生物制品的，必要时，应对有关种毒进行检验。"},{"i":9,"n":"第九条","txt":"农业部兽药审评委员会应当自收到资料之日起120个工作日内提出评审意见，报送农业部。 评审中需要补充资料的，申请人应当自收到通知之日起6个月内补齐有关数据；逾期未补正的，视为自动撤回注册申请。"},{"i":10,"n":"第十条","txt":"兽药检验机构应当在规定时间内完成复核检验，并将检验报告书和复核意见送达申请人，同时报农业部和农业部兽药审评委员会。 初次样品检验不合格的，申请人可以再送样复核检验一次。"},{"i":11,"n":"第十一条","txt":"农业部自收到技术评审和复核检验结论之日起60个工作日内完成审查；必要时，可派员进行现场核查。审查合格的，发给《新兽药注册证书》，并予以公告，同时发布该新兽药的标准、标签和说明书。不合格的，书面通知申请人。"},{"i":12,"n":"第十二条","txt":"新兽药注册审批期间，新兽药的技术要求由于相同品种在境外获准上市而发生变化的，按原技术要求审批。"},{"i":13,"n":"第十三条","txt":"首次向中国出口兽药，应当由出口方驻中国境内的办事机构或由其委托的中国境内代理机构向农业部提出申请，填写《兽药注册申请表》，并按《兽药注册资料要求》提交相关资料。 申请向中国出口兽用生物制品的，还应当提供菌（毒、虫）种、细胞等有关材料和资料。"},{"i":14,"n":"第十四条","txt":"申请兽药制剂进口注册，必须提供用于生产该制剂的原料药和辅料、直接接触兽药的包装材料和容器合法来源的证明文件。原料药尚未取得农业部批准的，须同时申请原料药注册，并应当报送有关的生产工艺、质量指标和检验方法等研究资料。"},{"i":15,"n":"第十五条","txt":"申请进口兽药注册所报送的资料应当完整、规范，数据必须真实、可靠。引用文献资料应当注明著作名称、刊物名称及卷、期、页等；外文资料应当按照要求提供中文译本。"},{"i":16,"n":"第十六条","txt":"农业部自收到申请之日起10个工作日内组织初步审查，经初步审查合格的，予以受理，书面通知申请人。 予以受理的，农业部将进口兽药注册申请资料送农业部兽药审评委员会进行技术评审，并通知申请人提交复核检验所需的连续3个生产批号的样品和有关资料，送指定的兽药检验机构进行复核检验。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的进口兽药注册申请，不予受理： （一）农业部已公告在监测期，申请人不能证明数据为自己取得的兽药； （二）经基因工程技术获得，未通过生物安全评价的灭活疫苗、诊断制品之外的兽药； （三）我国规定的一类疫病以及国内未发生疫病的活疫苗； （四）来自疫区可能造成疫病在中国境内传播的兽用生物制品； （五）申请资料不符合要求，在规定期间内未补正的； （六）不予受理的其他情形。"},{"i":18,"n":"第十八条","txt":"进口兽药注册的评审和检验程序适用本办法第九条和第十条的规定。"},{"i":19,"n":"第十九条","txt":"申请进口注册的兽用化学药品，应当在中华人民共和国境内指定的机构进行相关临床试验和残留检测方法验证；必要时，农业部可以要求进行残留消除试验，以确定休药期。 申请进口注册的兽药属于生物制品的，农业部可以要求在中华人民共和国境内指定的机构进行安全性和有效性试验。"},{"i":20,"n":"第二十条","txt":"农业部自收到技术评审和复核检验结论之日起60个工作日内完成审查；必要时，可派员进行现场核查。审查合格的，发给《进口兽药注册证书》，并予以公告；中国香港、澳门和台湾地区的生产企业申请注册的兽药，发给《兽药注册证书》。审查不合格的，书面通知申请人。 农业部在批准进口兽药注册的同时，发布经核准的进口兽药标准和产品标签、说明书。"},{"i":21,"n":"第二十一条","txt":"农业部对申请进口注册的兽药进行风险分析，经风险分析存在安全风险的，不予注册。"},{"i":22,"n":"第二十二条","txt":"已经注册的兽药拟改变原批准事项的，应当向农业部申请兽药变更注册。"},{"i":23,"n":"第二十三条","txt":"申请人申请变更注册时，应当填写《兽药变更注册申请表》，报送有关资料和说明。涉及兽药产品权属变化的，应当提供有效证明文件。 进口兽药的变更注册，申请人还应当提交生产企业所在国家（地区）兽药管理机构批准变更的文件。"},{"i":24,"n":"第二十四条","txt":"农业部对决定受理的不需进行技术审评的兽药变更注册申请，自收到申请之日起30个工作日内完成审查。审查合格的，批准变更注册。 需要进行技术审评的兽药变更注册申请，农业部将受理的材料送农业部兽药审评委员会评审，并通知申请人提交复核检验所需的连续3个生产批号的样品和有关资料，送指定的兽药检验机构进行复核检验。"},{"i":25,"n":"第二十五条","txt":"兽药变更注册申请的评审、检验的程序、时限和要求适用本办法新兽药注册和进口兽药注册的规定。 申请修改兽药标准变更注册的，兽药检验机构应当进行标准复核。"},{"i":26,"n":"第二十六条","txt":"农业部自收到技术评审和复核检验结论之日起30个工作日内完成审查，审查合格的，批准变更注册。审查不合格的，书面告知申请人。"},{"i":27,"n":"第二十七条","txt":"《进口兽药注册证书》和《兽药注册证书》的有效期为5年。有效期届满需要继续进口的，申请人应当在有效期届满6个月前向农业部提出再注册申请。"},{"i":28,"n":"第二十八条","txt":"申请进口兽药再注册时，应当填写《兽药再注册申请表》，并按《兽药注册资料要求》提交相关资料。"},{"i":29,"n":"第二十九条","txt":"农业部在受理进口兽药再注册申请后，应当在20个工作日内完成审查。符合规定的，予以再注册。不符合规定的，书面通知申请人。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，不予再注册： （一）未在有效期届满6个月前提出再注册申请的； （二）未按规定提交兽药不良反应监测报告的； （三）经农业部安全再评价被列为禁止使用品种的； （四）经考查生产条件不符合规定的； （五）经风险分析存在安全风险的； （六）我国规定的一类疫病以及国内未发生疫病的活疫苗； （七）来自疫区可能造成疫病在中国境内传播的兽用生物制品； （八）其他依法不予再注册的。"},{"i":31,"n":"第三十一条","txt":"不予再注册的，由农业部注销其《进口兽药注册证书》或《兽药注册证书》，并予以公告。"},{"i":32,"n":"第三十二条","txt":"申请兽药注册应当进行兽药复核检验，包括样品检验和兽药质量标准复核。"},{"i":33,"n":"第三十三条","txt":"从事兽药复核检验的兽药检验机构，应当符合兽药检验质量管理规范。"},{"i":34,"n":"第三十四条","txt":"申请人应当向兽药检验机构提供兽药复核检验所需要的有关资料和样品，提供检验用标准物质和必需材料。 申请兽药注册所需的3批样品，应当在取得《兽药GMP证书》的车间生产。每批的样品应为拟上市销售的3个最小包装，并为检验用量的3～5倍。"},{"i":35,"n":"第三十五条","txt":"兽药检验机构进行兽药质量标准复核时，除进行样品检验外，还应当根据该兽药的研究数据、国内外同类产品的兽药质量标准和国家有关要求，对该兽药的兽药质量标准、检验项目和方法等提出复核意见。"},{"i":36,"n":"第三十六条","txt":"兽药检验机构在接到检验通知和样品后，应当在90个工作日内完成样品检验，出具检验报告书；需用特殊方法检验的兽药应当在120个工作日内完成。 需要进行样品检验和兽药质量标准复核的，兽药检验机构应当在120个工作日内完成；需用特殊方法检验的兽药应当在150个工作日内完成。"},{"i":37,"n":"第三十七条","txt":"中国兽医药品监察所负责标定和供应国家兽药标准物质。 中国兽医药品监察所可以组织相关的省、自治区、直辖市兽药监察所、兽药研究机构或兽药生产企业协作标定国家兽药标准物质。"},{"i":38,"n":"第三十八条","txt":"申请人在申请新兽药注册和进口兽药注册时，应当向中国兽医药品监察所提供制备该兽药标准物质的原料，并报送有关标准物质的研究资料。"},{"i":39,"n":"第三十九条","txt":"中国兽医药品监察所对兽药标准物质的原料选择、制备方法、标定方法、标定结果、定值准确性、量值溯源、稳定性及分装与包装条件等资料进行全面技术审核；必要时，进行标定或组织进行标定，并做出可否作为国家兽药质量标准物质的推荐结论，报国家兽药典委员会审查。"},{"i":40,"n":"第四十条","txt":"农业部根据国家兽药典委员会的审查意见批准国家兽药质量标准物质，并发布兽药标准物质清单及质量标准。"},{"i":41,"n":"第四十一条","txt":"申请人提供虚假的资料、样品或者采取其他欺骗手段申请注册的，农业部对该申请不予批准，对申请人给予警告，申请人在一年内不得再次申请该兽药的注册。 申请人提供虚假的资料、样品或者采取其他欺骗手段取得兽药注册证明文件的，按《兽药管理条例》第五十七条的规定给予处罚，申请人在三年内不得再次申请该兽药的注册。"},{"i":42,"n":"第四十二条","txt":"其它违反本办法规定的行为，依照《兽药管理条例》的有关规定进行处罚。"},{"i":43,"n":"第四十三条","txt":"属于兽用麻醉药品、兽用精神药品、兽医医疗用毒性药品、放射性药品的新兽药和进口兽药注册申请，除按照本办法办理外，还应当符合国家其他有关规定。"},{"i":44,"n":"第四十四条","txt":"根据动物防疫需要，农业部对国家兽医参考实验室推荐的强制免疫用疫苗生产所用菌（毒）种的变更实行备案制，不需进行变更注册。"},{"i":45,"n":"第四十五条","txt":"本办法自2005年1月1日起施行。"}],"shouyaoshengchanzhiliangguanliguifan":[{"i":1,"n":"第一条","txt":"为加强兽药生产质量管理，根据《兽药管理条例》，制定兽药生产质量管理规范（兽药GMP）。"},{"i":2,"n":"第二条","txt":"本规范是兽药生产管理和质量控制的基本要求，旨在确保持续稳定地生产出符合注册要求的兽药。"},{"i":3,"n":"第三条","txt":"企业应当严格执行本规范，坚持诚实守信，禁止任何虚假、欺骗行为。"},{"i":4,"n":"第四条","txt":"企业应当建立符合兽药质量管理要求的质量目标，将兽药有关安全、有效和质量可控的所有要求，系统地贯彻到兽药生产、控制及产品放行、贮存、销售的全过程中，确保所生产的兽药符合注册要求。"},{"i":5,"n":"第五条","txt":"企业高层管理人员应当确保实现既定的质量目标，不同层次的人员应当共同参与并承担各自的责任。"},{"i":6,"n":"第六条","txt":"企业配备的人员、厂房、设施和设备等条件，应当满足质量目标的需要。"},{"i":7,"n":"第七条","txt":"企业应当建立质量保证系统，同时建立完整的文件体系，以保证系统有效运行。 企业应当对高风险产品的关键生产环节建立信息化管理系统，进行在线记录和监控。"},{"i":8,"n":"第八条","txt":"质量保证系统应当确保： （一）兽药的设计与研发体现本规范的要求； （二）生产管理和质量控制活动符合本规范的要求； （三）管理职责明确； （四）采购和使用的原辅料和包装材料符合要求； （五）中间产品得到有效控制； （六）确认、验证的实施； （七）严格按照规程进行生产、检查、检验和复核； （八）每批产品经质量管理负责人批准后方可放行； （九）在贮存、销售和随后的各种操作过程中有保证兽药质量的适当措施； （十）按照自检规程，定期检查评估质量保证系统的有效性和适用性。"},{"i":9,"n":"第九条","txt":"兽药生产质量管理的基本要求： （一）制定生产工艺，系统地回顾并证明其可持续稳定地生产出符合要求的产品。 （二）生产工艺及影响产品质量的工艺变更均须经过验证。 （三）配备所需的资源，至少包括： 1.具有相应能力并经培训合格的人员； 2.足够的厂房和空间； 3.适用的设施、设备和维修保障； 4.正确的原辅料、包装材料和标签； 5.经批准的工艺规程和操作规程； 6.适当的贮运条件。 （四）应当使用准确、易懂的语言制定操作规程。 （五）操作人员经过培训，能够按照操作规程正确操作。 （六）生产全过程应当有记录，偏差均经过调查并记录。 （七）批记录、销售记录和电子追溯码信息应当能够追溯批产品的完整历史，并妥善保存、便于查阅。 （八）采取适当的措施，降低兽药销售过程中的质量风险。 （九）建立兽药召回系统，确保能够召回已销售的产品。 （十）调查导致兽药投诉和质量缺陷的原因，并采取措施，防止类似投诉和质"},{"i":10,"n":"第十条","txt":"质量控制包括相应的组织机构、文件系统以及取样、检验等，确保物料或产品在放行前完成必要的检验，确认其质量符合要求。"},{"i":11,"n":"第十一条","txt":"质量控制的基本要求： （一）应当配备适当的设施、设备、仪器和经过培训的人员，有效、可靠地完成所有质量控制的相关活动； （二）应当有批准的操作规程，用于原辅料、包装材料、中间产品和成品的取样、检查、检验以及产品的稳定性考察，必要时进行环境监测，以确保符合本规范的要求； （三）由经授权的人员按照规定的方法对原辅料、包装材料、中间产品和成品取样； （四）检验方法应当经过验证或确认； （五）应当按照质量标准对物料、中间产品和成品进行检查和检验； （六）取样、检查、检验应当有记录，偏差应当经过调查并记录； （七）物料和成品应当有足够的留样，以备必要的检查或检验；除最终包装容器过大的成品外，成品的留样包装应当与最终包装相同。最终包装容器过大的成品应使用材质和结构一样的市售模拟包装。"},{"i":12,"n":"第十二条","txt":"质量风险管理是在整个产品生命周期中采用前瞻或回顾的方式，对质量风险进行识别、评估、控制、沟通、审核的系统过程。"},{"i":13,"n":"第十三条","txt":"应当根据科学知识及经验对质量风险进行评估，以保证产品质量。"},{"i":14,"n":"第十四条","txt":"质量风险管理过程所采用的方法、措施、形式及形成的文件应当与存在风险的级别相适应。"},{"i":15,"n":"第十五条","txt":"企业应当建立与兽药生产相适应的管理机构，并有组织机构图。 企业应当设立独立的质量管理部门，履行质量保证和质量控制的职责。质量管理部门可以分别设立质量保证部门和质量控制部门。"},{"i":16,"n":"第十六条","txt":"质量管理部门应当参与所有与质量有关的活动，负责审核所有与本规范有关的文件。质量管理部门人员不得将职责委托给其他部门的人员。"},{"i":17,"n":"第十七条","txt":"企业应当配备足够数量并具有相应能力（含学历、培训和实践经验）的管理和操作人员，应当明确规定每个部门和每个岗位的职责。岗位职责不得遗漏，交叉的职责应当有明确规定。每个人承担的职责不得过多。 所有人员应当明确并理解自己的职责，熟悉与其职责相关的要求，并接受必要的培训，包括上岗前培训和继续培训。"},{"i":18,"n":"第十八条","txt":"职责通常不得委托给他人。确需委托的，其职责应委托给具有相当资质的指定人员。"},{"i":19,"n":"第十九条","txt":"关键人员应当为企业的全职人员，至少包括企业负责人、生产管理负责人和质量管理负责人。 质量管理负责人和生产管理负责人不得互相兼任。企业应当制定操作规程确保质量管理负责人独立履行职责，不受企业负责人和其他人员的干扰。"},{"i":20,"n":"第二十条","txt":"企业负责人是兽药质量的主要责任人，全面负责企业日常管理。为确保企业实现质量目标并按照本规范要求生产兽药，企业负责人负责提供并合理计划、组织和协调必要的资源，保证质量管理部门独立履行其职责。"},{"i":21,"n":"第二十一条","txt":"生产管理负责人 （一）资质： 生产管理负责人应当至少具有药学、兽医学、生物学、化学等相关专业本科学历（中级专业技术职称），具有至少三年从事兽药（药品）生产或质量管理的实践经验，其中至少有一年的兽药（药品）生产管理经验，接受过与所生产产品相关的专业知识培训。 （二）主要职责： 1.确保兽药按照批准的工艺规程生产、贮存，以保证兽药质量； 2.确保严格执行与生产操作相关的各种操作规程； 3.确保批生产记录和批包装记录已经指定人员审核并送交质量管理部门； 4.确保厂房和设备的维护保养，以保持其良好的运行状态； 5.确保完成各种必要的验证工作； 6.确保生产相关人员经过必要的上岗前培训和继续培训，并根据实际需要调整培训内容。"},{"i":22,"n":"第二十二条","txt":"质量管理负责人 （一）资质： 质量管理负责人应当至少具有药学、兽医学、生物学、化学等相关专业本科学历（中级专业技术职称），具有至少五年从事兽药（药品）生产或质量管理的实践经验，其中至少一年的兽药（药品）质量管理经验，接受过与所生产产品相关的专业知识培训。 （二）主要职责： 1.确保原辅料、包装材料、中间产品和成品符合工艺规程的要求和质量标准； 2.确保在产品放行前完成对批记录的审核； 3.确保完成所有必要的检验； 4.批准质量标准、取样方法、检验方法和其他质量管理的操作规程； 5.审核和批准所有与质量有关的变更； 6.确保所有重大偏差和检验结果超标已经过调查并得到及时处理； 7.监督厂房和设备的维护，以保持其良好的运行状态； 8.确保完成各种必要的确认或验证工作，审核和批准确认或验证方案和报告； 9.确保完成自检； 10.评估和批准物料供应商； 11.确保所有与产品质量有关的投诉已经过"},{"i":23,"n":"第二十三条","txt":"企业应当指定部门或专人负责培训管理工作，应当有批准的培训方案或计划，培训记录应当予以保存。"},{"i":24,"n":"第二十四条","txt":"与兽药生产、质量有关的所有人员都应当经过培训，培训的内容应当与岗位的要求相适应。除进行本规范理论和实践的培训外，还应当有相关法规、相应岗位的职责、技能的培训，并定期评估培训实际效果。应对检验人员进行检验能力考核，合格后上岗。"},{"i":25,"n":"第二十五条","txt":"高风险操作区（如高活性、高毒性、传染性、高致敏性物料的生产区）的工作人员应当接受专门的专业知识和安全防护要求的培训。"},{"i":26,"n":"第二十六条","txt":"企业应当建立人员卫生操作规程，最大限度地降低人员对兽药生产造成污染的风险。"},{"i":27,"n":"第二十七条","txt":"人员卫生操作规程应当包括与健康、卫生习惯及人员着装相关的内容。企业应当采取措施确保人员卫生操作规程的执行。"},{"i":28,"n":"第二十八条","txt":"企业应当对人员健康进行管理，并建立健康档案。直接接触兽药的生产人员上岗前应当接受健康检查，以后每年至少进行一次健康检查。"},{"i":29,"n":"第二十九条","txt":"企业应当采取适当措施，避免体表有伤口、患有传染病或其他疾病可能污染兽药的人员从事直接接触兽药的生产活动。"},{"i":30,"n":"第三十条","txt":"参观人员和未经培训的人员不得进入生产区和质量控制区，特殊情况确需进入的，应当经过批准，并对进入人员的个人卫生、更衣等事项进行指导。"},{"i":31,"n":"第三十一条","txt":"任何进入生产区的人员均应当按照规定更衣。工作服的选材、式样及穿戴方式应当与所从事的工作和空气洁净度级别要求相适应。"},{"i":32,"n":"第三十二条","txt":"进入洁净生产区的人员不得化妆和佩带饰物。"},{"i":33,"n":"第三十三条","txt":"生产区、检验区、仓储区应当禁止吸烟和饮食，禁止存放食品、饮料、香烟和个人用品等非生产用物品。"},{"i":34,"n":"第三十四条","txt":"操作人员应当避免裸手直接接触兽药以及与兽药直接接触的容器具、包装材料和设备表面。"},{"i":35,"n":"第三十五条","txt":"厂房的选址、设计、布局、建造、改造和维护必须符合兽药生产要求，应当能够最大限度地避免污染、交叉污染、混淆和差错，便于清洁、操作和维护。"},{"i":36,"n":"第三十六条","txt":"应当根据厂房及生产防护措施综合考虑选址，厂房所处的环境应当能够最大限度地降低物料或产品遭受污染的风险。"},{"i":37,"n":"第三十七条","txt":"企业应当有整洁的生产环境；厂区的地面、路面等设施及厂内运输等活动不得对兽药的生产造成污染；生产、行政、生活和辅助区的总体布局应当合理，不得互相妨碍；厂区和厂房内的人、物流走向应当合理。"},{"i":38,"n":"第三十八条","txt":"应当对厂房进行适当维护，并确保维修活动不影响兽药的质量。应当按照详细的书面操作规程对厂房进行清洁或必要的消毒。"},{"i":39,"n":"第三十九条","txt":"厂房应当有适当的照明、温度、湿度和通风，确保生产和贮存的产品质量以及相关设备性能不会直接或间接地受到影响。"},{"i":40,"n":"第四十条","txt":"厂房、设施的设计和安装应当能够有效防止昆虫或其他动物进入。应当采取必要的措施，避免所使用的灭鼠药、杀虫剂、烟熏剂等对设备、物料、产品造成污染。"},{"i":41,"n":"第四十一条","txt":"应当采取适当措施，防止未经批准人员的进入。生产、贮存和质量控制区不得作为非本区工作人员的直接通道。"},{"i":42,"n":"第四十二条","txt":"应当保存厂房、公用设施、固定管道建造或改造后的竣工图纸。"},{"i":43,"n":"第四十三条","txt":"为降低污染和交叉污染的风险，厂房、生产设施和设备应当根据所生产兽药的特性、工艺流程及相应洁净度级别要求合理设计、布局和使用，并符合下列要求： （一）应当根据兽药的特性、工艺等因素，确定厂房、生产设施和设备供多产品共用的可行性，并有相应的评估报告。 （二）生产青霉素类等高致敏性兽药应使用相对独立的厂房、生产设施及专用的空气净化系统，分装室应保持相对负压，排至室外的废气应经净化处理并符合要求，排风口应远离其他空气净化系统的进风口。如需利用停产的该类车间分装其他产品时，则必须进行清洁处理，不得有残留并经测试合格后才能生产其他产品。 （三）生产高生物活性兽药（如性激素类等）应使用专用的车间、生产设施及空气净化系统，并与其他兽药生产区严格分开。 （四）生产吸入麻醉剂类兽药应使用专用的车间、生产设施及空气净化系统；配液和分装工序应保持相对负压，其空调排风系统采用全排风，不得利用回风方式。 （五）兽"},{"i":44,"n":"第四十四条","txt":"生产区和贮存区应当有足够的空间，确保有序地存放设备、物料、中间产品和成品，避免不同产品或物料的混淆、交叉污染，避免生产或质量控制操作发生遗漏或差错。"},{"i":45,"n":"第四十五条","txt":"应当根据兽药品种、生产操作要求及外部环境状况等配置空气净化系统，使生产区有效通风，并有温度、湿度控制和空气净化过滤，保证兽药的生产环境符合要求。 洁净区与非洁净区之间、不同级别洁净区之间的压差应当不低于10帕斯卡。必要时，相同洁净度级别的不同功能区域（操作间）之间也应当保持适当的压差梯度，并应有指示压差的装置和（或）设置监控系统。 兽药生产洁净室（区）分为A级、B级、C级和D级4个级别。生产不同类别兽药的洁净室（区）设计应当符合相应的洁净度要求，包括达到“静态”和“动态”的标准。"},{"i":46,"n":"第四十六条","txt":"洁净区的内表面（墙壁、地面、天棚）应当平整光滑、无裂缝、接口严密、无颗粒物脱落，避免积尘，便于有效清洁，必要时应当进行消毒。"},{"i":47,"n":"第四十七条","txt":"各种管道、工艺用水的水处理及其配套设施、照明设施、风口和其他公用设施的设计和安装应当避免出现不易清洁的部位，应当尽可能在生产区外部对其进行维护。 与无菌兽药直接接触的干燥用空气、压缩空气和惰性气体应经净化处理，其洁净程度、管道材质等应与对应的洁净区的要求相一致。"},{"i":48,"n":"第四十八条","txt":"排水设施应当大小适宜，并安装防止倒灌的装置。含高致病性病原微生物以及有感染人风险的人兽共患病病原微生物的活毒废水，应有有效的无害化处理设施。"},{"i":49,"n":"第四十九条","txt":"制剂的原辅料称量通常应当在专门设计的称量室内进行。"},{"i":50,"n":"第五十条","txt":"产尘操作间（如干燥物料或产品的取样、称量、混合、包装等操作间）应当保持相对负压或采取专门的措施，防止粉尘扩散、避免交叉污染并便于清洁。"},{"i":51,"n":"第五十一条","txt":"用于兽药包装的厂房或区域应当合理设计和布局，以避免混淆或交叉污染。如同一区域内有数条包装线，应当有隔离措施。"},{"i":52,"n":"第五十二条","txt":"生产区应根据功能要求提供足够的照明，目视操作区域的照明应当满足操作要求。"},{"i":53,"n":"第五十三条","txt":"生产区内可设中间产品检验区域，但中间产品检验操作不得给兽药带来质量风险。"},{"i":54,"n":"第五十四条","txt":"仓储区应当有足够的空间，确保有序存放待验、合格、不合格、退货或召回的原辅料、包装材料、中间产品和成品等各类物料和产品。"},{"i":55,"n":"第五十五条","txt":"仓储区的设计和建造应当确保良好的仓储条件，并有通风和照明设施。仓储区应当能够满足物料或产品的贮存条件（如温湿度、避光）和安全贮存的要求，并进行检查和监控。"},{"i":56,"n":"第五十六条","txt":"如采用单独的隔离区域贮存待验物料或产品，待验区应当有醒目的标识，且仅限经批准的人员出入。 不合格、退货或召回的物料或产品应当隔离存放。 如果采用其他方法替代物理隔离，则该方法应当具有同等的安全性。"},{"i":57,"n":"第五十七条","txt":"易燃、易爆和其他危险品的生产和贮存的厂房设施应符合国家有关规定。兽用麻醉药品、精神药品、毒性药品的贮存设施应符合有关规定。"},{"i":58,"n":"第五十八条","txt":"高活性的物料或产品以及印刷包装材料应当贮存于安全的区域。"},{"i":59,"n":"第五十九条","txt":"接收、发放和销售区域及转运过程应当能够保护物料、产品免受外界天气（如雨、雪）的影响。接收区的布局和设施，应当能够确保物料在进入仓储区前可对外包装进行必要的清洁。"},{"i":60,"n":"第六十条","txt":"贮存区域应当设置托盘等设施，避免物料、成品受潮。"},{"i":61,"n":"第六十一条","txt":"应当有单独的物料取样区，取样区的空气洁净度级别应当与生产要求相一致。如在其他区域或采用其他方式取样，应当能够防止污染或交叉污染。"},{"i":62,"n":"第六十二条","txt":"质量控制实验室通常应当与生产区分开。根据生产品种，应有相应符合无菌检查、微生物限度检查和抗生素微生物检定等要求的实验室。生物检定和微生物实验室还应当彼此分开。"},{"i":63,"n":"第六十三条","txt":"实验室的设计应当确保其适用于预定的用途，并能够避免混淆和交叉污染，应当有足够的区域用于样品处置、留样和稳定性考察样品的存放以及记录的保存。"},{"i":64,"n":"第六十四条","txt":"有特殊要求的仪器应当设置专门的仪器室，使灵敏度高的仪器免受静电、震动、潮湿或其他外界因素的干扰。"},{"i":65,"n":"第六十五条","txt":"处理生物样品等特殊物品的实验室应当符合国家的有关要求。"},{"i":66,"n":"第六十六条","txt":"实验动物房应当与其他区域严格分开，其设计、建造应当符合国家有关规定，并设有专用的空气处理设施以及动物的专用通道。如需采用动物生产兽用生物制品，生产用动物房必须单独设置，并设有专用的空气处理设施以及动物的专用通道。 生产兽用生物制品的企业应设置检验用动物实验室。同一集团控股的不同生物制品生产企业，可由每个生产企业分别设置检验用动物实验室或委托集团内具备相应检验条件和能力的生产企业进行有关动物实验。有生物安全三级防护要求的兽用生物制品检验用实验室和动物实验室，还应符合相关规定。 生产兽用生物制品外其他需使用动物进行检验的兽药产品，兽药生产企业可采取自行设置检验用动物实验室或委托其他单位进行有关动物实验。接受委托检验的单位，其检验用动物实验室必须具备相应的检验条件，并应符合相关规定要求。采取委托检验的，委托方对检验结果负责。"},{"i":67,"n":"第六十七条","txt":"休息室的设置不得对生产区、仓储区和质量控制区造成不良影响。"},{"i":68,"n":"第六十八条","txt":"更衣室和盥洗室应当方便人员进出，并与使用人数相适应。盥洗室不得与生产区和仓储区直接相通。"},{"i":69,"n":"第六十九条","txt":"维修间应当尽可能远离生产区。存放在洁净区内的维修用备件和工具，应当放置在专门的房间或工具柜中。"},{"i":70,"n":"第七十条","txt":"设备的设计、选型、安装、改造和维护必须符合预定用途，应当尽可能降低产生污染、交叉污染、混淆和差错的风险，便于操作、清洁、维护以及必要时进行的消毒或灭菌。"},{"i":71,"n":"第七十一条","txt":"应当建立设备使用、清洁、维护和维修的操作规程，以保证设备的性能，应按规程使用设备并记录。"},{"i":72,"n":"第七十二条","txt":"主要生产和检验设备、仪器、衡器均应建立设备档案，内容包括：生产厂家、型号、规格、技术参数、说明书、设备图纸、备件清单、安装位置及竣工图，以及检修和维修保养内容及记录、验证记录、事故记录等。"},{"i":73,"n":"第七十三条","txt":"生产设备应当避免对兽药质量产生不利影响。与兽药直接接触的生产设备表面应当平整、光洁、易清洗或消毒、耐腐蚀，不得与兽药发生化学反应、吸附兽药或向兽药中释放物质而影响产品质量。"},{"i":74,"n":"第七十四条","txt":"生产、检验设备的性能、参数应能满足设计要求和实际生产需求，并应当配备有适当量程和精度的衡器、量具、仪器和仪表。相关设备还应符合实施兽药产品电子追溯管理的要求。"},{"i":75,"n":"第七十五条","txt":"应当选择适当的清洗、清洁设备，并防止这类设备成为污染源。"},{"i":76,"n":"第七十六条","txt":"设备所用的润滑剂、冷却剂等不得对兽药或容器造成污染，与兽药可能接触的部位应当使用食用级或级别相当的润滑剂。"},{"i":77,"n":"第七十七条","txt":"生产用模具的采购、验收、保管、维护、发放及报废应当制定相应操作规程，设专人专柜保管，并有相应记录。"},{"i":78,"n":"第七十八条","txt":"主要生产和检验设备都应当有明确的操作规程。"},{"i":79,"n":"第七十九条","txt":"生产设备应当在确认的参数范围内使用。"},{"i":80,"n":"第八十条","txt":"生产设备应当有明显的状态标识，标明设备编号、名称、运行状态等。运行的设备应当标明内容物的信息，如名称、规格、批号等，没有内容物的生产设备应当标明清洁状态。"},{"i":81,"n":"第八十一条","txt":"与设备连接的主要固定管道应当标明内容物名称和流向。"},{"i":82,"n":"第八十二条","txt":"应当制定设备的预防性维护计划，设备的维护和维修应当有相应的记录。"},{"i":83,"n":"第八十三条","txt":"设备的维护和维修应保持设备的性能，并不得影响产品质量。"},{"i":84,"n":"第八十四条","txt":"经改造或重大维修的设备应当进行再确认，符合要求后方可继续使用。"},{"i":85,"n":"第八十五条","txt":"不合格的设备应当搬出生产和质量控制区，如未搬出，应当有醒目的状态标识。"},{"i":86,"n":"第八十六条","txt":"用于兽药生产或检验的设备和仪器，应当有使用和维修、维护记录，使用记录内容包括使用情况、日期、时间、所生产及检验的兽药名称、规格和批号等。"},{"i":87,"n":"第八十七条","txt":"兽药生产设备应保持良好的清洁卫生状态，不得对兽药的生产造成污染和交叉污染。"},{"i":88,"n":"第八十八条","txt":"生产、检验设备及器具均应制定清洁操作规程，并按照规程进行清洁和记录。"},{"i":89,"n":"第八十九条","txt":"已清洁的生产设备应当在清洁、干燥的条件下存放。"},{"i":90,"n":"第九十条","txt":"应当根据国家标准及仪器使用特点对生产和检验用衡器、量具、仪表、记录和控制设备以及仪器制定检定(校准)计划，检定(校准)的范围应当涵盖实际使用范围。应按计划进行检定或校准，并保存相关证书、报告或记录。"},{"i":91,"n":"第九十一条","txt":"应当确保生产和检验使用的衡器、量具、仪器仪表经过校准，控制设备得到确认，确保得到的数据准确、可靠。"},{"i":92,"n":"第九十二条","txt":"仪器的检定和校准应当符合国家有关规定，应保证校验数据的有效性。 自校仪器、量具应制定自校规程，并具备自校设施条件，校验人员具有相应资质，并做好校验记录。"},{"i":93,"n":"第九十三条","txt":"衡器、量具、仪表、用于记录和控制的设备以及仪器应当有明显的标识，标明其检定或校准有效期。"},{"i":94,"n":"第九十四条","txt":"在生产、包装、仓储过程中使用自动或电子设备的，应当按照操作规程定期进行校准和检查，确保其操作功能正常。校准和检查应当有相应的记录。"},{"i":95,"n":"第九十五条","txt":"制药用水应当适合其用途，并符合《中华人民共和国兽药典》的质量标准及相关要求。制药用水至少应当采用饮用水。"},{"i":96,"n":"第九十六条","txt":"水处理设备及其输送系统的设计、安装、运行和维护应当确保制药用水达到设定的质量标准。水处理设备的运行不得超出其设计能力。"},{"i":97,"n":"第九十七条","txt":"纯化水、注射用水储罐和输送管道所用材料应当无毒、耐腐蚀；储罐的通气口应当安装不脱落纤维的疏水性除菌滤器；管道的设计和安装应当避免死角、盲管。"},{"i":98,"n":"第九十八条","txt":"纯化水、注射用水的制备、贮存和分配应当能够防止微生物的滋生。纯化水可采用循环，注射用水可采用70℃以上保温循环。"},{"i":99,"n":"第九十九条","txt":"应当对制药用水及原水的水质进行定期监测，并有相应的记录。"},{"i":100,"n":"第一百条","txt":"应当按照操作规程对纯化水、注射用水管道进行清洗消毒，并有相关记录。发现制药用水微生物污染达到警戒限度、纠偏限度时应当按照操作规程处理。"},{"i":101,"n":"第一百零一条","txt":"兽药生产所用的原辅料、与兽药直接接触的包装材料应当符合兽药标准、药品标准、包装材料标准或其他有关标准。兽药上直接印字所用油墨应当符合食用标准要求。 进口原辅料应当符合国家相关的进口管理规定。"},{"i":102,"n":"第一百零二条","txt":"应当建立相应的操作规程，确保物料和产品的正确接收、贮存、发放、使用和销售，防止污染、交叉污染、混淆和差错。 物料和产品的处理应当按照操作规程或工艺规程执行，并有记录。"},{"i":103,"n":"第一百零三条","txt":"物料供应商的确定及变更应当进行质量评估，并经质量管理部门批准后方可采购。必要时对关键物料进行现场考查。"},{"i":104,"n":"第一百零四条","txt":"物料和产品的运输应当能够满足质量和安全的要求，对运输有特殊要求的，其运输条件应当予以确认。"},{"i":105,"n":"第一百零五条","txt":"原辅料、与兽药直接接触的包装材料和印刷包装材料的接收应当有操作规程，所有到货物料均应当检查，确保与订单一致，并确认供应商已经质量管理部门批准。 物料的外包装应当有标签，并注明规定的信息。必要时应当进行清洁，发现外包装损坏或其他可能影响物料质量的问题，应当向质量管理部门报告并进行调查和记录。 每次接收均应当有记录，内容包括： （一）交货单和包装容器上所注物料的名称； （二）企业内部所用物料名称和（或）代码； （三）接收日期； （四）供应商和生产商(如不同)的名称； （五）供应商和生产商(如不同)标识的批号； （六）接收总量和包装容器数量； （七）接收后企业指定的批号或流水号； （八）有关说明（如包装状况）； （九）检验报告单等合格性证明材料。"},{"i":106,"n":"第一百零六条","txt":"物料接收和成品生产后应当及时按照待验管理，直至放行。"},{"i":107,"n":"第一百零七条","txt":"物料和产品应当根据其性质有序分批贮存和周转，发放及销售应当符合先进先出和近效期先出的原则。"},{"i":108,"n":"第一百零八条","txt":"使用计算机化仓储管理的，应当有相应的操作规程，防止因系统故障、停机等特殊情况而造成物料和产品的混淆和差错。"},{"i":109,"n":"第一百零九条","txt":"应当制定相应的操作规程，采取核对或检验等适当措施，确认每一批次的原辅料准确无误。"},{"i":110,"n":"第一百一十条","txt":"一次接收数个批次的物料，应当按批取样、检验、放行。"},{"i":111,"n":"第一百一十一条","txt":"仓储区内的原辅料应当有适当的标识，并至少标明下述内容： （一）指定的物料名称或企业内部的物料代码； （二）企业接收时设定的批号； （三）物料质量状态（如待验、合格、不合格、已取样）； （四）有效期或复验期。"},{"i":112,"n":"第一百一十二条","txt":"只有经质量管理部门批准放行并在有效期或复验期内的原辅料方可使用。"},{"i":113,"n":"第一百一十三条","txt":"原辅料应当按照有效期或复验期贮存。贮存期内，如发现对质量有不良影响的特殊情况，应当进行复验。"},{"i":114,"n":"第一百一十四条","txt":"中间产品应当在适当的条件下贮存。"},{"i":115,"n":"第一百一十五条","txt":"中间产品应当有明确的标识，并至少标明下述内容： （一）产品名称或企业内部的产品代码； （二）产品批号； （三）数量或重量（如毛重、净重等）； （四）生产工序（必要时）； （五）产品质量状态（必要时，如待验、合格、不合格、已取样）。"},{"i":116,"n":"第一百一十六条","txt":"与兽药直接接触的包装材料以及印刷包装材料的管理和控制要求与原辅料相同。"},{"i":117,"n":"第一百一十七条","txt":"包装材料应当由专人按照操作规程发放，并采取措施避免混淆和差错，确保用于兽药生产的包装材料正确无误。"},{"i":118,"n":"第一百一十八条","txt":"应当建立印刷包装材料设计、审核、批准的操作规程，确保印刷包装材料印制的内容与畜牧兽医主管部门核准的一致，并建立专门文档，保存经签名批准的印刷包装材料原版实样。"},{"i":119,"n":"第一百一十九条","txt":"印刷包装材料的版本变更时，应当采取措施，确保产品所用印刷包装材料的版本正确无误。应收回作废的旧版印刷模版并予以销毁。"},{"i":120,"n":"第一百二十条","txt":"印刷包装材料应当设置专门区域妥善存放，未经批准，人员不得进入。切割式标签或其他散装印刷包装材料应当分别置于密闭容器内储运，以防混淆。"},{"i":121,"n":"第一百二十一条","txt":"印刷包装材料应当由专人保管，并按照操作规程和需求量发放。"},{"i":122,"n":"第一百二十二条","txt":"每批或每次发放的与兽药直接接触的包装材料或印刷包装材料，均应当有识别标志，标明所用产品的名称和批号。"},{"i":123,"n":"第一百二十三条","txt":"过期或废弃的印刷包装材料应当予以销毁并记录。"},{"i":124,"n":"第一百二十四条","txt":"成品放行前应当待验贮存。"},{"i":125,"n":"第一百二十五条","txt":"成品的贮存条件应当符合兽药质量标准。"},{"i":126,"n":"第一百二十六条","txt":"兽用麻醉药品、精神药品、毒性药品（包括药材）和放射类药品等特殊药品，易制毒化学品及易燃、易爆和其他危险品的验收、贮存、管理应当执行国家有关规定。"},{"i":127,"n":"第一百二十七条","txt":"不合格的物料、中间产品和成品的每个包装容器或批次上均应当有清晰醒目的标志，并在隔离区内妥善保存。"},{"i":128,"n":"第一百二十八条","txt":"不合格的物料、中间产品和成品的处理应当经质量管理负责人批准，并有记录。"},{"i":129,"n":"第一百二十九条","txt":"产品回收需经预先批准，并对相关的质量风险进行充分评估，根据评估结论决定是否回收。回收应当按照预定的操作规程进行，并有相应记录。回收处理后的产品应当按照回收处理中最早批次产品的生产日期确定有效期。"},{"i":130,"n":"第一百三十条","txt":"制剂产品原则上不得进行重新加工。不合格的制剂中间产品和成品一般不得进行返工。只有不影响产品质量、符合相应质量标准，且根据预定、经批准的操作规程以及对相关风险充分评估后，才允许返工处理。返工应当有相应记录。"},{"i":131,"n":"第一百三十一条","txt":"对返工或重新加工或回收合并后生产的成品，质量管理部门应当评估对产品质量的影响，必要时需要进行额外相关项目的检验和稳定性考察。"},{"i":132,"n":"第一百三十二条","txt":"企业应当建立兽药退货的操作规程，并有相应的记录，内容至少应包括：产品名称、批号、规格、数量、退货单位及地址、退货原因及日期、最终处理意见。同一产品同一批号不同渠道的退货应当分别记录、存放和处理。"},{"i":133,"n":"第一百三十三条","txt":"只有经检查、检验和调查，有证据证明退货产品质量未受影响，且经质量管理部门根据操作规程评价后，方可考虑将退货产品重新包装、重新销售。评价考虑的因素至少应当包括兽药的性质、所需的贮存条件、兽药的现状、历史，以及销售与退货之间的间隔时间等因素。对退货产品质量存有怀疑时，不得重新销售。 对退货产品进行回收处理的，回收后的产品应当符合预定的质量标准和第一百二十九条的要求。 退货产品处理的过程和结果应当有相应记录。"},{"i":134,"n":"第一百三十四条","txt":"企业应当确定需要进行的确认或验证工作，以证明有关操作的关键要素能够得到有效控制。确认或验证的范围和程度应当经过风险评估来确定。"},{"i":135,"n":"第一百三十五条","txt":"企业的厂房、设施、设备和检验仪器应当经过确认，应当采用经过验证的生产工艺、操作规程和检验方法进行生产、操作和检验，并保持持续的验证状态。"},{"i":136,"n":"第一百三十六条","txt":"企业应当制定验证总计划，包括厂房与设施、设备、检验仪器、生产工艺、操作规程、清洁方法和检验方法等，确立验证工作的总体原则，明确企业所有验证的总体计划，规定各类验证应达到的目标、验证机构和人员的职责和要求。"},{"i":137,"n":"第一百三十七条","txt":"应当建立确认与验证的文件和记录，并能以文件和记录证明达到以下预定的目标： （一）设计确认应当证明厂房、设施、设备的设计符合预定用途和本规范要求； （二）安装确认应当证明厂房、设施、设备的建造和安装符合设计标准； （三）运行确认应当证明厂房、设施、设备的运行符合设计标准； （四）性能确认应当证明厂房、设施、设备在正常操作方法和工艺条件下能够持续符合标准； （五）工艺验证应当证明一个生产工艺按照规定的工艺参数能够持续生产出符合预定用途和注册要求的产品。"},{"i":138,"n":"第一百三十八条","txt":"采用新的生产处方或生产工艺前，应当验证其常规生产的适用性。生产工艺在使用规定的原辅料和设备条件下，应当能够始终生产出符合注册要求的产品。"},{"i":139,"n":"第一百三十九条","txt":"当影响产品质量的主要因素，如原辅料、与药品直接接触的包装材料、生产设备、生产环境（厂房）、生产工艺、检验方法等发生变更时，应当进行确认或验证。必要时，还应当经畜牧兽医主管部门批准。"},{"i":140,"n":"第一百四十条","txt":"清洁方法应当经过验证，证实其清洁的效果，以有效防止污染和交叉污染。清洁验证应当综合考虑设备使用情况、所使用的清洁剂和消毒剂、取样方法和位置以及相应的取样回收率、残留物的性质和限度、残留物检验方法的灵敏度等因素。"},{"i":141,"n":"第一百四十一条","txt":"应当根据确认或验证的对象制定确认或验证方案，并经审核、批准。确认或验证方案应当明确职责，验证合格标准的设立及进度安排科学合理，可操作性强。"},{"i":142,"n":"第一百四十二条","txt":"确认或验证应当按照预先确定和批准的方案实施，并有记录。确认或验证工作完成后，应当对验证结果进行评价，写出报告（包括评价与建议），并经审核、批准。验证的文件应存档。"},{"i":143,"n":"第一百四十三条","txt":"应当根据验证的结果确认工艺规程和操作规程。"},{"i":144,"n":"第一百四十四条","txt":"确认和验证不是一次性的行为。首次确认或验证后，应当根据产品质量回顾分析情况进行再确认或再验证。关键的生产工艺和操作规程应当定期进行再验证，确保其能够达到预期结果。"},{"i":145,"n":"第一百四十五条","txt":"文件是质量保证系统的基本要素。企业应当有内容正确的书面质量标准、生产处方和工艺规程、操作规程以及记录等文件。"},{"i":146,"n":"第一百四十六条","txt":"企业应当建立文件管理的操作规程，系统地设计、制定、审核、批准、发放、收回和销毁文件。"},{"i":147,"n":"第一百四十七条","txt":"文件的内容应当覆盖与兽药生产有关的所有方面，包括人员、设施设备、物料、验证、生产管理、质量管理、销售、召回和自检等，以及兽药产品赋电子追溯码（二维码）标识制度，保证产品质量可控并有助于追溯每批产品的历史情况。"},{"i":148,"n":"第一百四十八条","txt":"文件的起草、修订、审核、批准、替换或撤销、复制、保管和销毁等应当按照操作规程管理，并有相应的文件分发、撤销、复制、收回、销毁记录。"},{"i":149,"n":"第一百四十九条","txt":"文件的起草、修订、审核、批准均应当由适当的人员签名并注明日期。"},{"i":150,"n":"第一百五十条","txt":"文件应当标明题目、种类、目的以及文件编号和版本号。文字应当确切、清晰、易懂，不能模棱两可。"},{"i":151,"n":"第一百五十一条","txt":"文件应当分类存放、条理分明，便于查阅。"},{"i":152,"n":"第一百五十二条","txt":"原版文件复制时，不得产生任何差错；复制的文件应当清晰可辨。"},{"i":153,"n":"第一百五十三条","txt":"文件应当定期审核、修订；文件修订后，应当按照规定管理，防止旧版文件的误用。分发、使用的文件应当为批准的现行文本，已撤销的或旧版文件除留档备查外，不得在工作现场出现。"},{"i":154,"n":"第一百五十四条","txt":"与本规范有关的每项活动均应当有记录，记录数据应完整可靠，以保证产品生产、质量控制和质量保证、包装所赋电子追溯码等活动可追溯。记录应当留有填写数据的足够空格。记录应当及时填写，内容真实，字迹清晰、易读，不易擦除。"},{"i":155,"n":"第一百五十五条","txt":"应当尽可能采用生产和检验设备自动打印的记录、图谱和曲线图等，并标明产品或样品的名称、批号和记录设备的信息，操作人应当签注姓名和日期。"},{"i":156,"n":"第一百五十六条","txt":"记录应当保持清洁，不得撕毁和任意涂改。记录填写的任何更改都应当签注姓名和日期，并使原有信息仍清晰可辨，必要时，应当说明更改的理由。记录如需重新誊写，则原有记录不得销毁，应当作为重新誊写记录的附件保存。"},{"i":157,"n":"第一百五十七条","txt":"每批兽药应当有批记录，包括批生产记录、批包装记录、批检验记录和兽药放行审核记录以及电子追溯码标识记录等。批记录应当由质量管理部门负责管理，至少保存至兽药有效期后一年。质量标准、工艺规程、操作规程、稳定性考察、确认、验证、变更等其他重要文件应当长期保存。"},{"i":158,"n":"第一百五十八条","txt":"如使用电子数据处理系统、照相技术或其他可靠方式记录数据资料，应当有所用系统的操作规程；记录的准确性应当经过核对。 使用电子数据处理系统的，只有经授权的人员方可输入或更改数据，更改和删除情况应当有记录；应当使用密码或其他方式来控制系统的登录；关键数据输入后，应当由他人独立进行复核。 用电子方法保存的批记录，应当采用磁带、缩微胶卷、纸质副本或其他方法进行备份，以确保记录的安全，且数据资料在保存期内便于查阅。"},{"i":159,"n":"第一百五十九条","txt":"物料和成品应当有经批准的现行质量标准；必要时，中间产品也应当有质量标准。"},{"i":160,"n":"第一百六十条","txt":"物料的质量标准一般应当包括： （一）物料的基本信息： 1.企业统一指定的物料名称或内部使用的物料代码； 2.质量标准的依据。 （二）取样、检验方法或相关操作规程编号。 （三）定性和定量的限度要求。 （四）贮存条件和注意事项。 （五）有效期或复验期。"},{"i":161,"n":"第一百六十一条","txt":"成品的质量标准至少应当包括： （一）产品名称或产品代码； （二）对应的产品处方编号（如有）； （三）产品规格和包装形式； （四）取样、检验方法或相关操作规程编号； （五）定性和定量的限度要求； （六）贮存条件和注意事项； （七）有效期。"},{"i":162,"n":"第一百六十二条","txt":"每种兽药均应当有经企业批准的工艺规程，不同兽药规格的每种包装形式均应当有各自的包装操作要求。工艺规程的制定应当以注册批准的工艺为依据。"},{"i":163,"n":"第一百六十三条","txt":"工艺规程不得任意更改。如需更改，应当按照相关的操作规程修订、审核、批准，影响兽药产品质量的更改应当经过验证。"},{"i":164,"n":"第一百六十四条","txt":"制剂的工艺规程内容至少应当包括： （一）生产处方： 1.产品名称； 2.产品剂型、规格和批量； 3.所用原辅料清单（包括生产过程中使用，但不在成品中出现的物料），阐明每一物料的指定名称和用量；原辅料的用量需要折算时，还应当说明计算方法。 （二）生产操作要求： 1.对生产场所和所用设备的说明（如操作间的位置、洁净度级别、温湿度要求、设备型号等）； 2.关键设备的准备（如清洗、组装、校准、灭菌等）所采用的方法或相应操作规程编号； 3.详细的生产步骤和工艺参数说明（如物料的核对、预处理、加入物料的顺序、混合时间、温度等）； 4.中间控制方法及标准； 5.预期的最终产量限度，必要时，还应当说明中间产品的产量限度，以及物料平衡的计算方法和限度； 6.待包装产品的贮存要求，包括容器、标签、贮存时间及特殊贮存条件； 7.需要说明的注意事项。 （三）包装操作要求： 1.以最终包装容器中产品的数量、重量"},{"i":165,"n":"第一百六十五条","txt":"每批产品均应当有相应的批生产记录，记录的内容应确保该批产品的生产历史以及与质量有关的情况可追溯。"},{"i":166,"n":"第一百六十六条","txt":"批生产记录应当依据批准的现行工艺规程的相关内容制定。批生产记录的每一工序应当标注产品的名称、规格和批号。"},{"i":167,"n":"第一百六十七条","txt":"原版空白的批生产记录应当经生产管理负责人和质量管理负责人审核和批准。批生产记录的复制和发放均应当按照操作规程进行控制并有记录，每批产品的生产只能发放一份原版空白批生产记录的复制件。"},{"i":168,"n":"第一百六十八条","txt":"在生产过程中，进行每项操作时应当及时记录，操作结束后，应当由生产操作人员确认并签注姓名和日期。"},{"i":169,"n":"第一百六十九条","txt":"批生产记录的内容应当包括： （一）产品名称、规格、批号； （二）生产以及中间工序开始、结束的日期和时间； （三）每一生产工序的负责人签名； （四）生产步骤操作人员的签名；必要时，还应当有操作（如称量）复核人员的签名； （五）每一原辅料的批号以及实际称量的数量（包括投入的回收或返工处理产品的批号及数量）； （六）相关生产操作或活动、工艺参数及控制范围，以及所用主要生产设备的编号； （七）中间控制结果的记录以及操作人员的签名； （八）不同生产工序所得产量及必要时的物料平衡计算； （九）对特殊问题或异常事件的记录，包括对偏离工艺规程的偏差情况的详细说明或调查报告，并经签字批准。"},{"i":170,"n":"第一百七十条","txt":"产品的包装应当有批包装记录，以便追溯该批产品包装操作以及与质量有关的情况。"},{"i":171,"n":"第一百七十一条","txt":"批包装记录应当依据工艺规程中与包装相关的内容制定。"},{"i":172,"n":"第一百七十二条","txt":"批包装记录应当有待包装产品的批号、数量以及成品的批号和计划数量。原版空白的批包装记录的审核、批准、复制和发放的要求与原版空白的批生产记录相同。"},{"i":173,"n":"第一百七十三条","txt":"在包装过程中，进行每项操作时应当及时记录，操作结束后，应当由包装操作人员确认并签注姓名和日期。"},{"i":174,"n":"第一百七十四条","txt":"批包装记录的内容包括： （一）产品名称、规格、包装形式、批号、生产日期和有效期。 （二）包装操作日期和时间。 （三）包装操作负责人签名。 （四）包装工序的操作人员签名。 （五）每一包装材料的名称、批号和实际使用的数量。 （六）包装操作的详细情况，包括所用设备及包装生产线的编号。 （七）兽药产品赋电子追溯码标识操作的详细情况，包括所用设备、编号。电子追溯码信息以及对两级以上包装进行赋码关联关系信息等记录可采用电子方式保存。 （八）所用印刷包装材料的实样，并印有批号、有效期及其他打印内容；不易随批包装记录归档的印刷包装材料可采用印有上述内容的复制品。 （九）对特殊问题或异常事件的记录，包括对偏离工艺规程的偏差情况的详细说明或调查报告，并经签字批准。 （十）所有印刷包装材料和待包装产品的名称、代码，以及发放、使用、销毁或退库的数量、实际产量等的物料平衡检查。"},{"i":175,"n":"第一百七十五条","txt":"操作规程的内容应当包括：题目、编号、版本号、颁发部门、生效日期、分发部门以及制定人、审核人、批准人的签名并注明日期，标题、正文及变更历史。"},{"i":176,"n":"第一百七十六条","txt":"厂房、设备、物料、文件和记录应当有编号（代码），并制定编制编号（代码）的操作规程，确保编号（代码）的唯一性。"},{"i":177,"n":"第一百七十七条","txt":"下述活动也应当有相应的操作规程，其过程和结果应当有记录： （一）确认和验证； （二）设备的装配和校准； （三）厂房和设备的维护、清洁和消毒； （四）培训、更衣、卫生等与人员相关的事宜； （五）环境监测； （六）虫害控制； （七）变更控制； （八）偏差处理； （九）投诉； （十）兽药召回； （十一）退货。"},{"i":178,"n":"第一百七十八条","txt":"兽药生产应当按照批准的工艺规程和操作规程进行操作并有相关记录，确保兽药达到规定的质量标准，并符合兽药生产许可和注册批准的要求。"},{"i":179,"n":"第一百七十九条","txt":"应当建立划分产品生产批次的操作规程，生产批次的划分应当能够确保同一批次产品质量和特性的均一性。"},{"i":180,"n":"第一百八十条","txt":"应当建立编制兽药批号和确定生产日期的操作规程。每批兽药均应当编制唯一的批号。除另有法定要求外，生产日期不得迟于产品成型或灌装（封）前经最后混合的操作开始日期，不得以产品包装日期作为生产日期。"},{"i":181,"n":"第一百八十一条","txt":"每批产品应当检查产量和物料平衡，确保物料平衡符合设定的限度。如有差异，必须查明原因，确认无潜在质量风险后，方可按照正常产品处理。"},{"i":182,"n":"第一百八十二条","txt":"不得在同一生产操作间同时进行不同品种和规格兽药的生产操作，除非没有发生混淆或交叉污染的可能。"},{"i":183,"n":"第一百八十三条","txt":"在生产的每一阶段，应当保护产品和物料免受微生物和其他污染。"},{"i":184,"n":"第一百八十四条","txt":"在干燥物料或产品，尤其是高活性、高毒性或高致敏性物料或产品的生产过程中，应当采取特殊措施，防止粉尘的产生和扩散。"},{"i":185,"n":"第一百八十五条","txt":"生产期间使用的所有物料、中间产品的容器及主要设备、必要的操作室应当粘贴标签标识，或以其他方式标明生产中的产品或物料名称、规格和批号，如有必要，还应当标明生产工序。"},{"i":186,"n":"第一百八十六条","txt":"容器、设备或设施所用标识应当清晰明了，标识的格式应当经企业相关部门批准。除在标识上使用文字说明外，还可采用不同颜色区分被标识物的状态（如待验、合格、不合格或已清洁等）。"},{"i":187,"n":"第一百八十七条","txt":"应当检查产品从一个区域输送至另一个区域的管道和其他设备连接，确保连接正确无误。"},{"i":188,"n":"第一百八十八条","txt":"每次生产结束后应当进行清场，确保设备和工作场所没有遗留与本次生产有关的物料、产品和文件。下次生产开始前，应当对前次清场情况进行确认。"},{"i":189,"n":"第一百八十九条","txt":"应当尽可能避免出现任何偏离工艺规程或操作规程的偏差。一旦出现偏差，应当按照偏差处理操作规程执行。"},{"i":190,"n":"第一百九十条","txt":"生产过程中应当尽可能采取措施，防止污染和交叉污染，如： （一）在分隔的区域内生产不同品种的兽药； （二）采用阶段性生产方式； （三）设置必要的气锁间和排风；空气洁净度级别不同的区域应当有压差控制； （四）应当降低未经处理或未经充分处理的空气再次进入生产区导致污染的风险； （五）在易产生交叉污染的生产区内，操作人员应当穿戴该区域专用的防护服； （六）采用经过验证或已知有效的清洁和去污染操作规程进行设备清洁；必要时，应当对与物料直接接触的设备表面的残留物进行检测； （七）采用密闭系统生产； （八）干燥设备的进风应当有空气过滤器，且过滤后的空气洁净度应当与所干燥产品要求的洁净度相匹配，排风应当有防止空气倒流装置； （九）生产和清洁过程中应当避免使用易碎、易脱屑、易发霉器具；使用筛网时，应当有防止因筛网断裂而造成污染的措施； （十）液体制剂的配制、过滤、灌封、灭菌等工序应当在规定时间内完成；"},{"i":191,"n":"第一百九十一条","txt":"应当定期检查防止污染和交叉污染的措施并评估其适用性和有效性。"},{"i":192,"n":"第一百九十二条","txt":"生产开始前应当进行检查，确保设备和工作场所没有上批遗留的产品、文件和物料，设备处于已清洁及待用状态。检查结果应当有记录。 生产操作前，还应当核对物料或中间产品的名称、代码、批号和标识，确保生产所用物料或中间产品正确且符合要求。"},{"i":193,"n":"第一百九十三条","txt":"应当由配料岗位人员按照操作规程进行配料，核对物料后，精确称量或计量，并作好标识。"},{"i":194,"n":"第一百九十四条","txt":"配制的每一物料及其重量或体积应当由他人进行复核，并有复核记录。"},{"i":195,"n":"第一百九十五条","txt":"每批产品的每一生产阶段完成后必须由生产操作人员清场，并填写清场记录。清场记录内容包括：操作间名称或编号、产品名称、批号、生产工序、清场日期、检查项目及结果、清场负责人及复核人签名。清场记录应当纳入批生产记录。"},{"i":196,"n":"第一百九十六条","txt":"包装操作规程应当规定降低污染和交叉污染、混淆或差错风险的措施。"},{"i":197,"n":"第一百九十七条","txt":"包装开始前应当进行检查，确保工作场所、包装生产线、印刷机及其他设备已处于清洁或待用状态，无上批遗留的产品和物料。检查结果应当有记录。"},{"i":198,"n":"第一百九十八条","txt":"包装操作前，还应当检查所领用的包装材料正确无误，核对待包装产品和所用包装材料的名称、规格、数量、质量状态，且与工艺规程相符。"},{"i":199,"n":"第一百九十九条","txt":"每一包装操作场所或包装生产线，应当有标识标明包装中的产品名称、规格、批号和批量的生产状态。"},{"i":200,"n":"第二百条","txt":"有数条包装线同时进行包装时，应当采取隔离或其他有效防止污染、交叉污染或混淆的措施。"},{"i":201,"n":"第二百零一条","txt":"产品分装、封口后应当及时贴签。"},{"i":202,"n":"第二百零二条","txt":"单独打印或包装过程中在线打印、赋码的信息（如产品批号或有效期）均应当进行检查，确保其准确无误，并予以记录。如手工打印，应当增加检查频次。"},{"i":203,"n":"第二百零三条","txt":"使用切割式标签或在包装线以外单独打印标签，应当采取专门措施，防止混淆。"},{"i":204,"n":"第二百零四条","txt":"应当对电子读码机、标签计数器或其他类似装置的功能进行检查，确保其准确运行。检查应当有记录。"},{"i":205,"n":"第二百零五条","txt":"包装材料上印刷或模压的内容应当清晰，不易褪色和擦除。"},{"i":206,"n":"第二百零六条","txt":"包装期间，产品的中间控制检查应当至少包括以下内容： （一）包装外观； （二）包装是否完整； （三）产品和包装材料是否正确； （四）打印、赋码信息是否正确； （五）在线监控装置的功能是否正常。"},{"i":207,"n":"第二百零七条","txt":"因包装过程产生异常情况需要重新包装产品的，必须经专门检查、调查并由指定人员批准。重新包装应当有详细记录。"},{"i":208,"n":"第二百零八条","txt":"在物料平衡检查中，发现待包装产品、印刷包装材料以及成品数量有显著差异时，应当进行调查，未得出结论前，成品不得放行。"},{"i":209,"n":"第二百零九条","txt":"包装结束时，已打印批号的剩余包装材料应当由专人负责全部计数销毁，并有记录。如将未打印批号的印刷包装材料退库，应当按照操作规程执行。"},{"i":210,"n":"第二百一十条","txt":"质量控制实验室的人员、设施、设备和环境洁净要求应当与产品性质和生产规模相适应。"},{"i":211,"n":"第二百一十一条","txt":"质量控制负责人应当具有足够的管理实验室的资质和经验，可以管理同一企业的一个或多个实验室。"},{"i":212,"n":"第二百一十二条","txt":"质量控制实验室的检验人员至少应当具有药学、兽医学、生物学、化学等相关专业大专学历或从事检验工作3年以上的中专、高中以上学历，并经过与所从事的检验操作相关的实践培训且考核通过。"},{"i":213,"n":"第二百一十三条","txt":"质量控制实验室应当配备《中华人民共和国兽药典》、兽药质量标准、标准图谱等必要的工具书，以及标准品或对照品等相关的标准物质。"},{"i":214,"n":"第二百一十四条","txt":"质量控制实验室的文件应当符合第八章的原则，并符合下列要求： （一）质量控制实验室应当至少有下列文件： 1.质量标准； 2.取样操作规程和记录； 3.检验操作规程和记录（包括检验记录或实验室工作记事簿）； 4.检验报告或证书； 5.必要的环境监测操作规程、记录和报告； 6.必要的检验方法验证方案、记录和报告； 7.仪器校准和设备使用、清洁、维护的操作规程及记录。 （二）每批兽药的检验记录应当包括中间产品和成品的质量检验记录，可追溯该批兽药所有相关的质量检验情况； （三）应保存和统计（宜采用便于趋势分析的方法）相关的检验和监测数据（如检验数据、环境监测数据、制药用水的微生物监测数据）； （四）除与批记录相关的资料信息外，还应当保存与检验相关的其他原始资料或记录，便于追溯查阅。"},{"i":215,"n":"第二百一十五条","txt":"取样应当至少符合以下要求： （一）质量管理部门的人员可进入生产区和仓储区进行取样及调查； （二）应当按照经批准的操作规程取样，操作规程应当详细规定： 1.经授权的取样人； 2.取样方法； 3.取样用器具； 4.样品量； 5.分样的方法； 6.存放样品容器的类型和状态； 7.实施取样后物料及样品的处置和标识； 8.取样注意事项，包括为降低取样过程产生的各种风险所采取的预防措施，尤其是无菌或有害物料的取样以及防止取样过程中污染和交叉污染的取样注意事项； 9.贮存条件； 10.取样器具的清洁方法和贮存要求。 （三）取样方法应当科学、合理，以保证样品的代表性； （四）样品应当能够代表被取样批次的产品或物料的质量状况，为监控生产过程中最重要的环节（如生产初始或结束），也可抽取该阶段样品进行检测； （五）样品容器应当贴有标签，注明样品名称、批号、取样人、取样日期等信息； （六）样品应当按照被取样产"},{"i":216,"n":"第二百一十六条","txt":"物料和不同生产阶段产品的检验应当至少符合以下要求： （一）企业应当确保成品按照质量标准进行全项检验。 （二）有下列情形之一的，应当对检验方法进行验证： 1.采用新的检验方法； 2.检验方法需变更的； 3.采用《中华人民共和国兽药典》及其他法定标准未收载的检验方法； 4.法规规定的其他需要验证的检验方法。 （三）对不需要进行验证的检验方法，必要时企业应当对检验方法进行确认，确保检验数据准确、可靠。 （四）检验应当有书面操作规程，规定所用方法、仪器和设备，检验操作规程的内容应当与经确认或验证的检验方法一致。 （五）检验应当有可追溯的记录并应当复核，确保结果与记录一致。所有计算均应当严格核对。 （六）检验记录应当至少包括以下内容： 1.产品或物料的名称、剂型、规格、批号或供货批号，必要时注明供应商和生产商（如不同）的名称或来源； 2.依据的质量标准和检验操作规程； 3.检验所用的仪器或设备的"},{"i":217,"n":"第二百一十七条","txt":"质量控制实验室应当建立检验结果超标调查的操作规程。任何检验结果超标都必须按照操作规程进行调查，并有相应的记录。"},{"i":218,"n":"第二百一十八条","txt":"企业按规定保存的、用于兽药质量追溯或调查的物料、产品样品为留样。用于产品稳定性考察的样品不属于留样。 留样应当至少符合以下要求： （一）应当按照操作规程对留样进行管理。 （二）留样应当能够代表被取样批次的物料或产品。 （三）成品的留样： 1.每批兽药均应当有留样；如果一批兽药分成数次进行包装，则每次包装至少应当保留一件最小市售包装的成品； 2.留样的包装形式应当与兽药市售包装形式相同，大包装规格或原料药的留样如无法采用市售包装形式的，可采用模拟包装； 3.每批兽药的留样量一般至少应当能够确保按照批准的质量标准完成两次全检（无菌检查和热原检查等除外）； 4.如果不影响留样的包装完整性，保存期间内至少应当每年对留样进行一次目检或接触观察，如发现异常，应当调查分析原因并采取相应的处理措施； 5.留样观察应当有记录； 6.留样应当按照注册批准的贮存条件至少保存至兽药有效期后一年； 7.企业终止"},{"i":219,"n":"第二百一十九条","txt":"试剂、试液、培养基和检定菌的管理应当至少符合以下要求： （一）商品化试剂和培养基应当从可靠的、有资质的供应商处采购，必要时应当对供应商进行评估。 （二）应当有接收试剂、试液、培养基的记录，必要时，应当在试剂、试液、培养基的容器上标注接收日期和首次开口日期、有效期（如有）。 （三）应当按照相关规定或使用说明配制、贮存和使用试剂、试液和培养基。特殊情况下，在接收或使用前，还应当对试剂进行鉴别或其他检验。 （四）试液和已配制的培养基应当标注配制批号、配制日期和配制人员姓名，并有配制（包括灭菌）记录。不稳定的试剂、试液和培养基应当标注有效期及特殊贮存条件。标准液、滴定液还应当标注最后一次标化的日期和校正因子，并有标化记录。 （五）配制的培养基应当进行适用性检查，并有相关记录。应当有培养基使用记录。 （六）应当有检验所需的各种检定菌，并建立检定菌保存、传代、使用、销毁的操作规程和相应记录。 （七"},{"i":220,"n":"第二百二十条","txt":"标准品或对照品的管理应当至少符合以下要求： （一）标准品或对照品应当按照规定贮存和使用； （二）标准品或对照品应当有适当的标识，内容至少包括名称、批号、制备日期（如有）、有效期（如有）、首次开启日期、含量或效价、贮存条件； （三）企业如需自制工作标准品或对照品，应当建立工作标准品或对照品的质量标准以及制备、鉴别、检验、批准和贮存的操作规程，每批工作标准品或对照品应当用法定标准品或对照品进行标化，并确定有效期，还应当通过定期标化证明工作标准品或对照品的效价或含量在有效期内保持稳定。标化的过程和结果应当有相应的记录。"},{"i":221,"n":"第二百二十一条","txt":"应当分别建立物料和产品批准放行的操作规程，明确批准放行的标准、职责，并有相应的记录。"},{"i":222,"n":"第二百二十二条","txt":"物料的放行应当至少符合以下要求： （一）物料的质量评价内容应当至少包括生产商的检验报告、物料入库接收初验情况（是否为合格供应商、物料包装完整性和密封性的检查情况等）和检验结果； （二）物料的质量评价应当有明确的结论，如批准放行、不合格或其他决定； （三）物料应当由指定的质量管理人员签名批准放行。"},{"i":223,"n":"第二百二十三条","txt":"产品的放行应当至少符合以下要求： （一）在批准放行前，应当对每批兽药进行质量评价，并确认以下各项内容： 1.已完成所有必需的检查、检验，批生产和检验记录完整； 2.所有必需的生产和质量控制均已完成并经相关主管人员签名； 3.确认与该批相关的变更或偏差已按照相关规程处理完毕，包括所有必要的取样、检查、检验和审核； 4.所有与该批产品有关的偏差均已有明确的解释或说明，或者已经过彻底调查和适当处理；如偏差还涉及其他批次产品，应当一并处理。 （二）兽药的质量评价应当有明确的结论，如批准放行、不合格或其他决定。 （三）每批兽药均应当由质量管理负责人签名批准放行。 （四）兽用生物制品放行前还应当取得批签发合格证明。"},{"i":224,"n":"第二百二十四条","txt":"持续稳定性考察的目的是在有效期内监控已上市兽药的质量，以发现兽药与生产相关的稳定性问题（如杂质含量或溶出度特性的变化），并确定兽药能够在标示的贮存条件下，符合质量标准的各项要求。"},{"i":225,"n":"第二百二十五条","txt":"持续稳定性考察主要针对市售包装兽药，但也需兼顾待包装产品。此外，还应当考虑对贮存时间较长的中间产品进行考察。"},{"i":226,"n":"第二百二十六条","txt":"持续稳定性考察应当有考察方案，结果应当有报告。用于持续稳定性考察的设备（即稳定性试验设备或设施）应当按照第七章和第五章的要求进行确认和维护。"},{"i":227,"n":"第二百二十七条","txt":"持续稳定性考察的时间应当涵盖兽药有效期，考察方案应当至少包括以下内容： （一）每种规格、每种生产批量兽药的考察批次数； （二）相关的物理、化学、微生物和生物学检验方法，可考虑采用稳定性考察专属的检验方法； （三）检验方法依据； （四）合格标准； （五）容器密封系统的描述； （六）试验间隔时间（测试时间点）； （七）贮存条件（应当采用与兽药标示贮存条件相对应的《中华人民共和国兽药典》规定的长期稳定性试验标准条件）； （八）检验项目，如检验项目少于成品质量标准所包含的项目，应当说明理由。"},{"i":228,"n":"第二百二十八条","txt":"考察批次数和检验频次应当能够获得足够的数据，用于趋势分析。通常情况下，每种规格、每种内包装形式至少每年应当考察一个批次，除非当年没有生产。"},{"i":229,"n":"第二百二十九条","txt":"某些情况下，持续稳定性考察中应当额外增加批次数，如重大变更或生产和包装有重大偏差的兽药应当列入稳定性考察。此外，重新加工、返工或回收的批次，也应当考虑列入考察，除非已经过验证和稳定性考察。"},{"i":230,"n":"第二百三十条","txt":"应当对不符合质量标准的结果或重要的异常趋势进行调查。对任何已确认的不符合质量标准的结果或重大不良趋势，企业都应当考虑是否可能对已上市兽药造成影响，必要时应当实施召回，调查结果以及采取的措施应当报告当地畜牧兽医主管部门。"},{"i":231,"n":"第二百三十一条","txt":"应当根据获得的全部数据资料，包括考察的阶段性结论，撰写总结报告并保存。应当定期审核总结报告。"},{"i":232,"n":"第二百三十二条","txt":"企业应当建立变更控制系统，对所有影响产品质量的变更进行评估和管理。"},{"i":233,"n":"第二百三十三条","txt":"企业应当建立变更控制操作规程，规定原辅料、包装材料、质量标准、检验方法、操作规程、厂房、设施、设备、仪器、生产工艺和计算机软件变更的申请、评估、审核、批准和实施。质量管理部门应当指定专人负责变更控制。"},{"i":234,"n":"第二百三十四条","txt":"企业可以根据变更的性质、范围、对产品质量潜在影响的程度进行变更分类（如主要、次要变更）并建档。"},{"i":235,"n":"第二百三十五条","txt":"与产品质量有关的变更由申请部门提出后，应当经评估、制定实施计划并明确实施职责，由质量管理部门审核批准后实施，变更实施应当有相应的完整记录。"},{"i":236,"n":"第二百三十六条","txt":"改变原辅料、与兽药直接接触的包装材料、生产工艺、主要生产设备以及其他影响兽药质量的主要因素时，还应当根据风险评估对变更实施后最初至少三个批次的兽药质量进行评估。如果变更可能影响兽药的有效期，则质量评估还应当包括对变更实施后生产的兽药进行稳定性考察。"},{"i":237,"n":"第二百三十七条","txt":"变更实施时，应当确保与变更相关的文件均已修订。"},{"i":238,"n":"第二百三十八条","txt":"质量管理部门应当保存所有变更的文件和记录。"},{"i":239,"n":"第二百三十九条","txt":"各部门负责人应当确保所有人员正确执行生产工艺、质量标准、检验方法和操作规程，防止偏差的产生。"},{"i":240,"n":"第二百四十条","txt":"企业应当建立偏差处理的操作规程，规定偏差的报告、记录、评估、调查、处理以及所采取的纠正、预防措施，并保存相应的记录。"},{"i":241,"n":"第二百四十一条","txt":"企业应当评估偏差对产品质量的潜在影响。质量管理部门可以根据偏差的性质、范围、对产品质量潜在影响的程度进行偏差分类（如重大、次要偏差），对重大偏差的评估应当考虑是否需要对产品进行额外的检验以及产品是否可以放行，必要时，应当对涉及重大偏差的产品进行稳定性考察。"},{"i":242,"n":"第二百四十二条","txt":"任何偏离生产工艺、物料平衡限度、质量标准、检验方法、操作规程等的情况均应当有记录，并立即报告主管人员及质量管理部门，重大偏差应当由质量管理部门会同其他部门进行彻底调查，并有调查报告。偏差调查应当包括相关批次产品的评估，偏差调查报告应当由质量管理部门的指定人员审核并签字。"},{"i":243,"n":"第二百四十三条","txt":"质量管理部门应当保存偏差调查、处理的文件和记录。"},{"i":244,"n":"第二百四十四条","txt":"企业应当建立纠正措施和预防措施系统，对投诉、召回、偏差、自检或外部检查结果、工艺性能和质量监测趋势等进行调查并采取纠正和预防措施。调查的深度和形式应当与风险的级别相适应。纠正措施和预防措施系统应当能够增进对产品和工艺的理解，改进产品和工艺。"},{"i":245,"n":"第二百四十五条","txt":"企业应当建立实施纠正和预防措施的操作规程，内容至少包括： （一）对投诉、召回、偏差、自检或外部检查结果、工艺性能和质量监测趋势以及其他来源的质量数据进行分析，确定已有和潜在的质量问题； （二）调查与产品、工艺和质量保证系统有关的原因； （三）确定需采取的纠正和预防措施，防止问题的再次发生； （四）评估纠正和预防措施的合理性、有效性和充分性； （五）对实施纠正和预防措施过程中所有发生的变更应当予以记录； （六）确保相关信息已传递到质量管理负责人和预防问题再次发生的直接负责人； （七）确保相关信息及其纠正和预防措施已通过高层管理人员的评审。"},{"i":246,"n":"第二百四十六条","txt":"实施纠正和预防措施应当有文件记录，并由质量管理部门保存。"},{"i":247,"n":"第二百四十七条","txt":"质量管理部门应当对生产用关键物料的供应商进行质量评估，必要时会同有关部门对主要物料供应商（尤其是生产商）的质量体系进行现场质量考查，并对质量评估不符合要求的供应商行使否决权。"},{"i":248,"n":"第二百四十八条","txt":"应当建立物料供应商评估和批准的操作规程，明确供应商的资质、选择的原则、质量评估方式、评估标准、物料供应商批准的程序。 如质量评估需采用现场质量考查方式的，还应当明确考查内容、周期、考查人员的组成及资质。需采用样品小批量试生产的，还应当明确生产批量、生产工艺、产品质量标准、稳定性考察方案。"},{"i":249,"n":"第二百四十九条","txt":"质量管理部门应当指定专人负责物料供应商质量评估和现场质量考查，被指定的人员应当具有相关的法规和专业知识，具有足够的质量评估和现场质量考查的实践经验。"},{"i":250,"n":"第二百五十条","txt":"现场质量考查应当核实供应商资质证明文件。应当对其人员机构、厂房设施和设备、物料管理、生产工艺流程和生产管理、质量控制实验室的设备、仪器、文件管理等进行检查，以全面评估其质量保证系统。现场质量考查应当有报告。"},{"i":251,"n":"第二百五十一条","txt":"必要时，应当对主要物料供应商提供的样品进行小批量试生产，并对试生产的兽药进行稳定性考察。"},{"i":252,"n":"第二百五十二条","txt":"质量管理部门对物料供应商的评估至少应当包括：供应商的资质证明文件、质量标准、检验报告、企业对物料样品的检验数据和报告。如进行现场质量考查和样品小批量试生产的，还应当包括现场质量考查报告，以及小试产品的质量检验报告和稳定性考察报告。"},{"i":253,"n":"第二百五十三条","txt":"改变物料供应商，应当对新的供应商进行质量评估；改变主要物料供应商的，还需要对产品进行相关的验证及稳定性考察。"},{"i":254,"n":"第二百五十四条","txt":"质量管理部门应当向物料管理部门分发经批准的合格供应商名单，该名单内容至少包括物料名称、规格、质量标准、生产商名称和地址、经销商（如有）名称等，并及时更新。"},{"i":255,"n":"第二百五十五条","txt":"质量管理部门应当与主要物料供应商签订质量协议，在协议中应当明确双方所承担的质量责任。"},{"i":256,"n":"第二百五十六条","txt":"质量管理部门应当定期对物料供应商进行评估或现场质量考查，回顾分析物料质量检验结果、质量投诉和不合格处理记录。如物料出现质量问题或生产条件、工艺、质量标准和检验方法等可能影响质量的关键因素发生重大改变时，还应当尽快进行相关的现场质量考查。"},{"i":257,"n":"第二百五十七条","txt":"企业应当对每家物料供应商建立质量档案，档案内容应当包括供应商资质证明文件、质量协议、质量标准、样品检验数据和报告、供应商检验报告、供应商评估报告、定期的质量回顾分析报告等。"},{"i":258,"n":"第二百五十八条","txt":"企业应当建立产品质量回顾分析操作规程，每年对所有生产的兽药按品种进行产品质量回顾分析，以确认工艺稳定可靠性，以及原辅料、成品现行质量标准的适用性，及时发现不良趋势，确定产品及工艺改进的方向。 企业至少应当对下列情形进行回顾分析： （一）产品所用原辅料的所有变更，尤其是来自新供应商的原辅料； （二）关键中间控制点及成品的检验结果以及趋势图； （三）所有不符合质量标准的批次及其调查； （四）所有重大偏差及变更相关的调查、所采取的纠正措施和预防措施的有效性； （五）稳定性考察的结果及任何不良趋势； （六）所有因质量原因造成的退货、投诉、召回及调查； （七）当年执行法规自查情况； （八）验证评估概述； （九）对该产品该年度质量评估和总结。"},{"i":259,"n":"第二百五十九条","txt":"应当对回顾分析的结果进行评估，提出是否需要采取纠正和预防措施，并及时、有效地完成整改。"},{"i":260,"n":"第二百六十条","txt":"应当建立兽药投诉与不良反应报告制度，设立专门机构并配备专职人员负责管理。"},{"i":261,"n":"第二百六十一条","txt":"应当主动收集兽药不良反应，对不良反应应当详细记录、评价、调查和处理，及时采取措施控制可能存在的风险，并按照要求向企业所在地畜牧兽医主管部门报告。"},{"i":262,"n":"第二百六十二条","txt":"应当建立投诉操作规程，规定投诉登记、评价、调查和处理的程序，并规定因可能的产品缺陷发生投诉时所采取的措施，包括考虑是否有必要从市场召回兽药。"},{"i":263,"n":"第二百六十三条","txt":"应当有专人负责进行质量投诉的调查和处理，所有投诉、调查的信息应当向质量管理负责人通报。"},{"i":264,"n":"第二百六十四条","txt":"投诉调查和处理应当有记录，并注明所查相关批次产品的信息。"},{"i":265,"n":"第二百六十五条","txt":"应当定期回顾分析投诉记录，以便发现需要预防、重复出现以及可能需要从市场召回兽药的问题，并采取相应措施。"},{"i":266,"n":"第二百六十六条","txt":"企业出现生产失误、兽药变质或其他重大质量问题，应当及时采取相应措施，必要时还应当向当地畜牧兽医主管部门报告。"},{"i":267,"n":"第二百六十七条","txt":"企业应当建立产品召回系统，必要时可迅速、有效地从市场召回任何一批存在安全隐患的产品。"},{"i":268,"n":"第二百六十八条","txt":"因质量原因退货和召回的产品，均应当按照规定监督销毁，有证据证明退货产品质量未受影响的除外。"},{"i":269,"n":"第二百六十九条","txt":"企业应当建立产品销售管理制度，并有销售记录。根据销售记录，应当能够追查每批产品的销售情况，必要时应当能够及时全部追回。"},{"i":270,"n":"第二百七十条","txt":"每批产品均应当有销售记录。销售记录内容应当包括：产品名称、规格、批号、数量、收货单位和地址、联系方式、发货日期、运输方式等。"},{"i":271,"n":"第二百七十一条","txt":"产品上市销售前，应将产品生产和入库信息上传到国家兽药产品追溯系统。销售出库时，需向国家兽药产品追溯系统上传产品出库信息。"},{"i":272,"n":"第二百七十二条","txt":"兽药的零头可直接销售，若需合箱，包装只限两个批号为一个合箱，合箱外应当标明全部批号，并建立合箱记录。"},{"i":273,"n":"第二百七十三条","txt":"销售记录应当至少保存至兽药有效期后一年。"},{"i":274,"n":"第二百七十四条","txt":"应当制定召回操作规程，确保召回工作的有效性。"},{"i":275,"n":"第二百七十五条","txt":"应当指定专人负责组织协调召回工作，并配备足够数量的人员。如产品召回负责人不是质量管理负责人，则应当向质量管理负责人通报召回处理情况。"},{"i":276,"n":"第二百七十六条","txt":"召回应当随时启动，产品召回负责人应当根据销售记录迅速组织召回。"},{"i":277,"n":"第二百七十七条","txt":"因产品存在安全隐患决定从市场召回的，应当立即向当地畜牧兽医主管部门报告。"},{"i":278,"n":"第二百七十八条","txt":"已召回的产品应当有标识，并单独、妥善贮存，等待最终处理决定。"},{"i":279,"n":"第二百七十九条","txt":"召回的进展过程应当有记录，并有最终报告。产品销售数量、已召回数量以及数量平衡情况应当在报告中予以说明。"},{"i":280,"n":"第二百八十条","txt":"应当定期对产品召回系统的有效性进行评估。"},{"i":281,"n":"第二百八十一条","txt":"质量管理部门应当定期组织对企业进行自检，监控本规范的实施情况，评估企业是否符合本规范要求，并提出必要的纠正和预防措施。"},{"i":282,"n":"第二百八十二条","txt":"自检应当有计划，对机构与人员、厂房与设施、设备、物料与产品、确认与验证、文件管理、生产管理、质量控制与质量保证、产品销售与召回等项目定期进行检查。"},{"i":283,"n":"第二百八十三条","txt":"应当由企业指定人员进行独立、系统、全面的自检，也可由外部人员或专家进行独立的质量审计。"},{"i":284,"n":"第二百八十四条","txt":"自检应当有记录。自检完成后应当有自检报告，内容至少包括自检过程中观察到的所有情况、评价的结论以及提出纠正和预防措施的建议。有关部门和人员应立即进行整改，自检和整改情况应当报告企业高层管理人员。"},{"i":285,"n":"第二百八十五条","txt":"本规范为兽药生产质量管理的基本要求。对不同类别兽药或生产质量管理活动的特殊要求，列入本规范附录，另行以公告发布。"},{"i":286,"n":"第二百八十六条","txt":"本规范中下列用语的含义是： （一）包装材料，是指兽药包装所用的材料，包括与兽药直接接触的包装材料和容器、印刷包装材料，但不包括运输用的外包装材料。 （二）操作规程，是指经批准用来指导设备操作、维护与清洁、验证、环境控制、生产操作、取样和检验等兽药生产活动的通用性文件，也称标准操作规程。 （三）产品生命周期，是指产品从最初的研发、上市直至退市的所有阶段。 （四）成品，是指已完成所有生产操作步骤和最终包装的产品。 （五）重新加工，是指将某一生产工序生产的不符合质量标准的一批中间产品的一部分或全部，采用不同的生产工艺进行再加工，以符合预定的质量标准。 （六）待验，是指原辅料、包装材料、中间产品或成品，采用物理手段或其他有效方式将其隔离或区分，在允许用于投料生产或上市销售之前贮存、等待作出放行决定的状态。 （七）发放，是指生产过程中物料、中间产品、文件、生产用模具等在企业内部流转的一系列操作。"},{"i":287,"n":"第二百八十七条","txt":"本规范自2020年6月1日起施行。具体实施要求另行公告。"}],"shouyaojingyingzhiliangguanliguifan":[{"i":1,"n":"第一条","txt":"为加强兽药经营质量管理，保证兽药质量，根据《兽药管理条例》，制定本规范。"},{"i":2,"n":"第二条","txt":"本规范适用于中华人民共和国境内的兽药经营企业。"},{"i":3,"n":"第三条","txt":"兽药经营企业应当具有固定的经营场所和仓库，其面积应当符合省、自治区、直辖市人民政府兽医行政管理部门的规定。经营场所和仓库应当布局合理，相对独立。 经营场所的面积、设施和设备应当与经营的兽药品种、经营规模相适应。兽药经营区域与生活区域、动物诊疗区域应当分别独立设置，避免交叉污染。"},{"i":4,"n":"第四条","txt":"兽药经营企业的经营地点应当与《兽药经营许可证》载明的地点一致。《兽药经营许可证》应当悬挂在经营场所的显著位置。 变更经营地点的，应当申请换发兽药经营许可证。 变更经营场所面积的，应当在变更后30个工作日内向发证机关备案。"},{"i":5,"n":"第五条","txt":"兽药经营企业应当具有与经营的兽药品种、经营规模适应并能够保证兽药质量的常温库、阴凉库(柜)、冷库(柜)等仓库和相关设施、设备。 仓库面积和相关设施、设备应当满足合格兽药区、不合格兽药区、待验兽药区、退货兽药区等不同区域划分和不同兽药品种分区、分类保管、储存的要求。 变更仓库位置，增加、减少仓库数量、面积以及相关设施、设备的，应当在变更后30个工作日内向发证机关备案。"},{"i":6,"n":"第六条","txt":"兽药直营连锁经营企业在同一县(市)内有多家经营门店的，可以统一配置仓储和相关设施、设备。"},{"i":7,"n":"第七条","txt":"兽药经营企业的经营场所和仓库的地面、墙壁、顶棚等应当平整、光洁，门、窗应当严密、易清洁。"},{"i":8,"n":"第八条","txt":"兽药经营企业的经营场所和仓库应当具有下列设施、设备： (一)与经营兽药相适应的货架、柜台； (二)避光、通风、照明的设施、设备； (三)与储存兽药相适应的控制温度、湿度的设施、设备； (四)防尘、防潮、防霉、防污染和防虫、防鼠、防鸟的设施、设备； (五)进行卫生清洁的设施、设备等。 (六)实施兽药电子追溯管理的相关设备。"},{"i":9,"n":"第九条","txt":"兽药经营企业经营场所和仓库的设施、设备应当齐备、整洁、完好，并根据兽药品种、类别、用途等设立醒目标志。"},{"i":10,"n":"第十条","txt":"兽药经营企业直接负责的主管人员应当熟悉兽药管理法律、法规及政策规定，具备相应兽药专业知识。"},{"i":11,"n":"第十一条","txt":"兽药经营企业应当配备与经营兽药相适应的质量管理人员。有条件的，可以建立质量管理机构。"},{"i":12,"n":"第十二条","txt":"兽药经营企业主管质量的负责人和质量管理机构的负责人应当具备相应兽药专业知识，且其专业学历或技术职称应当符合省、自治区、直辖市人民政府兽医行政管理部门的规定。 兽药质量管理人员应当具有兽药、兽医等相关专业中专以上学历，或者具有兽药、兽医等相关专业初级以上专业技术职称。经营兽用生物制品的，兽药质量管理人员应当具有兽药、兽医等相关专业大专以上学历，或者具有兽药、兽医等相关专业中级以上专业技术职称，并具备兽用生物制品专业知识。 兽药质量管理人员不得在本企业以外的其他单位兼职。 主管质量的负责人、质量管理机构的负责人、质量管理人员发生变更的，应当在变更后30个工作日内向发证机关备案。"},{"i":13,"n":"第十三条","txt":"兽药经营企业从事兽药采购、保管、销售、技术服务等工作的人员，应当具有高中以上学历，并具有相应兽药、兽医等专业知识，熟悉兽药管理法律、法规及政策规定。"},{"i":14,"n":"第十四条","txt":"兽药经营企业应当制定培训计划，定期对员工进行兽药管理法律、法规、政策规定和相关专业知识、职业道德培训、考核，并建立培训、考核档案。"},{"i":15,"n":"第十五条","txt":"兽药经营企业应当建立质量管理体系，制定管理制度、操作程序等质量管理文件。 质量管理文件应当包括下列内容： (一)企业质量管理目标； (二)企业组织机构、岗位和人员职责； (三)对供货单位和所购兽药的质量评估制度； (四)兽药采购、验收、入库、陈列、储存、运输、销售、出库等环节的管理制度； (五)环境卫生的管理制度； (六)兽药不良反应报告制度； (七)不合格兽药和退货兽药的管理制度； (八)质量事故、质量查询和质量投诉的管理制度； (九)企业记录、档案和凭证的管理制度； (十)质量管理培训、考核制度。 (十一)兽药产品追溯管理制度。"},{"i":16,"n":"第十六条","txt":"兽药经营企业应当建立下列记录： (一)人员培训、考核记录； (二)控制温度、湿度的设施、设备的维护、保养、清洁、运行状态记录； (三)兽药质量评估记录； (四)兽药采购、验收、入库、储存、销售、出库等记录； (五)兽药清查记录； (六)兽药质量投诉、质量纠纷、质量事故、不良反应等记录； (七)不合格兽药和退货兽药的处理记录； (八)兽医行政管理部门的监督检查情况记录。 (九)兽药产品追溯记录。 记录应当真实、准确、完整、清晰，不得随意涂改、伪造和变造。确需修改的，应当签名、注明日期，原数据应当清晰可辨。"},{"i":17,"n":"第十七条","txt":"兽药经营企业应当建立兽药质量管理档案，设置档案管理室或者档案柜，并由专人负责。 质量管理档案应当包括： (一)人员档案、培训档案、设备设施档案、供应商质量评估档案、产品质量档案； (二)开具的处方、进货及销售凭证； (三)购销记录及本规范规定的其他记录。 质量管理档案不得涂改，保存期限不得少于2年；购销等记录和凭证应当保存至产品有效期后一年。"},{"i":18,"n":"第十八条","txt":"兽药经营企业应当采购合法兽药产品。兽药经营企业应当对供货单位的资质、质量保证能力、质量信誉和产品批准证明文件进行审核，并与供货单位签订采购合同。"},{"i":19,"n":"第十九条","txt":"兽药经营企业购进兽药时，应当依照国家兽药管理规定、兽药标准和合同约定，对每批兽药的包装、标签、说明书、质量合格证等内容进行检查，符合要求的方可购进。必要时，应当对购进兽药进行检验或者委托兽药检验机构进行检验，检验报告应当与产品质量档案一起保存。 兽药经营企业应当保存采购兽药的有效凭证，建立真实、完整的采购记录，做到有效凭证、账、货相符。采购记录应当载明兽药的通用名称、商品名称、批准文号、批号、剂型、规格、有效期、生产单位、供货单位、购入数量、购入日期、经手人或者负责入等内容。"},{"i":20,"n":"第二十条","txt":"兽药入库时，应当进行检查验收，将兽药入库的信息上传兽药产品追溯系统，并做好记录。 有下列情形之一的兽药，不得入库： (一)与进货单不符的； (二)内、外包装破损可能影响产品质量的； (三)没有标识或者标识模糊不清的； (四)质量异常的； (五)其他不符合规定的。 兽用生物制品入库，应当由两人以上进行检查验收。"},{"i":21,"n":"第二十一条","txt":"陈列、储存兽药应当符合下列要求： (一)按照品种、类别、用途以及温度、湿度等储存要求，分类、分区或者专库存放； (二)按照兽药外包装图示标志的要求搬运和存放； (三)与仓库地面、墙、顶等之间保持一定间距； (四)内用兽药与外用兽药分开存放，兽用处方药与非处方药分开存放；易串味兽药、危险药品等特殊兽药与其他兽药分库存放； (五)待验兽药、合格兽药、不合格兽药、退货兽药分区存放； (六)同一企业的同一批号的产品集中存放。"},{"i":22,"n":"第二十二条","txt":"不同区域、不同类型的兽药应当具有明显的识别标识。标识应当放置准确、字迹清楚。 不合格兽药以红色字体标识；待验和退货兽药以黄色字体标识；合格兽药以绿色字体标识。"},{"i":23,"n":"第二十三条","txt":"兽药经营企业应当定期对兽药及其陈列、储存的条件和设施、设备的运行状态进行检查，并做好记录。"},{"i":24,"n":"第二十四条","txt":"兽药经营企业应当及时清查兽医行政管理部门公布的假劣兽药，并做好记录。"},{"i":25,"n":"第二十五条","txt":"兽药经营企业销售兽药，应当遵循先产先出和按批号出库的原则。兽药出库时，应当进行检查、核对，建立出库记录，并将出库信息上传兽药产品追溯系统。兽药出库记录应当包括兽药通用名称、商品名称、批号、剂型、规格、生产厂商、数量、日期、经手人或者负责人等内容。 有下列情形之一的兽药，不得出库销售： (一)标识模糊不清或者脱落的； (二)外包装出现破损、封口不牢、封条严重损坏的； (三)超出有效期限的； (四)其他不符合规定的。"},{"i":26,"n":"第二十六条","txt":"兽药经营企业应当建立销售记录。销售记录应当载明兽药通用名称、商品名称、批准文号、批号、有效期、剂型、规格、生产厂商、购货单位、销售数量、销售日期、经手人或者负责人等内容。"},{"i":27,"n":"第二十七条","txt":"兽药经营企业销售兽药，应当开具有效凭证，做到有效凭证、账、货、记录相符。"},{"i":28,"n":"第二十八条","txt":"兽药经营企业销售兽用处方药的，应当遵守兽用处方药管理规定；销售兽用中药材、中药饮片的，应当注明产地。"},{"i":29,"n":"第二十九条","txt":"兽药拆零销售时，不得拆开最小销售单元。"},{"i":30,"n":"第三十条","txt":"兽药经营企业应当按照兽药外包装图示标志的要求运输兽药。有温度控制要求的兽药，在运输时应当采取必要的温度控制措施，并建立详细记录。"},{"i":31,"n":"第三十一条","txt":"兽药经营企业应当按照兽医行政管理部门批准的兽药标签、说明书及其他规定进行宣传，不得误导购买者。"},{"i":32,"n":"第三十二条","txt":"兽药经营企业应当向购买者提供技术咨询服务，在经营场所明示服务公约和质量承诺，指导购买者科学、安全、合理使用兽药。"},{"i":33,"n":"第三十三条","txt":"兽药经营企业应当注意收集兽药使用信息，发现假、劣兽药和质量可疑兽药以及严重兽药不良反应时，应当及时向所在地兽医行政管理部门报告，并根据规定做好相关工作。"},{"i":34,"n":"第三十四条","txt":"兽药经营企业经营兽用麻醉药品、精神药品、易制毒化学药品、毒性药品、放射性药品等特殊药品，还应当遵守国家其他有关规定。"},{"i":35,"n":"第三十五条","txt":"动物防疫机构依法从事兽药经营活动的，应当遵守本规范。"},{"i":36,"n":"第三十六条","txt":"各省、自治区、直辖市人民政府兽医行政管理部门可以根据本规范，结合本地实际，制定实施细则，并报农业部备案。"},{"i":37,"n":"第三十七条","txt":"本规范自2010年3月1日起施行。本规范施行前已开办的兽药经营企业，应当自本规范施行之日起24个月内达到本规范的要求，并依法申领兽药经营许可证。"}],"shouyaozhiliangjianduchouyangguiding":[{"i":1,"n":"第一条","txt":"为加强和规范兽药质量监督抽样工作，保证抽样工作的科学性和公正性，根据《兽药管理条例》的有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"依照《兽药管理条例》第三十条规定设立的《兽药监药生产许可证》及《营业执照》，被抽样兽药品种的批准证明文件、质量标准、生产记录、兽药检验报告书、生产量、库存量、销售量和销售记录，以及主要原料进货证明（包括发票、合同、调拨单、检察机构，根据省级以上农牧行政主管部门制定的抽样规划或者执法监督的需要，实施兽药质量监督抽样工作。"},{"i":3,"n":"第三条","txt":"抽样人员应熟悉兽药管理法规，具有专业技术知识，掌握抽样工作程序和抽样操作技术。"},{"i":4,"n":"第四条","txt":"兽药监察机构抽样时，抽样人员不得少于两人，并应当主动向被抽样单位或者个人出示抽样任务书。 兽药监察机构抽样时，被抽样的单位应当予以配合；抽样人员不能出示抽样任务书的，被抽样单位有权拒绝。"},{"i":5,"n":"第五条","txt":"被抽样单位应根据抽样工作的需要出具以下资料： （一）兽药生产企业提供（兽验报告书）等相关资料；有进口兽药原料药及用于分装的进口兽药的，还需提供《进口兽药许可证》、口岸兽药监察所出具的检验报告或其复印件： （二）兽药制剂室提供《兽药制剂许可证》、被抽样兽药制剂的批准证明文件、质量标准、生产记录、兽药检验报告书、批生产量、库存量和使用量，以及主要原料进货证明（包括发票、合同、调拨单、检验报告书）等相关资料；有进口兽药原料药的，还需提供《进口兽药许可证》、口岸兽药监察所出具的检验报告或其复印件； （三）兽药经营企业提供《兽药经营许可证》及《营业执照》，被抽样兽药品种的进货凭证（包括发票、合同、调拨单）、购销记录及库存量等相关资料；有进口兽药的，还需提供《进口兽药许可证》、口岸兽药监察所出具的检验报告或其复印件。 抽样人员应当核实前款规定的各项证明资料，并负有保密义务。"},{"i":6,"n":"第六条","txt":"兽药抽样应在被抽样单位存放兽药产品的现场进行，包括兽药生产企业成品仓库和药用原、辅料仓库；兽药经营企业的仓库或营业场所；兽医医疗机构的药房或药库；以及其他需要抽样的场所。 抽样品种由下达抽样任务的单位确定。"},{"i":7,"n":"第七条","txt":"抽样人员应当检查兽药贮存条件是否符合要求；兽药包装是否按照规定印有或者贴有标签并附有说明书，字样是否清晰；标签或者说明书的内容是否与兽药管理部门核准的内容相符，并核实被抽样兽药品种的库存量。"},{"i":8,"n":"第八条","txt":"对同一企业相同品种抽取的样品不超过三个批号的产品。相同批号的产品，依其库存数量，确定抽样件数，具体规定如下： （一）原料药及大包装预混剂： 兽药包装为25公斤（含25公斤）以上的，10件以内，抽样1件；11—50件抽2件；51—100件抽3件；101件以上每增加100件增抽1件（增加不足100件按100件计）。 兽药包装为2—24公斤的，每200公斤抽样1件，不足200公斤者以200公斤计。 兽药包装为2公斤以下的，每20公斤抽样1件，不足20公斤者以20公斤计。且以原包装抽取。 （二）注射剂： 2万支（瓶）以下，抽样1件。 2—5万支（瓶），抽样2件。 5—10万支（瓶），抽样3件。 10万支（瓶）以上，每增加10万支（瓶）加抽1件，不足10万支（瓶）以10万支计。 （三）其他制剂： 每2万盒（瓶），抽样1件，不足2万盒（瓶）以2万盒（瓶）计。"},{"i":9,"n":"第九条","txt":"抽样数量 （一）注射用针剂（粉针） 50瓶（支） （二）注射液（水针） 1.规格：1—5毫升　100支（瓶） 2.规格；10—20毫升　25支（瓶） 3.规格：50—100毫升　6支（瓶） 4.规格：250—500毫升　3瓶 注：该抽样数量不包括澄明度检查，需做该项检查的按实际需要抽取样品。 （三）片剂 1.片重0.5克、100片/瓶（袋、盒）以上（含100片）2瓶（袋、盒） 2.片重0.5克以下、500片/瓶（袋、盒）以上（含500片）2瓶（袋、盒） （四）原料药 200克 分装成2瓶 （五）预混剂 250克/袋（含250克以下）　10袋 250克/袋以上　10袋 （六）兽用生物制品 灭活苗　10支（瓶） 弱毒苗　20支（瓶）"},{"i":10,"n":"第十条","txt":"抽样人员应当根据随机抽样原则进行抽样，并遵循以下操作程序： （一）启封兽药包装前应检查所抽样品的外观情况，确定品名、批号、批准文号、数量、包装状况等项无误后，方可进行下一步骤。发现异常情况时，包括如破损、受潮、受污染、混有其他品种、批号，或者有掺假、掺劣、假冒迹象等，应当作针对性抽样。 （二）用适当方法拆开抽样单元的包装，观察内容物的情况，确定无异常情况后，方可进行下一步骤。发现异常情况，应当作针对性抽样。 （三）将被拆包的抽样单元重新包封，贴上已被抽样的标记，注明品名、批号、生产单位、抽样数量、抽样日期及场所、抽样人姓名等。对有异常情况或做针对性抽检的产品可暂时封存以候检验结果的处理。"},{"i":11,"n":"第十一条","txt":"抽样结束后，抽样人员应当用《兽药封签》（见附件一）将所抽样品签封，据实填写《兽药抽样记录及凭证》（见附件二）。《兽药封签》和《兽药抽样记录及凭证》应当由抽样人员和被抽样单位负责人签字，并加盖抽样单位和被抽样单位公章；被抽样对象为个人的，由该个人签字。 《兽药抽样记录及凭证》一式三份，一份交被抽样单位或者个人作抽样凭证，一份封存于样品包装内随检验单位检品卡流转，一份由抽样单位保存备查。"},{"i":12,"n":"第十二条","txt":"抽样注意事项： （一）抽样操作应当规范、注意安全，不影响所抽样品和被拆包装药品的质量。 （二）取样工具和盛样器具应当洁净、干燥，必要时作灭菌处理。盛样容器在使用及贮存运输过程中，应能防止受潮及异物混入。 （三）原料药取样应当迅速，样品和被拆包的抽样单元应当尽快密封，防止吸潮、风化或氧化。 （四）无菌原料药应当按照无菌操作法取样。 （五）需要在真空或者氮气条件下保存的兽药，抽取样品后，应当对样品和被拆包的抽样单元加以密封。 （六）液体样品应先摇匀后再取样。含有结晶者，应在不影响品质的情况下溶化后取样。 （七）对毒性、腐蚀性或者易燃易爆药品，抽样时应当穿戴防护用具，小心搬运，样品应当标注“危险品”的标志；易燃易爆药品应远离热源，并不得震动：腐蚀性药品还应当避免接触金属制品。 （八）遇光易变质的兽药应当避光取样，置于有色玻瓶中，必要时加套黑纸。"},{"i":13,"n":"第十三条","txt":"抽样过程中发现有下列情形之一的，应当及时报告农牧行政管理机关： （一）国家农牧行政管理机关明文规定禁止使用的； （二）未经批准生产、配制、经营、进口，或者须经口岸兽药监察所检验而未经检验即生产、销售的； （三）未取得兽药批准文号或人畜共用原料药未取得兽药或药品批准文号的； （四）用途或用法用量超出规定范围的； （五）应标明而未标明有效期或者更改有效期、超过有效期的； （六）未注明或者更改生产批号的； （七）超越许可范围生产、配制，经营或进口兽药的； （八）未经登记或者质量检验不合格仍进口、销售或者使用的。"},{"i":14,"n":"第十四条","txt":"抽样人员应当采取措施保证样品不失效、不变质、不破损、不泄漏，并及时将抽取的样品送达承担检验任务的兽药监察所。经核查，对抽样人员送检的样品与《兽药抽样记录及凭证》所记录的内容相符、《兽药封签》完整的，兽药监察所予以签收。"},{"i":15,"n":"第十五条","txt":"兽药监督员可以依照《兽药管理条例》和本规定，开展兽药监督抽样工作。 兽药监督员实施监督抽样时，应当向被抽查单位或者个人出示符合《兽药管理条例》规定的证件。"},{"i":16,"n":"第十六条","txt":"进口兽药的报验程序，依照《进口兽药管理办法》的规定执行；进口兽药的抽样依照本规定执行。"},{"i":17,"n":"第十七条","txt":"本规定自发布之日起施行。农业部发布的《进口兽药抽样规定》[（1991）农（牧）字第2号l和《兽药监督检验抽样规定》[（1993）农（牧）函字第46号]同时废止。 附件1 附件2"}],"shouyaojinkouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强进口兽药的监督管理，规范兽药进口行为，保证进口兽药质量，根据《中华人民共和国海关法》和《兽药管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事兽药进口、进口兽药的经营和监督管理，应当遵守本办法。 进口兽药实行目录管理。《进口兽药管理目录》由农业农村部会同海关总署制定、调整并公布。"},{"i":3,"n":"第三条","txt":"农业农村部负责全国进口兽药的监督管理工作。 县级以上地方人民政府兽医主管部门负责本行政区域内进口兽药的监督管理工作。"},{"i":4,"n":"第四条","txt":"兽药应当从具备检验能力的兽药检验机构所在地口岸进口（以下简称兽药进口口岸）。兽药检验机构名单由农业农村部确定并公布。"},{"i":5,"n":"第五条","txt":"兽药进口应当办理《进口兽药通关单》。《进口兽药通关单》由中国境内代理商向兽药进口口岸所在地省级人民政府兽医主管部门申请。申请时，应当提交下列材料： （一）兽药进口申请表； （二）代理合同（授权书）和购货合同复印件； （三）工商营业执照复印件；兽药生产企业申请进口本企业生产所需原料药的，提交工商营业执照复印件； （四）产品出厂检验报告； （五）装箱单、提运单和货运发票复印件； （六）产品中文标签、说明书式样。 申请兽用生物制品《进口兽药通关单》的，还应当向兽药进口口岸所在地省级人民政府兽医主管部门提交生产企业所在国家（地区）兽药管理部门出具的批签发证明。"},{"i":6,"n":"第六条","txt":"兽药进口口岸所在地省级人民政府兽医主管部门应当自收到申请之日起2个工作日内完成审查。审查合格的，发给《进口兽药通关单》；不合格的，书面通知申请人，并说明理由。 《进口兽药通关单》主要载明代理商名称、有效期限、兽药进口口岸、海关商品编码、商品名称、生产企业名称、进口数量、包装规格等内容。 兽药进口口岸所在地省级人民政府兽医主管部门应当在每月上旬将上月核发的《进口兽药通关单》报农业农村部备案。"},{"i":7,"n":"第七条","txt":"进口少量科研用兽药，应当向农业农村部申请，并提交兽药进口申请表和科研项目的立项报告、试验方案等材料。 进口注册用兽药样品、对照品、标准品、菌（毒、虫）种、细胞的，应当向农业农村部申请，并提交兽药进口申请表。 农业农村部受理申请后组织风险评估，并自收到评估结论之日起5个工作日内完成审查。审查合格的，发给《进口兽药通关单》；不合格的，书面通知申请人，并说明理由。"},{"i":8,"n":"第八条","txt":"国内急需的兽药，由农业农村部指定单位进口，并发给《进口兽药通关单》。"},{"i":9,"n":"第九条","txt":"《进口兽药通关单》实行一单一关，在30日有效期内只能一次性使用，内容不得更改，过期应当重新办理。"},{"i":10,"n":"第十条","txt":"境外企业不得在中国境内直接销售兽药。 进口的兽用生物制品，由中国境内的兽药经营企业作为代理商销售，但外商独资、中外合资和合作经营企业不得销售进口的兽用生物制品。 兽用生物制品以外的其他进口兽药，由境外企业依法在中国境内设立的销售机构或者符合条件的中国境内兽药经营企业作为代理商销售。"},{"i":11,"n":"第十一条","txt":"境外企业在中国境内设立的销售机构、委托的代理商及代理商确定的经销商，应当取得《兽药经营许可证》，并遵守农业农村部制定的兽药经营质量管理规范。 销售进口兽用生物制品的《兽药经营许可证》，应当载明委托的境外企业名称及委托销售的产品类别等内容。"},{"i":12,"n":"第十二条","txt":"进口兽药销售代理商由境外企业确定、调整，并报农业农村部备案。 境外企业应当与代理商签订进口兽药销售代理合同，明确代理范围等事项。"},{"i":13,"n":"第十三条","txt":"进口兽用生物制品，除境外企业确定的代理商及代理商确定的经销商外，其他兽药经营企业不得经营。"},{"i":14,"n":"第十四条","txt":"进口的兽药标签和说明书应当用中文标注。"},{"i":15,"n":"第十五条","txt":"养殖户、养殖场、动物诊疗机构等使用者采购的进口兽药只限自用，不得转手销售。"},{"i":16,"n":"第十六条","txt":"进口列入《进口兽药管理目录》的兽药，进口单位进口时，需持《进口兽药通关单》向海关申报，海关按货物进口管理的相关规定办理通关手续。 进口单位办理报关手续时，因企业申报不实或者伪报用途所产生的后果，由进口单位承担相应的法律责任。"},{"i":17,"n":"第十七条","txt":"经批准以加工贸易方式进口兽药的，海关按照有关规定实施监管。进口料件或加工制成品属于兽药且无法出口的，应当按照本办法规定办理《进口兽药通关单》，海关凭《进口兽药通关单》办理内销手续。未取得《进口兽药通关单》的，由加工贸易企业所在地省级人民政府兽医主管部门监督销毁，海关凭有关证明材料办理核销手续。销毁所需费用由加工贸易企业承担。"},{"i":18,"n":"第十八条","txt":"以暂时进口方式进口的不在中国境内销售的兽药，不需要办理《进口兽药通关单》。暂时进口期满后应当全部复运出境，因特殊原因确需进口的，依照本办法和相关规定办理进口手续后方可在境内销售。无法复运出境又无法办理进口手续的，经进口单位所在地省级人民政府兽医主管部门批准，并商进境地直属海关同意，由所在地省级人民政府兽医主管部门监督销毁，海关凭有关证明材料办理核销手续。销毁所需费用由进口单位承担。"},{"i":19,"n":"第十九条","txt":"从境外进入保税区、出口加工区及其他海关特殊监管区域和保税监管场所的兽药及海关特殊监管区域、保税监管场所之间进出的兽药，免予办理《进口兽药通关单》，由海关按照有关规定实施监管。 从保税区、出口加工区及其他海关特殊监管区域和保税监管场所进入境内区外的兽药，应当办理《进口兽药通关单》。"},{"i":20,"n":"第二十条","txt":"兽用生物制品进口后，代理商应当向农业农村部指定的检验机构申请办理审查核对和抽查检验手续。未经审查核对或者抽查检验不合格的，不得销售。 其他兽药进口后，由兽药进口口岸所在地省级人民政府兽医主管部门通知兽药检验机构进行抽查检验。"},{"i":21,"n":"第二十一条","txt":"县级以上地方人民政府兽医主管部门应当将进口兽药纳入兽药监督抽检计划，加强对进口兽药的监督检查，发现违反《兽药管理条例》和本办法规定情形的，应当依法作出处理决定。"},{"i":22,"n":"第二十二条","txt":"禁止进口下列兽药： （一）经风险评估可能对养殖业、人体健康造成危害或者存在潜在风险的； （二）疗效不确定、不良反应大的； （三）来自疫区可能造成疫病在中国境内传播的兽用生物制品； （四）生产条件不符合规定的； （五）标签和说明书不符合规定的； （六）被撤销、吊销《进口兽药注册证书》的； （七）《进口兽药注册证书》有效期届满的； （八）未取得《进口兽药通关单》的； （九）农业农村部禁止生产、经营和使用的。"},{"i":23,"n":"第二十三条","txt":"提供虚假资料或者采取其他欺骗手段取得进口兽药证明文件的，按照《兽药管理条例》第五十七条的规定处罚。 伪造、涂改进口兽药证明文件进口兽药的，按照《兽药管理条例》第四十七条、第五十六条的规定处理。"},{"i":24,"n":"第二十四条","txt":"买卖、出租、出借《进口兽药通关单》的，按照《兽药管理条例》第五十八条的规定处罚。"},{"i":25,"n":"第二十五条","txt":"养殖户、养殖场、动物诊疗机构等使用者将采购的进口兽药转手销售的，或者代理商、经销商超出《兽药经营许可证》范围经营进口兽用生物制品的，属于无证经营，按照《兽药管理条例》第五十六条的规定处罚。"},{"i":26,"n":"第二十六条","txt":"兽药进口构成走私或者违反海关监管规定的，由海关根据《中华人民共和国海关法》及其相关法律、法规的规定处理。"},{"i":27,"n":"第二十七条","txt":"兽用麻醉药品、精神药品、毒性药品和放射性药品等特殊药品的进口管理，除遵守本办法的规定外，还应当遵守国家关于麻醉药品、精神药品、毒性药品和放射性药品的管理规定。"},{"i":28,"n":"第二十八条","txt":"本办法所称进口兽药证明文件，是指《进口兽药注册证书》、《进口兽药通关单》等。"},{"i":29,"n":"第二十九条","txt":"兽药进口申请表可以从农业农村部官方网站下载。"},{"i":30,"n":"第三十条","txt":"本办法自2008年1月1日起施行。海关总署发布的《海关总署关于验放进口兽药的通知》（〔88〕署货字第725号）、《海关总署关于明确进口人畜共用兽药有关验放问题的通知》（署法发〔2001〕276号）、中华人民共和国海关总署公告2001年第7号同时废止。"}],"nongyenongcunbuxingzhengxukeshishiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范农业农村部行政许可实施，维护农业农村领域市场主体合法权益,优化农业农村发展环境,根据《中华人民共和国行政许可法》《优化营商环境条例》等法律法规,制定本办法。"},{"i":2,"n":"第二条","txt":"农业农村部行政许可条件的规定、行政许可的办理和监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"实施行政许可应当遵循依法、公平、公正、公开、便民的原则。"},{"i":4,"n":"第四条","txt":"农业农村部法规司（以下简称“法规司”）在行政许可实施过程中承担下列职责： （一）组织协调行政审批制度改革，指导、督促相关单位取消和下放行政许可事项、强化事中事后监管； （二）负责行政审批综合办公业务管理工作，审核行政许可事项实施规范、办事指南、审查细则等，适时集中公布行政许可事项办事指南； （三）受理和督办申请人提出的行政许可投诉举报； （四）受理申请人依法提出的行政复议申请。"},{"i":5,"n":"第五条","txt":"行政许可承办司局及单位（以下简称“承办单位”）在行政许可实施过程中承担下列职责： （一）起草行政许可事项实施规范、办事指南、审查细则等； （二）按规定选派政务服务大厅窗口工作人员（以下简称“窗口人员”）； （三）依法对行政许可申请进行审查，在规定时限内提出审查意见； （四）对申请材料和行政许可实施过程中形成的纸质及电子文件资料及时归档； （五）调查核实与行政许可实施有关的投诉举报，并按规定整改反馈； （六）持续简化行政许可申请材料和办理程序，提高审批效率，提升服务水平； （七）实施行政许可事中事后监管。"},{"i":6,"n":"第六条","txt":"行政许可事项实行清单管理。农业农村部行政许可事项以国务院公布的清单为准，禁止在清单外以任何形式和名义设定、实施行政许可。"},{"i":7,"n":"第七条","txt":"部门规章可以在法律、行政法规设定的行政许可事项范围内，对实施该行政许可作出具体规定。农业农村部规范性文件可以明确行政许可条件的具体技术指标或资料要求，但不得增设违反上位法的条件和程序，不得限制申请人的权利、增加申请人的义务。 部门规章和农业农村部规范性文件应当按照法定程序起草、审查和公布，法律、行政法规、部门规章和农业农村部规范性文件以外的其他文件不得规定和调整行政许可具体条件及其技术指标或资料要求。"},{"i":8,"n":"第八条","txt":"行政许可具体条件调整后，承办单位应当及时进行宣传、解读和培训，便于申请人及时了解、地方农业农村部门按规定实施。"},{"i":9,"n":"第九条","txt":"行政许可具体条件及其技术指标或资料要求调整后，承办单位应当及时修改实施规范、办事指南、审查细则等，并送法规司审核。 修改后的实施规范、办事指南、审查细则等，承办单位应当及时在农业农村部政务服务平台、国家政务服务平台等载体同源同步更新，确保信息统一。"},{"i":10,"n":"第十条","txt":"申请人可以通过信函、电子数据交换和电子邮件等方式提出行政许可申请。申请书需要采用格式文本的，承办单位应当向申请人免费提供行政许可申请书格式文本。"},{"i":11,"n":"第十一条","txt":"农业农村部行政许可的事项名称、依据、条件、数量、程序、期限以及需要提交全部材料的目录和申请书示范文本等，应当在农业农村部政务服务大厅及一体化在线政务服务平台进行公示。 申请人要求对公示内容予以说明、解释的，承办单位或者窗口人员应当说明、解释，提供准确、可靠的信息。"},{"i":12,"n":"第十二条","txt":"除直接涉及国家安全、国家秘密、公共安全、生态环境保护，直接关系人身健康、生命财产安全以及重要涉外等情形以外，对行政许可事项要求提供的证明材料实行证明事项告知承诺制。承办单位应当提出实行告知承诺制的事项范围并制作告知承诺书格式文本，法规司统一公布实行告知承诺制的证明事项目录。"},{"i":13,"n":"第十三条","txt":"实行告知承诺制的证明事项，申请人可以自主选择是否采用告知承诺制方式办理。"},{"i":14,"n":"第十四条","txt":"承办单位不得要求申请人提交法律、行政法规和部门规章、农业农村部规范性文件要求范围以外的材料。"},{"i":15,"n":"第十五条","txt":"对申请人提出的行政许可申请，应当根据下列情况分别作出处理： （一）申请事项依法不需要取得行政许可的，应当即时告知申请人不受理及不受理的理由； （二）申请事项依法不属于农业农村部职权范围的，应当即时作出不予受理的决定，并告知申请人向有关行政机关申请； （三）申请材料存在可以当场更正的错误的，应当允许申请人当场更正； （四）申请材料不齐全或者不符合法定形式的，应当当场或者在五个工作日内一次性告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （五）申请事项属于农业农村部职权范围，申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正申请材料的，应当受理行政许可申请。 受理或者不予受理行政许可申请，应当出具通知书。通知书应当加盖农业农村部行政审批专用章，并注明日期。"},{"i":16,"n":"第十六条","txt":"申请人在行政许可决定作出前要求撤回申请的，应当书面提出，经承办单位审核同意后，由窗口人员将行政许可申请材料退回申请人。撤回的申请自始无效。"},{"i":17,"n":"第十七条","txt":"农业农村部按照国务院要求建设一体化在线政务服务平台，强化安全保障和运营管理，拓展完善系统功能，推动行政许可全程网上办理。"},{"i":18,"n":"第十八条","txt":"除法律、行政法规另有规定或者涉及国家秘密等情形外，农业农村部行政许可应当纳入一体化在线政务服务平台办理。"},{"i":19,"n":"第十九条","txt":"农业农村部政务服务大厅与一体化在线政务服务平台均可受理行政许可申请，适用统一的办理标准，申请人可以自主选择。"},{"i":20,"n":"第二十条","txt":"承办单位应当按规定对申请材料进行审查。 申请人提交的申请材料齐全、符合法定形式和有关要求，能够当场作出决定的，应当当场作出书面的行政许可决定。 根据法定条件和程序，需要对申请材料的实质内容进行核实的，承办单位应当指派两名以上工作人员进行核查。"},{"i":21,"n":"第二十一条","txt":"依法应当先经省级人民政府农业农村部门审查后报农业农村部决定的行政许可，省级人民政府农业农村部门应当在法定期限内将初步审查意见和全部申请材料报送农业农村部。窗口人员和承办单位不得要求申请人重复提供申请材料。"},{"i":22,"n":"第二十二条","txt":"承办单位审查行政许可申请，发现行政许可事项直接关系他人重大利益的，应当在作出行政许可决定前告知利害关系人。申请人、利害关系人有权进行陈述和申辩，承办单位应当听取申请人、利害关系人的意见。申请人、利害关系人依法要求听证的，承办单位应当在二十个工作日内组织听证。"},{"i":23,"n":"第二十三条","txt":"申请人的申请符合规定条件的，应当依法作出准予行政许可的书面决定。 作出不予行政许可的书面决定的，应当说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":24,"n":"第二十四条","txt":"除当场作出行政许可决定的情形外，行政许可决定应当在法定期限内按照规定程序作出。行政许可事项办事指南中明确承诺时限的，应当在承诺时限内作出行政许可决定。"},{"i":25,"n":"第二十五条","txt":"在承诺时限内不能作出行政许可决定的，承办单位应当提出书面延期申请并说明理由，会签法规司并报该行政许可决定签发人审核同意后，将延长期限的理由告知申请人，但不得超过法定办理时限。"},{"i":26,"n":"第二十六条","txt":"作出行政许可决定，依法需要听证、检验、检测、检疫、鉴定和专家评审的，所需时间不计算在办理期限内。承办单位应当及时安排、限时办结，并将所需时间书面告知申请人。"},{"i":27,"n":"第二十七条","txt":"农业农村部一体化在线政务服务平台设立行政许可电子监察系统，对行政许可办理时限全流程实时监控，及时予以警示。"},{"i":28,"n":"第二十八条","txt":"窗口人员或者承办单位应当在行政许可决定作出之日起十个工作日内，将行政许可决定通过农业农村部一体化在线政务服务平台反馈申请人，并通过现场、邮政特快专递等方式向申请人颁发、送达许可证件，或者加盖检疫印章。"},{"i":29,"n":"第二十九条","txt":"农业农村部作出的准予行政许可决定应当公开，公众有权查阅。"},{"i":30,"n":"第三十条","txt":"农业农村部按照国务院要求推广应用电子证照，逐步实现行政许可证照电子化。承办单位会同法规司制定电子证照标准，制作和管理电子证照，对有效期内存量纸质证照数据逐步实行电子化。"},{"i":31,"n":"第三十一条","txt":"已取消的行政许可事项，承办单位不得继续实施或者变相实施，不得转由其他单位或组织实施。"},{"i":32,"n":"第三十二条","txt":"中介服务事项作为行政许可办理条件的，应当有法律、行政法规或者国务院决定依据。 承办单位不得为申请人指定或者变相指定中介服务机构；除法定行政许可中介服务事项外，不得强制或者变相强制申请人接受中介服务。 农业农村部所属事业单位、主管的社会组织，及其设立的企业，不得开展与农业农村部行政许可相关的中介服务。法律、行政法规另有规定的，依照其规定。"},{"i":33,"n":"第三十三条","txt":"承办单位应当对实施的行政许可事项逐项明确监管主体,制定并公布全国统一、简明易行的监管规则，明确监管方式和标准。"},{"i":34,"n":"第三十四条","txt":"已取消的行政许可事项，承办单位应当变更监管规则，加强事中事后监管；已下放的行政许可事项，承办单位应当同步调整优化监管层级，确保审批与监管权责统一。"},{"i":35,"n":"第三十五条","txt":"承办单位负责同志、直接从事行政许可审查的工作人员，符合法定回避情形的应当回避；直接从事行政许可审查的工作人员应当定期轮岗交流。"},{"i":36,"n":"第三十六条","txt":"承办单位及相关人员违反《中华人民共和国行政许可法》和其他有关规定，情节轻微，尚未给公民、法人或者其他组织造成严重财产损失或者严重不良社会影响的，采取通报批评、责令整改等方式予以处理。涉嫌违规违纪的，按照干部管理权限移送纪检监察机关。涉嫌犯罪的，依法移送司法机关。"},{"i":37,"n":"第三十七条","txt":"申请人隐瞒有关情况或者提供虚假材料申请行政许可的，不予受理或者不予行政许可，并给予警告；行政许可申请属于直接关系公共安全、人身健康、生命财产安全事项的，申请人在一年内不得再次申请该行政许可。法律、行政法规另有规定的，依照其规定。"},{"i":38,"n":"第三十八条","txt":"被许可人以欺骗、贿赂等不正当手段取得行政许可的，应当依法给予行政处罚；取得的行政许可属于直接关系公共安全、人身健康、生命财产安全事项的，申请人在三年内不得再次申请该行政许可。法律、行政法规另有规定的，依照其规定。"},{"i":39,"n":"第三十九条","txt":"农业农村部政务服务大厅其他政务服务事项的办理，参照本办法执行。"},{"i":40,"n":"第四十条","txt":"本办法自2022年1月15日起施行。"}],"nongyenongcunbumentongjigongzuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了进一步加强和规范农业农村部门统计工作，提高统计数据质量，发挥统计在服务全面推进乡村振兴、加快建设农业强国中的重要作用，根据《中华人民共和国统计法》、《中华人民共和国统计法实施条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"各级农业农村主管部门对农业产业发展、乡村发展建设治理、农民生产生活等情况进行统计调查、统计分析，提供统计数据，实施统计监督，适用本办法。"},{"i":3,"n":"第三条","txt":"农业农村部负责全国农业农村部门统计工作的宏观指导、统筹协调、组织实施和监督管理。 地方各级农业农村主管部门在上级农业农村主管部门指导下，负责本行政区域内的农业农村部门统计工作。"},{"i":4,"n":"第四条","txt":"各级农业农村主管部门应当加强对统计工作的组织领导，明确承担统计任务的机构和人员，为依法开展统计工作提供必要的经费和条件保障。"},{"i":5,"n":"第五条","txt":"各级农业农村主管部门应当加强统计信息化建设，加快农业农村大数据应用，积极运用信息技术推进农业农村部门统计工作现代化。"},{"i":6,"n":"第六条","txt":"国家机关、企业事业单位和其他组织以及个体工商户和个人等统计调查对象，应当依法真实、准确、完整、及时地提供统计调查所需的资料，不得提供不真实或者不完整的统计资料，不得迟报、瞒报、拒报。"},{"i":7,"n":"第七条","txt":"各级农业农村主管部门应当严格落实防范和惩治统计造假、弄虚作假责任制，积极协助本级人民政府统计机构查处统计违法行为，按照规定及时移送有关统计违法案件材料。"},{"i":8,"n":"第八条","txt":"各级农业农村主管部门贯彻执行法律、法规、规章和本级人民政府的决定及履行本部门职责，需要开展统计活动的，应当制定相应的统计调查项目。 统计调查项目包括： （一）综合统计调查项目，指涉及三农发展全局的统计调查项目； （二）专业统计调查项目，指涉及农业农村某一行业、某个领域、某项工作的统计调查项目。"},{"i":9,"n":"第九条","txt":"农业农村部制定的统计调查项目，由农业农村部有关司局、派出机构在充分论证、征求意见、集体讨论决定的基础上提出，经统计工作归口管理司局审核后按程序报送国家统计局审批或者备案。 地方各级农业农村主管部门制定的统计调查项目，依法报送统计机构审批，其主要内容不得与农业农村部制定的统计调查项目内容重复、矛盾。 统计调查项目以统计机构批准执行或者同意备案的日期为生效时间。统计调查项目在有效期内需要变更内容的，应当按程序重新审批或者备案。"},{"i":10,"n":"第十条","txt":"各级农业农村主管部门制定统计调查项目，应当同时制定该项目的统计调查制度。 统计调查制度内容包括总说明、报表目录、调查表式、分类目录、指标解释、指标间逻辑关系，采用抽样调查方法的还应当包括抽样方案。 统计调查制度总说明应当对调查目的、调查对象、统计范围、调查内容、调查频率、调查时间、调查方法、组织实施方式、质量控制、报送要求、信息共享、资料公布等作出规定。 面向单位的部门统计调查，其统计调查对象应当取自国家基本单位名录库或者部门基本单位名录库。"},{"i":11,"n":"第十一条","txt":"统计调查表应当标明表号、制定机关、批准或者备案文号、有效期限等。统计调查表中的指标应当具有明确清晰的定义和数据采集来源。"},{"i":12,"n":"第十二条","txt":"农业农村部门统计调查应当合理确定调查频率和调查规模，综合运用全面调查、抽样调查、重点调查等方法，并充分利用行政记录等资料。 各级农业农村主管部门可以通过政府购买服务等方式开展统计调查工作，并对统计调查过程和结果负责。承接政府购买服务的主体应当严格按照统计调查制度开展统计调查工作。"},{"i":13,"n":"第十三条","txt":"地方各级农业农村主管部门应当严格执行统计调查制度，加强数据采集、传输、审核、汇总、核算、分析等环节的全流程质量控制，及时、准确上报统计资料。"},{"i":14,"n":"第十四条","txt":"农业农村部门统计调查应当依据国家统计标准。没有国家统计标准的，农业农村部可以制定部门统计标准并按照《中华人民共和国统计法》规定程序报批。"},{"i":15,"n":"第十五条","txt":"各级农业农村主管部门应当建立健全统计资料保存管理制度，规范统计资料整理、标识、交接、归档、维护、借阅等工作，推进电子化管理。"},{"i":16,"n":"第十六条","txt":"各级农业农村主管部门应当建立健全统计信息共享机制，依法及时与本级人民政府统计机构共享统计信息。"},{"i":17,"n":"第十七条","txt":"各级农业农村主管部门应当加强统计资料在农业产业发展、乡村发展建设治理、农民生产生活等方面的应用，按照统计调查制度规定公布数据。"},{"i":18,"n":"第十八条","txt":"各级农业农村主管部门及其统计人员对在统计工作中知悉的国家秘密、工作秘密、商业秘密和个人信息，应当予以保密，不得泄露或者向他人非法提供。 各级农业农村主管部门应当加强数据安全管理，科学研判数据汇聚形成的风险，提升数据安全技术手段，防范数据泄露。"},{"i":19,"n":"第十九条","txt":"农业农村部统计工作归口管理司局履行以下职责： （一）组织制定农业农村部门统计制度规范、部门统计标准，建立健全农业农村部门统计体系，具体承担全国农业农村部门统计工作的监督管理； （二）统一部署和审核报送农业农村部统计调查项目； （三）组织实施农业农村部综合统计调查项目，对综合统计调查制度执行情况进行监督检查； （四）指导各相关司局、派出机构实施农业农村部专业统计调查项目； （五）统筹管理农业农村部统计资料的汇总、共享和公布，编制年度统计公报和综合性统计资料，建立健全统计指标库和数据库； （六）统筹推进农业农村部门统计信息化建设和大数据发展； （七）组织指导农业农村部门统计人员的专业培训和职业道德教育。"},{"i":20,"n":"第二十条","txt":"农业农村部各相关司局、派出机构履行以下职责： （一）组织实施业务范围内的专业统计调查项目，对专业统计调查制度执行情况进行监督检查； （二）制定本行业、本领域统计管理制度，参与制定农业农村部门统计标准； （三）优化完善统计指标体系，加强统计资料的采集、整理、汇总、审核、共享、分析及应用； （四）向统计工作归口管理司局报送年度统计数据公布计划，并按照要求公布； （五）推进本行业、本领域统计信息化建设和大数据发展； （六）对受委托开展统计工作的相关事业单位、科研机构加强监督管理； （七）负责本行业、本领域统计人员管理和培训。"},{"i":21,"n":"第二十一条","txt":"地方各级农业农村主管部门履行以下职责： （一）按照农业农村部统计调查项目及其统计调查制度要求，负责采集、整理、汇总、审核、报送本行政区域统计资料； （二）制定实施地方农业农村部门统计调查项目及其统计调查制度； （三）开展统计数据分析研判，提供统计信息服务； （四）推进本行政区域内的农业农村部门统计信息化建设和大数据发展； （五）监督管理本行政区域内的农业农村部门统计工作； （六）负责本行政区域内的统计人员管理和培训。"},{"i":22,"n":"第二十二条","txt":"各级农业农村主管部门及其统计人员应当依法履行职责,如实搜集、报送统计资料,不得伪造、篡改统计资料,不得以任何方式要求任何单位和个人提供不真实的统计资料,不得有其他违反《中华人民共和国统计法》规定的行为。 统计人员进行统计调查时,有权就与统计有关的问题询问有关人员,要求其如实提供有关情况、资料并改正不真实、不准确的资料。 统计人员进行统计调查时,应当出示其所在部门颁发的工作证件;未出示的,统计调查对象有权拒绝调查。"},{"i":23,"n":"第二十三条","txt":"统计人员应当具备与其从事的统计工作相适应的专业知识和业务能力，坚持实事求是,恪守职业道德,对其负责搜集、审核、录入的统计资料与统计调查对象报送的统计资料的一致性负责。"},{"i":24,"n":"第二十四条","txt":"各级农业农村主管部门及其工作人员有违反本办法规定行为的，依照《中华人民共和国统计法》、《中华人民共和国统计法实施条例》有关规定予以处理。"},{"i":25,"n":"第二十五条","txt":"作为农业农村部门统计调查对象的国家机关、企业事业单位或者其他组织有下列行为之一的，依照《中华人民共和国统计法》移送有关机构予以查处： （一）拒绝提供统计资料或者经催报后仍未按时提供统计资料的; （二）提供不真实或者不完整的统计资料的; （三）拒绝、阻碍统计调查、统计检查的; （四）转移、隐匿、篡改、毁弃或者拒绝提供原始记录和凭证、统计台账、统计调查表及其他相关证明和资料的； （五）迟报统计资料的； （六）未按照国家有关规定设置原始记录、统计台账的。 个体工商户有前款第（一）项至第（五）项所列行为之一的，依照《中华人民共和国统计法》移送有关机构予以查处。"},{"i":26,"n":"第二十六条","txt":"上级农业农村主管部门可以依据本办法，对下级农业农村主管部门贯彻落实统计法律法规和制度，开展统计业务工作，落实防范和惩治统计造假、弄虚作假责任制，保障人员力量和工作条件等情况进行监督。 各级农业农村主管部门对在统计工作中履职尽责并作出突出贡献的单位和人员给予通报表扬，对报送不及时、数据质量差等履职不力的，给予通报批评。 地方各级农业农村主管部门执行上级农业农村主管部门布置的统计调查任务存在严重问题的，由上级农业农村主管部门予以约谈。"},{"i":27,"n":"第二十七条","txt":"本办法自2024年7月1日起施行。"}],"nongyejixieshiguchulibanfa":[{"i":1,"n":"第一条","txt":"为规范农业机械事故处理工作，维护农业机械安全生产秩序，保护农业机械事故当事人的合法权益，根据《农业机械安全监督管理条例》等法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称农业机械事故（以下简称农机事故），是指农业机械在作业或转移等过程中造成人身伤亡、财产损失的事件。 农机事故分为特别重大农机事故、重大农机事故、较大农机事故和一般农机事故： （一）特别重大农机事故，是指造成30人以上死亡，或者100人以上重伤的事故，或者1亿元以上直接经济损失的事故； （二）重大农机事故，是指造成10人以上30人以下死亡，或者50人以上100人以下重伤的事故，或者5000万元以上1亿元以下直接经济损失的事故； （三）较大农机事故，是指造成3人以上10人以下死亡，或者10人以上50人以下重伤的事故，或者1000万元以上5000万元以下直接经济损失的事故； （四）一般农机事故，是指造成3人以下死亡，或者10人以下重伤，或者1000万元以下直接经济损失的事故。"},{"i":3,"n":"第三条","txt":"县级以上地方人民政府农业机械化主管部门负责农业机械事故责任的认定和调解处理。 县级以上地方人民政府农业机械化主管部门所属的农业机械安全监督管理机构（以下简称农机安全监理机构）承担本辖区农机事故处理的具体工作。 法律、行政法规对农机事故的处理部门另有规定的，从其规定。"},{"i":4,"n":"第四条","txt":"对特别重大、重大、较大农机事故，农业农村部、省级人民政府农业机械化主管部门和地（市）级人民政府农业机械化主管部门应当分别派员参与调查处理。"},{"i":5,"n":"第五条","txt":"农机事故处理应当遵循公正、公开、便民、效率的原则。"},{"i":6,"n":"第六条","txt":"农机安全监理机构应当按照农机事故处理规范化建设要求，配备必需的人员和事故勘查车辆、现场勘查设备、警示标志、取像设备、现场标划用具等装备。 县级以上地方人民政府农业机械化主管部门应当将农机事故处理装备建设和工作经费纳入本部门财政预算。"},{"i":7,"n":"第七条","txt":"农机安全监理机构应当建立24小时值班制度，向社会公布值班电话，保持通讯畅通。"},{"i":8,"n":"第八条","txt":"农机安全监理机构应当做好本辖区农机事故的报告工作，将农机事故情况及时、准确、完整地报送同级农业机械化主管部门和上级农机安全监理机构。 农业机械化主管部门应当定期将农业机械事故统计情况及说明材料报送上级农业机械化主管部门，并抄送同级安全生产监督管理部门。 任何单位和个人不得迟报、漏报、谎报或者瞒报农机事故。"},{"i":9,"n":"第九条","txt":"农机安全监理机构应当建立健全农机事故档案管理制度，指定专人负责农机事故档案管理。"},{"i":10,"n":"第十条","txt":"发生农机事故后，农机操作人员和现场其他人员应当立即停止农业机械作业或转移，保护现场，并向事故发生地县级农机安全监理机构报案；造成人身伤害的，还应当立即采取措施，抢救受伤人员；造成人员死亡的，还应当向事故发生地公安机关报案。因抢救受伤人员变动现场的，应当标明事故发生时机具和人员的位置。 发生农机事故，未造成人身伤亡，当事人对事实及成因无争议的，可以在就有关事项达成协议后即行撤离现场。"},{"i":11,"n":"第十一条","txt":"发生农机事故后当事人逃逸的，农机事故现场目击者和其他知情人应当向事故发生地县级农机安全监理机构或公安机关举报。接到举报的农机安全监理机构应当协助公安机关开展追查工作。"},{"i":12,"n":"第十二条","txt":"农机安全监理机构接到事故报案，应当记录下列内容： （一）报案方式、报案时间、报案人姓名、联系方式，电话报案的还应当记录报案电话； （二）农机事故发生的时间、地点； （三）人员伤亡和财产损失情况； （四）农业机械类型、号牌号码、装载物品等情况； （五）是否存在肇事嫌疑人逃逸等情况。"},{"i":13,"n":"第十三条","txt":"接到事故现场报案的，县级农机安全监理机构应当立即派人勘查现场，并自勘查现场之时起24小时内决定是否立案。 当事人未在事故现场报案，事故发生后请求农机安全监理机构处理的，农机安全监理机构应当按照本办法第十二条的规定予以记录，并在3日内作出是否立案的决定。"},{"i":14,"n":"第十四条","txt":"经核查农机事故事实存在且在管辖范围内的，农机安全监理机构应当立案，并告知当事人。经核查无法证明农机事故事实存在，或不在管辖范围内的，不予立案，书面告知当事人并说明理由。"},{"i":15,"n":"第十五条","txt":"农机安全监理机构对农机事故管辖权有争议的，应当报请共同的上级农机安全监理机构指定管辖。上级农机安全监理机构应当在24小时内作出决定，并通知争议各方。"},{"i":16,"n":"第十六条","txt":"农机事故应当由2名以上农机事故处理员共同处理。农机事故处理员处理农机事故，应当佩戴统一标志，出示行政执法证件。"},{"i":17,"n":"第十七条","txt":"农机事故处理员与事故当事人有利害关系、可能影响案件公正处理的，应当回避。"},{"i":18,"n":"第十八条","txt":"农机事故处理员到达现场后，应当立即开展下列工作： （一）组织抢救受伤人员； （二）保护、勘查事故现场，拍摄现场照片，绘制现场图，采集、提取痕迹、物证，并制作现场勘查笔录； （三）对涉及易燃、易爆、剧毒、易腐蚀等危险物品的农机事故，应当立即报告当地人民政府，并协助做好相关工作； （四）对造成供电、通讯等设施损毁的农机事故，应当立即通知有关部门处理； （五）确定农机事故当事人、肇事嫌疑人，查找证人，并制作询问笔录； （六）登记和保护遗留物品。"},{"i":19,"n":"第十九条","txt":"参加勘查的农机事故处理员、当事人或者见证人应当在现场图、勘查笔录和询问笔录上签名或捺印。当事人拒绝或者无法签名、捺印以及无见证人的，应当记录在案。 当事人应当如实陈述事故发生的经过，不得隐瞒。"},{"i":20,"n":"第二十条","txt":"调查事故过程中，农机安全监理机构发现当事人涉嫌犯罪的，应当依法移送公安机关处理；对事故农业机械可以依照《中华人民共和国行政处罚法》的规定，先行登记保存。 发生农机事故后企图逃逸、拒不停止存在重大事故隐患农业机械的作业或者转移的，县级以上地方人民政府农业机械化主管部门可以依法扣押有关农业机械及证书、牌照、操作证件。"},{"i":21,"n":"第二十一条","txt":"农机安全监理机构可以对事故农业机械进行检验，需要对事故当事人的生理、精神状况、人体损伤和事故农业机械行驶速度、痕迹等进行鉴定的，农机安全监理机构应当自现场勘查结束之日起3日内委托具有资质的鉴定机构进行鉴定。 当事人要求自行检验、鉴定的，农机安全监理机构应当向当事人介绍具有资质的检验、鉴定机构，由当事人自行选择。"},{"i":22,"n":"第二十二条","txt":"农机事故处理员在现场勘查过程中，可以使用呼气式酒精测试仪或者唾液试纸，对农业机械操作人员进行酒精含量检测，检测结果应当在现场勘查笔录中载明。 发现当事人有饮酒或者服用国家管制的精神药品、麻醉药品嫌疑的，应当委托有资质的专门机构对当事人提取血样或者尿样，进行相关检测鉴定。检测鉴定结果应当书面告知当事人。"},{"i":23,"n":"第二十三条","txt":"农机安全监理机构应当与检验、鉴定机构约定检验、鉴定的项目和完成的期限，约定的期限不得超过20日。超过20日的，应当报上一级农机安全监理机构批准，但最长不得超过60日。"},{"i":24,"n":"第二十四条","txt":"农机安全监理机构应当自收到书面鉴定报告之日起2日内，将检验、鉴定报告复印件送达当事人。当事人对检验、鉴定报告有异议的，可以在收到检验、鉴定报告之日起3日内申请重新检验、鉴定。县级农机安全监理机构批准重新检验、鉴定的，应当另行委托检验、鉴定机构或者由原检验、鉴定机构另行指派鉴定人。重新检验、鉴定以一次为限。"},{"i":25,"n":"第二十五条","txt":"发生农机事故，需要抢救治疗受伤人员的，抢救治疗费用由肇事嫌疑人和肇事农业机械所有人先行预付。投保机动车交通事故责任强制保险的拖拉机发生事故，因抢救受伤人员需要保险公司依法支付抢救费用的，事故发生地农业机械化主管部门应当书面通知保险公司。抢救受伤人员需要道路交通事故社会救助基金垫付费用的，事故发生地农业机械化主管部门应当通知道路交通事故社会救助基金管理机构，并协助救助基金管理机构向事故责任人追偿。"},{"i":26,"n":"第二十六条","txt":"农机事故造成人员死亡的，由急救、医疗机构或者法医出具死亡证明。尸体应当存放在殡葬服务单位或者有停尸条件的医疗机构。 对农机事故死者尸体进行检验的，应当通知死者家属或代理人到场。需解剖鉴定的，应当征得死者家属或所在单位的同意。 无法确定死亡人身份的，移交公安机关处理。"},{"i":27,"n":"第二十七条","txt":"农机安全监理机构应当依据以下情况确定当事人的责任： （一）因一方当事人的过错导致农机事故的，该方当事人承担全部责任； （二）因两方或者两方以上当事人的过错发生农机事故的，根据其行为对事故发生的作用以及过错的严重程度，分别承担主要责任、同等责任和次要责任； （三）各方均无导致农机事故的过错，属于意外事故的，各方均无责任； （四）一方当事人故意造成事故的，他方无责任。"},{"i":28,"n":"第二十八条","txt":"农机安全监理机构在进行事故认定前，应当对证据进行审查： （一）证据是否是原件、原物，复印件、复制品与原件、原物是否相符； （二）证据的形式、取证程序是否符合法律规定； （三）证据的内容是否真实； （四）证人或者提供证据的人与当事人有无利害关系。 符合规定的证据，可以作为农机事故认定的依据，不符合规定的，不予采信。"},{"i":29,"n":"第二十九条","txt":"农机安全监理机构应当自现场勘查之日起10日内，作出农机事故认定，并制作农机事故认定书。对肇事逃逸案件，应当自查获肇事机械和操作人后10日内制作农机事故认定书。对需要进行鉴定的，应当自收到鉴定结论之日起5日内，制作农机事故认定书。"},{"i":30,"n":"第三十条","txt":"农机事故认定书应当载明以下内容： （一）事故当事人、农业机械、作业场所的基本情况； （二）事故发生的基本事实； （三）事故证据及事故成因分析； （四）当事人的过错及责任或意外原因； （五）当事人向农机安全监理机构申请复核、调解和直接向人民法院提起民事诉讼的权利、期限； （六）作出农机事故认定的农机安全监理机构名称和农机事故认定日期。 农机事故认定书应当由事故处理员签名或盖章，加盖农机事故处理专用章，并在制作完成之日起3日内送达当事人。"},{"i":31,"n":"第三十一条","txt":"逃逸农机事故肇事者未查获，农机事故受害一方当事人要求出具农机事故认定书的，农机安全监理机构应当在接到当事人的书面申请后10日内制作农机事故认定书，并送达当事人。农机事故认定书应当载明农机事故发生的时间、地点、受害人情况及调查得到的事实，有证据证明受害人有过错的，确定受害人的责任;无证据证明受害人有过错的，确定受害人无责任。"},{"i":32,"n":"第三十二条","txt":"农机事故成因无法查清的，农机安全监理机构应当出具农机事故证明，载明农机事故发生的时间、地点、当事人情况及调查得到的事实，分别送达当事人。"},{"i":33,"n":"第三十三条","txt":"当事人对农机事故认定有异议的，可以自农机事故认定书送达之日起3日内，向上一级农机安全监理机构提出书面复核申请。 复核申请应当载明复核请求及其理由和主要证据。"},{"i":34,"n":"第三十四条","txt":"上一级农机安全监理机构应当自收到当事人书面复核申请后5日内，作出是否受理决定。任何一方当事人向人民法院提起诉讼并经法院受理的或案件已进入刑事诉讼程序的，复核申请不予受理，并书面通知当事人。 上一级农机安全监理机构受理复核申请的，应当书面通知各方当事人，并通知原办案单位5日内提交案件材料。"},{"i":35,"n":"第三十五条","txt":"上一级农机安全监理机构自受理复核申请之日起30日内，对下列内容进行审查，并作出复核结论： （一）农机事故事实是否清楚，证据是否确实充分，适用法律是否正确； （二）农机事故责任划分是否公正； （三）农机事故调查及认定程序是否合法。 复核原则上采取书面审查的办法，但是当事人提出要求或者农机安全监理机构认为有必要时，可以召集各方当事人到场听取意见。 复核期间，任何一方当事人就该事故向人民法院提起诉讼并经法院受理或案件已进入刑事诉讼程序的，农机安全监理机构应当终止复核。"},{"i":36,"n":"第三十六条","txt":"上一级农机安全监理机构经复核认为农机事故认定符合规定的，应当作出维持农机事故认定的复核结论；经复核认为不符合规定的，应当作出撤销农机事故认定的复核结论，责令原办案单位重新调查、认定。 复核结论应当自作出之日起3日内送达当事人。 上一级农机安全监理机构复核以1次为限。"},{"i":37,"n":"第三十七条","txt":"上一级农机安全监理机构作出责令重新认定的复核结论后，原办案单位应当在10日内依照本办法重新调查，重新制作编号不同的农机事故认定书，送达各方当事人，并报上一级农机安全监理机构备案。"},{"i":38,"n":"第三十八条","txt":"当事人对农机事故损害赔偿有争议的，可以在收到农机事故认定书或者上一级农机安全监理机构维持原农机事故认定的复核结论之日起10日内，共同向农机安全监理机构提出书面调解申请。"},{"i":39,"n":"第三十九条","txt":"农机安全监理机构应当按照合法、公正、自愿、及时的原则，采取公开方式进行农机事故损害赔偿调解，但当事人一方要求不予公开的除外。 农机安全监理机构调解农机事故损害赔偿的期限为10日。对农机事故致死的，调解自办理丧葬事宜结束之日起开始；对农机事故致伤、致残的，调解自治疗终结或者定残之日起开始；对农机事故造成财产损失的，调解从确定损失之日起开始。 调解涉及保险赔偿的，农机安全监理机构应当提前3日将调解的时间、地点通报相关保险机构，保险机构可以派员以第三人的身份参加调解。经农机安全监理机构主持达成的调解协议，可以作为保险理赔的依据，被保险人据此申请赔偿保险金的，保险人应当按照法律规定和合同约定进行赔偿。"},{"i":40,"n":"第四十条","txt":"事故调解参加人员包括： （一）事故当事人及其代理人或损害赔偿的权利人、义务人； （二）农业机械所有人或者管理人； （三）农机安全监理机构认为有必要参加的其他人员。 委托代理人应当出具由委托人签名或者盖章的授权委托书。授权委托书应当载明委托事项和权限。 参加调解的当事人一方不得超过3人。"},{"i":41,"n":"第四十一条","txt":"调解农机事故损害赔偿争议，按下列程序进行： （一）告知各方当事人的权利、义务； （二）听取各方当事人的请求； （三）根据农机事故认定书的事实以及相关法律法规，调解达成损害赔偿协议。"},{"i":42,"n":"第四十二条","txt":"调解达成协议的，农机安全监理机构应当制作农机事故损害赔偿调解书送达各方当事人，农机事故损害赔偿调解书经各方当事人共同签字后生效。调解达成协议后当事人反悔的，可以依法向人民法院提起民事诉讼。 农机事故损害赔偿调解书应当载明以下内容： （一）调解的依据； （二）农机事故简况和损失情况； （三）各方的损害赔偿责任及比例； （四）损害赔偿的项目和数额； （五）当事人自愿协商达成一致的意见； （六）赔偿方式和期限； （七）调解终结日期。 赔付款由当事人自行交接，当事人要求农机安全监理机构转交的，农机安全监理机构可以转交，并在农机事故损害赔偿调解书上附记。"},{"i":43,"n":"第四十三条","txt":"调解不能达成协议的，农机安全监理机构应当终止调解，并制作农机事故损害赔偿调解终结书送达各方当事人。农机事故损害赔偿调解终结书应当载明未达成协议的原因。"},{"i":44,"n":"第四十四条","txt":"调解期间，当事人向人民法院提起民事诉讼、无正当理由不参加调解或者放弃调解的，农机安全监理机构应当终结调解。"},{"i":45,"n":"第四十五条","txt":"农机事故损害赔偿费原则上应当一次性结算付清。对不明身份死者的人身损害赔偿，农机安全监理机构应当将赔偿费交付有关部门保存，待损害赔偿权利人确认后，通知有关部门交付损害赔偿权利人。"},{"i":46,"n":"第四十六条","txt":"省级农机安全监理机构应当按照农业机械化管理统计报表制度按月报送农机事故。农机事故月报的内容包括农机事故起数、伤亡情况、直接经济损失和事故发生的原因等情况。"},{"i":47,"n":"第四十七条","txt":"发生较大以上的农机事故，事故发生地农机安全监理机构应当立即向农业机械化主管部门报告，并逐级上报至农业农村部农机监理总站。每级上报时间不得超过2小时。必要时，农机安全监理机构可以越级上报事故情况。 农机事故快报应当包括下列内容： （一）事故发生的时间、地点、天气以及事故现场情况； （二）操作人姓名、住址、持证等情况； （三）事故造成的伤亡人数(包括下落不明的人数)及伤亡人员的基本情况、初步估计的直接经济损失； （四）发生事故的农业机械机型、牌证号、是否载有危险物品及危险物品的种类等； （五）事故发生的简要经过； （六）已经采取的措施； （七）其他应当报告的情况。 农机事故发生之日起7日内，事故造成的伤亡人数发生变化的，应当及时补报。"},{"i":48,"n":"第四十八条","txt":"农机安全监理机构应当每月对农机事故情况进行分析评估，向农业机械化主管部门提交事故情况和分析评估报告。 农业农村部每半年发布一次相关信息，通报典型的较大以上农机事故。省级农业机械化主管部门每季度发布一次相关信息，通报典型农机事故。"},{"i":49,"n":"第四十九条","txt":"农业机械化主管部门及其农机安全监理机构有下列行为之一的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；涉嫌犯罪的，及时将案件移送司法机关，依法追究刑事责任： （一）不依法处理农机事故或者不依法出具农机事故认定书等有关材料的； （二）迟报、漏报、谎报或者瞒报事故的； （三）阻碍、干涉事故调查工作的； （四）其他依法应当追究责任的行为。"},{"i":50,"n":"第五十条","txt":"农机事故处理员有下列行为之一的，依法给予行政处分；涉嫌犯罪的，及时将案件移送司法机关，依法追究刑事责任： （一）不立即实施事故抢救的； （二）在事故调查处理期间擅离职守的； （三）利用职务之便，非法占有他人财产的； （四）索取、收受贿赂的； （五）故意或者过失造成认定事实错误、违反法定程序的； （六）应当回避而未回避影响事故公正处理的； （七）其他影响公正处理事故的。"},{"i":51,"n":"第五十一条","txt":"当事人有农机安全违法行为的，农机安全监理机构应当在作出农机事故认定之日起5日内，依照《农业机械安全监督管理条例》作出处罚。 农机事故肇事人构成犯罪的，农机安全监理机构应当在人民法院作出的有罪判决生效后，依法吊销其操作证件；拖拉机驾驶人有逃逸情形的，应当同时依法作出终生不得重新取得拖拉机驾驶证的决定。"},{"i":52,"n":"第五十二条","txt":"农机事故处理文书表格格式、农机事故处理专用印章式样由农业农村部统一制定。"},{"i":53,"n":"第五十三条","txt":"涉外农机事故应当按照本办法处理，并通知外事部门派员协助。国家另有规定的，从其规定。"},{"i":54,"n":"第五十四条","txt":"本办法规定的“日”是指工作日，不含法定节假日。"},{"i":55,"n":"第五十五条","txt":"本办法自2011年3月1日起施行。"}],"nongyejixieweixiuguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范农业机械维修业务，保证农业机械维修质量，维护农业机械维修当事人的合法权益，根据《中华人民共和国农业机械化促进法》和有关法律、行政法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称农业机械维修，是指使用工具、仪器、设备，对农业机械进行维护和修理，使其保持、恢复技术状态和工作能力的技术服务活动。"},{"i":3,"n":"第三条","txt":"从事农业机械维修经营及相关的维修配件销售活动，应当遵守本规定。"},{"i":4,"n":"第四条","txt":"农业机械维修者和维修配件销售者，应当依法经营，诚实守信，公平竞争，优质服务。"},{"i":5,"n":"第五条","txt":"县级以上人民政府农业机械化主管部门、工商行政管理部门按照各自的职责分工，负责本行政区域内的农业机械维修和维修配件经营的监督管理工作，保护农业机械消费者的合法权益。"},{"i":6,"n":"第六条","txt":"国家鼓励农业机械维修技术科研开发，促进农业机械维修新技术、新材料、新工艺和新设备的推广应用，提高维修质量，降低维修费用，节约资源，保护环境。"},{"i":7,"n":"第七条","txt":"农业机械维修者，应当具备符合有关农业行业标准规定的设备、设施、人员、质量管理、安全生产及环境保护等条件，方可从事农业机械维修业务。"},{"i":8,"n":"第八条","txt":"农业机械维修者应公开维修工时定额和收费标准。"},{"i":9,"n":"第九条","txt":"农业机械维修者和维修配件销售者应当向农业机械消费者如实说明维修配件的真实质量状况，农业机械维修者使用可再利用旧配件进行维修时，应当征得送修者同意，并保证农业机械安全性能符合国家安全标准。 禁止农业机械维修者和维修配件销售者从事下列活动： （一）销售不符合国家技术规范强制性要求的农业机械维修配件； （二）使用不符合国家技术规范强制性要求的维修配件维修农业机械； （三）以次充好、以旧充新，或者作引人误解的虚假宣传； （四）利用维修零配件和报废机具的部件拼装农业机械整机； （五）承揽已报废农业机械维修业务。"},{"i":10,"n":"第十条","txt":"农业机械化主管部门应当加强对农业机械维修和维修配件销售从业人员职业技能培训和鉴定工作的指导，提高从业人员素质和技能水平。"},{"i":11,"n":"第十一条","txt":"维修农业机械，应当执行国家有关技术标准、规范或者与用户签订的维修协议，保证维修质量。"},{"i":12,"n":"第十二条","txt":"农业机械维修实行质量保证期制度。在质量保证期内，农业机械因维修质量不合格的，维修者应当免费重新修理。 整机或总成修理质量保证期为3个月。"},{"i":13,"n":"第十三条","txt":"农业机械维修配件销售者对其销售的维修配件质量负责。农业机械维修配件应当用中文标明产品名称、生产厂厂名和厂址，有质量检验合格证。 在质量保证期内的维修配件，应当按照有关规定包修、包换、包退。"},{"i":14,"n":"第十四条","txt":"农业机械维修当事人因维修质量发生争议，可以向农业机械化主管部门投诉，或者向工商行政管理部门投诉，农业机械化主管部门和工商行政管理部门应当受理，调解质量纠纷。调解不成的，应当告知当事人向人民法院提起诉讼或者向仲裁机构申请仲裁。"},{"i":15,"n":"第十五条","txt":"农业机械维修者应当使用符合标准的量具、仪表、仪器等检测器具和其他维修设备，对农业机械的维修应当填写维修记录，并于每年一月份向农业机械化主管部门报送上一年度维修情况统计表。"},{"i":16,"n":"第十六条","txt":"农业机械化主管部门、工商行政管理部门应当按照各自职责，密切配合，加强对农业机械维修者的从业资格、维修人员资格、维修质量、维修设备和检测仪器技术状态以及安全生产情况的监督检查。"},{"i":17,"n":"第十七条","txt":"农业机械化主管部门应当建立健全农业机械维修监督检查制度，加强农机执法人员培训，完善相应技术检测手段，确保行政执法公开、公平、公正。"},{"i":18,"n":"第十八条","txt":"农业机械化主管部门、工商行政管理部门执法人员实施农业机械维修监督检查，应当出示行政执法证件，否则受检查者有权拒绝检查。"},{"i":19,"n":"第十九条","txt":"农业机械维修者和维修配件销售者应当配合农业机械化主管部门、工商行政管理部门依法开展监督检查，如实反映情况，提供有关资料。"},{"i":20,"n":"第二十条","txt":"违反本规定，不能保持设备、设施、人员、质量管理、安全生产和环境保护等技术条件符合要求的，由农业机械化主管部门给予警告，限期整改；拒不改正的，依照《农业机械安全监督管理条例》有关规定予以处罚。"},{"i":21,"n":"第二十一条","txt":"违反本规定，超越范围承揽无技术能力保障的维修项目的，由农业机械化主管部门处200元以上500元以下罚款。"},{"i":22,"n":"第二十二条","txt":"违反本规定第九条第二款第一、三、四项的，由工商行政管理部门依法处理；违反本规定第九条第二款第二、五项的，由农业机械化主管部门处500元以上1000元以下罚款。"},{"i":23,"n":"第二十三条","txt":"农业机械维修者未按规定填写维修记录和报送年度维修情况统计表的，由农业机械化主管部门给予警告，限期改正；逾期拒不改正的，处100元以下罚款。"},{"i":24,"n":"第二十四条","txt":"农业机械化主管部门工作人员玩忽职守、滥用职权、徇私舞弊的，由其所在单位或者上级主管机关依法给予行政处分。"},{"i":25,"n":"第二十五条","txt":"本规定自2006年7月1日起施行。原农牧渔业部、国家工商行政管理局1984年11月15日发布的《全国农村机械维修点管理办法》（〔84〕农〔机〕字第42号）同时废止。"}],"nongyejixieshiyanjiandingbanfa":[{"i":1,"n":"第一条","txt":"为了促进先进适用农业机械的推广应用，维护农业机械使用者及生产者、销售者的合法权益，根据《中华人民共和国农业机械化促进法》和《中华人民共和国农业技术推广法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称农业机械试验鉴定（以下简称农机鉴定），是指农业机械试验鉴定机构（以下简称农机鉴定机构）通过科学试验、检测和考核，对农业机械的适用性、安全性和可靠性作出技术评价，为农业机械的选择和推广提供依据和信息的活动。 根据鉴定目的不同，农机鉴定分为： （一）推广鉴定：全面考核农业机械性能,评定是否适于推广； （二）专项鉴定：考核、评定农业机械创新产品的专项性能。"},{"i":3,"n":"第三条","txt":"农机鉴定由农业机械生产者或者销售者自愿申请。"},{"i":4,"n":"第四条","txt":"农业农村部主管全国农机鉴定工作，制定并公布推广鉴定大纲。 省、自治区、直辖市人民政府农业机械化行政主管部门主管本行政区域的农机鉴定工作，制定并公布专项鉴定大纲，报农业农村部备案。 农机鉴定大纲应当根据法规、标准变化或者农机产品技术发展情况进行修订、废止，不断适应农机鉴定工作需要。"},{"i":5,"n":"第五条","txt":"农机鉴定机构应当制定并定期调整、发布农机鉴定产品种类指南，明确可鉴定的产品范围，依据农机鉴定大纲开展农机鉴定工作。"},{"i":6,"n":"第六条","txt":"农机鉴定属公益性服务，应当坚持公正、公开、科学、高效的原则，推行网上申请、受理、审核、发证、注册管理，接受农业机械使用者、生产者、销售者和社会的监督。"},{"i":7,"n":"第七条","txt":"通过农机鉴定的产品，可以依法纳入国家促进农业机械化技术推广的财政补贴、优惠信贷、政府采购等政策支持的范围。"},{"i":8,"n":"第八条","txt":"农机鉴定由省级以上人民政府农业机械化行政主管部门所属或者指定的农机鉴定机构实施。"},{"i":9,"n":"第九条","txt":"农机鉴定机构应当具备下列条件: （一）不以赢利为目的的公益性事业组织； （二）具有与鉴定工作相适应的工作人员、场所和设施设备； （三）具有符合鉴定工作要求的工作制度和操作规范。"},{"i":10,"n":"第十条","txt":"农业农村部农业机械试验鉴定总站负责组织协调农机鉴定机构开展国家支持的推广鉴定工作。 鼓励各农机鉴定机构之间开展鉴定合作，共享鉴定资源，提高鉴定能力。"},{"i":11,"n":"第十一条","txt":"申请农机鉴定的产品应当符合下列条件： （一）属合格产品； （二）有一定的生产批量； （三）列入农机鉴定产品种类指南； （四）实行强制性认证或者生产许可管理的产品，还应当取得相应的证书； （五）申请前五年内，未违反本办法第二十五条第一项、第五项、第六项、第七项和第三十条的规定。"},{"i":12,"n":"第十二条","txt":"申请农机鉴定的农业机械生产者或者销售者应当向农机鉴定机构提交下列材料: （一）农机鉴定申请表； （二）产品执行标准； （三）产品使用说明书； （四）农机产品合格和申请材料真实性承诺书。 委托他人代理申请的，还应当提交农业机械生产者或者销售者签署的委托书。 申请专项鉴定的产品，还应当提交农机创新产品的说明材料。"},{"i":13,"n":"第十三条","txt":"农机鉴定机构应当在收到申请之日起10日内对申请材料进行审查，决定是否受理，并通知申请者。不予受理的，应当说明理由。"},{"i":14,"n":"第十四条","txt":"农机鉴定机构应当在受理申请后与申请者确定试验鉴定时间，组织人员按鉴定大纲抽取或确认样机，并审核必需的技术文件。"},{"i":15,"n":"第十五条","txt":"鉴定用样机由申请者提供，并按期送到指定试验地点。鉴定结束后，样机由申请者自行处理。"},{"i":16,"n":"第十六条","txt":"农机鉴定内容根据鉴定类型分别确定。 （一）推广鉴定： 1.安全性评价； 2.适用性评价； 3.可靠性评价。 （二）专项鉴定： 1.创新性评价； 2.安全性检查； 3.适用地区性能试验。"},{"i":17,"n":"第十七条","txt":"农机鉴定机构应当在鉴定结束之日起15日内向申请者出具鉴定报告。"},{"i":18,"n":"第十八条","txt":"申请者对鉴定结果有异议的，可以在收到鉴定报告之日起15日内向原鉴定机构申请复验一次。"},{"i":19,"n":"第十九条","txt":"农机鉴定机构应当在指定媒体上公布通过鉴定的产品信息和相应的检测结果。"},{"i":20,"n":"第二十条","txt":"对通过农机鉴定的产品，农机鉴定机构应当在公布后10日内颁发农业机械鉴定证书，产品生产者凭农业机械鉴定证书使用相应的农业机械鉴定标志。"},{"i":21,"n":"第二十一条","txt":"农业机械鉴定证书和标志的式样由农业农村部统一制定、发布。 农机推广鉴定证书的有效期为5年，农机专项鉴定证书的有效期为3年，有效期满仍符合现行鉴定大纲要求的，实行注册管理；不再符合鉴定大纲要求的，证书失效。 禁止伪造、涂改、转让和超范围使用农机鉴定证书和标志。"},{"i":22,"n":"第二十二条","txt":"农机鉴定机构应当组织对通过农机鉴定的产品及农业机械鉴定证书和标志的使用情况进行监督，发现有违反本办法行为的，应当依法处理。"},{"i":23,"n":"第二十三条","txt":"农机鉴定机构应当严格依照鉴定大纲进行农机鉴定，不得伪造鉴定结果或者出具虚假证明，并对鉴定结果承担责任。"},{"i":24,"n":"第二十四条","txt":"通过农机鉴定的产品，其生产企业的名称或者注册地点发生改变的，应当凭相关证明文件向原发证机构申请变更换证；产品结构、型式和主要技术参数变化超出限定范围的，应当重新申请鉴定。"},{"i":25,"n":"第二十五条","txt":"通过农机鉴定的产品，有下列情形之一的，由原发证机构撤销农机鉴定证书，并予公告： （一）产品出现重大质量问题，或出现集中的质量投诉后生产者未在规定期限内解决的； （二）企业名称或者注册地点发生改变在3个月内未申请变更的； （三）产品结构、型式和主要技术参数变化超出限定范围未重新申请鉴定的； （四）在国家产品质量监督抽查或市场质量监督检查中不合格的； （五）通过欺诈、贿赂等手段获取鉴定结果或者证书的； （六）涂改、转让、超范围使用农机鉴定证书和标志的； （七）存在侵犯专利的。"},{"i":26,"n":"第二十六条","txt":"通过农机鉴定的产品，有下列情形之一的，由原发证机构注销农机鉴定证书，并予公告： （一）生产者申请注销的； （二）证书有效期届满未实行注册管理的； （三）国家明令淘汰的； （四）生产者营业执照被吊销的； （五）法律法规规定应当注销的其他情形。"},{"i":27,"n":"第二十七条","txt":"县级以上地方人民政府农业（农业机械化）行政主管部门强制或者变相强制农业机械生产者、销售者对其生产、销售的农业机械产品进行鉴定的，由上级主管机关或者监察机关责令限期改正，并对直接负责的主管人员和其他直接责任人员给予行政处分。"},{"i":28,"n":"第二十八条","txt":"农机鉴定机构不按规定进行鉴定、伪造鉴定结果或者出具虚假证明的，由农业机械化行政主管部门责令改正，对单位负责人和其他直接责任人员，依法给予处分；给农业机械使用者造成损失的，依法承担赔偿责任。"},{"i":29,"n":"第二十九条","txt":"从事农机鉴定工作的人员徇私舞弊、弄虚作假、滥用职权、玩忽职守的，依法给予处分。"},{"i":30,"n":"第三十条","txt":"伪造、冒用或使用过期的农机鉴定证书和标志的，由农机鉴定机构责令停止违法行为，5年内不受理其农机鉴定申请。"},{"i":31,"n":"第三十一条","txt":"本办法所称日，是指工作日。"},{"i":32,"n":"第三十二条","txt":"本办法自2019年4月1日起施行。农业部2005年7月26日发布，2013年12月31日、2015年7月15日修订的《农业机械试验鉴定办法》同时废止。"}],"nongyezhiwupinzhongmingmingguiding":[{"i":1,"n":"第一条","txt":"为规范农业植物品种命名，加强品种名称管理，保护育种者和种子生产者、经营者、使用者的合法权益，根据《中华人民共和国种子法》、《中华人民共和国植物新品种保护条例》和《农业转基因生物安全管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"申请农作物品种审定、品种登记和农业植物新品种权的农业植物品种及其直接应用的亲本的命名，应当遵守本规定。 其他农业植物品种的命名，参照本规定执行。"},{"i":3,"n":"第三条","txt":"农业农村部负责全国农业植物品种名称的监督管理工作。 县级以上地方人民政府农业农村主管部门负责本行政区域内农业植物品种名称的监督管理工作。"},{"i":4,"n":"第四条","txt":"农业农村部建立农业植物品种名称检索系统，供品种命名、审查和查询使用。"},{"i":5,"n":"第五条","txt":"一个农业植物品种只能使用一个中文名称，在先使用的品种名称具有优先性，不能再使用其他的品种名称对同一品种进行命名。 申请植物新品种保护的同时提供英文名称。 相同或者相近的农业植物属内的品种名称不得相同。 相近的农业植物属见附件。"},{"i":6,"n":"第六条","txt":"申请人应当书面保证所申请品种名称在农作物品种审定、品种登记和农业植物新品种权中的一致性。"},{"i":7,"n":"第七条","txt":"相同或者相近植物属内的两个以上品种，以同一名称提出相关申请的，名称授予先申请的品种，后申请的应当重新命名；同日申请的，名称授予先完成培育的品种，后完成培育的应当重新命名。"},{"i":8,"n":"第八条","txt":"品种名称应当使用规范的汉字、英文字母、阿拉伯数字、罗马数字或其组合。品种名称不得超过15个字符。"},{"i":9,"n":"第九条","txt":"品种命名不得存在下列情形： （一）仅以数字或者英文字母组成的； （二）仅以一个汉字组成的； （三）含有国家名称的全称、简称或者缩写的，但存在其他含义且不易误导公众的除外； （四）含有县级以上行政区划的地名或者公众知晓的其他国内外地名的，但地名简称、地名具有其他含义的除外； （五）与政府间国际组织或者其他国际国内知名组织名称相同或者近似的，但经该组织同意或者不易误导公众的除外； （六）容易对植物品种的特征、特性或者育种者身份等引起误解的，但惯用的杂交水稻品种命名除外； （七）夸大宣传的； （八）与他人驰名商标、同类注册商标的名称相同或者近似，未经商标权人书面同意的； （九）含有杂交、回交、突变、芽变、花培等植物遗传育种术语的； （十）含有植物分类学种属名称的，但简称的除外； （十一）违反国家法律法规、社会公德或者带有歧视性的； （十二）不适宜作为品种名称的或者容易引起误解的其他情形。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，属于容易对植物品种的特征、特性引起误解的情形： （一）易使公众误认为该品种具有某种特性或特征，但该品种不具备该特性或特征的； （二）易使公众误认为只有该品种具有某种特性或特征，但同属或者同种内的其他品种同样具有该特性或特征的； （三）易使公众误认为该品种来源于另一品种或者与另一品种有关，实际并不具有联系的； （四）品种名称中含有知名人物名称的，但经该知名人物同意的除外； （五）其他容易对植物品种的特征、特性引起误解的情形。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，属于容易对育种者身份引起误解的情形： （一）品种名称中含有另一知名育种者名称的，但经该知名育种者同意的除外； （二）品种名称与另一已经使用的知名系列品种名称近似的； （三）其他容易对育种者身份引起误解的情形。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，视为品种名称相同： （一）读音或者字义不同但文字相同的； （二）以中文数字、阿拉伯数字或罗马数字表示，但含义为同一数字的； （三）仅以名称中数字后有无“号”字区别的； （四）其他视为品种名称相同的情形。"},{"i":13,"n":"第十三条","txt":"通过基因工程技术改变个别性状的品种，其品种名称与受体品种名称相近似的，应当经过受体品种育种者同意。"},{"i":14,"n":"第十四条","txt":"品种的中文名称译成英文时，应当逐字音译，每个汉字音译的第一个字母应当大写。 品种的外文名称译成中文时，应当优先采用音译；音译名称与已知品种重复的，采用意译；意译仍有重复的，应当另行命名。"},{"i":15,"n":"第十五条","txt":"农业植物品种名称不符合本规定的，申请人应当在指定的期限内予以修改。逾期未修改或者修改后仍不符合规定的，驳回该申请。"},{"i":16,"n":"第十六条","txt":"申请农作物品种审定、品种登记和农业植物新品种权的农业植物品种，在公告前应当在农业农村部网站公示，公示期为15个工作日。省级审定的农作物品种在公告前，应当由省级人民政府农业农村主管部门将品种名称等信息报农业农村部公示。 农业农村部对公示期间提出的异议进行审查，并将异议处理结果通知异议人和申请人。"},{"i":17,"n":"第十七条","txt":"公告后的品种名称不得擅自更改。确需更改的，报原审批单位审批。"},{"i":18,"n":"第十八条","txt":"销售农业植物种子，未使用公告品种名称的，由县级以上人民政府农业农村主管部门按照《中华人民共和国种子法》的规定处罚。"},{"i":19,"n":"第十九条","txt":"申请人以同一品种申请农作物品种审定、品种登记和农业植物新品种权过程中，通过欺骗、贿赂等不正当手段获取多个品种名称的，除由审批机关撤销相应的农作物品种审定、品种登记和农业植物新品种权外，三年内不再受理该申请人相应申请。"},{"i":20,"n":"第二十条","txt":"本规定施行前已取得品种名称的农业植物品种，可以继续使用其名称。对有多个名称的在用品种，由农业农村部组织品种名称清理并重新公告。 本规定施行前已受理但尚未批准的农作物品种审定、品种登记和农业植物新品种权申请，其品种名称不符合本规定要求的，申请人应当在指定期限内重新命名。"},{"i":21,"n":"第二十一条","txt":"本规定自2012年4月15日起施行。"}],"nongyezhiwuxinpinzhongquanqinquananjianchuliguidinff6d5f":[{"i":1,"n":"第一条","txt":"为有效处理农业植物新品种权（以下简称品种权）侵权案件，根据《中华人民共和国植物新品种保护条例》（以下简称《条例》），制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称的品种权侵权案件是指未经品种权人许可，以商业目的生产或销售授权品种的繁殖材料以及将该授权品种的繁殖材料重复使用于生产另一品种的繁殖材料的行为。"},{"i":3,"n":"第三条","txt":"省级以上人民政府农业行政部门负责处理本行政辖区内品种权侵权案件。"},{"i":4,"n":"第四条","txt":"请求省级以上人民政府农业行政部门处理品种权侵权案件的，应当符合下列条件： （一）请求人是品种权人或者利害关系人； （二）有明确的被请求人； （三）有明确的请求事项和具体事实、理由； （四）属于受案农业行政部门的受案范围和管辖； （五）在诉讼时效范围内； （六）当事人没有就该品种权侵权案件向人民法院起诉。 第一项所称利害关系人包括品种权实施许可合同的被许可人、品种权的合法继承人。品种权实施许可合同的被许可人中，独占实施许可合同的被许可人可以单独提出请求；排他实施许可合同的被许可人在品种权人不请求的情况下，可以单独提出请求；除合同另有约定外，普通实施许可合同的被许可人不能单独提出请求。"},{"i":5,"n":"第五条","txt":"请求处理品种权侵权案件的诉讼时效为二年，自品种权人或利害关系人得知或应当得知侵权行为之日起计算。"},{"i":6,"n":"第六条","txt":"请求省级以上人民政府农业行政部门处理品种权侵权案件的，应当提交请求书以及所涉及品种权的品种权证书，并且按照被请求人的数量提供请求书副本。 请求书应当记载以下内容： （一）请求人的姓名或者名称、地址，法定代表人姓名、职务。委托代理的，代理人的姓名和代理机构的名称、地址； （二）被请求人的姓名或者名称、地址； （三）请求处理的事项、事实和理由。 请求书应当由请求人签名或盖章。"},{"i":7,"n":"第七条","txt":"请求符合本办法第六条规定条件的，省级以上人民政府农业行政部门应当在收到请求书之日起7日内立案并书面通知请求人，同时指定3名以上单数承办人员处理该品种权侵权案件；请求不符合本办法第六条规定条件的，省级以上人民政府农业行政部门应当在收到请求书之日起7日内书面通知请求人不予受理，并说明理由。"},{"i":8,"n":"第八条","txt":"省级以上人民政府农业行政部门应当在立案之日起7日内将请求书及其附件的副本通过邮寄、直接送交或者其他方式送被请求人，要求其在收到之日起15日内提交答辩书，并且按照请求人的数量提供答辩书副本。被请求人逾期不提交答辩书的，不影响省级以上人民政府农业行政部门进行处理。被请求人提交答辩书的，省级以上人民政府农业行政部门应当在收到之日起7日内将答辩书副本通过邮寄、直接送交或者其他方式送请求人。"},{"i":9,"n":"第九条","txt":"省级以上人民政府农业行政部门处理品种权侵权案件一般以书面审理为主。必要时，可以举行口头审理，并在口头审理7日前通知当事人口头审理的时间和地点。当事人无正当理由拒不参加的，或者未经允许中途退出的，对请求人按撤回请求处理，对被请求人按缺席处理。 省级以上人民政府农业行政部门举行口头审理的，应当记录参加人和审理情况，经核对无误后，由案件承办人员和参加人签名或盖章。"},{"i":10,"n":"第十条","txt":"除当事人达成调解、和解协议，请求人撤回请求之外，省级以上人民政府农业行政部门对侵权案件应作出处理决定，并制作处理决定书，写明以下内容： （一）请求人、被请求人的姓名或者名称、地址，法定代表人或者主要负责人的姓名、职务，代理人的姓名和代理机构的名称； （二）当事人陈述的事实和理由； （三）认定侵权行为是否成立的理由和依据； （四）处理决定：认定侵权行为成立的，应当责令被请求人立即停止侵权行为，写明处罚内容；认定侵权行为不成立的，应当驳回请求人的请求； （五）不服处理决定申请行政复议或者提起行政诉讼的途径和期限。 处理决定书应当由案件承办人员署名，并加盖省级以上人民政府农业行政部门的公章。"},{"i":11,"n":"第十一条","txt":"省级以上人民政府农业行政部门认定侵权行为成立并作出处理决定的，可以采取下列措施，制止侵权行为： （一）侵权人生产授权品种繁殖材料或者直接使用授权品种的繁殖材料生产另一品种繁殖材料的，责令其立即停止生产，并销毁生产中的植物材料；已获得繁殖材料的，责令其不得销售； （二）侵权人销售授权品种繁殖材料或者销售直接使用授权品种繁殖材料生产另一品种繁殖材料的，责令其立即停止销售行为，并且不得销售尚未售出的侵权品种繁殖材料； （三）没收违法所得； （四）处以违法所得5倍以下的罚款； （五）停止侵权行为的其他必要措施。"},{"i":12,"n":"第十二条","txt":"当事人对省级以上人民政府农业行政部门作出的处理决定不服的，可以依法申请行政复议或者向人民法院提起行政诉讼。期满不申请行政复议或者不起诉又不停止侵权行为的，省级以上人民政府农业行政部门可以申请人民法院强制执行。"},{"i":13,"n":"第十三条","txt":"省级以上人民政府农业行政部门认定侵权行为成立的，可以根据当事人自愿的原则，对侵权所造成的损害赔偿进行调解。必要时，可以邀请有关单位和个人协助调解。 调解达成协议的，省级以上人民政府农业行政部门应当制作调解协议书，写明如下内容： （一）请求人、被请求人的姓名或者名称、地址，法定代表人的姓名、职务。委托代理人的，代理人的姓名和代理机构的名称、地址； （二）案件的主要事实和各方应承担的责任； （三）协议内容以及有关费用的分担。 调解协议书由各方当事人签名或盖章、案件承办人员签名并加盖省级以上人民政府农业行政部门的公章。调解书送达后，当事人应当履行协议。 调解未达成协议的，当事人可以依法向人民法院起诉。"},{"i":14,"n":"第十四条","txt":"侵犯品种权的赔偿数额，按照权利人因被侵权所受到的损失或者侵权人因侵权所获得的利益确定。权利人的损失或者侵权人获得的利益难以确定的，按照品种权许可使用费的1倍以上5倍以下酌情确定。"},{"i":15,"n":"第十五条","txt":"省级以上人民政府农业行政部门或者人民法院作出认定侵权行为成立的处理决定或者判决之后，被请求人就同一品种权再次作出相同类型的侵权行为，品种权人或者利害关系人请求处理的，省级以上人民政府农业行政部门可以直接作出责令立即停止侵权行为的处理决定并采取相应处罚措施。"},{"i":16,"n":"第十六条","txt":"农业行政部门可以按照以下方式确定品种权案件行为人的违法所得： （一）销售侵权或者假冒他人品种权的繁殖材料的，以该品种繁殖材料销售价格乘以销售数量作为其违法所得； （二）订立侵权或者假冒他人品种权合同的，以收取的费用作为其违法所得。"},{"i":17,"n":"第十七条","txt":"省级以上人民政府农业行政部门查处品种权侵权案件和县级以上人民政府农业行政部门查处假冒授权品种案件的程序，适用《农业行政处罚程序规定》。"},{"i":18,"n":"第十八条","txt":"本办法由农业部负责解释。"},{"i":19,"n":"第十九条","txt":"本办法自二○○三年二月一日起施行。"}],"nongyezhiwuyiqingbaogaoyufabuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强农业植物疫情管理，规范疫情报告与发布工作，根据《植物检疫条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称农业植物疫情，是指全国农业植物检疫性有害生物、各省（自治区、直辖市）补充的农业植物检疫性有害生物、境外新传入或境内新发现的潜在的农业植物检疫性有害生物的发生情况。"},{"i":3,"n":"第三条","txt":"农业部主管全国农业植物疫情报告与发布工作。 县级以上地方人民政府农业行政主管部门按照职责分工，主管本行政区域内的农业植物疫情报告与发布工作。 县级以上人民政府农业行政主管部门所属的植物检疫机构负责农业植物疫情报告与发布的具体工作。"},{"i":4,"n":"第四条","txt":"农业植物疫情报告与发布，应当遵循依法、科学、及时的原则。"},{"i":5,"n":"第五条","txt":"县级以上植物检疫机构负责监测、调查本行政区域内的农业植物疫情，并向社会公布农业植物疫情报告联系方式。"},{"i":6,"n":"第六条","txt":"有下列情形之一的，市（地）、县级植物检疫机构应当在12小时内报告省级植物检疫机构，省级植物检疫机构经核实后，应当在12小时内报告农业部所属的植物检疫机构，农业部所属的植物检疫机构应当在12小时内报告农业部： （一）在本行政区域内发现境外新传入或境内新发现的潜在的农业植物检疫性有害生物； （二）全国农业植物检疫性有害生物在本行政区域内新发现或暴发流行； （三）经确认已经扑灭的全国农业植物检疫性有害生物在本行政区域内再次发生。 前款有害生物发生对农业生产构成重大威胁的，农业部依据有关规定及时报告国务院。"},{"i":7,"n":"第七条","txt":"省级植物检疫机构应当于每月5日前，向农业部所属的植物检疫机构汇总报告上一个月本行政区域内全国农业植物检疫性有害生物、境外新传入或境内新发现的潜在的农业植物检疫性有害生物的发生及处置情况，农业部所属的植物检疫机构应当于每月10日前将各省汇总情况报告农业部。"},{"i":8,"n":"第八条","txt":"省级植物检疫机构应当于每年1月10日前，向农业部所属的植物检疫机构报告本行政区域内上一年度农业植物疫情的发生和处置情况，农业部所属的植物检疫机构应当于每年1月20日前将各省汇总情况报告农业部。"},{"i":9,"n":"第九条","txt":"县级以上地方植物检疫机构依照本办法第六条、第七条、第八条的规定报告农业植物疫情时，应当同时报告本级人民政府农业行政主管部门。 对于境外新传入或境内新发现的潜在的农业植物检疫性有害生物疫情，疫情发生地的农业行政主管部门应当提请同级人民政府依法采取必要的处置措施。"},{"i":10,"n":"第十条","txt":"境外新传入或境内新发现的潜在的农业植物检疫性有害生物疫情的报告内容，应当包括有害生物的名称、寄主、发现时间、地点、分布、危害、可能的传播途径以及应急处置措施。 其他农业植物疫情的报告内容，应当包括有害生物名称、疫情涉及的县级行政区、发生面积、危害程度以及疫情处置措施。"},{"i":11,"n":"第十一条","txt":"农业植物疫情被扑灭的，由县级以上地方植物检疫机构按照农业植物疫情报告程序申请解除。"},{"i":12,"n":"第十二条","txt":"农业部及时向国务院有关部门和各省（自治区、直辖市）人民政府农业行政主管部门通报从境外新传入或境内新发现的潜在的农业植物检疫性有害生物疫情。"},{"i":13,"n":"第十三条","txt":"全国农业植物检疫性有害生物及其首次发生和疫情解除情况，由农业部发布。"},{"i":14,"n":"第十四条","txt":"下列农业植物疫情由省级人民政府农业行政主管部门发布，并报农业部备案： （一）省（自治区、直辖市）补充的农业植物检疫性有害生物及其发生、疫情解除情况； （二）农业部已发布的全国农业植物检疫性有害生物在本行政区域内的发生及处置情况。"},{"i":15,"n":"第十五条","txt":"农业植物疫情发生地的市（地）、县级农业行政主管部门及其所属的植物检疫机构应当在农业部或省级人民政府农业行政主管部门发布疫情后，及时向社会通告相关疫情在本行政区域内发生的具体情况，指导有关单位和个人开展防控工作。"},{"i":16,"n":"第十六条","txt":"农业部和省级人民政府农业行政主管部门以外的其他单位和个人不得以任何形式发布农业植物疫情。"},{"i":17,"n":"第十七条","txt":"违反本办法的，依据《植物检疫条例》和相关法律法规给予处罚。"},{"i":18,"n":"第十八条","txt":"本办法自2010年3月1日起施行。"}],"nongyezonghexingzhengzhifaguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强农业综合行政执法机构和执法人员管理，规范农业行政执法行为，根据《中华人民共和国行政处罚法》等有关法律的规定，结合农业综合行政执法工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上人民政府农业农村主管部门及农业综合行政执法机构开展农业综合行政执法工作及相关活动，适用本办法。"},{"i":3,"n":"第三条","txt":"农业综合行政执法工作应当遵循合法行政、合理行政、诚实信用、程序正当、高效便民、权责统一的原则。"},{"i":4,"n":"第四条","txt":"农业农村部负责指导和监督全国农业综合行政执法工作。 县级以上地方人民政府农业农村主管部门负责本辖区内农业综合行政执法工作。"},{"i":5,"n":"第五条","txt":"县级以上地方人民政府农业农村主管部门应当明确农业综合行政执法机构与行业管理、技术支撑机构的职责分工，健全完善线索处置、信息共享、监督抽查、检打联动等协作配合机制，形成执法合力。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府农业农村主管部门应当建立健全跨区域农业行政执法联动机制，加强与其他行政执法部门、司法机关的交流协作。"},{"i":7,"n":"第七条","txt":"县级以上人民政府农业农村主管部门对农业行政执法工作中表现突出、有显著成绩和贡献或者有其他突出事迹的执法机构、执法人员，按照国家和地方人民政府有关规定给予表彰和奖励。"},{"i":8,"n":"第八条","txt":"县级以上地方人民政府农业农村主管部门及其农业综合行政执法机构应当加强基层党组织和党员队伍建设，建立健全党风廉政建设责任制。"},{"i":9,"n":"第九条","txt":"县级以上地方人民政府农业农村主管部门依法设立的农业综合行政执法机构承担并集中行使农业行政处罚以及与行政处罚相关的行政检查、行政强制职能，以农业农村部门名义统一执法。"},{"i":10,"n":"第十条","txt":"省级农业综合行政执法机构承担并集中行使法律、法规、规章明确由省级人民政府农业农村主管部门及其所属单位承担的农业行政执法职责，负责查处具有重大影响的跨区域复杂违法案件，监督指导、组织协调辖区内农业行政执法工作。 市级农业综合行政执法机构承担并集中行使法律、法规、规章规定明确由市级人民政府农业农村主管部门及其所属单位承担的农业行政执法职责，负责查处具有较大影响的跨区域复杂违法案件及其直接管辖的市辖区内一般农业违法案件，监督指导、组织协调辖区内农业行政执法工作。 县级农业综合行政执法机构负责统一实施辖区内日常执法检查和一般农业违法案件查处工作。"},{"i":11,"n":"第十一条","txt":"农业农村部建立健全执法办案指导机制，分领域遴选执法办案能手，组建全国农业行政执法专家库。 市级以上地方人民政府农业农村主管部门应当选调辖区内农业行政执法骨干组建执法办案指导小组，加强对基层农业行政执法工作的指导。"},{"i":12,"n":"第十二条","txt":"县级以上地方人民政府农业农村主管部门应当建立与乡镇人民政府、街道办事处执法协作机制，引导和支持乡镇人民政府、街道办事处执法机构协助农业综合行政执法机构开展日常巡查、投诉举报受理以及调查取证等工作。 县级农业行政处罚权依法交由乡镇人民政府、街道办事处行使的，县级人民政府农业农村主管部门应当加强对乡镇人民政府、街道办事处综合行政执法机构的业务指导和监督，提供专业技术、业务培训等方面的支持保障。"},{"i":13,"n":"第十三条","txt":"上级农业农村主管部门及其农业综合行政执法机构可以根据工作需要，经下级农业农村主管部门同意后，按程序调用下级农业综合行政执法机构人员开展调查、取证等执法工作。 持有行政执法证件的农业综合行政执法人员，可以根据执法协同工作需要，参加跨部门、跨区域、跨层级的行政执法活动。"},{"i":14,"n":"第十四条","txt":"农业综合行政执法人员应当经过岗位培训，考试合格并取得行政执法证件后，方可从事行政执法工作。 农业综合行政执法机构应当鼓励和支持农业综合行政执法人员参加国家统一法律职业资格考试，取得法律职业资格。"},{"i":15,"n":"第十五条","txt":"农业农村部负责制定全国农业综合行政执法人员培训大纲，编撰统编执法培训教材，组织开展地方执法骨干和师资培训。 县级以上地方人民政府农业农村主管部门应当制定培训计划，组织开展本辖区内执法人员培训。鼓励有条件的地方建设农业综合行政执法实训基地、现场教学基地。 农业综合行政执法人员每年应当接受不少于60学时的公共法律知识、业务法律知识和执法技能培训。"},{"i":16,"n":"第十六条","txt":"县级以上人民政府农业农村主管部门应当定期开展执法练兵比武活动，选拔和培养业务水平高、综合素质强的执法办案能手。"},{"i":17,"n":"第十七条","txt":"农业综合行政执法机构应当建立和实施执法人员定期轮岗制度，培养通专结合、一专多能的执法人才。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府农业农村主管部门可以根据工作需要，按照规定程序和权限为农业综合行政执法机构配置行政执法辅助人员。 行政执法辅助人员应当在农业综合行政执法机构及执法人员的指导和监督下开展行政执法辅助性工作。禁止辅助人员独立执法。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府农业农村主管部门实施行政处罚及相关执法活动，应当做到事实清楚，证据充分，程序合法，定性准确，适用法律正确，裁量合理，文书规范。 农业综合行政执法人员应当依照法定权限履行行政执法职责，做到严格规范公正文明执法，不得玩忽职守、超越职权、滥用职权。"},{"i":20,"n":"第二十条","txt":"县级以上人民政府农业农村主管部门应当通过本部门或者本级政府官方网站、公示栏、执法服务窗口等平台，向社会公开行政执法人员、职责、依据、范围、权限、程序等农业行政执法基本信息，并及时根据法律法规及机构职能、执法人员等变化情况进行动态调整。 县级以上人民政府农业农村主管部门作出涉及农产品质量安全、农资质量、耕地质量、动植物疫情防控、农机、农业资源生态环境保护、植物新品种权保护等具有一定社会影响的行政处罚决定，应当依法向社会公开。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府农业农村主管部门应当通过文字、音像等形式，对农业行政执法的启动、调查取证、审核决定、送达执行等全过程进行记录，全面系统归档保存，做到执法全过程留痕和可回溯管理。 查封扣押财产、收缴销毁违法物品产品等直接涉及重大财产权益的现场执法活动，以及调查取证、举行听证、留置送达和公告送达等容易引发争议的行政执法过程，应当全程音像记录。 农业行政执法制作的法律文书、音像等记录资料，应当按照有关法律法规和档案管理规定归档保存。"},{"i":22,"n":"第二十二条","txt":"县级以上地方人民政府农业农村主管部门作出涉及重大公共利益，可能造成重大社会影响或引发社会风险，案件情况疑难复杂、涉及多个法律关系等重大执法决定前，应当依法履行法制审核程序。未经法制审核或者审核未通过的，不得作出决定。 县级以上地方人民政府农业农村主管部门应当结合本部门行政执法行为类别、执法层级、所属领域、涉案金额等，制定本部门重大执法决定法制审核目录清单。"},{"i":23,"n":"第二十三条","txt":"农业综合行政执法机构制作农业行政执法文书，应当遵照农业农村部制定的农业行政执法文书制作规范和农业行政执法基本文书格式。 农业行政执法文书的内容应当符合有关法律、法规和规章的规定，做到格式统一、内容完整、表述清楚、逻辑严密、用语规范。"},{"i":24,"n":"第二十四条","txt":"农业农村部可以根据统一和规范全国农业行政执法裁量尺度的需要，针对特定的农业行政处罚事项制定自由裁量权基准。 县级以上地方人民政府农业农村主管部门应当根据法律、法规、规章以及农业农村部规定，制定本辖区农业行政处罚自由裁量权基准，明确裁量标准和适用条件，并向社会公开。 县级以上人民政府农业农村主管部门行使农业行政处罚自由裁量权，应当根据违法行为的事实、性质、情节、社会危害程度等，准确适用行政处罚种类和处罚幅度。"},{"i":25,"n":"第二十五条","txt":"农业综合行政执法人员开展执法检查、调查取证、采取强制措施和强制执行、送达执法文书等执法时，应当主动出示执法证件，向当事人和相关人员表明身份，并按照规定要求统一着执法服装、佩戴农业执法标志。"},{"i":26,"n":"第二十六条","txt":"农业农村部定期发布农业行政执法指导性案例，规范和统一全国农业综合行政执法法律适用。 县级以上人民政府农业农村主管部门应当及时发布辖区内农业行政执法典型案例，发挥警示和震慑作用。"},{"i":27,"n":"第二十七条","txt":"农业综合行政执法机构应当坚持处罚与教育相结合，按照“谁执法谁普法”的要求，将法治宣传教育融入执法工作全过程。 县级农业综合行政执法人员应当采取包区包片等方式，与农村学法用法示范户建立联系机制。"},{"i":28,"n":"第二十八条","txt":"农业综合行政执法人员依法履行法定职责受法律保护，非因法定事由、非经法定程序，不受处分。任何组织和个人不得阻挠、妨碍农业综合行政执法人员依法执行公务。 农业综合行政执法人员因故意或者重大过失，不履行或者违法履行行政执法职责，造成危害后果或者不良影响的，应当依法承担行政责任。"},{"i":29,"n":"第二十九条","txt":"农业综合行政执法机构及其执法人员应当严格依照法律、法规、规章的要求进行执法，严格遵守下列规定： （一）不准徇私枉法、庇护违法者； （二）不准越权执法、违反程序办案； （三）不准干扰市场主体正常经营活动； （四）不准利用职务之便为自己和亲友牟利； （五）不准执法随意、畸轻畸重、以罚代管； （六）不准作风粗暴。"},{"i":30,"n":"第三十条","txt":"县级以上地方人民政府农业农村主管部门应当落实执法经费财政保障制度，将农业行政执法运行经费、执法装备建设经费、执法抽检经费、罚没物品保管处置经费等纳入部门预算，确保满足执法工作需要。"},{"i":31,"n":"第三十一条","txt":"县级以上人民政府农业农村主管部门应当依托大数据、云计算、人工智能等信息技术手段，加强农业行政执法信息化建设，推进执法数据归集整合、互联互通。 农业综合行政执法机构应当充分利用已有执法信息系统和信息共享平台，全面推行掌上执法、移动执法，实现执法程序网上流转、执法活动网上监督、执法信息网上查询。"},{"i":32,"n":"第三十二条","txt":"县级以上地方人民政府农业农村主管部门应当根据执法工作需要，为农业综合行政执法机构配置执法办公用房和问询室、调解室、听证室、物证室、罚没收缴扣押物品仓库等执法辅助用房。"},{"i":33,"n":"第三十三条","txt":"县级以上地方人民政府农业农村主管部门应当按照党政机关公务用车管理办法、党政机关执法执勤用车配备使用管理办法等有关规定，结合本辖区农业行政执法实际，为农业综合行政执法机构合理配备农业行政执法执勤用车。 县级以上地方人民政府农业农村主管部门应当按照有关执法装备配备标准为农业综合行政执法机构配备依法履职所需的基础装备、取证设备、应急设备和个人防护设备等执法装备。"},{"i":34,"n":"第三十四条","txt":"县级以上地方人民政府农业农村主管部门内设或所属的农业综合行政执法机构中在编在职执法人员，统一配发农业综合行政执法制式服装和标志。 县级以上地方人民政府农业农村主管部门应当按照综合行政执法制式服装和标志管理办法及有关技术规范配发制式服装和标志，不得自行扩大着装范围和提高发放标准，不得改变制式服装和标志样式。 农业综合行政执法人员应当妥善保管制式服装和标志，辞职、调离或者被辞退、开除的，应当交回所有制式服装和帽徽、臂章、肩章等标志；退休的，应当交回帽徽、臂章、肩章等所有标志。"},{"i":35,"n":"第三十五条","txt":"农业农村部制定、发布全国统一的农业综合行政执法标识。 县级以上地方人民政府农业农村主管部门应当按照农业农村部有关要求，规范使用执法标识，不得随意改变标识的内容、颜色、内部结构及比例。 农业综合行政执法标识所有权归农业农村部所有。未经许可，任何单位和个人不得擅自使用，不得将相同或者近似标识作为商标注册。"},{"i":36,"n":"第三十六条","txt":"上级农业农村部门应当对下级农业农村部门及其农业综合行政执法机构的行政执法工作情况进行监督，及时纠正违法或明显不当的行为。"},{"i":37,"n":"第三十七条","txt":"属于社会影响重大、案情复杂或者可能涉及犯罪的重大违法案件，上级农业农村部门可以采取发函督办、挂牌督办、现场督办等方式，督促下级农业农村部门及其农业综合行政执法机构调查处理。接办案件的农业农村部门及其农业综合行政执法机构应当及时调查处置，并按要求反馈查处进展情况和结果。"},{"i":38,"n":"第三十八条","txt":"县级以上人民政府农业农村主管部门应当建立健全行政执法文书和案卷评查制度，定期开展评查，发布评查结果。"},{"i":39,"n":"第三十九条","txt":"县级以上地方人民政府农业农村主管部门应当定期对本单位农业综合行政执法工作情况进行考核评议。考核评议结果作为农业行政执法人员职级晋升、评优评先的重要依据。"},{"i":40,"n":"第四十条","txt":"农业综合行政执法机构应当建立行政执法情况统计报送制度，按照农业农村部有关要求，于每年6月30日和12月31日前向本级农业农村主管部门和上一级农业综合行政执法机构报送半年、全年执法统计情况。"},{"i":41,"n":"第四十一条","txt":"县级以上地方人民政府农业农村主管部门应当健全群众监督、舆论监督等社会监督机制，对人民群众举报投诉、新闻媒体曝光、有关部门移送的涉农违法案件及时回应，妥善处置。"},{"i":42,"n":"第四十二条","txt":"鼓励县级以上地方人民政府农业农村主管部门会同财政、司法行政等有关部门建立重大违法行为举报奖励机制，结合本地实际对举报奖励范围、标准等予以具体规定，规范发放程序，做好全程监督。"},{"i":43,"n":"第四十三条","txt":"县级以上人民政府农业农村主管部门应当建立领导干部干预执法活动、插手具体案件责任追究制度。"},{"i":44,"n":"第四十四条","txt":"县级以上人民政府农业农村主管部门应当建立健全突发问题预警研判和应急处置机制，及时回应社会关切，提高风险防范及应对能力。"},{"i":45,"n":"第四十五条","txt":"本办法自2023年1月1日起施行。"}],"nongyexingzhengchufachengxuguiding":[{"i":1,"n":"第一条","txt":"为规范农业行政处罚程序，保障和监督农业农村主管部门依法实施行政管理，保护公民、法人或者其他组织的合法权益，根据《中华人民共和国行政处罚法》《中华人民共和国行政强制法》等有关法律、行政法规的规定，结合农业农村部门实际，制定本规定。"},{"i":2,"n":"第二条","txt":"农业行政处罚机关实施行政处罚及其相关的行政执法活动，适用本规定。 本规定所称农业行政处罚机关，是指依法行使行政处罚权的县级以上人民政府农业农村主管部门。"},{"i":3,"n":"第三条","txt":"农业行政处罚机关实施行政处罚，应当遵循公正、公开的原则，做到事实清楚，证据充分，程序合法，定性准确，适用法律正确，裁量合理，文书规范。"},{"i":4,"n":"第四条","txt":"农业行政处罚机关实施行政处罚，应当坚持处罚与教育相结合，采取指导、建议等方式，引导和教育公民、法人或者其他组织自觉守法。"},{"i":5,"n":"第五条","txt":"具有下列情形之一的，农业行政执法人员应当主动申请回避，当事人也有权申请其回避： （一）是本案当事人或者当事人的近亲属； （二）本人或者其近亲属与本案有直接利害关系； （三）与本案当事人有其他利害关系，可能影响案件的公正处理。 农业行政处罚机关主要负责人的回避，由该机关负责人集体讨论决定；其他人员的回避，由该机关主要负责人决定。 回避决定作出前，主动申请回避或者被申请回避的人员不停止对案件的调查处理。"},{"i":6,"n":"第六条","txt":"农业行政处罚应当由具有行政执法资格的农业行政执法人员实施。农业行政执法人员不得少于两人，法律另有规定的除外。 农业行政执法人员调查处理农业行政处罚案件时，应当主动向当事人或者有关人员出示行政执法证件，并按规定着装和佩戴执法标志。"},{"i":7,"n":"第七条","txt":"各级农业行政处罚机关应当全面推行行政执法公示制度、执法全过程记录制度、重大执法决定法制审核制度，加强行政执法信息化建设，推进信息共享，提高行政处罚效率。"},{"i":8,"n":"第八条","txt":"县级以上人民政府农业农村主管部门在法定职权范围内实施行政处罚。 县级以上地方人民政府农业农村主管部门内设或所属的农业综合行政执法机构承担并集中行使行政处罚以及与行政处罚有关的行政强制、行政检查职能，以农业农村主管部门名义统一执法。"},{"i":9,"n":"第九条","txt":"县级以上人民政府农业农村主管部门依法设立的派出执法机构，应当在派出部门确定的权限范围内以派出部门的名义实施行政处罚。"},{"i":10,"n":"第十条","txt":"上级农业农村主管部门依法监督下级农业农村主管部门实施的行政处罚。 县级以上人民政府农业农村主管部门负责监督本部门农业综合行政执法机构或者派出执法机构实施的行政处罚。"},{"i":11,"n":"第十一条","txt":"农业行政处罚机关在工作中发现违纪、违法或者犯罪问题线索的，应当按照《执法机关和司法机关向纪检监察机关移送问题线索工作办法》的规定，及时移送纪检监察机关。"},{"i":12,"n":"第十二条","txt":"农业行政处罚由违法行为发生地的农业行政处罚机关管辖。法律、行政法规以及农业农村部规章另有规定的，从其规定。 省、自治区、直辖市农业行政处罚机关应当按照职权法定、属地管理、重心下移的原则，结合违法行为涉及区域、案情复杂程度、社会影响范围等因素，厘清本行政区域内不同层级农业行政处罚机关行政执法权限，明确职责分工。"},{"i":13,"n":"第十三条","txt":"渔业行政违法行为有下列情况之一的，适用“谁查获、谁处理”的原则： （一）违法行为发生在共管区、叠区； （二）违法行为发生在管辖权不明确或者有争议的区域； （三）违法行为发生地与查获地不一致。"},{"i":14,"n":"第十四条","txt":"电子商务平台经营者和通过自建网站、其他网络服务销售商品或者提供服务的电子商务经营者的农业违法行为由其住所地县级以上农业行政处罚机关管辖。 平台内经营者的农业违法行为由其实际经营地县级以上农业行政处罚机关管辖。电子商务平台经营者住所地或者违法物品的生产、加工、存储、配送地的县级以上农业行政处罚机关先行发现违法线索或者收到投诉、举报的，也可以管辖。"},{"i":15,"n":"第十五条","txt":"对当事人的同一违法行为，两个以上农业行政处罚机关都有管辖权的，应当由先立案的农业行政处罚机关管辖。"},{"i":16,"n":"第十六条","txt":"两个以上农业行政处罚机关对管辖发生争议的，应当自发生争议之日起七日内协商解决，协商不成的，报请共同的上一级农业行政处罚机关指定管辖；也可以直接由共同的上一级农业行政机关指定管辖。"},{"i":17,"n":"第十七条","txt":"农业行政处罚机关发现立案查处的案件不属于本部门管辖的，应当将案件移送有管辖权的农业行政处罚机关。受移送的农业行政处罚机关对管辖权有异议的，应当报请共同的上一级农业行政处罚机关指定管辖，不得再自行移送。"},{"i":18,"n":"第十八条","txt":"上级农业行政处罚机关认为有必要时，可以直接管辖下级农业行政处罚机关管辖的案件，也可以将本机关管辖的案件交由下级农业行政处罚机关管辖，必要时可以将下级农业行政处罚机关管辖的案件指定其他下级农业行政处罚机关管辖，但不得违反法律、行政法规的规定。 下级农业行政处罚机关认为依法应由其管辖的农业行政处罚案件重大、复杂或者本地不适宜管辖的，可以报请上一级农业行政处罚机关直接管辖或者指定管辖。上一级农业行政处罚机关应当自收到报送材料之日起七日内作出书面决定。"},{"i":19,"n":"第十九条","txt":"农业行政处罚机关实施农业行政处罚时，需要其他行政机关协助的，可以向有关机关发送协助函，提出协助请求。 农业行政处罚机关在办理跨行政区域案件时，需要其他地区农业行政处罚机关协查的，可以发送协查函。收到协查函的农业行政处罚机关应当予以协助并及时书面告知协查结果。"},{"i":20,"n":"第二十条","txt":"农业行政处罚机关查处案件，对依法应当由原许可、批准的部门作出吊销许可证件等农业行政处罚决定的，应当自作出处理决定之日起十五日内将查处结果及相关材料书面报送或告知原许可、批准的部门，并提出处理建议。"},{"i":21,"n":"第二十一条","txt":"农业行政处罚机关发现所查处的案件不属于农业农村主管部门管辖的，应当按照有关要求和时限移送有管辖权的部门处理。 违法行为涉嫌犯罪的案件，农业行政处罚机关应当依法移送司法机关，不得以行政处罚代替刑事处罚。 农业行政处罚机关应当与司法机关加强协调配合，建立健全案件移送制度，加强证据材料移交、接收衔接，完善案件处理信息通报机制。 农业行政处罚机关应当将移送案件的相关材料妥善保管、存档备查。"},{"i":22,"n":"第二十二条","txt":"公民、法人或者其他组织违反农业行政管理秩序的行为，依法应当给予行政处罚的，农业行政处罚机关必须查明事实；违法事实不清、证据不足的，不得给予行政处罚。"},{"i":23,"n":"第二十三条","txt":"农业行政处罚机关作出农业行政处罚决定前，应当告知当事人拟作出行政处罚内容及事实、理由、依据，并告知当事人依法享有的陈述、申辩、要求听证等权利。 采取普通程序查办的案件，农业行政处罚机关应当制作行政处罚事先告知书送达当事人，并告知当事人可以在收到告知书之日起三日内进行陈述、申辩。符合听证条件的，应当告知当事人可以要求听证。 当事人无正当理由逾期提出陈述、申辩或者要求听证的，视为放弃上述权利。"},{"i":24,"n":"第二十四条","txt":"当事人有权进行陈述和申辩。农业行政处罚机关必须充分听取当事人的意见，对当事人提出的事实、理由和证据，应当进行复核；当事人提出的事实、理由或者证据成立的，应当予以采纳。 农业行政处罚机关不得因当事人陈述、申辩而给予更重的处罚。"},{"i":25,"n":"第二十五条","txt":"违法事实确凿并有法定依据，对公民处以二百元以下、对法人或者其他组织处以三千元以下罚款或者警告的行政处罚的，可以当场作出行政处罚决定。法律另有规定的，从其规定。"},{"i":26,"n":"第二十六条","txt":"当场作出行政处罚决定时，农业行政执法人员应当遵守下列程序： （一）向当事人表明身份，出示行政执法证件； （二）当场查清当事人的违法事实，收集和保存相关证据； （三）在行政处罚决定作出前，应当告知当事人拟作出决定的内容及事实、理由、依据，并告知当事人有权进行陈述和申辩； （四）听取当事人陈述、申辩，并记入笔录； （五）填写预定格式、编有号码、盖有农业行政处罚机关印章的当场处罚决定书，由执法人员签名或者盖章，当场交付当事人；当事人拒绝签收的，应当在行政处罚决定书上注明。 前款规定的行政处罚决定书应当载明当事人的违法行为，行政处罚的种类和依据、罚款数额、时间、地点，申请行政复议、提起行政诉讼的途径和期限以及行政机关名称。"},{"i":27,"n":"第二十七条","txt":"农业行政执法人员应当在作出当场处罚决定之日起、在水上办理渔业行政违法案件的农业行政执法人员应当自抵岸之日起二日内，将案件的有关材料交至所属农业行政处罚机关归档保存。"},{"i":28,"n":"第二十八条","txt":"实施农业行政处罚，除依法可以当场作出的行政处罚外，应当适用普通程序。"},{"i":29,"n":"第二十九条","txt":"农业行政处罚机关对依据监督检查职责或者通过投诉、举报、其他部门移送、上级交办等途径发现的违法行为线索，应当自发现线索或者收到相关材料之日起七日内予以核查，由农业行政处罚机关负责人决定是否立案；因特殊情况不能在规定期限内立案的，经农业行政处罚机关负责人批准，可以延长七日。法律、法规、规章另有规定的除外。"},{"i":30,"n":"第三十条","txt":"符合下列条件的，农业行政处罚机关应当予以立案，并填写行政处罚立案审批表： （一）有涉嫌违反法律、法规和规章的行为； （二）依法应当或者可以给予行政处罚； （三）属于本机关管辖； （四）违法行为发生之日起至被发现之日止未超过二年，或者违法行为有连续、继续状态，从违法行为终了之日起至被发现之日止未超过二年；涉及公民生命健康安全且有危害后果的，上述期限延长至五年。法律另有规定的除外。"},{"i":31,"n":"第三十一条","txt":"对已经立案的案件，根据新的情况发现不符合本规定第三十条规定的立案条件的，农业行政处罚机关应当撤销立案。"},{"i":32,"n":"第三十二条","txt":"农业行政处罚机关对立案的农业违法行为，必须全面、客观、公正地调查，收集有关证据；必要时，按照法律、法规的规定，可以进行检查。 农业行政执法人员在调查或者收集证据、进行检查时，不得少于两人。当事人或者有关人员有权要求农业行政执法人员出示执法证件。执法人员不出示执法证件的，当事人或者有关人员有权拒绝接受调查或者检查。"},{"i":33,"n":"第三十三条","txt":"农业行政执法人员有权依法采取下列措施： （一）查阅、复制书证和其他有关材料； （二）询问当事人或者其他与案件有关的单位和个人； （三）要求当事人或者有关人员在一定的期限内提供有关材料； （四）采取现场检查、勘验、抽样、检验、检测、鉴定、评估、认定、录音、拍照、录像、调取现场及周边监控设备电子数据等方式进行调查取证； （五）对涉案的场所、设施或者财物依法实施查封、扣押等行政强制措施； （六）责令被检查单位或者个人停止违法行为，履行法定义务； （七）其他法律、法规、规章规定的措施。"},{"i":34,"n":"第三十四条","txt":"农业行政处罚证据包括书证、物证、视听资料、电子数据、证人证言、当事人的陈述、鉴定意见、勘验笔录和现场笔录。 证据必须经查证属实，方可作为农业行政处罚机关认定案件事实的根据。立案前依法取得或收集的证据材料，可以作为案件的证据使用。 以非法手段取得的证据，不得作为认定案件事实的根据。"},{"i":35,"n":"第三十五条","txt":"收集、调取的书证、物证应当是原件、原物。收集、调取原件、原物确有困难的，可以提供与原件核对无误的复制件、影印件或者抄录件，也可以提供足以反映原物外形或者内容的照片、录像等其他证据。 复制件、影印件、抄录件和照片由证据提供人或者执法人员核对无误后注明与原件、原物一致，并注明出证日期、证据出处，同时签名或者盖章。"},{"i":36,"n":"第三十六条","txt":"收集、调取的视听资料应当是有关资料的原始载体。调取原始载体确有困难的，可以提供复制件，并注明制作方法、制作时间、制作人和证明对象等。声音资料应当附有该声音内容的文字记录。"},{"i":37,"n":"第三十七条","txt":"收集、调取的电子数据应当是有关数据的原始载体。收集电子数据原始载体确有困难的，可以采用拷贝复制、委托分析、书式固定、拍照录像等方式取证，并注明制作方法、制作时间、制作人等。 农业行政处罚机关可以利用互联网信息系统或者设备收集、固定违法行为证据。用来收集、固定违法行为证据的互联网信息系统或者设备应当符合相关规定，保证所收集、固定电子数据的真实性、完整性。 农业行政处罚机关可以指派或者聘请具有专门知识的人员或者专业机构，辅助农业行政执法人员对与案件有关的电子数据进行调查取证。"},{"i":38,"n":"第三十八条","txt":"农业行政执法人员询问证人或者当事人，应当个别进行，并制作询问笔录。 询问笔录有差错、遗漏的，应当允许被询问人更正或者补充。更正或者补充的部分应当由被询问人签名、盖章或者按指纹等方式确认。 询问笔录经被询问人核对无误后，由被询问人在笔录上逐页签名、盖章或者按指纹等方式确认。农业行政执法人员应当在笔录上签名。被询问人拒绝签名、盖章或者按指纹的，由农业行政执法人员在笔录上注明情况。"},{"i":39,"n":"第三十九条","txt":"农业行政执法人员对与案件有关的物品或者场所进行现场检查或者勘验，应当通知当事人到场，制作现场检查笔录或者勘验笔录，必要时可以采取拍照、录像或者其他方式记录现场情况。 当事人拒不到场、无法找到当事人或者当事人拒绝签名或盖章的，农业行政执法人员应当在笔录中注明，并可以请在场的其他人员见证。"},{"i":40,"n":"第四十条","txt":"农业行政处罚机关在调查案件时，对需要检测、检验、鉴定、评估、认定的专门性问题，应当委托具有法定资质的机构进行；没有具有法定资质的机构的，可以委托其他具备条件的机构进行。 检验、检测、鉴定、评估、认定意见应当由检验、检测、鉴定、评估、认定人员签名或者盖章，并加盖所在机构公章。检验、检测、鉴定、评估、认定意见应当送达当事人。"},{"i":41,"n":"第四十一条","txt":"农业行政处罚机关收集证据时，可以采取抽样取证的方法。农业行政执法人员应当制作抽样取证凭证，对样品加贴封条，并由执法人员和当事人在抽样取证凭证上签名或者盖章。当事人拒绝签名或者盖章的，应当采取拍照、录像或者其他方式记录抽样取证情况。 农业行政处罚机关抽样送检的，应当将抽样检测结果及时告知当事人，并告知当事人有依法申请复检的权利。 非从生产单位直接抽样取证的，农业行政处罚机关可以向产品标注生产单位发送产品确认通知书，对涉案产品是否为其生产的产品进行确认，并可以要求其在一定期限内提供相关证明材料。"},{"i":42,"n":"第四十二条","txt":"在证据可能灭失或者以后难以取得的情况下，经农业行政处罚机关负责人批准，农业行政执法人员可以对与涉嫌违法行为有关的证据采取先行登记保存措施。 情况紧急，农业行政执法人员需要当场采取先行登记保存措施的，可以采用即时通讯方式报请农业行政处罚机关负责人同意，并在二十四小时内补办批准手续。 先行登记保存有关证据，应当当场清点，开具清单，填写先行登记保存执法文书，由农业行政执法人员和当事人签名、盖章或者按指纹，并向当事人交付先行登记保存证据通知书和物品清单。"},{"i":43,"n":"第四十三条","txt":"先行登记保存物品时，就地由当事人保存的，当事人或者有关人员不得使用、销售、转移、损毁或者隐匿。 就地保存可能妨害公共秩序、公共安全，或者存在其他不适宜就地保存情况的，可以异地保存。对异地保存的物品，农业行政处罚机关应当妥善保管。"},{"i":44,"n":"第四十四条","txt":"农业行政处罚机关对先行登记保存的证据，应当自采取登记保存之日起七日内作出下列处理决定并送达当事人： （一）根据情况及时采取记录、复制、拍照、录像等证据保全措施； （二）需要进行技术检测、检验、鉴定、评估、认定的，送交有关机构检测、检验、鉴定、评估、认定； （三）对依法应予没收的物品，依照法定程序处理； （四）对依法应当由有关部门处理的，移交有关部门； （五）为防止损害公共利益，需要销毁或者无害化处理的，依法进行处理； （六）不需要继续登记保存的，解除先行登记保存。"},{"i":45,"n":"第四十五条","txt":"农业行政处罚机关依法对涉案场所、设施或者财物采取查封、扣押等行政强制措施，应当在实施前向农业行政处罚机关负责人报告并经批准，由具备资格的农业行政执法人员实施。 情况紧急，需要当场采取行政强制措施的，农业行政执法人员应当在二十四小时内向农业行政处罚机关负责人报告，并补办批准手续。农业行政处罚机关负责人认为不应当采取行政强制措施的，应当立即解除。 查封、扣押的场所、设施或者财物，应当妥善保管，不得使用或者损毁。除法律、法规另有规定外，鲜活产品、保管困难或者保管费用过高的物品和其他容易损毁、灭失、变质的物品，在确定为罚没财物前，经权利人同意或者申请，并经农业行政处罚机关负责人批准，在采取相关措施留存证据后，可以依法先行处置；权利人不明确的，可以依法公告，公告期满后仍没有权利人同意或者申请的，可以依法先行处置。先行处置所得款项按照涉案现金管理。"},{"i":46,"n":"第四十六条","txt":"农业行政处罚机关实施查封、扣押等行政强制措施，应当履行《中华人民共和国行政强制法》规定的程序和要求，制作并当场交付查封、扣押决定书和清单。"},{"i":47,"n":"第四十七条","txt":"经查明与违法行为无关或者不再需要采取查封、扣押措施的，应当解除查封、扣押措施，将查封、扣押的财物如数返还当事人，并由农业行政执法人员和当事人在解除查封或者扣押决定书和清单上签名、盖章或者按指纹。"},{"i":48,"n":"第四十八条","txt":"有下列情形之一的，经农业行政处罚机关负责人批准，中止案件调查，并制作案件中止调查决定书： （一）行政处罚决定必须以相关案件的裁判结果或者其他行政决定为依据，而相关案件尚未审结或者其他行政决定尚未作出； （二）涉及法律适用等问题，需要送请有权机关作出解释或者确认； （三）因不可抗力致使案件暂时无法调查； （四）因当事人下落不明致使案件暂时无法调查； （五）其他应当中止调查的情形。 中止调查的原因消除后，应当立即恢复案件调查。"},{"i":49,"n":"第四十九条","txt":"农业行政执法人员在调查结束后，应当根据不同情形提出如下处理建议，并制作案件处理意见书，报请农业行政处罚机关负责人审查： （一）确有应受行政处罚的违法行为的，根据情节轻重及具体情况，建议作出行政处罚； （二）违法事实不能成立的，建议不予行政处罚； （三）违法行为轻微并及时改正，没有造成危害后果的，建议不予行政处罚； （四）当事人有证据足以证明没有主观过错的，建议不予行政处罚，但法律、行政法规另有规定的除外； （五）初次违法且危害后果轻微并及时改正的，建议可以不予行政处罚； （六）违法行为超过追责时效的，建议不再给予行政处罚； （七）违法行为不属于农业行政处罚机关管辖的，建议移送其他行政机关； （八）违法行为涉嫌犯罪应当移送司法机关的，建议移送司法机关； （九）依法作出处理的其他情形。"},{"i":50,"n":"第五十条","txt":"有下列情形之一，在农业行政处罚机关负责人作出农业行政处罚决定前，应当由从事农业行政处罚决定法制审核的人员进行法制审核；未经法制审核或者审核未通过的，农业行政处罚机关不得作出决定： （一）涉及重大公共利益的； （二）直接关系当事人或者第三人重大权益，经过听证程序的； （三）案件情况疑难复杂、涉及多个法律关系的； （四）法律、法规规定应当进行法制审核的其他情形。 农业行政处罚法制审核工作由农业行政处罚机关法制机构负责；未设置法制机构的，由农业行政处罚机关确定的承担法制审核工作的其他机构或者专门人员负责。 案件查办人员不得同时作为该案件的法制审核人员。农业行政处罚机关中初次从事法制审核的人员，应当通过国家统一法律职业资格考试取得法律职业资格。"},{"i":51,"n":"第五十一条","txt":"农业行政处罚决定法制审核的主要内容包括： （一）本机关是否具有管辖权； （二）程序是否合法； （三）案件事实是否清楚，证据是否确实、充分； （四）定性是否准确； （五）适用法律依据是否正确； （六）当事人基本情况是否清楚； （七）处理意见是否适当； （八）其他应当审核的内容。 除本规定第五十条第一款规定以外，适用普通程序的其他农业行政处罚案件，在作出处罚决定前，应当参照前款规定进行案件审核。审核工作由农业行政处罚机关的办案机构或其他机构负责实施。"},{"i":52,"n":"第五十二条","txt":"法制审核结束后，应当区别不同情况提出如下建议： （一）对事实清楚、证据充分、定性准确、适用依据正确、程序合法、处理适当的案件，拟同意作出行政处罚决定； （二）对定性不准、适用依据错误、程序不合法或者处理不当的案件，建议纠正； （三）对违法事实不清、证据不充分的案件，建议补充调查或者撤销案件； （四）违法行为轻微并及时纠正没有造成危害后果的，或者违法行为超过追责时效的，建议不予行政处罚； （五）认为有必要提出的其他意见和建议。"},{"i":53,"n":"第五十三条","txt":"法制审核机构或者法制审核人员应当自接到审核材料之日起五日内完成审核。特殊情况下，经农业行政处罚机关负责人批准，可以延长十五日。法律、法规、规章另有规定的除外。"},{"i":54,"n":"第五十四条","txt":"农业行政处罚机关负责人应当对调查结果、当事人陈述申辩或者听证情况、案件处理意见和法制审核意见等进行全面审查，并区别不同情况分别作出如下处理决定： （一）确有应受行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）违法事实不能成立的，不予行政处罚； （三）违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚； （四）当事人有证据足以证明没有主观过错的，不予行政处罚，但法律、行政法规另有规定的除外； （五）初次违法且危害后果轻微并及时改正的，可以不予行政处罚； （六）违法行为超过追责时效的，不予行政处罚； （七）不属于农业行政处罚机关管辖的，移送其他行政机关处理； （八）违法行为涉嫌犯罪的，将案件移送司法机关。"},{"i":55,"n":"第五十五条","txt":"下列行政处罚案件，应当由农业行政处罚机关负责人集体讨论决定： （一）符合本规定第五十九条所规定的听证条件，且申请人申请听证的案件； （二）案情复杂或者有重大社会影响的案件； （三）有重大违法行为需要给予较重行政处罚的案件； （四）农业行政处罚机关负责人认为应当提交集体讨论的其他案件。"},{"i":56,"n":"第五十六条","txt":"农业行政处罚机关决定给予行政处罚的，应当制作行政处罚决定书。行政处罚决定书应当载明以下内容： （一）当事人的姓名或者名称、地址； （二）违反法律、法规、规章的事实和证据； （三）行政处罚的种类和依据； （四）行政处罚的履行方式和期限； （五）申请行政复议、提起行政诉讼的途径和期限； （六）作出行政处罚决定的农业行政处罚机关名称和作出决定的日期。 农业行政处罚决定书应当加盖作出行政处罚决定的行政机关的印章。"},{"i":57,"n":"第五十七条","txt":"在边远、水上和交通不便的地区按普通程序实施处罚时，农业行政执法人员可以采用即时通讯方式，报请农业行政处罚机关负责人批准立案和对调查结果及处理意见进行审查。报批记录必须存档备案。当事人可当场向农业行政执法人员进行陈述和申辩。当事人当场书面放弃陈述和申辩的，视为放弃权利。 前款规定不适用于本规定第五十五条规定的应当由农业行政处罚机关负责人集体讨论决定的案件。"},{"i":58,"n":"第五十八条","txt":"农业行政处罚案件应当自立案之日起九十日内作出处理决定；因案情复杂、调查取证困难等需要延长的，经本农业行政处罚机关负责人批准，可以延长三十日。案情特别复杂或者有其他特殊情况，延期后仍不能作出处理决定的，应当报经上一级农业行政处罚机关决定是否继续延期；决定继续延期的，应当同时确定延长的合理期限。 案件办理过程中，中止、听证、公告、检验、检测、鉴定等时间不计入前款所指的案件办理期限。"},{"i":59,"n":"第五十九条","txt":"农业行政处罚机关依照《中华人民共和国行政处罚法》第六十三条的规定，在作出较大数额罚款、没收较大数额违法所得、没收较大价值非法财物、降低资质等级、吊销许可证件、责令停产停业、责令关闭、限制从业等较重农业行政处罚决定前，应当告知当事人有要求举行听证的权利。当事人要求听证的，农业行政处罚机关应当组织听证。 前款所称的较大数额、较大价值，县级以上地方人民政府农业农村主管部门按所在省、自治区、直辖市人民代表大会及其常委会或者人民政府规定的标准执行。农业农村部规定的较大数额、较大价值，对个人是指超过一万元，对法人或者其他组织是指超过十万元。"},{"i":60,"n":"第六十条","txt":"听证由拟作出行政处罚的农业行政处罚机关组织。具体实施工作由其法制机构或者相应机构负责。"},{"i":61,"n":"第六十一条","txt":"当事人要求听证的，应当在收到行政处罚事先告知书之日起五日内向听证机关提出。"},{"i":62,"n":"第六十二条","txt":"听证机关应当在举行听证会的七日前送达行政处罚听证会通知书，告知当事人及有关人员举行听证的时间、地点、听证人员名单及当事人可以申请回避和可以委托代理人等事项。 当事人可以亲自参加听证，也可以委托一至二人代理。当事人及其代理人应当按期参加听证，无正当理由拒不出席听证或者未经许可中途退出听证的，视为放弃听证权利，行政机关终止听证。"},{"i":63,"n":"第六十三条","txt":"听证参加人由听证主持人、听证员、书记员、案件调查人员、当事人及其委托代理人等组成。 听证主持人、听证员、书记员应当由听证机关负责人指定的法制工作机构工作人员或者其他相应工作人员等非本案调查人员担任。 当事人委托代理人参加听证的，应当提交授权委托书。"},{"i":64,"n":"第六十四条","txt":"除涉及国家秘密、商业秘密或者个人隐私依法予以保密等情形外，听证应当公开举行。"},{"i":65,"n":"第六十五条","txt":"当事人在听证中的权利和义务： （一）有权对案件的事实认定、法律适用及有关情况进行陈述和申辩； （二）有权对案件调查人员提出的证据质证并提出新的证据； （三）如实回答主持人的提问； （四）遵守听证会场纪律，服从听证主持人指挥。"},{"i":66,"n":"第六十六条","txt":"听证按下列程序进行： （一）听证书记员宣布听证会场纪律、当事人的权利和义务，听证主持人宣布案由、核实听证参加人名单、宣布听证开始； （二）案件调查人员提出当事人的违法事实、出示证据，说明拟作出的农业行政处罚的内容及法律依据； （三）当事人或者其委托代理人对案件的事实、证据、适用的法律等进行陈述、申辩和质证，可以当场向听证会提交新的证据，也可以在听证会后三日内向听证机关补交证据； （四）听证主持人就案件的有关问题向当事人、案件调查人员、证人询问； （五）案件调查人员、当事人或者其委托代理人相互辩论； （六）当事人或者其委托代理人作最后陈述； （七）听证主持人宣布听证结束。听证笔录交当事人和案件调查人员审核无误后签字或者盖章。 当事人或者其代理人拒绝签字或者盖章的，由听证主持人在笔录中注明。"},{"i":67,"n":"第六十七条","txt":"听证结束后，听证主持人应当依据听证情况，制作行政处罚听证会报告书，连同听证笔录，报农业行政处罚机关负责人审查。农业行政处罚机关应当根据听证笔录，按照本规定第五十四条的规定，作出决定。"},{"i":68,"n":"第六十八条","txt":"听证机关组织听证，不得向当事人收取费用。"},{"i":69,"n":"第六十九条","txt":"农业行政处罚机关送达行政处罚决定书，应当在宣告后当场交付当事人；当事人不在场的，应当在七日内依照《中华人民共和国民事诉讼法》的有关规定将行政处罚决定书送达当事人。 当事人同意并签订确认书的，农业行政处罚机关可以采用传真、电子邮件等方式，将行政处罚决定书等送达当事人。"},{"i":70,"n":"第七十条","txt":"农业行政处罚机关送达行政执法文书，应当使用送达回证，由受送达人在送达回证上记明收到日期，签名或者盖章。 受送达人是公民的，本人不在时交其同住成年家属签收；受送达人是法人或者其他组织的，应当由法人的法定代表人、其他组织的主要负责人或者该法人、其他组织负责收件的有关人员签收；受送达人有代理人的，可以送交其代理人签收；受送达人已向农业行政处罚机关指定代收人的，送交代收人签收。 受送达人、受送达人的同住成年家属、法人或者其他组织负责收件的有关人员、代理人、代收人在送达回证上签收的日期为送达日期。"},{"i":71,"n":"第七十一条","txt":"受送达人或者他的同住成年家属拒绝接收行政执法文书的，送达人可以邀请有关基层组织或者其所在单位的代表到场，说明情况，在送达回证上记明拒收事由和日期，由送达人、见证人签名或者盖章，把行政执法文书留在受送达人的住所；也可以把行政执法文书留在受送达人的住所，并采用拍照、录像等方式记录送达过程，即视为送达。"},{"i":72,"n":"第七十二条","txt":"直接送达行政执法文书有困难的，农业行政处罚机关可以邮寄送达或者委托其他农业行政处罚机关代为送达。 受送达人下落不明，或者采用直接送达、留置送达、委托送达等方式无法送达的，农业行政处罚机关可以公告送达。 委托送达的，受送达人的签收日期为送达日期；邮寄送达的，以回执上注明的收件日期为送达日期；公告送达的，自发出公告之日起经过六十日，即视为送达。"},{"i":73,"n":"第七十三条","txt":"当事人应当在行政处罚决定书确定的期限内，履行处罚决定。 农业行政处罚决定依法作出后，当事人对行政处罚决定不服，申请行政复议或者提起行政诉讼的，除法律另有规定外，行政处罚决定不停止执行。"},{"i":74,"n":"第七十四条","txt":"除依照本规定第七十五条、第七十六条的规定当场收缴罚款外，农业行政处罚机关及其执法人员不得自行收缴罚款。决定罚款的农业行政处罚机关应当书面告知当事人在收到行政处罚决定书之日起十五日内，到指定的银行或者通过电子支付系统缴纳罚款。"},{"i":75,"n":"第七十五条","txt":"依照本规定第二十五条的规定当场作出农业行政处罚决定，有下列情形之一，农业行政执法人员可以当场收缴罚款： （一）依法给予一百元以下罚款的； （二）不当场收缴事后难以执行的。"},{"i":76,"n":"第七十六条","txt":"在边远、水上、交通不便地区，农业行政处罚机关及其执法人员依照本规定第二十五条、第五十四条、第五十五条的规定作出罚款决定后，当事人到指定的银行或者通过电子支付系统缴纳罚款确有困难，经当事人提出，农业行政处罚机关及其执法人员可以当场收缴罚款。"},{"i":77,"n":"第七十七条","txt":"农业行政处罚机关及其执法人员当场收缴罚款的，应当向当事人出具国务院财政部门或者省、自治区、直辖市财政部门统一制发的专用票据，不出具财政部门统一制发的专用票据的，当事人有权拒绝缴纳罚款。"},{"i":78,"n":"第七十八条","txt":"农业行政执法人员当场收缴的罚款，应当自返回农业行政处罚机关所在地之日起二日内，交至农业行政处罚机关；在水上当场收缴的罚款，应当自抵岸之日起二日内交至农业行政处罚机关；农业行政处罚机关应当自收到款项之日起二日内将罚款交至指定的银行。"},{"i":79,"n":"第七十九条","txt":"对需要继续行驶的农业机械、渔业船舶实施暂扣或者吊销证照的行政处罚，农业行政处罚机关在实施行政处罚的同时，可以发给当事人相应的证明，责令农业机械、渔业船舶驶往预定或者指定的地点。"},{"i":80,"n":"第八十条","txt":"对生效的农业行政处罚决定，当事人拒不履行的，作出农业行政处罚决定的农业行政处罚机关依法可以采取下列措施： （一）到期不缴纳罚款的，每日按罚款数额的百分之三加处罚款，加处罚款的数额不得超出罚款的数额； （二）根据法律规定，将查封、扣押的财物拍卖、依法处理或者将冻结的存款、汇款划拨抵缴罚款； （三）依照《中华人民共和国行政强制法》的规定申请人民法院强制执行。"},{"i":81,"n":"第八十一条","txt":"当事人确有经济困难，需要延期或者分期缴纳罚款的，应当在行政处罚决定书确定的缴纳期限届满前，向作出行政处罚决定的农业行政处罚机关提出延期或者分期缴纳罚款的书面申请。 农业行政处罚机关负责人批准当事人延期或者分期缴纳罚款后，应当制作同意延期（分期）缴纳罚款通知书，并送达当事人和收缴罚款的机构。农业行政处罚机关批准延期、分期缴纳罚款的，申请人民法院强制执行的期限，自暂缓或者分期缴纳罚款期限结束之日起计算。"},{"i":82,"n":"第八十二条","txt":"除依法应当予以销毁的物品外，依法没收的非法财物，必须按照国家规定公开拍卖或者按照国家有关规定处理。处理没收物品，应当制作罚没物品处理记录和清单。"},{"i":83,"n":"第八十三条","txt":"罚款、没收的违法所得或者没收非法财物拍卖的款项，必须全部上缴国库，任何行政机关或者个人不得以任何形式截留、私分或者变相私分。 罚款、没收的违法所得或者没收非法财物拍卖的款项，不得同作出农业行政处罚决定的农业行政处罚机关及其工作人员的考核、考评直接或者变相挂钩。除依法应当退还、退赔的外，财政部门不得以任何形式向作出农业行政处罚决定的农业行政处罚机关返还罚款、没收的违法所得或者没收非法财物拍卖的款项。"},{"i":84,"n":"第八十四条","txt":"有下列情形之一的，农业行政处罚机关可以结案： （一）行政处罚决定由当事人履行完毕的； （二）农业行政处罚机关依法申请人民法院强制执行行政处罚决定，人民法院依法受理的； （三）不予行政处罚等无须执行的； （四）行政处罚决定被依法撤销的； （五）农业行政处罚机关认为可以结案的其他情形。 农业行政执法人员应当填写行政处罚结案报告，经农业行政处罚机关负责人批准后结案。"},{"i":85,"n":"第八十五条","txt":"农业行政处罚机关应当按照下列要求及时将案件材料立卷归档： （一）一案一卷； （二）文书齐全，手续完备； （三）案卷应当按顺序装订。"},{"i":86,"n":"第八十六条","txt":"案件立卷归档后，任何单位和个人不得修改、增加或者抽取案卷材料，不得修改案卷内容。案卷保管及查阅，按档案管理有关规定执行。"},{"i":87,"n":"第八十七条","txt":"农业行政处罚机关应当建立行政处罚工作报告制度，并于每年1月31日前向上级农业行政处罚机关报送本行政区域上一年度农业行政处罚工作情况。"},{"i":88,"n":"第八十八条","txt":"本规定中的“以上”“以下”“内”均包括本数。"},{"i":89,"n":"第八十九条","txt":"本规定中“二日”“三日”“五日”“七日”的规定是指工作日，不含法定节假日。 期间以时、日、月、年计算。期间开始的时或者日，不计算在内。 期间届满的最后一日是节假日的，以节假日后的第一日为期间届满的日期。 行政处罚文书的送达期间不包括在路途上的时间，行政处罚文书在期满前交邮的，视为在有效期内。"},{"i":90,"n":"第九十条","txt":"农业行政处罚基本文书格式由农业农村部统一制定。各省、自治区、直辖市人民政府农业农村主管部门可以根据地方性法规、规章和工作需要，调整有关内容或者补充相应文书，报农业农村部备案。"},{"i":91,"n":"第九十一条","txt":"本规定自2022年2月1日起实施。2020年1月14日农业农村部发布的《农业行政处罚程序规定》同时废止。"}],"nongyexingzhengzhifazhengjianguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强农业行政执法证件管理，规范农业行政执法行为，保障和监督农业行政主管部门和执法人员依法行使职权，根据《农业行政处罚程序规定》及有关法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"农业行政执法证件的申领、发放、使用和管理适用本办法。"},{"i":3,"n":"第三条","txt":"农业行政执法证件为“中华人民共和国农业行政执法证”。 农业行政执法证是农业行政执法人员从事农业行政执法活动的统一有效证件。"},{"i":4,"n":"第四条","txt":"本办法所称农业行政主管部门，是指履行种植业、畜牧业、渔业、农垦、乡镇企业、饲料工业和农业机械化等行政职能的机关。 本办法所称农业管理部门，是指县级以上人民政府农业行政主管部门，法律、法规授权的农业管理机构，以及县级以上人民政府农业行政主管部门依法委托的农业管理机构（含农业行政综合执法机构）。"},{"i":5,"n":"第五条","txt":"县级以上农业管理部门的农业行政执法人员在执行公务时，应当出示或佩戴农业行政执法证。 农业行政执法人员应当在法律、法规和规章规定的职责范围内行使职权。"},{"i":6,"n":"第六条","txt":"农业行政执法证由农业部统一制定（见附件1略），并负责监制。农业行政执法证加盖农业部执法证件专用章。"},{"i":7,"n":"第七条","txt":"农业部法制工作机构负责农业行政执法证件的发放和管理工作。 部属的农业行政执法人员的执法证件，由农业部发放，具体工作由部法制工作机构组织实施。 省级以下（含省级，下同）农业管理部门农业行政执法人员的执法证件，由省级农业行政主管部门发放和管理，具体工作由其法制工作机构组织实施，并报农业部法制工作机构备案。 证件应当加盖发证机关印鉴。"},{"i":8,"n":"第八条","txt":"在岗专职从事农业行政执法工作的人员申领农业行政执法证，应当具备下列条件： （一）掌握必要的法律知识和专业知识，具有一定的工作经验； （二）经过农业行政主管部门组织的行政执法培训并考试合格； （三）公正廉洁，责任心强。"},{"i":9,"n":"第九条","txt":"凡符合规定条件的农业行政执法人员，应当填写《农业行政执法人员审批表》（见附件2略），经本级农业行政主管部门签署意见后，报发证机关申请办理农业行政执法证件。"},{"i":10,"n":"第十条","txt":"农业行政执法人员的培训和考试考核实行统一管理、分级组织的原则。部属的农业行政执法人员的培训和考试考核，由农业部法制工作机构负责组织；省级以下农业管理部门的农业行政执法人员的培训和考试考核，由省级农业行政主管部门法制工作机构负责组织。 农业部统一编制培训教学大纲和教材。省级农业行政主管部门应当根据农业部编制的教学大纲和教材，结合地方性法规和政府规章的规定组织编写培训辅导教材。"},{"i":11,"n":"第十一条","txt":"持证人应当妥善保管农业行政执法证件，不得损毁或者转借他人。"},{"i":12,"n":"第十二条","txt":"持证人丢失、毁损执法证件的，应当立即向所在单位报告，由所在单位报请发证机关注销，并公开声明作废，经发证机关审核后可补发新证。"},{"i":13,"n":"第十三条","txt":"任何单位和个人不得伪造或倒买倒卖农业行政执法证件。"},{"i":14,"n":"第十四条","txt":"农业行政执法证件实行审验制度，每两年审验一次。持证人所在单位应当于发证后的第二年的第四季度将持证人的农业行政执法证件及有关材料报发证机关，经审验合格的，由发证机关加盖验审印章。 发证机关对持证人的下列情况予以审验： （一）持证人执法工作考核情况； （二）持证人参加培训的情况； （三）持证人执法违纪或重大执法过失的情况； （四）持证人受奖励和处分的情况； （五）发证机关规定的其他情况。"},{"i":15,"n":"第十五条","txt":"持证人有下列情形之一的，由发证机关收回并注销农业行政执法证： （一）调离农业行政执法岗位的； （二）死亡的； （三）退休的； （四）辞去公职或者被开除公职的； （五）审验不合格或者到期未经审验的； （六）发证机关认为应当收回的。"},{"i":16,"n":"第十六条","txt":"有下列行为之一，情节轻微的，由发证机关或者持证人所在单位给予批评教育；情节严重的，由有关行政机关给予行政处分，并由发证机关吊销农业行政执法证；构成犯罪的，由司法机关依法追究刑事责任： （一）超越职权或者在非公务场所使用农业行政执法证的； （二）利用农业行政执法证谋取私利，违法乱纪的； （三）伪造或倒买倒卖农业行政执法证的； （四）使用伪造的农业行政执法证的； （五）冒用农业行政执法证的； （六）其他违反证件管理规定的行为。"},{"i":17,"n":"第十七条","txt":"本办法由农业部负责解释。"},{"i":18,"n":"第十八条","txt":"本办法自发布之日起施行。 附件1：农业行政执法证件的样式（略） 附件2：农业行政执法人员审批表（略）"}],"nongyexingzhengxuketingzhengchengxuguiding":[{"i":1,"n":"第一条","txt":"为了规范农业行政许可听证程序，保护公民、法人和其他组织的合法权益，根据《行政许可法》，制定本规定。"},{"i":2,"n":"第二条","txt":"农业行政机关起草法律、法规和省、自治区、直辖市人民政府规章草案以及实施行政许可，依法举行听证的，适用本规定。"},{"i":3,"n":"第三条","txt":"听证由农业行政机关法制工作机构组织。听证主持人、听证员由农业行政机关负责人指定。"},{"i":4,"n":"第四条","txt":"听证应当遵循公开、公平、公正的原则。"},{"i":5,"n":"第五条","txt":"农业行政机关起草法律、法规和省、自治区、直辖市人民政府规章草案，拟设定行政许可的，在草案提交立法机关审议前，可以采取听证的形式听取意见。"},{"i":6,"n":"第六条","txt":"农业行政机关应当在举行听证30日前公告听证事项、报名方式、报名条件、报名期限等内容。"},{"i":7,"n":"第七条","txt":"符合农业行政机关规定条件的公民、法人和其他组织，均可申请参加听证，也可推选代表参加听证。 农业行政机关应当从符合条件的报名者中确定适当比例的代表参加听证，确定的代表应当具有广泛性、代表性，并将代表名单向社会公告。 农业行政机关应当在举行听证7日前将听证通知和听证材料送达代表。"},{"i":8,"n":"第八条","txt":"听证按照下列程序进行： （一）听证主持人介绍法律、法规、政府规章草案设定行政许可的必要性以及实施行政许可的主体、程序、条件、期限和收费等情况； （二）听证代表分别对设定行政许可的必要性以及实施行政许可的主体、程序、条件、期限和收费等情况提出意见； （三）听证应当制作笔录，详细记录听证代表提出的各项意见。"},{"i":9,"n":"第九条","txt":"农业行政机关将法律、法规和省、自治区、直辖市人民政府规章草案提交立法机关审议时，应当说明举行听证和采纳意见的情况。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，农业行政机关在作出行政许可决定前，应当举行听证： （一）农业法律、法规、规章规定实施行政许可应当举行听证的； （二）农业行政机关认为其他涉及公共利益的重大行政许可需要听证的； （三）行政许可直接涉及申请人与他人之间重大利益关系，申请人、利害关系人在法定期限内申请听证的。"},{"i":11,"n":"第十一条","txt":"听证由一名听证主持人、两名听证员组织，也可视具体情况由一名听证主持人组织。 审查行政许可申请的工作人员不得作为该许可事项的听证主持人或者听证员。"},{"i":12,"n":"第十二条","txt":"听证主持人、听证员有下列情形之一的，应当自行回避，申请人、利害关系人也可以申请其回避： （一）与行政许可申请人、利害关系人或其委托代理人有近亲属关系的； （二）与该行政许可申请有其他直接利害关系，可能影响听证公正进行的。 听证主持人、听证员的回避由农业行政机关负责人决定，记录员的回避由听证主持人决定。"},{"i":13,"n":"第十三条","txt":"行政许可申请人、利害关系人可以亲自参加听证，也可以委托1-2名代理人参加听证。 由代理人参加听证的，应当向农业行政机关提交由委托人签名或者盖章的授权委托书。授权委托书应当载明委托事项及权限，并经听证主持人确认。 委托代理人代为放弃行使听证权的，应当有委托人的特别授权。"},{"i":14,"n":"第十四条","txt":"记录员应当将听证的全部内容制作笔录，由听证主持人、听证员、记录员签名。 听证笔录应当经听证代表或听证参加人确认无误后当场签名或者盖章。拒绝签名或者盖章的，听证主持人应当在听证笔录上注明。"},{"i":15,"n":"第十五条","txt":"农业行政机关应当根据听证笔录，作出行政许可决定。 法制工作机构应当在听证结束后5日内，提出对行政许可事项处理意见，报本行政机关负责人决定。"},{"i":16,"n":"第十六条","txt":"农业行政机关对本规定第十条第一款第（一）、（二）项所列行政许可事项举行听证的，应当在举行听证30日前，依照第六条的规定向社会公告有关内容，并依照第七条的规定确定听证代表，送达听证通知和材料。"},{"i":17,"n":"第十七条","txt":"符合本规定第十条第一款第（三）项规定的申请人、利害关系人，应当在被告知听证权利后5日内向农业行政机关提出听证申请。逾期未提出的，视为放弃听证。放弃听证的，应当书面记载。"},{"i":18,"n":"第十八条","txt":"听证申请包括以下内容： （一）听证申请人的姓名和住址，或者法人、其他组织的名称、地址、法定代表人或者主要负责人姓名； （二）申请听证的具体事项； （三）申请听证的依据、理由。 听证申请人还应当同时提供相关材料。"},{"i":19,"n":"第十九条","txt":"法制工作机构收到听证申请后，应当对申请材料进行审查；申请材料不齐备的，应当一次告知当事人补正。 有下列情形之一的，不予受理： （一）非行政许可申请人或利害关系人提出申请的； （二）超过5日期限提出申请的； （三）其他不符合申请听证条件的。 不予受理的，应当书面告知不予受理的理由。"},{"i":20,"n":"第二十条","txt":"法制工作机构审核后，对符合听证条件的，应当制作《行政许可听证通知书》，在举行听证7日前送达行政许可申请人、利害关系人。 《行政许可听证通知书》应当载明下列事项： （一）听证事项； （二）听证时间、地点； （三）听证主持人、听证员姓名、职务； （四）注意事项。"},{"i":21,"n":"第二十一条","txt":"听证应当在收到符合条件的听证申请之日起20日内举行。 行政许可申请人、利害关系人应当按时参加听证；无正当理由不到场的，或者未经听证主持人允许中途退场的，视为放弃听证。放弃听证的，记入听证笔录。"},{"i":22,"n":"第二十二条","txt":"承办行政许可的机构在接到《行政许可听证通知书》后，应当指派人员参加听证。"},{"i":23,"n":"第二十三条","txt":"听证按照下列程序进行： （一）听证主持人宣布听证开始，宣读听证纪律，核对听证参加人身份，宣布案由，宣布听证主持人、记录员名单； （二）告知听证参加人的权利和义务，询问申请人、利害关系人是否申请回避； （三）承办行政许可机构指派的人员提出其所了解掌握的事实，提供审查意见的证据、理由； （四）申请人、利害关系人进行申辩，提交证据材料； （五）听证主持人、听证员询问听证参加人、证人和其他有关人员； （六）听证参加人就颁发行政许可的事实和法律问题进行辩论，对有关证据材料进行质证； （七）申请人、利害关系人最后陈述； （八）听证主持人宣布听证结束。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，可以延期举行听证： （一）因不可抗力的事由致使听证无法按期举行的； （二）行政许可申请人、利害关系人临时申请回避，不能当场决定的； （三）应当延期的其他情形。 延期听证的，应当书面通知听证参加人。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，中止听证： （一）申请人、利害关系人在听证过程中提出了新的事实、理由和依据，需要调查核实的； （二）申请听证的公民死亡、法人或者其他组织终止，尚未确定权利、义务承受人的； （三）应当中止听证的其他情形。 中止听证的，应当书面通知听证参加人。"},{"i":26,"n":"第二十六条","txt":"延期、中止听证的情形消失后，由法制工作机构决定恢复听证，并书面通知听证参加人。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一的，终止听证： （一）申请听证的公民死亡，没有继承人，或者继承人放弃听证的； （二）申请听证的法人或者其他组织终止，承受其权利的法人或者其他组织放弃听证的； （三）行政许可申请人、利害关系人明确放弃听证或者被视为放弃听证的； （四）应当终止听证的其他情形。"},{"i":28,"n":"第二十八条","txt":"听证不得向当事人收取任何费用。听证经费列入本部门预算。"},{"i":29,"n":"第二十九条","txt":"法律、法规授权组织实施农业行政许可需要举行听证的，参照本规定执行。"},{"i":30,"n":"第三十条","txt":"本规定的期限以工作日计算，不含法定节假日。"},{"i":31,"n":"第三十一条","txt":"本规定自2004年7月1日起施行。"}],"nongyezhuanjiyinshengwujiagongshenpibanfa":[{"i":1,"n":"第一条","txt":"为了加强农业转基因生物加工审批管理,根据《农业转基因生物安全管理条例》的有关规定,制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称农业转基因生物加工，是指以具有活性的农业转基因生物为原料，生产农业转基因生物产品的活动。 前款所称农业转基因生物产品，是指《农业转基因生物安全管理条例》第三条第（二）、（三）项所称的转基因动植物、微生物产品和转基因农产品的直接加工品。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内从事农业转基因生物加工的单位和个人，应当取得加工所在地省级人民政府农业行政主管部门颁发的《农业转基因生物加工许可证》（以下简称《加工许可证》）。"},{"i":4,"n":"第四条","txt":"从事农业转基因生物加工的单位和个人，除应当符合有关法律、法规规定的设立条件外，还应当具备下列条件： （一）与加工农业转基因生物相适应的专用生产线和封闭式仓储设施。 （二）加工废弃物及灭活处理的设备和设施。 （三）农业转基因生物与非转基因生物原料加工转换污染处理控制措施； （四）完善的农业转基因生物加工安全管理制度。包括： 1．原料采购、运输、贮藏、加工、销售管理档案； 2．岗位责任制度； 3．农业转基因生物扩散等突发事件应急预案； 4．农业转基因生物安全管理小组，具备农业转基因生物安全知识的管理人员、技术人员。"},{"i":5,"n":"第五条","txt":"申请《加工许可证》应当向省级人民政府农业行政主管部门提出，并提供下列材料： （一）农业转基因生物加工许可证申请表（见附件）； （二）农业转基因生物加工安全管理制度文本； （三）农业转基因生物安全管理小组人员名单和专业知识、学历证明； （四）农业转基因生物安全法规和加工安全知识培训记录； （五）农业转基因生物产品标识样本；"},{"i":6,"n":"第六条","txt":"省级人民政府农业行政主管部门应当自受理申请之日起20个工作日内完成审查。审查符合条件的，发给《加工许可证》，并及时向农业部备案；不符合条件的，应当书面通知申请人并说明理由。 省级人民政府农业行政主管部门可以根据需要组织专家小组对申请材料进行评审，专家小组可以进行实地考察，并在农业行政主管部门规定的期限内提交考察报告。"},{"i":7,"n":"第七条","txt":"《加工许可证》有效期为三年。期满后需要继续从事加工的，持证单位和个人应当在期满前六个月，重新申请办理《加工许可证》。"},{"i":8,"n":"第八条","txt":"从事农业转基因生物加工的单位和个人变更名称的，应当申请换发《加工许可证》。 从事农业转基因生物加工的单位和个人有下列情形之一的，应当重新办理《加工许可证》： （一）超出原《加工许可证》规定的加工范围的； （二）改变生产地址的，包括异地生产和设立分厂。"},{"i":9,"n":"第九条","txt":"违反本办法规定的，依照《农业转基因生物安全管理条例》的有关规定处罚。"},{"i":10,"n":"第十条","txt":"《加工许可证》由农业部统一印制。"},{"i":11,"n":"第十一条","txt":"本办法自2006年7月1日起施行。"}],"nongyezhuanjiyinshengwuanquanpingjiaguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强农业转基因生物安全评价管理，保障人类健康和动植物、微生物安全，保护生态环境，根据《农业转基因生物安全管理条例》（简称《条例》），制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事农业转基因生物的研究、试验、生产、加工、经营和进口、出口活动，依照《条例》规定需要进行安全评价的，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法适用于《条例》规定的农业转基因生物，即利用基因工程技术改变基因组构成，用于农业生产或者农产品加工的植物、动物、微生物及其产品，主要包括： （一）转基因动植物（含种子、种畜禽、水产苗种）和微生物； （二）转基因动植物、微生物产品； （三）转基因农产品的直接加工品； （四）含有转基因动植物、微生物或者其产品成份的种子、种畜禽、水产苗种、农药、兽药、肥料和添加剂等产品。"},{"i":4,"n":"第四条","txt":"本办法评价的是农业转基因生物对人类、动植物、微生物和生态环境构成的危险或者潜在的风险。安全评价工作按照植物、动物、微生物三个类别，以科学为依据，以个案审查为原则，实行分级分阶段管理。"},{"i":5,"n":"第五条","txt":"根据《条例》第九条的规定设立国家农业转基因生物安全委员会，负责农业转基因生物的安全评价工作。国家农业转基因生物安全委员会由从事农业转基因生物研究、生产、加工、检验检疫、卫生、环境保护等方面的专家组成，每届任期五年。 农业农村部设立农业转基因生物安全管理办公室，负责农业转基因生物安全评价管理工作。"},{"i":6,"n":"第六条","txt":"从事农业转基因生物研究与试验的单位是农业转基因生物安全管理的第一责任人，应当成立由单位法定代表人负责的农业转基因生物安全小组，负责本单位农业转基因生物的安全管理及安全评价申报的审查工作。 从事农业转基因生物研究与试验的单位，应当制定农业转基因生物试验操作规程，加强农业转基因生物试验的可追溯管理。"},{"i":7,"n":"第七条","txt":"农业农村部根据农业转基因生物安全评价工作的需要，委托具备检测条件和能力的技术检测机构对农业转基因生物进行检测，为安全评价和管理提供依据。"},{"i":8,"n":"第八条","txt":"转基因植物种子、种畜禽、水产种苗，利用农业转基因生物生产的或者含有农业转基因生物成份的种子、种畜禽、水产种苗、农药、兽药、肥料和添加剂等，在依照有关法律、行政法规的规定进行审定、登记或者评价、审批前，应当依照本办法的规定取得农业转基因生物安全证书。"},{"i":9,"n":"第九条","txt":"农业转基因生物安全实行分级评价管理。 按照对人类、动植物、微生物和生态环境的危险程度，将农业转基因生物分为以下四个等级： 安全等级I：尚不存在危险； 安全等级Ⅱ：具有低度危险； 安全等级Ⅲ：具有中度危险； 安全等级Ⅳ：具有高度危险。"},{"i":10,"n":"第十条","txt":"农业转基因生物安全评价和安全等级的确定按以下步骤进行： （一）确定受体生物的安全等级； （二）确定基因操作对受体生物安全等级影响的类型； （三）确定转基因生物的安全等级； （四）确定生产、加工活动对转基因生物安全性的影响； （五）确定转基因产品的安全等级。"},{"i":11,"n":"第十一条","txt":"受体生物安全等级的确定 受体生物分为四个安全等级： （一）符合下列条件之一的受体生物应当确定为安全等级I： 1.对人类健康和生态环境未曾发生过不利影响； 2.演化成有害生物的可能性极小； 3.用于特殊研究的短存活期受体生物，实验结束后在自然环境中存活的可能性极小。 （二）对人类健康和生态环境可能产生低度危险，但是通过采取安全控制措施完全可以避免其危险的受体生物，应当确定为安全等级Ⅱ。 （三）对人类健康和生态环境可能产生中度危险，但是通过采取安全控制措施，基本上可以避免其危险的受体生物，应当确定为安全等级Ⅲ。 （四）对人类健康和生态环境可能产生高度危险，而且在封闭设施之外尚无适当的安全控制措施避免其发生危险的受体生物，应当确定为安全等级Ⅳ。包括： 1.可能与其它生物发生高频率遗传物质交换的有害生物； 2.尚无有效技术防止其本身或其产物逃逸、扩散的有害生物； 3.尚无有效技术保证其逃逸后，"},{"i":12,"n":"第十二条","txt":"基因操作对受体生物安全等级影响类型的确定 基因操作对受体生物安全等级的影响分为三种类型，即：增加受体生物的安全性；不影响受体生物的安全性；降低受体生物的安全性。 类型1 增加受体生物安全性的基因操作 包括：去除某个（些）已知具有危险的基因或抑制某个（些）已知具有危险的基因表达的基因操作。 类型2 不影响受体生物安全性的基因操作 包括： 1.改变受体生物的表型或基因型而对人类健康和生态环境没有影响的基因操作； 2.改变受体生物的表型或基因型而对人类健康和生态环境没有不利影响的基因操作。 类型3 降低受体生物安全性的基因操作 包括: 1.改变受体生物的表型或基因型，并可能对人类健康或生态环境产生不利影响的基因操作； 2.改变受体生物的表型或基因型，但不能确定对人类健康或生态环境影响的基因操作。"},{"i":13,"n":"第十三条","txt":"农业转基因生物安全等级的确定 根据受体生物的安全等级和基因操作对其安全等级的影响类型及影响程度，确定转基因生物的安全等级。 （一）受体生物安全等级为I的转基因生物 1.安全等级为I的受体生物，经类型1或类型2的基因操作而得到的转基因生物，其安全等级仍为I。 2.安全等级为Ⅰ的受体生物，经类型3的基因操作而得到的转基因生物，如果安全性降低很小，且不需要采取任何安全控制措施的，则其安全等级仍为I；如果安全性有一定程度的降低，但是可以通过适当的安全控制措施完全避免其潜在危险的，则其安全等级为Ⅱ；如果安全性严重降低，但是可以通过严格的安全控制措施避免其潜在危险的，则其安全等级为Ⅲ；如果安全性严重降低，而且无法通过安全控制措施完全避免其危险的，则其安全等级为IV。 （二）受体生物安全等级为Ⅱ的转基因生物 1.安全等级为Ⅱ的受体生物，经类型1的基因操作而得到的转基因生物，如果安全性增加到对人类健康"},{"i":14,"n":"第十四条","txt":"农业转基因产品安全等级的确定 根据农业转基因生物的安全等级和产品的生产、加工活动对其安全等级的影响类型和影响程度，确定转基因产品的安全等级。 （一）农业转基因产品的生产、加工活动对转基因生物安全等级的影响分为三种类型： 类型1 增加转基因生物的安全性； 类型2 不影响转基因生物的安全性； 类型3 降低转基因生物的安全性。 （二）转基因生物安全等级为I的转基因产品 1.安全等级为I的转基因生物，经类型1或类型2的生产、加工活动而形成的转基因产品，其安全等级仍为I。 2.安全等级为I的转基因生物，经类型3的生产、加工活动而形成的转基因产品，根据安全性降低的程度不同，其安全等级可为I、Ⅱ、Ⅲ或Ⅳ，分级标准与受体生物的分级标准相同。 （三）转基因生物安全等级为Ⅱ的转基因产品 1.安全等级为Ⅱ的转基因生物，经类型1的生产、加工活动而形成的转基因产品，如果安全性增加到对人类健康和生态环境不再产生不"},{"i":15,"n":"第十五条","txt":"凡在中华人民共和国境内从事农业转基因生物安全等级为Ⅲ和Ⅳ的研究以及所有安全等级的试验和进口的单位以及生产和加工的单位和个人，应当根据农业转基因生物的类别和安全等级，分阶段向农业转基因生物安全管理办公室报告或者提出申请。"},{"i":16,"n":"第十六条","txt":"农业农村部依法受理农业转基因生物安全评价申请。申请被受理的，应当交由国家农业转基因生物安全委员会进行安全评价。国家农业转基因生物安全委员会每年至少开展两次农业转基因生物安全评审。农业农村部收到安全评价结果后按照《中华人民共和国行政许可法》和《条例》的规定作出批复。"},{"i":17,"n":"第十七条","txt":"从事农业转基因生物试验和进口的单位以及从事农业转基因生物生产和加工的单位和个人，在向农业转基因生物安全管理办公室提出安全评价报告或申请前应当完成下列手续： （一）报告或申请单位和报告或申请人对所从事的转基因生物工作进行安全性评价，并填写报告书或申报书； （二）组织本单位转基因生物安全小组对申报材料进行技术审查； （三）提供有关技术资料。"},{"i":18,"n":"第十八条","txt":"在中华人民共和国从事农业转基因生物实验研究与试验的，应当具备下列条件： （一）在中华人民共和国境内有专门的机构； （二）有从事农业转基因生物实验研究与试验的专职技术人员； （三）具备与实验研究和试验相适应的仪器设备和设施条件； （四）成立农业转基因生物安全管理小组。 鼓励从事农业转基因生物试验的单位建立或共享专门的试验基地。"},{"i":19,"n":"第十九条","txt":"报告农业转基因生物实验研究和中间试验以及申请环境释放、生产性试验和安全证书的单位应当按照农业农村部制定的农业转基因植物、动物和微生物安全评价各阶段的报告或申报要求、安全评价的标准和技术规范，办理报告或申请手续 （见附录I、Ⅱ、Ⅲ、Ⅳ）。"},{"i":20,"n":"第二十条","txt":"从事安全等级为I和Ⅱ的农业转基因生物实验研究，由本单位农业转基因生物安全小组批准；从事安全等级为Ⅲ和Ⅳ的农业转基因生物实验研究，应当在研究开始前向农业转基因生物安全管理办公室报告。 研究单位向农业转基因生物安全管理办公室报告时应当提供以下材料： （一）实验研究报告书； （二）农业转基因生物的安全等级和确定安全等级的依据； （三）相应的实验室安全设施、安全管理和防范措施。"},{"i":21,"n":"第二十一条","txt":"在农业转基因生物（安全等级I、Ⅱ、Ⅲ、Ⅳ）实验研究结束后拟转入中间试验的，试验单位应当向农业转基因生物安全管理办公室报告。 试验单位向农业转基因生物安全管理办公室报告时应当提供下列材料： （一）中间试验报告书； （二）实验研究总结报告； （三）农业转基因生物的安全等级和确定安全等级的依据； （四）相应的安全研究内容、安全管理和防范措施。"},{"i":22,"n":"第二十二条","txt":"在农业转基因生物中间试验结束后拟转入环境释放的，或者在环境释放结束后拟转入生产性试验的，试验单位应当向农业转基因生物安全管理办公室提出申请，经国家农业转基因生物安全委员会安全评价合格并由农业农村部批准后，方可根据农业转基因生物安全审批书的要求进行相应的试验。 试验单位提出前款申请时，应当按照相关安全评价指南的要求提供下列材料： （一）安全评价申报书； （二）农业转基因生物的安全等级和确定安全等级的依据； （三）有检测条件和能力的技术检测机构出具的检测报告； （四）相应的安全研究内容、安全管理和防范措施； （五）上一试验阶段的试验总结报告； 申请生产性试验的，还应当按要求提交农业转基因生物样品、对照样品及检测方法。"},{"i":23,"n":"第二十三条","txt":"在农业转基因生物安全审批书有效期内，试验单位需要改变试验地点的，应当向农业转基因生物安全管理办公室报告。"},{"i":24,"n":"第二十四条","txt":"在农业转基因生物试验结束后拟申请安全证书的，试验单位应当向农业转基因生物安全管理办公室提出申请。 试验单位提出前款申请时，应当按照相关安全评价指南的要求提供下列材料： （一）安全评价申报书； （二）农业转基因生物的安全等级和确定安全等级的依据； （三）中间试验、环境释放和生产性试验阶段的试验总结报告； （四）按要求提交农业转基因生物样品、对照样品及检测所需的试验材料、检测方法，但按照本办法第二十二条规定已经提交的除外； （五）其他有关材料。 农业农村部收到申请后，应当组织农业转基因生物安全委员会进行安全评价，并委托具备检测条件和能力的技术检测机构进行检测；安全评价合格的，经农业农村部批准后，方可颁发农业转基因生物安全证书。"},{"i":25,"n":"第二十五条","txt":"农业转基因生物安全证书应当明确转基因生物名称（编号）、规模、范围、时限及有关责任人、安全控制措施等内容。 从事农业转基因生物生产和加工的单位和个人以及进口的单位，应当按照农业转基因生物安全证书的要求开展工作并履行安全证书规定的相关义务。"},{"i":26,"n":"第二十六条","txt":"从中华人民共和国境外引进农业转基因生物，或者向中华人民共和国出口农业转基因生物的，应当按照《农业转基因生物进口安全管理办法》的规定提供相应的安全评价材料，并在申请安全证书时按要求提交农业转基因生物样品、对照样品及检测方法。"},{"i":27,"n":"第二十七条","txt":"农业转基因生物安全评价受理审批机构的工作人员和参与审查的专家，应当为申报者保守技术秘密和商业秘密，与本人及其近亲属有利害关系的应当回避。"},{"i":28,"n":"第二十八条","txt":"农业农村部根据农业转基因生物安全评价及其管理工作的需要，委托具备检测条件和能力的技术检测机构进行检测。"},{"i":29,"n":"第二十九条","txt":"技术检测机构应当具备下列基本条件： （一）具有公正性和权威性，设有相对独立的机构和专职人员； （二）具备与检测任务相适应的、符合国家标准（或行业标准）的仪器设备和检测手段； （三）严格执行检测技术规范，出具的检测数据准确可靠； （四）有相应的安全控制措施。"},{"i":30,"n":"第三十条","txt":"技术检测机构的职责任务： （一）为农业转基因生物安全管理和评价提供技术服务； （二）承担农业农村部或申请人委托的农业转基因生物定性定量检验、鉴定和复查任务； （三）出具检测报告，做出科学判断； （四）研究检测技术与方法，承担或参与评价标准和技术法规的制修订工作； （五）检测结束后，对用于检测的样品应当安全销毁，不得保留; （六）为委托人和申请人保守技术秘密和商业秘密。"},{"i":31,"n":"第三十一条","txt":"农业农村部负责农业转基因生物安全的监督管理，指导不同生态类型区域的农业转基因生物安全监控和监测工作，建立全国农业转基因生物安全监管和监测体系。"},{"i":32,"n":"第三十二条","txt":"县级以上地方各级人民政府农业农村主管部门按照《条例》第三十八条和第三十九条的规定负责本行政区域内的农业转基因生物安全的监督管理工作。"},{"i":33,"n":"第三十三条","txt":"有关单位和个人应当按照《条例》第四十条的规定，配合农业农村主管部门做好监督检查工作。"},{"i":34,"n":"第三十四条","txt":"从事农业转基因生物试验、生产的单位，应当接受农业农村主管部门的监督检查，并在每年3月31日前,向试验、生产所在地省级和县级人民政府农业农村主管部门提交上一年度试验、生产总结报告。"},{"i":35,"n":"第三十五条","txt":"从事农业转基因生物试验和生产的单位 ，应当根据本办法的规定确定安全控制措施和预防事故的紧急措施，做好安全监督记录，以备核查。 安全控制措施包括物理控制、化学控制、生物控制、环境控制和规模控制等（见附录Ⅳ）。"},{"i":36,"n":"第三十六条","txt":"安全等级Ⅱ、Ⅲ、Ⅳ的转基因生物，在废弃物处理和排放之前应当采取可靠措施将其销毁、灭活，以防止扩散和污染环境。发现转基因生物扩散、残留或者造成危害的，必须立即采取有效措施加以控制、消除，并向当地农业农村主管部门报告。"},{"i":37,"n":"第三十七条","txt":"农业转基因生物在贮存、转移、运输和销毁、灭活时，应当采取相应的安全管理和防范措施，具备特定的设备或场所，指定专人管理并记录。"},{"i":38,"n":"第三十八条","txt":"发现农业转基因生物对人类、动植物和生态环境存在危险时，农业农村部有权宣布禁止生产、加工、经营和进口，收回农业转基因生物安全证书，由货主销毁有关存在危险的农业转基因生物。"},{"i":39,"n":"第三十九条","txt":"违反本办法规定，从事安全等级Ⅲ、Ⅳ的农业转基因生物实验研究或者从事农业转基因生物中间试验，未向农业农村部报告的，按照《条例》第四十二条的规定处理。"},{"i":40,"n":"第四十条","txt":"违反本办法规定，未经批准擅自从事环境释放、生产性试验的，或已获批准但未按照规定采取安全管理防范措施的，或者超过批准范围和期限进行试验的，按照《条例》第四十三条的规定处罚。"},{"i":41,"n":"第四十一条","txt":"违反本办法规定，在生产性试验结束后，未取得农业转基因生物安全证书，擅自将农业转基因生物投入生产和应用的，按照《条例》第四十四条的规定处罚。"},{"i":42,"n":"第四十二条","txt":"假冒、伪造、转让或者买卖农业转基因生物安全证书、审批书以及其他批准文件的，按照《条例》第五十一条的规定处罚。"},{"i":43,"n":"第四十三条","txt":"违反本办法规定核发农业转基因生物安全审批书、安全证书以及其他批准文件的，或者核发后不履行监督管理职责的，按照《条例》第五十三条的规定处罚。"},{"i":44,"n":"第四十四条","txt":"本办法所用术语及含义如下： 一、基因，系控制生物性状的遗传物质的功能和结构单位，主要指具有遗传信息的DNA片段。 二、基因工程技术，包括利用载体系统的重组DNA技术以及利用物理、化学和生物学等方法把重组DNA分子导入有机体的技术。 三、基因组，系指特定生物的染色体和染色体外所有遗传物质的总和。 四、DNA，系脱氧核糖核酸的英文名词缩写，是贮存生物遗传信息的遗传物质。 五、农业转基因生物，系指利用基因工程技术改变基因组构成，用于农业生产或者农产品加工的动植物、微生物及其产品。 六、目的基因，系指以修饰受体细胞遗传组成并表达其遗传效应为目的的基因。 七、受体生物，系指被导入重组DNA分子的生物。 八、种子，系指农作物和林木的种植材料或者繁殖材料，包括籽粒、果实和根、茎、苗、芽、叶等。 九、实验研究，系指在实验室控制系统内进行的基因操作和转基因生物研究工作。 十、中间试验，系指在控制系统内或"},{"i":45,"n":"第四十五条","txt":"本办法由农业农村部负责解释。"},{"i":46,"n":"第四十六条","txt":"本办法自2002年3月20日起施行。1996年7月10日农业部发布的第7号令《农业生物基因工程安全管理实施办法》同时废止。 附录I 转基因植物安全评价 一、转基因植物安全性评价 1　受体植物的安全性评价 1. 1　受体植物的背景资料： 1.1.1　学名、俗名和其他名称； 1.1.2　分类学地位； 1.1.3　试验用受体植物品种（或品系）名称； 1.1.4　是野生种还是栽培种； 1.1.5　原产地及引进时间； 1.1.6　用途； 1.1.7　在国内的应用情况； 1.1.8　对人类健康和生态环境是否发生过不利影响； 1.1.9　从历史上看，受体植物演变成有害植物（如杂草等）的可能性； 1.1.10　是否有长期安全应用的记录。 1.2　受体植物的生物学特性： 1.2.1　是一年生还是多年生； 1.2.2　对人及其他生物是否有毒，如有毒，应说明毒性存在的部位及其毒性的性质； 1.2.3　是否有"}],"nongyezhuanjiyinshengwubiaoshiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对农业转基因生物的标识管理，规范农业转基因生物的销售行为，引导农业转基因生物的生产和消费，保护消费者的知情权，根据《农业转基因生物安全管理条例》（简称《条例》）的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家对农业转基因生物实行标识制度。实施标识管理的农业转基因生物目录，由国务院农业行政主管部门商国务院有关部门制定、调整和公布。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内销售列入农业转基因生物标识目录的农业转基因生物，必须遵守本办法。 凡是列入标识管理目录并用于销售的农业转基因生物，应当进行标识；未标识和不按规定标识的，不得进口或销售。"},{"i":4,"n":"第四条","txt":"农业部负责全国农业转基因生物标识的监督管理工作。 县级以上地方人民政府农业行政主管部门负责本行政区域内的农业转基因生物标识的监督管理工作。 国家质检总局负责进口农业转基因生物在口岸的标识检查验证工作。"},{"i":5,"n":"第五条","txt":"列入农业转基因生物标识目录的农业转基因生物，由生产、分装单位和个人负责标识；经营单位和个人拆开原包装进行销售的，应当重新标识。"},{"i":6,"n":"第六条","txt":"标识的标注方法： （一）转基因动植物（含种子、种畜禽、水产苗种）和微生物，转基因动植物、微生物产品，含有转基因动植物、微生物或者其产品成份的种子、种畜禽、水产苗种、农药、兽药、肥料和添加剂等产品，直接标注“转基因××”。 （二）转基因农产品的直接加工品，标注为“转基因××加工品（制成品）”或者“加工原料为转基因××”。 （三）用农业转基因生物或用含有农业转基因生物成份的产品加工制成的产品，但最终销售产品中已不再含有或检测不出转基因成份的产品，标注为“本产品为转基因××加工制成，但本产品中已不再含有转基因成份”或者标注为“本产品加工原料中有转基因××，但本产品中已不再含有转基因成份”。"},{"i":7,"n":"第七条","txt":"农业转基因生物标识应当醒目，并和产品的包装、标签同时设计和印制。 难以在原有包装、标签上标注农业转基因生物标识的，可采用在原有包装、标签的基础上附加转基因生物标识的办法进行标注，但附加标识应当牢固、持久。"},{"i":8,"n":"第八条","txt":"难以用包装物或标签对农业转基因生物进行标识时，可采用下列方式标注： （一）难以在每个销售产品上标识的快餐业和零售业中的农业转基因生物，可以在产品展销（示）柜（台）上进行标识，也可以在价签上进行标识或者设立标识板（牌）进行标识。 （二）销售无包装和标签的农业转基因生物时，可以采取设立标识板（牌）的方式进行标识。 （三）装在运输容器内的农业转基因生物不经包装直接销售时，销售现场可以在容器上进行标识，也可以设立标识板（牌）进行标识。 （四）销售无包装和标签的农业转基因生物，难以用标识板（牌）进行标注时，销售者应当以适当的方式声明。 （五）进口无包装和标签的农业转基因生物，难以用标识板（牌）进行标注时，应当在报检（关）单上注明。"},{"i":9,"n":"第九条","txt":"有特殊销售范围要求的农业转基因生物，还应当明确标注销售的范围，可标注为“仅限于××销售（生产、加工、使用）”。"},{"i":10,"n":"第十条","txt":"农业转基因生物标识应当使用规范的中文汉字进行标注。"},{"i":11,"n":"第十一条","txt":"销售农业转基因生物的经营单位和个人在进货时，应当对货物和标识进行核对。"},{"i":12,"n":"第十二条","txt":"违反本办法规定的，按《条例》第五十条规定予以处罚。"},{"i":13,"n":"第十三条","txt":"本办法由农业部负责解释。"},{"i":14,"n":"第十四条","txt":"本办法自2002年3月20日起施行。 附件 第一批实施标识管理的农业转基因生物目录 1、大豆种子、大豆、大豆粉、大豆油、豆粕 2、玉米种子、玉米、玉米油、玉米粉（含税号为11022000、11031300、11042300的玉米粉） 3、油菜种子、油菜籽、油菜籽油、油菜籽粕 4、棉花种子 5、番茄种子、鲜番茄、番茄酱"}],"nongyezhuanjiyinshengwujinkouanquanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对农业转基因生物进口的安全管理，根据《农业转基因生物安全管理条例》（简称《条例》）的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内从事农业转基因生物进口活动的安全管理。"},{"i":3,"n":"第三条","txt":"农业部负责农业转基因生物进口的安全管理工作。国家农业转基因生物安全委员会负责农业转基因生物进口的安全评价工作。"},{"i":4,"n":"第四条","txt":"对于进口的农业转基因生物，按照用于研究和试验的、用于生产的以及用作加工原料的三种用途实行管理。"},{"i":5,"n":"第五条","txt":"从中华人民共和国境外引进安全等级I、II的农业转基因生物进行实验研究的，引进单位应当向农业转基因生物安全管理办公室提出申请，并提供下列材料： （一）农业部规定的申请资格文件； （二）进口安全管理登记表（见附件）； （三）引进农业转基因生物在国（境）外已经进行了相应的研究的证明文件； （四）引进单位在引进过程中拟采取的安全防范措施。 经审查合格后，由农业部颁发农业转基因生物进口批准文件。引进单位应当凭此批准文件依法向有关部门办理相关手续。"},{"i":6,"n":"第六条","txt":"从中华人民共和国境外引进安全等级III、IV的农业转基因生物进行实验研究的和所有安全等级的农业转基因生物进行中间试验的，引进单位应当向农业部提出申请，并提供下列材料： （一）农业部规定的申请资格文件； （二）进口安全管理登记表（见附件）； （三）引进农业转基因生物在国（境）外已经进行了相应研究或试验的证明文件； （四）引进单位在引进过程中拟采取的安全防范措施； （五）《农业转基因生物安全评价管理办法》规定的相应阶段所需的材料。 经审查合格后，由农业部颁发农业转基因生物进口批准文件。引进单位应当凭此批准文件依法向有关部门办理相关手续。"},{"i":7,"n":"第七条","txt":"从中华人民共和国境外引进农业转基因生物进行环境释放和生产性试验的，引进单位应当向农业部提出申请，并提供下列材料： （一）农业部规定的申请资格文件； （二）进口安全管理登记表（见附件）； （三）引进农业转基因生物在国（境）外已经进行了相应的研究的证明文件； （四）引进单位在引进过程中拟采取的安全防范措施； （五）《农业转基因生物安全评价管理办法》规定的相应阶段所需的材料。 经审查合格后，由农业部颁发农业转基因生物安全审批书。引进单位应当凭此审批书依法向有关部门办理相关手续。"},{"i":8,"n":"第八条","txt":"从中华人民共和国境外引进农业转基因生物用于试验的，引进单位应当从中间试验阶段开始逐阶段向农业部申请。"},{"i":9,"n":"第九条","txt":"境外公司向中华人民共和国出口转基因植物种子、种畜禽、水产苗种和利用农业转基因生物生产的或者含有农业转基因生物成份的植物种子、种畜禽、水产苗种、农药、兽药、肥料和添加剂等拟用于生产应用的，应当向农业部提出申请，并提供下列材料： （一）进口安全管理登记表（见附件）； （二）输出国家或者地区已经允许作为相应用途并投放市场的证明文件； （三）输出国家或者地区经过科学试验证明对人类、动植物、微生物和生态环境无害的资料； （四）境外公司在向中华人民共和国出口过程中拟采取的安全防范措施。 （五）《农业转基因生物安全评价管理办法》规定的相应阶段所需的材料。"},{"i":10,"n":"第十条","txt":"境外公司在提出上述申请时，应当在中间试验开始前申请，经审批同意，试验材料方可入境，并依次经过中间试验、环境释放、生产性试验三个试验阶段以及农业转基因生物安全证书申领阶段。 中间试验阶段的申请，经审查合格后，由农业部颁发农业转基因生物进口批准文件，境外公司凭此批准文件依法向有关部门办理相关手续。环境释放和生产性试验阶段的申请，经安全评价合格后，由农业部颁发农业转基因生物安全审批书，境外公司凭此审批书依法向有关部门办理相关手续。安全证书的申请，经安全评价合格后，由农业部颁发农业转基因生物安全证书，境外公司凭此证书依法向有关部门办理相关手续。"},{"i":11,"n":"第十一条","txt":"引进的农业转基因生物在生产应用前，应取得农业转基因生物安全证书，方可依照有关种子、种畜禽、水产苗种、农药、兽药、肥料和添加剂等法律、行政法规的规定办理相应的审定、登记或者评价、审批手续。"},{"i":12,"n":"第十二条","txt":"境外公司向中华人民共和国出口农业转基因生物用作加工原料的，应当向农业部申请领取农业转基因生物安全证书。"},{"i":13,"n":"第十三条","txt":"境外公司提出上述申请时，应当按照相关安全评价指南的要求提供下列材料： （一）进口安全管理登记表（见附件）； （二）安全评价申报书（见《农业转基因生物安全评价管理办法》附录V）； （三）输出国家或者地区已经允许作为相应用途并投放市场的证明文件； （四）输出国家或者地区经过科学试验证明对人类、动植物、微生物和生态环境无害的资料； （五）按要求提交农业转基因生物样品、对照样品及检测所需的试验材料、检测方法； （六）境外公司在向中华人民共和国出口过程中拟采取的安全防范措施。 农业部收到申请后，应当组织农业转基因生物安全委员会进行安全评价，并委托具备检测条件和能力的技术检测机构进行检测；安全评价合格的，经农业部批准后，方可颁发农业转基因生物安全证书。"},{"i":14,"n":"第十四条","txt":"在申请获得批准后，再次向中华人民共和国提出申请时，符合同一公司、同一农业转基因生物条件的，可简化安全评价申请手续，并提供以下材料： （一）进口安全管理登记表（见附件）； （二）农业部首次颁发的农业转基因生物安全证书复印件； （三）境外公司在向中华人民共和国出口过程中拟采取的安全防范措施。 经审查合格后，由农业部颁发农业转基因生物安全证书。"},{"i":15,"n":"第十五条","txt":"境外公司应当凭农业部颁发的农业转基因生物安全证书，依法向有关部门办理相关手续。"},{"i":16,"n":"第十六条","txt":"进口用作加工原料的农业转基因生物如果具有生命活力，应当建立进口档案，载明其来源、贮存、运输等内容，并采取与农业转基因生物相适应的安全控制措施，确保农业转基因生物不进入环境。"},{"i":17,"n":"第十七条","txt":"向中国出口农业转基因生物直接用作消费品的，依照向中国出口农业转基因生物用作加工原料的审批程序办理。"},{"i":18,"n":"第十八条","txt":"农业部应当自收到申请人申请之日起270日内做批准或者不批准的决定，并通知申请人。"},{"i":19,"n":"第十九条","txt":"进口农业转基因生物用于生产或用作加工原料的，应当在取得农业部颁发的农业转基因生物安全证书后，方能签订合同。"},{"i":20,"n":"第二十条","txt":"进口农业转基因生物，没有国务院农业行政主管部门颁发的农业转基因生物安全证书和相关批准文件的，或者与证书、批准文件不符的，作退货或者销毁处理。"},{"i":21,"n":"第二十一条","txt":"本办法由农业部负责解释。"},{"i":22,"n":"第二十二条","txt":"本办法自2002年3月20日起施行。"}],"nongyebuguanyuyuyechuanboyouleijilubaoshiyongfangf838437":[],"nongyebuguanyuyuyechuanboyouleijilubushiyongfangfadd4878":[],"nongyebuguanyuxiafahaiyangyuyechuanbochuanyuanzhenceffc0":[],"nongyebuguanyufabudongwujidongwuyuanshipinzhongcan0165f0":[],"nongyebuguanyuquedingjingjijiazhijiaogaodeyuyeziyu9322e1":[],"nongyebuzhiwuxinpinzhongfushenweiyuanhuishenliguid53ccb5":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国植物新品种保护条例》（以下简称《条例》）、《中华人民共和国植物新品种保护条例实施细则（农业部分）》（以下简称《实施细则》），制定本规定。"},{"i":2,"n":"第二条","txt":"农业部植物新品种复审委员会（以下简称复审委员会）负责审理驳回品种权申请的复审案件、品种权无效宣告案件和新品种更名案件。"},{"i":3,"n":"第三条","txt":"复审委员会依法独立行使审理权，并作出审理决定。"},{"i":4,"n":"第四条","txt":"复审委员会设主任委员1名，副主任委员4名，秘书长1名，委员30名。 主任委员由农业部主管领导兼任，副主任委员由科教司司长和种植业管理司、产业政策与法规司、科技教育司主管副司长兼任，秘书长由农业部科教司知识产权与成果管理处负责人兼任。"},{"i":5,"n":"第五条","txt":"复审委员会委员（简称复审委员）由农业部聘请有经验的技术、法律和行政管理人员组成。复审委员每届任期3年，可连聘连任，但最多不得超过3届。 复审委员会下设大田作物、果树、观赏植物及草类、蔬菜作物等四个复审小组，每个复审小组由若干名复审委员组成，负责复审案件的具体审理工作。 根据案件审理的需要，复审委员会可以邀请其他专家对案件涉及的内容提供咨询意见，或者委托有关单位进行技术性鉴定。"},{"i":6,"n":"第六条","txt":"复审委员会的主要职责是： （一）负责审理农业部植物新品种保护办公室（以下简称新品种保护办公室）在初步审查和实质审查程序中驳回品种权申请的复审请求； （二）负责审理无效宣告和品种更名请求； （三）依据职权宣告品种权无效，以及对授权品种予以更名。"},{"i":7,"n":"第七条","txt":"复审委员会主任委员行使下列职权： （一）任命复审小组组长； （二）主持复审委员会全体会议； （三）决定复审委员的回避； （四）签发审理决定。 主任委员可以委托副主任委员代行部分职权。"},{"i":8,"n":"第八条","txt":"复审小组组长负责主持复审案件和无效案件审理会议以及组织起草审理决定草案。"},{"i":9,"n":"第九条","txt":"复审委员会秘书处设在农业部科教司知识产权与成果管理处，负责处理复审委员会的日常工作。"},{"i":10,"n":"第十条","txt":"中国的单位和个人请求复审或者无效宣告的，可以直接或者委托新品种保护办公室认可的具有品种权代理资格的机构向复审委员会提出符合规定格式要求的复审请求书或者无效宣告请求书。 在中国没有经常居所的外国人、外国企业或者外国其他组织，应当委托新品种保护办公室认可的具有品种权代理资格的机构办理。"},{"i":11,"n":"第十一条","txt":"当事人委托代理机构办理的，应当提交代理人委托书一份。代理人委托书应当载明代理内容、委托权限。"},{"i":12,"n":"第十二条","txt":"依据《实施细则》第四十四条的规定，复审委员会委托新品种保护办公室受理处代收复审请求书和无效宣告请求书及有关文件。"},{"i":13,"n":"第十三条","txt":"复审委员会应当坚持以事实为依据，以法律为准绳，依法公正、客观地审理案件。"},{"i":14,"n":"第十四条","txt":"当事人在复审中的法律地位一律平等。"},{"i":15,"n":"第十五条","txt":"复审和无效宣告审理工作应当自觉接受社会监督。复审委员认为自己与本案件有利害关系的，应当申请回避。 当事人认为复审委员与本案件有利害关系或者其他关系可能影响公正审理的，在审理决定作出前，有权要求相关人员回避。相关人员是否回避由主任委员决定。"},{"i":16,"n":"第十六条","txt":"复审委员会主要依据书面材料进行审理。但对于重大或者有重要疑难法律、技术问题或者较为复杂的案件，复审委员会可以召集双方当事人举行听证会。 当事人对自己提出的主张有举证责任，但复审委员会不受当事人所提供的证据限制，可以依据职权进行调查或者要求当事人补充证据。"},{"i":17,"n":"第十七条","txt":"复审委员会举行听证会，应当在听证会前45天将会议日期通知当事人。当事人应当在收到通知后的5天内将参加听证会的人员名单回执交复审委员会秘书处。当事人有正当理由的，可以在听证会召开前25天请求延期，是否延期，由复审委员会决定。当事人无正当理由不提交听证会人员回执、不到会或者未经许可中途退会的，视为放弃申辩的权利。"},{"i":18,"n":"第十八条","txt":"复审委员会决定举行听证会后，当事人可以在提交《听证会人员回执》前补充证据材料。逾期补充的证据材料，复审委员会不予考虑。"},{"i":19,"n":"第十九条","txt":"复审委员会举行听证会时应当制作笔录。当事人或者其他参加人认为对自己陈述的记录有遗漏或者差错的，有权申请更正。笔录由到会的复审委员、当事人和其他有关人员签名或者盖章。"},{"i":20,"n":"第二十条","txt":"复审委员会和复审小组依照少数服从多数的原则，通过投票表决作出审理决定。 当表决结果出现赞成票与反对票票数相同的情况时，负责主持会议的主任委员或者副主任委员或者复审小组组长所投的一票有决定作用。"},{"i":21,"n":"第二十一条","txt":"申请人对驳回品种权申请的决定不服的，可以自收到通知之日起3个月内向复审委员会提交复审请求书，请求复审。"},{"i":22,"n":"第二十二条","txt":"秘书处对收到的复审请求书进行以下形式审查： （一）复审请求应当属于新品种保护办公室在初步审查或者实质审查中驳回的品种权申请； （二）复审请求不应当属于复审委员会已经审理并作出审理决定，请求人又以同一事实和理由提出复审请求的； （三）复审请求人应当是被驳回品种权申请的全体申请人； （四）复审请求的期限应当符合《条例》第三十二条的规定； （五）复审请求书应当符合规定的格式要求以及符合《实施细则》第四十五条第一款规定的份数； （六）复审请求中修改的被驳回的品种权申请文件应当符合《实施细则》第四十五条第二款的规定； （七）复审请求人委托代理机构办理的，应当提交代理人委托书并写明委托权限等。"},{"i":23,"n":"第二十三条","txt":"经形式审查认为复审请求不符合本规定第二十二条规定的，秘书处应当通知复审请求人在指定的期限内补正，逾期不补正的，该复审请求视为撤回。"},{"i":24,"n":"第二十四条","txt":"对形式审查合格的复审请求，可以直接交由复审小组审理，也可以交由新品种保护办公室进行“前置审查”。 进行前置审查的，新品种保护办公室应当自收到案卷之日起30日内（特殊情况除外）提出审查意见。前置审查意见分以下三种： （一）复审请求证据充分，理由成立，同意撤销原驳回申请的决定； （二）复审请求人提交的申请文件修改文本克服了原申请中存在的缺陷，同意在修改文本的基础上撤销原驳回申请的决定； （三）复审请求人陈述的意见和提交的申请文件修改文本不足以使原驳回申请的决定被撤回，坚持原驳回申请的决定。"},{"i":25,"n":"第二十五条","txt":"新品种保护办公室在前置审查过程中，对于原始申请文件未做修改的复审请求不得提出新的驳回理由。"},{"i":26,"n":"第二十六条","txt":"若新品种保护办公室作出的前置审查意见属于本规定第二十四条第（一）或者第（二）项两种情形之一的，复审委员会不再进行审理,可以据此作出审理决定。 若新品种保护办公室作出的前置审查意见属于本规定第二十四条第（三）项情形的，由复审小组继续进行审理。"},{"i":27,"n":"第二十七条","txt":"复审委员会应当自收到复审请求书之日起6个月内完成复审，并作出审理决定。审理决定分为以下三种： （一）复审请求的理由不成立，维持原驳回申请的决定，驳回复审请求； （二）复审请求的理由成立，撤消原驳回申请的决定； （三）品种权申请文件经复审请求人修改，克服了原驳回申请 的决定所指出的缺陷，在新的文本基础上撤消原驳回决定。"},{"i":28,"n":"第二十八条","txt":"复审请求人在复审委员会作出审理决定前可以撤回复审请求，复审程序终止。审理决定已宣布或者书面决定已经发出之后撤回的，不影响审理决定的有效性。"},{"i":29,"n":"第二十九条","txt":"复审委员会作出的审理决定，对于改变新品种保护办公室作出的审查决定的，应当及时通知新品种保护办公室执行复审委员会的审理决定，新品种保护办公室不得以同一事实和理由再次作出与原驳回决定相同的决定，并且继续进行审批程序。"},{"i":30,"n":"第三十条","txt":"品种权授予后，任何单位和个人均可对农业部授予的品种权提出无效宣告请求，复审委员会也可依职权直接启动无效宣告程序。"},{"i":31,"n":"第三十一条","txt":"秘书处对收到的无效宣告请求书或者品种更名请求书进行以下形式审查： （一）应当属于无效宣告或者品种更名的复审请求； （二）请求人不应当以同一事实和理由对复审委员会已经审理并决定仍维持品种权或者品种名称的又提出无效宣告或者品种更名请求书； （三）该品种权申请已经授权； （四）请求人所提交的无效宣告或者品种更名请求书中应当说明所依据的事实和理由； （五）请求人所提交的无效宣告或者品种更名请求书中所提出的理由应当符合《条例》第三十七条及《实施细则》第五十一条的规定； （六）无效宣告或者品种更名请求人委托代理机构办理的,应当提交代理人委托书并写明委托内容和权限等。"},{"i":32,"n":"第三十二条","txt":"对形式审查符合本规定第三十一条规定的无效宣告或者品种更名请求，秘书处发给“无效宣告受理通知书“或者“品种更名受理通知书”，通知请求人。对不合格的，发给“无效宣告或者品种更名不受理通知书”，并说明不受理的理由。"},{"i":33,"n":"第三十三条","txt":"对经形式审查合格的无效宣告或者品种更名请求书，秘书处应当将副本和有关文件副本送交品种权人，品种权人应当在收到文件之日起3个月内陈述意见，期满不答复的，不影响复审委员会的审理。 秘书处在收到品种权人的意见陈述书后，应当将其副本转送给请求人。信件往来次数由秘书处根据案件实际情况决定。"},{"i":34,"n":"第三十四条","txt":"复审委员会应当对无效宣告或者品种更名请求及时进行审理，并作出审理决定。无效宣告或者品种更名的审理决定有以下两种类型： （一）无效宣告或者品种更名请求理由成立，宣告品种权无效或者品种名称更名； （二）无效宣告或者品种更名请求理由不成立，驳回无效宣告或者品种更名请求，维持品种权有效或者品种的现有名称。"},{"i":35,"n":"第三十五条","txt":"在无效宣告或者品种更名审理程序中，品种权人以书面形式放弃其品种权的，无效宣告或者品种更名审理程序不受影响。"},{"i":36,"n":"第三十六条","txt":"在复审委员会对无效宣告或者品种更名请求作出决定之前，请求人可以撤回其请求。请求人撤回无效宣告或者品种更名请求的，复审程序是否终止，由复审委员会决定。"},{"i":37,"n":"第三十七条","txt":"复审委员会对审理完毕的案件均需作出书面审理决定。"},{"i":38,"n":"第三十八条","txt":"复审小组组长负责组织起草审理决定草案。审理决定草案应当写明复审请求争议的内容、审理决定及其理由，经复审小组集体讨论通过并由组长签字后报主任委员签发。"},{"i":39,"n":"第三十九条","txt":"审理决定除通知当事人外，还应当予以公告，并在登记簿上登记。 请求人在规定的期限内向人民法院起诉的，应当在人民法院作出的判决生效后再予以公告和登记。"},{"i":40,"n":"第四十条","txt":"复审委员会作出的品种更名决定生效后，新品种保护办公室应当及时通知品种权人更换品种权证书。品种权人以及其他任何人不得再使用原品种名称。"},{"i":41,"n":"第四十一条","txt":"对复审程序中各种文件的递交、送达和期限的规定按《实施细则》第七章执行。"},{"i":42,"n":"第四十二条","txt":"本规定由农业部负责解释。"},{"i":43,"n":"第四十三条","txt":"本规定自发布之日起施行。"}],"nongyebuzhiwujianyiyuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强植物检疫员的管理，提高植物检疫员的思想、业务素质，以正确执行检疫法规，根据《植物检疫条例》及《植物检疫条例实施细则》（农业部分），制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称植物检疫员为专职植物检疫员，其任免程序如下： （一）植物检疫员由地、县农业行政部门推荐，省（区、市）植物检疫机构负责考核，农业厅（局）审批，报农业部全国植保总站备案（统一格式见附件）和发证。 （二）植物检疫员增补审批工作，每两年办理一次，备案工作在当年11～12月份进行。 （三）凡需调离的植物检疫员，由当地农业行政部门征求上一级植物检疫机构意见，报省（区、市）农业厅（局）审批同意后，办理调离手续，注销检疫员证。 （四）对不称职的植物检疫员，应按本款第（三）项规定的程序，取消其检疫员资格，并注销检疫员证。 植物检疫员证件丢失须登报申明作废，办理补证手续。"},{"i":3,"n":"第三条","txt":"县级以上（含县级）各级植物检疫员依法执行植物检疫任务，必须保持稳定，以保证《植物检疫条例》及《植物检疫条例实施细则》（农业部分）的贯彻执行和植物检疫工作的开展。"},{"i":4,"n":"第四条","txt":"植物检疫员必须具备下列条件： （一）具有助理农艺师以上技术职称，或具有中等专业学历，从事植保工作三年以上； （二）热爱植物检疫事业，熟悉检疫业务，遵纪守法，坚持原则，忠于职守，有一定的思想觉悟和政策水平； （三）专职从事植物检疫工作； （四）身体健康，能坚持正常工作。"},{"i":5,"n":"第五条","txt":"植物检疫员的职权： （一）有权签发植物检疫证书及其他植物检疫单证； （二）有权进入车站、机场、邮局、港口、仓库、苗圃、良繁场地、集市贸易等场所执行检疫任务； （三）依法查处违法单位或个人及违章调运的植物和植物产品； （四）对兼职植物检疫员给予业务指导。"},{"i":6,"n":"第六条","txt":"植物检疫员必须做到： （一）坚持四项基本原则，认真执行政策，严格按照《植物检疫条例》和实施细则的规定办事； （二）热爱本职工作，坚守岗位，熟悉检疫法规和检疫业务，正确行使职权，认真完成检疫任务； （三）执行检疫任务必须持植物检疫员证，穿着检疫制服，佩戴检疫标志，仪容整洁、端庄； （四）秉公执法，廉洁奉公，不徇私舞弊； （五）敢于和善于同违反检疫法规的行为作斗争。 （六）定期参加植物检疫培训，并接受考核。"},{"i":7,"n":"第七条","txt":"对认真贯彻《植物检疫条例》及《植物检疫条例实施细则》（农业部分），正确行使检疫员职权，遵守检疫人员守则，完成检疫任务成绩突出者，应予奖励；对玩忽职守，滥用职权，致使国家和人民利益蒙受重大损失者，应视情节轻重，给予批评教育、取消检疫员资格，直至依法追究刑事责任。"}],"nongyebulifagongzuoguiding":[{"i":1,"n":"第一条","txt":"为规范农业部立法工作，保证立法质量，根据《立法法》、《行政法规制定程序条例》、《规章制定程序条例》和《法规规章备案条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称立法工作包括： （一）农业部起草法律草案、行政法规草案的工作； （二）农业部制定部门规章的工作； （三）农业部参与的农业立法工作； （四）　其他与农业立法有关的工作。"},{"i":3,"n":"第三条","txt":"立法工作应当遵循《立法法》、《行政法规制定程序条例》、《规章制定程序条例》确立的立法原则，符合宪法、法律、行政法规的规定。"},{"i":4,"n":"第四条","txt":"产业政策与法规司归口管理和协调部内立法工作，各司局依照本规定负责有关立法工作。"},{"i":5,"n":"第五条","txt":"农业部于每年年底编制下一年度的规章制定工作计划，由产业政策与法规司负责组织实施。"},{"i":6,"n":"第六条","txt":"各司局根据工作需要，提出主管业务范围内下一年度规章制定的立项申请，并于每年１０月３１日前报送产业政策与法规司。 立项申请应当对立法的必要性、立法依据、所要解决的主要问题、拟确立的主要制度、进展情况和进度安排等作出说明。"},{"i":7,"n":"第七条","txt":"产业政策与法规司根据有关司局报送的立项申请和实际工作需要，经综合平衡后，拟订农业部年度规章制定工作计划，报部常务会议审议通过后执行。 年度规章制定工作计划应当明确立法项目名称、主要内容、起草单位等内容。"},{"i":8,"n":"第八条","txt":"规章制定工作应当依照年度规章制定工作计划进行。年度规章制定工作计划在执行中确需调整的，经产业政策与法规司提出，报部领导同意。"},{"i":9,"n":"第九条","txt":"农业部根据需要，编制指导性农业立法五年规划的工作，参照本章的规定进行。 农业部根据全国人大有关部门和国务院的要求，提出法律的立法建议和行政法规的立项申请的工作，参照本章的规定进行。"},{"i":10,"n":"第十条","txt":"法律、行政法规和规章的起草，由提出立法建议或立项申请的司局负责。 重要法律、行政法规和综合性规章的起草工作，由产业政策与法规司负责或者组织有关司局共同办理。 起草法律、行政法规，应当成立起草小组；起草规章，必要时也应当成立起草小组。"},{"i":11,"n":"第十一条","txt":"起草法律、行政法规和规章，一般应当对立法目的、依据、适用（调整）范围、主管机关、主要内容、法律责任或处罚办法、名词界定（定义）、施行日期等作出规定。 起草法律、行政法规和规章，应当考虑原有相关法律、行政法规和规章的规定。需要废止相关法律、行政法规和规章或其部分条款的，应当在草案中予以明确。"},{"i":12,"n":"第十二条","txt":"起草法律、行政法规和规章，应当深入调查研究，总结实践经验，并根据具体情况，采取书面征求意见、座谈会、论证会、听证会和向社会公布等形式广泛听取有关机关、组织和公民的意见。"},{"i":13,"n":"第十三条","txt":"起草法律、行政法规和规章，涉及国务院其他部门的职责或者与国务院其他部门关系紧密的，或者涉及部内相关司局业务的，应当征求其他部门或相关司局的意见，充分协商，达成一致。协商不成的，应当说明情况和理由。"},{"i":14,"n":"第十四条","txt":"法律、行政法规和规章草案经起草司局负责人签字后，报送产业政策与法规司审查。涉及其他司局业务的，应当会签有关司局。"},{"i":15,"n":"第十五条","txt":"起草司局报送法律、行政法规和规章草案时，应当同时报送立法说明和其他有关材料。 立法说明应当对立法的必要性、起草过程、规定的主要措施、有关方面的意见等情况作出说明。 其他有关材料主要包括汇总的意见、听证会笔录、调研报告、国内外有关立法资料等。"},{"i":16,"n":"第十六条","txt":"产业政策与法规司对起草司局报送的法律、行政法规和规章草案，应当从以下方面进行审查： （一）是否符合宪法、法律、行政法规的规定和国家的方针政策； （二）是否与有关法律、行政法规和规章协调、衔接； （三）是否正确处理有关机关、组织和公民对法律、行政法规和规章草案主要问题的意见； （四）是否符合立法技术要求； （五）需要审查的其他内容。"},{"i":17,"n":"第十七条","txt":"报送审查的法律、行政法规和规章草案有下列情形之一的，产业政策与法规司可以缓办或者退回起草司局： （一）草案中规定的主要制度和措施尚不成熟的； （二）国务院其他部门或部内相关司局对草案中规定的主要制度存在较大争议，起草司局未与国务院其他部门或部内相关司局协商的； （三）不符合本规定第十四条和第十五条规定的。"},{"i":18,"n":"第十八条","txt":"在审查过程中，产业政策与法规司可以根据情况，进行下列工作： （一）就立法涉及的主要问题发送有关机关、组织和专家征求意见，或者向社会公布征求意见； （二）就立法涉及的主要问题深入基层进行调研，听取意见； （三）召开座谈会、论证会、听证会，听取意见，研究论证； （四）对立法中的不同意见进行协调。"},{"i":19,"n":"第十九条","txt":"产业政策与法规司应当认真研究各方面的意见，会同起草司局对报送审查的法律、行政法规和规章草案及草案说明进行修改。对立法中的不同意见经协调不能达成一致的，报请部领导决定。 拟报部常务会议审议的法律、行政法规和规章草案，由产业政策与法规司提出提请部常务会议审议的建议。 起草司局应当根据部长办公室的要求，提交相应份数的法律、行政法规和规章草案及其说明文本。"},{"i":20,"n":"第二十条","txt":"部常务会议审议法律、行政法规和规章草案时，起草小组或起草司局应当就该草案作说明。 法律、行政法规和规章草案由其他司局起草的，产业政策与法规司应当就审查情况等作说明。"},{"i":21,"n":"第二十一条","txt":"起草小组或起草司局应当根据部常务会议审议意见，对法律、行政法规和规章草案进行修改，经产业政策与法规司审核、办公厅核稿登记后，送部长或主管副部长签发。"},{"i":22,"n":"第二十二条","txt":"报国务院的法律、行政法规草案，经部常务会议审议通过后，由部长或主管副部长签发。"},{"i":23,"n":"第二十三条","txt":"农业部规章，经部常务会议审议通过后，由部长签署农业部令公布。"},{"i":24,"n":"第二十四条","txt":"农业部规章签署公布后，由办公厅送《农民日报》及时全文刊登。"},{"i":25,"n":"第二十五条","txt":"农业部制定的规章，由起草司局在规章公布之日起十五日内将规章正式文本和起草说明按照规定的格式装订成册，一式十五份，与规章的电子文本一起报送产业政策与法规司，由产业政策与法规司按照《法规规章备案条例》的规定，统一向国务院备案。"},{"i":26,"n":"第二十六条","txt":"农业部和其他部门联合制定的规章，由主办部门负责报国务院备案。农业部为主办部门的，按第二十五条规定办理。"},{"i":27,"n":"第二十七条","txt":"农业法律、行政法规和规章依照规定，需要由农业部进行解释的，应当由省级农业行政主管部门向农业部提出申请；部内司局认为需要解释的，应当向产业政策与法规司提出。"},{"i":28,"n":"第二十八条","txt":"符合下列情形的农业法律、行政法规的解释，由产业政策与法规司会同有关司局提出意见，报部领导签发后，依照有关规定送请制定机关作出解释： （一）条文本身需要进一步明确界限的； （二）需要作补充规定的。"},{"i":29,"n":"第二十九条","txt":"属于行政工作中具体应用农业法律、行政法规问题的解释，以及农业部规章的解释，由产业政策与法规司会同有关司局提出意见，报部常务会议审议通过后或者部领导签发后公布。"},{"i":30,"n":"第三十条","txt":"对属于行政工作中具体应用农业部规章问题的询问，由产业政策与法规司会同有关司局研究，以办公厅文件的形式答复。涉及重大问题的，应当报部领导签发后，以农业部文件的形式答复。 地方农业部门就农业部规章的具体应用问题向农业部申请答复的，应当由省级农业行政主管部门提出。"},{"i":31,"n":"第三十一条","txt":"农业部与有关部门联合发布，非农业部为主起草的规章草案，其协调工作由参加起草的司局负责办理；农业部为主起草的规章，其协调工作由起草司局办理。以部名义行文的，由办文司局负责人签字，会签产业政策与法规司后，报主管副部长签发。"},{"i":32,"n":"第三十二条","txt":"有关部门送农业部征求意见的法律、行政法规和规章草案，由产业政策与法规司组织有关司局提出意见，并以农业部文件或办公厅文件的形式答复有关部门。"},{"i":33,"n":"第三十三条","txt":"对有关部门送农业部征求意见的法律、行政法规和规章草案，办公厅应当及时转送产业政策与法规司；产业政策与法规司应当及时征求有关司局的意见，做好组织和综合工作；有关司局应当及时研究办理，提出书面意见并加盖本司局印章后，送产业政策与法规司。超过规定时限未答复的，或者未加盖本司局印章的，视为无意见。"},{"i":34,"n":"第三十四条","txt":"产业政策与法规司应当根据需要或有关机关的要求，组织各司局对农业法律、行政法规和规章进行清理。"},{"i":35,"n":"第三十五条","txt":"经清理需要修改的法律、行政法规，由产业政策与法规司会同有关司局提出意见，报部领导同意后，向制定机关提出修改建议。需要由农业部修改的，按照本规定的程序办理。 经清理需要修改的规章，由产业政策与法规司会同有关司局提出建议，报部领导同意后，按照本规定的程序进行修改。"},{"i":36,"n":"第三十六条","txt":"经清理需要废止的法律、行政法规，由产业政策与法规司会同有关司局提出意见，报部领导同意后，向制定机关提出废止建议。 经清理应当废止的规章，由产业政策与法规司会同有关司局提出建议，报部常务会议审议通过后，由部长签署农业部令予以废止。"},{"i":37,"n":"第三十七条","txt":"农业部各司局应当掌握相关法律、行政法规和规章的贯彻实施情况，发现有下列情形之一的，应当及时提出修改或废止建议： （一）法律、行政法规和规章的规定与上位法不一致的； （二）被新的法律、行政法规和规章的规定取代的； （三）不能适应现实需要的； （四）其他需要修改或废止的情形。"},{"i":38,"n":"第三十八条","txt":"农业部规章应当自公布之日起三十日后施行；但是，涉及国家安全或者公布后不立即施行将有碍规章施行的，可以自公布之日起施行。"},{"i":39,"n":"第三十九条","txt":"农业法律、行政法规的宣传工作，由产业政策与法规司组织有关司局办理。"},{"i":40,"n":"第四十条","txt":"产业政策与法规司应当参照《法规汇编编辑出版管理规定》，对农业法律、行政法规和规章进行汇编。"},{"i":41,"n":"第四十一条","txt":"本规定由农业部负责解释。"},{"i":42,"n":"第四十二条","txt":"本规定自二○○三年一月一日起施行。一九九一年十二月二十四日农业部发布的《农业部立法工作暂行规定》同时废止。"}],"nongyeyeshengzhiwubaohubanfa":[{"i":1,"n":"第一条","txt":"为保护和合理利用珍稀、濒危野生植物资源，保护生物多样性，加强野生植物管理，根据《中华人民共和国野生植物保护条例》(以下简称《条例》)，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称野生植物是指符合《条例》第二条第二款规定的野生植物，包括野生植物的任何部分及其衍生物。"},{"i":3,"n":"第三条","txt":"农业农村部按照《条例》第八条和本办法第二条规定的范围，主管全国野生植物的监督管理工作，并设立野生植物保护管理办公室负责全国野生植物监督管理的日常工作。 农业农村部野生植物保护管理办公室由部内有关司局组成。 县级以上地方人民政府农业农村(畜牧、渔业)主管部门(以下简称农业农村主管部门)依据《条例》和本办法规定负责本行政区域内野生植物监督管理工作。"},{"i":4,"n":"第四条","txt":"国家重点保护野生植物名录的制定和调整由农业农村部野生植物保护管理办公室提出初步意见，经农业农村部野生植物保护专家审定委员会审定通过后，由农业农村部按照《条例》第十条第二款的规定报国务院批准公布。"},{"i":5,"n":"第五条","txt":"农业农村部和省级农业农村主管部门负责在国家重点保护野生植物物种天然集中分布区域，划定并建立国家级或省级国家重点保护野生植物类型自然保护区。 国家级和省级国家重点保护野生植物类型自然保护区的建立，按照《中华人民共和国自然保护区条例》有关规定执行。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府农业农村主管部门可以在国家级或省级野生植物类型保护区以外的其他区域，建立国家重点保护野生植物保护点或者设立保护标志。 国家重点保护野生植物保护点和保护标志的具体管理办法，由农业农村部野生植物保护管理办公室负责统一制定。"},{"i":7,"n":"第七条","txt":"农业农村部根据需要，组织野生植物资源调查，建立国家重点保护野生植物资源档案，为确定国家重点保护野生植物名录及保护方案提供依据。"},{"i":8,"n":"第八条","txt":"农业农村部建立国家重点保护野生植物监测制度，对国家重点保护野生植物进行动态监测。"},{"i":9,"n":"第九条","txt":"县级以上农业农村主管部门所属的农业环境监测机构，负责监视、监测本辖区内环境质量变化对国家或地方重点保护野生植物生长情况的影响，并将监视、监测情况及时报送农业农村主管部门。"},{"i":10,"n":"第十条","txt":"在国家重点保护野生植物生长地或周边地区实施建设项目，建设单位应当在该建设项目环境影响评价报告书中对是否影响野生植物生存环境作出专项评价。 建设项目所在区域农业农村主管部门依据《条例》规定，对上述专项评价进行审查，并根据审查结果对建设项目提出具体意见。"},{"i":11,"n":"第十一条","txt":"对国家重点保护野生植物及其生长环境造成危害的单位和个人，应当及时采取补救措施，并报当地农业农村主管部门，接受调查处理。"},{"i":12,"n":"第十二条","txt":"各级农业农村主管部门应当积极开展野生植物保护的宣传教育工作。"},{"i":13,"n":"第十三条","txt":"禁止采集国家一级保护野生植物。有下列情形之一，确需进行少量采集的，应当申请办理采集许可证。 （一）进行科学考察、资源调查，应当从野外获取野生植物标本的； （二）进行野生植物人工培育、驯化，应当从野外获取种源的； （三）承担省部级以上科研项目，应当从野外获取标本或实验材料的； （四）因国事活动需要，应当提供并从野外获取野生植物活体的； （五）因调控野生植物种群数量、结构，经科学论证应当采集的。"},{"i":14,"n":"第十四条","txt":"申请采集国家重点保护野生植物，有下列情形之一的，不予发放采集许可证： （一）申请人有条件以非采集的方式获取野生植物的种源、产品或者达到其目的； （二）采集申请不符合国家或地方有关规定，或者采集申请的采集方法、采集时间、采集地点、采集数量不当的； （三）根据野生植物资源现状不宜采集的。"},{"i":15,"n":"第十五条","txt":"申请采集国家重点保护野生植物，应当填写《国家重点保护野生植物采集申请表》，经采集地县级农业农村主管部门签署审核意见后，向采集地省级农业农村主管部门或其授权的野生植物保护管理机构申请办理采集许可证。 采集城市园林或风景名胜区内的国家重点保护野生植物，按照《条例》第十六条第三款和前款有关规定办理。"},{"i":16,"n":"第十六条","txt":"申请采集国家一级重点保护野生植物的，还应当提供以下材料： （一）进行科学考察、资源调查，需要从野外获取野生植物标本的，或者进行野生植物人工培育、驯化，需要从野外获取种源的，应当提供省级以上主管部门批复的项目审批文件、项目任务书（合同书）及执行方案（均为复印件）。 （二）承担省部级以上科研项目，需要从野外获取标本或实验材料的，应当提供项目审批文件、项目任务书（合同书）及执行方案（均为复印件）。 （三）因国事活动，需要提供并从野外获取野生植物活体的，应当出具国务院外事主管部门的证明文件（复印件）。 （四）因调控野生植物种群数量、结构，经科学论证需要采集的，应当出具省级以上农业农村主管部门或省部级以上科研机构的论证报告或说明。"},{"i":17,"n":"第十七条","txt":"负责签署审核意见的农业农村主管部门应当自受理申请之日起20日内签署审核意见。同意采集的，报送上级农业农村主管部门审批。 负责核发采集许可的农业农村主管部门或其授权的野生植物保护管理机构，应当在收到下级农业农村主管部门报来的审核材料之日起20日内，作出批准或不批准的决定，并及时通知申请者。 接受授权的野生植物保护管理机构在作出批准或者不批准的决定之前，应当征求本部门业务主管单位的意见。 农业农村主管部门或其授权的野生植物保护管理机构核发采集许可证后，应当抄送同级生态环境主管部门备案。 省级农业农村主管部门或其授权的野生植物保护管理机构核发采集许可证后，应当向农业农村部备案。"},{"i":18,"n":"第十八条","txt":"取得采集许可证的单位和个人，应当按照许可证规定的植物种(或亚种)、数量、地点、期限和方式进行采集。采集作业完成后，应当及时向批准采集的农业农村主管部门或其授权的野生植物保护管理机构申请查验。 县级农业农村主管部门对在本辖区内的采集国家或地方重点保护野生植物的活动，应当进行实时监督检查，并应及时向批准采集的农业农村主管部门或其授权的野生植物保护管理机构报告监督检查结果。"},{"i":19,"n":"第十九条","txt":"出售、收购国家二级保护野生植物的，应当填写《出售、收购国家重点保护二级野生植物申请表》，省级农业农村主管部门或其授权的野生植物保护管理机构自收到申请之日起20日内完成审查，作出是否批准的决定，并通知申请者。 由野生植物保护管理机构负责批准的，野生植物保护管理机构在做出批准或者不批准的决定之前，应当征求本部门业务主管单位的意见。"},{"i":20,"n":"第二十条","txt":"出售、收购国家二级保护野生植物的许可为一次一批。 出售、收购国家二级保护野生植物的许可文件应当载明野生植物的物种名称(或亚种名)、数量、期限、地点及获取方式、来源等项内容。"},{"i":21,"n":"第二十一条","txt":"国家重点保护野生植物的采集限定采集方式和规定禁采期。 国家重点保护野生植物的采集方式和禁采期由省级人民政府农业农村主管部门负责规定。 禁止在禁采期内或者以非法采集方式采集国家重点保护野生植物。"},{"i":22,"n":"第二十二条","txt":"出口国家重点保护野生植物，或者进出口中国参加的国际公约所限制进出口的野生植物，应当填报《国家重点保护野生植物进出口许可申请表》，并报申请者所在地省级农业农村主管部门办理《国家重点保护野生植物进出口许可审批表》。省级农业农村主管部门应当自收到申请材料之日起20日作出是否批准的决定，并通知申请者。 省级农业农村主管部门应当将签发的进出口许可审批表抄送农业农村部、国家濒危物种进出口管理机构、海关等部门。"},{"i":23,"n":"第二十三条","txt":"申请出口国家重点保护野生植物，或者进出口中国参加的国际公约所限制进出口的野生植物的，应当提供以下材料： （一）国家重点保护野生植物进出口许可申请表。 （二）进出口合同（协议）复印件。 （三）出口野生植物及其产品的，应当提供省级以上农业农村主管部门或其授权机构核发的《国家重点保护野生植物采集许可证》复印件；野生植物来源为收购的，还应当提供省级农业农村主管部门出具的出售、收购审批件及购销合同（均为复印件）。 （四）出口含有国家重点保护农业野生植物成分产品的，应当提供由产品生产单位所在地省级以上农业农村主管部门认可的产品成分及规格的说明，以及产品成分检验报告。"},{"i":24,"n":"第二十四条","txt":"经省级农业农村主管部门批准进行野外考察的外国人，应当在地方农业农村主管部门有关人员的陪同下，按照规定的时间、区域、路线、植物种类进行考察。 考察地省级农业农村主管部门或其授权的野生植物保护管理机构应当对外国人在本行政区域内的考察活动进行现场监督检查，并及时将监督检查情况报告农业农村部野生植物保护管理办公室。 外国人野外科学考察结束离境之前，应当向省级农业农村主管部门提交此次科学考察的报告副本。"},{"i":25,"n":"第二十五条","txt":"在野生植物资源保护、科学研究、培育利用、宣传教育及其管理工作中成绩显著的单位和个人，县级以上人民政府农业农村主管部门予以表彰和奖励。"},{"i":26,"n":"第二十六条","txt":"违反本办法规定，依照《条例》的有关规定追究法律责任。"},{"i":27,"n":"第二十七条","txt":"本办法规定的《国家重点保护野生植物采集申请表》、《国家重点保护野生植物采集许可证》、《国家重点保护野生植物进出口许可申请表》和《国家重点保护野生植物进出口许可审批表》等文书格式，由农业农村部规定。有关表格由农业农村部野生植物保护管理办公室统一监制。《出售、收购国家重点保护二级野生植物申请表》等其他文书格式由省级农业农村主管部门规定。"},{"i":28,"n":"第二十八条","txt":"本办法由农业农村部负责解释。"},{"i":29,"n":"第二十九条","txt":"本办法自2002年10月1日起施行。"}],"nongchanpinchandianquanguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强农产品产地管理，改善产地条件，保障产地安全，依据《中华人民共和国农产品质量安全法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称农产品产地，是指植物、动物、微生物及其产品生产的相关区域。 本办法所称农产品产地安全，是指农产品产地的土壤、水体和大气环境质量等符合生产质量安全农产品要求。"},{"i":3,"n":"第三条","txt":"农业部负责全国农产品产地安全的监督管理。 县级以上地方人民政府农业行政主管部门负责本行政区域内农产品产地的划分和监督管理。"},{"i":4,"n":"第四条","txt":"县级以上人民政府农业行政主管部门应当建立健全农产品产地安全监测管理制度，加强农产品产地安全调查、监测和评价工作，编制农产品产地安全状况及发展趋势年度报告，并报上级农业行政主管部门备案。"},{"i":5,"n":"第五条","txt":"省级以上人民政府农业行政主管部门应当在下列地区分别设置国家和省级监测点，监控农产品产地安全变化动态，指导农产品产地安全管理和保护工作。 （一）工矿企业周边的农产品生产区； （二）污水灌溉区； （三）大中城市郊区农产品生产区； （四）重要农产品生产区； （五）其他需要监测的区域。"},{"i":6,"n":"第六条","txt":"农产品产地安全调查、监测和评价应当执行国家有关标准等技术规范。 监测点的设置、变更、撤销应当通过专家论证。"},{"i":7,"n":"第七条","txt":"县级以上人民政府农业行政主管部门应当加强农产品产地安全信息统计工作，健全农产品产地安全监测档案。 监测档案应当准确记载产地安全变化状况，并长期保存。"},{"i":8,"n":"第八条","txt":"农产品产地有毒有害物质不符合产地安全标准，并导致农产品中有毒有害物质不符合农产品质量安全标准的，应当划定为农产品禁止生产区。 禁止生产食用农产品的区域可以生产非食用农产品。"},{"i":9,"n":"第九条","txt":"符合本办法第八条规定情形的，由县级以上地方人民政府农业行政主管部门提出划定禁止生产区的建议，报省级农业行政主管部门。省级农业行政主管部门应当组织专家论证，并附具下列材料报本级人民政府批准后公布。 （一）产地安全监测结果和农产品检测结果； （二）产地安全监测评价报告，包括产地污染原因分析、产地与农产品污染的相关性分析、评价方法与结论等； （三）专家论证报告； （四）农业生产结构调整及相关处理措施的建议。"},{"i":10,"n":"第十条","txt":"禁止生产区划定后，不得改变耕地、基本农田的性质，不得降低农用地征地补偿标准。"},{"i":11,"n":"第十一条","txt":"县级人民政府农业行政主管部门应当在禁止生产区设置标示牌，载明禁止生产区地点、四至范围、面积、禁止生产的农产品种类、主要污染物种类、批准单位、立牌日期等。 任何单位和个人不得擅自移动和损毁标示牌。"},{"i":12,"n":"第十二条","txt":"禁止生产区安全状况改善并符合相关标准的，县级以上地方人民政府农业行政主管部门应当及时提出调整建议。 禁止生产区的调整依照本办法第九条的规定执行。禁止生产区调整的，应当变更标示牌内容或者撤除标示牌。"},{"i":13,"n":"第十三条","txt":"县级以上地方人民政府农业行政主管部门应当及时将本行政区域内农产品禁止生产区划定与调整结果逐级上报农业部备案。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府农业行政主管部门应当推广清洁生产技术和方法，发展生态农业。"},{"i":15,"n":"第十五条","txt":"县级以上地方人民政府农业行政主管部门应当制定农产品产地污染防治与保护规划，并纳入本地农业和农村经济发展规划。"},{"i":16,"n":"第十六条","txt":"县级以上人民政府农业行政主管部门应当采取生物、化学、工程等措施，对农产品禁止生产区和有毒有害物质不符合产地安全标准的其他农产品生产区域进行修复和治理。"},{"i":17,"n":"第十七条","txt":"县级以上人民政府农业行政主管部门应当采取措施，加强产地污染修复和治理的科学研究、技术推广、宣传培训工作。"},{"i":18,"n":"第十八条","txt":"农业建设项目的环境影响评价文件应当经县级以上人民政府农业行政主管部门依法审核后，报有关部门审批。 已经建成的企业或者项目污染农产品产地的，当地人民政府农业行政主管部门应当报请本级人民政府采取措施，减少或消除污染危害。"},{"i":19,"n":"第十九条","txt":"任何单位和个人不得在禁止生产区生产、捕捞、采集禁止的食用农产品和建立农产品生产基地。"},{"i":20,"n":"第二十条","txt":"禁止任何单位和个人向农产品产地排放或者倾倒废气、废水、固体废物或者其他有毒有害物质。 禁止在农产品产地堆放、贮存、处置工业固体废物。在农产品产地周围堆放、贮存、处置工业固体废物的，应当采取有效措施，防止对农产品产地安全造成危害。"},{"i":21,"n":"第二十一条","txt":"任何单位和个人提供或者使用农业用水和用作肥料的城镇垃圾、污泥等固体废物，应当经过无害化处理并符合国家有关标准。"},{"i":22,"n":"第二十二条","txt":"农产品生产者应当合理使用肥料、农药、兽药、饲料和饲料添加剂、农用薄膜等农业投入品。禁止使用国家明令禁止、淘汰的或者未经许可的农业投入品。 农产品生产者应当及时清除、回收农用薄膜、农业投入品包装物等，防止污染农产品产地环境。"},{"i":23,"n":"第二十三条","txt":"县级以上人民政府农业行政主管部门负责农产品产地安全的监督检查。 农业行政执法人员履行监督检查职责时，应当向被检查单位或者个人出示行政执法证件。有关单位或者个人应当如实提供有关情况和资料，不得拒绝检查或者提供虚假情况。"},{"i":24,"n":"第二十四条","txt":"县级以上人民政府农业行政主管部门发现农产品产地受到污染威胁时，应当责令致害单位或者个人采取措施，减少或者消除污染威胁。有关单位或者个人拒不采取措施的，应当报请本级人民政府处理。 农产品产地发生污染事故时，县级以上人民政府农业行政主管部门应当依法调查处理。 发生农业环境污染突发事件时，应当依照农业环境污染突发事件应急预案的规定处理。"},{"i":25,"n":"第二十五条","txt":"产地安全监测和监督检查经费应当纳入本级人民政府农业行政主管部门年度预算。开展产地安全监测和监督检查不得向被检查单位或者个人收取任何费用。"},{"i":26,"n":"第二十六条","txt":"违反《中华人民共和国农产品质量安全法》和本办法规定的划定标准和程序划定的禁止生产区无效。 违反本办法规定，擅自移动、损毁禁止生产区标牌的，由县级以上地方人民政府农业行政主管部门责令限期改正，可处以一千元以下罚款。 其他违反本办法规定的，依照有关法律法规处罚。"},{"i":27,"n":"第二十七条","txt":"本办法自2006年11月1日起施行。 附件： 农产品产地安全管理办法-清样"}],"nongchanpinbaozhuanghebiaoshiguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范农产品生产经营行为，加强农产品包装和标识管理，建立健全农产品可追溯制度，保障农产品质量安全，依据《中华人民共和国农产品质量安全法》，制定本办法。"},{"i":2,"n":"第二条","txt":"农产品的包装和标识活动应当符合本办法规定。"},{"i":3,"n":"第三条","txt":"农业部负责全国农产品包装和标识的监督管理工作。 县级以上地方人民政府农业行政主管部门负责本行政区域内农产品包装和标识的监督管理工作。"},{"i":4,"n":"第四条","txt":"国家支持农产品包装和标识科学研究，推行科学的包装方法，推广先进的标识技术。"},{"i":5,"n":"第五条","txt":"县级以上人民政府农业行政主管部门应当将农产品包装和标识管理经费纳入年度预算。"},{"i":6,"n":"第六条","txt":"县级以上人民政府农业行政主管部门对在农产品包装和标识工作中做出突出贡献的单位和个人，予以表彰和奖励。"},{"i":7,"n":"第七条","txt":"农产品生产企业、农民专业合作经济组织以及从事农产品收购的单位或者个人，用于销售的下列农产品必须包装： （一）获得无公害农产品、绿色食品、有机农产品等认证的农产品，但鲜活畜、禽、水产品除外。 （二）省级以上人民政府农业行政主管部门规定的其他需要包装销售的农产品。 符合规定包装的农产品拆包后直接向消费者销售的，可以不再另行包装。"},{"i":8,"n":"第八条","txt":"农产品包装应当符合农产品储藏、运输、销售及保障安全的要求，便于拆卸和搬运。"},{"i":9,"n":"第九条","txt":"包装农产品的材料和使用的保鲜剂、防腐剂、添加剂等物质必须符合国家强制性技术规范要求。 包装农产品应当防止机械损伤和二次污染。"},{"i":10,"n":"第十条","txt":"农产品生产企业、农民专业合作经济组织以及从事农产品收购的单位或者个人包装销售的农产品，应当在包装物上标注或者附加标识标明品名、产地、生产者或者销售者名称、生产日期。 有分级标准或者使用添加剂的，还应当标明产品质量等级或者添加剂名称。 未包装的农产品，应当采取附加标签、标识牌、标识带、说明书等形式标明农产品的品名、生产地、生产者或者销售者名称等内容。"},{"i":11,"n":"第十一条","txt":"农产品标识所用文字应当使用规范的中文。标识标注的内容应当准确、清晰、显著。"},{"i":12,"n":"第十二条","txt":"销售获得无公害农产品、绿色食品、有机农产品等质量标志使用权的农产品，应当标注相应标志和发证机构。 禁止冒用无公害农产品、绿色食品、有机农产品等质量标志。"},{"i":13,"n":"第十三条","txt":"畜禽及其产品、属于农业转基因生物的农产品，还应当按照有关规定进行标识。"},{"i":14,"n":"第十四条","txt":"农产品生产企业、农民专业合作经济组织以及从事农产品收购的单位或者个人，应当对其销售农产品的包装质量和标识内容负责。"},{"i":15,"n":"第十五条","txt":"县级以上人民政府农业行政主管部门依照《中华人民共和国农产品质量安全法》对农产品包装和标识进行监督检查。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，由县级以上人民政府农业行政主管部门按照《中华人民共和国农产品质量安全法》第四十八条、四十九条、五十一条、五十二条的规定处理、处罚： （一）使用的农产品包装材料不符合强制性技术规范要求的； （二）农产品包装过程中使用的保鲜剂、防腐剂、添加剂等材料不符合强制性技术规范要求的； （三）应当包装的农产品未经包装销售的； （四）冒用无公害农产品、绿色食品等质量标志的； （五）农产品未按照规定标识的。"},{"i":17,"n":"第十七条","txt":"本办法下列用语的含义： （一）农产品包装：是指对农产品实施装箱、装盒、装袋、包裹、捆扎等。 （二）保鲜剂：是指保持农产品新鲜品质，减少流通损失，延长贮存时间的人工合成化学物质或者天然物质。 （三）防腐剂：是指防止农产品腐烂变质的人工合成化学物质或者天然物质。 （四）添加剂：是指为改善农产品品质和色、香、味以及加工性能加入的人工合成化学物质或者天然物质。 （五）生产日期：植物产品是指收获日期；畜禽产品是指屠宰或者产出日期；水产品是指起捕日期；其他产品是指包装或者销售时的日期。"},{"i":18,"n":"第十八条","txt":"本办法自2006年11月1日起施行。"}],"nongchanpindilibiaozhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范农产品地理标志的使用，保证地理标志农产品的品质和特色，提升农产品市场竞争力，依据《中华人民共和国农业法》、《中华人民共和国农产品质量安全法》相关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称农产品是指来源于农业的初级产品，即在农业活动中获得的植物、动物、微生物及其产品。 本办法所称农产品地理标志，是指标示农产品来源于特定地域，产品品质和相关特征主要取决于自然生态环境和历史人文因素，并以地域名称冠名的特有农产品标志。"},{"i":3,"n":"第三条","txt":"国家对农产品地理标志实行登记制度。经登记的农产品地理标志受法律保护。"},{"i":4,"n":"第四条","txt":"农业部负责全国农产品地理标志的登记工作，农业部农产品质量安全中心负责农产品地理标志登记的审查和专家评审工作。 省级人民政府农业行政主管部门负责本行政区域内农产品地理标志登记申请的受理和初审工作。 农业部设立的农产品地理标志登记专家评审委员会，负责专家评审。农产品地理标志登记专家评审委员会由种植业、畜牧业、渔业和农产品质量安全等方面的专家组成。"},{"i":5,"n":"第五条","txt":"农产品地理标志登记不收取费用。县级以上人民政府农业行政主管部门应当将农产品地理标志管理经费编入本部门年度预算。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府农业行政主管部门应当将农产品地理标志保护和利用纳入本地区的农业和农村经济发展规划，并在政策、资金等方面予以支持。 国家鼓励社会力量参与推动地理标志农产品发展。"},{"i":7,"n":"第七条","txt":"申请地理标志登记的农产品，应当符合下列条件： （一）称谓由地理区域名称和农产品通用名称构成； （二）产品有独特的品质特性或者特定的生产方式； （三）产品品质和特色主要取决于独特的自然生态环境和人文历史因素； （四）产品有限定的生产区域范围； （五）产地环境、产品质量符合国家强制性技术规范要求。"},{"i":8,"n":"第八条","txt":"农产品地理标志登记申请人为县级以上地方人民政府根据下列条件择优确定的农民专业合作经济组织、行业协会等组织。 （一）具有监督和管理农产品地理标志及其产品的能力； （二）具有为地理标志农产品生产、加工、营销提供指导服务的能力； （三）具有独立承担民事责任的能力。"},{"i":9,"n":"第九条","txt":"符合农产品地理标志登记条件的申请人，可以向省级人民政府农业行政主管部门提出登记申请，并提交下列申请材料： （一）登记申请书； （二）产品典型特征特性描述和相应产品品质鉴定报告； （三）产地环境条件、生产技术规范和产品质量安全技术规范； （四）地域范围确定性文件和生产地域分布图； （五）产品实物样品或者样品图片； （六）其它必要的说明性或者证明性材料。"},{"i":10,"n":"第十条","txt":"省级人民政府农业行政主管部门自受理农产品地理标志登记申请之日起，应当在45个工作日内完成申请材料的初审和现场核查，并提出初审意见。符合条件的，将申请材料和初审意见报送农业部农产品质量安全中心；不符合条件的，应当在提出初审意见之日起10个工作日内将相关意见和建议通知申请人。"},{"i":11,"n":"第十一条","txt":"农业部农产品质量安全中心应当自收到申请材料和初审意见之日起20个工作日内，对申请材料进行审查，提出审查意见，并组织专家评审。 专家评审工作由农产品地理标志登记评审委员会承担。农产品地理标志登记专家评审委员会应当独立做出评审结论，并对评审结论负责。"},{"i":12,"n":"第十二条","txt":"经专家评审通过的，由农业部农产品质量安全中心代表农业部对社会公示。 有关单位和个人有异议的，应当自公示截止日起20日内向农业部农产品质量安全中心提出。公示无异议的，由农业部做出登记决定并公告，颁发《中华人民共和国农产品地理标志登记证书》，公布登记产品相关技术规范和标准。 专家评审没有通过的，由农业部做出不予登记的决定，书面通知申请人，并说明理由。"},{"i":13,"n":"第十三条","txt":"农产品地理标志登记证书长期有效。 有下列情形之一的，登记证书持有人应当按照规定程序提出变更申请： （一）登记证书持有人或者法定代表人发生变化的； （二）地域范围或者相应自然生态环境发生变化的。"},{"i":14,"n":"第十四条","txt":"农产品地理标志实行公共标识与地域产品名称相结合的标注制度。公共标识基本图案见附图。农产品地理标志使用规范由农业部另行制定公布。"},{"i":15,"n":"第十五条","txt":"符合下列条件的单位和个人，可以向登记证书持有人申请使用农产品地理标志： （一）生产经营的农产品产自登记确定的地域范围； （二）已取得登记农产品相关的生产经营资质； （三）能够严格按照规定的质量技术规范组织开展生产经营活动； （四）具有地理标志农产品市场开发经营能力。 使用农产品地理标志，应当按照生产经营年度与登记证书持有人签订农产品地理标志使用协议，在协议中载明使用的数量、范围及相关的责任义务。 农产品地理标志登记证书持有人不得向农产品地理标志使用人收取使用费。"},{"i":16,"n":"第十六条","txt":"农产品地理标志使用人享有以下权利： （一）可以在产品及其包装上使用农产品地理标志； （二）可以使用登记的农产品地理标志进行宣传和参加展览、展示及展销。"},{"i":17,"n":"第十七条","txt":"农产品地理标志使用人应当履行以下义务： （一）自觉接受登记证书持有人的监督检查； （二）保证地理标志农产品的品质和信誉； （三）正确规范地使用农产品地理标志。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府农业行政主管部门应当加强农产品地理标志监督管理工作，定期对登记的地理标志农产品的地域范围、标志使用等进行监督检查。 登记的地理标志农产品或登记证书持有人不符合本办法第七条、第八条规定的，由农业部注销其地理标志登记证书并对外公告。"},{"i":19,"n":"第十九条","txt":"地理标志农产品的生产经营者，应当建立质量控制追溯体系。农产品地理标志登记证书持有人和标志使用人，对地理标志农产品的质量和信誉负责。"},{"i":20,"n":"第二十条","txt":"任何单位和个人不得伪造、冒用农产品地理标志和登记证书。"},{"i":21,"n":"第二十一条","txt":"国家鼓励单位和个人对农产品地理标志进行社会监督。"},{"i":22,"n":"第二十二条","txt":"从事农产品地理标志登记管理和监督检查的工作人员滥用职权、玩忽职守、徇私舞弊的，依法给予处分；涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"违反本办法规定的，由县级以上人民政府农业行政主管部门依照《中华人民共和国农产品质量安全法》有关规定处罚。"},{"i":24,"n":"第二十四条","txt":"农业部接受国外农产品地理标志在中华人民共和国的登记并给予保护，具体办法另行规定。"},{"i":25,"n":"第二十五条","txt":"本办法自2008年2月1日起施行。"}],"nongchanpinzhilianganquanchengnuodabiaohegezhenggufbe7ad":[{"i":1,"n":"第一条","txt":"为规范农产品质量安全承诺达标合格证管理，落实农产品生产经营者主体责任，保障农产品质量安全，根据《中华人民共和国农产品质量安全法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称农产品质量安全承诺达标合格证（以下简称“承诺达标合格证”），是指农产品生产企业、农民专业合作社、农户和从事农产品收购的单位或者个人，根据质量安全控制、检测结果等依法开具，承诺其销售的农产品未使用禁用农药、兽药及其他化合物且使用的常规农药、兽药残留不超标等的证明。"},{"i":3,"n":"第三条","txt":"下列农产品应当实施承诺达标合格证管理： （一）蔬菜（含人工种植的食用菌）； （二）水果； （三）茶鲜叶； （四）畜禽； （五）禽蛋； （六）养殖水产品； （七）农业农村部规定的其他农产品。"},{"i":4,"n":"第四条","txt":"县级以上人民政府农业农村主管部门应当做好承诺达标合格证开具、收取、保存等工作的指导服务，加强日常监督检查。"},{"i":5,"n":"第五条","txt":"县级人民政府农业农村主管部门应当建立健全本行政区域内农产品生产企业、农民专业合作社名录，会同有关部门建立从事农产品收购的单位或者个人名录，并实行动态管理。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府农业农村主管部门应当积极争取同级人民政府支持，将承诺达标合格证管理经费纳入本部门财政预算。"},{"i":7,"n":"第七条","txt":"农产品生产企业、农民专业合作社应当对生产的农产品质量安全负责，科学合理使用农业投入品，如实做好农产品生产记录，加强生产全过程质量安全控制，保证销售的农产品符合农产品质量安全标准。"},{"i":8,"n":"第八条","txt":"农产品生产企业、农民专业合作社应当在农产品产地按照生产批次开具承诺达标合格证，并如实做好开具记录，开具记录应当至少保存六个月。 根据质量安全控制开具承诺达标合格证的，农产品生产过程应当符合有关质量安全控制措施要求。 根据检测结果开具承诺达标合格证的，应当按照生产批次对农产品用药等情况开展有针对性的检测。"},{"i":9,"n":"第九条","txt":"鼓励和支持农户销售农产品时参照本办法开具承诺达标合格证。 县级人民政府农业农村主管部门可以因地制宜设置区域或者村级农产品质量安全服务点，为农户提供质量安全控制技术指导、农产品快速检测、承诺达标合格证便捷开具等服务。"},{"i":10,"n":"第十条","txt":"从事农产品收购的单位或者个人向农产品生产企业、农民专业合作社收购本办法第三条规定的农产品时，应当收取承诺达标合格证，采用拍照、留存原件、留存复印件或者扫码截屏等方式保存至少六个月。农产品生产企业、农民专业合作社不提供承诺达标合格证的，不得收购。 农户主动提供承诺达标合格证或者其他质量安全合格证明的，从事农产品收购的单位或者个人应当按照前款规定收取和保存。 大量收购带包装农产品的，从事农产品收购的单位或者个人可以对同一生产批次农产品采取随机抽取方式保存承诺达标合格证，并如实记录收购农产品的数量。"},{"i":11,"n":"第十一条","txt":"从事农产品收购的单位或者个人对其收购的农产品进行混装或者分装后销售的，应当根据收购后的质量安全控制、检测结果开具承诺达标合格证并如实做好开具记录，开具记录应当至少保存六个月。"},{"i":12,"n":"第十二条","txt":"畜禽屠宰经营者应当按照本办法第十条的规定收取和保存畜禽养殖企业、农民专业合作社、从事畜禽收购的单位或者个人以及养殖户提供的承诺达标合格证。"},{"i":13,"n":"第十三条","txt":"农产品生产企业、农民专业合作社、从事农产品收购的单位或者个人通过网络平台销售农产品的，应当附具承诺达标合格证。 鼓励在网络平台销售页面显著位置展示相关农产品的承诺达标合格证。"},{"i":14,"n":"第十四条","txt":"承诺达标合格证应当包括承诺事项、承诺依据和产品名称、产品数量、产地、开具时间、承诺主体、联系方式等内容，具体样式由农业农村部制定。 前款规定的内容在农产品包装标识上已标注的，承诺达标合格证可以不再重复标注。"},{"i":15,"n":"第十五条","txt":"开具承诺达标合格证，可以采取信息化、印刷、手工填写等方式。 鼓励采用信息化方式开具承诺达标合格证。采用二维码标识的，应当在二维码周边或者中间显著位置标明“承诺达标合格证”字样，并可以与农产品质量安全追溯标签、农产品质量标志等标识整合。"},{"i":16,"n":"第十六条","txt":"包装销售的农产品，应当以销售包装为单位附具承诺达标合格证，承诺达标合格证应当以适当方式固定在包装表面或者放置在包装内。 无包装销售的农产品，应当以生产批次为单位附具承诺达标合格证。"},{"i":17,"n":"第十七条","txt":"从事农产品收购的单位或者个人发现收取的承诺达标合格证内容不全、与实际不符或者严重不规范的，应当及时向农产品产地县级人民政府农业农村主管部门报告。"},{"i":18,"n":"第十八条","txt":"违反本办法规定，有下列行为之一的，由县级以上地方人民政府农业农村主管部门按照职责给予批评教育，责令限期改正；逾期不改正的，处一百元以上一千元以下罚款： （一）农产品生产企业、农民专业合作社、从事农产品收购的单位或者个人应当开具而没有开具承诺达标合格证的； （二）农产品生产企业、农民专业合作社、从事农产品收购的单位或者个人未根据质量安全控制、检测结果开具承诺达标合格证的； （三）农产品生产企业、农民专业合作社、从事农产品收购的单位或者个人开具的承诺达标合格证内容不全、与实际不符或者严重不规范的； （四）从事农产品收购的单位或者个人、畜禽屠宰经营者未按照规定收取、保存承诺达标合格证或者其他质量安全合格证明的； （五）其他未按照规定开具、收取、保存承诺达标合格证的。"},{"i":19,"n":"第十九条","txt":"农业农村主管部门发现附具承诺达标合格证农产品不合格上市的，应当及时将掌握的信息通报同级市场监管部门。 市场监管部门向农业农村主管部门通报的承诺达标合格证相关违法违规问题，农业农村主管部门应当按照职责及时查处或者移交有管辖权的机关查处。"},{"i":20,"n":"第二十条","txt":"违反本办法第十八条规定给予行政处罚的，县级以上人民政府农业农村主管部门应当按照规定将违法违规行为记入信用记录，依法采取守信激励、失信惩戒措施。"},{"i":21,"n":"第二十一条","txt":"本办法所称收购，是指直接向农产品生产者收购农产品的行为。 本办法所称同一批次农产品，是指采取同一质量安全控制措施并在同一时间收获的同一品种农产品。"},{"i":22,"n":"第二十二条","txt":"本办法自2026年2月1日起施行。"}],"nongchanpinzhilianganquanjiancejigoukaohebanfa":[{"i":1,"n":"第一条","txt":"为加强农产品质量安全检测机构管理，规范农产品质量安全检测机构考核，根据《中华人民共和国农产品质量安全法》等有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称考核，是指省级以上人民政府农业行政主管部门按照法律、法规以及相关标准和技术规范的要求，对向社会出具具有证明作用的数据和结果的农产品质量安全检测机构进行条件与能力评审和确认的活动。"},{"i":3,"n":"第三条","txt":"农产品质量安全检测机构经考核和计量认证合格后，方可对外从事农产品、农业投入品和产地环境检测工作。"},{"i":4,"n":"第四条","txt":"农业部负责全国农产品质量安全检测机构考核的监督管理工作。 省、自治区、直辖市人民政府农业行政主管部门（以下简称省级农业行政主管部门）负责本行政区域农产品质量安全检测机构考核的监督管理工作。"},{"i":5,"n":"第五条","txt":"农产品质量安全检测机构建设，应当统筹规划，合理布局。鼓励检测资源共享，推进县级农产品综合性质检测机构建设。"},{"i":6,"n":"第六条","txt":"农产品质量安全检测机构应当依法设立，保证客观、公正和独立地从事检测活动，并承担相应的法律责任。"},{"i":7,"n":"第七条","txt":"农产品质量安全检测机构应当具有与其从事的农产品质量安全检测活动相适应的管理和技术人员。 从事农产品质量安全检测的技术人员应当具有相关专业中专以上学历，并经所在机构考核合格，持证上岗。"},{"i":8,"n":"第八条","txt":"农产品质量安全检测机构的技术人员应当不少于5人，其中中级以上技术职称或同等能力的人员比例不低于40%。技术负责人、质量负责人和授权签字人应当具有中级以上技术职称或同等能力，并从事农产品质量安全相关工作5年以上。博士研究生毕业，从事相关专业检验检测工作1年及以上；硕士研究生毕业，从事相关专业检验检测工作3年及以上；大学本科毕业，从事相关专业检验检测工作5年及以上；大学专科毕业，从事相关专业检验检测工作8年及以上，可视为同等能力。"},{"i":9,"n":"第九条","txt":"农产品质量安全检测机构应当具有与其从事的农产品质量安全检测活动相适应的检测仪器设备，仪器设备配备率达到98%，在用仪器设备完好率达到100%。"},{"i":10,"n":"第十条","txt":"农产品质量安全检测机构从事相关田间试验和饲养实验动物试验检测的，还应当符合检疫、防疫和环保的要求。 从事农业转基因生物及其产品检测的，还应当具备防范对人体、动植物和环境产生危害的条件。"},{"i":11,"n":"第十一条","txt":"农产品质量安全检测机构应当建立质量管理与质量保证体系。"},{"i":12,"n":"第十二条","txt":"农产品质量安全检测机构应当具有相对稳定的工作经费。"},{"i":13,"n":"第十三条","txt":"申请考核的农产品质量安全检测机构（以下简称申请人），应当向农业部或者省级人民政府农业行政主管部门（以下简称考核机关）提出书面申请。 国务院有关部门依法设立或者授权的农产品质量安全检测机构，经有关部门审核同意后向农业部提出申请。 其他农产品质量安全检测机构，向所在地省级人民政府农业行政主管部门提出申请。"},{"i":14,"n":"第十四条","txt":"申请人应当向考核机关提交下列材料： （一）申请书； （二）机构法人资格证书或者其授权的证明文件； （三）上级或者有关部门批准机构设置的证明文件； （四）质量体系文件； （五）计量认证情况； （六）近两年内的典型性检验报告2份； （七）其他证明材料。"},{"i":15,"n":"第十五条","txt":"考核机关设立或者委托的技术审查机构，负责对申请材料进行初审。"},{"i":16,"n":"第十六条","txt":"考核机关受理申请的，应当及时通知申请人，并将申请材料送技术审查机构；不予受理的，应当及时通知申请人并说明理由。"},{"i":17,"n":"第十七条","txt":"技术审查机构应当自收到申请材料之日起10个工作日内完成对申请材料的初审，并向考核机关提交初审报告。 通过初审的，考核机关安排现场评审；未通过初审的，考核机关应当出具初审不合格通知书。"},{"i":18,"n":"第十八条","txt":"现场评审实行评审专家组负责制。专家组由3-5名评审员组成，必要时可聘请其他技术专家参加。 评审员应当具有高级以上技术职称、从事农产品质量安全检测或相关工作5年以上，并经农业部考核合格。 评审专家组应当在3个工作日内完成评审工作，并向考核机关提交现场评审报告。"},{"i":19,"n":"第十九条","txt":"现场评审应当包括以下内容： （一）质量体系运行情况； （二）检测仪器设备和设施条件； （三）检测能力。"},{"i":20,"n":"第二十条","txt":"考核机关应当自收到现场评审报告之日起10个工作日内，做出申请人是否通过考核的决定。 通过考核的，颁发《中华人民共和国农产品质量安全检测机构考核合格证书》（以下简称《考核合格证书》），准许使用农产品质量安全检测考核标志，并予以公告。 未通过考核的，书面通知申请人并说明理由。"},{"i":21,"n":"第二十一条","txt":"《考核合格证书》应当载明农产品质量安全检测机构名称、检测范围和有效期等内容。"},{"i":22,"n":"第二十二条","txt":"省级农业行政主管部门应当自颁发《考核合格证书》之日起15个工作日内向农业部备案。"},{"i":23,"n":"第二十三条","txt":"《考核合格证书》有效期为6年。证书期满继续从事农产品质量安全检测工作的，应当在有效期届满3个月前提出申请，重新办理《考核合格证书》。"},{"i":24,"n":"第二十四条","txt":"在证书有效期内，农产品质量安全检测机构法定代表人、名称或者地址变更的，应当向原考核机关办理变更手续。"},{"i":25,"n":"第二十五条","txt":"在证书有效期内，农产品质量安全检测机构有下列情形之一的，应当向原考核机关重新申请考核： （一）检测机构分设或者合并的； （二）检测仪器设备和设施条件发生重大变化的； （三）检测场所变更的； （四）检测项目增加的。"},{"i":26,"n":"第二十六条","txt":"考核机关通过年度报告、能力验证、现场检查等方式，对农产品质量安全检测机构进行监督管理。 农产品质量安全检测机构应当按照考核机关的要求，参加其组织开展的能力验证或者比对，以保证持续符合机构考核条件和要求。"},{"i":27,"n":"第二十七条","txt":"对于农产品质量安全检测机构考核工作中的违法行为，任何单位和个人均可以向考核机关举报。考核机关应当对举报内容进行调查核实，并为举报人保密。"},{"i":28,"n":"第二十八条","txt":"农产品质量安全检测机构在考核中隐瞒有关情况或者弄虚作假的，考核机关应当予以警告，取消考核资格，一年内不再受理其考核申请；采取欺骗、贿赂等不正当手段取得考核证书的，撤销考核证书，三年内不再受理其考核申请。 农产品质量安全检测机构伪造检测结果或者出具虚假证明的，或擅自发布检测数据和结果，并造成不良后果的，依照《中华人民共和国农产品质量安全法》相关规定处罚，三年内不受理其机构考核申请。"},{"i":29,"n":"第二十九条","txt":"农产品质量安全检测机构有下列情形之一的，由考核机关责令其1个月内改正；逾期未改正或改正后仍不符合要求的，由考核机关暂停其检测工作。 （一）未按规定对人员、仪器设备、设施条件、质量管理体系、检测工作等实施有效管理的； （二）未按规定办理变更手续的； （三）检验报告、原始记录及其他档案管理不规范的。"},{"i":30,"n":"第三十条","txt":"农产品质量安全检测机构有下列情形之一的，由考核机关责令其3个月内整改，整改期间不得向社会出具具有证明作用的检验检测数据、结果；逾期未整改或整改后仍不符合要求的，由考核机关注销其《考核合格证书》。 （一）超出批准的检测能力范围，擅自向社会出具检验数据、结果的； （二）非授权签字人签发检验报告的； （三）检测工作存在较大风险隐患的。"},{"i":31,"n":"第三十一条","txt":"农产品质量安全检测机构有下列行为之一的，考核机关应当视情况注销其《考核合格证书》： （一）所在单位撤销或者法人资格终结的； （二）检测仪器设备和设施条件发生重大变化，不具备相应检测能力，未按本办法规定重新申请考核的； （三）《考核合格证书》有效期届满，未申请延续或者依法不予延续批准的； （四） 无正当理由未按照考核机关要求参加能力验证的； （五） 无正当理由不接受、不配合监督检查的； （六）依法可注销检测机构资格的其他情形。"},{"i":32,"n":"第三十二条","txt":"从事考核工作的人员不履行职责或者滥用职权的，依法给予处分。"},{"i":33,"n":"第三十三条","txt":"法律、行政法规和农业部规章对农业投入品检测机构考核另有规定的，从其规定。"},{"i":34,"n":"第三十四条","txt":"本办法自2008年1月12日起施行。"}],"nongchanpinzhilianganquanjianceguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强农产品质量安全管理，规范农产品质量安全监测工作，根据《中华人民共和国农产品质量安全法》、《中华人民共和国食品安全法》和《中华人民共和国食品安全法实施条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上人民政府农业农村主管部门开展农产品质量安全监测工作，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"农产品质量安全监测，包括农产品质量安全风险监测和农产品质量安全监督抽查。 农产品质量安全风险监测，是指为了掌握农产品质量安全状况和开展农产品质量安全风险评估，系统和持续地对影响农产品质量安全的有害因素进行检验、分析和评价的活动，包括农产品质量安全例行监测、普查和专项监测等内容。 农产品质量安全监督抽查，是指为了监督农产品质量安全，依法对生产中或市场上销售的农产品进行抽样检测的活动。"},{"i":4,"n":"第四条","txt":"农业农村部根据农产品质量安全风险评估、农产品质量安全监督管理等工作需要，制定全国农产品质量安全监测计划并组织实施。 县级以上地方人民政府农业农村主管部门应当根据全国农产品质量安全监测计划和本行政区域的实际情况，制定本级农产品质量安全监测计划并组织实施。"},{"i":5,"n":"第五条","txt":"农产品质量安全检测工作，由符合《中华人民共和国农产品质量安全法》第三十五条规定条件的检测机构承担。 县级以上人民政府农业农村主管部门应当加强农产品质量安全检测机构建设，提升其检测能力。"},{"i":6,"n":"第六条","txt":"农业农村部统一管理全国农产品质量安全监测数据和信息，并指定机构建立国家农产品质量安全监测数据库和信息管理平台，承担全国农产品质量安全监测数据和信息的采集、整理、综合分析、结果上报等工作。 县级以上地方人民政府农业农村主管部门负责管理本行政区域内的农产品质量安全监测数据和信息。鼓励县级以上地方人民政府农业农村主管部门建立本行政区域的农产品质量安全监测数据库。"},{"i":7,"n":"第七条","txt":"县级以上人民政府农业农村主管部门应当将农产品质量安全监测工作经费列入本部门财政预算，保证监测工作的正常开展。"},{"i":8,"n":"第八条","txt":"农产品质量安全风险监测应当定期开展。根据农产品质量安全监管需要，可以随时开展专项风险监测。"},{"i":9,"n":"第九条","txt":"省级以上人民政府农业农村主管部门应当根据农产品质量安全风险监测工作的需要，制定并实施农产品质量安全风险监测网络建设规划，建立健全农产品质量安全风险监测网络。"},{"i":10,"n":"第十条","txt":"县级以上人民政府农业农村主管部门根据监测计划向承担农产品质量安全监测工作的机构下达工作任务。接受任务的机构应当根据农产品质量安全监测计划编制工作方案，并报下达监测任务的农业农村主管部门备案。 工作方案应当包括下列内容： （一）监测任务分工，明确具体承担抽样、检测、结果汇总等的机构； （二）各机构承担的具体监测内容，包括样品种类、来源、数量、检测项目等； （三）样品的封装、传递及保存条件； （四）任务下达部门指定的抽样方法、检测方法及判定依据； （五）监测完成时间及结果报送日期。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府农业农村主管部门应当根据农产品质量安全风险隐患分布及变化情况，适时调整监测品种、监测区域、监测参数和监测频率。"},{"i":12,"n":"第十二条","txt":"农产品质量安全风险监测抽样应当采取符合统计学要求的抽样方法，确保样品的代表性。"},{"i":13,"n":"第十三条","txt":"农产品质量安全风险监测应当按照公布的标准方法检测。没有标准方法的可以采用非标准方法，但应当遵循先进技术手段与成熟技术相结合的原则，并经方法学研究确认和专家组认定。"},{"i":14,"n":"第十四条","txt":"承担农产品质量安全监测任务的机构应当按要求向下达任务的农业农村主管部门报送监测数据和分析结果。"},{"i":15,"n":"第十五条","txt":"省级以上人民政府农业农村主管部门应当建立风险监测形势会商制度，对风险监测结果进行会商分析，查找问题原因，研究监管措施。"},{"i":16,"n":"第十六条","txt":"县级以上地方人民政府农业农村主管部门应当及时向上级农业农村主管部门报送监测数据和分析结果，并向同级食品安全委员会办公室、卫生行政、市场监督管理等有关部门通报。 农业农村部及时向国务院食品安全委员会办公室和卫生行政、市场监督管理等有关部门及各省、自治区、直辖市、计划单列市人民政府农业农村主管部门通报监测结果。"},{"i":17,"n":"第十七条","txt":"县级以上人民政府农业农村主管部门应当按照法定权限和程序发布农产品质量安全监测结果及相关信息。"},{"i":18,"n":"第十八条","txt":"风险监测工作的抽样程序、检测方法等符合本办法第三章规定的，监测结果可以作为执法依据。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府农业农村主管部门应当重点针对农产品质量安全风险监测结果和农产品质量安全监管中发现的突出问题，及时开展农产品质量安全监督抽查工作。"},{"i":20,"n":"第二十条","txt":"监督抽查按照抽样机构和检测机构分离的原则实施。抽样工作由当地农业农村主管部门或其执法机构负责，检测工作由农产品质量安全检测机构负责。检测机构根据需要可以协助实施抽样和样品预处理等工作。 采用快速检测方法实施监督抽查的，不受前款规定的限制。"},{"i":21,"n":"第二十一条","txt":"抽样人员在抽样前应当向被抽查人出示执法证件或工作证件。具有执法证件的抽样人员不得少于两名。 抽样人员应当准确、客观、完整地填写抽样单。抽样单应当加盖抽样单位印章，并由抽样人员和被抽查人签字或捺印；被抽查人为单位的，应当加盖被抽查人印章或者由其工作人员签字或捺印。 抽样单一式四份，分别留存抽样单位、被抽查人、检测单位和下达任务的农业农村主管部门。 抽取的样品应当经抽样人员和被抽查人签字或捺印确认后现场封样。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一的，被抽查人可以拒绝抽样： （一）具有执法证件的抽样人员少于两名的； （二）抽样人员未出示执法证件或工作证件的。"},{"i":23,"n":"第二十三条","txt":"被抽查人无正当理由拒绝抽样的，抽样人员应当告知拒绝抽样的后果和处理措施。被抽查人仍拒绝抽样的，抽样人员应当现场填写监督抽查拒检确认文书，由抽样人员和见证人共同签字，并及时向当地农业农村主管部门报告情况，对被抽查农产品以不合格论处。"},{"i":24,"n":"第二十四条","txt":"上级农业农村主管部门监督抽查的同一批次农产品，下级农业农村主管部门不得重复抽查。"},{"i":25,"n":"第二十五条","txt":"检测机构接收样品，应当检查、记录样品的外观、状态、封条有无破损及其他可能对检测结果或者综合判定产生影响的情况，并确认样品与抽样单的记录是否相符，对检测和备份样品分别加贴相应标识后入库。必要时，在不影响样品检测结果的情况下，可以对检测样品分装或者重新包装编号。"},{"i":26,"n":"第二十六条","txt":"检测机构应当按照任务下达部门指定的方法和判定依据进行检测与判定。 采用快速检测方法检测的，应当遵守相关操作规范。 检测过程中遇有样品失效或者其他情况致使检测无法进行时，检测机构应当如实记录，并出具书面证明。"},{"i":27,"n":"第二十七条","txt":"检测机构不得将监督抽查检测任务委托其他检测机构承担。"},{"i":28,"n":"第二十八条","txt":"检测机构应当将检测结果及时报送下达任务的农业农村主管部门。检测结果不合格的，应当在确认后二十四小时内将检测报告报送下达任务的农业农村主管部门和抽查地农业农村主管部门，抽查地农业农村主管部门应当及时书面通知被抽查人。"},{"i":29,"n":"第二十九条","txt":"被抽查人对检测结果有异议的，可以自收到检测结果之日起五日内，向下达任务的农业农村主管部门或者其上级农业农村主管部门书面申请复检。 采用快速检测方法进行监督抽查检测，被抽查人对检测结果有异议的，可以自收到检测结果时起四小时内书面申请复检。"},{"i":30,"n":"第三十条","txt":"复检由农业农村主管部门指定具有资质的检测机构承担。 复检不得采用快速检测方法。 复检结论与原检测结论一致的，复检费用由申请人承担；不一致的，复检费用由原检测机构承担。"},{"i":31,"n":"第三十一条","txt":"县级以上地方人民政府农业农村主管部门对抽检不合格的农产品，应当及时依法查处，或依法移交市场监督管理等有关部门查处。"},{"i":32,"n":"第三十二条","txt":"农产品质量安全监测不得向被抽查人收取费用，监测样品由抽样单位向被抽查人购买。"},{"i":33,"n":"第三十三条","txt":"参与监测工作的人员应当秉公守法、廉洁公正，不得弄虚作假、以权谋私。 被抽查人或者与其有利害关系的人员不得参与抽样、检测工作。"},{"i":34,"n":"第三十四条","txt":"抽样应当严格按照工作方案进行，不得擅自改变。 抽样人员不得事先通知被抽查人，不得接受被抽查人的馈赠，不得利用抽样之便牟取非法利益。"},{"i":35,"n":"第三十五条","txt":"检测机构应当对检测结果的真实性负责，不得瞒报、谎报、迟报检测数据和分析结果。 检测机构不得利用检测结果参与有偿活动。"},{"i":36,"n":"第三十六条","txt":"监测任务承担单位和参与监测工作的人员应当对监测工作方案和检测结果保密，未经任务下达部门同意，不得向任何单位和个人透露。"},{"i":37,"n":"第三十七条","txt":"任何单位和个人对农产品质量安全监测工作中的违法行为，有权向农业农村主管部门举报，接到举报的部门应当及时调查处理。"},{"i":38,"n":"第三十八条","txt":"对违反抽样和检测工作纪律的工作人员，由任务承担单位作出相应处理，并报上级主管部门备案。 违反监测数据保密规定的，由上级主管部门对任务承担单位的负责人通报批评，对直接责任人员依法予以处分、处罚。"},{"i":39,"n":"第三十九条","txt":"检测机构无正当理由未按时间要求上报数据结果的，由上级主管部门通报批评并责令改正；情节严重的，取消其承担检测任务的资格。 检测机构伪造检测结果或者出具检测结果不实的，依照《中华人民共和国农产品质量安全法》第四十四条规定处罚。"},{"i":40,"n":"第四十条","txt":"违反本办法规定，涉嫌犯罪的，及时将案件移送司法机关，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"本规定自2012年10月1日起施行。"}],"nongzuowubingchonghaijianceyuyubaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范农作物病虫害监测与预报工作，织牢织密监测预警网络，有效防治农作物病虫害，保障国家粮食安全和重要农产品有效供给，根据《中华人民共和国生物安全法》《中华人民共和国农业技术推广法》《农作物病虫害防治条例》等相关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上人民政府农业农村主管部门及其所属的植物保护工作机构或植物病虫害预防控制机构（以下统称“植保机构”）开展农作物病虫害监测调查、信息报送、分析预测和预报发布等监督管理和有关技术工作，适用本办法。"},{"i":3,"n":"第三条","txt":"农业农村部负责全国农作物病虫害监测与预报的监督管理工作。县级以上地方人民政府农业农村主管部门负责本行政区域农作物病虫害监测与预报的监督管理工作。 植保机构负责农作物病虫害监测与预报的有关技术工作。"},{"i":4,"n":"第四条","txt":"县级以上人民政府农业农村主管部门应当将农作物病虫害监测与预报工作经费（含监测设备运行维护费等）纳入本级部门预算。"},{"i":5,"n":"第五条","txt":"支持和鼓励科研教学单位、学术团体、企业等组织和个人开展农作物病虫害监测与预报相关技术研究和产品研发。"},{"i":6,"n":"第六条","txt":"对在农作物病虫害监测与预报工作中作出突出贡献的单位和个人，按照国家有关规定予以表彰。"},{"i":7,"n":"第七条","txt":"从事农作物病虫害监测与预报工作的专业技术人员，按照国家有关规定享受农业有毒有害保健津贴、高温补贴等相应的劳保权益。"},{"i":8,"n":"第八条","txt":"农业农村部和省级人民政府农业农村主管部门，分别编制全国和本行政区域农作物病虫害监测网络建设规划或方案，按照分级负责、共建共用、聚点成网原则，开展农作物病虫害监测网络建设。"},{"i":9,"n":"第九条","txt":"县级人民政府农业农村主管部门及其所属的植保机构，应当根据农作物种植结构和病虫害监测工作需要，原则上按照耕地面积平原地区每5万－10万亩、丘陵山区每3万－5万亩设立不少于1个田间监测点的标准，组建县级农作物病虫害监测网络，并配备必要的设施设备。 地市级人民政府农业农村主管部门及其所属的植保机构，可以根据当地农作物病虫害监测工作需要，组建地市级农作物病虫害监测网络。 省级人民政府农业农村主管部门及其所属的植保机构，根据本行政区域一、二类农作物病虫害监测工作需要，选择一定数量的县级植保机构，作为省级农作物病虫害监测重点站，组建省级农作物病虫害监测网络。 农业农村部及其所属的植保机构，根据一类农作物病虫害监测工作需要，选择一定数量的省级农作物病虫害监测重点站，作为全国农作物病虫害监测区域站，组建全国农作物病虫害监测网络。"},{"i":10,"n":"第十条","txt":"全国农作物病虫害监测区域站应当具备下列条件： （一）位于农作物病虫害发生源头区、境外病虫源早期迁入区、境内迁飞流行过渡区、常年重发区，以及粮食作物主产区或经济作物优势区； （二）具有农作物病虫害系统观测场（圃）、配备自动化可视化监测设施设备的田间监测点，配备监测调查所需交通工具； （三）具有相应专业技术人员5人以上； （四）具有完备的工作岗位责任和考核制度。 县级和地市级农作物病虫害监测网络以及省级农作物病虫害监测重点站参照前款规定进行建设。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府农业农村主管部门及其所属的植保机构，应当加强农作物病虫害观测场（圃）、监测检测仪器设备、信息化平台等基础设施和条件建设，加强对农作物病虫害监测设施设备的管理、维护和更新。强化必要的监测调查交通工具保障。"},{"i":12,"n":"第十二条","txt":"县级以上人民政府农业农村主管部门及其所属的植保机构应当建立健全农作物病虫害测报队伍，配备专业技术人员，加强技术培训，保障农作物病虫害监测工作正常开展。"},{"i":13,"n":"第十三条","txt":"从事农作物病虫害监测的专业技术人员，应当具有植物保护相关专业大专以上学历或农业专业初级以上技术职称。 乡镇农业技术推广机构承担农作物病虫害监测的人员，应当具有植物保护专业知识或相关工作背景。 县级以上人民政府农业农村主管部门及其所属的植保机构可以通过政府购买服务等方式，委托或聘用农业生产经营者等有关单位和个人，开展农作物病虫害监测。"},{"i":14,"n":"第十四条","txt":"农业农村部所属的植保机构、省级植保机构应当根据农业生产和农作物病虫害防治需要，按照服务生产、简便易行的原则，依据或参照农作物病虫害测报调查技术规范国家标准或行业标准，分别制定一类和二类农作物病虫害监测调查方法。 县级和地市级植保机构应当根据农业生产和农作物病虫害防治需要，制定三类农作物病虫害监测调查方法。 开展农作物病虫害监测，应当根据农业农村主管部门要求，并遵循依据前两款规定制定的监测调查方法。"},{"i":15,"n":"第十五条","txt":"县级和地市级植保机构应当采取田间监测点定点监测与大田定期普查相结合的方式开展监测。 全国农作物病虫害监测区域站、省级农作物病虫害监测重点站应当重点开展一类和二类农作物病虫害系统监测。"},{"i":16,"n":"第十六条","txt":"农作物病虫害监测信息实行定期报送和紧急报告制度。 全国农作物病虫害监测区域站、省级农作物病虫害监测重点站应当及时收集汇总本行政区域一类农作物病虫害监测信息，按照要求定期报送。 一类农作物病虫害发生关键时期，实行一周一报制度。省级植保机构每周收集汇总本行政区域农作物病虫害的发生和防治情况，同时报送省级人民政府农业农村主管部门和农业农村部所属的植保机构。 如遇农作物病虫害新发、突发、暴发等紧急情况，县级以上地方植保机构应当在核实情况后，在24小时内报告同级人民政府农业农村主管部门和上一级植保机构；特别严重的，直接报告农业农村部及其所属的植保机构。 二、三类农作物病虫害监测信息报告制度，由省级人民政府农业农村主管部门制定。 任何单位和个人不得瞒报、谎报农作物病虫害发生信息，不得授意他人编造虚假信息，不得阻挠他人如实报告。"},{"i":17,"n":"第十七条","txt":"全国农作物病虫害监测区域站和省级农作物病虫害监测重点站的农作物病虫害监测数据等信息，未经其主管植保机构同意，不得擅自对外提供。"},{"i":18,"n":"第十八条","txt":"县级以上植保机构应当加强农作物病虫害监测信息平台建设、运行和维护，做好监测调查数据及预报资料的采集传输、分析处理、汇总上报和保存工作，保证数据安全。"},{"i":19,"n":"第十九条","txt":"县级以上植保机构应当按照全国植保专业统计调查制度要求，做好年度农作物病虫害发生防治信息等调查统计工作。"},{"i":20,"n":"第二十条","txt":"县级以上植保机构应当建立健全农作物病虫害发生趋势会商制度，及时组织相关专家综合分析监测信息，科学研判农作物病虫害发生趋势。"},{"i":21,"n":"第二十一条","txt":"农作物病虫害预报应当包括农作物病虫害发生以及可能发生的种类、时间、范围、程度以及预防控制措施等内容，并注明发布机构、发布时间等。 农作物病虫害预报分为长期预报、中期预报、短期预报和警报。长期预报应当在距防治适期30天以上发布；中期预报应当在距防治适期10天至30天发布；短期预报应当在距防治适期5天至10天发布。农作物病虫害一旦出现突发、暴发势头，立即发布警报。"},{"i":22,"n":"第二十二条","txt":"县级以上植保机构具体负责本行政区域农作物病虫害预报发布工作。其他单位和个人不得向社会发布农作物病虫害预报；擅自向社会发布农作物病虫害预报的，依据《农作物病虫害防治条例》第四十一条处理。 农业农村部所属的植保机构重点发布全国一类农作物病虫害长期、中期预报和警报。省级植保机构重点发布本行政区域一类、二类农作物病虫害长期、中期预报和警报。县级和地市级植保机构发布本行政区域主要农作物病虫害长期、中期、短期预报和警报。"},{"i":23,"n":"第二十三条","txt":"发布农作物病虫害预报，可通过广播、报刊、电视、网站、公众号等渠道向社会公开。 任何单位和个人转载农作物病虫害预报的，应当注明发布机构和发布时间，不得更改预报的内容和结论。"},{"i":24,"n":"第二十四条","txt":"植物检疫性有害生物信息的报告与发布，依照《农业植物疫情报告与发布管理办法》（中华人民共和国农业部令2010年第4号）执行。"},{"i":25,"n":"第二十五条","txt":"本办法自2022年1月24日起施行。"}],"nongzuowuzhongzibiaoqianheshiyongshuomingguanliban043c28":[{"i":1,"n":"第一条","txt":"为了规范农作物种子标签和使用说明的管理，维护种子生产经营者、使用者的合法权益，保障种子质量和农业生产安全，根据《中华人民共和国种子法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内销售的农作物种子应当附有种子标签和使用说明。 种子标签和使用说明标注的内容应当与销售的种子相符，符合本办法的规定，不得作虚假或者引人误解的宣传。"},{"i":3,"n":"第三条","txt":"种子生产经营者负责种子标签和使用说明的制作，对其标注内容的真实性和种子质量负责。"},{"i":4,"n":"第四条","txt":"县级以上人民政府农业主管部门负责农作物种子标签和使用说明的监督管理工作。"},{"i":5,"n":"第五条","txt":"种子标签是指印制、粘贴、固定或者附着在种子、种子包装物表面的特定图案及文字说明。"},{"i":6,"n":"第六条","txt":"种子标签应当标注下列内容： （一）作物种类、种子类别、品种名称； （二）种子生产经营者信息，包括种子生产经营者名称、种子生产经营许可证编号、注册地地址和联系方式； （三）质量指标、净含量； （四）检测日期和质量保证期； （五）品种适宜种植区域、种植季节； （六）检疫证明编号； （七）信息代码。"},{"i":7,"n":"第七条","txt":"属于下列情形之一的，种子标签除标注本办法第六条规定内容外，应当分别加注以下内容： （一）主要农作物品种，标注品种审定编号；通过两个以上省级审定的，至少标注种子销售所在地省级品种审定编号；引种的主要农作物品种，标注引种备案公告文号； （二）授权品种，标注品种权号； （三）已登记的农作物品种，标注品种登记编号； （四）进口种子，标注进口审批文号及进口商名称、注册地址和联系方式； （五）药剂处理种子，标注药剂名称、有效成分、含量及人畜误食后解决方案；依据药剂毒性大小，分别注明“高毒”并附骷髅标志、“中等毒”并附十字骨标志、“低毒”字样； （六）转基因种子，标注“转基因”字样、农业转基因生物安全证书编号；"},{"i":8,"n":"第八条","txt":"作物种类明确至植物分类学的种。 种子类别按照常规种和杂交种标注。类别为常规种的按照育种家种子、原种、大田用种标注。"},{"i":9,"n":"第九条","txt":"品种名称应当符合《农业植物品种命名规定》，一个品种只能标注一个品种名称。审定、登记的品种或授权保护的品种应当使用经批准的品种名称。"},{"i":10,"n":"第十条","txt":"种子生产经营者名称、种子生产经营许可证编号、注册地地址应当与农作物种子生产经营许可证载明内容一致；联系方式为电话、传真，可以加注网络联系方式。"},{"i":11,"n":"第十一条","txt":"质量指标是指生产经营者承诺的质量标准，不得低于国家或者行业标准规定；未制定国家标准或行业标准的，按企业标准或者种子生产经营者承诺的质量标准进行标注。"},{"i":12,"n":"第十二条","txt":"质量指标按照质量特性和特性值进行标注。 质量特性按照下列规定进行标注： （一）标注品种纯度、净度、发芽率和水分，但不宜标注水分、芽率、净度等指标的无性繁殖材料、种苗等除外； （二）脱毒繁殖材料按品种纯度、病毒状况和脱毒扩繁代数进行标注； （三）国家标准、行业标准或农业部对某些农作物种子有其他质量特性要求的，应当加注。 特性值应当标明具体数值，品种纯度、净度、水分百分率保留一位小数，发芽率保留整数。"},{"i":13,"n":"第十三条","txt":"净含量是指种子的实际重量或者数量，标注内容由“净含量”字样、数字、法定计量单位（kg或者g）或者数量单位（粒或者株）三部分组成。"},{"i":14,"n":"第十四条","txt":"检测日期是指生产经营者检测质量特性值的年月，年月分别用四位、两位数字完整标示，采用下列示例：检测日期：2016年05月。 质量保证期是指在规定贮存条件下种子生产经营者对种子质量特性值予以保证的承诺时间。标注以月为单位，自检测日期起最长时间不得超过十二个月，采用下列示例：质量保证期6个月。"},{"i":15,"n":"第十五条","txt":"品种适宜种植区域不得超过审定、登记公告及省级农业主管部门引种备案公告公布的区域。审定、登记以外作物的适宜区域由生产经营者根据试验确定。 种植季节是指适宜播种的时间段，由生产经营者根据试验确定，应当具体到日，采用下列示例：5月1日至5月20日。"},{"i":16,"n":"第十六条","txt":"检疫证明编号标注产地检疫合格证编号或者植物检疫证书编号。 进口种子检疫证明编号标注引进种子、苗木检疫审批单编号。"},{"i":17,"n":"第十七条","txt":"信息代码以二维码标注，应当包括品种名称、生产经营者名称或进口商名称、单元识别代码、追溯网址等信息。二维码格式及生成要求由农业部另行制定。"},{"i":18,"n":"第十八条","txt":"使用说明是指对种子的主要性状、主要栽培措施、适应性等使用条件的说明以及风险提示、技术服务等信息。"},{"i":19,"n":"第十九条","txt":"使用说明应当包括下列内容： （一）品种主要性状； （二）主要栽培措施； （三）适应性； （四）风险提示； （五）咨询服务信息。 除前款规定内容外，有下列情形之一的，还应当增加相应内容： （一）属于转基因种子的，应当提示使用时的安全控制措施； （二）使用说明与标签分别印制的，应当包括品种名称和种子生产经营者信息。"},{"i":20,"n":"第二十条","txt":"品种主要性状、主要栽培措施应当如实反映品种的真实状况，主要内容应当与审定或登记公告一致。通过两个以上省级审定的主要农作物品种，标注内容应当与销售地所在省级品种审定公告一致；引种标注内容应当与引种备案信息一致。"},{"i":21,"n":"第二十一条","txt":"适应性是指品种在适宜种植地区内不同年度间产量的稳定性、丰产性、抗病性、抗逆性等特性，标注值不得高于品种审定、登记公告载明的内容。审定、登记以外作物适应性的说明，参照登记作物有关要求执行。"},{"i":22,"n":"第二十二条","txt":"风险提示包括种子贮藏条件以及销售区域主要病虫害、高低温、倒伏等因素对品种引发风险的提示及注意事项。"},{"i":23,"n":"第二十三条","txt":"种子标签可以与使用说明合并印制。种子标签包括使用说明全部内容的，可不另行印制使用说明。"},{"i":24,"n":"第二十四条","txt":"应当包装的种子，标签应当直接印制在种子包装物表面。可以不包装销售的种子，标签可印制成印刷品粘贴、固定或者附着在种子上，也可以制成印刷品，在销售种子时提供给种子使用者。"},{"i":25,"n":"第二十五条","txt":"标注文字除注册商标外，应当使用国家语言工作委员会公布的现行规范化汉字。标注的文字、符号、数字的字体高度不得小于1.8毫米。同时标注的汉语拼音或者外文的，字体应当小于或者等于相应的汉字字体。信息代码不得小于2平方厘米。 品种名称应放在显著位置，字号不得小于标签标注的其它文字。"},{"i":26,"n":"第二十六条","txt":"印刷内容应当清晰、醒目、持久，易于辨认和识读。标注字体、背景和底色应当与基底形成明显的反差，易于识别；警示标志和说明应当醒目，其中“高毒”以红色字体印制。"},{"i":27,"n":"第二十七条","txt":"检疫证明编号、检测日期、质量保证期，可以采用喷印、压印等印制方式。"},{"i":28,"n":"第二十八条","txt":"作物种类和种子类别、品种名称、品种审定或者登记编号、净含量、种子生产经营者名称、种子生产经营许可证编号、注册地地址和联系方式、“转基因”字样、警示标志等信息，应当在同一版面标注。"},{"i":29,"n":"第二十九条","txt":"本办法第二十四条规定的印刷品，应当为长方形，长和宽不得小于11厘米×7厘米。印刷品制作材料应当有足够的强度，确保不易损毁或字迹变得模糊、脱落。"},{"i":30,"n":"第三十条","txt":"进口种子应当在原标签外附加符合本办法规定的中文标签和使用说明，使用进（出）口审批表批准的品种中文名称和英文名称、生产经营者。"},{"i":31,"n":"第三十一条","txt":"法律、行政法规没有特别规定的，种子标签和使用说明不得有下列内容： （一）在品种名称前后添加修饰性文字； （二）种子生产经营者、进口商名称以外的其他单位名称； （三）不符合广告法、商标法等法律法规规定的描述； （四）未经认证合格使用认证标识； （五）其他带有夸大宣传、引人误解或者虚假的文字、图案等信息。"},{"i":32,"n":"第三十二条","txt":"标签缺少品种名称，视为没有种子标签。 使用说明缺少品种主要性状、适应性或风险提示的，视为没有使用说明。 以剪切、粘贴等方式修改或者补充标签内容的，按涂改标签查处。"},{"i":33,"n":"第三十三条","txt":"县级以上人民政府农业主管部门应当加强监督检查，发现种子标签和使用说明不符合本办法规定的，按照《中华人民共和国种子法》的相关规定进行处罚。"},{"i":34,"n":"第三十四条","txt":"本办法自2017年1月1日起施行。农业部2001年2月26日发布的《农作物种子标签管理办法》同时废止。"}],"nongzuowuzhongzishengchanjingyingxukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强农作物种子生产经营许可管理，规范农作物种子生产经营秩序，根据《中华人民共和国种子法》，制定本办法。"},{"i":2,"n":"第二条","txt":"农作物种子生产经营许可证的申请、审核、核发和监管，适用本办法。"},{"i":3,"n":"第三条","txt":"县级以上人民政府农业农村主管部门按照职责分工，负责农作物种子生产经营许可证的受理、审核、核发和监管工作。"},{"i":4,"n":"第四条","txt":"负责审核、核发农作物种子生产经营许可证的农业农村主管部门，应当将农作物种子生产经营许可证的办理条件、程序等在办公场所公开。"},{"i":5,"n":"第五条","txt":"农业农村主管部门应当按照保障农业生产安全、提升农作物品种选育和种子生产经营水平、促进公平竞争、强化事中事后监管的原则，依法加强农作物种子生产经营许可管理。"},{"i":6,"n":"第六条","txt":"申请领取种子生产经营许可证的企业，应当具有与种子生产经营相适应的设施、设备、品种及人员，符合本办法规定的条件。"},{"i":7,"n":"第七条","txt":"申请领取主要农作物常规种子或非主要农作物种子生产经营许可证的企业，应当具备以下条件： （一）基本设施。生产经营主要农作物常规种子的，具有办公场所150平方米以上、检验室100平方米以上、加工厂房500平方米以上、仓库500平方米以上；生产经营非主要农作物种子的，具有办公场所100平方米以上、检验室50平方米以上、加工厂房100平方米以上、仓库100平方米以上； （二）检验仪器。具有净度分析台、电子秤、样品粉碎机、烘箱、生物显微镜、电子天平、扦样器、分样器、发芽箱等检验仪器，满足种子质量常规检测需要； （三）加工设备。具有与其规模相适应的种子加工、包装等设备。其中，生产经营主要农作物常规种子的，应当具有种子加工成套设备，生产经营常规小麦种子的，成套设备总加工能力10吨/小时以上；生产经营常规稻种子的，成套设备总加工能力5吨/小时以上；生产经营常规大豆种子的，成套设备总加工能力3吨/小时以"},{"i":8,"n":"第八条","txt":"申请领取主要农作物杂交种子及其亲本种子生产经营许可证的企业，应当具备以下条件： （一）基本设施。具有办公场所200平方米以上、检验室150平方米以上、加工厂房500平方米以上、仓库500平方米以上； （二）检验仪器。除具备本办法第七条第二项规定的条件外，还应当具有PCR扩增仪及产物检测配套设备、酸度计、高压灭菌锅、磁力搅拌器、恒温水浴锅、高速冷冻离心机、成套移液器等仪器设备，能够开展种子水分、净度、纯度、发芽率四项指标检测及品种分子鉴定； （三）加工设备。具有种子加工成套设备，生产经营杂交玉米种子的，成套设备总加工能力10吨/小时以上；生产经营杂交稻种子的，成套设备总加工能力5吨/小时以上；生产经营其他主要农作物杂交种子的，成套设备总加工能力1吨/小时以上； （四）人员。具有种子生产、加工贮藏和检验专业技术人员各5名以上； （五）品种。生产经营的品种应当通过审定，并具有自育品种或作为第"},{"i":9,"n":"第九条","txt":"申请领取实行选育生产经营相结合、有效区域为全国的种子生产经营许可证的企业，应当具备以下条件: （一）基本设施。具有办公场所500平方米以上，冷藏库200平方米以上。生产经营主要农作物种子或马铃薯种薯的，具有检验室300平方米以上；生产经营其他农作物种子的，具有检验室200平方米以上。生产经营杂交玉米、杂交稻、小麦种子或马铃薯种薯的，具有加工厂房1000平方米以上、仓库2000平方米以上；生产经营棉花、大豆种子的，具有加工厂房500平方米以上、仓库500平方米以上；生产经营其他农作物种子的，具有加工厂房200平方米以上、仓库500平方米以上； （二）育种机构及测试网络。具有专门的育种机构和相应的育种材料，建有完整的科研育种档案。生产经营杂交玉米、杂交稻种子的，在全国不同生态区有测试点30个以上和相应的播种、收获、考种设施设备；生产经营其他农作物种子的，在全国不同生态区有测试点10个以上和"},{"i":10,"n":"第十条","txt":"申请领取转基因农作物种子生产经营许可证的企业，应当具备下列条件： （一）农业转基因生物安全管理人员2名以上； （二）种子生产地点、经营区域在农业转基因生物安全证书批准的区域内； （三）有符合要求的隔离和生产条件； （四）有相应的农业转基因生物安全管理、防范措施； （五）农业农村部规定的其他条件。 从事种子进出口业务、转基因农作物种子生产经营的企业和外商投资企业申请领取种子生产经营许可证，除具备本办法规定的相应农作物种子生产经营许可证核发的条件外，还应当符合有关法律、行政法规规定的其他条件。"},{"i":11,"n":"第十一条","txt":"申请领取种子生产经营许可证，应当提交以下材料： （一）种子生产经营许可证申请表（式样见附件1）； （二）单位性质、股权结构等基本情况，公司章程、营业执照复印件，设立分支机构、委托生产种子、委托代销种子以及以购销方式销售种子等情况说明； （三）种子生产、加工贮藏、检验专业技术人员和农业转基因生物安全管理人员的基本情况，企业法定代表人和高级管理人员名单及其种业从业简历； （四）种子检验室、加工厂房、仓库和其他设施的自有产权或自有资产的证明材料；办公场所自有产权证明复印件或租赁合同；种子检验、加工等设备清单和购置发票复印件；相关设施设备的情况说明及实景照片； （五）品种审定证书复印件；生产经营转基因农作物种子的，提交农业转基因生物安全证书复印件；生产经营授权品种种子的，提交植物新品种权证书复印件及品种权人的书面同意证明； （六）委托种子生产合同复印件或自行组织种子生产的情况说明和证明材料；"},{"i":12,"n":"第十二条","txt":"申请领取选育生产经营相结合、有效区域为全国的种子生产经营许可证，除提交本办法第十一条所规定的材料外，还应当提交以下材料： （一）自有科研育种基地证明或租用科研育种基地的合同复印件； （二）品种试验测试网络和测试点情况说明，以及相应的播种、收获、烘干等设备设施的自有产权证明复印件及实景照片； （三）育种机构、科研投入及育种材料、科研活动等情况说明和证明材料，育种人员基本情况及其企业缴纳的社保证明复印件； （四）近三年种子生产地点、面积和基地联系人等情况说明和证明材料； （五）种子经营量、经营额及其市场份额的情况说明和证明材料； （六）销售网络和售后服务体系的建设情况。"},{"i":13,"n":"第十三条","txt":"种子生产经营许可证实行分级审核、核发。 （一）从事主要农作物常规种子生产经营及非主要农作物种子经营的，其种子生产经营许可证由企业所在地县级以上地方农业农村主管部门核发； （二）从事主要农作物杂交种子及其亲本种子生产经营以及实行选育生产经营相结合、有效区域为全国的种子企业，其种子生产经营许可证由企业所在地县级农业农村主管部门审核，省、自治区、直辖市农业农村主管部门核发； （三）从事农作物种子进出口业务以及转基因农作物种子生产经营的，其种子生产经营许可证由农业农村部核发。"},{"i":14,"n":"第十四条","txt":"农业农村主管部门对申请人提出的种子生产经营许可申请，应当根据下列情况分别作出处理： （一）不需要取得种子生产经营许可的，应当即时告知申请人不受理； （二）不属于本部门职权范围的，应当即时作出不予受理的决定，并告知申请人向有关部门申请； （三）申请材料存在可以当场更正的错误的，应当允许申请人当场更正； （四）申请材料不齐全或者不符合法定形式的，应当当场或者在五个工作日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （五）申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正申请材料的，应当予以受理。"},{"i":15,"n":"第十五条","txt":"审核机关应当对申请人提交的材料进行审查，并对申请人的办公场所和种子加工、检验、仓储等设施设备进行实地考察，查验相关申请材料原件。 审核机关应当自受理申请之日起二十个工作日内完成审核工作。具备本办法规定条件的，签署审核意见，上报核发机关；审核不予通过的，书面通知申请人并说明理由。"},{"i":16,"n":"第十六条","txt":"核发机关应当自受理申请或收到审核意见之日起二十个工作日内完成核发工作。核发机关认为有必要的，可以进行实地考察并查验原件。符合条件的，发给种子生产经营许可证并予公告；不符合条件的，书面通知申请人并说明理由。 选育生产经营相结合、有效区域为全国的种子生产经营许可证，核发机关应当在核发前在中国种业信息网公示五个工作日。"},{"i":17,"n":"第十七条","txt":"种子生产经营许可证设主证、副证（式样见附件2）。主证注明许可证编号、企业名称、统一社会信用代码、住所、法定代表人、生产经营范围、生产经营方式、有效区域、有效期至、发证机关、发证日期；副证注明生产种子的作物种类、种子类别、品种名称及审定（登记）编号、种子生产地点等内容。 （一）许可证编号为“__（××××）农种许字（××××）第××××号”。“__”上标注生产经营类型，A为实行选育生产经营相结合，B为主要农作物杂交种子及其亲本种子，C为其他主要农作物种子，D为非主要农作物种子，E为种子进出口，F为外商投资企业，G为转基因农作物种子；第一个括号内为发证机关所在地简称，格式为“省地县”；第二个括号内为首次发证时的年号；“第××××号”为四位顺序号； （二）生产经营范围按生产经营种子的作物名称填写，蔬菜、花卉、麻类按作物类别填写； （三）生产经营方式按生产、加工、包装、批发、零售或进出口填写；"},{"i":18,"n":"第十八条","txt":"种子生产经营许可证载明的有效区域是指企业设立分支机构的区域。 种子生产地点不受种子生产经营许可证载明的有效区域限制，由发证机关根据申请人提交的种子生产合同复印件及无检疫性有害生物证明确定。 种子销售活动不受种子生产经营许可证载明的有效区域限制，但种子的终端销售地应当在品种审定、品种登记或标签标注的适宜区域内。"},{"i":19,"n":"第十九条","txt":"种子生产经营许可证有效期为五年。转基因农作物种子生产经营许可证有效期不得超出农业转基因生物安全证书规定的有效期限。 在有效期内变更主证载明事项的，应当向原发证机关申请变更并提交相应材料，原发证机关应当依法进行审查，办理变更手续。 在有效期内变更副证载明的生产种子的品种、地点等事项的，应当在播种三十日前向原发证机关申请变更并提交相应材料，申请材料齐全且符合法定形式的，原发证机关应当当场予以变更登记。 种子生产经营许可证期满后继续从事种子生产经营的，企业应当在期满六个月前重新提出申请。"},{"i":20,"n":"第二十条","txt":"在种子生产经营许可证有效期内，有下列情形之一的，发证机关应当注销许可证，并予以公告： （一）企业停止生产经营活动一年以上的； （二）企业不再具备本办法规定的许可条件，经限期整改仍达不到要求的。"},{"i":21,"n":"第二十一条","txt":"有下列情形之一的，不需要办理种子生产经营许可证： （一）农民个人自繁自用常规种子有剩余，在当地集贸市场上出售、串换的； （二）在种子生产经营许可证载明的有效区域设立分支机构的； （三）专门经营不再分装的包装种子的； （四）受具有种子生产经营许可证的企业书面委托生产、代销其种子的。 前款第一项所称农民，是指以家庭联产承包责任制的形式签订农村土地承包合同的农民；所称当地集贸市场，是指农民所在的乡（镇）区域。农民个人出售、串换的种子数量不应超过其家庭联产承包土地的年度用种量。违反本款规定出售、串换种子的，视为无证生产经营种子。"},{"i":22,"n":"第二十二条","txt":"种子生产经营者在种子生产经营许可证载明有效区域设立的分支机构，应当在取得或变更分支机构营业执照后十五个工作日内向当地县级农业农村主管部门备案。备案时应当提交分支机构的营业执照复印件、设立企业的种子生产经营许可证复印件以及分支机构名称、住所、负责人、联系方式等材料（式样见附件3）。"},{"i":23,"n":"第二十三条","txt":"专门经营不再分装的包装种子或者受具有种子生产经营许可证的企业书面委托代销其种子的，应当在种子销售前向当地县级农业农村主管部门备案，并建立种子销售台账。备案时应当提交种子销售者的营业执照复印件、种子购销凭证或委托代销合同复印件，以及种子销售者名称、住所、经营方式、负责人、联系方式、销售地点、品种名称、种子数量等材料（式样见附件4）。种子销售台账应当如实记录销售种子的品种名称、种子数量、种子来源和种子去向。"},{"i":24,"n":"第二十四条","txt":"受具有种子生产经营许可证的企业书面委托生产其种子的，应当在种子播种前向当地县级农业农村主管部门备案。受委托生产转基因农作物种子的，应当有专门的管理人员和经营档案，有相应的安全管理、防范措施及国务院农业农村主管部门规定的其他条件。备案时应当提交委托企业的种子生产经营许可证复印件、委托生产合同，以及种子生产者名称、住所、负责人、联系方式、品种名称、生产地点、生产面积等材料（式样见附件5）。受托生产杂交玉米、杂交稻种子的，还应当提交与生产所在地农户、农民合作组织或村委会的生产协议。受委托生产转基因种子的，还应当提交转基因生物安全证书复印件。"},{"i":25,"n":"第二十五条","txt":"种子生产经营者应当建立包括种子田间生产、加工包装、销售流通等环节形成的原始记载或凭证的种子生产经营档案，具体内容如下： （一）田间生产方面：技术负责人，作物类别、品种名称、亲本（原种）名称、亲本（原种）来源，生产地点、生产面积、播种日期、隔离措施、产地检疫、收获日期、种子产量等。委托种子生产的，还应当包括种子委托生产合同。 （二）加工包装方面：技术负责人，品种名称、生产地点，加工时间、加工地点、包装规格、种子批次、标签标注，入库时间、种子数量、质量检验报告等。 （三）流通销售方面：经办人，种子销售对象姓名及地址、品种名称、包装规格、销售数量、销售时间、销售票据。批量购销的，还应包括种子购销合同。 种子生产经营者应当至少保存种子生产经营档案五年，确保档案记载信息连续、完整、真实，保证可追溯。档案材料含有复印件的，应当注明复印时间并经相关责任人签章。"},{"i":26,"n":"第二十六条","txt":"种子生产经营者应当按批次保存所生产经营的种子样品，样品至少保存该类作物两个生产周期。"},{"i":27,"n":"第二十七条","txt":"申请人故意隐瞒有关情况或者提供虚假材料申请种子生产经营许可证的，农业农村主管部门应当不予许可，并将申请人的不良行为记录在案，纳入征信系统。申请人在一年内不得再次申请种子生产经营许可证。 申请人以欺骗、贿赂等不正当手段取得种子生产经营许可证的，农业农村主管部门应当撤销种子生产经营许可证，并将申请人的不良行为记录在案，纳入征信系统。申请人在三年内不得再次申请种子生产经营许可证。"},{"i":28,"n":"第二十八条","txt":"农业农村主管部门应当对种子生产经营行为进行监督检查，发现不符合本办法的违法行为，按照《中华人民共和国种子法》有关规定进行处理。 核发、撤销、吊销、注销种子生产经营许可证的有关信息，农业农村主管部门应当依法予以公布，并在中国种业信息网上及时更新信息。 对管理过程中获知的种子生产经营者的商业秘密，农业农村主管部门及其工作人员应当依法保密。"},{"i":29,"n":"第二十九条","txt":"上级农业农村主管部门应当对下级农业农村主管部门的种子生产经营许可行为进行监督检查。有下列情形的，责令改正，对直接负责的主管人员和其他直接责任人依法给予行政处分；涉嫌犯罪的，及时将案件移送司法机关，依法追究刑事责任： （一）未按核发权限发放种子生产经营许可证的； （二）擅自降低核发标准发放种子生产经营许可证的； （三）其他未依法核发种子生产经营许可证的。"},{"i":30,"n":"第三十条","txt":"本办法所称种子生产经营，是指种植、采收、干燥、清选、分级、包衣、包装、标识、贮藏、销售及进出口种子的活动；种子生产是指繁（制）种的种植、采收的田间活动。"},{"i":31,"n":"第三十一条","txt":"本办法所称种子加工成套设备，是指主机和配套系统相互匹配并固定安装在加工厂房内，实现种子精选、包衣、计量和包装基本功能的加工系统。主机主要包括风筛清选机（风选部分应具有前后吸风道，双沉降室；筛选部分应具有三层以上筛片）、比重式清选机和电脑计量包装设备；配套系统主要包括输送系统、储存系统、除尘系统、除杂系统和电控系统。"},{"i":32,"n":"第三十二条","txt":"本办法规定的科研育种、生产、加工、检验、贮藏等设施设备，应为申请企业自有产权或自有资产，或者为其绝对控股子公司的自有产权或自有资产。办公场所应在种子生产经营许可证核发机关所辖行政区域，可以租赁。对申请企业绝对控股子公司的自有品种可以视为申请企业的自有品种。申请企业的绝对控股子公司不可重复利用上述办证条件申请办理种子生产经营许可证。"},{"i":33,"n":"第三十三条","txt":"本办法所称不再分装的包装种子，是指按有关规定和标准包装的、不再分拆的最小包装种子。分装种子的，应当取得种子生产经营许可证，保证种子包装的完整性，并对其所分装种子负责。 有性繁殖作物的籽粒、果实，包括颖果、荚果、蒴果、核果等以及马铃薯微型脱毒种薯应当包装。无性繁殖的器官和组织、种苗以及不宜包装的非籽粒种子可以不包装。 种子包装应当符合有关国家标准或者行业标准。"},{"i":34,"n":"第三十四条","txt":"申请领取鲜食、爆裂玉米的种子生产经营许可证的，按非主要农作物种子的许可条件办理。"},{"i":35,"n":"第三十五条","txt":"生产经营无性繁殖的器官和组织、种苗、种薯以及不宜包装的非籽粒种子的，应当具有相适应的设施、设备、品种及人员，具体办法由省级农业农村主管部门制定，报农业农村部备案。"},{"i":36,"n":"第三十六条","txt":"没有设立农业农村主管部门的行政区域，种子生产经营许可证由上级行政区域农业农村主管部门审核、核发。"},{"i":37,"n":"第三十七条","txt":"种子生产经营许可证由农业农村部统一印制，相关表格格式由农业农村部统一制定。种子生产经营许可证的申请、受理、审核、核发和打印，以及种子生产经营备案管理，在中国种业信息网统一进行。"},{"i":38,"n":"第三十八条","txt":"本办法自2016年8月15日起施行。农业部2011年8月22日公布、2015年4月29日修订的《农作物种子生产经营许可管理办法》（农业部令2011年第3号）和2001年2月26日公布的《农作物商品种子加工包装规定》（农业部令第50号）同时废止。 本办法施行之日前已取得的农作物种子生产、经营许可证有效期不变，有效期在本办法发布之日至2016年8月15日届满的企业，其原有种子生产、经营许可证的有效期自动延展至2016年12月31日。 本办法施行之日前已取得农作物种子生产、经营许可证且在有效期内，申请变更许可证载明事项的，按本办法第十三条规定程序办理。"}],"nongzuowuzhongzizhiliangjianyanjigoukaoheguanliban87c8f9":[{"i":1,"n":"第一条","txt":"为了加强农作物种子质量检验机构（以下简称“种子检验机构”）管理，规范种子检验机构考核工作，保证检验能力，根据《中华人民共和国种子法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称考核，是指省级人民政府农业农村主管部门（以下简称“考核机关”）依据有关法律、法规、标准和技术规范的规定，对种子检验机构的检测条件、能力等资质进行考评和核准的活动。"},{"i":3,"n":"第三条","txt":"从事下列活动的种子检验机构，应当经过考核合格： （一）为行政机关作出的行政决定、司法机关作出的裁判、仲裁机构作出的仲裁裁决等出具有证明作用的数据、结果的； （二）为社会经济活动出具有证明作用的数据、结果的； （三）其他依法应当经过考核合格的。"},{"i":4,"n":"第四条","txt":"省级人民政府农业农村主管部门负责本行政区域内种子检验机构的考核、监管、技术指导等工作。 农业农村部负责制定种子检验机构考核相关标准，监督、指导考核工作。具体工作由全国农业技术推广服务中心承担。"},{"i":5,"n":"第五条","txt":"种子检验机构考核应当遵循统一规范、客观公正、科学准确、公开透明的原则，采取文件审查、现场评审和能力验证相结合的方式，实行考核要求、考核程序、证书标志、监督管理统一的制度。 种子检验机构考核的申请、受理、公示、证书打印等通过中国种业大数据平台办理。"},{"i":6,"n":"第六条","txt":"申请考核的种子检验机构应当具备下列条件： （一）依法成立并能够承担相应法律责任的法人或者其他组织； （二）具有与其从事检验活动相适应的检验技术人员和管理人员； （三）具有不少于100平方米的固定工作场所，工作环境满足检验要求； （四）具备与申请检验活动相匹配的检验设备设施； （五）具有有效运行且保证其检验活动独立、公正、科学、诚信的管理体系； （六）符合有关法律法规或者标准、技术规范规定的特殊要求。"},{"i":7,"n":"第七条","txt":"申请种子检验机构考核的，应当向考核机关提交下列材料，并对所提交材料的真实性负责： （一）申请书（按附录A格式填写）； （二）满足检验能力所需办公场所、仪器设备等说明材料； （三）检验技术人员和管理人员数量与基本情况说明材料； （四）质量管理体系文件，包括质量手册、程序文件、作业指导书等材料； （五）检验报告2份（按附录B要求制作）。"},{"i":8,"n":"第八条","txt":"办公场所、仪器说明材料包括场所面积、结构，仪器名称、数量、型号、功能等。 人员说明材料主要包括人员数量、姓名及接受教育程度和工作经历。"},{"i":9,"n":"第九条","txt":"质量手册包括以下内容： （一）种子检验机构负责人对手册发布的声明及签名； （二）公正性声明、质量方针声明； （三）种子检验机构概况、范围、术语定义、组织机构； （四）资源管理、检验实施和质量管理及其支持性程序等。"},{"i":10,"n":"第十条","txt":"程序文件是质量手册的支持性文件，包括以下内容： （一）公正性和保密程序； （二）人员培训管理程序； （三）仪器设备管理维护程序； （四）仪器设备和标准物质检定校准确认程序； （五）合同评审、外部服务和供应管理程序； （六）样品管理程序； （七）数据保护程序、检验报告和CASL（中国合格种子检验机构，China Accredited Seed Laboratory）标志使用管理程序； （八）文件控制程序； （九）记录控制和质量控制程序； （十）内部审核、申诉投诉处理、不符合工作控制、纠正和预防措施控制、管理评审等程序。"},{"i":11,"n":"第十一条","txt":"作业指导书包括扦取和制备样品的工作规范、使用仪器设备的操作规程、指导检验过程及数据处理的方法细则等。"},{"i":12,"n":"第十二条","txt":"考核机关对申请人提出的申请材料，应当根据下列情况分别作出处理： （一）申请材料不齐全或者不符合法定形式的，当场或在5个工作日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理，业务办理系统中将自动显示为受理状态； （二）申请材料存在可以更正的错误的，允许申请人即时更正； （三）申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正材料的，予以受理。"},{"i":13,"n":"第十三条","txt":"考核机关受理申请后应当组织考核，进行能力验证和现场考评。 能力验证时间由考核机关和申请人商定。能力验证合格后，考核机关应当及时组织现场考评。"},{"i":14,"n":"第十四条","txt":"能力验证采取比对试验法，应根据申请检验项目的范围设计。 能力验证的样品由考核机关组织制备，制备应按照已实施标准或规范性文件要求执行。 申请人应当在规定时间内完成项目检验，并报送检验结果。"},{"i":15,"n":"第十五条","txt":"考核机关应当建立考评专家库。 考评专家可以从全国范围内遴选，应当具备副高以上专业技术职称或四级主任科员以上职级，从事种子检验或管理工作5年以上，熟悉考核程序和技术规范。"},{"i":16,"n":"第十六条","txt":"考核机关应当从考评专家库中抽取不少于3名专家组成专家组，并指定考评组组长。 考评专家组实行组长负责制，对种子检验机构开展现场考评，制作考评报告。"},{"i":17,"n":"第十七条","txt":"现场考评应当包括以下内容： （一）质量管理体系文件、能力验证结果、检验报告的规范性和准确性； （二）办公场所、检验场所和仪器设备设施条件； （三）废弃物处理情况； （四）检验操作情况。"},{"i":18,"n":"第十八条","txt":"质量管理体系文件、检验报告应当完整、真实、有效、适宜，符合相关标准或规程。 检验报告和能力验证的结果应当准确。"},{"i":19,"n":"第十九条","txt":"办公场所应满足开展检测工作的基本需求。 检验场所应当有预防超常温度、湿度、灰尘、电磁干扰或其它超常情况发生的保护措施；有关规定对环境控制条件有要求的，应当安装适宜的设备进行监测、控制和记录。"},{"i":20,"n":"第二十条","txt":"仪器设备、电气线路和管道布局应当合理，符合安全要求。 互有影响或者互不相容的区域应当进行有效隔离。需要限制活动的区域应明确标示。"},{"i":21,"n":"第二十一条","txt":"仪器设备应当满足扦样、样品制备、检验、贮存、数据处理与分析等工作需要，有完善的管理程序和档案，重要设备由专人管理；用于检验的仪器设备，还应当达到规定的准确度和规范要求。 仪器设备档案应当包括以下内容： （一）仪器设备名称，制造商名称、型号和编号或者其他唯一性标识、放置地点； （二）接收、启用日期和验收记录； （三）制造商提供的资料或者使用说明书； （四）历次检定、校准报告和确认记录； （五）使用和维护记录； （六）仪器设备损坏、故障、改装或者修理记录。"},{"i":22,"n":"第二十二条","txt":"标准样品、标准溶液等标准物质的质量应当稳定，有安全运输、存放、使用、处置的规范程序和防止污染、损坏的措施。 危害性废弃物管理、处理应当符合国家有关规定。"},{"i":23,"n":"第二十三条","txt":"检验操作程序、数据处理应当符合有关国家标准、行业标准或规范性文件规定。"},{"i":24,"n":"第二十四条","txt":"考评专家组在现场考评中发现有不符合考评要求的，应当书面通知申请人限期整改，整改期限不得超过30个工作日。逾期未按要求整改，或整改后仍不符合要求的，相应的考评项目应当判定为不合格。"},{"i":25,"n":"第二十五条","txt":"考评专家组应当在考核结束后2个工作日内出具考核报告。考核报告经专家组成员半数以上通过并由专家组全体成员签字后生效。对考核报告有不同意见的，应当予以注明。"},{"i":26,"n":"第二十六条","txt":"考核机关应当自受理申请之日起20个工作日内完成考核，申请人整改和能力验证时间不计算在内。能力验证时间不得超过45个工作日。"},{"i":27,"n":"第二十七条","txt":"考核机关根据考核报告结论作出考核决定。对符合要求的，考核机关应当在中国种业大数据平台公示考核结果，公示时间不得少于7个工作日；经公示无异议的或异议已得到妥善处理的，考核机关应颁发种子检验机构合格证书。对不符合要求的，书面通知申请人并说明理由。"},{"i":28,"n":"第二十八条","txt":"合格证书有效期为6年。合格证书应当载明机构名称、证书编号、检验范围、有效期限、考核机关。 证书编号格式为“X中种检字XXXX第XXX号”，其中“X”为省、自治区、直辖市简称，“XXXX”为年号，“XXX”为证书序号。 检验范围应当包括检验项目、检验内容、适用范围等内容。"},{"i":29,"n":"第二十九条","txt":"考核合格的种子检验机构，由考核机关予以公告。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，种子检验机构应当向考核机关申请办理变更手续： （一）机构名称或地址发生变更的； （二）检验范围发生变化的； （三）依法需要办理变更的其他事项。 机构名称或地址发生变更的，当场办理变更手续。"},{"i":31,"n":"第三十一条","txt":"种子检验机构新增检验项目或者变更检验内容的，应当按照本办法规定申请考核。考核机关应当简化程序，对新增项目或变更检验内容所需仪器、场所及检验能力进行考核。"},{"i":32,"n":"第三十二条","txt":"合格证书有效期届满后需要继续从事本办法第三条规定活动内容的，应当在有效期届满6个月前向考核机关提出延续申请。"},{"i":33,"n":"第三十三条","txt":"种子检验机构从事本办法第三条第一项、第二项检验服务，应当在其出具的检验报告上标注CASL标志。"},{"i":34,"n":"第三十四条","txt":"省级以上农业农村主管部门根据需要对考核通过的种子检验机构进行现场检查或能力验证，种子检验机构应当予以配合，不得拒绝。"},{"i":35,"n":"第三十五条","txt":"在合格证书有效期内，种子检验机构不再从事检验范围内的种子检验服务或者自愿申请终止的，应当向考核机关申请办理合格证书注销手续。"},{"i":36,"n":"第三十六条","txt":"合格证书有效期届满，未申请延续或依法不予延续批准的，考核机关应当予以注销。"},{"i":37,"n":"第三十七条","txt":"考评专家在考核活动中，有下列情形之一的，考核机关可以根据情节轻重，作出告诫、暂停或者取消其从事考核活动的处理： （一）未按照规定的要求和时间开展考核的； （二）与所考核的种子检验机构有利害关系或者可能对公正性产生影响，未进行回避的； （三）透露工作中所知悉的国家秘密、商业秘密或者技术秘密的； （四）向所考核的种子检验机构谋取不正当利益的； （五）出具虚假或者不实的考核结论的。"},{"i":38,"n":"第三十八条","txt":"种子检验机构以欺骗、贿赂等不正当手段骗取合格证书的，由考核机关撤销其合格证书。 种子检验机构伪造测试、试验、检验数据或者出具虚假证明，情节严重的，由考核机关取消其种子检验机构合格证书。"},{"i":39,"n":"第三十九条","txt":"种子检验机构合格证书和CASL标志的格式由农业农村部统一规定（按附录C格式和附录D格式制作）。"},{"i":40,"n":"第四十条","txt":"本办法自2019年10月1日起施行。原农业部2008年1月2日发布，2013年12月31日修订的《农作物种子质量检验机构考核管理办法》和《农业部关于印发〈农作物种子质量检验机构考核准则〉等文件的通知》（农农发〔2008〕16号）同时废止。"}],"nongzuowuzhongzizhiliangjianduchouchaguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强农作物种子质量监督管理，维护种子市场秩序，规范农作物种子质量监督抽查（以下简称监督抽查）工作，根据《中华人民共和国种子法》（以下简称《种子法》）及有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称监督抽查是指由县级以上人民政府农业行政主管部门组织有关种子管理机构和种子质量检验机构对生产、销售的农作物种子进行扦样、检验，并按规定对抽查结果公布和处理的活动。"},{"i":3,"n":"第三条","txt":"农业行政主管部门负责监督抽查的组织实施和结果处理。农业行政主管部门委托的种子质量检验机构和（或）种子管理机构（以下简称承检机构）负责抽查样品的扦样工作，种子质量检验机构（以下简称检验机构）负责抽查样品的检验工作。"},{"i":4,"n":"第四条","txt":"监督抽查的样品，由被抽查企业无偿提供，扦取样品的数量不得超过检验的合理需要。"},{"i":5,"n":"第五条","txt":"被抽查企业应当积极配合监督抽查工作，无正当理由不得拒绝监督抽查。"},{"i":6,"n":"第六条","txt":"监督抽查所需费用列入农业行政主管部门的预算，不得向被抽查企业收取费用。"},{"i":7,"n":"第七条","txt":"农业行政主管部门已经实施监督抽查的企业，自扦样之日起六个月内，本级或下级农业行政主管部门对该企业的同一作物种子不得重复进行监督抽查。"},{"i":8,"n":"第八条","txt":"农业部负责制定全国监督抽查规划和本级监督抽查计划，县级以上地方人民政府农业行政主管部门根据全国规划和当地实际情况制定相应监督抽查计划。 监督抽查对象重点是当地重要农作物种子以及种子使用者、有关组织反映有质量问题的农作物种子。 农业行政主管部门可以根据实际情况，对种子质量单项或几项指标进行监督抽查。"},{"i":9,"n":"第九条","txt":"农业行政主管部门根据计划向承检机构下达监督抽查任务。承检机构根据监督抽查任务，制定抽查方案，并报农业行政主管部门审查。 抽查方案应当科学、公正、符合实际。 抽查方案应当包括扦样、检验依据、检验项目、判定依据、被抽查企业名单、经费预算、抽查时间及结果报送时间等内容。 确定被抽查企业时，应当突出重点并具有一定的代表性。"},{"i":10,"n":"第十条","txt":"农业行政主管部门审查通过抽查方案后，向承检机构开具《种子质量监督抽查通知书》。 《种子质量监督抽查通知书》是通知企业接受监督抽查的证明，应当说明被抽查企业、作物种类、扦样人员和单位等，承检机构凭此通知书到企业扦样，并交企业留存。"},{"i":11,"n":"第十一条","txt":"承检机构接受监督抽查任务后，应当组织有关人员学习有关法律法规和监督抽查规定，熟悉监督抽查方案，对扦样及检验过程中可能出现的问题提出合理的解决预案，并做好准备工作。 各有关单位和个人对监督抽查中确定的被抽查企业和作物种类以及承检机构、扦样人员等应当严格保密，禁止以任何形式和名义事先向被抽查企业泄露。"},{"i":12,"n":"第十二条","txt":"执行监督抽查任务的扦样人员由承检机构指派。到被抽查企业进行扦样时，扦样人员不得少于两名，其中至少有一名持种子检验员证的扦样员。"},{"i":13,"n":"第十三条","txt":"扦样人员扦样前，应当向被抽查企业出示《种子质量监督抽查通知书》和有效身份证件，说明监督抽查的性质和扦样方法、检验项目、检验依据、判定依据等内容；了解被抽查企业的种子生产、经营情况，必要时可要求被抽查企业出示有关档案资料，以确定所抽查品种、样品数量等事项。"},{"i":14,"n":"第十四条","txt":"抽查的样品应当从市场上销售或者仓库内待销的商品种子中扦取，并保证样品具有代表性。 有下列情形之一的，不得扦样： （一）被抽查企业无《种子质量监督抽查通知书》所列农作物种子的； （二）有证据证明拟抽查的种子不是用于销售的； （三）有证据证明生产的种子用于出口，且出口合同对其质量有明确约定的。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，被抽查企业可以拒绝接受扦样： （一）扦样人员少于两人的； （二）扦样人员中没有持证扦样员的； （三）扦样人员姓名、单位与《种子质量监督抽查通知书》不符的； （四）扦样人员应当携带的《种子质量监督抽查通知书》和有效身份证件等不齐全的； （五）被抽查企业、作物种类与《种子质量监督抽查通知书》不一致的； （六）上级或本级农业行政主管部门六个月内对该企业的同一作物种子进行过监督抽查的。"},{"i":16,"n":"第十六条","txt":"扦样按国家标准《农作物种子检验规程——扦样》执行。 扦样人员封样时，应当有防拆封措施，以保证样品的真实性。"},{"i":17,"n":"第十七条","txt":"扦样工作结束后，扦样人员应当填写扦样单。扦样单中的被抽查企业名称、通讯地址、电话，所扦作物种类、品种名称、生产年月、种子批重、种子批号，扦样日期、扦样数量、执行标准、检验项目、检验依据、结果判定依据等内容应当逐项填写清楚。被抽查企业如有需要特别陈述的事项，可在备注栏中加以说明。"},{"i":18,"n":"第十八条","txt":"扦样单应当有扦样人员和被抽查企业负责人或者其授权的人员签字，并加盖被抽查企业的公章。扦样单一式三份，承检机构和被抽查企业各留存一份，报送下达任务的农业行政主管部门一份。"},{"i":19,"n":"第十九条","txt":"被抽查企业无《种子质量监督抽查通知书》所列农作物种子的，应当出具书面证明材料。扦样人员应当在查阅有关材料和检查有关场所后予以确认，并在证明材料上签字。"},{"i":20,"n":"第二十条","txt":"被抽查企业无正当理由拒绝接受扦样或拒绝在扦样单上签字盖章的，扦样人员应当阐明拒绝监督抽查的后果和处理措施；必要时可以由企业所在地农业行政主管部门予以协调，如企业仍不接受抽查，扦样人员应当及时向下达任务的农业行政主管部门报告情况，对该企业按照拒绝监督抽查处理。"},{"i":21,"n":"第二十一条","txt":"在市场上扦取的样品，如果经销单位与标签标注的生产商不一致的，承检机构应当及时通知种子生产商，并由该企业出具书面证明材料，以确认样品的生产商。生产商在接到通知七日内不予回复的，视为所扦种子为标签标注企业的产品。"},{"i":22,"n":"第二十二条","txt":"承担监督抽查检验工作的检验机构应当符合《种子法》的有关规定，具备相应的检测条件和能力，并经省级以上人民政府农业行政主管部门考核合格。 农业部组织的监督抽查检验工作由农业部考核合格的检验机构承担。"},{"i":23,"n":"第二十三条","txt":"检验机构应当制定监督抽查样品的接收、入库、领用、检验、保存及处置程序，并严格执行。 监督抽查的样品应当妥善保存至监督抽查结果发布后三个月。"},{"i":24,"n":"第二十四条","txt":"检验机构应当按国家标准《农作物种子检验规程》进行检测，保证检验工作科学、公正、准确。 检验原始记录应当按规定如实填写，保证真实、准确、清晰，不得随意涂改，并妥善保存备查。"},{"i":25,"n":"第二十五条","txt":"检验机构依据《种子法》第四十六条的规定和相关种子技术规范的强制性要求，并根据国家标准《农作物种子检验规程》所规定的容许误差对种子质量进行判定。"},{"i":26,"n":"第二十六条","txt":"检验结束后，检验机构应当及时向被抽查企业和生产商送达《种子质量监督抽查结果通知单》。 检验机构可以在部分检验项目完成后，及时将检验结果通知被抽查企业。"},{"i":27,"n":"第二十七条","txt":"被抽查企业或者生产商对检验结果有异议的，应当在接到《种子质量监督抽查结果通知单》或者单项指标检验结果通知之日起十五日内，向下达任务的农业行政主管部门提出书面报告，并抄送检验机构。逾期未提出异议的，视为认可检验结果。"},{"i":28,"n":"第二十八条","txt":"下达任务的农业行政主管部门应当对企业提出的异议进行审查，并将处理意见告知企业。需要进行复验的，应当及时安排。"},{"i":29,"n":"第二十九条","txt":"复验一般由原检验机构承担，特殊情况下，可以由下达任务的农业行政主管部门委托其他检验机构承担。 复验结果与原检验结果不一致的，复验费用由原检验机构承担。"},{"i":30,"n":"第三十条","txt":"复验按照原抽查方案，根据实际情况可以在原样品基础上或者采用备用样品进行。 净度、发芽率和水分等质量指标采用备用样品进行复验，品种真实性和纯度在原种植小区基础上进行复查，特殊情况下，也可以重新种植鉴定。"},{"i":31,"n":"第三十一条","txt":"检验机构完成检验任务后，应当及时出具检验报告，送达被抽查企业。在市场上扦取的样品，应当同时送达生产商。 检验报告内容应当齐全，检验依据和检验项目与抽查方案一致，数据准确，结论明确。"},{"i":32,"n":"第三十二条","txt":"承检机构完成抽查任务后，应当在规定时间内将监督抽查结果报送下达任务的农业行政主管部门。"},{"i":33,"n":"第三十三条","txt":"监督抽查结果主要包括以下内容： （一）监督抽查总结； （二）检验结果汇总表； （三）监督抽查质量较好企业名单、不合格种子生产经营企业名单、拒绝接受监督抽查企业名单； （四）企业提出异议、复验等问题的处理情况说明； （五）其他需要说明的情况。"},{"i":34,"n":"第三十四条","txt":"下达任务的农业行政主管部门应当及时汇总结果，在农业系统或者向相关企业通报，并视情况通报被抽查企业所在地农业行政主管部门。 省级以上农业行政主管部门可以向社会公告监督抽查结果。"},{"i":35,"n":"第三十五条","txt":"不合格种子生产经营企业，由下达任务的农业行政主管部门或企业所在地农业行政主管部门，依据《种子法》有关规定予以处罚。 对不合格种子生产经营企业，应当作为下次监督抽查的重点。连续两次监督抽查有不合格种子的企业，应当提请有关发证机关吊销该企业的种子生产许可证、种子经营许可证，并向社会公布。"},{"i":36,"n":"第三十六条","txt":"不合格种子生产经营企业应当按照下列要求进行整改： （一）限期追回已经销售的不合格种子； （二）立即对不合格批次种子进行封存，作非种用处理或者重新加工，经检验合格后方可销售； （三）企业法定代表人向全体职工通报监督抽查情况，制定整改方案，落实整改措施； （四）查明产生不合格种子的原因，查清质量责任，对有关责任人进行处理； （五）对未抽查批次的种子进行全面清理，不合格种子不得销售； （六）健全和完善质量保证体系，并按期提交整改报告； （七）接受农业行政主管部门组织的整改复查。"},{"i":37,"n":"第三十七条","txt":"拒绝接受依法监督抽查的，给予警告，责令改正；拒不改正的，被监督抽查的种子按不合格种子处理，下达任务的农业行政主管部门予以通报。"},{"i":38,"n":"第三十八条","txt":"参与监督抽查的工作人员，应当严格遵守国家法律、法规，秉公执法、不徇私情，对被抽查的作物种类和企业名单严守秘密。"},{"i":39,"n":"第三十九条","txt":"检验机构应当如实上报检验结果和检验结论，不得瞒报、谎报，并对检验工作负责。 检验机构在承担监督抽查任务期间，不得接受被抽查企业种子样品的委托检验。"},{"i":40,"n":"第四十条","txt":"承检机构应当符合《种子法》第五十六条的规定，不得从事种子生产、经营活动。 承检机构不得利用种子质量监督抽查结果参与有偿活动，不得泄露抽查结果及有关材料，不得向企业颁发抽查合格证书。"},{"i":41,"n":"第四十一条","txt":"检验机构和参与监督抽查的工作人员伪造、涂改检验数据，出具虚假检验结果和结论的，按照《种子法》第六十二条、第六十八条的规定处理。"},{"i":42,"n":"第四十二条","txt":"检验机构和参与监督抽查的工作人员违反本办法第三十八条、第三十九条第二款、第四十条规定，由农业行政主管部门责令限期改正，暂停其种子质量检验工作；情节严重的，收回有关证书和证件，取消从事种子质量检验资格；对有关责任人员依法给予行政处分，构成犯罪的，依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"本办法自2005年5月1日起实施。"}],"nongzuowuzhongzizhiliangjiufentianjianxianchangjia33b6c1":[{"i":1,"n":"第一条","txt":"为了规范农作物种子质量纠纷田间现场鉴定（以下简称现场鉴定）程序和方法，合理解决农作物种子质量纠纷，维护种子使用者和经营者的合法权益，根据《中华人民共和国种子法》（以下简称《种子法》）及有关法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法称现场鉴定是指农作物种子在大田种植后，因种子质量或者栽培、气候等原因，导致田间出苗、植株生长、作物产量、产品品质等受到影响，双方当事人对造成事故的原因或损失程度存在分歧，为确定事故原因或（和）损失程度而进行的田间现场技术鉴定活动。"},{"i":3,"n":"第三条","txt":"现场鉴定由田间现场所在地县级以上地方人民政府农业行政主管部门所属的种子管理机构组织实施。"},{"i":4,"n":"第四条","txt":"种子质量纠纷处理机构根据需要可以申请现场鉴定；种子质量纠纷当事人可以共同申请现场鉴定，也可以单独申请现场鉴定。 鉴定申请一般以书面形式提出，说明鉴定的内容和理由，并提供相关材料。口头提出鉴定申请的，种子管理机构应当制作笔录，并请申请人签字确认。"},{"i":5,"n":"第五条","txt":"种子管理机构对申请人的申请进行审查，符合条件的，应当及时组织鉴定。有下列情形之一的，种子管理机构对现场鉴定申请不予受理： （一）针对所反映的质量问题，申请人提出鉴定申请时，需鉴定地块的作物生长期已错过该作物典型性状表现期，从技术上已无法鉴别所涉及质量纠纷起因的； （二）司法机构、仲裁机构、行政主管部门已对质量纠纷做出生效判决和处理决定的； （三）受当前技术水平的限制，无法通过田间现场鉴定的方式来判定所提及质量问题起因的； （四）纠纷涉及的种子没有质量判定标准、规定或合同约定要求的； （五）有确凿的理由判定纠纷不是由种子质量所引起的； （六）不按规定缴纳鉴定费的。"},{"i":6,"n":"第六条","txt":"现场鉴定由种子管理机构组织专家鉴定组进行。 专家鉴定组由鉴定所涉及作物的育种、栽培、种子管理等方面的专家组成，必要时可邀请植物保护、气象、土壤肥料等方面的专家参加。专家鉴定组名单应当征求申请人和当事人的意见，可以不受行政区域的限制。 参加鉴定的专家应当具有高级专业技术职称、具有相应的专门知识和实际工作经验、从事相关专业领域的工作五年以上。 纠纷所涉品种的选育人为鉴定组成员的，其资格不受前款条件的限制。"},{"i":7,"n":"第七条","txt":"专家鉴定组人数应为3人以上的单数，由一名组长和若干成员组成。"},{"i":8,"n":"第八条","txt":"专家鉴定组成员有下列情形之一的，应当回避，申请人也可以口头或者书面申请其回避： （一）是种子质量纠纷当事人或者当事人的近亲属的； （二）与种子质量纠纷有利害关系的； （三）与种子质量纠纷当事人有其他关系，可能影响公正鉴定的。"},{"i":9,"n":"第九条","txt":"专家鉴定组进行现场鉴定时，可以向当事人了解有关情况，可以要求申请人提供与现场鉴定有关的材料。 申请人及当事人应予以必要的配合，并提供真实资料和证明。不配合或者提供虚假资料和证明，对鉴定工作造成影响的，应承担由此造成的相应后果。"},{"i":10,"n":"第十条","txt":"专家鉴定组进行现场鉴定时，应当通知申请人及有关当事人到场。专家鉴定组根据现场情况确定取样方法和鉴定步骤，并独立进行现场鉴定。 任何单位或者个人不得干扰现场鉴定工作，不得威胁、利诱、辱骂、殴打专家鉴定组成员。 专家鉴定组成员不得接受当事人的财物或者其他利益。"},{"i":11,"n":"第十一条","txt":"有下列情况之一的，终止现场鉴定： （一）申请人不到场的； （二）需鉴定的地块已不具备鉴定条件的； （三）因人为因素使鉴定无法开展的。"},{"i":12,"n":"第十二条","txt":"专家鉴定组对鉴定地块中种植作物的生长情况进行鉴定时，应当充分考虑以下因素： （一）作物生长期间的气候环境状况； （二）当事人对种子处理及田间管理情况； （三）该批种子室内鉴定结果； （四）同批次种子在其他地块生长情况； （五）同品种其他批次种子生长情况； （六）同类作物其他品种种子生长情况； （七）鉴定地块地力水平； （八）影响作物生长的其他因素。"},{"i":13,"n":"第十三条","txt":"专家鉴定组应当在事实清楚、证据确凿的基础上，根据有关种子法规、标准，依据相关的专业知识，本着科学、公正、公平的原则，及时作出鉴定结论。 专家鉴定组现场鉴定实行合议制。鉴定结论以专家鉴定组成员半数以上通过有效。专家鉴定组成员在鉴定结论上签名。专家鉴定组成员对鉴定结论的不同意见，应当予以注明。"},{"i":14,"n":"第十四条","txt":"专家鉴定组应当制作现场鉴定书。现场鉴定书应当包括以下主要内容： （一）鉴定申请人名称、地址、受理鉴定日期等基本情况； （二）鉴定的目的、要求； （三）有关的调查材料； （四）对鉴定方法、依据、过程的说明； （五）鉴定结论； （六）鉴定组成员名单； （七）其他需要说明的问题。"},{"i":15,"n":"第十五条","txt":"现场鉴定书制作完成后，专家鉴定组应当及时交给组织鉴定的种子管理机构。种子管理机构应当在5日内将现场鉴定书交付申请人。"},{"i":16,"n":"第十六条","txt":"对现场鉴定书有异议的，应当在收到现场鉴定书15日内向原受理单位上一级种子管理机构提出再次鉴定申请，并说明理由。上一级种子管理机构对原鉴定的依据、方法、过程等进行审查，认为有必要和可能重新鉴定的，应当按本办法规定重新组织专家鉴定。 再次鉴定申请只能提起一次。 当事人双方共同提出鉴定申请的，再次鉴定申请由双方共同提出。当事人一方单独提出鉴定申请的，另一方当事人不得提出再次鉴定申请。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，现场鉴定无效： （一）专家鉴定组组成不符合本办法规定的； （二）专家鉴定组成员收受当事人财物或者其他利益，弄虚作假的； （三）其他违反鉴定程序，可能影响现场鉴定客观、公正的。 现场鉴定无效的，应当重新组织鉴定。"},{"i":18,"n":"第十八条","txt":"申请现场鉴定，应当按照省级有关主管部门的规定缴纳鉴定费。"},{"i":19,"n":"第十九条","txt":"参加现场鉴定工作的人员违反本办法的规定，接受鉴定申请人或者当事人的财物或者其他利益，出具虚假现场鉴定书的，由其所在单位或者主管部门给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"申请人、有关当事人或者其他人员干扰田间现场鉴定工作，寻衅滋事，扰乱现场鉴定工作正常进行的，依法给予治安管理处罚或者追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"委托制种发生质量纠纷，需要进行现场鉴定的，参照本办法执行。"},{"i":22,"n":"第二十二条","txt":"本办法自2003年8月1日起施行。"}],"nongzuowuzhongzhiziyuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强农作物种质资源的保护，促进农作物种质资源的交流和利用，根据《中华人民共和国种子法》的规定,制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事农作物种质资源收集、整理、鉴定、登记、保存、交流、利用和管理等活动，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称农作物种质资源，是指选育农作物新品种的基础材料，包括农作物的栽培种、野生种和濒危稀有种的繁殖材料，以及利用上述繁殖材料人工创造的各种遗传材料，其形态包括果实、籽粒、苗、根、茎、叶、芽、花、组织、细胞和DNA、DNA片段及基因等有生命的物质材料。"},{"i":4,"n":"第四条","txt":"农业部设立国家农作物种质资源委员会，研究提出国家农作物种质资源发展战略和方针政策，协调全国农作物种质资源的管理工作。委员会办公室设在农业部种植业管理司，负责委员会的日常工作。 各省、自治区、直辖市农业行政主管部门可根据需要，确定相应的农作物种质资源管理单位。"},{"i":5,"n":"第五条","txt":"农作物种质资源工作属于公益性事业，国家及地方政府有关部门应当采取措施，保障农作物种质资源工作的稳定和经费来源。"},{"i":6,"n":"第六条","txt":"国家对在农作物种质资源收集、整理、鉴定、登记、保存、交流、引进、利用和管理过程中成绩显著的单位和个人，给予表彰和奖励。"},{"i":7,"n":"第七条","txt":"国家有计划地组织农作物种质资源普查、重点考察和收集工作。因工程建设、环境变化等情况可能造成农作物种质资源灭绝的，应当及时组织抢救收集。"},{"i":8,"n":"第八条","txt":"禁止采集或者采伐列入国家重点保护野生植物名录的野生种、野生近缘种、濒危稀有种和保护区、保护地、种质圃内的农作物种质资源。 因科研等特殊情况需要采集或者采伐列入国家重点保护野生植物名录的野生种、野生近缘种、濒危稀有种种质资源的，应当按照国务院及农业部有关野生植物管理的规定，办理审批手续；需要采集或者采伐保护区、保护地、种质圃内种质资源的，应当经建立该保护区、保护地、种质圃的农业行政主管部门批准。"},{"i":9,"n":"第九条","txt":"农作物种质资源的采集数量应当以不影响原始居群的遗传完整性及其正常生长为标准。"},{"i":10,"n":"第十条","txt":"未经批准，境外人员不得在中国境内采集农作物种质资源。中外科学家联合考察我国农作物种质资源的，应当提前6个月报经农业部批准。 采集的农作物种质资源需要带出境外的，应当按照本办法的规定办理对外提供农作物种质资源审批手续。"},{"i":11,"n":"第十一条","txt":"收集种质资源应当建立原始档案，详细记载材料名称、基本特征特性、采集地点和时间、采集数量、采集人等。"},{"i":12,"n":"第十二条","txt":"收集的所有农作物种质资源及其原始档案应当送交国家种质库登记保存。"},{"i":13,"n":"第十三条","txt":"申请品种审定的单位和个人，应当将适量繁殖材料（包括杂交亲本繁殖材料）交国家种质库登记保存。"},{"i":14,"n":"第十四条","txt":"单位和个人持有国家尚未登记保存的种质资源的，有义务送交国家种质库登记保存。 当事人可以将种质资源送交当地农业行政主管部门或者农业科研机构，地方农业行政主管部门或者农业科研机构应当及时将收到的种质资源送交国家种质库登记保存。"},{"i":15,"n":"第十五条","txt":"对收集的所有农作物种质资源应当进行植物学类别和主要农艺性状鉴定。 农作物种质资源的鉴定实行国家统一标准制度，具体标准由农业部根据国家农作物种质资源委员会的建议制定和公布。 农作物种质资源的登记实行统一编号制度，任何单位和个人不得更改国家统一编号和名称。"},{"i":16,"n":"第十六条","txt":"农作物种质资源保存实行原生境保存和非原生境保存相结合的制度。原生境保存包括建立农作物种质资源保护区和保护地，非原生境保存包括建立各种类型的种质库、种质圃及试管苗库。"},{"i":17,"n":"第十七条","txt":"农业部在农业植物多样性中心、重要农作物野生种及野生近缘植物原生地以及其他农业野生资源富集区，建立农作物种质资源保护区或者保护地。"},{"i":18,"n":"第十八条","txt":"农业部建立国家农作物种质库，包括长期种质库及其复份库、中期种质库、种质圃及试管苗库。 长期种质库负责全国农作物种质资源的长期保存；复份库负责长期种质库贮存种质的备份保存；中期种质库负责种质的中期保存、特性鉴定、繁殖和分发；种质圃及试管苗库负责无性繁殖作物及多年生作物种质的保存、特性鉴定、繁殖和分发。 国家和地方有关部门应当采取措施，保障国家种质库的正常运转和种质资源安全。"},{"i":19,"n":"第十九条","txt":"各省、自治区、直辖市农业行政主管部门根据需要建立本地区的农作物种质资源保护区、保护地、种质圃和中期种质库。"},{"i":20,"n":"第二十条","txt":"国家鼓励单位和个人从事农作物种质资源研究和创新。"},{"i":21,"n":"第二十一条","txt":"国家长期种质库保存的种质资源属国家战略资源，未经农业部批准，任何单位和个人不得动用。 因国家中期种质库保存的种质资源绝种，需要从国家长期种质库取种繁殖的，应当报农业部审批。 国家长期种质库应当定期检测库存种质资源，当库存种质资源活力降低或数量减少影响种质资源安全时，应当及时繁殖补充。"},{"i":22,"n":"第二十二条","txt":"国家中期种质库应当定期繁殖更新库存种质资源，保证库存种质资源活力和数量；国家种质圃应当定期更新复壮圃存种质资源，保证圃存种质资源的生长势。国家有关部门应保障其繁殖更新费用。"},{"i":23,"n":"第二十三条","txt":"农业部根据国家农作物种质资源委员会的建议，定期公布可供利用的农作物种质资源目录，并评选推荐优异种质资源。 因科研和育种需要目录中农作物种质资源的单位和个人，可以向国家中期种质库、种质圃提出申请。对符合国家中期种质库、种质圃提供种质资源条件的，国家中期种质库、种质圃应当迅速、免费向申请者提供适量种质材料。如需收费，不得超过繁种等所需的最低费用。"},{"i":24,"n":"第二十四条","txt":"从国家获取的种质资源不得直接申请新品种保护及其他知识产权。"},{"i":25,"n":"第二十五条","txt":"从国家中期种质库、种质圃获取种质资源的单位和个人应当及时向国家中期种质库、种质圃反馈种质资源利用信息，对不反馈信息者，国家中期种质库、种质圃有权不再向其提供种质资源。 国家中期种质库、种质圃应当定期向国家农作物种质资源委员会办公室上报种质资源发放和利用情况。"},{"i":26,"n":"第二十六条","txt":"各省、自治区、直辖市农业行政主管部门可以根据本办法和本地区实际情况，制定本地区的农作物种质资源发放和利用办法。"},{"i":27,"n":"第二十七条","txt":"国家对农作物种质资源享有主权，任何单位和个人向境外提供种质资源，应当经所在地省、自治区、直辖市农业行政主管部门审核，报农业部审批。"},{"i":28,"n":"第二十八条","txt":"对外提供农作物种质资源实行分类管理制度，农业部定期修订分类管理目录。"},{"i":29,"n":"第二十九条","txt":"对外提供农作物种质资源按以下程序办理： （一）对外提供种质资源的单位和个人按规定的格式及要求填写《对外提供农作物种质资源申请表》（见附件一），提交对外提供种质资源说明，向农业部提出申请。 （二）农业部应当在收到审核意见之日起20日内作出审批决定。审批通过的，开具《对外提供农作物种质资源准许证》（见附件二），加盖“农业部对外提供农作物种质资源审批专用章”。 （三）对外提供种质资源的单位和个人持《对外提供农作物种质资源准许证》到检疫机关办理检疫审批手续。 （四）《对外提供农作物种质资源准许证》和检疫通关证明作为海关放行依据。"},{"i":30,"n":"第三十条","txt":"对外合作项目中包括农作物种质资源交流的，应当在签订合作协议前，办理对外提供农作物种质资源审批手续。"},{"i":31,"n":"第三十一条","txt":"国家鼓励单位和个人从境外引进农作物种质资源。"},{"i":32,"n":"第三十二条","txt":"从境外引进新物种的，应当进行科学论证，采取有效措施，防止可能造成的生态危害和环境危害。引进前，报经农业部批准，引进后隔离种植1个以上生育周期，经评估，证明确实安全和有利用价值的，方可分散种植。"},{"i":33,"n":"第三十三条","txt":"单位和个人从境外引进种质资源，应当依照有关植物检疫法律、行政法规的规定，办理植物检疫手续。引进的种质资源，应当隔离试种，经植物检疫机构检疫，证明确实不带危险性病、虫及杂草的，方可分散种植。"},{"i":34,"n":"第三十四条","txt":"国家实行引种统一登记制度。引种单位和个人应当在引进种质资源入境之日起一年之内向国家农作物种质资源委员会办公室申报备案，并附适量种质材料供国家种质库保存。 当事人可以将引种信息和种质资源送交当地农业行政主管部门或者农业科研机构，地方农业行政主管部门或者农业科研机构应当及时向国家农作物种质资源委员会办公室申报备案，并将收到的种质资源送交国家种质库保存。"},{"i":35,"n":"第三十五条","txt":"引进的种质资源，由国家农作物种质资源委员会统一编号和译名，任何单位和个人不得更改国家引种编号和译名。"},{"i":36,"n":"第三十六条","txt":"国家农作物种质资源委员会办公室应当加强农作物种质资源的信息管理工作，包括种质资源收集、鉴定、保存、利用、国际交流等动态信息，为有关部门提供信息服务，保护国家种质资源信息安全。"},{"i":37,"n":"第三十七条","txt":"负责农作物种质资源收集、鉴定、保存、登记等工作的单位，有义务向国家农作物种质资源委员会办公室提供相关信息，保障种质资源信息共享。"},{"i":38,"n":"第三十八条","txt":"违反本办法规定，未经批准私自采集或者采伐国家重点保护的天然种质资源的，按照《种子法》第八十一条的规定予以处罚。"},{"i":39,"n":"第三十九条","txt":"违反本办法规定，未经批准动用国家长期种质库贮存的种质资源的，对直接负责的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":40,"n":"第四十条","txt":"违反本办法规定，未经批准向境外提供或者从境外引进种质资源的，按照《种子法》第八十二条的规定予以处罚。"},{"i":41,"n":"第四十一条","txt":"违反本办法规定，农业行政主管部门或者农业科研机构未及时将收到的单位或者个人送交的国家未登记的种质资源及境外引种种质资源送交国家种质库保存的，或者引进境外种质资源未申报备案的，由本单位或者上级主管部门责令改正，对直接负责的主管人员和其他直接责任人员，可以依法给予行政处分。"},{"i":42,"n":"第四十二条","txt":"中外科学家联合考察的农作物种质资源，对外提供的农作物种质资源，以及从境外引进的农作物种质资源，属于列入国家重点保护野生植物名录的野生种、野生近缘种、濒危稀有种的，除按本办法办理审批手续外，还应按照《野生植物保护条例》、《农业野生植物保护办法》的规定，办理相关审批手续。"},{"i":43,"n":"第四十三条","txt":"本办法自2003年10月1日起施行。1997年3月28日农业部发布的《进出口农作物种子（苗）管理暂行办法》有关种质资源进出口管理的内容同时废止。"}],"nongcuntudichengbaohetongguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范农村土地承包合同的管理，维护承包合同当事人的合法权益，维护农村社会和谐稳定，根据《中华人民共和国农村土地承包法》等法律及有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"农村土地承包经营应当巩固和完善以家庭承包经营为基础、统分结合的双层经营体制，保持农村土地承包关系稳定并长久不变。农村土地承包经营，不得改变土地的所有权性质。"},{"i":3,"n":"第三条","txt":"农村土地承包经营应当依法签订承包合同。土地承包经营权自承包合同生效时设立。 承包合同订立、变更和终止的，应当开展土地承包经营权调查。"},{"i":4,"n":"第四条","txt":"农村土地承包合同管理应当遵守法律、法规，保护土地资源的合理开发和可持续利用，依法落实耕地利用优先序。发包方和承包方应当依法履行保护农村土地的义务。"},{"i":5,"n":"第五条","txt":"农村土地承包合同管理应当充分维护农民的财产权益，任何组织和个人不得剥夺和非法限制农村集体经济组织成员承包土地的权利。妇女与男子享有平等的承包农村土地的权利。 承包方承包土地后，享有土地承包经营权，可以自己经营，也可以保留土地承包权，流转其承包地的土地经营权，由他人经营。"},{"i":6,"n":"第六条","txt":"农业农村部负责全国农村土地承包合同管理的指导。 县级以上地方人民政府农业农村主管（农村经营管理）部门负责本行政区域内农村土地承包合同管理。 乡（镇）人民政府负责本行政区域内农村土地承包合同管理。"},{"i":7,"n":"第七条","txt":"本集体经济组织成员的村民会议依法选举产生的承包工作小组，应当依照法律、法规的规定拟订承包方案，并在本集体经济组织范围内公示不少于十五日。 承包方案应当依法经本集体经济组织成员的村民会议三分之二以上成员或者三分之二以上村民代表的同意。 承包方案由承包工作小组公开组织实施。"},{"i":8,"n":"第八条","txt":"承包方案应当符合下列要求： （一）内容合法； （二）程序规范； （三）保障农村集体经济组织成员合法权益； （四）不得违法收回、调整承包地； （五）法律、法规和规章规定的其他要求。"},{"i":9,"n":"第九条","txt":"县级以上地方人民政府农业农村主管（农村经营管理）部门、乡（镇）人民政府农村土地承包管理部门应当指导制定承包方案，并对承包方案的实施进行监督，发现问题的，应当及时予以纠正。"},{"i":10,"n":"第十条","txt":"承包合同应当符合下列要求： （一）文本规范； （二）内容合法； （三）双方当事人签名、盖章或者按指印； （四）法律、法规和规章规定的其他要求。 县级以上地方人民政府农业农村主管（农村经营管理）部门、乡（镇）人民政府农村土地承包管理部门应当依法指导发包方和承包方订立、变更或者终止承包合同，并对承包合同实施监督，发现不符合前款要求的，应当及时通知发包方更正。"},{"i":11,"n":"第十一条","txt":"发包方和承包方应当采取书面形式签订承包合同。 承包合同一般包括以下条款： （一）发包方、承包方的名称，发包方负责人和承包方代表的姓名、住所； （二）承包土地的名称、坐落、面积、质量等级； （三）承包方家庭成员信息； （四）承包期限和起止日期； （五）承包土地的用途； （六）发包方和承包方的权利和义务； （七）违约责任。 承包合同示范文本由农业农村部制定。"},{"i":12,"n":"第十二条","txt":"承包合同自双方当事人签名、盖章或者按指印时成立。"},{"i":13,"n":"第十三条","txt":"承包期内，出现下列情形之一的，承包合同变更： （一）承包方依法分立或者合并的； （二）发包方依法调整承包地的； （三）承包方自愿交回部分承包地的； （四）土地承包经营权互换的； （五）土地承包经营权部分转让的； （六）承包地被部分征收的； （七）法律、法规和规章规定的其他情形。 承包合同变更的，变更后的承包期限不得超过承包期的剩余期限。"},{"i":14,"n":"第十四条","txt":"承包期内，出现下列情形之一的，承包合同终止： （一）承包方消亡的； （二）承包方自愿交回全部承包地的； （三）土地承包经营权全部转让的； （四）承包地被全部征收的； （五）法律、法规和规章规定的其他情形。"},{"i":15,"n":"第十五条","txt":"承包地被征收、发包方依法调整承包地或者承包方消亡的，发包方应当变更或者终止承包合同。 除前款规定的情形外，承包合同变更、终止的，承包方向发包方提出申请，并提交以下材料： （一）变更、终止承包合同的书面申请； （二）原承包合同； （三）承包方分立或者合并的协议，交回承包地的书面通知或者协议，土地承包经营权互换合同、转让合同等其他相关证明材料； （四）具有土地承包经营权的全部家庭成员同意变更、终止承包合同的书面材料； （五）法律、法规和规章规定的其他材料。"},{"i":16,"n":"第十六条","txt":"省级人民政府农业农村主管部门可以根据本行政区域实际依法制定承包方分立、合并、消亡而导致承包合同变更、终止的具体规定。"},{"i":17,"n":"第十七条","txt":"承包期内，因自然灾害严重毁损承包地等特殊情形对个别农户之间承包地需要适当调整的，发包方应当制定承包地调整方案，并应当经本集体经济组织成员的村民会议三分之二以上成员或者三分之二以上村民代表的同意。承包合同中约定不得调整的，按照其约定。 调整方案通过之日起二十个工作日内，发包方应当将调整方案报乡（镇）人民政府和县级人民政府农业农村主管（农村经营管理）部门批准。 乡（镇）人民政府应当于二十个工作日内完成调整方案的审批，并报县级人民政府农业农村主管（农村经营管理）部门；县级人民政府农业农村主管（农村经营管理）部门应当于二十个工作日内完成调整方案的审批。乡（镇）人民政府、县级人民政府农业农村主管（农村经营管理）部门对违反法律、法规和规章规定的调整方案，应当及时通知发包方予以更正，并重新申请批准。 调整方案未经乡（镇）人民政府和县级人民政府农业农村主管（农村经营管理）部门批准的，发包方不得调整承包"},{"i":18,"n":"第十八条","txt":"承包方自愿将部分或者全部承包地交回发包方的，承包方与发包方在该土地上的承包关系终止，承包期内其土地承包经营权部分或者全部消灭，并不得再要求承包土地。 承包方自愿交回承包地的，应当提前半年以书面形式通知发包方。承包方对其在承包地上投入而提高土地生产能力的，有权获得相应的补偿。交回承包地的其他补偿，由发包方和承包方协商确定。"},{"i":19,"n":"第十九条","txt":"为了方便耕种或者各自需要，承包方之间可以互换属于同一集体经济组织的不同承包地块的土地承包经营权。 土地承包经营权互换的，应当签订书面合同，并向发包方备案。 承包方提交备案的互换合同，应当符合下列要求： （一）互换双方是属于同一集体经济组织的农户； （二）互换后的承包期限不超过承包期的剩余期限； （三）法律、法规和规章规定的其他事项。 互换合同备案后，互换双方应当与发包方变更承包合同。"},{"i":20,"n":"第二十条","txt":"经承包方申请和发包方同意，承包方可以将部分或者全部土地承包经营权转让给本集体经济组织的其他农户。 承包方转让土地承包经营权的，应当以书面形式向发包方提交申请。发包方同意转让的，承包方与受让方应当签订书面合同；发包方不同意转让的，应当于七日内向承包方书面说明理由。发包方无法定理由的，不得拒绝同意承包方的转让申请。未经发包方同意的，土地承包经营权转让合同无效。 土地承包经营权转让合同，应当符合下列要求： （一）受让方是本集体经济组织的农户； （二）转让后的承包期限不超过承包期的剩余期限； （三）法律、法规和规章规定的其他事项。 土地承包经营权转让后，受让方应当与发包方签订承包合同。原承包方与发包方在该土地上的承包关系终止，承包期内其土地承包经营权部分或者全部消灭，并不得再要求承包土地。"},{"i":21,"n":"第二十一条","txt":"承包合同管理工作中形成的，对国家、社会和个人有保存价值的文字、图表、声像、数据等各种形式和载体的材料，应当纳入农村土地承包档案管理。 县级以上地方人民政府农业农村主管（农村经营管理）部门、乡（镇）人民政府农村土地承包管理部门应当制定工作方案、健全档案工作管理制度、落实专项经费、指定工作人员、配备必要设施设备，确保农村土地承包档案完整与安全。 发包方应当将农村土地承包档案纳入村级档案管理。"},{"i":22,"n":"第二十二条","txt":"承包合同管理工作中产生、使用和保管的数据，包括承包地权属数据、地理信息数据和其他相关数据等，应当纳入农村土地承包数据管理。 县级以上地方人民政府农业农村主管（农村经营管理）部门负责本行政区域内农村土地承包数据的管理，组织开展数据采集、使用、更新、保管和保密等工作，并向上级业务主管部门提交数据。 鼓励县级以上地方人民政府农业农村主管（农村经营管理）部门通过数据交换接口、数据抄送等方式与相关部门和机构实现承包合同数据互通共享，并明确使用、保管和保密责任。"},{"i":23,"n":"第二十三条","txt":"县级以上地方人民政府农业农村主管（农村经营管理）部门应当加强农村土地承包合同管理信息化建设，按照统一标准和技术规范建立国家、省、市、县等互联互通的农村土地承包信息应用平台。"},{"i":24,"n":"第二十四条","txt":"县级以上地方人民政府农业农村主管（农村经营管理）部门、乡（镇）人民政府农村土地承包管理部门应当利用农村土地承包信息应用平台，组织开展承包合同网签。"},{"i":25,"n":"第二十五条","txt":"承包方、利害关系人有权依法查询、复制农村土地承包档案和农村土地承包数据的相关资料，发包方、乡（镇）人民政府农村土地承包管理部门、县级以上地方人民政府农业农村主管（农村经营管理）部门应当依法提供。"},{"i":26,"n":"第二十六条","txt":"土地承包经营权调查，应当查清发包方、承包方的名称，发包方负责人和承包方代表的姓名、身份证号码、住所，承包方家庭成员，承包地块的名称、坐落、面积、质量等级、土地用途等信息。"},{"i":27,"n":"第二十七条","txt":"土地承包经营权调查应当按照农村土地承包经营权调查规程实施，一般包括准备工作、权属调查、地块测量、审核公示、勘误修正、结果确认、信息入库、成果归档等。 农村土地承包经营权调查规程由农业农村部制定。"},{"i":28,"n":"第二十八条","txt":"土地承包经营权调查的成果，应当符合农村土地承包经营权调查规程的质量要求，并纳入农村土地承包信息应用平台统一管理。"},{"i":29,"n":"第二十九条","txt":"县级以上地方人民政府农业农村主管（农村经营管理）部门、乡（镇）人民政府农村土地承包管理部门依法组织开展本行政区域内的土地承包经营权调查。 土地承包经营权调查可以依法聘请具有相应资质的单位开展。"},{"i":30,"n":"第三十条","txt":"国家机关及其工作人员利用职权干涉承包合同的订立、变更、终止，给承包方造成损失的，应当依法承担损害赔偿等责任；情节严重的，由上级机关或者所在单位给予直接责任人员处分；构成犯罪的，依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"土地承包经营权调查、农村土地承包档案管理、农村土地承包数据管理和使用过程中发生的违法行为，根据相关法律法规的规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"本办法所称农村土地，是指除林地、草地以外的，农民集体所有和国家所有依法由农民集体使用的耕地和其他依法用于农业的土地。 本办法所称承包合同，是指在家庭承包方式中，发包方和承包方依法签订的土地承包经营权合同。"},{"i":33,"n":"第三十三条","txt":"本办法施行以前依法签订的承包合同继续有效。"},{"i":34,"n":"第三十四条","txt":"本办法自2023年5月1日起施行。农业部2003年11月14日发布的《中华人民共和国农村土地承包经营权证管理办法》（农业部令第33号）同时废止。"}],"nongcuntudichengbaojingyingjiufenzhongcaiguize":[{"i":1,"n":"第一条","txt":"为规范农村土地承包经营纠纷仲裁活动，根据《中华人民共和国农村土地承包经营纠纷调解仲裁法》，制定本规则。"},{"i":2,"n":"第二条","txt":"农村土地承包经营纠纷仲裁适用本规则。"},{"i":3,"n":"第三条","txt":"下列农村土地承包经营纠纷，当事人可以向农村土地承包仲裁委员会（以下简称仲裁委员会）申请仲裁： （一）因订立、履行、变更、解除和终止农村土地承包合同发生的纠纷； （二）因农村土地承包经营权转包、出租、互换、转让、入股等流转发生的纠纷； （三）因收回、调整承包地发生的纠纷； （四）因确认农村土地承包经营权发生的纠纷； （五）因侵害农村土地承包经营权发生的纠纷； （六）法律、法规规定的其他农村土地承包经营纠纷。 因征收集体所有的土地及其补偿发生的纠纷，不属于仲裁委员会的受理范围，可以通过行政复议或者诉讼等方式解决。"},{"i":4,"n":"第四条","txt":"仲裁委员会依法设立，其日常工作由当地农村土地承包管理部门承担。"},{"i":5,"n":"第五条","txt":"农村土地承包经营纠纷仲裁，应当公开、公平、公正，便民高效，注重调解，尊重事实，符合法律，遵守社会公德。"},{"i":6,"n":"第六条","txt":"农村土地承包经营纠纷仲裁的申请人、被申请人为仲裁当事人。"},{"i":7,"n":"第七条","txt":"家庭承包的，可以由农户代表人参加仲裁。农户代表人由农户成员共同推选；不能共同推选的，按下列方式确定： （一）土地承包经营权证或者林权证等证书上记载的人； （二）未取得土地承包经营权证或者林权证等证书的，为在承包合同上签字的人。"},{"i":8,"n":"第八条","txt":"当事人一方为五户（人）以上的，可以推选三至五名代表人参加仲裁。"},{"i":9,"n":"第九条","txt":"与案件处理结果有利害关系的，可以申请作为第三人参加仲裁，或者由仲裁委员会通知其参加仲裁。"},{"i":10,"n":"第十条","txt":"当事人、第三人可以委托代理人参加仲裁。 当事人或者第三人为无民事行为能力人或者限制民事行为能力人的，由其法定代理人参加仲裁。"},{"i":11,"n":"第十一条","txt":"当事人申请农村土地承包经营纠纷仲裁的时效期间为二年，自当事人知道或者应当知道其权利被侵害之日起计算。 仲裁时效因申请调解、申请仲裁、当事人一方提出要求或者同意履行义务而中断。从中断时起，仲裁时效重新计算。 在仲裁时效期间的最后六个月内，因不可抗力或者其他事由，当事人不能申请仲裁的，仲裁时效中止。从中止时效的原因消除之日起，仲裁时效期间继续计算。 侵害农村土地承包经营权行为持续发生的，仲裁时效从侵权行为终了时计算。"},{"i":12,"n":"第十二条","txt":"申请农村土地承包经营纠纷仲裁，应当符合下列条件： （一）申请人与纠纷有直接的利害关系； （二）有明确的被申请人； （三）有具体的仲裁请求和事实、理由； （四）属于仲裁委员会的受理范围。"},{"i":13,"n":"第十三条","txt":"当事人申请仲裁，应当向纠纷涉及土地所在地的仲裁委员会递交仲裁申请书。申请书可以邮寄或者委托他人代交。 书面申请有困难的，可以口头申请，由仲裁委员会记入笔录，经申请人核实后由其签名、盖章或者按指印。 仲裁委员会收到仲裁申请材料，应当出具回执。回执应当载明接收材料的名称和份数、接收日期等，并加盖仲裁委员会印章。"},{"i":14,"n":"第十四条","txt":"仲裁申请书应当载明下列内容： （一）申请人和被申请人的姓名、年龄、住所、邮政编码、电话或者其他通讯方式；法人或者其他组织应当写明名称、地址和法定代表人或者主要负责人的姓名、职务、通讯方式； （二）申请人的仲裁请求； （三）仲裁请求所依据的事实和理由； （四）证据和证据来源、证人姓名和联系方式。"},{"i":15,"n":"第十五条","txt":"仲裁委员会应当对仲裁申请进行审查，符合申请条件的，应当受理。 有下列情形之一的，不予受理；已受理的，终止仲裁程序： （一）不符合申请条件； （二）人民法院已受理该纠纷； （三）法律规定该纠纷应当由其他机构受理； （四）对该纠纷已有生效的判决、裁定、仲裁裁决、行政处理决定等。"},{"i":16,"n":"第十六条","txt":"仲裁委员会决定受理仲裁申请的，应当自收到仲裁申请之日起五个工作日内，将受理通知书、仲裁规则、仲裁员名册送达申请人，将受理通知书、仲裁申请书副本、仲裁规则、仲裁员名册送达被申请人。 决定不予受理或者终止仲裁程序的，应当自收到仲裁申请或者发现终止仲裁程序情形之日起五个工作日内书面通知申请人，并说明理由。 需要通知第三人参加仲裁的，仲裁委员会应当通知第三人，并告知其权利义务。"},{"i":17,"n":"第十七条","txt":"被申请人应当自收到仲裁申请书副本之日起十日内向仲裁委员会提交答辩书。 仲裁委员会应当自收到答辩书之日起五个工作日内将答辩书副本送达申请人。 被申请人未答辩的，不影响仲裁程序的进行。"},{"i":18,"n":"第十八条","txt":"答辩书应当载明下列内容： （一）答辩人姓名、年龄、住所、邮政编码、电话或者其他通讯方式；法人或者其他组织应当写明名称、地址和法定代表人或者主要负责人的姓名、职务、通讯方式； （二）对申请人仲裁申请的答辩及所依据的事实和理由； （三）证据和证据来源，证人姓名和联系方式。 书面答辩确有困难的，可以口头答辩，由仲裁委员会记入笔录，经被申请人核实后由其签名、盖章或者按指印。"},{"i":19,"n":"第十九条","txt":"当事人提交仲裁申请书、答辩书、有关证据材料及其他书面文件，应当一式三份。"},{"i":20,"n":"第二十条","txt":"因一方当事人的行为或者其他原因可能使裁决不能执行或者难以执行，另一方当事人申请财产保全的，仲裁委员会应当将当事人的申请提交被申请人住所地或者财产所在地的基层人民法院，并告知申请人因申请错误造成被申请人财产损失的，应当承担相应的赔偿责任。"},{"i":21,"n":"第二十一条","txt":"仲裁庭由三名仲裁员组成。 事实清楚、权利义务关系明确、争议不大的农村土地承包经营纠纷，经双方当事人同意，可以由一名仲裁员仲裁。"},{"i":22,"n":"第二十二条","txt":"双方当事人自收到受理通知书之日起五个工作日内，从仲裁员名册中选定仲裁员。首席仲裁员由双方当事人共同选定，其他二名仲裁员由双方当事人各自选定；当事人不能选定的，由仲裁委员会主任指定。 独任仲裁员由双方当事人共同选定；当事人不能选定的，由仲裁委员会主任指定。 仲裁委员会应当自仲裁庭组成之日起二个工作日内将仲裁庭组成情况通知当事人。"},{"i":23,"n":"第二十三条","txt":"仲裁庭组成后，首席仲裁员应当召集其他仲裁员审阅案件材料，了解纠纷的事实和情节，研究双方当事人的请求和理由，查核证据，整理争议焦点。 仲裁庭认为确有必要的，可以要求当事人在一定期限内补充证据，也可以自行调查取证。自行调查取证的，调查人员不得少于二人。"},{"i":24,"n":"第二十四条","txt":"仲裁员有下列情形之一的，应当回避： （一）是本案当事人或者当事人、代理人的近亲属； （二）与本案有利害关系； （三）与本案当事人、代理人有其他关系，可能影响公正仲裁； （四）私自会见当事人、代理人，或者接受当事人、代理人请客送礼。"},{"i":25,"n":"第二十五条","txt":"仲裁员有回避情形的，应当以口头或者书面方式及时向仲裁委员会提出。 当事人认为仲裁员有回避情形的，有权以口头或者书面方式向仲裁委员会申请其回避。 当事人提出回避申请，应当在首次开庭前提出，并说明理由；在首次开庭后知道回避事由的，可以在最后一次开庭终结前提出。"},{"i":26,"n":"第二十六条","txt":"仲裁委员会应当自收到回避申请或者发现仲裁员有回避情形之日起二个工作日内作出决定，以口头或者书面方式通知当事人，并说明理由。 仲裁员是否回避，由仲裁委员会主任决定；仲裁委员会主任担任仲裁员时，由仲裁委员会集体决定主任的回避。"},{"i":27,"n":"第二十七条","txt":"仲裁员有下列情形之一的，应当按照本规则第二十二条规定重新选定或者指定仲裁员： （一）被决定回避的； （二）在法律上或者事实上不能履行职责的； （三）因被除名或者解聘丧失仲裁员资格的； （四）因个人原因退出或者不能从事仲裁工作的； （五）因徇私舞弊、失职渎职被仲裁委员会决定更换的。 重新选定或者指定仲裁员后，仲裁程序继续进行。当事人请求仲裁程序重新进行的，由仲裁庭决定。"},{"i":28,"n":"第二十八条","txt":"仲裁庭应当向当事人提供必要的法律政策解释，帮助当事人自行和解。 达成和解协议的，当事人可以请求仲裁庭根据和解协议制作裁决书；当事人要求撤回仲裁申请的，仲裁庭应当终止仲裁程序。"},{"i":29,"n":"第二十九条","txt":"仲裁庭应当在双方当事人自愿的基础上进行调解。调解达成协议的，仲裁庭应当制作调解书。 调解书应当载明双方当事人基本情况、纠纷事由、仲裁请求和协议结果，由仲裁员签名，并加盖仲裁委员会印章，送达双方当事人。 调解书经双方当事人签收即发生法律效力。"},{"i":30,"n":"第三十条","txt":"调解不成或者当事人在调解书签收前反悔的，仲裁庭应当及时作出裁决。 当事人在调解过程中的陈述、意见、观点或者建议，仲裁庭不得作为裁决的证据或依据。"},{"i":31,"n":"第三十一条","txt":"仲裁庭作出裁决前，申请人放弃仲裁请求并撤回仲裁申请，且被申请人没有就申请人的仲裁请求提出反请求的，仲裁庭应当终止仲裁程序。 申请人经书面通知，无正当理由不到庭或者未经仲裁庭许可中途退庭的，可以视为撤回仲裁申请。"},{"i":32,"n":"第三十二条","txt":"被申请人就申请人的仲裁请求提出反请求的，应当说明反请求事项及其所依据的事实和理由，并附具有关证明材料。 被申请人在仲裁庭组成前提出反请求的，由仲裁委员会决定是否受理；在仲裁庭组成后提出反请求的，由仲裁庭决定是否受理。 仲裁委员会或者仲裁庭决定受理反请求的，应当自收到反请求之日起五个工作日内将反请求申请书副本送达申请人。申请人应当在收到反请求申请书副本后十个工作日内提交反请求答辩书，不答辩的不影响仲裁程序的进行。仲裁庭应当将被申请人的反请求与申请人的请求合并审理。 仲裁委员会或者仲裁庭决定不予受理反请求的，应当书面通知被申请人，并说明理由。"},{"i":33,"n":"第三十三条","txt":"仲裁庭组成前申请人变更仲裁请求或者被申请人变更反请求的，由仲裁委员会作出是否准许的决定；仲裁庭组成后变更请求或者反请求的，由仲裁庭作出是否准许的决定。"},{"i":34,"n":"第三十四条","txt":"农村土地承包经营纠纷仲裁应当开庭进行。开庭应当公开，但涉及国家秘密、商业秘密和个人隐私以及当事人约定不公开的除外。 开庭可以在纠纷涉及的土地所在地的乡（镇）或者村进行，也可以在仲裁委员会所在地进行。当事人双方要求在乡（镇）或者村开庭的，应当在该乡（镇）或者村开庭。"},{"i":35,"n":"第三十五条","txt":"仲裁庭应当在开庭五个工作日前将开庭时间、地点通知当事人、第三人和其他仲裁参与人。 当事人请求变更开庭时间和地点的，应当在开庭三个工作日前向仲裁庭提出，并说明理由。仲裁庭决定变更的，通知双方当事人、第三人和其他仲裁参与人；决定不变更的，通知提出变更请求的当事人。"},{"i":36,"n":"第三十六条","txt":"公开开庭的，应当将开庭时间、地点等信息予以公告。 申请旁听的公民，经仲裁庭审查后可以旁听。"},{"i":37,"n":"第三十七条","txt":"被申请人经书面通知，无正当理由不到庭或者未经仲裁庭许可中途退庭的，仲裁庭可以缺席裁决。 被申请人提出反请求，申请人经书面通知，无正当理由不到庭或者未经仲裁庭许可中途退庭的，仲裁庭可以就反请求缺席裁决。"},{"i":38,"n":"第三十八条","txt":"开庭前，仲裁庭应当查明当事人、第三人、代理人和其他仲裁参与人是否到庭，并逐一核对身份。 开庭由首席仲裁员或者独任仲裁员宣布。首席仲裁员或者独任仲裁员应当宣布案由，宣读仲裁庭组成人员名单、仲裁庭纪律、当事人权利和义务，询问当事人是否申请仲裁员回避。"},{"i":39,"n":"第三十九条","txt":"仲裁庭应当保障双方当事人平等陈述的机会，组织当事人、第三人、代理人陈述事实、意见、理由。"},{"i":40,"n":"第四十条","txt":"当事人、第三人应当提供证据，对其主张加以证明。 与纠纷有关的证据由作为当事人一方的发包方等掌握管理的，该当事人应当在仲裁庭指定的期限内提供，逾期不提供的，应当承担不利后果。"},{"i":41,"n":"第四十一条","txt":"仲裁庭自行调查收集的证据，应当在开庭时向双方当事人出示。"},{"i":42,"n":"第四十二条","txt":"仲裁庭对专门性问题认为需要鉴定的，可以交由当事人约定的鉴定机构鉴定；当事人没有约定的，由仲裁庭指定的鉴定机构鉴定。"},{"i":43,"n":"第四十三条","txt":"当事人申请证据保全，应当向仲裁委员会书面提出。仲裁委员会应当自收到申请之日起二个工作日内，将申请提交证据所在地的基层人民法院。"},{"i":44,"n":"第四十四条","txt":"当事人、第三人申请证人出庭作证的，仲裁庭应当准许，并告知证人的权利义务。 证人不得旁听案件审理。"},{"i":45,"n":"第四十五条","txt":"证据应当在开庭时出示，但涉及国家秘密、商业秘密和个人隐私的证据不得在公开开庭时出示。 仲裁庭应当组织当事人、第三人交换证据，相互质证。 经仲裁庭许可，当事人、第三人可以向证人询问，证人应当据实回答。 根据当事人的请求或者仲裁庭的要求，鉴定机构应当派鉴定人参加开庭。经仲裁庭许可，当事人可以向鉴定人提问。"},{"i":46,"n":"第四十六条","txt":"仲裁庭应当保障双方当事人平等行使辩论权，并对争议焦点组织辩论。 辩论终结时，首席仲裁员或者独任仲裁员应当征询双方当事人、第三人的最后意见。"},{"i":47,"n":"第四十七条","txt":"对权利义务关系明确的纠纷，当事人可以向仲裁庭书面提出先行裁定申请，请求维持现状、恢复农业生产以及停止取土、占地等破坏性行为。仲裁庭应当自收到先行裁定申请之日起二个工作日内作出决定。 仲裁庭作出先行裁定的，应当制作先行裁定书，并告知先行裁定申请人可以向人民法院申请执行，但应当提供相应的担保。 先行裁定书应当载明先行裁定申请的内容、依据事实和理由、裁定结果和日期，由仲裁员签名，加盖仲裁委员会印章。"},{"i":48,"n":"第四十八条","txt":"仲裁庭应当将开庭情况记入笔录。笔录由仲裁员、记录人员、当事人、第三人和其他仲裁参与人签名、盖章或者按指印。 当事人、第三人和其他仲裁参与人认为对自己的陈述记录有遗漏或者差错的，有权申请补正。仲裁庭不予补正的，应当向申请人说明情况，并记录该申请。"},{"i":49,"n":"第四十九条","txt":"发生下列情形之一的，仲裁程序中止： （一）一方当事人死亡，需要等待继承人表明是否参加仲裁的； （二）一方当事人丧失行为能力，尚未确定法定代理人的； （三）作为一方当事人的法人或者其他组织终止，尚未确定权利义务承受人的； （四）一方当事人因不可抗拒的事由，不能参加仲裁的； （五）本案必须以另一案的审理结果为依据，而另一案尚未审结的； （六）其他应当中止仲裁程序的情形。 在仲裁庭组成前发生仲裁中止事由的，由仲裁委员会决定是否中止仲裁；仲裁庭组成后发生仲裁中止事由的，由仲裁庭决定是否中止仲裁。决定仲裁程序中止的，应当书面通知当事人。 仲裁程序中止的原因消除后，仲裁委员会或者仲裁庭应当在三个工作日内作出恢复仲裁程序的决定，并通知当事人和第三人。"},{"i":50,"n":"第五十条","txt":"发生下列情形之一的，仲裁程序终结： （一）申请人死亡或者终止，没有继承人及权利义务承受人，或者继承人、权利义务承受人放弃权利的； （二）被申请人死亡或者终止，没有可供执行的财产，也没有应当承担义务的人的； （三）其他应当终结仲裁程序的。 终结仲裁程序的，仲裁委员会应当自发现终结仲裁程序情形之日起五个工作日内书面通知当事人、第三人，并说明理由。"},{"i":51,"n":"第五十一条","txt":"仲裁庭应当根据认定的事实和法律以及国家政策作出裁决，并制作裁决书。 首席仲裁员组织仲裁庭对案件进行评议，裁决依多数仲裁员意见作出。少数仲裁员的不同意见可以记入笔录。 仲裁庭不能形成多数意见时，应当按照首席仲裁员的意见作出裁决。"},{"i":52,"n":"第五十二条","txt":"裁决书应当写明仲裁请求、争议事实、裁决理由和依据、裁决结果、裁决日期，以及当事人不服仲裁裁决的起诉权利和期限。 裁决书由仲裁员签名，加盖仲裁委员会印章。"},{"i":53,"n":"第五十三条","txt":"对裁决书中的文字、计算错误，或者裁决书中有遗漏的事项，仲裁庭应当及时补正。补正构成裁决书的一部分。"},{"i":54,"n":"第五十四条","txt":"仲裁庭应当自受理仲裁申请之日起六十日内作出仲裁裁决。受理日期以受理通知书上记载的日期为准。 案情复杂需要延长的，经仲裁委员会主任批准可以延长，但延长期限不得超过三十日。 延长期限的，应当自作出延期决定之日起三个工作日内书面通知当事人、第三人。 期限不包括仲裁程序中止、鉴定、当事人在庭外自行和解、补充申请材料和补正裁决的时间。"},{"i":55,"n":"第五十五条","txt":"仲裁委员会应当在裁决作出之日起三个工作日内将裁决书送达当事人、第三人。 直接送达的，应当告知当事人、第三人下列事项： （一）不服仲裁裁决的，可以在收到裁决书之日起三十日内向人民法院起诉，逾期不起诉的，裁决书即发生法律效力； （二）一方当事人不履行生效的裁决书所确定义务的，另一方当事人可以向被申请人住所地或者财产所在地的基层人民法院申请执行。"},{"i":56,"n":"第五十六条","txt":"仲裁文书应当直接送达当事人或者其代理人。受送达人是自然人，但本人不在场的，由其同住成年家属签收；受送达人是法人或者其他组织的，应当由法人的法定代表人、其他组织的主要负责人或者该法人、组织负责收件的人签收。 仲裁文书送达后，由受送达人在送达回证上签名、盖章或者按指印，受送达人在送达回证上的签收日期为送达日期。 受送达人或者其同住成年家属拒绝接收仲裁文书的，可以留置送达。送达人应当邀请有关基层组织或者受送达人所在单位的代表到场，说明情况，在送达回证上记明拒收理由和日期，由送达人、见证人签名、盖章或者按指印，将仲裁文书留在受送达人的住所，即视为已经送达。 直接送达有困难的，可以邮寄送达。邮寄送达的，以当事人签收日期为送达日期。 当事人下落不明，或者以前款规定的送达方式无法送达的，可以公告送达，自发出公告之日起，经过六十日，即视为已经送达。"},{"i":57,"n":"第五十七条","txt":"独任仲裁可以适用简易程序。简易程序的仲裁规则由仲裁委员会依照本规则制定。"},{"i":58,"n":"第五十八条","txt":"期间包括法定期间和仲裁庭指定的期间。 期间以日、月、年计算，期间开始日不计算在期间内。 期间最后一日是法定节假日的，以法定节假日后的第一个工作日为期间的最后一日。"},{"i":59,"n":"第五十九条","txt":"对不通晓当地通用语言文字的当事人、第三人，仲裁委员会应当为其提供翻译。"},{"i":60,"n":"第六十条","txt":"仲裁文书格式由农业部、国家林业局共同制定。"},{"i":61,"n":"第六十一条","txt":"农村土地承包经营纠纷仲裁不得向当事人收取费用，仲裁工作经费依法纳入财政预算予以保障。 当事人委托代理人、申请鉴定等发生的费用由当事人负担。"},{"i":62,"n":"第六十二条","txt":"本规则自2010年1月1日起施行。"}],"nongcuntudijingyingquanliuzhuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范农村土地经营权（以下简称土地经营权）流转行为，保障流转当事人合法权益，加快农业农村现代化，维护农村社会和谐稳定，根据《中华人民共和国农村土地承包法》等法律及有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"土地经营权流转应当坚持农村土地农民集体所有、农户家庭承包经营的基本制度，保持农村土地承包关系稳定并长久不变，遵循依法、自愿、有偿原则，任何组织和个人不得强迫或者阻碍承包方流转土地经营权。"},{"i":3,"n":"第三条","txt":"土地经营权流转不得损害农村集体经济组织和利害关系人的合法权益，不得破坏农业综合生产能力和农业生态环境，不得改变承包土地的所有权性质及其农业用途，确保农地农用，优先用于粮食生产，制止耕地“非农化”、防止耕地“非粮化”。"},{"i":4,"n":"第四条","txt":"土地经营权流转应当因地制宜、循序渐进，把握好流转、集中、规模经营的度，流转规模应当与城镇化进程和农村劳动力转移规模相适应，与农业科技进步和生产手段改进程度相适应，与农业社会化服务水平提高相适应，鼓励各地建立多种形式的土地经营权流转风险防范和保障机制。"},{"i":5,"n":"第五条","txt":"农业农村部负责全国土地经营权流转及流转合同管理的指导。 县级以上地方人民政府农业农村主管（农村经营管理）部门依照职责，负责本行政区域内土地经营权流转及流转合同管理。 乡（镇）人民政府负责本行政区域内土地经营权流转及流转合同管理。"},{"i":6,"n":"第六条","txt":"承包方在承包期限内有权依法自主决定土地经营权是否流转，以及流转对象、方式、期限等。"},{"i":7,"n":"第七条","txt":"土地经营权流转收益归承包方所有，任何组织和个人不得擅自截留、扣缴。"},{"i":8,"n":"第八条","txt":"承包方自愿委托发包方、中介组织或者他人流转其土地经营权的，应当由承包方出具流转委托书。委托书应当载明委托的事项、权限和期限等，并由委托人和受托人签字或者盖章。 没有承包方的书面委托，任何组织和个人无权以任何方式决定流转承包方的土地经营权。"},{"i":9,"n":"第九条","txt":"土地经营权流转的受让方应当为具有农业经营能力或者资质的组织和个人。在同等条件下，本集体经济组织成员享有优先权。"},{"i":10,"n":"第十条","txt":"土地经营权流转的方式、期限、价款和具体条件，由流转双方平等协商确定。流转期限届满后，受让方享有以同等条件优先续约的权利。"},{"i":11,"n":"第十一条","txt":"受让方应当依照有关法律法规保护土地，禁止改变土地的农业用途。禁止闲置、荒芜耕地，禁止占用耕地建窑、建坟或者擅自在耕地上建房、挖砂、采石、采矿、取土等。禁止占用永久基本农田发展林果业和挖塘养鱼。"},{"i":12,"n":"第十二条","txt":"受让方将流转取得的土地经营权再流转以及向金融机构融资担保的，应当事先取得承包方书面同意，并向发包方备案。"},{"i":13,"n":"第十三条","txt":"经承包方同意，受让方依法投资改良土壤，建设农业生产附属、配套设施，及农业生产中直接用于作物种植和畜禽水产养殖设施的，土地经营权流转合同到期或者未到期由承包方依法提前收回承包土地时，受让方有权获得合理补偿。具体补偿办法可在土地经营权流转合同中约定或者由双方协商确定。"},{"i":14,"n":"第十四条","txt":"承包方可以采取出租（转包）、入股或者其他符合有关法律和国家政策规定的方式流转土地经营权。 出租（转包），是指承包方将部分或者全部土地经营权，租赁给他人从事农业生产经营。 入股，是指承包方将部分或者全部土地经营权作价出资，成为公司、合作经济组织等股东或者成员，并用于农业生产经营。"},{"i":15,"n":"第十五条","txt":"承包方依法采取出租（转包）、入股或者其他方式将土地经营权部分或者全部流转的，承包方与发包方的承包关系不变，双方享有的权利和承担的义务不变。"},{"i":16,"n":"第十六条","txt":"承包方自愿将土地经营权入股公司发展农业产业化经营的，可以采取优先股等方式降低承包方风险。公司解散时入股土地应当退回原承包方。"},{"i":17,"n":"第十七条","txt":"承包方流转土地经营权，应当与受让方在协商一致的基础上签订书面流转合同，并向发包方备案。 承包方将土地交由他人代耕不超过一年的，可以不签订书面合同。"},{"i":18,"n":"第十八条","txt":"承包方委托发包方、中介组织或者他人流转土地经营权的，流转合同应当由承包方或者其书面委托的受托人签订。"},{"i":19,"n":"第十九条","txt":"土地经营权流转合同一般包括以下内容： （一）双方当事人的姓名或者名称、住所、联系方式等； （二）流转土地的名称、四至、面积、质量等级、土地类型、地块代码等； （三）流转的期限和起止日期； （四）流转方式； （五）流转土地的用途； （六）双方当事人的权利和义务； （七）流转价款或者股份分红，以及支付方式和支付时间； （八）合同到期后地上附着物及相关设施的处理； （九）土地被依法征收、征用、占用时有关补偿费的归属； （十）违约责任。 土地经营权流转合同示范文本由农业农村部制定。"},{"i":20,"n":"第二十条","txt":"承包方不得单方解除土地经营权流转合同，但受让方有下列情形之一的除外： （一）擅自改变土地的农业用途； （二）弃耕抛荒连续两年以上； （三）给土地造成严重损害或者严重破坏土地生态环境； （四）其他严重违约行为。 有以上情形，承包方在合理期限内不解除土地经营权流转合同的，发包方有权要求终止土地经营权流转合同。 受让方对土地和土地生态环境造成的损害应当依法予以赔偿。"},{"i":21,"n":"第二十一条","txt":"发包方对承包方流转土地经营权、受让方再流转土地经营权以及承包方、受让方利用土地经营权融资担保的，应当办理备案，并报告乡（镇）人民政府农村土地承包管理部门。"},{"i":22,"n":"第二十二条","txt":"乡（镇）人民政府农村土地承包管理部门应当向达成流转意向的双方提供统一文本格式的流转合同，并指导签订。流转合同中有违反法律法规的，应当及时予以纠正。"},{"i":23,"n":"第二十三条","txt":"乡（镇）人民政府农村土地承包管理部门应当建立土地经营权流转台账，及时准确记载流转情况。"},{"i":24,"n":"第二十四条","txt":"乡（镇）人民政府农村土地承包管理部门应当对土地经营权流转有关文件、资料及流转合同等进行归档并妥善保管。"},{"i":25,"n":"第二十五条","txt":"鼓励各地建立土地经营权流转市场或者农村产权交易市场。县级以上地方人民政府农业农村主管（农村经营管理）部门应当加强业务指导，督促其建立健全运行规则，规范开展土地经营权流转政策咨询、信息发布、合同签订、交易鉴证、权益评估、融资担保、档案管理等服务。"},{"i":26,"n":"第二十六条","txt":"县级以上地方人民政府农业农村主管（农村经营管理）部门应当按照统一标准和技术规范建立国家、省、市、县等互联互通的农村土地承包信息应用平台，健全土地经营权流转合同网签制度，提升土地经营权流转规范化、信息化管理水平。"},{"i":27,"n":"第二十七条","txt":"县级以上地方人民政府农业农村主管（农村经营管理）部门应当加强对乡（镇）人民政府农村土地承包管理部门工作的指导。乡（镇）人民政府农村土地承包管理部门应当依法开展土地经营权流转的指导和管理工作。"},{"i":28,"n":"第二十八条","txt":"县级以上地方人民政府农业农村主管（农村经营管理）部门应当加强服务，鼓励受让方发展粮食生产；鼓励和引导工商企业等社会资本（包括法人、非法人组织或者自然人等）发展适合企业化经营的现代种养业。 县级以上地方人民政府农业农村主管（农村经营管理）部门应当根据自然经济条件、农村劳动力转移情况、农业机械化水平等因素，引导受让方发展适度规模经营，防止垒大户。"},{"i":29,"n":"第二十九条","txt":"县级以上地方人民政府对工商企业等社会资本流转土地经营权，依法建立分级资格审查和项目审核制度。审查审核的一般程序如下： （一）受让主体与承包方就流转面积、期限、价款等进行协商并签订流转意向协议书。涉及未承包到户集体土地等集体资源的，应当按照法定程序经本集体经济组织成员的村民会议三分之二以上成员或者三分之二以上村民代表的同意，并与集体经济组织签订流转意向协议书。 （二）受让主体按照分级审查审核规定，分别向乡（镇）人民政府农村土地承包管理部门或者县级以上地方人民政府农业农村主管（农村经营管理）部门提出申请，并提交流转意向协议书、农业经营能力或者资质证明、流转项目规划等相关材料。 （三）县级以上地方人民政府或者乡（镇）人民政府应当依法组织相关职能部门、农村集体经济组织代表、农民代表、专家等就土地用途、受让主体农业经营能力，以及经营项目是否符合粮食生产等产业规划等进行审查审核，并于受理之日起20"},{"i":30,"n":"第三十条","txt":"县级以上地方人民政府依法建立工商企业等社会资本通过流转取得土地经营权的风险防范制度，加强事中事后监管，及时查处纠正违法违规行为。 鼓励承包方和受让方在土地经营权流转市场或者农村产权交易市场公开交易。 对整村（组）土地经营权流转面积较大、涉及农户较多、经营风险较高的项目，流转双方可以协商设立风险保障金。 鼓励保险机构为土地经营权流转提供流转履约保证保险等多种形式保险服务。"},{"i":31,"n":"第三十一条","txt":"农村集体经济组织为工商企业等社会资本流转土地经营权提供服务的，可以收取适量管理费用。收取管理费用的金额和方式应当由农村集体经济组织、承包方和工商企业等社会资本三方协商确定。管理费用应当纳入农村集体经济组织会计核算和财务管理，主要用于农田基本建设或者其他公益性支出。"},{"i":32,"n":"第三十二条","txt":"县级以上地方人民政府可以根据本办法，结合本行政区域实际，制定工商企业等社会资本通过流转取得土地经营权的资格审查、项目审核和风险防范实施细则。"},{"i":33,"n":"第三十三条","txt":"土地经营权流转发生争议或者纠纷的，当事人可以协商解决，也可以请求村民委员会、乡（镇）人民政府等进行调解。 当事人不愿意协商、调解或者协商、调解不成的，可以向农村土地承包仲裁机构申请仲裁，也可以直接向人民法院提起诉讼。"},{"i":34,"n":"第三十四条","txt":"本办法所称农村土地，是指除林地、草地以外的，农民集体所有和国家所有依法由农民集体使用的耕地和其他用于农业的土地。 本办法所称农村土地经营权流转，是指在承包方与发包方承包关系保持不变的前提下，承包方依法在一定期限内将土地经营权部分或者全部交由他人自主开展农业生产经营的行为。"},{"i":35,"n":"第三十五条","txt":"通过招标、拍卖和公开协商等方式承包荒山、荒沟、荒丘、荒滩等农村土地，经依法登记取得权属证书的，可以流转土地经营权，其流转管理参照本办法执行。"},{"i":36,"n":"第三十六条","txt":"本办法自2021年3月1日起施行。农业部2005年1月19日发布的《农村土地承包经营权流转管理办法》（农业部令第47号）同时废止。"}],"nongcunjitijingjizuzhishenjiguiding":[{"i":1,"n":"第一条","txt":"为了加强农村集体经济组织的审计监督，严肃财经法纪，提高经济效益，保护农村集体经济组织的合法权益，促进农村经济的发展，根据《中华人民共和国审计法》、《农民承担费用和劳务管理条例》、《审计署关于内部审计工作的规定》和有关法律、法规、政策，结合农村集体经济组织发展的具体情况，制定本规定。"},{"i":2,"n":"第二条","txt":"农业部负责全国农村集体经济组织的审计工作。 审计业务接受国家审计机关和上级主管部门内审机构的指导。"},{"i":3,"n":"第三条","txt":"县级以上地方人民政府农村经营管理部门负责指导农村集体经济组织的审计工作，乡级农村经营管理部门负责农村集体经济组织的审计工作。"},{"i":4,"n":"第四条","txt":"凡建立农村集体经济组织审计机构的，都应配备相应的审计人员。 审计人员应当经过考核，发给审计证，凭证开展审计工作。"},{"i":5,"n":"第五条","txt":"农村集体经济组织审计机构工作人员应当依法审计，忠于职守，坚持原则，客观公正，廉洁奉公，保守秘密。"},{"i":6,"n":"第六条","txt":"农村集体经济组织审计机构的审计监督范围为村、组集体经济组织。"},{"i":7,"n":"第七条","txt":"农村集体经济组织审计机构对前条所列单位的下列事项进行审计监督： （一）资金、财产的验证和使用管理情况； （二）财务收支和有关的经济活动及其经济效益； （三）财务管理制度的制定和执行情况； （四）承包合同的签订和履行情况； （五）收益（利润）分配情况； （六）承包费等集体专项资金的预算、提取和使用情况； （七）村集体公益事业建设筹资筹劳情况； （八）村集体经济组织负责人任期目标和离任经济责任； （九）侵占集体财产等损害农村集体经济组织利益的行为； （十）乡经营管理站代管的集体资金管理情况； （十一）当地人民政府、国家审计机关和上级业务主管部门等委托的其他审计事项。"},{"i":8,"n":"第八条","txt":"农村集体经济组织审计机构在审计过程中有下列职权： （一）要求被审计单位报送和提供财务计划、会计报表及有关资料； （二）检查被审计单位的有关账目、资产，查阅有关文件资料，参加被审计单位的有关会议； （三）向有关单位和人员进行调查，被调查的单位和人员应当如实提供有关资料及证明材料； （四）对正在进行的损害农村集体经济组织利益、违反财经法纪的行为，有权制止； （五）对阻挠、破坏审计工作的被审计单位，有权采取封存有关账册、资产等临时措施。"},{"i":9,"n":"第九条","txt":"农村集体经济组织审计工作人员依法行使职权，受法律保护，任何人不得打击报复。"},{"i":10,"n":"第十条","txt":"农村集体经济组织审计机构根据同级人民政府和上级业务主管部门的要求，结合本地实际，确定审计工作的重点，编制审计项目计划和工作方案。 农村集体经济组织审计机构确定审计事项后，应当通知被审计单位。"},{"i":11,"n":"第十一条","txt":"农村集体经济组织审计人员根据审计项目，审查凭证、账表，查阅文件、资料，检查现金、实物，向有关单位和人员进行调查，并取得证明材料。 证明人提供的书面证明材料应当由提供者签名或盖章。"},{"i":12,"n":"第十二条","txt":"农村集体经济组织审计人员，在审计过程中，应当主动听取农民群众和民主理财组织的意见。"},{"i":13,"n":"第十三条","txt":"农村集体经济组织审计人员对审计事项进行审计后，向委派其进行审计的农村集体经济组织审计机构提出审计报告。重大审计事项的审计报告，应当分别报送同级人民政府、上级农村集体经济组织审计机构和有关主管部门。 审计报告在报送之前，应当征求被审计单位的意见。被审计单位应当在收到审计报告之日起十日内提出书面意见。"},{"i":14,"n":"第十四条","txt":"农村集体经济组织审计机构审定审计报告，作出审计结论和决定，通知被审计单位和有关单位执行，并向农民群众公布。"},{"i":15,"n":"第十五条","txt":"被审计单位对农村集体经济组织审计机构作出的审计结论和决定如有异议，可在收到审计结论和决定之日起十五日内，向上一级农村集体经济组织审计机构申请复审。上一级农村集体经济组织审计机构应当在收到复审申请之日起三十日内，作出复审结论和决定。特殊情况下，作出复审结论和决定的期限，可适当延长。 复审期间，不停止原审计结论和决定的执行。"},{"i":16,"n":"第十六条","txt":"农村集体经济组织审计机构应当检查审计结论和决定的执行情况。"},{"i":17,"n":"第十七条","txt":"农村集体经济组织审计机构对办理的审计事项必须建立审计档案，加强档案管理。"},{"i":18,"n":"第十八条","txt":"农村集体经济组织审计机构应当对农村集体经济组织财务收支按月或按季进行经常、全面的审计监督。"},{"i":19,"n":"第十九条","txt":"对遵守和维护财经法纪成绩显著的单位和个人，提出通报表扬和奖励。"},{"i":20,"n":"第二十条","txt":"农村集体经济组织审计机构对被审计单位违反规定的收支、用工和非法所得的收入，应当在审计结论和决定中明确，分别按规定上缴国家，或退还农村集体经济组织和农户。"},{"i":21,"n":"第二十一条","txt":"违反本规定，有下列行为之一的单位负责人、直接责任人员及其他有关人员，应当给予行政处分的，由农村集体经济组织审计机构建议当地人民政府或有关主管部门处理： （一）拒绝提供账簿、凭证、会计报表、资料和证明材料的； （二）阻挠审计工作人员依法行使审计职权，抗拒、破坏监督检查的； （三）弄虚作假，隐瞒事实真相的； （四）拒不执行审计结论和决定的； （五）打击报复审计工作人员和检举人的。"},{"i":22,"n":"第二十二条","txt":"违反本规定，有下列行为之一的农村集体经济组织审计人员，可由农村集体经济组织审计机构给予处分，或向同级人民政府和有关部门提出给予行政处分的建议： （一）利用职权，谋取私利的； （二）弄虚作假，徇私舞弊的； （三）玩忽职守，给被审计单位和个人造成损失的； （四）泄露秘密的。"},{"i":23,"n":"第二十三条","txt":"对经济处理决定不服的单位和个人，可向作出处理决定机构的上一级机构提出申诉。"},{"i":24,"n":"第二十四条","txt":"对有本规定第二十一条、第二十二条所列行为，情节严重，构成犯罪的，提请司法机关依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"农村集体经济组织审计机构可接受委托向农村集体经济组织以外的单位提供审计服务，其收费标准，由省、自治区、直辖市农村行政主管部门会同同级财政、物价主管部门制定。"},{"i":26,"n":"第二十六条","txt":"各省、自治区、直辖市可根据本规定制定实施办法。"},{"i":27,"n":"第二十七条","txt":"本规定由农业部负责解释。"},{"i":28,"n":"第二十八条","txt":"本规定自发布之日起施行。"}],"nongyongdituranghuanjingguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为了加强农用地土壤环境保护监督管理，保护农用地土壤环境，管控农用地土壤环境风险，保障农产品质量安全，根据《中华人民共和国环境保护法》《中华人民共和国农产品质量安全法》等法律法规和《土壤污染防治行动计划》，制定本办法。"},{"i":2,"n":"第二条","txt":"农用地土壤污染防治相关活动及其监督管理适用本办法。 前款所指的农用地土壤污染防治相关活动，是指对农用地开展的土壤污染预防、土壤污染状况调查、环境监测、环境质量类别划分、分类管理等活动。 本办法所称的农用地土壤环境质量类别划分和分类管理，主要适用于耕地。园地、草地、林地可参照本办法。"},{"i":3,"n":"第三条","txt":"环境保护部对全国农用地土壤环境保护工作实施统一监督管理；县级以上地方环境保护主管部门对本行政区域内农用地土壤污染防治相关活动实施统一监督管理。 农业部对全国农用地土壤安全利用、严格管控、治理与修复等工作实施监督管理；县级以上地方农业主管部门负责本行政区域内农用地土壤安全利用、严格管控、治理与修复等工作的组织实施。 农用地土壤污染预防、土壤污染状况调查、环境监测、环境质量类别划分、农用地土壤优先保护、监督管理等工作，由县级以上环境保护和农业主管部门按照本办法有关规定组织实施。"},{"i":4,"n":"第四条","txt":"环境保护部会同农业部制定农用地土壤污染状况调查、环境监测、环境质量类别划分等技术规范。 农业部会同环境保护部制定农用地土壤安全利用、严格管控、治理与修复、治理与修复效果评估等技术规范。"},{"i":5,"n":"第五条","txt":"县级以上地方环境保护和农业主管部门在编制本行政区域的环境保护规划和农业发展规划时，应当包含农用地土壤污染防治工作的内容。"},{"i":6,"n":"第六条","txt":"环境保护部会同农业部等部门组织建立全国农用地土壤环境管理信息系统（以下简称农用地环境信息系统），实行信息共享。 县级以上地方环境保护主管部门、农业主管部门应当按照国家有关规定，在本行政区域内组织建设和应用农用地环境信息系统，并加强农用地土壤环境信息统计工作，健全农用地土壤环境信息档案，定期上传农用地环境信息系统，实行信息共享。"},{"i":7,"n":"第七条","txt":"受委托从事农用地土壤污染防治相关活动的专业机构，以及受委托从事治理与修复效果评估的第三方机构，应当遵守有关环境保护标准和技术规范，并对其出具的技术文件的真实性、准确性、完整性负责。 受委托从事治理与修复的专业机构，应当遵守国家有关环境保护标准和技术规范，在合同约定范围内开展工作，对治理与修复活动及其效果负责。 受委托从事治理与修复的专业机构在治理与修复活动中弄虚作假，对造成的环境污染和生态破坏负有责任的，除依照有关法律法规接受处罚外，还应当依法与造成环境污染和生态破坏的其他责任者承担连带责任。"},{"i":8,"n":"第八条","txt":"排放污染物的企业事业单位和其他生产经营者应当采取有效措施，确保废水、废气排放和固体废物处理、处置符合国家有关规定要求，防止对周边农用地土壤造成污染。 从事固体废物和化学品储存、运输、处置的企业，应当采取措施防止固体废物和化学品的泄露、渗漏、遗撒、扬散污染农用地。"},{"i":9,"n":"第九条","txt":"县级以上地方环境保护主管部门应当加强对企业事业单位和其他生产经营者排污行为的监管，将土壤污染防治作为环境执法的重要内容。 设区的市级以上地方环境保护主管部门应当根据本行政区域内工矿企业分布和污染排放情况，确定土壤环境重点监管企业名单，上传农用地环境信息系统，实行动态更新，并向社会公布。"},{"i":10,"n":"第十条","txt":"从事规模化畜禽养殖和农产品加工的单位和个人，应当按照相关规范要求，确定废物无害化处理方式和消纳场地。 县级以上地方环境保护主管部门、农业主管部门应当依据法定职责加强畜禽养殖污染防治工作，指导畜禽养殖废弃物综合利用，防止畜禽养殖活动对农用地土壤环境造成污染。"},{"i":11,"n":"第十一条","txt":"县级以上地方农业主管部门应当加强农用地土壤污染防治知识宣传，提高农业生产者的农用地土壤环境保护意识，引导农业生产者合理使用肥料、农药、兽药、农用薄膜等农业投入品，根据科学的测土配方进行合理施肥，鼓励采取种养结合、轮作等良好农业生产措施。"},{"i":12,"n":"第十二条","txt":"禁止在农用地排放、倾倒、使用污泥、清淤底泥、尾矿（渣）等可能对土壤造成污染的固体废物。 农田灌溉用水应当符合相应的水质标准，防止污染土壤、地下水和农产品。禁止向农田灌溉渠道排放工业废水或者医疗污水。向农田灌溉渠道排放城镇污水以及未综合利用的畜禽养殖废水、农产品加工废水的，应当保证其下游最近的灌溉取水点的水质符合农田灌溉水质标准。"},{"i":13,"n":"第十三条","txt":"环境保护部会同农业部等部门建立农用地土壤污染状况定期调查制度，制定调查工作方案，每十年开展一次。"},{"i":14,"n":"第十四条","txt":"环境保护部会同农业部等部门建立全国土壤环境质量监测网络，统一规划农用地土壤环境质量国控监测点位，规定监测要求，并组织实施全国农用地土壤环境监测工作。 农用地土壤环境质量国控监测点位应当重点布设在粮食生产功能区、重要农产品生产保护区、特色农产品优势区以及污染风险较大的区域等。 县级以上地方环境保护主管部门会同农业等有关部门，可以根据工作需要，布设地方农用地土壤环境质量监测点位，增加特征污染物监测项目，提高监测频次，有关监测结果应当及时上传农用地环境信息系统。"},{"i":15,"n":"第十五条","txt":"县级以上农业主管部门应当根据不同区域的农产品质量安全情况，组织实施耕地土壤与农产品协同监测，开展风险评估，根据监测评估结果，优化调整安全利用措施，并将监测结果及时上传农用地环境信息系统。"},{"i":16,"n":"第十六条","txt":"省级农业主管部门会同环境保护主管部门，按照国家有关技术规范，根据土壤污染程度、农产品质量情况，组织开展耕地土壤环境质量类别划分工作，将耕地划分为优先保护类、安全利用类和严格管控类，划分结果报省级人民政府审定，并根据土地利用变更和土壤环境质量变化情况，定期对各类别农用地面积、分布等信息进行更新，数据上传至农用地环境信息系统。"},{"i":17,"n":"第十七条","txt":"县级以上地方农业主管部门应当根据永久基本农田划定工作要求，积极配合相关部门将符合条件的优先保护类耕地划为永久基本农田，纳入粮食生产功能区和重要农产品生产保护区建设，实行严格保护，确保其面积不减少，耕地污染程度不上升。在优先保护类耕地集中的地区，优先开展高标准农田建设。"},{"i":18,"n":"第十八条","txt":"严格控制在优先保护类耕地集中区域新建有色金属冶炼、石油加工、化工、焦化、电镀、制革等行业企业，有关环境保护主管部门依法不予审批可能造成耕地土壤污染的建设项目环境影响报告书或者报告表。优先保护类耕地集中区域现有可能造成土壤污染的相关行业企业应当按照有关规定采取措施，防止对耕地造成污染。"},{"i":19,"n":"第十九条","txt":"对安全利用类耕地，应当优先采取农艺调控、替代种植、轮作、间作等措施，阻断或者减少污染物和其他有毒有害物质进入农作物可食部分，降低农产品超标风险。 对严格管控类耕地，主要采取种植结构调整或者按照国家计划经批准后进行退耕还林还草等风险管控措施。 对需要采取治理与修复工程措施的安全利用类或者严格管控类耕地，应当优先采取不影响农业生产、不降低土壤生产功能的生物修复措施，或辅助采取物理、化学治理与修复措施。"},{"i":20,"n":"第二十条","txt":"县级以上地方农业主管部门应当根据农用地土壤安全利用相关技术规范要求，结合当地实际情况，组织制定农用地安全利用方案，报所在地人民政府批准后实施，并上传农用地环境信息系统。 农用地安全利用方案应当包括以下风险管控措施： （一）针对主要农作物种类、品种和农作制度等具体情况，推广低积累品种替代、水肥调控、土壤调理等农艺调控措施，降低农产品有害物质超标风险； （二）定期开展农产品质量安全监测和调查评估，实施跟踪监测，根据监测和评估结果及时优化调整农艺调控措施。"},{"i":21,"n":"第二十一条","txt":"对需要采取治理与修复工程措施的受污染耕地，县级以上地方农业主管部门应当组织制定土壤污染治理与修复方案，报所在地人民政府批准后实施，并上传农用地环境信息系统。"},{"i":22,"n":"第二十二条","txt":"从事农用地土壤污染治理与修复活动的单位和个人应当采取必要措施防止产生二次污染，并防止对被修复土壤和周边环境造成新的污染。治理与修复过程中产生的废水、废气和固体废物，应当按照国家有关规定进行处理或者处置，并达到国家或者地方规定的环境保护标准和要求。"},{"i":23,"n":"第二十三条","txt":"县级以上地方环境保护主管部门应当对农用地土壤污染治理与修复的环境保护措施落实情况进行监督检查。 治理与修复活动结束后，县级以上地方农业主管部门应当委托第三方机构对治理与修复效果进行评估，评估结果上传农用地环境信息系统。"},{"i":24,"n":"第二十四条","txt":"县级以上地方农业主管部门应当对严格管控类耕地采取以下风险管控措施： （一）依法提出划定特定农产品禁止生产区域的建议； （二）会同有关部门按照国家退耕还林还草计划，组织制定种植结构调整或者退耕还林还草计划，报所在地人民政府批准后组织实施，并上传农用地环境信息系统。"},{"i":25,"n":"第二十五条","txt":"对威胁地下水、饮用水水源安全的严格管控类耕地，县级环境保护主管部门应当会同农业等主管部门制定环境风险管控方案，报同级人民政府批准后组织实施，并上传农用地环境信息系统。"},{"i":26,"n":"第二十六条","txt":"设区的市级以上地方环境保护主管部门应当定期对土壤环境重点监管企业周边农用地开展监测，监测结果作为环境执法和风险预警的重要依据，并上传农用地环境信息系统。 设区的市级以上地方环境保护主管部门应当督促土壤环境重点监管企业自行或者委托专业机构开展土壤环境监测，监测结果向社会公开，并上传农用地环境信息系统。"},{"i":27,"n":"第二十七条","txt":"县级以上环境保护主管部门和县级以上农业主管部门，有权对本行政区域内的农用地土壤污染防治相关活动进行现场检查。被检查单位应当予以配合，如实反映情况，提供必要的资料。实施现场检查的部门、机构及其工作人员应当为被检查单位保守商业秘密。"},{"i":28,"n":"第二十八条","txt":"突发环境事件可能造成农用地土壤污染的，县级以上地方环境保护主管部门应当及时会同农业主管部门对可能受到污染的农用地土壤进行监测，并根据监测结果及时向当地人民政府提出应急处置建议。"},{"i":29,"n":"第二十九条","txt":"违反本办法规定，受委托的专业机构在从事农用地土壤污染防治相关活动中，不负责任或者弄虚作假的，由县级以上地方环境保护主管部门、农业主管部门将该机构失信情况记入其环境信用记录，并通过企业信用信息系统向社会公开。"},{"i":30,"n":"第三十条","txt":"本办法自2017年11月1日起施行。"}],"nongyongbaomoguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为了防治农用薄膜污染，加强农用薄膜监督管理，保护和改善农业生态环境，根据《中华人民共和国土壤污染防治法》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称农用薄膜，是指用于农业生产的地面覆盖薄膜和棚膜。"},{"i":3,"n":"第三条","txt":"农用薄膜的生产、销售、使用、回收、再利用及其监督管理适用本办法。"},{"i":4,"n":"第四条","txt":"地方各级人民政府依法对本行政区域农用薄膜污染防治负责，组织、协调、督促有关部门依法履行农用薄膜污染防治监督管理职责。"},{"i":5,"n":"第五条","txt":"县级以上人民政府农业农村主管部门负责农用薄膜使用、回收监督管理工作，指导农用薄膜回收利用体系建设。 县级以上人民政府工业和信息化主管部门负责农用薄膜生产指导工作。 县级以上人民政府市场监管部门负责农用薄膜产品质量监督管理工作。 县级以上生态环境主管部门负责农用薄膜回收、再利用过程环境污染防治的监督管理工作。"},{"i":6,"n":"第六条","txt":"禁止生产、销售、使用国家明令禁止或者不符合强制性国家标准的农用薄膜。鼓励和支持生产、使用全生物降解农用薄膜。"},{"i":7,"n":"第七条","txt":"农用薄膜生产者应当落实国家关于农用薄膜行业规范的要求，执行农用薄膜相关标准，确保产品质量。"},{"i":8,"n":"第八条","txt":"农用薄膜生产者应当在每卷地膜、每延米棚膜上添加可辨识的企业标识，便于产品追溯和市场监管。"},{"i":9,"n":"第九条","txt":"农用薄膜生产者应当依法建立农用薄膜出厂销售记录制度，如实记录农用薄膜的名称、规格、数量、生产日期和批号、产品质量检验信息、购货人名称及其联系方式、销售日期等内容。出厂销售记录应当至少保存两年。"},{"i":10,"n":"第十条","txt":"出厂销售的农用薄膜产品应当依法附具产品质量检验合格证，标明推荐使用时间等内容。 农用薄膜应当在合格证明显位置标注“使用后请回收利用，减少环境污染”中文字样。全生物降解农用薄膜应当在合格证明显位置标注“全生物降解薄膜，注意使用条件”中文字样。"},{"i":11,"n":"第十一条","txt":"农用薄膜销售者应当查验农用薄膜产品的包装、标签、质量检验合格证，不得采购和销售未达到强制性国家标准的农用薄膜，不得将非农用薄膜销售给农用薄膜使用者。 农用薄膜销售者应当依法建立销售台账，如实记录销售农用薄膜的名称、规格、数量、生产者、生产日期和供货人名称及其联系方式、进货日期等内容。销售台账应当至少保存两年。"},{"i":12,"n":"第十二条","txt":"农用薄膜使用者应当按照产品标签标注的期限使用农用薄膜。农业生产企业、农民专业合作社等使用者应当依法建立农用薄膜使用记录，如实记录使用时间、地点、对象以及农用薄膜名称、用量、生产者、销售者等内容。农用薄膜使用记录应当至少保存两年。"},{"i":13,"n":"第十三条","txt":"县级以上人民政府农业农村主管部门应当采取措施，加强农用薄膜使用控制，开展农用薄膜适宜性覆盖评价，为农用薄膜使用者提供技术指导和服务，鼓励农用薄膜覆盖替代技术和产品的研发与示范推广，提高农用薄膜科学使用水平。"},{"i":14,"n":"第十四条","txt":"农用薄膜回收实行政府扶持、多方参与的原则，各地要采取措施，鼓励、支持单位和个人回收农用薄膜。"},{"i":15,"n":"第十五条","txt":"农用薄膜使用者应当在使用期限到期前捡拾田间的非全生物降解农用薄膜废弃物，交至回收网点或回收工作者，不得随意弃置、掩埋或者焚烧。"},{"i":16,"n":"第十六条","txt":"农用薄膜生产者、销售者、回收网点、废旧农用薄膜回收再利用企业或其他组织等应当开展合作，采取多种方式，建立健全农用薄膜回收利用体系，推动废旧农用薄膜回收、处理和再利用。"},{"i":17,"n":"第十七条","txt":"农用薄膜回收网点和回收再利用企业应当依法建立回收台账，如实记录废旧农用薄膜的重量、体积、杂质、缴膜人名称及其联系方式、回收时间等内容。回收台账应当至少保存两年。"},{"i":18,"n":"第十八条","txt":"鼓励研发、推广农用薄膜回收技术与机械，开展废旧农用薄膜再利用。"},{"i":19,"n":"第十九条","txt":"支持废旧农用薄膜再利用企业按照规定享受用地、用电、用水、信贷、税收等优惠政策，扶持从事废旧农用薄膜再利用的社会化服务组织和企业。"},{"i":20,"n":"第二十条","txt":"农用薄膜回收再利用企业应当依法做好回收再利用厂区和周边环境的环境保护工作，避免二次污染。"},{"i":21,"n":"第二十一条","txt":"建立农用薄膜残留监测制度，县级以上地方人民政府农业农村主管部门应当定期开展本行政区域的农用薄膜残留监测。"},{"i":22,"n":"第二十二条","txt":"建立农用薄膜市场监管制度，县级以上地方人民政府市场监管部门应当定期开展本行政区域的农用薄膜质量监督检查。"},{"i":23,"n":"第二十三条","txt":"生产、销售农用薄膜不符合强制性国家标准的，依照《中华人民共和国产品质量法》等法律、行政法规的规定查处，依法依规记入信用记录并予以公示。 政府招标采购的农用薄膜应当符合强制性国家标准，依法限制失信企业参与政府招标采购。"},{"i":24,"n":"第二十四条","txt":"农用薄膜生产者、销售者、使用者未按照规定回收农用薄膜的，依照《中华人民共和国土壤污染防治法》第八十八条规定处罚。"},{"i":25,"n":"第二十五条","txt":"本办法自2020年9月1日起施行。"}],"nongyongbaomoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了防治农用薄膜污染，加强农用薄膜监督管理，保护和改善农业生态环境，根据《中华人民共和国土壤污染防治法》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称农用薄膜，是指用于农业生产的地面覆盖薄膜和棚膜。"},{"i":3,"n":"第三条","txt":"农用薄膜的生产、销售、使用、回收、再利用及其监督管理适用本办法。"},{"i":4,"n":"第四条","txt":"地方各级人民政府依法对本行政区域农用薄膜污染防治负责，组织、协调、督促有关部门依法履行农用薄膜污染防治监督管理职责。"},{"i":5,"n":"第五条","txt":"县级以上人民政府农业农村主管部门负责农用薄膜使用、回收监督管理工作，指导农用薄膜回收利用体系建设。 县级以上人民政府工业和信息化主管部门负责农用薄膜生产指导工作。 县级以上人民政府市场监管部门负责农用薄膜产品质量监督管理工作。 县级以上生态环境主管部门负责农用薄膜回收、再利用过程环境污染防治的监督管理工作。"},{"i":6,"n":"第六条","txt":"禁止生产、销售、使用国家明令禁止或者不符合强制性国家标准的农用薄膜。鼓励和支持生产、使用全生物降解农用薄膜。"},{"i":7,"n":"第七条","txt":"农用薄膜生产者应当落实国家关于农用薄膜行业规范的要求，执行农用薄膜相关标准，确保产品质量。"},{"i":8,"n":"第八条","txt":"农用薄膜生产者应当在每卷地膜、每延米棚膜上添加可辨识的企业标识，便于产品追溯和市场监管。"},{"i":9,"n":"第九条","txt":"农用薄膜生产者应当依法建立农用薄膜出厂销售记录制度，如实记录农用薄膜的名称、规格、数量、生产日期和批号、产品质量检验信息、购货人名称及其联系方式、销售日期等内容。出厂销售记录应当至少保存两年。"},{"i":10,"n":"第十条","txt":"出厂销售的农用薄膜产品应当依法附具产品质量检验合格证，标明推荐使用时间等内容。 农用薄膜应当在合格证明显位置标注“使用后请回收利用，减少环境污染”中文字样。全生物降解农用薄膜应当在合格证明显位置标注“全生物降解薄膜，注意使用条件”中文字样。"},{"i":11,"n":"第十一条","txt":"农用薄膜销售者应当查验农用薄膜产品的包装、标签、质量检验合格证，不得采购和销售未达到强制性国家标准的农用薄膜，不得将非农用薄膜销售给农用薄膜使用者。 农用薄膜销售者应当依法建立销售台账，如实记录销售农用薄膜的名称、规格、数量、生产者、生产日期和供货人名称及其联系方式、进货日期等内容。销售台账应当至少保存两年。"},{"i":12,"n":"第十二条","txt":"农用薄膜使用者应当按照产品标签标注的期限使用农用薄膜。农业生产企业、农民专业合作社等使用者应当依法建立农用薄膜使用记录，如实记录使用时间、地点、对象以及农用薄膜名称、用量、生产者、销售者等内容。农用薄膜使用记录应当至少保存两年。"},{"i":13,"n":"第十三条","txt":"县级以上人民政府农业农村主管部门应当采取措施，加强农用薄膜使用控制，开展农用薄膜适宜性覆盖评价，为农用薄膜使用者提供技术指导和服务，鼓励农用薄膜覆盖替代技术和产品的研发与示范推广，提高农用薄膜科学使用水平。"},{"i":14,"n":"第十四条","txt":"农用薄膜回收实行政府扶持、多方参与的原则，各地要采取措施，鼓励、支持单位和个人回收农用薄膜。"},{"i":15,"n":"第十五条","txt":"农用薄膜使用者应当在使用期限到期前捡拾田间的非全生物降解农用薄膜废弃物，交至回收网点或回收工作者，不得随意弃置、掩埋或者焚烧。"},{"i":16,"n":"第十六条","txt":"农用薄膜生产者、销售者、回收网点、废旧农用薄膜回收再利用企业或其他组织等应当开展合作，采取多种方式，建立健全农用薄膜回收利用体系，推动废旧农用薄膜回收、处理和再利用。"},{"i":17,"n":"第十七条","txt":"农用薄膜回收网点和回收再利用企业应当依法建立回收台账，如实记录废旧农用薄膜的重量、体积、杂质、缴膜人名称及其联系方式、回收时间等内容。回收台账应当至少保存两年。"},{"i":18,"n":"第十八条","txt":"鼓励研发、推广农用薄膜回收技术与机械，开展废旧农用薄膜再利用。"},{"i":19,"n":"第十九条","txt":"支持废旧农用薄膜再利用企业按照规定享受用地、用电、用水、信贷、税收等优惠政策，扶持从事废旧农用薄膜再利用的社会化服务组织和企业。"},{"i":20,"n":"第二十条","txt":"农用薄膜回收再利用企业应当依法做好回收再利用厂区和周边环境的环境保护工作，避免二次污染。"},{"i":21,"n":"第二十一条","txt":"建立农用薄膜残留监测制度，县级以上地方人民政府农业农村主管部门应当定期开展本行政区域的农用薄膜残留监测。"},{"i":22,"n":"第二十二条","txt":"建立农用薄膜市场监管制度，县级以上地方人民政府市场监管部门应当定期开展本行政区域的农用薄膜质量监督检查。"},{"i":23,"n":"第二十三条","txt":"生产、销售农用薄膜不符合强制性国家标准的，依照《中华人民共和国产品质量法》等法律、行政法规的规定查处，依法依规记入信用记录并予以公示。 政府招标采购的农用薄膜应当符合强制性国家标准，依法限制失信企业参与政府招标采购。"},{"i":24,"n":"第二十四条","txt":"农用薄膜生产者、销售者、使用者未按照规定回收农用薄膜的，依照《中华人民共和国土壤污染防治法》第八十八条规定处罚。"},{"i":25,"n":"第二十五条","txt":"本办法自2020年9月1日起施行。"}],"nongtianjianshexiangmuguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范农田建设项目管理，确保项目建设质量，实现项目预期目标，依据《中华人民共和国农业法》《基本农田保护条例》《政府投资条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称农田建设，是指各级人民政府为支持农业可持续发展，改善农田基础设施条件，提高农田综合生产能力，贯彻落实“藏粮于地、藏粮于技”战略，安排资金对农田进行综合治理和保护的活动。本办法所称农田建设项目，是指为开展农田建设而实施的高标准农田建设等项目类型。"},{"i":3,"n":"第三条","txt":"农田建设实行集中统一管理体制，统一规划布局、建设标准、组织实施、验收评价、上图入库。"},{"i":4,"n":"第四条","txt":"农业农村部负责管理和指导全国农田建设工作，制定农田建设政策、规章制度，牵头组织编制农田建设规划，建立全国农田建设项目评审专家库，统筹安排农田建设任务，管理农田建设项目，对各地农田建设项目管理进行监督评价。 省级人民政府农业农村主管部门负责指导本地区农田建设工作，牵头拟订本地区农田建设政策和规划，组织完成中央下达的建设任务，提出本地区农田建设年度任务方案，建立省级农田建设项目评审专家库，审批项目初步设计文件，组织开展项目竣工验收和监督检查，确定本地区各级人民政府农业农村主管部门农田建设项目管理职责，对本地区农田建设项目进行管理。 地（市、州、盟）级人民政府农业农村主管部门负责指导本地区农田建设工作，承担省级下放或委托的项目初步设计审批、竣工验收等职责，对本地区农田建设项目进行监督检查和统计汇总等。 县级人民政府农业农村主管部门负责本地区农田建设工作，制定县域农田建设规划，建立项目库，组织"},{"i":5,"n":"第五条","txt":"农田建设项目遵循规划编制、前期准备、申报审批、计划管理、组织实施、竣工验收、监督评价等管理程序。"},{"i":6,"n":"第六条","txt":"农田建设项目坚持规划先行。规划应遵循突出重点、集中连片、整体推进、分期建设的原则，明确农田建设区域布局，优先扶持粮食生产功能区和重要农产品生产保护区（以下简称“两区”），把“两区”耕地全部建成高标准农田。"},{"i":7,"n":"第七条","txt":"农业农村部负责牵头组织制定全国农田建设规划，报经国务院批准后实施。省级人民政府农业农村主管部门根据全国农田建设规划，研究编制本省农田建设规划，经省级人民政府批准后发布实施，并报农业农村部备案。"},{"i":8,"n":"第八条","txt":"县级人民政府农业农村主管部门对接省级农田建设规划任务，牵头组织编制本级农田建设规划，并与当地水利、自然资源等部门规划衔接。 县级农田建设规划要根据区域水土资源条件，按流域或连片区域规划项目，落实到地块，形成规划项目布局图和项目库（单个项目达到项目可行性研究深度）。县级规划经本级人民政府批准后发布实施，并报省、市两级人民政府农业农村主管部门备案。"},{"i":9,"n":"第九条","txt":"省级人民政府农业农村主管部门汇总县级项目库，形成省级农田建设项目库。"},{"i":10,"n":"第十条","txt":"农田建设项目实行常态化申报，纳入项目库的项目，在征求项目区农村集体经济组织和农户意见后，在完成项目区实地测绘和勘察的基础上，编制项目初步设计文件。"},{"i":11,"n":"第十一条","txt":"农田建设项目初步设计文件由县级人民政府农业农村主管部门牵头组织编制。初步设计文件包括初步设计报告、设计图、概算书等材料。"},{"i":12,"n":"第十二条","txt":"初步设计文件应由具有相应勘察、设计资质的机构进行编制，并达到规定的深度。"},{"i":13,"n":"第十三条","txt":"县级人民政府农业农村主管部门依据规划任务、工作实际等情况，将项目初步设计文件报送上级人民政府农业农村主管部门。省级人民政府农业农村主管部门会同有关部门，结合本地实际，按照地方法规要求，确定项目审批主体。"},{"i":14,"n":"第十四条","txt":"省、受托的地（市、州、盟）组织或委托第三方机构开展初步设计文件评审工作。评审专家从评审专家库中抽取。评审可行的项目要向社会公示（涉及国家秘密的内容除外），公示期一般不少于5个工作日。公示无异议的项目要适时批复。"},{"i":15,"n":"第十五条","txt":"省级人民政府农业农村主管部门依据本省农田建设规划以及前期工作情况，以县为单元向农业农村部申报年度建设任务。农业农村部根据全国农田建设规划并结合省级监督评价等情况，下达年度农田建设任务。"},{"i":16,"n":"第十六条","txt":"地方各级人民政府农业农村主管部门应当依据经批复的项目初步设计文件，编制、汇总农田建设项目年度实施计划。省级人民政府农业农村主管部门负责批复本地区农田建设项目年度实施计划，并报农业农村部备案。"},{"i":17,"n":"第十七条","txt":"农田建设项目应按照批复的初步设计文件和年度实施计划组织实施，按期完工，并达到项目设计目标。建设期一般为1—2年。"},{"i":18,"n":"第十八条","txt":"农田建设项目应当推行项目法人制，按照国家有关招标投标、政府采购、合同管理、工程监理、资金和项目公示等规定执行。省级人民政府农业农村主管部门根据本地区实际情况，对具备条件的新型经营主体或农村集体经济组织自主组织实施的农田建设项目，可简化操作程序，以先建后补等方式实施，县级人民政府农业农村主管部门应选定工程监理单位监督实施。"},{"i":19,"n":"第十九条","txt":"组织开展农田建设应坚持农民自愿、民主方式，调动农民主动参与项目规划、建设和管护等积极性。鼓励在项目建设中开展耕地小块并大块的宜机化整理。"},{"i":20,"n":"第二十条","txt":"参与项目建设的工程施工、监理、审计及专业化管理等单位或机构应具有相应资质。"},{"i":21,"n":"第二十一条","txt":"项目实施应当严格按照年度实施计划和初步设计批复执行，不得擅自调整或终止。确需进行调整或终止的，按照“谁审批、谁调整”的原则，依据有关规定办理审核批复。项目调整应确保批复的建设任务不减少，建设标准不降低。 终止项目和省级部门批复调整的项目应当报农业农村部备案。"},{"i":22,"n":"第二十二条","txt":"农田建设项目执行定期调度和统计调查制度，各级人民政府农业农村主管部门应按照有关要求，及时汇总上报建设进度，定期报送项目年度实施计划完成情况。"},{"i":23,"n":"第二十三条","txt":"农田建设项目按照“谁审批、谁验收”的原则，由审批项目初步设计单位组织竣工验收。"},{"i":24,"n":"第二十四条","txt":"申请竣工验收的项目应当具备下列条件： （一）完成批复的初步设计文件中各项建设内容； （二）技术文件材料分类立卷，技术档案和施工管理资料齐全、完整； （三）主要设备及配套设施运行正常，达到项目设计目标； （四）各单项工程已经设计单位、施工单位、监理单位和建设单位等四方验收； （五）编制竣工决算，并经有资质的机构审计。"},{"i":25,"n":"第二十五条","txt":"县级人民政府农业农村主管部门组织初验，初验合格后，提出竣工验收申请报告。 竣工验收申请报告应依照竣工验收条件对项目实施情况进行分类总结，并附初验意见、竣工决算审计报告等。"},{"i":26,"n":"第二十六条","txt":"项目初步设计审批部门在收到项目竣工验收申请报告后，及时组织竣工验收。由地（市、州、盟）级人民政府农业农村主管部门组织验收的项目，验收结果应报省级人民政府农业农村主管部门备案。省级每年应对不低于10%的当年竣工验收项目进行抽查。 对竣工验收合格的项目，核发由农业农村部统一格式的竣工验收合格证书。"},{"i":27,"n":"第二十七条","txt":"农田建设项目全部竣工验收后，要在项目区设立统一规范的公示标牌和标志，将农田建设项目建设单位、设计单位、施工单位、监理单位、项目年度、建设区域、投资规模以及管护主体等信息进行公示，接受社会和群众监督。"},{"i":28,"n":"第二十八条","txt":"项目竣工验收后，应及时按有关规定办理资产交付手续。按照“谁受益、谁管护，谁使用、谁管护”的原则明确工程管护主体，拟定管护制度，落实管护责任，保证工程在设计使用期限内正常运行。"},{"i":29,"n":"第二十九条","txt":"项目竣工验收后，县级人民政府农业农村主管部门应按照有关规定对项目档案进行收集、整理、组卷、存档。"},{"i":30,"n":"第三十条","txt":"加强农田建设新增耕地核定工作，并按相关要求将新增耕地指标调剂收益优先用于高标准农田建设。"},{"i":31,"n":"第三十一条","txt":"各级人民政府农业农村主管部门应当按照《中华人民共和国政府信息公开条例》等有关规定，公开农田建设项目建设相关信息，接受社会监督。"},{"i":32,"n":"第三十二条","txt":"各级人民政府农业农村主管部门应当制定、实施内部控制制度，对农田建设项目管理风险进行预防和控制，加强事前、事中、事后的监督检查，发现问题及时纠正。"},{"i":33,"n":"第三十三条","txt":"各级人民政府农业农村主管部门应当加强对农田建设项目的监督评价。农业农村部结合粮食安全省长责任制考核，采取直接组织或委托第三方的方式，对各省农田建设项目开展监督评价和检查。"},{"i":34,"n":"第三十四条","txt":"农田建设项目实施过程中发现存在严重违法违规问题的，各级人民政府农业农村主管部门应当及时终止项目，协助有关部门追回项目财政资金，并依法依规追究相关人员责任。"},{"i":35,"n":"第三十五条","txt":"各级人民政府农业农村主管部门应当积极配合相关部门的审计和监督检查，对发现的问题及时整改。"},{"i":36,"n":"第三十六条","txt":"各级人民政府农业农村主管部门应当及时在信息平台上填报农田建设项目的任务下达、初步设计审批、实施管理、竣工验收等工作信息。 县级人民政府农业农村主管部门应当在项目竣工验收后，对项目建档立册、上图入库并与规划图衔接。"},{"i":37,"n":"第三十七条","txt":"省级人民政府农业农村主管部门根据本办法，结合本地区的实际情况，制定具体实施办法，报农业农村部备案。"},{"i":38,"n":"第三十八条","txt":"本办法为农田建设项目管理程序性规定，涉及资金管理和中央预算内投资计划管理相关事宜按照相关规定执行。"},{"i":39,"n":"第三十九条","txt":"在本办法施行之前，原由相关部门已经批复的农田建设项目，仍按原规定执行。"},{"i":40,"n":"第四十条","txt":"本办法自2019年10月1日起施行。"}],"nongyaobaozhuangfeiqiwuhuishouchuliguanlibanfa":[{"i":1,"n":"第一条","txt":"为了防治农药包装废弃物污染，保障公众健康，保护生态环境，根据《中华人民共和国土壤污染防治法》《中华人民共和国固体废物污染环境防治法》《农药管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于农业生产过程中农药包装废弃物的回收处理活动及其监督管理。"},{"i":3,"n":"第三条","txt":"本办法所称农药包装废弃物，是指农药使用后被废弃的与农药直接接触或含有农药残余物的包装物，包括瓶、罐、桶、袋等。"},{"i":4,"n":"第四条","txt":"地方各级人民政府依照《中华人民共和国土壤污染防治法》的规定，组织、协调、督促相关部门依法履行农药包装废弃物回收处理监督管理职责，建立健全回收处理体系，统筹推进农药包装废弃物回收处理等设施建设。"},{"i":5,"n":"第五条","txt":"县级以上地方人民政府农业农村主管部门负责本行政区域内农药生产者、经营者、使用者履行农药包装废弃物回收处理义务的监督管理。 县级以上地方人民政府生态环境主管部门负责本行政区域内农药包装废弃物回收处理活动环境污染防治的监督管理。"},{"i":6,"n":"第六条","txt":"农药生产者（含向中国出口农药的企业）、经营者和使用者应当积极履行农药包装废弃物回收处理义务，及时回收农药包装废弃物并进行处理。"},{"i":7,"n":"第七条","txt":"国家鼓励和支持行业协会在农药包装废弃物回收处理中发挥组织协调、技术指导、提供服务等作用，鼓励和扶持专业化服务机构开展农药包装废弃物回收处理。"},{"i":8,"n":"第八条","txt":"县级以上地方人民政府农业农村和生态环境主管部门应当采取多种形式，开展农药包装废弃物回收处理的宣传和教育，指导农药生产者、经营者和专业化服务机构开展农药包装废弃物的回收处理。 鼓励农药生产者、经营者和社会组织开展农药包装废弃物回收处理的宣传和培训。"},{"i":9,"n":"第九条","txt":"县级以上地方人民政府农业农村主管部门应当调查监测本行政区域内农药包装废弃物产生情况，指导建立农药包装废弃物回收体系，合理布设县、乡、村农药包装废弃物回收站（点），明确管理责任。"},{"i":10,"n":"第十条","txt":"农药生产者、经营者应当按照“谁生产、经营，谁回收”的原则，履行相应的农药包装废弃物回收义务。农药生产者、经营者可以协商确定农药包装废弃物回收义务的具体履行方式。 农药经营者应当在其经营场所设立农药包装废弃物回收装置，不得拒收其销售农药的包装废弃物。 农药生产者、经营者应当采取有效措施，引导农药使用者及时交回农药包装废弃物。"},{"i":11,"n":"第十一条","txt":"农药使用者应当及时收集农药包装废弃物并交回农药经营者或农药包装废弃物回收站（点），不得随意丢弃。 农药使用者在施用过程中，配药时应当通过清洗等方式充分利用包装物中的农药，减少残留农药。 鼓励有条件的地方，探索建立检查员等农药包装废弃物清洗审验机制。"},{"i":12,"n":"第十二条","txt":"农药经营者和农药包装废弃物回收站（点）应当建立农药包装废弃物回收台账，记录农药包装废弃物的数量和去向信息。回收台账应当保存两年以上。"},{"i":13,"n":"第十三条","txt":"农药生产者应当改进农药包装，便于清洗和回收。 国家鼓励农药生产者使用易资源化利用和易处置包装物、水溶性高分子包装物或者在环境中可降解的包装物，逐步淘汰铝箔包装物。鼓励使用便于回收的大容量包装物。"},{"i":14,"n":"第十四条","txt":"农药经营者和农药包装废弃物回收站（点）应当加强相关设施设备、场所的管理和维护，对收集的农药包装废弃物进行妥善贮存，不得擅自倾倒、堆放、遗撒农药包装废弃物。"},{"i":15,"n":"第十五条","txt":"运输农药包装废弃物应当采取防止污染环境的措施，不得丢弃、遗撒农药包装废弃物，运输工具应当满足防雨、防渗漏、防遗撒要求。"},{"i":16,"n":"第十六条","txt":"国家鼓励和支持对农药包装废弃物进行资源化利用；资源化利用以外的，应当依法依规进行填埋、焚烧等无害化处置。 资源化利用按照“风险可控、定点定向、全程追溯”的原则，由省级人民政府农业农村主管部门会同生态环境主管部门结合本地实际需要确定资源化利用单位，并向社会公布。资源化利用不得用于制造餐饮用具、儿童玩具等产品，防止危害人体健康。资源化利用单位不得倒卖农药包装废弃物。 县级以上地方人民政府农业农村主管部门、生态环境主管部门指导资源化利用单位利用处置回收的农药包装废弃物。"},{"i":17,"n":"第十七条","txt":"农药包装废弃物处理费用由相应的农药生产者和经营者承担；农药生产者、经营者不明确的，处理费用由所在地的县级人民政府财政列支。 鼓励地方有关部门加大资金投入，给予补贴、优惠措施等，支持农药包装废弃物回收、贮存、运输、处置和资源化利用活动。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府农业农村主管部门或生态环境主管部门未按规定履行职责的，对直接负责的主管人员和其他直接责任人依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"农药生产者、经营者、使用者未按规定履行农药包装废弃物回收处理义务的，由地方人民政府农业农村主管部门按照《中华人民共和国土壤污染防治法》第八十八条规定予以处罚。"},{"i":20,"n":"第二十条","txt":"农药包装废弃物回收处理过程中，造成环境污染的，由地方人民政府生态环境主管部门按照《中华人民共和国固体废物污染环境防治法》等法律的有关规定予以处罚。"},{"i":21,"n":"第二十一条","txt":"农药经营者和农药包装废弃物回收站（点）未按规定建立农药包装废弃物回收台账的，由地方人民政府农业农村主管部门责令改正；拒不改正或者情节严重的，可处二千元以上二万元以下罚款。"},{"i":22,"n":"第二十二条","txt":"本办法所称的专业化服务机构，指从事农药包装废弃物回收处理等经营活动的机构。"},{"i":23,"n":"第二十三条","txt":"本办法自2020年10月1日起施行。"}],"nongyaobiaoqianheshuomingshuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范农药标签和说明书的管理，保证农药使用的安全，根据《农药管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中国境内经营、使用的农药产品应当在包装物表面印制或者贴有标签。产品包装尺寸过小、标签无法标注本办法规定内容的，应当附具相应的说明书。"},{"i":3,"n":"第三条","txt":"本办法所称标签和说明书，是指农药包装物上或者附于农药包装物的，以文字、图形、符号说明农药内容的一切说明物。"},{"i":4,"n":"第四条","txt":"农药登记申请人应当在申请农药登记时提交农药标签样张及电子文档。附具说明书的农药，应当同时提交说明书样张及电子文档。"},{"i":5,"n":"第五条","txt":"农药标签和说明书由农业部核准。农业部在批准农药登记时公布经核准的农药标签和说明书的内容、核准日期。"},{"i":6,"n":"第六条","txt":"标签和说明书的内容应当真实、规范、准确，其文字、符号、图形应当易于辨认和阅读，不得擅自以粘贴、剪切、涂改等方式进行修改或者补充。"},{"i":7,"n":"第七条","txt":"标签和说明书应当使用国家公布的规范化汉字，可以同时使用汉语拼音或者其他文字。其他文字表述的含义应当与汉字一致。"},{"i":8,"n":"第八条","txt":"农药标签应当标注下列内容： （一）农药名称、剂型、有效成分及其含量； （二）农药登记证号、产品质量标准号以及农药生产许可证号； （三）农药类别及其颜色标志带、产品性能、毒性及其标识； （四）使用范围、使用方法、剂量、使用技术要求和注意事项； （五）中毒急救措施； （六）储存和运输方法； （七）生产日期、产品批号、质量保证期、净含量； （八）农药登记证持有人名称及其联系方式； （九）可追溯电子信息码； （十）像形图； （十一）农业部要求标注的其他内容。"},{"i":9,"n":"第九条","txt":"除第八条规定内容外，下列农药标签标注内容还应当符合相应要求： （一）原药（母药）产品应当注明“本品是农药制剂加工的原材料，不得用于农作物或者其他场所。”且不标注使用技术和使用方法。但是，经登记批准允许直接使用的除外； （二）限制使用农药应当标注“限制使用”字样，并注明对使用的特别限制和特殊要求； （三）用于食用农产品的农药应当标注安全间隔期，但属于第十八条第三款所列情形的除外； （四）杀鼠剂产品应当标注规定的杀鼠剂图形； （五）直接使用的卫生用农药可以不标注特征颜色标志带； （六）委托加工或者分装农药的标签还应当注明受托人的农药生产许可证号、受托人名称及其联系方式和加工、分装日期； （七）向中国出口的农药可以不标注农药生产许可证号，应当标注其境外生产地，以及在中国设立的办事机构或者代理机构的名称及联系方式。"},{"i":10,"n":"第十条","txt":"农药标签过小，无法标注规定全部内容的，应当至少标注农药名称、有效成分含量、剂型、农药登记证号、净含量、生产日期、质量保证期等内容，同时附具说明书。说明书应当标注规定的全部内容。 登记的使用范围较多，在标签中无法全部标注的，可以根据需要，在标签中标注部分使用范围，但应当附具说明书并标注全部使用范围。"},{"i":11,"n":"第十一条","txt":"农药名称应当与农药登记证的农药名称一致。"},{"i":12,"n":"第十二条","txt":"联系方式包括农药登记证持有人、企业或者机构的住所和生产地的地址、邮政编码、联系电话、传真等。"},{"i":13,"n":"第十三条","txt":"生产日期应当按照年、月、日的顺序标注，年份用四位数字表示，月、日分别用两位数表示。产品批号包含生产日期的，可以与生产日期合并表示。"},{"i":14,"n":"第十四条","txt":"质量保证期应当规定在正常条件下的质量保证期限，质量保证期也可以用有效日期或者失效日期表示。"},{"i":15,"n":"第十五条","txt":"净含量应当使用国家法定计量单位表示。特殊农药产品，可根据其特性以适当方式表示。"},{"i":16,"n":"第十六条","txt":"产品性能主要包括产品的基本性质、主要功能、作用特点等。对农药产品性能的描述应当与农药登记批准的使用范围、使用方法相符。"},{"i":17,"n":"第十七条","txt":"使用范围主要包括适用作物或者场所、防治对象。 使用方法是指施用方式。 使用剂量以每亩使用该产品的制剂量或者稀释倍数表示。种子处理剂的使用剂量采用每100公斤种子使用该产品的制剂量表示。特殊用途的农药，使用剂量的表述应当与农药登记批准的内容一致。"},{"i":18,"n":"第十八条","txt":"使用技术要求主要包括施用条件、施药时期、次数、最多使用次数，对当茬作物、后茬作物的影响及预防措施，以及后茬仅能种植的作物或者后茬不能种植的作物、间隔时间等。 限制使用农药，应当在标签上注明施药后设立警示标志，并明确人畜允许进入的间隔时间。 安全间隔期及农作物每个生产周期的最多使用次数的标注应当符合农业生产、农药使用实际。下列农药标签可以不标注安全间隔期： （一）用于非食用作物的农药； （二）拌种、包衣、浸种等用于种子处理的农药； （三）用于非耕地(牧场除外)的农药； （四）用于苗前土壤处理剂的农药； （五）仅在农作物苗期使用一次的农药； （六）非全面撒施使用的杀鼠剂； （七）卫生用农药； （八）其他特殊情形。"},{"i":19,"n":"第十九条","txt":"毒性分为剧毒、高毒、中等毒、低毒、微毒五个级别，分别用“”标识和“剧毒”字样、“”标识和“高毒”字样、“”标识和“中等毒”字样、“”标识、“微毒”字样标注。标识应当为黑色，描述文字应当为红色。 由剧毒、高毒农药原药加工的制剂产品，其毒性级别与原药的最高毒性级别不a一致时，应当同时以括号标明其所使用的原药的最高毒性级别。"},{"i":20,"n":"第二十条","txt":"注意事项应当标注以下内容： （一）对农作物容易产生药害，或者对病虫容易产生抗性的，应当标明主要原因和预防方法； （二）对人畜、周边作物或者植物、有益生物（如蜜蜂、鸟、蚕、蚯蚓、天敌及鱼、水蚤等水生生物）和环境容易产生不利影响的，应当明确说明，并标注使用时的预防措施、施用器械的清洗要求； （三）已知与其他农药等物质不能混合使用的，应当标明； （四）开启包装物时容易出现药剂撒漏或者人身伤害的，应当标明正确的开启方法； （五）施用时应当采取的安全防护措施； （六）国家规定禁止的使用范围或者使用方法等。"},{"i":21,"n":"第二十一条","txt":"中毒急救措施应当包括中毒症状及误食、吸入、眼睛溅入、皮肤沾附农药后的急救和治疗措施等内容。 有专用解毒剂的，应当标明，并标注医疗建议。 剧毒、高毒农药应当标明中毒急救咨询电话。"},{"i":22,"n":"第二十二条","txt":"储存和运输方法应当包括储存时的光照、温度、湿度、通风等环境条件要求及装卸、运输时的注意事项，并标明“置于儿童接触不到的地方”、“不能与食品、饮料、粮食、饲料等混合储存”等警示内容。"},{"i":23,"n":"第二十三条","txt":"农药类别应当采用相应的文字和特征颜色标志带表示。 不同类别的农药采用在标签底部加一条与底边平行的、不褪色的特征颜色标志带表示。 除草剂用“除草剂”字样和绿色带表示；杀虫(螨、软体动物)剂用“杀虫剂”或者“杀螨剂”、“杀软体动物剂”字样和红色带表示；杀菌(线虫)剂用“杀菌剂”或者“杀线虫剂”字样和黑色带表示；植物生长调节剂用“植物生长调节剂”字样和深黄色带表示；杀鼠剂用“杀鼠剂”字样和蓝色带表示；杀虫/杀菌剂用“杀虫/杀菌剂”字样、红色和黑色带表示。农药类别的描述文字应当镶嵌在标志带上，颜色与其形成明显反差。其他农药可以不标注特征颜色标志带。"},{"i":24,"n":"第二十四条","txt":"可追溯电子信息码应当以二维码等形式标注，能够扫描识别农药名称、农药登记证持有人名称等信息。信息码不得含有违反本办法规定的文字、符号、图形。 可追溯电子信息码格式及生成要求由农业部另行制定。"},{"i":25,"n":"第二十五条","txt":"像形图包括储存像形图、操作像形图、忠告像形图、警告像形图。像形图应当根据产品安全使用措施的需要选择，并按照产品实际使用的操作要求和顺序排列，但不得代替标签中必要的文字说明。"},{"i":26,"n":"第二十六条","txt":"标签和说明书不得标注任何带有宣传、广告色彩的文字、符号、图形，不得标注企业获奖和荣誉称号。法律、法规或者规章另有规定的，从其规定。"},{"i":27,"n":"第二十七条","txt":"每个农药最小包装应当印制或者贴有独立标签，不得与其他农药共用标签或者使用同一标签。"},{"i":28,"n":"第二十八条","txt":"标签上汉字的字体高度不得小于1.8毫米。"},{"i":29,"n":"第二十九条","txt":"农药名称应当显著、突出，字体、字号、颜色应当一致，并符合以下要求： （一）对于横版标签，应当在标签上部三分之一范围内中间位置显著标出；对于竖版标签，应当在标签右部三分之一范围内中间位置显著标出； （二）不得使用草书、篆书等不易识别的字体，不得使用斜体、中空、阴影等形式对字体进行修饰； （三）字体颜色应当与背景颜色形成强烈反差； （四）除因包装尺寸的限制无法同行书写外，不得分行书写。 除“限制使用”字样外，标签其他文字内容的字号不得超过农药名称的字号。"},{"i":30,"n":"第三十条","txt":"有效成分及其含量和剂型应当醒目标注在农药名称的正下方（横版标签）或者正左方（竖版标签）相邻位置（直接使用的卫生用农药可以不再标注剂型名称），字体高度不得小于农药名称的二分之一。 混配制剂应当标注总有效成分含量以及各有效成分的中文通用名称和含量。各有效成分的中文通用名称及含量应当醒目标注在农药名称的正下方（横版标签）或者正左方（竖版标签），字体、字号、颜色应当一致，字体高度不得小于农药名称的二分之一。"},{"i":31,"n":"第三十一条","txt":"农药标签和说明书不得使用未经注册的商标。 标签使用注册商标的，应当标注在标签的四角，所占面积不得超过标签面积的九分之一，其文字部分的字号不得大于农药名称的字号。"},{"i":32,"n":"第三十二条","txt":"毒性及其标识应当标注在有效成分含量和剂型的正下方（横版标签）或者正左方（竖版标签），并与背景颜色形成强烈反差。 像形图应当用黑白两种颜色印刷，一般位于标签底部，其尺寸应当与标签的尺寸相协调。 安全间隔期及施药次数应当醒目标注，字号大于使用技术要求其他文字的字号。"},{"i":33,"n":"第三十三条","txt":"“限制使用”字样，应当以红色标注在农药标签正面右上角或者左上角，并与背景颜色形成强烈反差，其字号不得小于农药名称的字号。"},{"i":34,"n":"第三十四条","txt":"标签中不得含有虚假、误导使用者的内容，有下列情形之一的，属于虚假、误导使用者的内容： （一）误导使用者扩大使用范围、加大用药剂量或者改变使用方法的； （二）卫生用农药标注适用于儿童、孕妇、过敏者等特殊人群的文字、符号、图形等； （三）夸大产品性能及效果、虚假宣传、贬低其他产品或者与其他产品相比较，容易给使用者造成误解或者混淆的； （四）利用任何单位或者个人的名义、形象作证明或者推荐的； （五）含有保证高产、增产、铲除、根除等断言或者保证，含有速效等绝对化语言和表示的； （六）含有保险公司保险、无效退款等承诺性语言的； （七）其他虚假、误导使用者的内容。"},{"i":35,"n":"第三十五条","txt":"标签和说明书上不得出现未经登记批准的使用范围或者使用方法的文字、图形、符号。"},{"i":36,"n":"第三十六条","txt":"除本办法规定应当标注的农药登记证持有人、企业或者机构名称及其联系方式之外，标签不得标注其他任何企业或者机构的名称及其联系方式。"},{"i":37,"n":"第三十七条","txt":"产品毒性、注意事项、技术要求等与农药产品安全性、有效性有关的标注内容经核准后不得擅自改变，许可证书编号、生产日期、企业联系方式等产品证明性、企业相关性信息由企业自主标注，并对真实性负责。"},{"i":38,"n":"第三十八条","txt":"农药登记证持有人变更标签或者说明书有关产品安全性和有效性内容的，应当向农业部申请重新核准。 农业部应当在三个月内作出核准决定。"},{"i":39,"n":"第三十九条","txt":"农业部根据监测与评价结果等信息，可以要求农药登记证持有人修改标签和说明书，并重新核准。 农药登记证载明事项发生变化的，农业部在作出准予农药登记变更决定的同时，对其农药标签予以重新核准。"},{"i":40,"n":"第四十条","txt":"标签和说明书重新核准三个月后，不得继续使用原标签和说明书。"},{"i":41,"n":"第四十一条","txt":"违反本办法的，依照《农药管理条例》有关规定处罚。"},{"i":42,"n":"第四十二条","txt":"本办法自2017年8月1日起施行。2007年12月8日农业部公布的《农药标签和说明书管理办法》同时废止。 现有产品标签或者说明书与本办法不符的，应当自2018年1月1日起使用符合本办法规定的标签和说明书。"}],"nongyaoshengchanxukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范农药生产行为，加强农药生产管理，保证农药产品质量，根据《农药管理条例》,制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称农药生产，包括农药原药（母药）生产、制剂加工或者分装。"},{"i":3,"n":"第三条","txt":"农药生产许可的申请、审查、核发和监督管理，适用本办法。"},{"i":4,"n":"第四条","txt":"农业部负责监督指导全国农药生产许可管理工作，制定生产条件要求和审查细则。 省级人民政府农业主管部门（以下简称省级农业部门）负责受理申请、审查并核发农药生产许可证。 县级以上地方农业部门应当加强本行政区域内的农药生产监督管理工作。"},{"i":5,"n":"第五条","txt":"农药生产许可实行一企一证管理，一个农药生产企业只核发一个农药生产许可证。"},{"i":6,"n":"第六条","txt":"农药生产应当符合国家产业政策，不得生产国家淘汰的产品，不得采用国家淘汰的工艺、装置、原材料从事农药生产，不得新增国家限制生产的产品或者国家限制的工艺、装置、原材料从事农药生产。"},{"i":7,"n":"第七条","txt":"各级农业部门应当加强农药生产许可信息化建设。农业部加快建设全国统一的农药管理信息平台，逐步实现农药生产许可证的申请、受理、审核、核发和打印在农药管理信息平台统一进行。地方农业部门应当及时上传、更新农药生产许可、监督管理等信息。"},{"i":8,"n":"第八条","txt":"从事农药生产的企业，应当具备下列条件： （一）符合国家产业政策； （二）有符合生产工艺要求的管理、技术、操作、检验等人员； （三）有固定的生产厂址； （四）有布局合理的厂房，新设立化学农药生产企业或者非化学农药生产企业新增化学农药生产范围的，应当在省级以上化工园区内建厂；新设立非化学农药生产企业、家用卫生杀虫剂企业或者化学农药生产企业新增原药（母药）生产范围的，应当进入地市级以上化工园区或者工业园区； （五）有与生产农药相适应的自动化生产设备、设施，有利用产品可追溯电子信息码从事生产、销售的设施； （六）有专门的质量检验机构，齐全的质量检验仪器和设备，完整的质量保证体系和技术标准； （七）有完备的管理制度，包括原材料采购、工艺设备、质量控制、产品销售、产品召回、产品储存与运输、安全生产、职业卫生、环境保护、农药废弃物回收与处置、人员培训、文件与记录等管理制度； （八）农业部规定的其他条"},{"i":9,"n":"第九条","txt":"申请农药生产许可证的，应当向生产所在地省级农业部门提交以下材料： （一）农药生产许可证申请书； （二）企业营业执照复印件； （三）法定代表人（负责人）身份证明及基本情况； （四）主要管理人员、技术人员、检验人员简介及资质证件复印件，以及从事农药生产相关人员基本情况； （五）生产厂址所在区域的说明及生产布局平面图、土地使用权证或者租赁证明； （六）所申请生产农药原药（母药）或者制剂剂型的生产装置工艺流程图、生产装置平面布置图、生产工艺流程图和工艺说明，以及相对应的主要厂房、设备、设施和保障正常运转的辅助设施等名称、数量、照片； （七）所申请生产农药原药（母药）或者制剂剂型的产品质量标准及主要检验仪器设备清单； （八）产品质量保证体系文件和管理制度； （九）按照产品质量保证体系文件和管理制度要求，所申请农药的三批次试生产运行原始记录； （十）申请材料真实性、合法性声明； （十一）农业部规定"},{"i":10,"n":"第十条","txt":"省级农业部门对申请人提交的申请材料，应当根据下列情况分别作出处理： （一）不需要取得农药生产许可的，即时告知申请者不予受理； （二）申请材料存在错误的，允许申请者当场更正； （三）申请材料不齐全或者不符合法定形式的，应当当场或者在五个工作日内一次告知申请者需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （四）申请材料齐全、符合法定形式，或者申请者按照要求提交全部补正材料的，予以受理。"},{"i":11,"n":"第十一条","txt":"省级农业部门应当对申请材料书面审查和技术评审，必要时应当进行实地核查，自受理申请之日起二十个工作日内作出是否核发生产许可证的决定。符合条件的，核发农药生产许可证；不符合条件的，书面通知申请人并说明理由。 技术评审可以组织农药管理、生产、质量控制等方面的专业人员进行，所需时间不计算许可期限内，不得超过九十日。"},{"i":12,"n":"第十二条","txt":"农药生产许可证式样及相关表格格式由农业部统一制定。 农药生产许可证应当载明许可证编号、生产企业名称、统一社会信用代码、住所、法定代表人（负责人）、生产范围、生产地址、有效期等事项。 农药生产许可证编号规则为：农药生许+省份简称+顺序号（四位数）。 农药生产许可证的生产范围按照下列规定进行标注： （一）原药（母药）品种； （二）制剂剂型，同时区分化学农药或者非化学农药。"},{"i":13,"n":"第十三条","txt":"农药生产许可证有效期为五年。农药生产许可证有效期内，企业名称、住所、法定代表人（负责人）发生变化或者缩小生产范围的，应当自发生变化之日起三十日内向省级农业部门提出变更申请，并提交变更申请表和相关证明等材料。 省级农业部门应当自受理申请之日起二十个工作日内作出审批决定。符合条件的，予以变更；不符合条件的，书面通知申请人并说明理由。"},{"i":14,"n":"第十四条","txt":"农药生产企业扩大生产范围或者改变生产地址的,应当按照本办法的规定重新申请农药生产许可证。化学农药生产企业改变生产地址的，还应当进入市级以上化工园区或者工业园区。 新增生产地址的，按新设立农药生产企业要求办理。"},{"i":15,"n":"第十五条","txt":"农药生产许可证有效期届满，需要继续生产农药的，农药生产企业应当在有效期届满九十日前向省级农业部门申请延续。"},{"i":16,"n":"第十六条","txt":"申请农药生产许可证延续的，应当提交申请书、生产情况报告等材料。省级农业部门对申请材料进行审查，未在规定期限内提交申请或者不符合农药生产企业条件要求的，不予延续。"},{"i":17,"n":"第十七条","txt":"农药生产许可证遗失、损坏的，应当说明原因并提供相关证明材料，及时向所在地省级农业部门申请补发。"},{"i":18,"n":"第十八条","txt":"农药生产企业应当按照产品质量标准和生产许可证的规定组织生产，确保农药产品与登记农药一致，对农药产品质量负责。 农药生产企业在其农药生产许可范围内，依据《农药管理条例》第十九条的规定，可以接受新农药研制者和其他农药生产企业的委托，加工或者分装农药；也可以接受向中国出口农药的企业委托，分装农药。"},{"i":19,"n":"第十九条","txt":"农药生产企业应当在每季度结束之日起十五日内，将上季度生产销售数据上传至农业部规定的农药管理信息平台。委托加工、分装农药的，由委托方报送。"},{"i":20,"n":"第二十条","txt":"县级以上地方农业部门应当加强对农药生产企业的监督检查，定期调查统计农药生产情况，建立农药生产诚信档案并予以公布。"},{"i":21,"n":"第二十一条","txt":"有下列情形之一的，由省级农业部门依法吊销农药生产许可证： （一）生产假农药的； （二）生产劣质农药情节严重的； （三）不再符合农药生产许可条件继续生产农药且逾期拒不整改或者整改后仍不符合要求的； （四）违反《农药管理条例》第五十三条、五十四条规定情形的； （五）转让、出租、出借农药生产许可证的； （六）招用《农药管理条例》第六十三条第一款规定人员从事农药生产活动的； （七）依法应当吊销农药生产许可证的其他情形。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一的，由省级农业部门依法撤销农药生产许可证： （一）发证机关工作人员滥用职权、玩忽职守作出准予农药生产许可决定的； （二）发证机关违反法定程序作出准予农药生产许可决定的； （三）发证机关对不具备申请资格或者不符合法定条件的申请人准予农药生产许可的； （四）申请人以欺骗、贿赂等不正当手段取得农药生产许可的； （五）依法应当撤销农药生产许可的其他情形。"},{"i":23,"n":"第二十三条","txt":"有下列情形之一的，由省级农业部门依法注销农药生产许可证： （一）企业申请注销的； （二）企业主体资格依法终止的； （三）农药生产许可有效期届满未申请延续的； （四）农药生产许可依法被撤回、撤销、吊销的； （五）依法应当注销的其他情形。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，按未取得农药生产许可证处理： （一）超过农药生产许可证有效期继续生产农药的； （二）超过农药生产许可范围生产农药的； （三）未经批准擅自改变生产地址生产农药的； （四）委托已取得农药生产许可证的企业超过农药生产许可范围加工或者分装农药的； （五）应当按照未取得农药生产许可证处理的其他情形。"},{"i":25,"n":"第二十五条","txt":"农业部加强对省级农业部门实施农药生产许可的监督检查，及时纠正农药生产许可审批中的违规行为。发现有关工作人员有违规行为的，应当责令改正；依法应当给予处分的，向其任免机关或者监察机关提出处分建议。"},{"i":26,"n":"第二十六条","txt":"县级以上农业部门及其工作人员有下列行为之一的，责令改正；对负有责任的领导人员和直接责任人员调查处理；依法给予处分；构成犯罪的，依法追究刑事责任： （一）不履行农药生产监督管理职责，所辖行政区域的违法农药生产活动造成重大损失或者恶劣社会影响； （二）对不符合条件的申请人准予生产许可或者对符合条件的申请人拒不准予生产许可； （三）参与农药生产、经营活动； （四）有其他徇私舞弊、滥用职权、玩忽职守行为。"},{"i":27,"n":"第二十七条","txt":"任何单位和个人发现违法从事农药生产活动的，有权向农业部门举报，农业部门应当及时核实、处理，严格为举报人保密。经查证属实，并对生产安全起到积极作用或者挽回损失较大的，按照国家有关规定予以表彰或者奖励。"},{"i":28,"n":"第二十八条","txt":"农药生产企业违法从事农药生产活动的，按照《农药管理条例》的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"本办法中化学农药是指利用化学物质人工合成的农药。"},{"i":30,"n":"第三十条","txt":"本办法自2017年8月1日起实施。 在本办法实施前已取得农药生产批准证书或者农药生产许可证的农药生产企业，可以在有效期内继续生产相应的农药产品。有效期届满，需要继续生产农药的，农药生产企业应当在有效期届满九十日前，按照本办法的规定，向省级农业部门申请农药生产许可证。 在本办法实施前已取得农药登记证但未取得农药生产批准证书或者农药生产许可证，需要继续生产农药的，应当在本办法实施之日起两年内取得农药生产许可证。"}],"nongyaodengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范农药登记行为，加强农药登记管理，保证农药的安全性、有效性，根据《农药管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内生产、经营、使用的农药，应当取得农药登记。 未依法取得农药登记证的农药，按照假农药处理。"},{"i":3,"n":"第三条","txt":"农业农村部负责全国农药登记管理工作，组织成立农药登记评审委员会，制定农药登记评审规则。 农业农村部所属的负责农药检定工作的机构负责全国农药登记具体工作。"},{"i":4,"n":"第四条","txt":"省级人民政府农业农村主管部门（以下简称省级农业农村部门）负责受理本行政区域内的农药登记申请，对申请资料进行审查，提出初审意见。 省级农业农村部门负责农药检定工作的机构（以下简称省级农药检定机构）协助做好农药登记具体工作。"},{"i":5,"n":"第五条","txt":"农药登记应当遵循科学、公平、公正、高效和便民的原则。"},{"i":6,"n":"第六条","txt":"鼓励和支持登记安全、高效、经济的农药，加快淘汰对农业、林业、人畜安全、农产品质量安全和生态环境等风险高的农药。"},{"i":7,"n":"第七条","txt":"农药名称应当使用农药的中文通用名称或者简化中文通用名称，植物源农药名称可以用植物名称加提取物表示。直接使用的卫生用农药的名称用功能描述词语加剂型表示。"},{"i":8,"n":"第八条","txt":"农药有效成分含量、剂型的设定应当符合提高质量、保护环境和促进农业可持续发展的原则。制剂产品的配方应当科学、合理、方便使用。 相同有效成分和剂型的单制剂产品，含量梯度不超过三个。 混配制剂的有效成分不超过两种，除草剂、种子处理剂有效成分不超过三种。有效成分和剂型相同的混配制剂，配比不超过三个，相同配比的总含量梯度不超过三个。不经稀释或者分散直接使用的低有效成分含量农药单独分类。 信息素等引诱、迷向类产品按主要有效成分登记。 制剂产品有效成分种类和含量梯度的具体要求，由农业农村部另行制定。"},{"i":9,"n":"第九条","txt":"农业农村部根据农药助剂的毒性和危害性，适时公布和调整禁用、限用助剂名单及限量。 使用时需要添加指定助剂的，申请农药登记时，应当提交相应的试验资料。"},{"i":10,"n":"第十条","txt":"农药产品的稀释倍数或者使用浓度,应当与施药技术相匹配。"},{"i":11,"n":"第十一条","txt":"申请人提供的相关数据或者资料，应当能够满足风险评估的需要，产品与已登记产品在安全性、有效性等方面相当或者具有明显优势。 对申请登记产品进行审查，需要参考已登记产品风险评估结果时，遵循最大风险原则。"},{"i":12,"n":"第十二条","txt":"申请人应当按规定提交相关材料，并对所提供资料的真实性、合法性负责。"},{"i":13,"n":"第十三条","txt":"申请人应当是农药生产企业、向中国出口农药的企业或者新农药研制者。 农药生产企业，是指已经取得农药生产许可证的境内企业。向中国出口农药的企业（以下简称境外企业），是指将在境外生产的农药向中国出口的企业。新农药研制者，是指在我国境内研制开发新农药的中国公民、法人或者其他组织。 多个主体联合研制的新农药，应当明确其中一个主体作为申请人，并说明其他合作研制机构，以及相关试验样品同质性的证明材料。其他主体不得重复申请。"},{"i":14,"n":"第十四条","txt":"申请人为法人或者其他组织的，应当指定本单位专人负责农药登记申请相关工作。 境内申请人向所在地省级农业农村部门提出农药登记申请。境外企业向农业农村部提出农药登记申请。"},{"i":15,"n":"第十五条","txt":"申请人应当提交产品化学、毒理学、药效、残留、环境影响等试验报告、风险评估报告、标签或者说明书样张、产品安全数据单、相关文献资料、申请表、申请人资质证明、资料真实性声明等申请资料。 委托其他单位或者个人代为办理农药登记业务的，还应当提交双方签字或者盖章的授权委托书，授权委托书应当载明代理人姓名或者名称、委托事项、权限等。 农药登记申请资料应当真实、规范、完整、有效，具体要求由农业农村部另行制定。"},{"i":16,"n":"第十六条","txt":"登记试验报告应当由农业农村部认定的登记试验单位出具，也可以由与中国政府有关部门签署互认协定的境外相关实验室出具；但药效、残留、环境影响等与环境条件密切相关的试验以及中国特有生物物种的登记试验应当在中国境内完成。"},{"i":17,"n":"第十七条","txt":"申请新农药登记的，应当同时提交新农药原药和新农药制剂登记申请，并提供农药标准品。"},{"i":18,"n":"第十八条","txt":"取得首次登记、含有新化合物的农药，自登记之日起六年内，其他申请人申请含该新化合物的农药登记的，应当获得该登记证持有人完整登记资料授权，但提交自己取得数据的除外。 其他申请人提交自己取得的数据申请前款农药登记的，按照本办法第十七条规定办理。"},{"i":19,"n":"第十九条","txt":"按照《农药管理条例》第十四条规定转让农药登记资料的，受让方凭以下材料申请农药登记： （一）双方的转让合同； （二）根据农药登记资料要求补充完善的相关登记资料； （三）原农药登记证持有人注销相应登记证的申请。"},{"i":20,"n":"第二十条","txt":"农业农村部或者省级农业农村部门对申请人提交的申请资料，应当根据下列情况分别作出处理： （一）不需要农药登记的，即时告知申请人不予受理； （二）申请资料存在错误的，允许申请人当场更正； （三）申请资料不齐全或者不符合法定形式的，应当当场或者在五个工作日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请资料之日起即为受理； （四）申请资料齐全、符合法定形式，或者申请人按照要求提交全部补正资料的，予以受理。"},{"i":21,"n":"第二十一条","txt":"省级农业农村部门应当自受理申请之日起二十个工作日内对申请人提交的资料进行初审，提出初审意见，并将初审意见和全部申请资料于五个工作日内直接报送农业农村部。 初审不通过的，省级农业农村部门可以根据申请人意愿，书面通知申请人并说明理由。"},{"i":22,"n":"第二十二条","txt":"农业农村部自受理申请或者收到省级农业农村部门报送的申请资料和初审意见后，组织所属农药检定机构在九个月内完成产品化学、毒理学、药效、残留、环境影响、标签样张等的技术审查工作，并将审查意见提交农药登记评审委员会评审。 农业农村部所属农药检定机构在技术审查过程中发现申请资料存在轻微瑕疵需要补正的，可以要求申请人在五个工作日内补充相关材料，相关期限不计入审查期限。"},{"i":23,"n":"第二十三条","txt":"农药登记评审委员会在收到技术审查意见后，按照农药登记评审规则提出评审意见。"},{"i":24,"n":"第二十四条","txt":"农药登记申请受理后、进入技术审查前，申请人可以撤回登记申请，并在补充完善相关资料后重新申请。 农业农村部根据农药登记评审委员会意见，可以要求申请人在指定时间内补充资料。"},{"i":25,"n":"第二十五条","txt":"农药登记审查和评审过程中认为申请人提交的试验数据需要验证的，农业农村部可以组织开展验证试验，并将所需时间告知申请人。"},{"i":26,"n":"第二十六条","txt":"农业农村部审批未通过的产品，申请人再次申请登记的，可以申请使用之前已提交的相应登记资料。具体要求由农业农村部另行规定。"},{"i":27,"n":"第二十七条","txt":"在登记审查和评审期间，申请人提交的登记申请的种类以及其所依照的技术要求和审批程序，不因为其他申请人在此期间取得农药登记证而发生变化。 新农药获得批准后，已经受理的其他申请人的新农药登记申请，可以继续按照新农药登记审批程序予以审查和评审。其他申请人也可以撤回该申请，重新提出登记申请。"},{"i":28,"n":"第二十八条","txt":"农业农村部自收到评审意见之日起二十个工作日内作出审批决定。符合条件的，核发农药登记证；不符合条件的，书面通知申请人并说明理由。"},{"i":29,"n":"第二十九条","txt":"农药登记证式样由农业农村部统一制定。"},{"i":30,"n":"第三十条","txt":"农药登记证有效期为五年。"},{"i":31,"n":"第三十一条","txt":"农药登记证持有人变更名称、企业合并分立需要换发农药登记证的，应当自发生变化之日起三十日内向农业农村部提出申请，并提交相关证明材料。 农业农村部应当自受理申请之日起二十个工作日内完成审查，符合条件的换发证书。"},{"i":32,"n":"第三十二条","txt":"农药登记证有效期内有下列情形之一，农药登记证持有人应当向农业农村部申请变更： （一）改变农药使用范围、使用方法或者使用剂量的； （二）改变农药有效成分以外组成成分的； （三）改变产品毒性级别的； （四）原药产品有效成分含量发生改变的； （五）产品质量标准发生变化的； （六）农业农村部规定的其他情形。"},{"i":33,"n":"第三十三条","txt":"农业农村部在六个月内完成登记变更审查，形成审查意见，提交农药登记评审委员会评审，并自收到评审意见之日起二十个工作日内作出审批决定。符合条件的，准予登记变更，登记证号及有效期不变；不符合条件的，书面通知申请人并说明理由。"},{"i":34,"n":"第三十四条","txt":"有效期届满，需要继续生产农药或者向中国出口农药的，农药登记证持有人应当在有效期届满九十日前向农业农村部申请延续。逾期未申请延续的，应当重新申请登记。"},{"i":35,"n":"第三十五条","txt":"农业农村部对登记延续申请资料进行审查，在有效期届满前作出是否延续的决定。审查中发现安全性、有效性出现隐患或者风险的，提交农药登记评审委员会评审。"},{"i":36,"n":"第三十六条","txt":"省级以上农业农村部门应当建立农药安全风险监测制度，组织农药检定机构、植保机构对已登记农药的安全性和有效性进行监测、评价。"},{"i":37,"n":"第三十七条","txt":"监测内容包括农药对农业、林业、人畜安全、农产品质量安全、生态环境等的影响。 有下列情形之一的，应当组织开展评价： （一）发生多起农作物药害事故的； （二）靶标生物抗性大幅升高的； （三）农产品农药残留多次超标的； （四）出现多起对蜜蜂、鸟、鱼、蚕、虾、蟹等非靶标生物、天敌生物危害事件的； （五）对地下水、地表水和土壤等产生不利影响的； （六）对农药使用者或者接触人群、畜禽等产生健康危害的。 省级农业农村部门应当及时将监测、评价结果报告农业农村部。"},{"i":38,"n":"第三十八条","txt":"农药登记证持有人应当收集分析农药产品的安全性、有效性变化情况并及时报告农业农村部；召回农药产品、发生农药使用事故的，应当及时报告所在地农业农村部门。"},{"i":39,"n":"第三十九条","txt":"对登记十五年以上的农药品种，农业农村部根据生产使用和产业政策变化情况，组织开展周期性评价，评价结果作为登记延续审查的重要依据。 周期性评价主要包括以下内容： （一）靶标生物抗药性； （二）作物安全性； （三）农产品质量安全； （四）人畜健康安全； （五）有益生物安全和生态环境影响。"},{"i":40,"n":"第四十条","txt":"发现已登记农药对农业、林业、人畜安全、农产品质量安全、生态环境等有严重危害或者较大风险的，农业农村部应当组织农药登记评审委员会进行评审，根据评审结果撤销或者变更相应农药登记证，必要时决定禁用或者限制使用并予以公告。"},{"i":41,"n":"第四十一条","txt":"有下列情形之一的，农业农村部或者省级农业农村部门不予受理农药登记申请；已经受理的，不予批准： （一）申请资料的真实性、完整性或者规范性不符合要求； （二）申请人不符合本办法第十三条规定的资格要求； （三）申请人被列入国家有关部门规定的严重失信单位名单并限制其取得行政许可； （四）申请登记农药属于国家有关部门明令禁止生产、经营、使用或者农业农村部依法不再新增登记的农药； （五）登记试验不符合《农药管理条例》第九条、第十条规定; （六）应当不予受理或者批准的其他情形。"},{"i":42,"n":"第四十二条","txt":"隐瞒有关情况或者提交虚假农药登记资料和试验样品的，农业农村部或者省级农业农村部门不予受理或者不予批准，对申请人及其代理人给予警告，一年内不再受理该申请人及其代理人的农药登记申请。 以欺骗、贿赂等不正当手段取得农药登记的，撤销农药登记证，县级以上农业农村部门可以对申请人及其代理人分别处五万元以上十万元以下罚款；农业农村部或者省级农业农村部门三年内不再受理该申请人及其代理人的农药登记申请。"},{"i":43,"n":"第四十三条","txt":"对提交虚假资料和试验样品的，农业农村部将申请人的违法信息列入诚信档案，并予以公布。"},{"i":44,"n":"第四十四条","txt":"有下列情形之一，农业农村部注销农药登记证，并予以公布： （一）有效期届满未延续的； （二）农药登记证持有人依法终止或者不具备农药登记申请人资格的； （三）农药登记证持有人变更名称或者合并分立，已换发新农药登记证的； （四）农药登记资料已经依法转让的； （五）应当注销农药登记证的其他情形。"},{"i":45,"n":"第四十五条","txt":"农业农村部建立农药管理信息平台，定期公布农药登记证核发、延续、变更、撤销、注销情况以及有关的农药产品质量标准号、残留限量规定或者建议值、检验方法、经核准的标签等信息。"},{"i":46,"n":"第四十六条","txt":"农药登记评审委员会组成人员在农药登记评审中谋取不正当利益的，农业农村部将其从农药登记评审委员会除名；属于国家工作人员的，提请有关部门依法予以处分；构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"农业农村部、省级农业农村部门及其负责农药登记工作人员，应当依法履行职责，科学、客观、公正地提出审查和评审意见，对申请人提交的登记资料和尚未公开的审查、评审结果、意见负有保密义务；与申请人或者其产品（资料）具有利害关系的，应当回避；不得参与农药生产、经营活动。"},{"i":48,"n":"第四十八条","txt":"农药登记工作人员不依法履行职责，滥用职权、徇私舞弊，索取、收受他人财物，或者谋取其他利益的，依法给予处分；自处分决定作出之日起，五年内不得从事农药登记工作。"},{"i":49,"n":"第四十九条","txt":"任何单位和个人发现有违反本办法规定情形的，有权向农业农村部或者省级农业农村部门举报。农业农村部或者省级农业农村部门应当及时核实、处理，并为举报人保密。经查证属实，并对生产安全起到积极作用或者挽回损失较大的，按照国家有关规定予以表彰或者奖励。"},{"i":50,"n":"第五十条","txt":"用于特色小宗作物的农药登记，实行群组化扩大使用范围登记管理，特色小宗作物的范围由农业农村部规定。 尚无登记农药可用的特色小宗作物或者新的有害生物，省级农业农村部门可以根据当地实际情况，在确保风险可控的前提下，采取临时用药措施，并报农业农村部备案。"},{"i":51,"n":"第五十一条","txt":"本办法下列用语的含义是： （一）新农药，是指含有的有效成分尚未在中国批准登记的农药，包括新农药原药（母药）和新农药制剂。 （二）原药，是指在生产过程中得到的由有效成分及有关杂质组成的产品，必要时可加入少量的添加剂。 （三）母药，是指在生产过程中得到的由有效成分及有关杂质组成的产品，可含有少量必需的添加剂和适当的稀释剂。 （四）制剂，是指由农药原药（母药）和适宜的助剂加工成的，或者由生物发酵、植物提取等方法加工而成的状态稳定的农药产品。 （五）助剂，是指除有效成分以外，任何被添加在农药产品中，本身不具有农药活性和有效成分功能，但能够或者有助于提高、改善农药产品理化性能的单一组分或者多个组分的物质。"},{"i":52,"n":"第五十二条","txt":"仅供境外使用农药的登记管理由农业农村部另行规定。"},{"i":53,"n":"第五十三条","txt":"本办法自2017年8月1日起施行。 2017年6月1日之前，已经取得的农药临时登记证到期不予延续；已经受理尚未作出审批决定的农药登记申请，按照《农药管理条例》有关规定办理。"}],"nongyaodengjishiyanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了保证农药登记试验数据的完整性、可靠性和真实性，加强农药登记试验管理，根据《农药管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"申请农药登记的，应当按照本办法进行登记试验。 开展农药登记试验的，农药登记申请人应当报试验所在地省级人民政府农业农村主管部门（以下简称省级农业农村部门）备案。"},{"i":3,"n":"第三条","txt":"农业农村部负责农药登记试验单位认定及登记试验的监督管理，具体工作由农业农村部所属的负责农药检定工作的机构承担。 省级农业农村部门负责本行政区域的农药登记试验备案及相关监督管理工作，具体工作由省级农业农村部门所属的负责农药检定工作的机构（以下简称省级农药检定机构）承担。"},{"i":4,"n":"第四条","txt":"省级农业农村部门应当加强农药登记试验监督管理信息化建设，及时将登记试验监督管理信息上传至农业农村部农药管理信息平台。"},{"i":5,"n":"第五条","txt":"申请承担农药登记试验的机构，应当具备下列条件： （一）具有独立的法人资格，或者经法人授权同意申请并承诺承担相应法律责任； （二）具有与申请承担登记试验范围相匹配的试验场所、环境设施条件、试验设施和仪器设备、样品及档案保存设施等； （三）具有与其确立了合法劳动或者录用关系，且与其所申请承担登记试验范围相适应的专业技术和管理人员； （四）建立完善的组织管理体系，配备机构负责人、质量保证部门负责人、试验项目负责人、档案管理员、样品管理员和相应的试验与工作人员等； （五）符合农药登记试验质量管理规范，并制定了相应的标准操作规程； （六）有完成申请试验范围相关的试验经历，并按照农药登记试验质量管理规范运行六个月以上； （七）农业农村部规定的其他条件。"},{"i":6,"n":"第六条","txt":"申请承担农药登记试验的机构应当向农业农村部提交以下资料： （一）农药登记试验单位认定申请书； （二）法人资格证明复印件，或者法人授权书； （三）组织机构设置与职责； （四）试验机构质量管理体系文件（标准操作规程）清单； （五）试验场所、试验设施、实验室等证明材料以及仪器设备清单； （六）专业技术和管理人员名单及相关证明材料； （七）按照农药登记试验质量管理规范要求运行情况的说明，典型试验报告及其相关原始记录复印件。"},{"i":7,"n":"第七条","txt":"农业农村部对申请人提交的资料进行审查，材料不齐全或者不符合法定形式的，应当当场或者在五个工作日内一次告知申请人需要补正的全部内容；申请资料齐全、符合法定形式，或者按照要求提交全部补正资料的，予以受理。"},{"i":8,"n":"第八条","txt":"农业农村部对申请资料进行技术评审，所需时间不计算在审批期限内，不得超过六个月。"},{"i":9,"n":"第九条","txt":"技术评审包括资料审查和现场检查。 资料审查主要审查申请人组织机构、试验条件与能力匹配性、质量管理体系及相关材料的完整性、真实性和适宜性。 现场检查主要对申请人质量管理体系运行情况、试验设施设备条件、试验能力等情况进行符合性检查。 具体评审规则由农业农村部另行制定。"},{"i":10,"n":"第十条","txt":"农业农村部根据评审结果在二十个工作日内作出审批决定，符合条件的，颁发农药登记试验单位证书；不符合条件的，书面通知申请人并说明理由。"},{"i":11,"n":"第十一条","txt":"农药登记试验单位证书有效期为五年，应当载明试验单位名称、统一社会信用代码、法定代表人（负责人）、住所、实验室地址、试验范围、证书编号、有效期等事项。"},{"i":12,"n":"第十二条","txt":"农药登记试验单位证书有效期内，农药登记试验单位名称、法定代表人（负责人）或者住所发生变更的，应当自变更之日起三十日内向农业农村部提出换发证书申请，并提交相关证明材料。农业农村部应当自受理申请之日起二十个工作日内完成审查，符合条件的换发证书。"},{"i":13,"n":"第十三条","txt":"农药登记试验单位证书有效期内，有下列情形之一，应当向农业农村部重新申请： （一）实验室地址发生变化或者设施条件发生重大变化的； （二）试验范围增加的； （三）其他事项。"},{"i":14,"n":"第十四条","txt":"农药登记试验单位证书有效期届满，需要继续从事农药登记试验的，应当在有效期届满六个月前，向农业农村部申请延续。逾期未申请延续的，应当重新申请。 延续申请的具体要求由农业农村部另行规定。"},{"i":15,"n":"第十五条","txt":"农药登记试验单位证书遗失、损坏的，应当说明原因并提供相关证明材料，及时向农业农村部申请补发。"},{"i":16,"n":"第十六条","txt":"开展农药登记试验之前，农药登记申请人应当根据农业农村部规定的程序和要求，通过农业农村部农药管理信息平台向登记试验所在地省级农业农村部门备案。 前款备案信息包括备案主体、有效成分名称、含量及剂型、试验项目、试验地点、试验单位、试验起始时间、与试验单位签订的委托协议、安全防范措施等。新农药试验备案还包括作用机理和作用方式。 试验项目、地点、单位等发生变化的，农药登记申请人应当按前款规定重新备案。"},{"i":17,"n":"第十七条","txt":"农药登记试验样品应当是成熟定型的产品，具有产品鉴别方法、质量控制指标和检测方法。 农药登记申请人应当对试验样品的真实性和一致性负责。"},{"i":18,"n":"第十八条","txt":"农药登记申请人应当将试验样品提交所在地省级农药检定机构进行封样，提供农药名称、有效成分及其含量、剂型、样品生产日期、规格与数量、储存条件、质量保证期等信息，并附具产品质量符合性检验报告及相关谱图。"},{"i":19,"n":"第十九条","txt":"所封试验样品由省级农药检定机构和农药登记申请人各留存一份，保存期限不少于两年，其余样品由农药登记申请人送至登记试验单位开展试验。"},{"i":20,"n":"第二十条","txt":"封存试验样品不足以满足试验需求或者试验样品已超过保存期限，仍需要进行试验的，农药登记申请人应当按本办法规定重新封存样品。"},{"i":21,"n":"第二十一条","txt":"农药登记申请人应当向农药登记试验单位提供试验样品的农药名称、含量、剂型、生产日期、储存条件、质量保证期等信息及安全风险防范措施。 农药登记试验单位应当查验封样完整性、样品信息符合性。"},{"i":22,"n":"第二十二条","txt":"农药登记试验单位接受农药登记申请人委托开展登记试验的，应当签订协议，明确双方权利与义务。"},{"i":23,"n":"第二十三条","txt":"农药登记试验应当按照法定农药登记试验技术准则和方法进行。尚无法定技术准则和方法的，由农药登记申请人和登记试验单位协商确定，且应当保证试验的科学性和准确性。 农药登记试验过程出现重大安全风险时，试验单位应当立即停止试验，采取相应措施防止风险进一步扩大，并报告试验所在地省级农业农村部门，通知农药登记申请人。"},{"i":24,"n":"第二十四条","txt":"试验结束后，农药登记试验单位应当按照协议约定，向农药登记申请人出具规范的试验报告。"},{"i":25,"n":"第二十五条","txt":"农药登记试验单位应当建立试验全过程记录制度，将试验计划、原始记录、标本、留样被试物和对照物、试验报告、与试验有关的文字材料及电子数据保存至试验结束后至少七年，期满后可移交农药登记申请人保存。农药登记申请人应当保存至农药退市后至少五年。 质量容易变化的标本、被试物和对照物留样样品等，其保存期应以能够进行有效评价为期限。 试验单位应当长期保存组织机构、人员、质量保证部门检查记录、主计划表、标准操作规程等试验机构运行与质量管理记录，并及时将开展登记试验的相关信息上传至农业农村部农药管理信息平台。"},{"i":26,"n":"第二十六条","txt":"省级农业农村部门、农业农村部对农药登记试验单位和登记试验过程进行监督检查，重点检查以下内容： （一）试验单位资质条件变化情况; （二）重要试验设备、设施情况; （三）试验地点、试验项目等备案信息是否相符; （四）试验过程是否遵循法定的技术准则和方法; （五）登记试验安全风险及其防范措施的落实情况; （六）其他不符合农药登记试验质量管理规范要求或者影响登记试验质量的情况。 省级农业农村部门按照每年不少于百分之二十的比例，组织对辖区内农药登记试验单位进行检查。农业农村部根据登记评审、投诉举报等情况，不定期组织开展飞行检查。"},{"i":27,"n":"第二十七条","txt":"监督检查中发现试验过程存在难以控制安全风险的，应当及时责令停止试验或者终止试验，省级农业农村部门还应当及时报告农业农村部。 监督检查中发现试验单位不再符合规定条件的，按照以下情形分别办理： （一）具备整改条件的，责令改进或者限期整改，逾期拒不整改或者整改后仍达不到规定条件的，由农业农村部撤销其试验单位证书； （二）不具备整改条件的，由农业农村部撤销其试验单位证书。"},{"i":28,"n":"第二十八条","txt":"农药登记试验单位存在下列情形之一，造成数据、结果出现错误或者无法复核的，由省级以上农业农村部门责令限期整改，给予警告，可以并处一万元以上五万元以下罚款： （一）样品的接收、标识、分发、流转、保存、处置不符合农药登记试验质量管理规范要求，存在样品污染、混淆、损毁、性状异常改变等情形的； （二）使用未经检定、校准或者验证的仪器、设备、设施的； （三）未按照有关农药登记试验技术准则和方法进行的； （四）未按照农药登记试验质量管理规范等规定传输、保存原始数据和报告的； （五）其他不遵守农药登记试验质量管理规范的情形。"},{"i":29,"n":"第二十九条","txt":"农药登记试验单位存在下列情形之一，属于出具虚假登记试验报告，依照《农药管理条例》第五十一条的规定处罚： （一）未经试验出具试验报告的； （二）伪造、变造原始数据、记录，或者未按照法定的技术准则和方法采用原始数据、记录的； （三）减少、遗漏或者变更标准等规定的应当试验的项目，或者改变关键试验条件的； （四）调换封存样品或者改变其原有状态进行试验的； （五）伪造试验单位公章、试验报告签字人签名或者签发时间的； （六）其他出具虚假登记试验报告的情形。"},{"i":30,"n":"第三十条","txt":"农药登记试验单位应当每年向农业农村部报送本年度执行农药登记试验质量管理规范的报告。"},{"i":31,"n":"第三十一条","txt":"省级以上农业农村部门应当组织对农药登记试验所封存的农药试验样品的符合性和一致性进行监督检查，并及时将监督检查发现的问题报告农业农村部。"},{"i":32,"n":"第三十二条","txt":"现有农药登记试验单位无法承担的试验项目，由农业农村部指定的单位承担。"},{"i":33,"n":"第三十三条","txt":"本办法自2017年8月1日起施行。 在本办法施行前农业部公布的农药登记试验单位，在有效期内可继续从事农药登记试验；有效期届满，需要继续从事登记试验的，应当按照本办法的规定申请试验单位认定。"}],"nongyaojingyingxukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范农药经营行为，加强农药经营许可管理，根据《农药管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"农药经营许可的申请、审查、核发和监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内销售农药的，应当取得农药经营许可证。"},{"i":4,"n":"第四条","txt":"农业农村部负责监督指导全国农药经营许可管理工作。 限制使用农药经营许可由省级人民政府农业农村主管部门（以下简称省级农业农村部门）核发；其他农药经营许可由县级以上地方人民政府农业农村主管部门（以下简称县级以上地方农业农村部门）根据农药经营者的申请分别核发。"},{"i":5,"n":"第五条","txt":"农药经营许可实行一企一证管理，一个农药经营者只核发一个农药经营许可证。"},{"i":6,"n":"第六条","txt":"县级以上地方农业农村部门应当加强农药经营许可信息化管理，及时将农药经营许可、监督管理等信息上传至农业农村部农药管理信息平台。"},{"i":7,"n":"第七条","txt":"农药经营者应当具备下列条件： （一）有农学、植保、农药等相关专业中专以上学历或者专业教育培训机构五十六学时以上的学习经历，熟悉农药管理规定，掌握农药和病虫害防治专业知识，能够指导安全合理使用农药的经营人员； （二）有不少于三十平方米的营业场所、不少于五十平方米的仓储场所，并与其他商品、生活区域、饮用水源有效隔离；兼营其他农业投入品的，应当具有相对独立的农药经营区域； （三）营业场所和仓储场所应当配备通风、消防、预防中毒等设施，有与所经营农药品种、类别相适应的货架、柜台等展示、陈列的设施设备； （四）有可追溯电子信息码扫描识别设备和用于记载农药购进、储存、销售等电子台账的计算机管理系统； （五）有进货查验、台账记录、安全管理、安全防护、应急处置、仓储管理、农药废弃物回收与处置、使用指导等管理制度和岗位操作规程； （六）农业农村部规定的其他条件。 经营限制使用农药的，还应当具备下列条件："},{"i":8,"n":"第八条","txt":"申请农药经营许可证的，应当向县级以上地方农业农村部门提交以下材料： （一）农药经营许可证申请表； （二）法定代表人（负责人）身份证明复印件； （三）经营人员的学历或者培训证明； （四）营业场所和仓储场所地址、面积、平面图等说明材料及照片； （五）计算机管理系统、可追溯电子信息码扫描设备、安全防护、仓储设施等清单及照片； （六）有关管理制度目录及文本； （七）申请材料真实性、合法性声明； （八）农业农村部规定的其他材料。"},{"i":9,"n":"第九条","txt":"县级以上地方农业农村部门对申请人提交的申请材料，应当根据下列情况分别作出处理： （一）不需要农药经营许可的，即时告知申请人不予受理； （二）申请材料存在错误的，允许申请人当场更正； （三）申请材料不齐全或者不符合法定形式的，应当当场或者在五个工作日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （四）申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正材料的，予以受理。"},{"i":10,"n":"第十条","txt":"县级以上地方农业农村部门应当对农药经营许可申请材料进行审查，必要时进行实地核查或者委托下级农业农村部门进行实地核查。"},{"i":11,"n":"第十一条","txt":"县级以上地方农业农村部门应当自受理之日起二十个工作日内作出审批决定。符合条件的，核发农药经营许可证；不符合条件的，书面通知申请人并说明理由。"},{"i":12,"n":"第十二条","txt":"农药经营许可证应当载明许可证编号、经营者名称、住所、营业场所、仓储场所、经营范围、有效期、法定代表人（负责人）、统一社会信用代码等事项。 经营者设立分支机构的，还应当注明分支机构的营业场所和仓储场所地址等事项。 农药经营许可证编号规则为：农药经许+省份简称+发证机关代码+经营范围代码+顺序号（四位数）。 经营范围按照农药、农药（限制使用农药除外）分别标注。 农药经营许可证式样由农业农村部统一制定。"},{"i":13,"n":"第十三条","txt":"农药经营许可证有效期为五年。农药经营许可证有效期内，改变农药经营者名称、法定代表人（负责人）、住所、调整分支机构，或者减少经营范围的，应当自发生变化之日起三十日内向原发证机关提出换发证书申请，并提交相关证明材料。 原发证机关应当自受理申请之日起二十个工作日内完成审查，符合条件的换发证书；不符合条件的，书面通知申请人并说明理由。"},{"i":14,"n":"第十四条","txt":"经营范围增加限制使用农药或者营业场所、仓储场所地址发生变更的，应当按照本办法的规定重新申请农药经营许可证。"},{"i":15,"n":"第十五条","txt":"农药经营许可证有效期届满，需要继续经营农药的，农药经营者应当在有效期届满九十日前向原发证机关申请延续。"},{"i":16,"n":"第十六条","txt":"申请农药经营许可证延续的，应当向原发证机关提交申请表、农药经营情况综合报告等材料。"},{"i":17,"n":"第十七条","txt":"原发证机关对申请材料进行审查，未在规定期限内提交申请或者不符合农药经营条件要求的，不予延续。"},{"i":18,"n":"第十八条","txt":"农药经营许可证遗失、损坏的，应当说明原因并提供相关证明材料，及时向原发证机关申请补发。"},{"i":19,"n":"第十九条","txt":"有下列情形之一，不需要取得农药经营许可证： （一）专门经营卫生用农药的； （二）农药经营者在发证机关管辖的行政区域内设立分支机构的； （三）农药生产企业在其生产场所范围内销售本企业生产的农药，或者向农药经营者直接销售本企业生产农药的。"},{"i":20,"n":"第二十条","txt":"农药经营者应当将农药经营许可证置于营业场所的醒目位置，并按照《农药管理条例》规定，建立采购、销售台账，向购买人询问病虫害发生情况，必要时应当实地查看病虫害发生情况，科学推荐农药，正确说明农药的使用范围、使用方法和剂量、使用技术要求和注意事项，不得误导购买人。 限制使用农药的经营者应当为农药使用者提供用药指导，并逐步提供统一用药服务。"},{"i":21,"n":"第二十一条","txt":"利用互联网经营农药的，应当取得农药经营许可证，并在上线运营后二十日内将网站名称、网络平台名称、应用程序名称等报发证机关备案。经营卫生用农药，以及农药生产企业利用本企业网站销售本企业产品的除外。 2026年1月1日前已上线运营的互联网农药经营者，应当在2026年1月31日前完成备案。 限制使用农药和农业农村部规定的其他农药不得利用互联网经营。 超出经营范围经营限制使用农药，或者利用互联网经营前款规定的农药的，按照未取得农药经营许可证处理。"},{"i":22,"n":"第二十二条","txt":"利用互联网经营农药的，应当在其网站首页或者经营活动的主页面显著位置，持续公示农药经营许可证载明的全部信息或者其链接标识。农药经营许可证信息发生变化的，应当在十个工作日内更新页面内容。 农药生产企业利用本企业网站销售本企业产品的，应当持续公示农药生产许可证载明的全部信息或者其链接标识。农药生产许可证信息发生变化的，应当在十个工作日内更新页面内容。 利用互联网经营农药的，应当完整、真实、准确展示实际销售产品的标签等信息。"},{"i":23,"n":"第二十三条","txt":"农药互联网交易第三方平台应当建立并实施农药经营资质核验、网络经营行为监督、农药信息展示、农药实名购买、交易记录保存、投诉举报处理等管理制度，并积极配合农业农村部门的监管执法工作。"},{"i":24,"n":"第二十四条","txt":"农药经营者应当在每季度结束之日起十五日内，将上季度农药经营数据上传至农业农村部农药管理信息平台或者通过其他形式报发证机关备案。 农药经营者设立分支机构的，应当在农药经营许可证变更后三十日内，向分支机构所在地县级农业农村部门备案。"},{"i":25,"n":"第二十五条","txt":"县级以上地方农业农村部门应当对农药经营情况进行监督检查，定期调查统计农药销售情况，建立农药经营诚信档案并予以公布。"},{"i":26,"n":"第二十六条","txt":"县级以上地方农业农村部门发现农药经营者不再符合规定条件的，应当责令其限期整改；逾期拒不整改或者整改后仍不符合规定条件的，发证机关吊销其农药经营许可证。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一，发证机关依法注销农药经营许可证： （一）农药经营者申请注销的； （二）主体资格依法终止的； （三）农药经营许可有效期届满未申请延续的； （四）农药经营许可依法被撤回、撤销、吊销的； （五）依法应当注销的其他情形。"},{"i":28,"n":"第二十八条","txt":"利用互联网经营农药未报发证机关备案的，由发证机关责令改正，可以处五千元以上五万元以下罚款。"},{"i":29,"n":"第二十九条","txt":"农药经营者、农药生产企业利用互联网经营农药，未依法持续公示相应许可证信息或者其链接标识的，依照《中华人民共和国电子商务法》第七十六条的规定处理。 农药经营者、农药生产企业利用互联网经营农药，未完整、真实、准确展示实际销售产品的标签等信息的，由县级以上地方农业农村部门责令改正；有下列情形之一，可以处一万元以下罚款： （一）拒不改正的； （二）展示信息不完整、不真实或不准确的农药产品在三个以上的； （三）两年内再次有同类违法行为的； （四）有其他严重情节的。"},{"i":30,"n":"第三十条","txt":"农药互联网交易第三方平台未履行核验农药经营者资质等义务的，由县级以上农业农村部门依照《中华人民共和国电子商务法》第八十条的规定处理。"},{"i":31,"n":"第三十一条","txt":"县级以上地方农业农村部门及其工作人员应当依法履行农药经营许可管理职责，自觉接受农药经营者和社会监督。"},{"i":32,"n":"第三十二条","txt":"上级农业农村部门应当加强对下级农业农村部门农药经营许可管理工作的监督，发现有关工作人员有违规行为的，应当责令改正；依法应当给予处分的，向其任免机关或者监察机关提出处分建议。"},{"i":33,"n":"第三十三条","txt":"县级以上农业农村部门及其工作人员有下列行为之一的，责令改正；对负有责任的领导人员和直接责任人员调查处理；依法给予处分；构成犯罪的，依法追究刑事责任： （一）不履行农药经营监督管理职责，所辖行政区域的违法农药经营活动造成重大损失或者恶劣社会影响； （二）对不符合条件的申请人准予经营许可或者对符合条件的申请人拒不准予经营许可； （三）参与农药生产、经营活动； （四）有其他徇私舞弊、滥用职权、玩忽职守行为。"},{"i":34,"n":"第三十四条","txt":"任何单位和个人发现违法从事农药经营活动的，有权向农业农村部门举报，农业农村部门应当及时核实、处理，严格为举报人保密。经查证属实，并对生产安全起到积极作用或者挽回损失较大的，按照国家有关规定予以表彰或者奖励。"},{"i":35,"n":"第三十五条","txt":"农药经营者违法从事农药经营活动的，按照《农药管理条例》的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"本办法自2017年8月1日起施行。 2017年6月1日前已从事农药经营活动的，应当自本办法施行之日起一年内达到本办法规定的条件，并依法申领农药经营许可证。 在本办法施行前已按有关规定取得农药经营许可证的，可以在有效期内继续从事农药经营活动，但经营限制使用农药的应当重新申请农药经营许可证；有效期届满，需要继续经营农药的，应当在有效期届满九十日前，按本办法的规定，重新申请农药经营许可证。"}],"dongwujianyiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强动物检疫活动管理，预防、控制、净化、消灭动物疫病，防控人畜共患传染病，保障公共卫生安全和人体健康，根据《中华人民共和国动物防疫法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国领域内的动物、动物产品的检疫及其监督管理活动。 陆生野生动物检疫办法，由农业农村部会同国家林业和草原局另行制定。"},{"i":3,"n":"第三条","txt":"动物检疫遵循过程监管、风险控制、区域化和可追溯管理相结合的原则。"},{"i":4,"n":"第四条","txt":"农业农村部主管全国动物检疫工作。 县级以上地方人民政府农业农村主管部门主管本行政区域内的动物检疫工作，负责动物检疫监督管理工作。 县级人民政府农业农村主管部门可以根据动物检疫工作需要，向乡、镇或者特定区域派驻动物卫生监督机构或者官方兽医。 县级以上人民政府建立的动物疫病预防控制机构应当为动物检疫及其监督管理工作提供技术支撑。"},{"i":5,"n":"第五条","txt":"农业农村部制定、调整并公布检疫规程，明确动物检疫的范围、对象和程序。"},{"i":6,"n":"第六条","txt":"农业农村部加强信息化建设，建立全国统一的动物检疫管理信息化系统，实现动物检疫信息的可追溯。 县级以上动物卫生监督机构应当做好本行政区域内的动物检疫信息数据管理工作。 从事动物饲养、屠宰、经营、运输、隔离等活动的单位和个人，应当按照要求在动物检疫管理信息化系统填报动物检疫相关信息。"},{"i":7,"n":"第七条","txt":"县级以上地方人民政府的动物卫生监督机构负责本行政区域内动物检疫工作，依照《中华人民共和国动物防疫法》、本办法以及检疫规程等规定实施检疫。 动物卫生监督机构的官方兽医实施检疫，出具动物检疫证明、加施检疫标志，并对检疫结论负责。"},{"i":8,"n":"第八条","txt":"国家实行动物检疫申报制度。 出售或者运输动物、动物产品的，货主应当提前三天向所在地动物卫生监督机构申报检疫。 屠宰动物的，应当提前六小时向所在地动物卫生监督机构申报检疫；急宰动物的，可以随时申报。"},{"i":9,"n":"第九条","txt":"向无规定动物疫病区输入相关易感动物、易感动物产品的，货主除按本办法第八条规定向输出地动物卫生监督机构申报检疫外，还应当在启运三天前向输入地动物卫生监督机构申报检疫。输入易感动物的，向输入地隔离场所在地动物卫生监督机构申报；输入易感动物产品的，在输入地省级动物卫生监督机构指定的地点申报。"},{"i":10,"n":"第十条","txt":"动物卫生监督机构应当根据动物检疫工作需要，合理设置动物检疫申报点，并向社会公布。 县级以上地方人民政府农业农村主管部门应当采取有力措施，加强动物检疫申报点建设。"},{"i":11,"n":"第十一条","txt":"申报检疫的，应当提交检疫申报单以及农业农村部规定的其他材料，并对申报材料的真实性负责。 申报检疫采取在申报点填报或者通过传真、电子数据交换等方式申报。"},{"i":12,"n":"第十二条","txt":"动物卫生监督机构接到申报后，应当及时对申报材料进行审查。申报材料齐全的，予以受理；有下列情形之一的，不予受理，并说明理由： （一）申报材料不齐全的，动物卫生监督机构当场或在三日内已经一次性告知申报人需要补正的内容，但申报人拒不补正的； （二）申报的动物、动物产品不属于本行政区域的； （三）申报的动物、动物产品不属于动物检疫范围的； （四）农业农村部规定不应当检疫的动物、动物产品； （五）法律法规规定的其他不予受理的情形。"},{"i":13,"n":"第十三条","txt":"受理申报后，动物卫生监督机构应当指派官方兽医实施检疫，可以安排协检人员协助官方兽医到现场或指定地点核实信息，开展临床健康检查。"},{"i":14,"n":"第十四条","txt":"出售或者运输的动物，经检疫符合下列条件的，出具动物检疫证明： （一）来自非封锁区及未发生相关动物疫情的饲养场（户）； （二）来自符合风险分级管理有关规定的饲养场（户）； （三）申报材料符合检疫规程规定； （四）畜禽标识符合规定； （五）按照规定进行了强制免疫，并在有效保护期内； （六）临床检查健康； （七）需要进行实验室疫病检测的，检测结果合格。 出售、运输的种用动物精液、卵、胚胎、种蛋，经检疫其种用动物饲养场符合第一款第一项规定，申报材料符合第一款第三项规定，供体动物符合第一款第四项、第五项、第六项、第七项规定的，出具动物检疫证明。 出售、运输的生皮、原毛、绒、血液、角等产品，经检疫其饲养场（户）符合第一款第一项规定，申报材料符合第一款第三项规定，供体动物符合第一款第四项、第五项、第六项、第七项规定，且按规定消毒合格的，出具动物检疫证明。"},{"i":15,"n":"第十五条","txt":"出售或者运输水生动物的亲本、稚体、幼体、受精卵、发眼卵及其他遗传育种材料等水产苗种的，经检疫符合下列条件的，出具动物检疫证明： （一）来自未发生相关水生动物疫情的苗种生产场； （二）申报材料符合检疫规程规定； （三）临床检查健康； （四）需要进行实验室疫病检测的，检测结果合格。 水产苗种以外的其他水生动物及其产品不实施检疫。"},{"i":16,"n":"第十六条","txt":"已经取得产地检疫证明的动物，从专门经营动物的集贸市场继续出售或者运输的，或者动物展示、演出、比赛后需要继续运输的，经检疫符合下列条件的，出具动物检疫证明： （一）有原始动物检疫证明和完整的进出场记录； （二）畜禽标识符合规定； （三）临床检查健康； （四）原始动物检疫证明超过调运有效期，按规定需要进行实验室疫病检测的，检测结果合格。"},{"i":17,"n":"第十七条","txt":"跨省、自治区、直辖市引进的乳用、种用动物到达输入地后，应当在隔离场或者饲养场内的隔离舍进行隔离观察，隔离期为三十天。经隔离观察合格的，方可混群饲养；不合格的，按照有关规定进行处理。隔离观察合格后需要继续运输的，货主应当申报检疫，并取得动物检疫证明。 跨省、自治区、直辖市输入到无规定动物疫病区的乳用、种用动物的隔离按照本办法第二十六条规定执行。"},{"i":18,"n":"第十八条","txt":"出售或者运输的动物、动物产品取得动物检疫证明后，方可离开产地。"},{"i":19,"n":"第十九条","txt":"动物卫生监督机构向依法设立的屠宰加工场所派驻（出）官方兽医实施检疫。屠宰加工场所应当提供与检疫工作相适应的官方兽医驻场检疫室、工作室和检疫操作台等设施。"},{"i":20,"n":"第二十条","txt":"进入屠宰加工场所的待宰动物应当附有动物检疫证明并加施有符合规定的畜禽标识。"},{"i":21,"n":"第二十一条","txt":"屠宰加工场所应当严格执行动物入场查验登记、待宰巡查等制度，查验进场待宰动物的动物检疫证明和畜禽标识，发现动物染疫或者疑似染疫的，应当立即向所在地农业农村主管部门或者动物疫病预防控制机构报告。"},{"i":22,"n":"第二十二条","txt":"官方兽医应当检查待宰动物健康状况，在屠宰过程中开展同步检疫和必要的实验室疫病检测，并填写屠宰检疫记录。"},{"i":23,"n":"第二十三条","txt":"经检疫符合下列条件的，对动物的胴体及生皮、原毛、绒、脏器、血液、蹄、头、角出具动物检疫证明，加盖检疫验讫印章或者加施其他检疫标志： （一）申报材料符合检疫规程规定； （二）待宰动物临床检查健康； （三）同步检疫合格； （四）需要进行实验室疫病检测的，检测结果合格。"},{"i":24,"n":"第二十四条","txt":"官方兽医应当回收进入屠宰加工场所待宰动物附有的动物检疫证明，并将有关信息上传至动物检疫管理信息化系统。回收的动物检疫证明保存期限不得少于十二个月。"},{"i":25,"n":"第二十五条","txt":"向无规定动物疫病区运输相关易感动物、动物产品的，除附有输出地动物卫生监督机构出具的动物检疫证明外，还应当按照本办法第二十六条、第二十七条规定取得动物检疫证明。"},{"i":26,"n":"第二十六条","txt":"输入到无规定动物疫病区的相关易感动物，应当在输入地省级动物卫生监督机构指定的隔离场所进行隔离，隔离检疫期为三十天。隔离检疫合格的，由隔离场所在地县级动物卫生监督机构的官方兽医出具动物检疫证明。"},{"i":27,"n":"第二十七条","txt":"输入到无规定动物疫病区的相关易感动物产品，应当在输入地省级动物卫生监督机构指定的地点，按照无规定动物疫病区有关检疫要求进行检疫。检疫合格的，由当地县级动物卫生监督机构的官方兽医出具动物检疫证明。"},{"i":28,"n":"第二十八条","txt":"国家实行官方兽医任命制度。官方兽医应当符合以下条件： （一）动物卫生监督机构的在编人员，或者接受动物卫生监督机构业务指导的其他机构在编人员； （二）从事动物检疫工作； （三）具有畜牧兽医水产初级以上职称或者相关专业大专以上学历或者从事动物防疫等相关工作满三年以上； （四）接受岗前培训，并经考核合格； （五）符合农业农村部规定的其他条件。"},{"i":29,"n":"第二十九条","txt":"县级以上动物卫生监督机构提出官方兽医任命建议，报同级农业农村主管部门审核。审核通过的，由省级农业农村主管部门按程序确认、统一编号，并报农业农村部备案。 经省级农业农村主管部门确认的官方兽医，由其所在的农业农村主管部门任命，颁发官方兽医证，公布人员名单。 官方兽医证的格式由农业农村部统一规定。"},{"i":30,"n":"第三十条","txt":"官方兽医实施动物检疫工作时，应当持有官方兽医证。禁止伪造、变造、转借或者以其他方式违法使用官方兽医证。"},{"i":31,"n":"第三十一条","txt":"农业农村部制定全国官方兽医培训计划。 县级以上地方人民政府农业农村主管部门制定本行政区域官方兽医培训计划，提供必要的培训条件，设立考核指标，定期对官方兽医进行培训和考核。"},{"i":32,"n":"第三十二条","txt":"官方兽医实施动物检疫的，可以由协检人员进行协助。协检人员不得出具动物检疫证明。 协检人员的条件和管理要求由省级农业农村主管部门规定。"},{"i":33,"n":"第三十三条","txt":"动物饲养场、屠宰加工场所的执业兽医或者动物防疫技术人员，应当协助官方兽医实施动物检疫。"},{"i":34,"n":"第三十四条","txt":"对从事动物检疫工作的人员，有关单位按照国家规定，采取有效的卫生防护、医疗保健措施，全面落实畜牧兽医医疗卫生津贴等相关待遇。 对在动物检疫工作中做出贡献的动物卫生监督机构、官方兽医，按照国家有关规定给予表彰、奖励。"},{"i":35,"n":"第三十五条","txt":"动物检疫证章标志包括： （一）动物检疫证明; （二）动物检疫印章、动物检疫标志; （三）农业农村部规定的其他动物检疫证章标志。"},{"i":36,"n":"第三十六条","txt":"动物检疫证章标志的内容、格式、规格、编码和制作等要求，由农业农村部统一规定。"},{"i":37,"n":"第三十七条","txt":"县级以上动物卫生监督机构负责本行政区域内动物检疫证章标志的管理工作，建立动物检疫证章标志管理制度，严格按照程序订购、保管、发放。"},{"i":38,"n":"第三十八条","txt":"任何单位和个人不得伪造、变造、转让动物检疫证章标志，不得持有或者使用伪造、变造、转让的动物检疫证章标志。"},{"i":39,"n":"第三十九条","txt":"禁止屠宰、经营、运输依法应当检疫而未经检疫或者检疫不合格的动物。 禁止生产、经营、加工、贮藏、运输依法应当检疫而未经检疫或者检疫不合格的动物产品。"},{"i":40,"n":"第四十条","txt":"经检疫不合格的动物、动物产品，由官方兽医出具检疫处理通知单，货主或者屠宰加工场所应当在农业农村主管部门的监督下按照国家有关规定处理。 动物卫生监督机构应当及时向同级农业农村主管部门报告检疫不合格情况。"},{"i":41,"n":"第四十一条","txt":"有下列情形之一的，出具动物检疫证明的动物卫生监督机构或者其上级动物卫生监督机构，根据利害关系人的请求或者依据职权，撤销动物检疫证明，并及时通告有关单位和个人： （一）官方兽医滥用职权、玩忽职守出具动物检疫证明的； （二）以欺骗、贿赂等不正当手段取得动物检疫证明的； （三）超出动物检疫范围实施检疫，出具动物检疫证明的； （四）对不符合检疫申报条件或者不符合检疫合格标准的动物、动物产品，出具动物检疫证明的； （五）其他未按照《中华人民共和国动物防疫法》、本办法和检疫规程的规定实施检疫，出具动物检疫证明的。"},{"i":42,"n":"第四十二条","txt":"有下列情形之一的，按照依法应当检疫而未经检疫处理处罚： （一）动物种类、动物产品名称、畜禽标识号与动物检疫证明不符的； （二）动物、动物产品数量超出动物检疫证明载明部分的； （三）使用转让的动物检疫证明的。"},{"i":43,"n":"第四十三条","txt":"依法应当检疫而未经检疫的动物、动物产品，由县级以上地方人民政府农业农村主管部门依照《中华人民共和国动物防疫法》处理处罚，不具备补检条件的，予以收缴销毁；具备补检条件的，由动物卫生监督机构补检。 依法应当检疫而未经检疫的胴体、肉、脏器、脂、血液、精液、卵、胚胎、骨、蹄、头、筋、种蛋等动物产品，不予补检，予以收缴销毁。"},{"i":44,"n":"第四十四条","txt":"补检的动物具备下列条件的，补检合格，出具动物检疫证明： （一）畜禽标识符合规定； （二）检疫申报需要提供的材料齐全、符合要求； （三）临床检查健康； （四）不符合第一项或者第二项规定条件，货主于七日内提供检疫规程规定的实验室疫病检测报告，检测结果合格。"},{"i":45,"n":"第四十五条","txt":"补检的生皮、原毛、绒、角等动物产品具备下列条件的，补检合格，出具动物检疫证明： （一）经外观检查无腐烂变质； （二）按照规定进行消毒； （三）货主于七日内提供检疫规程规定的实验室疫病检测报告，检测结果合格。"},{"i":46,"n":"第四十六条","txt":"经检疫合格的动物应当按照动物检疫证明载明的目的地运输，并在规定时间内到达，运输途中发生疫情的应当按有关规定报告并处置。 跨省、自治区、直辖市通过道路运输动物的，应当经省级人民政府设立的指定通道入省境或者过省境。 饲养场（户）或者屠宰加工场所不得接收未附有有效动物检疫证明的动物。"},{"i":47,"n":"第四十七条","txt":"运输用于继续饲养或屠宰的畜禽到达目的地后，货主或者承运人应当在三日内向启运地县级动物卫生监督机构报告；目的地饲养场（户）或者屠宰加工场所应当在接收畜禽后三日内向所在地县级动物卫生监督机构报告。"},{"i":48,"n":"第四十八条","txt":"申报动物检疫隐瞒有关情况或者提供虚假材料的，或者以欺骗、贿赂等不正当手段取得动物检疫证明的，依照《中华人民共和国行政许可法》有关规定予以处罚。"},{"i":49,"n":"第四十九条","txt":"违反本办法规定运输畜禽，有下列行为之一的，由县级以上地方人民政府农业农村主管部门处一千元以上三千元以下罚款；情节严重的，处三千元以上三万元以下罚款： （一）运输用于继续饲养或者屠宰的畜禽到达目的地后，未向启运地动物卫生监督机构报告的； （二）未按照动物检疫证明载明的目的地运输的； （三）未按照动物检疫证明规定时间运达且无正当理由的； （四）实际运输的数量少于动物检疫证明载明数量且无正当理由的。"},{"i":50,"n":"第五十条","txt":"其他违反本办法规定的行为，依照《中华人民共和国动物防疫法》有关规定予以处罚。"},{"i":51,"n":"第五十一条","txt":"水产苗种产地检疫，由从事水生动物检疫的县级以上动物卫生监督机构实施。"},{"i":52,"n":"第五十二条","txt":"实验室疫病检测报告应当由动物疫病预防控制机构、取得相关资质认定、国家认可机构认可或者符合省级农业农村主管部门规定条件的实验室出具。"},{"i":53,"n":"第五十三条","txt":"本办法自2022年12月1日起施行。农业部2010年1月21日公布、2019年4月25日修订的《动物检疫管理办法》同时废止。"}],"dongwubingyuanweishengwufenleiminglu":[],"dongwubingyuanweishengwujunzhongbaocangguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强动物病原微生物菌（毒）种和样本保藏管理，依据《中华人民共和国动物防疫法》、《病原微生物实验室生物安全管理条例》和《兽药管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内菌（毒）种和样本的保藏活动及其监督管理。"},{"i":3,"n":"第三条","txt":"本办法所称菌（毒）种，是指具有保藏价值的动物细菌、真菌、放线菌、衣原体、支原体、立克次氏体、螺旋体、病毒等微生物。 本办法所称样本，是指人工采集的、经鉴定具有保藏价值的含有动物病原微生物的体液、组织、排泄物、分泌物、污染物等物质。 本办法所称保藏机构，是指承担菌（毒）种和样本保藏任务，并向合法从事动物病原微生物相关活动的实验室或者兽用生物制品企业提供菌（毒）种或者样本的单位。 菌（毒）种和样本的分类按照《动物病原微生物分类名录》的规定执行。"},{"i":4,"n":"第四条","txt":"农业农村部主管全国菌（毒）种和样本保藏管理工作。 县级以上地方人民政府畜牧兽医主管部门负责本行政区域内的菌（毒）种和样本保藏监督管理工作。"},{"i":5,"n":"第五条","txt":"国家对实验活动用菌（毒）种和样本实行集中保藏，保藏机构以外的任何单位和个人不得保藏菌（毒）种或者样本。"},{"i":6,"n":"第六条","txt":"保藏机构分为国家级保藏中心和省级保藏中心。保藏机构由农业农村部指定。 保藏机构保藏的菌（毒）种和样本的种类由农业农村部核定。"},{"i":7,"n":"第七条","txt":"保藏机构应当具备以下条件： （一）符合国家关于保藏机构设立的整体布局和实际需要； （二）有满足菌（毒）种和样本保藏需要的设施设备；保藏高致病性动物病原微生物菌（毒）种或者样本的，应当具有相应级别的高等级生物安全实验室，并依法取得《高致病性动物病原微生物实验室资格证书》； （三）有满足保藏工作要求的工作人员； （四）有完善的菌（毒）种和样本保管制度、安全保卫制度； （五）有满足保藏活动需要的经费。"},{"i":8,"n":"第八条","txt":"保藏机构的职责： （一）负责菌（毒）种和样本的收集、筛选、分析、鉴定和保藏； （二）开展菌（毒）种和样本的分类与保藏新方法、新技术研究； （三）建立菌（毒）种和样本数据库； （四）向合法从事动物病原微生物实验活动的实验室或者兽用生物制品生产企业提供菌（毒）种或者样本。"},{"i":9,"n":"第九条","txt":"从事动物疫情监测、疫病诊断、检验检疫和疫病研究等活动的单位和个人，应当及时将研究、教学、检测、诊断等实验活动中获得的具有保藏价值的菌（毒）种和样本，送交保藏机构鉴定和保藏，并提交菌（毒）种和样本的背景资料。 保藏机构可以向国内有关单位和个人索取需要保藏的菌（毒）种和样本。"},{"i":10,"n":"第十条","txt":"保藏机构应当向提供菌（毒）种和样本的单位和个人出具接收证明。"},{"i":11,"n":"第十一条","txt":"保藏机构应当在每年年底前将保藏的菌（毒）种和样本的种类、数量报农业农村部。"},{"i":12,"n":"第十二条","txt":"保藏机构应当设专库保藏一、二类菌（毒）种和样本，设专柜保藏三、四类菌（毒）种和样本。 保藏机构保藏的菌（毒）种和样本应当分类存放，实行双人双锁管理。"},{"i":13,"n":"第十三条","txt":"保藏机构应当建立完善的技术资料档案，详细记录所保藏的菌（毒）种和样本的名称、编号、数量、来源、病原微生物类别、主要特性、保存方法等情况。 技术资料档案应当永久保存。"},{"i":14,"n":"第十四条","txt":"保藏机构应当对保藏的菌（毒）种按时鉴定、复壮，妥善保藏，避免失活。 保藏机构对保藏的菌（毒）种开展鉴定、复壮的，应当按照规定在相应级别的生物安全实验室进行。"},{"i":15,"n":"第十五条","txt":"保藏机构应当制定实验室安全事故处理应急预案。发生保藏的菌（毒）种或者样本被盗、被抢、丢失、泄漏和实验室人员感染的，应当按照《病原微生物实验室生物安全管理条例》的规定及时报告、启动预案，并采取相应的处理措施。"},{"i":16,"n":"第十六条","txt":"实验室和兽用生物制品生产企业需要使用菌（毒）种或者样本的，应当向保藏机构提出申请。"},{"i":17,"n":"第十七条","txt":"保藏机构应当按照以下规定提供菌（毒）种或者样本： （一）提供高致病性动物病原微生物菌（毒）种或者样本的，查验从事高致病性动物病原微生物相关实验活动的批准文件； （二）提供兽用生物制品生产和检验用菌（毒）种或者样本的，查验兽药生产批准文号文件； （三）提供三、四类菌（毒）种或者样本的，查验实验室所在单位出具的证明。 保藏机构应当留存前款规定的证明文件的原件或者复印件。"},{"i":18,"n":"第十八条","txt":"保藏机构提供菌（毒）种或者样本时，应当进行登记，详细记录所提供的菌（毒）种或者样本的名称、数量、时间以及发放人、领取人、使用单位名称等。"},{"i":19,"n":"第十九条","txt":"保藏机构应当对具有知识产权的菌（毒）种承担相应的保密责任。 保藏机构提供具有知识产权的菌（毒）种或者样本的，应当经原提供者或者持有人的书面同意。"},{"i":20,"n":"第二十条","txt":"保藏机构提供的菌（毒）种或者样本应当附有标签，标明菌（毒）种名称、编号、移植和冻干日期等。"},{"i":21,"n":"第二十一条","txt":"保藏机构保藏菌（毒）种或者样本所需费用由同级财政在单位预算中予以保障。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一的，保藏机构应当组织专家论证，提出销毁菌（毒）种或者样本的建议： （一）国家规定应当销毁的； （二）有证据表明已丧失生物活性或者被污染，已不适于继续使用的； （三）无继续保藏价值的。"},{"i":23,"n":"第二十三条","txt":"保藏机构销毁一、二类菌（毒）种和样本的，应当经农业农村部批准；销毁三、四类菌（毒）种和样本的，应当经保藏机构负责人批准，并报农业农村部备案。 保藏机构销毁菌（毒）种和样本的，应当在实施销毁30日前书面告知原提供者。"},{"i":24,"n":"第二十四条","txt":"保藏机构销毁菌（毒）种和样本的，应当制定销毁方案，注明销毁的原因、品种、数量，以及销毁方式方法、时间、地点、实施人和监督人等。"},{"i":25,"n":"第二十五条","txt":"保藏机构销毁菌（毒）种和样本时，应当使用可靠的销毁设施和销毁方法，必要时应当组织开展灭活效果验证和风险评估。"},{"i":26,"n":"第二十六条","txt":"保藏机构销毁菌（毒）种和样本的，应当做好销毁记录，经销毁实施人、监督人签字后存档，并将销毁情况报农业农村部。"},{"i":27,"n":"第二十七条","txt":"实验室在相关实验活动结束后，应当按照规定及时将菌（毒）种和样本就地销毁或者送交保藏机构保管。"},{"i":28,"n":"第二十八条","txt":"国家对菌（毒）种和样本对外交流实行认定审批制度。"},{"i":29,"n":"第二十九条","txt":"从国外引进和向国外提供菌（毒）种或者样本的，应当报农业农村部批准。"},{"i":30,"n":"第三十条","txt":"从国外引进菌（毒）种或者样本的单位，应当在引进菌（毒）种或者样本后6个月内，将备份及其背景资料，送交保藏机构。 引进单位应当在相关活动结束后，及时将菌（毒）种和样本就地销毁。"},{"i":31,"n":"第三十一条","txt":"出口《生物两用品及相关设备和技术出口管制清单》所列的菌（毒）种或者样本的，还应当按照《生物两用品及相关设备和技术出口管制条例》的规定取得生物两用品及相关设备和技术出口许可证件。"},{"i":32,"n":"第三十二条","txt":"违反本办法规定，保藏或者提供菌（毒）种或者样本的，由县级以上地方人民政府畜牧兽医主管部门责令其将菌（毒）种或者样本销毁或者送交保藏机构；拒不销毁或者送交的，对单位处一万元以上三万元以下罚款，对个人处五百元以上一千元以下罚款。"},{"i":33,"n":"第三十三条","txt":"违反本办法规定，未及时向保藏机构提供菌（毒）种或者样本的，由县级以上地方人民政府畜牧兽医主管部门责令改正；拒不改正的，对单位处一万元以上三万元以下罚款，对个人处五百元以上一千元以下罚款。"},{"i":34,"n":"第三十四条","txt":"违反本办法规定，未经农业农村部批准，从国外引进或者向国外提供菌（毒）种或者样本的，由县级以上地方人民政府畜牧兽医主管部门责令其将菌（毒）种或者样本销毁或者送交保藏机构，并对单位处一万元以上三万元以下罚款，对个人处五百元以上一千元以下罚款。"},{"i":35,"n":"第三十五条","txt":"保藏机构违反本办法规定的，由农业农村部责令限期改正，并给予警告；造成严重后果的，由其所在单位或者其上级主管部门对主要负责人、直接负责的主管人员和其他直接责任人员依法予以处理。"},{"i":36,"n":"第三十六条","txt":"本办法自2009年1月1日起施行。1980年11月25日农业部发布的《兽医微生物菌种保藏管理试行办法》（农〔牧〕字第181号）同时废止。"}],"dongwuzhenliaojigouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强动物诊疗机构管理，规范动物诊疗行为，保障公共卫生安全，根据《中华人民共和国动物防疫法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事动物诊疗活动的机构，应当遵守本办法。 本办法所称动物诊疗，是指动物疾病的预防、诊断、治疗和动物绝育手术等经营性活动，包括动物的健康检查、采样、剖检、配药、给药、针灸、手术、填写诊断书和出具动物诊疗有关证明文件等。 本办法所称动物诊疗机构，包括动物医院、动物诊所以及其他提供动物诊疗服务的机构。"},{"i":3,"n":"第三条","txt":"农业农村部负责全国动物诊疗机构的监督管理。 县级以上地方人民政府农业农村主管部门负责本行政区域内动物诊疗机构的监督管理。"},{"i":4,"n":"第四条","txt":"农业农村部加强信息化建设，建立健全动物诊疗机构信息管理系统。 县级以上地方人民政府农业农村主管部门应当优化许可办理流程，推行网上办理等便捷方式，加强动物诊疗机构信息管理工作。"},{"i":5,"n":"第五条","txt":"国家实行动物诊疗许可制度。从事动物诊疗活动的机构，应当取得动物诊疗许可证，并在规定的诊疗活动范围内开展动物诊疗活动。"},{"i":6,"n":"第六条","txt":"从事动物诊疗活动的机构，应当具备下列条件： （一）有固定的动物诊疗场所，且动物诊疗场所使用面积符合省、自治区、直辖市人民政府农业农村主管部门的规定； （二）动物诊疗场所选址距离动物饲养场、动物屠宰加工场所、经营动物的集贸市场不少于二百米； （三）动物诊疗场所设有独立的出入口，出入口不得设在居民住宅楼内或者院内，不得与同一建筑物的其他用户共用通道； （四）具有布局合理的诊疗室、隔离室、药房等功能区； （五）具有诊断、消毒、冷藏、常规化验、污水处理等器械设备； （六）具有诊疗废弃物暂存处理设施，并委托专业处理机构处理； （七）具有染疫或者疑似染疫动物的隔离控制措施及设施设备； （八）具有与动物诊疗活动相适应的执业兽医； （九）具有完善的诊疗服务、疫情报告、卫生安全防护、消毒、隔离、诊疗废弃物暂存、兽医器械、兽医处方、药物和无害化处理等管理制度。"},{"i":7,"n":"第七条","txt":"动物诊所除具备本办法第六条规定的条件外，还应当具备下列条件： （一）具有一名以上执业兽医师； （二）具有布局合理的手术室和手术设备。"},{"i":8,"n":"第八条","txt":"动物医院除具备本办法第六条规定的条件外，还应当具备下列条件： （一）具有三名以上执业兽医师； （二）具有X光机或者B超等器械设备； （三）具有布局合理的手术室和手术设备。 除前款规定的动物医院外，其他动物诊疗机构不得从事动物颅腔、胸腔和腹腔手术。"},{"i":9,"n":"第九条","txt":"从事动物诊疗活动的机构，应当向动物诊疗场所所在地的发证机关提出申请，并提交下列材料： （一）动物诊疗许可证申请表； （二）动物诊疗场所地理方位图、室内平面图和各功能区布局图； （三）动物诊疗场所使用权证明； （四）法定代表人（负责人）身份证明； （五）执业兽医资格证书； （六）设施设备清单； （七）管理制度文本。 申请材料不齐全或者不符合规定条件的，发证机关应当自收到申请材料之日起五个工作日内一次性告知申请人需补正的内容。"},{"i":10,"n":"第十条","txt":"动物诊疗机构应当使用规范的名称。未取得相应许可的，不得使用“动物诊所”或者“动物医院”的名称。"},{"i":11,"n":"第十一条","txt":"发证机关受理申请后，应当在十五个工作日内完成对申请材料的审核和对动物诊疗场所的实地考查。符合规定条件的，发证机关应当向申请人颁发动物诊疗许可证；不符合条件的，书面通知申请人，并说明理由。 专门从事水生动物疫病诊疗的，发证机关在核发动物诊疗许可证时，应当征求同级渔业主管部门的意见。"},{"i":12,"n":"第十二条","txt":"动物诊疗许可证应当载明诊疗机构名称、诊疗活动范围、从业地点和法定代表人（负责人）等事项。 动物诊疗许可证格式由农业农村部统一规定。"},{"i":13,"n":"第十三条","txt":"动物诊疗机构设立分支机构的，应当按照本办法的规定另行办理动物诊疗许可证。"},{"i":14,"n":"第十四条","txt":"动物诊疗机构变更名称或者法定代表人（负责人）的，应当在办理市场主体变更登记手续后十五个工作日内，向原发证机关申请办理变更手续。 动物诊疗机构变更从业地点、诊疗活动范围的，应当按照本办法规定重新办理动物诊疗许可手续，申请换发动物诊疗许可证。"},{"i":15,"n":"第十五条","txt":"动物诊疗许可证不得伪造、变造、转让、出租、出借。 动物诊疗许可证遗失的，应当及时向原发证机关申请补发。"},{"i":16,"n":"第十六条","txt":"发证机关办理动物诊疗许可证，不得向申请人收取费用。"},{"i":17,"n":"第十七条","txt":"动物诊疗机构应当依法从事动物诊疗活动，建立健全内部管理制度，在诊疗场所的显著位置悬挂动物诊疗许可证和公示诊疗活动从业人员基本情况。"},{"i":18,"n":"第十八条","txt":"动物诊疗机构可以通过在本机构备案从业的执业兽医师，利用互联网等信息技术开展动物诊疗活动，活动范围不得超出动物诊疗许可证核定的诊疗活动范围。"},{"i":19,"n":"第十九条","txt":"动物诊疗机构应当对兽医相关专业学生、毕业生参与动物诊疗活动加强监督指导。"},{"i":20,"n":"第二十条","txt":"动物诊疗机构应当按照国家有关规定使用兽医器械和兽药，不得使用不符合规定的兽医器械、假劣兽药和农业农村部规定禁止使用的药品及其他化合物。"},{"i":21,"n":"第二十一条","txt":"动物诊疗机构兼营动物用品、动物饲料、动物美容、动物寄养等项目的，兼营区域与动物诊疗区域应当分别独立设置。"},{"i":22,"n":"第二十二条","txt":"动物诊疗机构应当使用载明机构名称的规范病历，包括门（急）诊病历和住院病历。病历档案保存期限不得少于三年。 病历根据不同的记录形式，分为纸质病历和电子病历。电子病历与纸质病历具有同等效力。 病历包括诊疗活动中形成的文字、符号、图表、影像、切片等内容或者资料。"},{"i":23,"n":"第二十三条","txt":"动物诊疗机构应当为执业兽医师提供兽医处方笺，处方笺的格式和保存等应当符合农业农村部规定的兽医处方格式及应用规范。"},{"i":24,"n":"第二十四条","txt":"动物诊疗机构安装、使用具有放射性的诊疗设备的，应当依法经生态环境主管部门批准。"},{"i":25,"n":"第二十五条","txt":"动物诊疗机构发现动物染疫或者疑似染疫的，应当按照国家规定立即向所在地农业农村主管部门或者动物疫病预防控制机构报告，并迅速采取隔离、消毒等控制措施，防止动物疫情扩散。 动物诊疗机构发现动物患有或者疑似患有国家规定应当扑杀的疫病时，不得擅自进行治疗。"},{"i":26,"n":"第二十六条","txt":"动物诊疗机构应当按照国家规定处理染疫动物及其排泄物、污染物和动物病理组织等。 动物诊疗机构应当参照《医疗废物管理条例》的有关规定处理诊疗废弃物，不得随意丢弃诊疗废弃物，排放未经无害化处理的诊疗废水。"},{"i":27,"n":"第二十七条","txt":"动物诊疗机构应当支持执业兽医按照当地人民政府或者农业农村主管部门的要求，参加动物疫病预防、控制和动物疫情扑灭活动。 动物诊疗机构可以通过承接政府购买服务的方式开展动物防疫和疫病诊疗活动。"},{"i":28,"n":"第二十八条","txt":"动物诊疗机构应当配合农业农村主管部门、动物卫生监督机构、动物疫病预防控制机构进行有关法律法规宣传、流行病学调查和监测工作。"},{"i":29,"n":"第二十九条","txt":"动物诊疗机构应当定期对本单位工作人员进行专业知识、生物安全以及相关政策法规培训。"},{"i":30,"n":"第三十条","txt":"动物诊疗机构应当于每年三月底前将上年度动物诊疗活动情况向县级人民政府农业农村主管部门报告。"},{"i":31,"n":"第三十一条","txt":"县级以上地方人民政府农业农村主管部门应当建立健全日常监管制度，对辖区内动物诊疗机构和人员执行法律、法规、规章的情况进行监督检查。"},{"i":32,"n":"第三十二条","txt":"违反本办法规定，动物诊疗机构有下列行为之一的，依照《中华人民共和国动物防疫法》第一百零五条第一款的规定予以处罚： （一）超出动物诊疗许可证核定的诊疗活动范围从事动物诊疗活动的； （二）变更从业地点、诊疗活动范围未重新办理动物诊疗许可证的。"},{"i":33,"n":"第三十三条","txt":"使用伪造、变造、受让、租用、借用的动物诊疗许可证的，县级以上地方人民政府农业农村主管部门应当依法收缴，并依照《中华人民共和国动物防疫法》第一百零五条第一款的规定予以处罚。"},{"i":34,"n":"第三十四条","txt":"动物诊疗场所不再具备本办法第六条、第七条、第八条规定条件，继续从事动物诊疗活动的，由县级以上地方人民政府农业农村主管部门给予警告，责令限期改正；逾期仍达不到规定条件的，由原发证机关收回、注销其动物诊疗许可证。"},{"i":35,"n":"第三十五条","txt":"违反本办法规定，动物诊疗机构有下列行为之一的，由县级以上地方人民政府农业农村主管部门责令限期改正，处一千元以上五千元以下罚款： （一）变更机构名称或者法定代表人（负责人）未办理变更手续的； （二）未在诊疗场所悬挂动物诊疗许可证或者公示诊疗活动从业人员基本情况的； （三）未使用规范的病历或未按规定为执业兽医师提供处方笺的，或者不按规定保存病历档案的； （四）使用未在本机构备案从业的执业兽医从事动物诊疗活动的。"},{"i":36,"n":"第三十六条","txt":"动物诊疗机构未按规定实施卫生安全防护、消毒、隔离和处置诊疗废弃物的，依照《中华人民共和国动物防疫法》第一百零五条第二款的规定予以处罚。"},{"i":37,"n":"第三十七条","txt":"诊疗活动从业人员有下列行为之一的，依照《中华人民共和国动物防疫法》第一百零六条第一款的规定，对其所在的动物诊疗机构予以处罚： （一）执业兽医超出备案所在县域或者执业范围从事动物诊疗活动的； （二）执业兽医被责令暂停动物诊疗活动期间从事动物诊疗活动的； （三）执业助理兽医师未按规定开展手术活动，或者开具处方、填写诊断书、出具动物诊疗有关证明文件的； （四）参加教学实践的学生或者工作实践的毕业生未经执业兽医师指导开展动物诊疗活动的。"},{"i":38,"n":"第三十八条","txt":"违反本办法规定，动物诊疗机构未按规定报告动物诊疗活动情况的，依照《中华人民共和国动物防疫法》第一百零八条的规定予以处罚。"},{"i":39,"n":"第三十九条","txt":"县级以上地方人民政府农业农村主管部门不依法履行审查和监督管理职责，玩忽职守、滥用职权或者徇私舞弊的，依照有关规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"乡村兽医在乡村从事动物诊疗活动的，应当有固定的从业场所。"},{"i":41,"n":"第四十一条","txt":"本办法所称发证机关，是指县（市辖区）级人民政府农业农村主管部门；市辖区未设立农业农村主管部门的，发证机关为上一级农业农村主管部门。"},{"i":42,"n":"第四十二条","txt":"本办法自2022年10月1日起施行。农业部2008年11月26日公布，2016年5月30日、2017年11月30日修订的《动物诊疗机构管理办法》同时废止。 本办法施行前已取得动物诊疗许可证的动物诊疗机构，应当自本办法实施之日起一年内达到本办法规定的条件。"}],"dongwufangyitiaojianshenchabanfa":[{"i":1,"n":"第一条","txt":"为了规范动物防疫条件审查，有效预防、控制、净化、消灭动物疫病，防控人畜共患传染病，保障公共卫生安全和人体健康，根据《中华人民共和国动物防疫法》，制定本办法。"},{"i":2,"n":"第二条","txt":"动物饲养场、动物隔离场所、动物屠宰加工场所以及动物和动物产品无害化处理场所，应当符合本办法规定的动物防疫条件，并取得动物防疫条件合格证。 经营动物和动物产品的集贸市场应当符合本办法规定的动物防疫条件。"},{"i":3,"n":"第三条","txt":"农业农村部主管全国动物防疫条件审查和监督管理工作。 县级以上地方人民政府农业农村主管部门负责本行政区域内的动物防疫条件审查和监督管理工作。"},{"i":4,"n":"第四条","txt":"动物防疫条件审查应当遵循公开、公平、公正、便民的原则。"},{"i":5,"n":"第五条","txt":"农业农村部加强信息化建设，建立动物防疫条件审查信息管理系统。"},{"i":6,"n":"第六条","txt":"动物饲养场、动物隔离场所、动物屠宰加工场所以及动物和动物产品无害化处理场所应当符合下列条件： （一）各场所之间，各场所与动物诊疗场所、居民生活区、生活饮用水水源地、学校、医院等公共场所之间保持必要的距离； （二）场区周围建有围墙等隔离设施；场区出入口处设置运输车辆消毒通道或者消毒池，并单独设置人员消毒通道；生产经营区与生活办公区分开，并有隔离设施；生产经营区入口处设置人员更衣消毒室； （三）配备与其生产经营规模相适应的执业兽医或者动物防疫技术人员； （四）配备与其生产经营规模相适应的污水、污物处理设施，清洗消毒设施设备，以及必要的防鼠、防鸟、防虫设施设备； （五）建立隔离消毒、购销台账、日常巡查等动物防疫制度。"},{"i":7,"n":"第七条","txt":"动物饲养场除符合本办法第六条规定外，还应当符合下列条件： （一）设置配备疫苗冷藏冷冻设备、消毒和诊疗等防疫设备的兽医室； （二）生产区清洁道、污染道分设；具有相对独立的动物隔离舍； （三）配备符合国家规定的病死动物和病害动物产品无害化处理设施设备或者冷藏冷冻等暂存设施设备； （四）建立免疫、用药、检疫申报、疫情报告、无害化处理、畜禽标识及养殖档案管理等动物防疫制度。 禽类饲养场内的孵化间与养殖区之间应当设置隔离设施，并配备种蛋熏蒸消毒设施，孵化间的流程应当单向，不得交叉或者回流。 种畜禽场除符合本条第一款、第二款规定外，还应当有国家规定的动物疫病的净化制度；有动物精液、卵、胚胎采集等生产需要的，应当设置独立的区域。"},{"i":8,"n":"第八条","txt":"动物隔离场所除符合本办法第六条规定外，还应当符合下列条件： （一）饲养区内设置配备疫苗冷藏冷冻设备、消毒和诊疗等防疫设备的兽医室； （二）饲养区内清洁道、污染道分设； （三）配备符合国家规定的病死动物和病害动物产品无害化处理设施设备或者冷藏冷冻等暂存设施设备； （四）建立动物进出登记、免疫、用药、疫情报告、无害化处理等动物防疫制度。"},{"i":9,"n":"第九条","txt":"动物屠宰加工场所除符合本办法第六条规定外，还应当符合下列条件： （一）入场动物卸载区域有固定的车辆消毒场地，并配备车辆清洗消毒设备； （二）有与其屠宰规模相适应的独立检疫室和休息室；有待宰圈、急宰间，加工原毛、生皮、绒、骨、角的，还应当设置封闭式熏蒸消毒间； （三）屠宰间配备检疫操作台； （四）有符合国家规定的病死动物和病害动物产品无害化处理设施设备或者冷藏冷冻等暂存设施设备； （五）建立动物进场查验登记、动物产品出场登记、检疫申报、疫情报告、无害化处理等动物防疫制度。"},{"i":10,"n":"第十条","txt":"动物和动物产品无害化处理场所除符合本办法第六条规定外，还应当符合下列条件： （一）无害化处理区内设置无害化处理间、冷库； （二）配备与其处理规模相适应的病死动物和病害动物产品的无害化处理设施设备，符合农业农村部规定条件的专用运输车辆，以及相关病原检测设备，或者委托有资质的单位开展检测； （三）建立病死动物和病害动物产品入场登记、无害化处理记录、病原检测、处理产物流向登记、人员防护等动物防疫制度。"},{"i":11,"n":"第十一条","txt":"经营动物和动物产品的集贸市场应当符合下列条件： （一）场内设管理区、交易区和废弃物处理区，且各区相对独立； （二）动物交易区与动物产品交易区相对隔离，动物交易区内不同种类动物交易场所相对独立； （三）配备与其经营规模相适应的污水、污物处理设施和清洗消毒设施设备； （四）建立定期休市、清洗消毒等动物防疫制度。 经营动物的集贸市场，除符合前款规定外，周围应当建有隔离设施，运输动物车辆出入口处设置消毒通道或者消毒池。"},{"i":12,"n":"第十二条","txt":"活禽交易市场除符合本办法第十一条规定外，还应当符合下列条件： （一）活禽销售应单独分区，有独立出入口；市场内水禽与其他家禽应相对隔离；活禽宰杀间应相对封闭，宰杀间、销售区域、消费者之间应实施物理隔离； （二）配备通风、无害化处理等设施设备，设置排污通道； （三）建立日常监测、从业人员卫生防护、突发事件应急处置等动物防疫制度。"},{"i":13,"n":"第十三条","txt":"开办动物饲养场、动物隔离场所、动物屠宰加工场所以及动物和动物产品无害化处理场所，应当向县级人民政府农业农村主管部门提交选址需求。 县级人民政府农业农村主管部门依据评估办法，结合场所周边的天然屏障、人工屏障、饲养环境、动物分布等情况，以及动物疫病发生、流行和控制等因素，实施综合评估，确定本办法第六条第一项要求的距离，确认选址。 前款规定的评估办法由省级人民政府农业农村主管部门依据《中华人民共和国畜牧法》《中华人民共和国动物防疫法》等法律法规和本办法制定。"},{"i":14,"n":"第十四条","txt":"本办法第十三条规定的场所建设竣工后，应当向所在地县级人民政府农业农村主管部门提出申请，并提交以下材料： （一）《动物防疫条件审查申请表》； （二）场所地理位置图、各功能区布局平面图； （三）设施设备清单； （四）管理制度文本； （五）人员信息。 申请材料不齐全或者不符合规定条件的，县级人民政府农业农村主管部门应当自收到申请材料之日起五个工作日内，一次性告知申请人需补正的内容。"},{"i":15,"n":"第十五条","txt":"县级人民政府农业农村主管部门应当自受理申请之日起十五个工作日内完成材料审核，并结合选址综合评估结果完成现场核查，审查合格的，颁发动物防疫条件合格证；审查不合格的，应当书面通知申请人，并说明理由。"},{"i":16,"n":"第十六条","txt":"动物防疫条件合格证应当载明申请人的名称（姓名）、场（厂）址、动物（动物产品）种类等事项，具体格式由农业农村部规定。"},{"i":17,"n":"第十七条","txt":"患有人畜共患传染病的人员不得在本办法第二条所列场所直接从事动物疫病检测、检验、协助检疫、诊疗以及易感染动物的饲养、屠宰、经营、隔离等活动。"},{"i":18,"n":"第十八条","txt":"县级以上地方人民政府农业农村主管部门依照《中华人民共和国动物防疫法》和本办法以及有关法律、法规的规定，对本办法第二条所列场所的动物防疫条件实施监督检查，有关单位和个人应当予以配合，不得拒绝和阻碍。"},{"i":19,"n":"第十九条","txt":"推行动物饲养场分级管理制度，根据规模、设施设备状况、管理水平、生物安全风险等因素采取差异化监管措施。"},{"i":20,"n":"第二十条","txt":"取得动物防疫条件合格证后，变更场址或者经营范围的，应当重新申请办理，同时交回原动物防疫条件合格证，由原发证机关予以注销。 变更布局、设施设备和制度，可能引起动物防疫条件发生变化的，应当提前三十日向原发证机关报告。发证机关应当在十五日内完成审查，并将审查结果通知申请人。 变更单位名称或者法定代表人（负责人）的，应当在变更后十五日内持有效证明申请变更动物防疫条件合格证。"},{"i":21,"n":"第二十一条","txt":"动物饲养场、动物隔离场所、动物屠宰加工场所以及动物和动物产品无害化处理场所，应当在每年三月底前将上一年的动物防疫条件情况和防疫制度执行情况向县级人民政府农业农村主管部门报告。"},{"i":22,"n":"第二十二条","txt":"禁止转让、伪造或者变造动物防疫条件合格证。"},{"i":23,"n":"第二十三条","txt":"动物防疫条件合格证丢失或者损毁的，应当在十五日内向原发证机关申请补发。"},{"i":24,"n":"第二十四条","txt":"违反本办法规定，有下列行为之一的，依照《中华人民共和国动物防疫法》第九十八条的规定予以处罚: （一）动物饲养场、动物隔离场所、动物屠宰加工场所以及动物和动物产品无害化处理场所变更场所地址或者经营范围，未按规定重新办理动物防疫条件合格证的； （二）经营动物和动物产品的集贸市场不符合本办法第十一条、第十二条动物防疫条件的。"},{"i":25,"n":"第二十五条","txt":"违反本办法规定，动物饲养场、动物隔离场所、动物屠宰加工场所以及动物和动物产品无害化处理场所未经审查变更布局、设施设备和制度，不再符合规定的动物防疫条件继续从事相关活动的，依照《中华人民共和国动物防疫法》第九十九条的规定予以处罚。"},{"i":26,"n":"第二十六条","txt":"违反本办法规定，动物饲养场、动物隔离场所、动物屠宰加工场所以及动物和动物产品无害化处理场所变更单位名称或者法定代表人（负责人）未办理变更手续的，由县级以上地方人民政府农业农村主管部门责令限期改正；逾期不改正的，处一千元以上五千元以下罚款。"},{"i":27,"n":"第二十七条","txt":"违反本办法规定，动物饲养场、动物隔离场所、动物屠宰加工场所以及动物和动物产品无害化处理场所未按规定报告动物防疫条件情况和防疫制度执行情况的，依照《中华人民共和国动物防疫法》第一百零八条的规定予以处罚。"},{"i":28,"n":"第二十八条","txt":"违反本办法规定，涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"本办法所称动物饲养场是指《中华人民共和国畜牧法》规定的畜禽养殖场。 本办法所称经营动物和动物产品的集贸市场，是指经营畜禽或者专门经营畜禽产品，并取得营业执照的集贸市场。 动物饲养场内自用的隔离舍，参照本办法第八条规定执行，不再另行办理动物防疫条件合格证。 动物饲养场、隔离场所、屠宰加工场所内的无害化处理区域，参照本办法第十条规定执行，不再另行办理动物防疫条件合格证。"},{"i":30,"n":"第三十条","txt":"本办法自2022年12月1日起施行。农业部2010年1月21日公布的《动物防疫条件审查办法》同时废止。 本办法施行前已取得动物防疫条件合格证的各类场所，应当自本办法实施之日起一年内达到本办法规定的条件。"}],"lvsichangjiangkouhezhoushanyuchangbufenhaiyubulaox043cbd":[],"guowaiyinzhongjianyishenpiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对国外（含境外，下同）引进种子、苗木和其他繁殖材料的检疫管理，根据《植物检疫条例》第十二条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"从国外引进种子、苗木和其他繁殖材料，实行农业部和各省、自治区、直辖市农业厅（局）两级审批，其执行机构是农业部全国植物保护总站和各省、自治区，直辖市农业厅（局）植物检疫（植保植检）站。"},{"i":3,"n":"第三条","txt":"引进种子、苗木和其他繁殖材料的单位或代理进口单位（以下统称引种单位）必须在对外贸易合同或者协议中，列入《引进种子、苗木检疫审批单》上所提对外植物检疫要求，并订明必须附有输出国家或者地区政府植物检疫机关出具的植物检疫证书，证明符合我国所提对外植物检疫要求。"},{"i":4,"n":"第四条","txt":"引种检疫申请 （一）引种单位应当在对外签订贸易合同、协议30日前，申请办理国外引种检疫审批手续。 （二）国务院和中央各部门所属在京单位、驻京部队单位、外国驻京机构等，向农业部全国植物保护总站提出申请；各省、自治区，直辖市有关单位和中央京外单位向种植地的省、自治区、直辖市农业厅（局）植物检疫（植保植检）站提出申请。 （三）引种单位提出申请时，必须按规定的格式及要求填写《引进种子、苗木检疫审批申请书》（附件1）；引进生产用种苗须同时提供有效的进口种苗权证明材料。报农业部全国植物保护总站审批的生产用种苗，还须提供种植地的省，自治区，直辖市农业厅（局）植物检疫（植保植检）站签署的有关种苗的疫情监测报告。 （四）引种单位应调查了解引进植物在原产地的病虫发生情况，并在申请时向检疫审批单位提供有关疫情资料，对于引进数量较大、疫情不清，与农业安全生产密切相关的种苗，引种单位应事先进行有检疫人员参加的"},{"i":5,"n":"第五条","txt":"检疫审批 （一）检疫审批单位自收到《引进种子、苗木检疫审批申请书》之日起15天内予以审批或签复。 （二）农作物种质资源和科研试验材料引进，国务院和中央各部门所属在京单位、驻京部队单位、外国驻京机构等，由农业部全国植物保护总站审批；各省、自治区、直辖市有关单位和中央京外单位由种植地的省、自治区、直辖市农业厅（局）植物检疫（植保植检）站审批，热带作物种质资源交换和引进由农业部农垦司签署意见后，报农业部全国植物保护总站审批，种质资源和科研试验材料检疫审批限量见附件2。 （三）国际区域性试验和对外制种的种苗引进，由种植地的省、自治区、直辖市农业厅（局）植物检疫（植保植检）站签署意见后，报农业部全国植物保护总站审批。 （四）生产用种苗的引进 1．对于新引进的（指从未引进和近三年内未引进）的作物或品种的引进，必须事先少量隔离试种（种子以2亩地，苗木以50株用量为限），引种单位在申请引进前，应安排好"},{"i":6,"n":"第六条","txt":"种苗入境后检疫 （一）引进种苗经口岸动植物检疫机关检疫后，《引进种子、苗木硷疫审批单》回执由口岸动植物检疫机关及时寄回种苗审批单位核查。 （二）种苗引进后，引种单位必须按照《引进种子、苗木检疫审批单》上指定的地点进行引进种苗隔离试种或者隔离种植。隔离试种或者隔离种植期限，一年生植物不得小于一个生育周期，多年生植物不得少于两年。隔离试种或者隔离种植期间，由种植地的省农业厅（局）植物检疫（植保植检）站负责疫情监测，并签署症情监测报告。必要时，由全国植物保护总站组织重点疫情监测。 （三）在隔离种植期间，发现疫情的，引进单位必须在检疫部门的指导和监督下，及时采取封锁，控制和消灭措施，严防疫情扩散，并承担实施检疫处理的全部费用。"},{"i":7,"n":"第七条","txt":"检疫审批管理 （一）国外引种检疫审批实行季度报表制度。各省、自治区、直辖市植物检疫（植保植检）站应当在每新季度开始第一个月十日内，将上一季度“引进种苗检疫审批及疫情监测情况”（见附件5）上报全国植物保护总站。发现重大疫情时，应当及时报告。 （二）“国外引种检疫审批限量表”，由全国植物保护总站根据疫情变化情况和农业生产发展的实际需要，进行修订。 《引进种子、苗木检疫审批申请书》、《引进种子、苗木检疫审批单》由农业部全国植物保护总站统一制定格式，各省、自治区，直辖市农业厅（局）统一翻印。 （三）国外引种检疫审批费、种植期间疫情监测费按国家有关规定收取。因实施重点疫情调查的检疫费用由引种单位承担。"},{"i":8,"n":"第八条","txt":"违反本办法规定的，按国家有关植物检疫规定处罚。"},{"i":9,"n":"第九条","txt":"本办法自发布之日起施行，1980年8月12日农业部关于印发《引进种子、苗木检疫审批单》的函和1990年8月13日农业部印发《关于国外引种检疫审批工作的补充规定（试行）》的通知同时废止。"}],"wailairuqinwuzhongguanlibanfa":[{"i":1,"n":"第一条","txt":"为了防范和应对外来入侵物种危害，保障农林牧渔业可持续发展，保护生物多样性，根据《中华人民共和国生物安全法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称外来物种，是指在中华人民共和国境内无天然分布，经自然或人为途径传入的物种，包括该物种所有可能存活和繁殖的部分。 本办法所称外来入侵物种，是指传入定殖并对生态系统、生境、物种带来威胁或者危害，影响我国生态环境，损害农林牧渔业可持续发展和生物多样性的外来物种。"},{"i":3,"n":"第三条","txt":"外来入侵物种管理是维护国家生物安全的重要举措，应当坚持风险预防、源头管控、综合治理、协同配合、公众参与的原则。"},{"i":4,"n":"第四条","txt":"农业农村部会同国务院有关部门建立外来入侵物种防控部际协调机制，研究部署全国外来入侵物种防控工作，统筹协调解决重大问题。 省级人民政府农业农村主管部门会同有关部门建立外来入侵物种防控协调机制，组织开展本行政区域外来入侵物种防控工作。 海关完善境外风险预警和应急处理机制，强化入境货物、运输工具、寄递物、旅客行李、跨境电商、边民互市等渠道外来入侵物种的口岸检疫监管。"},{"i":5,"n":"第五条","txt":"县级以上地方人民政府依法对本行政区域外来入侵物种防控工作负责，组织、协调、督促有关部门依法履行外来入侵物种防控管理职责。 县级以上地方人民政府农业农村主管部门负责农田生态系统、渔业水域等区域外来入侵物种的监督管理。 县级以上地方人民政府林业草原主管部门负责森林、草原、湿地生态系统和自然保护地等区域外来入侵物种的监督管理。 沿海县级以上地方人民政府自然资源（海洋）主管部门负责近岸海域、海岛等区域外来入侵物种的监督管理。 县级以上地方人民政府生态环境主管部门负责外来入侵物种对生物多样性影响的监督管理。 高速公路沿线、城镇绿化带、花卉苗木交易市场等区域的外来入侵物种监督管理，由县级以上地方人民政府其他相关主管部门负责。"},{"i":6,"n":"第六条","txt":"农业农村部会同有关部门制定外来入侵物种名录，实行动态调整和分类管理，建立外来入侵物种数据库，制修订外来入侵物种风险评估、监测预警、防控治理等技术规范。"},{"i":7,"n":"第七条","txt":"农业农村部会同有关部门成立外来入侵物种防控专家委员会，为外来入侵物种管理提供咨询、评估、论证等技术支撑。"},{"i":8,"n":"第八条","txt":"农业农村部、自然资源部、生态环境部、海关总署、国家林业和草原局等主管部门建立健全应急处置机制，组织制订相关领域外来入侵物种突发事件应急预案。 县级以上地方人民政府有关部门应当组织制订本行政区域相关领域外来入侵物种突发事件应急预案。"},{"i":9,"n":"第九条","txt":"县级以上人民政府农业农村、自然资源（海洋）、生态环境、林业草原等主管部门加强外来入侵物种防控宣传教育与科学普及，增强公众外来入侵物种防控意识，引导公众依法参与外来入侵物种防控工作。 任何单位和个人未经批准，不得擅自引进、释放或者丢弃外来物种。"},{"i":10,"n":"第十条","txt":"因品种培育等特殊需要从境外引进农作物和林草种子苗木、水产苗种等外来物种的，应当依据审批权限向省级以上人民政府农业农村、林业草原主管部门和海关办理进口审批与检疫审批。 属于首次引进的，引进单位应当就引进物种对生态环境的潜在影响进行风险分析，并向审批部门提交风险评估报告。审批部门应当及时组织开展审查评估。经评估有入侵风险的，不予许可入境。"},{"i":11,"n":"第十一条","txt":"引进单位应当采取安全可靠的防范措施，加强引进物种研究、保存、种植、繁殖、运输、销毁等环节管理，防止其逃逸、扩散至野外环境。 对于发生逃逸、扩散的，引进单位应当及时采取清除、捕回或其他补救措施，并及时向审批部门及所在地县级人民政府农业农村或林业草原主管部门报告。"},{"i":12,"n":"第十二条","txt":"海关应当加强外来入侵物种口岸防控，对非法引进、携带、寄递、走私外来物种等违法行为进行打击。对发现的外来入侵物种以及经评估具有入侵风险的外来物种，依法进行处置。"},{"i":13,"n":"第十三条","txt":"县级以上地方人民政府农业农村、林业草原主管部门应当依法加强境内跨区域调运农作物和林草种子苗木、植物产品、水产苗种等检疫监管，防止外来入侵物种扩散传播。"},{"i":14,"n":"第十四条","txt":"农业农村部、自然资源部、生态环境部、海关总署、国家林业和草原局等主管部门依据职责分工，对可能通过气流、水流等自然途径传入我国的外来物种加强动态跟踪和风险评估。 有关部门应当对经外来入侵物种防控专家委员会评估具有较高入侵风险的物种采取必要措施，加大防范力度。"},{"i":15,"n":"第十五条","txt":"农业农村部会同有关部门建立外来入侵物种普查制度，每十年组织开展一次全国普查，掌握我国外来入侵物种的种类数量、分布范围、危害程度等情况，并将普查成果纳入国土空间基础信息平台和自然资源“一张图”。"},{"i":16,"n":"第十六条","txt":"农业农村部会同有关部门建立外来入侵物种监测制度，构建全国外来入侵物种监测网络，按照职责分工布设监测站点，组织开展常态化监测。 县级以上地方人民政府农业农村主管部门会同有关部门按照职责分工开展本行政区域外来入侵物种监测工作。"},{"i":17,"n":"第十七条","txt":"县级以上地方人民政府农业农村、自然资源（海洋）、生态环境、林业草原等主管部门和海关应当按照职责分工及时收集汇总外来入侵物种监测信息，并报告上级主管部门。 任何单位和个人不得瞒报、谎报监测信息，不得擅自发布监测信息。"},{"i":18,"n":"第十八条","txt":"省级以上人民政府农业农村、自然资源（海洋）、生态环境、林业草原等主管部门和海关应当加强外来入侵物种监测信息共享，分析研判外来入侵物种发生、扩散趋势，评估危害风险，及时发布预警预报，提出应对措施，指导开展防控。"},{"i":19,"n":"第十九条","txt":"农业农村部会同有关部门建立外来入侵物种信息发布制度。全国外来入侵物种总体情况由农业农村部商有关部门统一发布。自然资源部、生态环境部、海关总署、国家林业和草原局等主管部门依据职责权限发布本领域外来入侵物种发生情况。 省级人民政府农业农村主管部门商有关部门统一发布本行政区域外来入侵物种情况。"},{"i":20,"n":"第二十条","txt":"农业农村部、自然资源部、生态环境部、国家林业和草原局按照职责分工，研究制订本领域外来入侵物种防控策略措施，指导地方开展防控。 县级以上地方人民政府农业农村、自然资源（海洋）、林业草原等主管部门应当按照职责分工，在综合考虑外来入侵物种种类、危害对象、危害程度、扩散趋势等因素的基础上，制订本行政区域外来入侵物种防控治理方案，并组织实施，及时控制或消除危害。"},{"i":21,"n":"第二十一条","txt":"外来入侵植物的治理，可根据实际情况在其苗期、开花期或结实期等生长关键时期，采取人工拔除、机械铲除、喷施绿色药剂、释放生物天敌等措施。"},{"i":22,"n":"第二十二条","txt":"外来入侵病虫害的治理，应当采取选用抗病虫品种、种苗预处理、物理清除、化学灭除、生物防治等措施，有效阻止病虫害扩散蔓延。"},{"i":23,"n":"第二十三条","txt":"外来入侵水生动物的治理，应当采取针对性捕捞等措施，防止其进一步扩散危害。"},{"i":24,"n":"第二十四条","txt":"外来入侵物种发生区域的生态系统恢复，应当因地制宜采取种植乡土植物、放流本地种等措施。"},{"i":25,"n":"第二十五条","txt":"违反本办法规定，未经批准，擅自引进、释放或者丢弃外来物种的，依照《中华人民共和国生物安全法》第八十一条处罚。涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"本办法自2022年8月1日起施行。"}],"jiachuyichuancailiaoshengchanxukebanfa":[{"i":1,"n":"第一条","txt":"为加强家畜冷冻精液、胚胎、卵子等遗传材料（以下简称家畜遗传材料）生产的管理，根据《中华人民共和国畜牧法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称冷冻精液，是指经超低温冷冻保存的家畜精液。 本办法所称胚胎，是指用人工方法获得的家畜早期胚胎，包括体内受精胚胎和体外受精胚胎。 本办法所称卵子，是指母畜卵巢所产生的卵母细胞，包括体外培养卵母细胞。"},{"i":3,"n":"第三条","txt":"从事家畜遗传材料生产的单位和个人，应当依照本办法取得省级人民政府畜牧兽医行政主管部门核发的《种畜禽生产经营许可证》。"},{"i":4,"n":"第四条","txt":"从事家畜遗传材料生产的单位和个人，应当具备下列条件： （一）与生产规模相适应的家畜饲养、繁育、治疗场地和家畜遗传材料生产、质量检测、产品储存、档案管理场所； （二）与生产规模相适应的家畜饲养和遗传材料生产、检测、保存、运输等设施设备。其中，生产冷冻精液应当配备精子密度测定仪、相差显微镜、分析天平、细管精液分装机、细管印字机、精液冷冻程控仪、低温平衡柜、超低温贮存设备等仪器设备；生产胚胎和卵子应当配备超净台或洁净间、体视显微镜、超低温贮存设备等，生产体外胚胎还应当配备二氧化碳培养箱等仪器设备； （三）种畜为通过国家畜禽遗传资源委员会审定或者鉴定的品种，或者为农业部批准引进的境外品种，并符合种用标准； （四）体外受精取得的胚胎、使用的卵子来源明确，三代系谱清楚，供体畜符合国家规定的种畜健康标准和质量要求； （五）饲养的种畜达到农业部规定的数量。其中，生产牛冷冻精液的合格采精种公牛数量不少于"},{"i":5,"n":"第五条","txt":"申请取得家畜遗传材料生产许可的，应当向所在地省级人民政府畜牧兽医行政主管部门提出，并提交以下材料： （一）申请表； （二）生产条件说明材料； （三）家畜遗传材料供体畜的原始系谱复印件；优良种畜证书复印件;从国内引进的种畜及遗传材料提供引种场的《种畜禽生产经营许可证》复印件，从境外引进的种畜及遗传材料提供农业部审批复印件；生产卵子、胚胎的提供供体畜来源证明； （四）仪器设备检定报告复印件； （五）技术人员资格证书或者学历证书及培训合格证明的复印件； （六）动物防疫条件合格证复印件； （七）饲养、繁育、生产、质量检测、储存等管理制度； （八）申请换发家畜遗传材料生产许可证的，应当提供近三年内家畜遗传材料的生产和销售情况； （九）农业部规定的其他技术材料。 申请材料不齐全，或者不符合法定形式的，省级人民政府畜牧兽医行政主管部门应当当场或者自收到申请材料之日起5个工作日内，一次告知申请人需要补"},{"i":6,"n":"第六条","txt":"省级人民政府畜牧兽医行政主管部门自受理申请之日起10个工作日内完成书面审查。对通过书面审查的，组织专家现场评审。"},{"i":7,"n":"第七条","txt":"农业部设立家畜遗传材料生产许可专家库，负责家畜遗传材料生产许可的技术支撑工作。"},{"i":8,"n":"第八条","txt":"现场评审实行专家组负责制。专家组由省级人民政府畜牧兽医行政主管部门指定的5名以上畜牧兽医专业高级技术职称人员组成，人数为单数，可以从农业部家畜遗传材料生产许可专家库中选取。 专家组组长负责现场评审的召集、组织和汇总现场评审意见等工作。"},{"i":9,"n":"第九条","txt":"专家组应当对家畜遗传材料生产场所及布局、仪器设备、防疫等基本条件进行审查。"},{"i":10,"n":"第十条","txt":"专家组应当根据家畜种用标准和全国畜牧总站公布的种公牛育种值，对家畜冷冻精液、胚胎、卵子的供体畜逐一进行评定。"},{"i":11,"n":"第十一条","txt":"专家组应当对技术人员的相关法律法规、生产规程、产品技术标准等知识进行理论考核；对家畜冷冻精液、胚胎、卵子的完整生产流程进行考核，并随机抽取3个以上关键环节，对相关技术人员进行实际操作考核。"},{"i":12,"n":"第十二条","txt":"专家组应当抽查30％以上的仪器设备，对设备的性能与分辨率、完好率、操作规程、使用记录、检测情况等内容进行核查。"},{"i":13,"n":"第十三条","txt":"申请人应当在专家组的监督下，对每头供体畜生产的冷冻精液、3%供体畜生产的胚胎和卵子进行现场随机取样封存，送具有法定资质的种畜禽质量检验机构检测。"},{"i":14,"n":"第十四条","txt":"现场评审完成后，专家组应当形成书面评审意见，由专家组成员签字确认。 评审意见书包括以下内容： （一）申报材料核查情况； （二）生产基本条件审查结论； （三）家畜遗传材料供体评定结果； （四）技术人员理论和实际操作考核结果； （五）家畜饲养、繁育和遗传材料生产、产品质量控制、质量检测等规章制度落实情况。 评审意见一式三份，一份交申请人保存，两份报省级人民政府畜牧兽医行政主管部门。"},{"i":15,"n":"第十五条","txt":"现场评审应当自书面审查通过之日起40个工作日内完成。"},{"i":16,"n":"第十六条","txt":"省级人民政府畜牧兽医行政主管部门自收到现场评审意见和家畜遗传材料质量检测报告后10个工作日内，决定是否发放《种畜禽生产经营许可证》。不予发放的，书面通知申请人，并说明理由。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，不予发放《种畜禽生产经营许可证》： （一）现场评审不合格的； （二）冷冻精液质量检测合格的供体畜数量低于本办法第四条第五项规定的； （三）送检的胚胎或者卵子质量检测不合格的。"},{"i":18,"n":"第十八条","txt":"省级人民政府畜牧兽医行政主管部门在核发生产家畜冷冻精液的《种畜禽生产经营许可证》的同时，公布合格供体畜的编号。 家畜冷冻精液生产单位和个人在许可证有效期内新增供体畜的，应当及时向省级人民政府畜牧兽医行政主管部门申报。省级人民政府畜牧兽医行政主管部门按照本办法的规定组织对供体畜进行现场评审及冷冻精液质量检测，符合规定条件的，公布供体畜编号。 未经公布编号的供体畜，不得投入生产。 生产单位和个人应当及时淘汰冷冻精液不合格的供体畜。拒不淘汰的，由省级人民政府畜牧兽医行政主管部门公布不合格供体畜的编号，并依法予以处罚。"},{"i":19,"n":"第十九条","txt":"省级人民政府畜牧兽医行政主管部门核发的家畜遗传材料《种畜禽生产经营许可证》有效期3年。期满继续从事家畜遗传材料生产的，申请人应当在许可证有效期满5个月前，依照本办法规定重新提出申请。"},{"i":20,"n":"第二十条","txt":"已取得家畜遗传材料《种畜禽生产经营许可证》的单位和个人，申请扩大家畜遗传材料生产范围时，省级人民政府畜牧兽医行政主管部门可在组织现场评审环节适当简化相关程序。"},{"i":21,"n":"第二十一条","txt":"省级人民政府畜牧兽医行政主管部门应当自发放家畜遗传材料《种畜禽生产经营许可证》起20个工作日内，将现场评审、质量检测报告、批准发放家畜遗传材料《种畜禽生产经营许可证》公告等有关材料报农业部备案。"},{"i":22,"n":"第二十二条","txt":"农业部可以对取得家畜遗传材料《种畜禽生产经营许可证》的单位和个人实施监督检查和质量抽查，对不符合要求的，通报所在地省级人民政府畜牧兽医行政主管部门处理，必要时由农业部依法处理。"},{"i":23,"n":"第二十三条","txt":"县级以上人民政府畜牧兽医行政主管部门依法对家畜遗传材料生产活动实施监督检查和质量抽查，对违反本办法从事家畜遗传材料生产活动的，依照《中华人民共和国畜牧法》的有关规定处罚。"},{"i":24,"n":"第二十四条","txt":"不从事家畜遗传材料生产、只从事经营活动的单位和个人，应当依照省级人民政府的规定取得《种畜禽生产经营许可证》。"},{"i":25,"n":"第二十五条","txt":"本办法自2010年3月1日起施行。1998年11月5日农业部发布的《<种畜禽生产经营许可证>管理办法》（农业部令第4号）同时废止。"}],"zhiyeshouyihexiangcunshouyiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了维护执业兽医和乡村兽医合法权益，规范动物诊疗活动，加强执业兽医和乡村兽医队伍建设，保障动物健康和公共卫生安全，根据《中华人民共和国动物防疫法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称执业兽医，包括执业兽医师和执业助理兽医师。 本办法所称乡村兽医，是指尚未取得执业兽医资格，经备案在乡村从事动物诊疗活动的人员。"},{"i":3,"n":"第三条","txt":"农业农村部主管全国执业兽医和乡村兽医管理工作，加强信息化建设，建立完善执业兽医和乡村兽医信息管理系统。 农业农村部和省级人民政府农业农村主管部门制定实施执业兽医和乡村兽医的继续教育计划，提升执业兽医和乡村兽医素质和执业水平。 县级以上地方人民政府农业农村主管部门主管本行政区域内的执业兽医和乡村兽医管理工作，加强执业兽医和乡村兽医备案、执业活动、继续教育等监督管理。"},{"i":4,"n":"第四条","txt":"鼓励执业兽医和乡村兽医接受继续教育。执业兽医和乡村兽医继续教育工作可以委托相关机构或者组织具体承担。 执业兽医所在机构应当支持执业兽医参加继续教育。"},{"i":5,"n":"第五条","txt":"执业兽医、乡村兽医依法执业，其权益受法律保护。 兽医行业协会应当依照法律、法规、规章和章程，加强行业自律，及时反映行业诉求，为兽医人员提供信息咨询、宣传培训、权益保护、纠纷处理等方面的服务。"},{"i":6,"n":"第六条","txt":"对在动物防疫工作中做出突出贡献的执业兽医和乡村兽医，按照国家有关规定给予表彰和奖励。 对因参与动物防疫工作致病、致残、死亡的执业兽医和乡村兽医，按照国家有关规定给予补助或者抚恤。 县级人民政府农业农村主管部门和乡（镇）人民政府应当优先确定乡村兽医作为村级动物防疫员。"},{"i":7,"n":"第七条","txt":"国家实行执业兽医资格考试制度。 具备下列条件之一的，可以报名参加全国执业兽医资格考试： （一）具有大学专科以上学历的人员或全日制高校在校生，专业符合全国执业兽医资格考试委员会公布的报考专业目录； （二）2009年1月1日前已取得兽医师以上专业技术职称； （三）依法备案或登记，且从事动物诊疗活动十年以上的乡村兽医。"},{"i":8,"n":"第八条","txt":"执业兽医资格考试由农业农村部组织，全国统一大纲、统一命题、统一考试、统一评卷。"},{"i":9,"n":"第九条","txt":"执业兽医资格考试类别分为兽医全科类和水生动物类，包含基础、预防、临床和综合应用四门科目。"},{"i":10,"n":"第十条","txt":"农业农村部设立的全国执业兽医资格考试委员会负责审定考试科目、考试大纲，发布考试公告、确定考试试卷等,对考试工作进行监督、指导和确定合格标准。"},{"i":11,"n":"第十一条","txt":"通过执业兽医资格考试的人员，由省、自治区、直辖市人民政府农业农村主管部门根据考试合格标准颁发执业兽医师或者执业助理兽医师资格证书。"},{"i":12,"n":"第十二条","txt":"取得执业兽医资格证书并在动物诊疗机构从事动物诊疗活动的，应当向动物诊疗机构所在地备案机关备案。"},{"i":13,"n":"第十三条","txt":"具备下列条件之一的，可以备案为乡村兽医： （一）取得中等以上兽医、畜牧（畜牧兽医）、中兽医（民族兽医）、水产养殖等相关专业学历； （二）取得中级以上动物疫病防治员、水生物病害防治员职业技能鉴定证书或职业技能等级证书； （三）从事村级动物防疫员工作满五年。"},{"i":14,"n":"第十四条","txt":"执业兽医或者乡村兽医备案的，应当向备案机关提交下列材料： （一）备案信息表； （二）身份证明。 除前款规定的材料外，执业兽医备案还应当提交动物诊疗机构聘用证明，乡村兽医备案还应当提交学历证明、职业技能鉴定证书或职业技能等级证书等材料。"},{"i":15,"n":"第十五条","txt":"备案材料符合要求的，应当及时予以备案；不符合要求的，应当一次性告知备案人补正相关材料。 备案机关应当优化备案办理流程，逐步实现网上统一办理，提高备案效率。"},{"i":16,"n":"第十六条","txt":"执业兽医可以在同一县域内备案多家执业的动物诊疗机构；在不同县域从事动物诊疗活动的，应当分别向动物诊疗机构所在地备案机关备案。 执业的动物诊疗机构发生变化的，应当按规定及时更新备案信息。"},{"i":17,"n":"第十七条","txt":"患有人畜共患传染病的执业兽医和乡村兽医不得直接从事动物诊疗活动。"},{"i":18,"n":"第十八条","txt":"执业兽医应当在备案的动物诊疗机构执业，但动物诊疗机构间的会诊、支援、应邀出诊、急救等除外。 经备案专门从事水生动物疫病诊疗的执业兽医，不得从事其他动物疫病诊疗。 乡村兽医应当在备案机关所在县域的乡村从事动物诊疗活动，不得在城区从业。"},{"i":19,"n":"第十九条","txt":"执业兽医师可以从事动物疾病的预防、诊断、治疗和开具处方、填写诊断书、出具动物诊疗有关证明文件等活动。 执业助理兽医师可以从事动物健康检查、采样、配药、给药、针灸等活动，在执业兽医师指导下辅助开展手术、剖检活动，但不得开具处方、填写诊断书、出具动物诊疗有关证明文件。"},{"i":20,"n":"第二十条","txt":"执业兽医师应当规范填写处方笺、病历。未经亲自诊断、治疗，不得开具处方、填写诊断书、出具动物诊疗有关证明文件。 执业兽医师不得伪造诊断结果，出具虚假动物诊疗证明文件。"},{"i":21,"n":"第二十一条","txt":"参加动物诊疗教学实践的兽医相关专业学生和尚未取得执业兽医资格证书、在动物诊疗机构中参加工作实践的兽医相关专业毕业生，应当在执业兽医师监督、指导下协助参与动物诊疗活动。"},{"i":22,"n":"第二十二条","txt":"执业兽医和乡村兽医在执业活动中应当履行下列义务： （一）遵守法律、法规、规章和有关管理规定； （二）按照技术操作规范从事动物诊疗活动； （三）遵守职业道德，履行兽医职责； （四）爱护动物，宣传动物保健知识和动物福利。"},{"i":23,"n":"第二十三条","txt":"执业兽医和乡村兽医应当按照国家有关规定使用兽药和兽医器械，不得使用假劣兽药、农业农村部规定禁止使用的药品及其他化合物和不符合规定的兽医器械。 执业兽医和乡村兽医发现可能与兽药和兽医器械使用有关的严重不良反应的，应当立即向所在地人民政府农业农村主管部门报告。"},{"i":24,"n":"第二十四条","txt":"执业兽医和乡村兽医在动物诊疗活动中，应当按照规定处理使用过的兽医器械和诊疗废弃物。"},{"i":25,"n":"第二十五条","txt":"执业兽医和乡村兽医在动物诊疗活动中发现动物染疫或者疑似染疫的，应当按照国家规定立即向所在地人民政府农业农村主管部门或者动物疫病预防控制机构报告，并迅速采取隔离、消毒等控制措施，防止动物疫情扩散。 执业兽医和乡村兽医在动物诊疗活动中发现动物患有或者疑似患有国家规定应当扑杀的疫病时，不得擅自进行治疗。"},{"i":26,"n":"第二十六条","txt":"执业兽医和乡村兽医应当按照当地人民政府或者农业农村主管部门的要求，参加动物疫病预防、控制和动物疫情扑灭活动，执业兽医所在单位和乡村兽医不得阻碍、拒绝。 执业兽医和乡村兽医可以通过承接政府购买服务的方式开展动物防疫和疫病诊疗活动。"},{"i":27,"n":"第二十七条","txt":"执业兽医应当于每年三月底前，按照县级人民政府农业农村主管部门要求如实报告上年度兽医执业活动情况。"},{"i":28,"n":"第二十八条","txt":"县级以上地方人民政府农业农村主管部门应当建立健全日常监管制度，对辖区内执业兽医和乡村兽医执行法律、法规、规章的情况进行监督检查。"},{"i":29,"n":"第二十九条","txt":"违反本办法规定，执业兽医有下列行为之一的，依照《中华人民共和国动物防疫法》第一百零六条第一款的规定予以处罚： （一）在责令暂停动物诊疗活动期间从事动物诊疗活动的； （二）超出备案所在县域或者执业范围从事动物诊疗活动的； （三）执业助理兽医师直接开展手术，或者开具处方、填写诊断书、出具动物诊疗有关证明文件的。"},{"i":30,"n":"第三十条","txt":"违反本办法规定，执业兽医对患有或者疑似患有国家规定应当扑杀的疫病的动物进行治疗，造成或者可能造成动物疫病传播、流行的，依照《中华人民共和国动物防疫法》第一百零六条第二款的规定予以处罚。"},{"i":31,"n":"第三十一条","txt":"违反本办法规定，执业兽医未按县级人民政府农业农村主管部门要求如实形成兽医执业活动情况报告的，依照《中华人民共和国动物防疫法》第一百零八条的规定予以处罚。"},{"i":32,"n":"第三十二条","txt":"违反本办法规定，执业兽医在动物诊疗活动中有下列行为之一的，由县级以上地方人民政府农业农村主管部门责令限期改正，处一千元以上五千元以下罚款： （一）不使用病历，或者应当开具处方未开具处方的； （二）不规范填写处方笺、病历的； （三）未经亲自诊断、治疗，开具处方、填写诊断书、出具动物诊疗有关证明文件的； （四）伪造诊断结果，出具虚假动物诊疗证明文件的。"},{"i":33,"n":"第三十三条","txt":"违反本办法规定，乡村兽医不按照备案规定区域从事动物诊疗活动的，由县级以上地方人民政府农业农村主管部门责令限期改正，处一千元以上五千元以下罚款。"},{"i":34,"n":"第三十四条","txt":"动物饲养场、实验动物饲育单位、兽药生产企业、动物园等单位聘用的取得执业兽医资格证书的人员，可以凭聘用合同办理执业兽医备案，但不得对外开展动物诊疗活动。"},{"i":35,"n":"第三十五条","txt":"省、自治区、直辖市人民政府农业农村主管部门根据本地区实际，可以决定执业助理兽医师在乡村独立从事动物诊疗活动，并按执业兽医师进行执业活动管理。"},{"i":36,"n":"第三十六条","txt":"本办法所称备案机关，是指县（市辖区）级人民政府农业农村主管部门；市辖区未设立农业农村主管部门的，备案机关为上一级农业农村主管部门。"},{"i":37,"n":"第三十七条","txt":"本办法自2022年10月1日起施行。农业部2008年11月26日公布，2013年9月28日、2013年12月31日修订的《执业兽医管理办法》和2008年11月26日公布、2019年4月25日修订的《乡村兽医管理办法》同时废止。"}],"tuolajihelianheshougejidengjiguiding":[{"i":1,"n":"第一条","txt":"为了规范拖拉机和联合收割机登记，根据《中华人民共和国农业机械化促进法》、《中华人民共和国道路交通安全法》和《农业机械安全监督管理条例》、《中华人民共和国道路交通安全法实施条例》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称登记，是指依法对拖拉机和联合收割机进行的登记。包括注册登记、变更登记、转移登记、抵押登记和注销登记。 拖拉机包括轮式拖拉机、手扶拖拉机、履带拖拉机、轮式拖拉机运输机组、手扶拖拉机运输机组。 联合收割机包括轮式联合收割机、履带式联合收割机。"},{"i":3,"n":"第三条","txt":"县级人民政府农业机械化主管部门负责本行政区域内拖拉机和联合收割机的登记管理，其所属的农机安全监理机构（以下简称农机监理机构）承担具体工作。 县级以上人民政府农业机械化主管部门及其所属的农机监理机构负责拖拉机和联合收割机登记业务工作的指导、检查和监督。"},{"i":4,"n":"第四条","txt":"农机监理机构办理拖拉机、联合收割机登记业务，应当遵循公开、公正、便民、高效原则。 农机监理机构在办理业务时，对材料齐全并符合规定的，应当按期办结。对材料不全或者不符合规定的，应当一次告知申请人需要补正的全部内容。对不予受理的，应当书面告知不予受理的理由。"},{"i":5,"n":"第五条","txt":"农机监理机构应当在业务办理场所公示业务办理条件、依据、程序、期限、收费标准、需要提交的材料和申请表示范文本等内容，并在相关网站发布信息，便于群众查阅、下载和使用。"},{"i":6,"n":"第六条","txt":"农机监理机构应当使用计算机管理系统办理登记业务，完整、准确记录和存储登记内容、办理过程以及经办人员等信息，打印行驶证和登记证书。计算机管理系统的数据库标准由农业部制定。"},{"i":7,"n":"第七条","txt":"初次申领拖拉机、联合收割机号牌、行驶证的，应当在申请注册登记前，对拖拉机、联合收割机进行安全技术检验，取得安全技术检验合格证明。 依法通过农机推广鉴定的机型，其新机在出厂时经检验获得出厂合格证明的，出厂一年内免予安全技术检验，拖拉机运输机组除外。"},{"i":8,"n":"第八条","txt":"拖拉机、联合收割机所有人应当向居住地的农机监理机构申请注册登记，填写申请表，交验拖拉机、联合收割机，提交以下材料： （一）所有人身份证明； （二）拖拉机、联合收割机来历证明； （三）出厂合格证明或进口凭证； （四）拖拉机运输机组交通事故责任强制保险凭证； （五）安全技术检验合格证明（免检产品除外）。 农机监理机构应当自受理之日起2个工作日内，确认拖拉机、联合收割机的类型、品牌、型号名称、机身颜色、发动机号码、底盘号／机架号、挂车架号码，核对发动机号码和拖拉机、联合收割机底盘号／机架号、挂车架号码的拓印膜，审查提交的证明、凭证；对符合条件的，核发登记证书、号牌、行驶证和检验合格标志。登记证书由所有人自愿申领。"},{"i":9,"n":"第九条","txt":"办理注册登记，应当登记下列内容： （一）拖拉机、联合收割机号牌号码、登记证书编号； （二）所有人的姓名或者单位名称、身份证明名称与号码、住址、联系电话和邮政编码； （三）拖拉机、联合收割机的类型、生产企业名称、品牌、型号名称、发动机号码、底盘号／机架号、挂车架号码、生产日期、机身颜色； （四）拖拉机、联合收割机的有关技术数据； （五）拖拉机、联合收割机的获得方式； （六）拖拉机、联合收割机来历证明的名称、编号； （七）拖拉机运输机组交通事故责任强制保险的日期和保险公司的名称； （八）注册登记的日期； （九）法律、行政法规规定登记的其他事项。 拖拉机、联合收割机登记后，对其来历证明、出厂合格证明应当签注已登记标志，收存来历证明、出厂合格证明原件和身份证明复印件。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，不予办理注册登记： （一）所有人提交的证明、凭证无效； （二）来历证明被涂改，或者来历证明记载的所有人与身份证明不符； （三）所有人提交的证明、凭证与拖拉机、联合收割机不符； （四）拖拉机、联合收割机不符合国家安全技术强制标准； （五）拖拉机、联合收割机达到国家规定的强制报废标准； （六）属于被盗抢、扣押、查封的拖拉机和联合收割机； （七）其他不符合法律、行政法规规定的情形。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，所有人应当向登记地农机监理机构申请变更登记： （一）改变机身颜色、更换机身（底盘）或者挂车的； （二）更换发动机的； （三）因质量有问题，更换整机的； （四）所有人居住地在本行政区域内迁移、所有人姓名（单位名称）变更的。"},{"i":12,"n":"第十二条","txt":"申请变更登记的，应当填写申请表，提交下列材料； （一）所有人身份证明； （二）行驶证； （三）更换整机、发动机、机身（底盘）或挂车需要提供法定证明、凭证； （四）安全技术检验合格证明。 农机监理机构应当自受理之日起2个工作日内查验相关证明，准予变更的，收回原行驶证，重新核发行驶证。"},{"i":13,"n":"第十三条","txt":"拖拉机、联合收割机所有人居住地迁出农机监理机构管辖区域的，应当向登记地农机监理机构申请变更登记，提交行驶证和身份证明。 农机监理机构应当自受理之日起2个工作日内核发临时行驶号牌，收回原号牌、行驶证，将档案密封交所有人。 所有人应当于3个月内到迁入地农机监理机构申请转入，提交身份证明、登记证书和档案，交验拖拉机、联合收割机。 迁入地农机监理机构应当自受理之日起2个工作日内，查验拖拉机、联合收割机，收存档案，核发号牌、行驶证。"},{"i":14,"n":"第十四条","txt":"办理变更登记，应当分别登记下列内容： （一）变更后的机身颜色； （二）变更后的发动机号码； （三）变更后的底盘号／机架号、挂车架号码； （四）发动机、机身（底盘）或者挂车来历证明的名称、编号； （五）发动机、机身（底盘）或者挂车出厂合格证明或者进口凭证编号、生产日期、注册登记日期； （六）变更后的所有人姓名或者单位名称； （七）需要办理档案转出的，登记转入地农机监理机构的名称； （八）变更登记的日期。"},{"i":15,"n":"第十五条","txt":"拖拉机、联合收割机所有权发生转移的，应当向登记地的农机监理机构申请转移登记，填写申请表，交验拖拉机、联合收割机，提交以下材料： （一）所有人身份证明； （二）所有权转移的证明、凭证； （三）行驶证、登记证书。 农机监理机构应当自受理之日起2个工作日内办理转移手续。转移后的拖拉机、联合收割机所有人居住地在原登记地农机监理机构管辖区内的，收回原行驶证，核发新行驶证；转移后的拖拉机、联合收割机所有人居住地不在原登记地农机监理机构管辖区内的，按照本规定第十三条办理。"},{"i":16,"n":"第十六条","txt":"办理转移登记，应当登记下列内容： （一）转移后的拖拉机、联合收割机所有人的姓名或者单位名称、身份证明名称与号码、住址、联系电话和邮政编码； （二）拖拉机、联合收割机获得方式； （三）拖拉机、联合收割机来历证明的名称、编号； （四）转移登记的日期； （五）改变拖拉机、联合收割机号牌号码的，登记拖拉机、联合收割机号牌号码； （六）转移后的拖拉机、联合收割机所有人居住地不在原登记地农机监理机构管辖区内的，登记转入地农机监理机构的名称。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，不予办理转移登记： （一）有本规定第十条规定情形； （二）拖拉机、联合收割机与该机的档案记载的内容不一致； （三）在抵押期间； （四）拖拉机、联合收割机或者拖拉机、联合收割机档案被人民法院、人民检察院、行政执法部门依法查封、扣押； （五）拖拉机、联合收割机涉及未处理完毕的道路交通违法行为、农机安全违法行为或者道路交通事故、农机事故。"},{"i":18,"n":"第十八条","txt":"被司法机关和行政执法部门依法没收并拍卖，或者被仲裁机构依法仲裁裁决，或者被人民法院调解、裁定、判决拖拉机、联合收割机所有权转移时，原所有人未向转移后的所有人提供行驶证的，转移后的所有人在办理转移登记时，应当提交司法机关出具的《协助执行通知书》或者行政执法部门出具的未取得行驶证的证明。农机监理机构应当公告原行驶证作废，并在办理所有权转移登记的同时，发放拖拉机、联合收割机行驶证。"},{"i":19,"n":"第十九条","txt":"申请抵押登记的，由拖拉机、联合收割机所有人（抵押人）和抵押权人共同申请，填写申请表，提交下列证明、凭证： （一）抵押人和抵押权人身份证明； （二）拖拉机、联合收割机登记证书； （三）抵押人和抵押权人依法订立的主合同和抵押合同。 农机监理机构应当自受理之日起1日内，在拖拉机、联合收割机登记证书上记载抵押登记内容。"},{"i":20,"n":"第二十条","txt":"农机监理机构办理抵押登记，应当登记下列内容： （一）抵押权人的姓名或者单位名称、身份证明名称与号码、住址、联系电话和邮政编码； （二）抵押担保债权的数额； （三）主合同和抵押合同号码； （四）抵押登记的日期。"},{"i":21,"n":"第二十一条","txt":"申请注销抵押的，应当由抵押人与抵押权人共同申请，填写申请表，提交以下证明、凭证： （一）抵押人和抵押权人身份证明； （二）拖拉机、联合收割机登记证书。 农机监理机构应当自受理之日起1日内，在农机监理信息系统注销抵押内容和注销抵押的日期。"},{"i":22,"n":"第二十二条","txt":"抵押登记内容和注销抵押日期应当允许公众查询。"},{"i":23,"n":"第二十三条","txt":"有下列情形之一的，应当向登记地的农机监理机构申请注销登记，填写申请表，提交身份证明，并交回号牌、行驶证、登记证书。 （一）报废的； （二）灭失的； （三）所有人因其他原因申请注销的。 农机监理机构应当自受理之日起1日内办理注销登记，收回号牌、行驶证和登记证书。无法收回的，由农机监理机构公告作废。"},{"i":24,"n":"第二十四条","txt":"拖拉机、联合收割机号牌、行驶证、登记证书灭失、丢失或者损毁申请补领、换领的，所有人应当向登记地农机监理机构提出申请，提交身份证明和相关证明材料。 经审查，属于补发、换发号牌的，农机监理机构应当自受理之日起15日内办理；属于补发、换发行驶证、登记证书的，自受理之日起1日内办理。 办理补发、换发号牌期间，应当给所有人核发临时行驶号牌。 补发、换发号牌、行驶证、登记证书后，应当收回未灭失、丢失或者损坏的号牌、行驶证、登记证书。"},{"i":25,"n":"第二十五条","txt":"未注册登记的拖拉机、联合收割机需要驶出本行政区域的，所有人应当申请临时行驶号牌，提交以下证明、凭证： （一）所有人身份证明； （二）拖拉机、联合收割机来历证明； （三）出厂合格证明或进口凭证； （四）拖拉机运输机组须提交交通事故责任强制保险凭证。 农机监理机构应当自受理之日起1日内，核发临时行驶号牌。临时行驶号牌有效期最长为3个月。"},{"i":26,"n":"第二十六条","txt":"拖拉机、联合收割机所有人发现登记内容有错误的，应当及时到农机监理机构申请更正。农机监理机构应当自受理之日起2个工作日内予以确认并更正。"},{"i":27,"n":"第二十七条","txt":"已注册登记的拖拉机、联合收割机被盗抢，所有人应当在向公安机关报案的同时，向登记地农机监理机构申请封存档案。农机监理机构应当受理申请，在计算机管理系统内记录被盗抢信息，封存档案，停止办理该拖拉机、联合收割机的各项登记。被盗抢拖拉机、联合收割机发还后，所有人应当向登记地农机监理机构申请解除封存，农机监理机构应当受理申请，恢复办理各项登记。 在被盗抢期间，发动机号码、底盘号／机架号、挂车架号码或者机身颜色被改变的，农机监理机构应当凭有关技术鉴定证明办理变更。"},{"i":28,"n":"第二十八条","txt":"登记的拖拉机、联合收割机应当每年进行1次安全检验。"},{"i":29,"n":"第二十九条","txt":"拖拉机、联合收割机所有人可以委托代理人代理申请各项登记和相关业务，但申请补发登记证书的除外。代理人办理相关业务时，应当提交代理人身份证明、经申请人签字的委托书。"},{"i":30,"n":"第三十条","txt":"申请人以隐瞒、欺骗等不正当手段办理登记的，应当撤销登记，并收回相关证件和号牌。 农机安全监理人员违反规定为拖拉机、联合收割机办理登记的，按照国家有关规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"行驶证的式样、规格按照农业行业标准《中华人民共和国拖拉机和联合收割机行驶证》执行。拖拉机、联合收割机号牌、临时行驶号牌、登记证书、检验合格标志和相关登记表格的式样、规格，由农业部制定。"},{"i":32,"n":"第三十二条","txt":"本规定下列用语的含义： （一）拖拉机、联合收割机所有人是指拥有拖拉机、联合收割机所有权的个人或者单位。 （二）身份证明是指： 1．机关、事业单位、企业和社会团体的身份证明，是指标注有“统一社会信用代码”的注册登记证（照）。上述单位已注销、撤销或者破产的，已注销的企业单位的身份证明，是工商行政管理部门出具的注销证明；已撤销的机关、事业单位的身份证明，是上级主管机关出具的有关证明；已破产的企业单位的身份证明，是依法成立的财产清算机构出具的有关证明； 2．居民的身份证明，是指《居民身份证》或者《居民户口簿》。在户籍所在地以外居住的，其身份证明还包括公安机关核发的居住证明。 （三）住址是指： 1．单位的住址为其主要办事机构所在地的地址； 2．个人的住址为其身份证明记载的地址。在户籍所在地以外居住的是公安机关核发的居住证明记载的地址。 （四）获得方式是指：购买、继承、赠予、中奖、协议抵偿债务、资"},{"i":33,"n":"第三十三条","txt":"本规定自2018年6月1日起施行。2004年9月21日公布、2010年11月26日修订的《拖拉机登记规定》和2006年11月2日公布、2010年11月26日修订的《联合收割机及驾驶人安全监理规定》同时废止。"}],"tuolajihelianheshougejijiashizhengguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范拖拉机和联合收割机驾驶证（以下简称驾驶证）的申领和使用，根据《中华人民共和国农业机械化促进法》、《中华人民共和国道路交通安全法》和《农业机械安全监督管理条例》、《中华人民共和国道路交通安全法实施条例》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称驾驶证是指驾驶拖拉机、联合收割机所需持有的证件。"},{"i":3,"n":"第三条","txt":"县级人民政府农业机械化主管部门负责本行政区域内拖拉机和联合收割机驾驶证的管理，其所属的农机安全监理机构（以下简称农机监理机构）承担驾驶证申请受理、考试、发证等具体工作。 县级以上人民政府农业机械化主管部门及其所属的农机监理机构负责驾驶证业务工作的指导、检查和监督。"},{"i":4,"n":"第四条","txt":"农机监理机构办理驾驶证业务，应当遵循公开、公正、便民、高效原则。 农机监理机构在办理驾驶证业务时，对材料齐全并符合规定的，应当按期办结。对材料不全或者不符合规定的，应当一次告知申请人需要补正的全部内容。对不予受理的，应当书面告知不予受理的理由。"},{"i":5,"n":"第五条","txt":"农机监理机构应当在办理业务的场所公示驾驶证申领的条件、依据、程序、期限、收费标准、需要提交的全部资料的目录和申请表示范文本等内容，并在相关网站发布信息，便于群众查阅有关规定，下载、使用有关表格。"},{"i":6,"n":"第六条","txt":"农机监理机构应当使用计算机管理系统办理业务，完整、准确记录和存储申请受理、科目考试、驾驶证核发等全过程以及经办人员等信息。计算机管理系统的数据库标准由农业部制定。"},{"i":7,"n":"第七条","txt":"驾驶拖拉机、联合收割机，应当申请考取驾驶证。"},{"i":8,"n":"第八条","txt":"拖拉机、联合收割机驾驶人员准予驾驶的机型分为： （一）轮式拖拉机，代号为G1； （二）手扶拖拉机，代号为K1； （三）履带拖拉机，代号为L； （四）轮式拖拉机运输机组，代号为G2（准予驾驶轮式拖拉机）； （五）手扶拖拉机运输机组，代号为K2（准予驾驶手扶拖拉机）； （六）轮式联合收割机，代号为R； （七）履带式联合收割机，代号为S。"},{"i":9,"n":"第九条","txt":"申请驾驶证，应当符合下列条件： （一）年龄：18周岁以上，70周岁以下； （二）身高：不低于150厘米； （三）视力：两眼裸视力或者矫正视力达到对数视力表4.9以上； （四）辨色力：无红绿色盲； （五）听力：两耳分别距音叉50厘米能辨别声源方向； （六）上肢：双手拇指健全，每只手其他手指必须有3指健全，肢体和手指运动功能正常； （七）下肢：运动功能正常，下肢不等长度不得大于5厘米； （八）躯干、颈部：无运动功能障碍。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，不得申领驾驶证： （一）有器质性心脏病、癫痫、美尼尔氏症、眩晕症、癔病、震颤麻痹、精神病、痴呆以及影响肢体活动的神经系统疾病等妨碍安全驾驶疾病的； （二）3年内有吸食、注射毒品行为或者解除强制隔离戒毒措施未满3年，或者长期服用依赖性精神药品成瘾尚未戒除的； （三）吊销驾驶证未满2年的； （四）驾驶许可依法被撤销未满3年的； （五）醉酒驾驶依法被吊销驾驶证未满5年的； （六）饮酒后或醉酒驾驶造成重大事故被吊销驾驶证的； （七）造成事故后逃逸被吊销驾驶证的； （八）法律、行政法规规定的其他情形。"},{"i":11,"n":"第十一条","txt":"申领驾驶证，按照下列规定向农机监理机构提出申请： （一）在户籍所在地居住的，应当在户籍所在地提出申请； （二）在户籍所在地以外居住的，可以在居住地提出申请； （三）境外人员，应当在居住地提出申请。"},{"i":12,"n":"第十二条","txt":"初次申领驾驶证的，应当填写申请表，提交以下材料： （一）申请人身份证明； （二）身体条件证明。"},{"i":13,"n":"第十三条","txt":"申请增加准驾机型的，应当向驾驶证核发地或居住地农机监理机构提出申请，填写申请表，提交驾驶证和本规定第十二条规定的材料。"},{"i":14,"n":"第十四条","txt":"农机监理机构办理驾驶证业务，应当依法审核申请人提交的资料，对符合条件的，按照规定程序和期限办理驾驶证。 申领驾驶证的，应当向农机监理机构提交规定的有关资料，如实申告规定事项。"},{"i":15,"n":"第十五条","txt":"符合驾驶证申请条件的，农机监理机构应当受理并在20日内安排考试。 农机监理机构应当提供网络或电话等预约考试的方式。"},{"i":16,"n":"第十六条","txt":"驾驶考试科目分为： （一）科目一：理论知识考试； （二）科目二：场地驾驶技能考试； （三）科目三：田间作业技能考试； （四）科目四：道路驾驶技能考试。 考试内容与合格标准由农业部制定。"},{"i":17,"n":"第十七条","txt":"申请人应当在科目一考试合格后2年内完成科目二、科目三、科目四考试。未在2年内完成考试的，已考试合格的科目成绩作废。"},{"i":18,"n":"第十八条","txt":"每个科目考试1次，考试不合格的，可以当场补考1次。补考仍不合格的，申请人可以预约后再次补考，每次预约考试次数不超过2次。"},{"i":19,"n":"第十九条","txt":"各科目考试结果应当场公布，并出示成绩单。成绩单由考试员和申请人共同签名。考试不合格的，应当说明不合格原因。"},{"i":20,"n":"第二十条","txt":"申请人在考试过程中有舞弊行为的，取消本次考试资格，已经通过考试的其他科目成绩无效。"},{"i":21,"n":"第二十一条","txt":"申请人全部科目考试合格后，应当在2个工作日内核发驾驶证。准予增加准驾机型的，应当收回原驾驶证。"},{"i":22,"n":"第二十二条","txt":"从事考试工作的人员，应当持有省级农机监理机构核发的考试员证件，认真履行考试职责，严格遵守考试工作纪律。"},{"i":23,"n":"第二十三条","txt":"驾驶证记载和签注以下内容： （一）驾驶人信息：姓名、性别、出生日期、国籍、住址、身份证明号码（驾驶证号码）、照片； （二）农机监理机构签注内容：初次领证日期、准驾机型代号、有效期限、核发机关印章、档案编号、副页签注期满换证时间。"},{"i":24,"n":"第二十四条","txt":"驾驶证有效期为6年。驾驶人驾驶拖拉机、联合收割机时，应当随身携带。 驾驶人应当于驾驶证有效期满前3个月内，向驾驶证核发地或居住地农机监理机构申请换证。申请换证时应当填写申请表，提交以下材料： （一）驾驶人身份证明； （二）驾驶证； （三）身体条件证明。"},{"i":25,"n":"第二十五条","txt":"驾驶人户籍迁出原农机监理机构管辖区的，应当向迁入地农机监理机构申请换证；驾驶人在驾驶证核发地农机监理机构管辖区以外居住的，可以向居住地农机监理机构申请换证。申请换证时应当填写申请表，提交驾驶人身份证明和驾驶证。"},{"i":26,"n":"第二十六条","txt":"驾驶证记载的驾驶人信息发生变化的或驾驶证损毁无法辨认的，驾驶人应当及时到驾驶证核发地或居住地农机监理机构申请换证。申请换证时应当填写申请表，提交驾驶人身份证明和驾驶证。"},{"i":27,"n":"第二十七条","txt":"符合本规定第二十四条、第二十五条、第二十六条换证条件的，农机监理机构应当在2个工作日内换发驾驶证，并收回原驾驶证。"},{"i":28,"n":"第二十八条","txt":"驾驶证遗失的，驾驶人应当向驾驶证核发地或居住地农机监理机构申请补发。申请时应当填写申请表，提交驾驶人身份证明。 符合规定的，农机监理机构应当在2个工作日内补发驾驶证，原驾驶证作废。 驾驶证被依法扣押、扣留或者暂扣期间，驾驶人不得申请补证。"},{"i":29,"n":"第二十九条","txt":"拖拉机运输机组驾驶人在一个记分周期内累计达到12分的，农机监理机构在接到公安部门通报后，应当通知驾驶人在15日内接受道路交通安全法律法规和相关知识的教育。驾驶人接受教育后，农机监理机构应当在20日内对其进行科目一考试。 驾驶人在一个记分周期内两次以上达到12分的，农机监理机构还应当在科目一考试合格后的10日内对其进行科目四考试。"},{"i":30,"n":"第三十条","txt":"驾驶人具有下列情形之一的，其驾驶证失效，应当注销： （一）申请注销的； （二）身体条件或其他原因不适合继续驾驶的； （三）丧失民事行为能力，监护人提出注销申请的； （四）死亡的； （五）超过驾驶证有效期1年以上未换证的； （六）年龄在70周岁以上的； （七）驾驶证依法被吊销或者驾驶许可依法被撤销的。 有前款情形之一，未收回驾驶证的，应当公告驾驶证作废。 有第一款第（五）项情形，被注销驾驶证未超过2年的，驾驶人参加科目一考试合格后，可以申请恢复驾驶资格，办理期满换证。"},{"i":31,"n":"第三十一条","txt":"驾驶人可以委托代理人办理换证、补证、注销业务。代理人办理相关业务时，除规定材料外，还应当提交代理人身份证明、经申请人签字的委托书。"},{"i":32,"n":"第三十二条","txt":"驾驶证的式样、规格与中华人民共和国公共安全行业标准《中华人民共和国机动车驾驶证件》一致，按照农业行业标准《中华人民共和国拖拉机和联合收割机驾驶证》执行。相关表格式样由农业部制定。"},{"i":33,"n":"第三十三条","txt":"申请人以隐瞒、欺骗等不正当手段取得驾驶证的，应当撤销驾驶许可，并收回驾驶证。 农机安全监理人员违反规定办理驾驶证申领和使用业务的，按照国家有关规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"本规定下列用语的含义： （一）身份证明是指：《居民身份证》或者《临时居民身份证》。在户籍地以外居住的，身份证明还包括公安部门核发的居住证明。 住址是指：申请人提交的身份证明上记载的住址。 现役军人、港澳台居民、华侨、外国人等的身份证明和住址，参照公安部门有关规定执行。 （二）身体条件证明是指：乡镇或社区以上医疗机构出具的包含本规定第九条指定项目的有关身体条件证明。身体条件证明自出具之日起6个月内有效。"},{"i":35,"n":"第三十五条","txt":"本规定自2018年6月1日起施行。2004年9月21日公布、2010年11月26日修订的《拖拉机驾驶证申领和使用规定》和2006年11月2日公布、2010年11月26日修订的《联合收割机及驾驶人安全监理规定》同时废止。"}],"tuolajijiashipeixunguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范拖拉机驾驶员培训行业管理，确保拖拉机驾驶培训质量，保障人民生命财产安全，根据《中华人民共和国道路交通安全法》有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"农业部负责全国拖拉机驾驶培训管理工作。 县级以上地方人民政府农机主管部门负责本行政区域内拖拉机驾驶培训管理工作。"},{"i":3,"n":"第三条","txt":"拖拉机培训实行社会化。农机主管部门及其安全监理机构不得举办或者参与举办拖拉机驾驶培训学校、驾驶培训班。 国家按照统筹规划、合理布局、公平竞争、保证质量的原则，对拖拉机驾驶培训机构实行资格管理。"},{"i":4,"n":"第四条","txt":"拖拉机驾驶培训机构应当具备与其培训活动相适应的场地、设备、人员、规章制度等条件，取得省级人民政府农机主管部门颁发的《中华人民共和国拖拉机驾驶培训许可证》，方可从事相关培训活动。"},{"i":5,"n":"第五条","txt":"教学场所 （一）教室人均使用面积不少于1.2平方米，总面积不得低于120平方米，且采光、通风、照明和消防等条件符合有关标准; （二）有单独的办公用房; （三）有固定的教练场地，面积不得少于1500平方米。"},{"i":6,"n":"第六条","txt":"教学设备 （一）有5台以上检验合格的教练车辆，并配备相应的农机具，配套比例不低于1：2; （二）有常用机型的教学挂图、示教板和主要零部件实物; （三）有必要的电教设备。"},{"i":7,"n":"第七条","txt":"教学人员 （一）教学负责人应当具有本专业大专以上学历或中级以上技术职称，并从事拖拉机驾驶培训工作三年以上; （二）理论教员应当具有农机及相关专业中专以上学历，经省级人民政府农机主管部门考核合格; （三）教练员应当持有拖拉机驾驶中级以上技术等级证书和相应机型5年以上安全驾龄，经省级人民政府农机主管部门考核合格。 拖拉机驾驶培训机构的教学人员不得少于5人。"},{"i":8,"n":"第八条","txt":"组织管理制度 （一）有完善的教学制度，包括学员学籍档案管理制度、教员管理制度、教学设备及车辆管理制度。 （二）有健全的财务制度，配备专职财务人员。 （三）有科学的安全管理制度。"},{"i":9,"n":"第九条","txt":"申请《中华人民共和国拖拉机驾驶培训许可证》的，应当向省级人民政府农机主管部门提交《拖拉机驾驶培训学校（班）申请表》，并附具以下材料： （一）教学场所说明材料及其平面图; （二）教学设备清单; （三）组织管理制度; （四）生源预测情况。"},{"i":10,"n":"第十条","txt":"申请人提交的材料齐全，内容符合要求的，省级人民政府农机主管部门应当受理，并出具书面凭证。不予受理的，应当书面通知申请人，并告知理由。"},{"i":11,"n":"第十一条","txt":"受理申请后，省级人民政府农机主管部门应当在10日内完成书面审查。书面审查合格的，应当指派2名以上专家进行现场评审。"},{"i":12,"n":"第十二条","txt":"现场评审合格的，省级人民政府农机主管部门应当在10日内做出准予许可的决定。 书面审查或现场评审不合格的，省级人民政府农机主管部门应当书面通知申请人，并说明理由。"},{"i":13,"n":"第十三条","txt":"拖拉机驾驶培训机构变更名称、法定代表人或者教学场所的，应当向省级人民政府农机主管部门申请变更登记。"},{"i":14,"n":"第十四条","txt":"拖拉机驾驶培训包括： （一）初学驾驶培训; （二）增驾车型培训; （三）与驾驶相关的其他培训。 拖拉机驾驶培训方式分为全日制和学时制，由学员选择。"},{"i":15,"n":"第十五条","txt":"拖拉机驾驶培训机构应当严格执行农业部颁发的教学大纲，按照许可的范围和规模培训，保证培训质量。 拖拉机驾驶培训机构的财务应当独立。"},{"i":16,"n":"第十六条","txt":"拖拉机驾驶培训机构应当聘用经省级人民政府农机主管部门考核合格的教学人员。"},{"i":17,"n":"第十七条","txt":"申请参加拖拉机驾驶员培训的人员应当符合拖拉机驾驶证管理的有关规定，填写《中华人民共和国拖拉机驾驶员培训申请表》，交验身份证件。"},{"i":18,"n":"第十八条","txt":"完成规定课程并考试合格的学员，培训机构向学员提供素质评价、培训课时、教练员签名等记录。培训记录保存期不得少于4年。"},{"i":19,"n":"第十九条","txt":"教练车应当按拖拉机登记有关规定取得教练车牌证。"},{"i":20,"n":"第二十条","txt":"拖拉机驾驶培训机构应当于每年12月10日前，填写《拖拉机驾驶培训机构情况表》，报省级人民政府农机主管部门备案。"},{"i":21,"n":"第二十一条","txt":"县级以上地方人民政府农机主管部门应当对拖拉机驾驶培训机构进行监督检查，发现违反本办法行为的，应当依照职权调查处理。需由省级人民政府农机主管部门处理的，应当及时报请决定。"},{"i":22,"n":"第二十二条","txt":"拖拉机驾驶培训机构有下列情形之一的，由省级人民政府农机主管部门予以注销，并收回《中华人民共和国拖拉机驾驶培训许可证》： （一）办学条件发生重大变化，不符合本办法规定，在省级人民政府农机主管部门规定的整改期限内仍未达到要求的; （二）歇业一年以上的; （三）申请终止的; （四）连续两年未按时报送《拖拉机驾驶培训机构情况表》，限期整改仍拒不报送的; （五）其他应当注销的情形。"},{"i":23,"n":"第二十三条","txt":"省级人民政府农机主管部门应当及时公告批准、变更和注销的驾驶培训机构。"},{"i":24,"n":"第二十四条","txt":"对违反本规定的单位和个人，由县级以上地方人民政府农机主管部门按以下规定处罚： （一）未取得培训许可擅自从事拖拉机驾驶培训业务的，责令停办，有违法所得的，处违法所得三倍以下罚款，但最高不超过三万元;无违法所得的，处一万元以下罚款; （二）未按统一的教学计划、教学大纲和规定教材进行培训的，责令改正，处二千元以下罚款; （三）聘用未经省级人民政府农机主管部门考核合格的人员从事拖拉机驾驶员培训教学工作的，责令改正，处五千元以下罚款。"},{"i":25,"n":"第二十五条","txt":"农机主管部门工作人员在拖拉机驾驶培训管理工作中，以权谋私，违法乱纪的，依法给予行政处分。"},{"i":26,"n":"第二十六条","txt":"拖拉机驾驶培训机构教员考核办法由省级人民政府农机主管部门制定。"},{"i":27,"n":"第二十七条","txt":"现有拖拉机驾驶培训机构应当在本办法施行之日起一年内取得《中华人民共和国拖拉机驾驶培训许可证》。"},{"i":28,"n":"第二十八条","txt":"本规定自2004年9月1日起施行。"}],"xinshouyaoyanzhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了保证兽药的安全、有效和质量，规范兽药研制活动，根据《兽药管理条例》和《病原微生物实验室生物安全管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事新兽药临床前研究、临床试验和监督管理，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"农业部负责全国新兽药研制管理工作，对研制新兽药使用一类病原微生物（含国内尚未发现的新病原微生物）、属于生物制品的新兽药临床试验进行审批。 省级人民政府兽医行政管理部门负责对其他新兽药临床试验审批。 县级以上地方人民政府兽医行政管理部门负责本辖区新兽药研制活动的监督管理工作。"},{"i":4,"n":"第四条","txt":"新兽药临床前研究包括药学、药理学和毒理学研究，具体研究项目如下： 生物制品（包括疫苗、血清制品、诊断制品、微生态制品等）：菌毒种、细胞株、生物组织等起始材料的系统鉴定、保存条件、遗传稳定性、实验室安全和效力试验及免疫学研究等； 其它兽药（化学药品、抗生素、消毒剂、生化药品、放射性药品、外用杀虫剂）：生产工艺、结构确证、理化性质及纯度，剂型选择、处方筛选，检验方法、质量指标，稳定性，药理学、毒理学等； 中药制剂（中药材、中成药）：除具备其它兽药的研究项目外，还应当包括原药材的来源、加工及炮制等。"},{"i":5,"n":"第五条","txt":"研制新兽药，应当进行安全性评价。新兽药的安全性评价系指在临床前研究阶段，通过毒理学研究等对一类新化学药品和抗生素对靶动物和人的健康影响进行风险评估的过程，包括急性毒性、亚慢性毒性、致突变、生殖毒性（含致畸）、慢性毒性（含致癌）试验以及用于食用动物时日允许摄入量（ADI）和最高残留限量（MRL）的确定。 承担新兽药安全性评价的单位应当符合《兽药非临床研究质量管理规范》的要求,执行《兽药非临床研究质量管理规范》,并参照农业部发布的有关技术指导原则进行试验。采用指导原则以外的其他方法和技术进行试验的,应当提交能证明其科学性的资料。"},{"i":6,"n":"第六条","txt":"研制新兽药需要使用一类病原微生物的，应当按照《病原微生物实验室生物安全管理条例》和《高致病性动物病原微生物实验室生物安全管理审批办法》等有关规定，在实验室阶段前取得实验活动批准文件，并在取得《高致病性动物病原微生物实验室资格证书》的实验室进行试验。 申请使用一类病原微生物时，除提交《高致病性动物病原微生物实验室生物安全管理审批办法》要求的申请资料外，还应当提交研制单位基本情况、研究目的和方案、生物安全防范措施等书面资料。必要时，农业部指定参考试验室对病原微生物菌（毒）种进行风险评估和适用性评价。"},{"i":7,"n":"第七条","txt":"临床前药理学与毒理学研究所用化学药品、抗生素，应当经过结构确证确认为所需要的化合物，并经质量检验符合拟定质量标准。"},{"i":8,"n":"第八条","txt":"申请人进行临床试验，应当在试验前提出申请，并提交下列资料： （一）《新兽药临床试验申请表》一份； （二）申请报告一份，内容包括研制单位基本情况；新兽药名称、来源和特性； （三）属于其他新兽药临床试验,还应当提供符合《兽药临床试验质量管理规范》要求的兽药安全评价实验室出具的安全性评价试验报告原件一份,或者提供国内外相关药理学和毒理学文献资料; （四）委托试验合同书正本一份； （五）本办法第四条规定的有关资料一份; （六）试制产品生产工艺、质量标准(草案)、试制研究总结报告及检验报告。 属于生物制品的新兽药临床试验，还应当提供生物安全防范基本条件、菌（毒、虫）种名称、来源和特性方面的资料。 属于其他新兽药临床试验，还应当提供符合《兽药临床试验质量管理规范》要求的兽药安全评价实验室出具的安全性评价试验报告原件一份，或者提供国内外相关药理学和毒理学文献资料。"},{"i":9,"n":"第九条","txt":"属于生物制品的新兽药临床试验，应当向农业部提出申请；其他新兽药临床试验，应当向所在地省级人民政府兽医行政管理部门提出申请。 农业部或者省级人民政府兽医行政管理部门收到新兽药临床试验申请后，应当对临床前研究结果的真实性和完整性，以及临床试验方案进行审查。必要时，可以派至少2人对申请人临床前研究阶段的原始记录、试验条件、生产工艺以及试制情况进行现场核查，并形成书面核查报告。"},{"i":10,"n":"第十条","txt":"农业部或者省级人民政府兽医行政管理部门应当自受理申请之日起60个工作日内做出是否批准的决定，确定试验区域和试验期限，并书面通知申请人。省级人民政府兽医行政管理部门做出批准决定后，应当及时报农业部备案。"},{"i":11,"n":"第十一条","txt":"临床试验批准后应当在2年内实施完毕。逾期未完成的，可以延期一年，但应当经原批准机关批准。 临床试验批准后变更申请人的，应当重新申请。"},{"i":12,"n":"第十二条","txt":"兽药临床试验应当执行《兽药临床试验质量管理规范》。"},{"i":13,"n":"第十三条","txt":"兽药临床试验应当参照农业部发布的兽药临床试验技术指导原则进行。采用指导原则以外的其他方法和技术进行试验的，应当提交能证明其科学性的资料。"},{"i":14,"n":"第十四条","txt":"临床试验用兽药应当在取得《兽药GMP证书》的企业制备，制备过程应当执行《兽药生产质量管理规范》。 根据需要，农业部或者省级人民政府兽医行政管理部门可以对制备现场进行考察。"},{"i":15,"n":"第十五条","txt":"申请人对临床试验用兽药和对照用兽药的质量负责。临床试验用兽药和对照用兽药应当经中国兽医药品监察所或者农业部认定的其他兽药检验机构进行检验，检验合格的方可用于试验。 临床试验用兽药标签应当注明批准机关的批准文件号，兽药名称、含量、规格、试制日期、有效期、试制批号、试制企业名称等，并注明“供临床试验用”字样。"},{"i":16,"n":"第十六条","txt":"临床试验用兽药仅供临床试验使用，不得销售，不得在未批准区域使用，不得超过批准期限使用。"},{"i":17,"n":"第十七条","txt":"临床试验需要使用放射元素标记药物的，试验单位应当有严密的防辐射措施，使用放射元素标记药物的动物处理应当符合环保要求。 因试验死亡的临床试验用食用动物及其产品不得作为动物性食品供人消费,应当作无害化处理;临床试验用食用动物及其产品供人消费的,应当提供符合《兽药非临床研究质量管理规范》和《兽药临床试验质量管理规范》要求的兽药安全性评价实验室出具的对人安全并超过休药期的证明。"},{"i":18,"n":"第十八条","txt":"临床试验应当根据批准的临床试验方案进行。如需变更批准内容的，申请人应向原批准机关报告变更后的试验方案，并说明依据和理由。"},{"i":19,"n":"第十九条","txt":"临床试验的受试动物数量应当根据临床试验的目的，符合农业部规定的最低临床试验病例数要求或相关统计学的要求。"},{"i":20,"n":"第二十条","txt":"因新兽药质量或其它原因导致临床试验过程中试验动物发生重大动物疫病的，试验单位和申请人应当立即停止试验，并按照国家有关动物疫情处理规定处理。"},{"i":21,"n":"第二十一条","txt":"承担临床试验的单位和试验者应当密切注意临床试验用兽药不良反应事件的发生，并及时记录在案。 临床试验过程中发生严重不良反应事件的，试验者应当在24小时内报告所在地省级人民政府兽医行政管理部门和申请人，并报农业部。"},{"i":22,"n":"第二十二条","txt":"临床试验期间发生下列情形之一的，原批准机关可以责令申请人修改试验方案、暂停或终止试验： （一）未按照规定时限报告严重不良反应事件的； （二）已有证据证明试验用兽药无效的； （三）试验用兽药出现质量问题的； （四）试验中出现大范围、非预期的不良反应或严重不良反应事件的； （五）试验中弄虚作假的； （六）违反《兽药临床试验质量管理规范》其他情形的。"},{"i":23,"n":"第二十三条","txt":"对批准机关做出责令修改试验方案、暂停或终止试验的决定有异议的，申请人可以在5个工作日内向原批准机关提出书面意见并说明理由。原批准机关应当在10个工作日内做出最后决定，并书面通知申请人。 临床试验完成后，申请人应当向原批准机关提交批准的临床试验方案、试验结果及统计分析报告，并附原始记录复印件。"},{"i":24,"n":"第二十四条","txt":"违反本办法第十五条第一款规定，临床试验用兽药和对照用兽药未经检验，或者检验不合格用于试验的，试验结果不予认可。"},{"i":25,"n":"第二十五条","txt":"违反本办法第十七条第二款规定，依照《兽药管理条例》第六十三条的规定予以处罚。"},{"i":26,"n":"第二十六条","txt":"申请人申请新兽药临床试验时，提供虚假资料和样品的，批准机关不予受理或者对申报的新兽药临床试验不予批准，并对申请人给予警告，一年内不受理该申请人提出的该新兽药临床试验申请；已批准进行临床试验的，撤销该新兽药临床试验批准文件，终止试验，并处5万元以上10万元以下罚款，三年内不受理该申请人提出的该新兽药临床试验申请。 农业部对提供虚假资料和样品的申请人建立不良行为记录，并予以公布。"},{"i":27,"n":"第二十七条","txt":"兽药安全性评价单位、临床试验单位未按照《兽药非临床研究质量管理规范》或《兽药临床试验质量管理规范》规定实施兽药研究试验的，依照《兽药管理条例》第五十九条的规定予以处罚。 农业部对提供虚假试验结果和对试验结果弄虚作假的试验单位和责任人，建立不良行为记录，予以公布，并撤销相应试验的资格。"},{"i":28,"n":"第二十八条","txt":"违反本办法的其他行为，依照《兽药管理条例》和其他行政法规予以处罚。"},{"i":29,"n":"第二十九条","txt":"境外企业不得在中国境内进行新兽药研制所需的临床试验和其他动物试验。 根据进口兽药注册审评的要求，需要进行临床试验的，由农业部指定的单位承担，并将临床试验方案和与受委托单位签订的试验合同报农业部备案。"},{"i":30,"n":"第三十条","txt":"本办法自2005年11月1日起施行。"}],"xinsiliaohexinsiliaotianjiajiguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强新饲料、新饲料添加剂管理，保障养殖动物产品质量安全，根据《饲料和饲料添加剂管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称新饲料，是指我国境内新研制开发的尚未批准使用的单一饲料。 本办法所称新饲料添加剂，是指我国境内新研制开发的尚未批准使用的饲料添加剂。"},{"i":3,"n":"第三条","txt":"有下列情形之一的，应当向农业农村部提出申请，参照本办法规定的新饲料、新饲料添加剂审定程序进行评审，评审通过的，由农业农村部公告作为饲料、饲料添加剂生产和使用，但不发给新饲料、新饲料添加剂证书： （一）饲料添加剂扩大适用范围的； （二）饲料添加剂含量规格低于饲料添加剂安全使用规范要求的，但由饲料添加剂与载体或者稀释剂按照一定比例配制的除外； （三）饲料添加剂生产工艺发生重大变化的； （四）新饲料、新饲料添加剂自获证之日起超过3年未投入生产，其他企业申请生产的； （五）农业农村部规定的其他情形。"},{"i":4,"n":"第四条","txt":"研制新饲料、新饲料添加剂，应当遵循科学、安全、有效、环保的原则，保证新饲料、新饲料添加剂的质量安全。"},{"i":5,"n":"第五条","txt":"农业农村部负责新饲料、新饲料添加剂审定。 全国饲料评审委员会（以下简称评审委）组织对新饲料、新饲料添加剂的安全性、有效性及其对环境的影响进行评审。"},{"i":6,"n":"第六条","txt":"新饲料、新饲料添加剂投入生产前，研制者或者生产企业（以下简称申请人）应当向农业农村部提出审定申请，并提交新饲料、新饲料添加剂的申请资料和样品。"},{"i":7,"n":"第七条","txt":"申请资料包括： （一）新饲料、新饲料添加剂审定申请表； （二）产品名称及命名依据、产品研制目的； （三）有效组分、理化性质及有效组分化学结构的鉴定报告，或者动物、植物、微生物的分类（菌种）鉴定报告，微生物发酵制品还应当提供生产所用菌株的菌种鉴定报告； （四）适用范围、使用方法、在配合饲料或全混合日粮中的推荐用量，必要时提供最高限量值； （五）生产工艺、制造方法及产品稳定性试验报告； （六）质量标准草案及其编制说明和产品检测报告；有最高限量要求的，还应提供有效组分在配合饲料、浓缩饲料、精料补充料、添加剂预混合饲料中的检测方法； （七）农业农村部指定的试验机构出具的产品有效性评价试验报告、安全性评价试验报告（包括靶动物耐受性评价报告、毒理学安全评价报告、代谢和残留评价报告等）；申请新饲料添加剂审定的，还应当提供该新饲料添加剂在养殖产品中的残留可能对人体健康造成影响的分析评价报告； （八）标"},{"i":8,"n":"第八条","txt":"产品样品应当符合以下要求： （一）来自中试或工业化生产线； （二）每个产品提供连续3个批次的样品，每个批次4份样品，每份样品不少于检测需要量的5倍； （三）必要时提供相关的标准品或化学对照品。"},{"i":9,"n":"第九条","txt":"有效性评价试验机构和安全性评价试验机构应当按照农业农村部制定的技术指导文件或行业公认的技术标准，科学、客观、公正开展试验，不得与研制者、生产企业存在利害关系。 承担试验的专家不得参与该新饲料、新饲料添加剂的评审工作。"},{"i":10,"n":"第十条","txt":"农业农村部自受理申请之日起5个工作日内，将申请资料和样品交评审委进行评审。"},{"i":11,"n":"第十一条","txt":"新饲料、新饲料添加剂的评审采取评审会议的形式。评审会议应当有9名以上评审委专家参加，根据需要也可以邀请1至2名评审委专家以外的专家参加。参加评审的专家对评审事项具有表决权。 评审会议应当形成评审意见和会议纪要，并由参加评审的专家审核签字；有不同意见的，应当注明。"},{"i":12,"n":"第十二条","txt":"参加评审的专家应当依法履行职责，科学、客观、公正提出评审意见。 评审专家与研制者、生产企业有利害关系的，应当回避。"},{"i":13,"n":"第十三条","txt":"评审会议原则通过的，由评审委将样品交农业农村部指定的饲料质量检验机构进行质量复核。质量复核机构应当自收到样品之日起3个月内完成质量复核，并将质量复核报告和复核意见报评审委，同时送达申请人。需用特殊方法检测的，质量复核时间可以延长1个月。 质量复核包括标准复核和样品检测，有最高限量要求的，还应当对申报产品有效组分在饲料产品中的检测方法进行验证。 申请人对质量复核结果有异议的，可以在收到质量复核报告后15个工作日内申请复检。"},{"i":14,"n":"第十四条","txt":"评审过程中，农业农村部可以组织对申请人的试验或生产条件进行现场核查，或者对试验数据进行核查或验证。"},{"i":15,"n":"第十五条","txt":"评审委应当自收到新饲料、新饲料添加剂申请资料和样品之日起9个月内向农业农村部提交评审结果；但是，评审委决定由申请人进行相关试验的，经农业农村部同意，评审时间可以延长3个月。"},{"i":16,"n":"第十六条","txt":"农业农村部自收到评审结果之日起10个工作日内作出是否核发新饲料、新饲料添加剂证书的决定。 决定核发新饲料、新饲料添加剂证书的，由农业农村部予以公告，同时发布该产品的质量标准。新饲料、新饲料添加剂投入生产后，按照公告中的质量标准进行监测和监督抽查。 决定不予核发的，书面通知申请人并说明理由。"},{"i":17,"n":"第十七条","txt":"新饲料、新饲料添加剂在生产前，生产者应当按照农业农村部有关规定取得生产许可证。生产新饲料添加剂的，还应当取得相应的产品批准文号。"},{"i":18,"n":"第十八条","txt":"新饲料、新饲料添加剂的监测期为5年，自新饲料、新饲料添加剂证书核发之日起计算。 监测期内不受理其他就该新饲料、新饲料添加剂提出的生产申请和进口登记申请，但该新饲料、新饲料添加剂超过3年未投入生产的除外。"},{"i":19,"n":"第十九条","txt":"新饲料、新饲料添加剂生产企业应当收集处于监测期内的产品质量、靶动物安全和养殖动物产品质量安全等相关信息，并向农业农村部报告。 农业农村部对新饲料、新饲料添加剂的质量安全状况组织跟踪监测，必要时进行再评价，证实其存在安全问题的，撤销新饲料、新饲料添加剂证书并予以公告。"},{"i":20,"n":"第二十条","txt":"从事新饲料、新饲料添加剂审定工作的相关单位和人员，应当对申请人提交的需要保密的技术资料保密。"},{"i":21,"n":"第二十一条","txt":"从事新饲料、新饲料添加剂审定工作的相关人员，不履行本办法规定的职责或者滥用职权、玩忽职守、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"申请人隐瞒有关情况或者提供虚假材料申请新饲料、新饲料添加剂审定的，农业农村部不予受理或者不予许可，并给予警告；申请人在1年内不得再次申请新饲料、新饲料添加剂审定。 以欺骗、贿赂等不正当手段取得新饲料、新饲料添加剂证书的，由农业农村部撤销新饲料、新饲料添加剂证书，申请人在3年内不得再次申请新饲料、新饲料添加剂审定；以欺骗方式取得新饲料、新饲料添加剂证书的，并处5万元以上10万元以下罚款；涉嫌犯罪的，及时将案件移送司法机关，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"其他违反本办法规定的，依照《饲料和饲料添加剂管理条例》的有关规定进行处罚。"},{"i":24,"n":"第二十四条","txt":"本办法自2012年7月1日起施行。农业部2000年8月17日发布的《新饲料和新饲料添加剂管理办法》同时废止。"}],"wuguidingdongwuyibingqupingguguanlibanfa":[{"i":1,"n":"第一条","txt":"为实施动物疫病区域化管理，规范无规定动物疫病区评估活动，有效控制和消灭动物疫病，提高动物卫生及动物产品安全水平，促进动物及动物产品贸易，根据《中华人民共和国动物防疫法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内无规定动物疫病区的评估管理。"},{"i":3,"n":"第三条","txt":"本办法所称无规定动物疫病区，是指具有天然屏障或者采用人工措施，在一定期限内没有发生规定的一种或者几种动物疫病，并经评估验收合格的区域。 无规定动物疫病区的范围，可以是以下区域： （一）省、自治区、直辖市的部分或全部地理区域； （二）毗邻省份连片的地理区域。 无规定动物疫病区分为免疫无规定动物疫病区和非免疫无规定动物疫病区。"},{"i":4,"n":"第四条","txt":"本办法所称无规定动物疫病区评估，是指按照《无规定动物疫病区管理技术规范》，对某一特定区域动物疫病状况及防控能力进行的综合评价。"},{"i":5,"n":"第五条","txt":"农业部负责无规定动物疫病区评估管理工作，制定发布《无规定动物疫病区管理技术规范》和无规定动物疫病区评审细则。 农业部设立的全国动物卫生风险评估专家委员会，承担无规定动物疫病区评估工作。"},{"i":6,"n":"第六条","txt":"无规定动物疫病区建设、评估应当符合有关国际组织确定的区域控制及风险评估的原则要求。"},{"i":7,"n":"第七条","txt":"无规定动物疫病区建成并符合《无规定动物疫病区管理技术规范》要求的，由省级人民政府兽医主管部门向农业部申请评估。跨省的无规定动物疫病区，由区域涉及的省级人民政府兽医主管部门共同申请。"},{"i":8,"n":"第八条","txt":"申请无规定动物疫病区评估应当提交申请书和自我评估报告。 申请书包括以下主要内容： （一）无规定动物疫病区概况； （二）兽医体系建设情况； （三）动物疫情报告体系情况； （四）动物疫病流行情况； （五）控制、消灭策略和措施情况； （六）免疫措施情况； （七）规定动物疫病的监测情况； （八）实验室建设情况； （九）屏障及边界控制措施情况； （十）应急体系建设及应急反应情况； （十一）其他需要说明的事项。 自我评估报告包括以下主要内容： （一）评估计划和评估专家组成情况； （二）评估程序及主要内容，评估的组织和实施情况； （三）评估结论。"},{"i":9,"n":"第九条","txt":"农业部自收到申请之日起10个工作日内作出是否受理的决定，并书面通知申请单位和全国动物卫生风险评估专家委员会。"},{"i":10,"n":"第十条","txt":"全国动物卫生风险评估专家委员会收到农业部通知后，应当在5个工作日内成立评估专家组并指定组长。评估专家组由5人以上单数组成，实行组长负责制。"},{"i":11,"n":"第十一条","txt":"评估专家组按照《无规定动物疫病区管理技术规范》和评审细则等要求，开展评估工作。 无规定动物疫病区评估应当遵循科学、公平、公正的原则，采取书面评审和现场评审相结合的方式进行。"},{"i":12,"n":"第十二条","txt":"评估专家组应当在10个工作日内完成书面评审。书面评审包括以下内容： （一）申请书和自我评估报告格式是否符合规定，有无缺项、漏项； （二）申报材料内容是否符合《无规定动物疫病区管理技术规范》的相关要求。"},{"i":13,"n":"第十三条","txt":"书面评审不合格的，由全国动物卫生风险评估专家委员会报请农业部书面通知申请单位在规定期限内补充有关材料。逾期未报送的，按撤回申请处理。"},{"i":14,"n":"第十四条","txt":"书面评审合格的，评估专家组应当制定现场评审方案，并在15个工作日内完成现场评审。"},{"i":15,"n":"第十五条","txt":"现场评审应当包括下列内容： （一）评估专家组组长主持召开会议，宣布现场评审方案和评估纪律等； （二）听取申请单位关于无规定动物疫病区建设及管理情况的介绍； （三）实地核查有关资料、档案和建设情况。"},{"i":16,"n":"第十六条","txt":"评估专家组组长可以根据评审需要，召集临时会议，对评审中发现的问题进行讨论。必要时可以要求申请单位陈述有关情况。 申请单位应当如实提供评估专家组所要求的有关资料，并配合专家组开展评估。"},{"i":17,"n":"第十七条","txt":"评估专家组应当根据评审细则确定的评审指标逐项核查，对核查结果进行综合评价，形成现场评审结果。 现场评审结果分为“建议通过”、“建议整改后通过”、“建议不予通过”。 现场评审结果为“建议通过”的，应当符合下列条件： （一）现场评审指标中的关键项全部为“符合”，重点项没有“不符合”项。 （二）“符合”项占总项数80%以上（含）。其中：重点项中“基本符合”项数不超过重点项总项数的15%；普通项中“不符合”项总项数不超过普通项总项数的10%。 现场评审结果为“建议整改后通过”的，应当符合下列条件： （一）关键项中没有“不符合”项； （二）“符合”项总项数达到60%以上（含）但不足80%； （三）通过限期整改可以达到“建议通过”条件。 有下列情形之一的，现场评审结果为“建议不予通过”： （一）关键项中有“不符合”项； （二）“符合”项总项数不足60%； （三）申请单位隐瞒有关情况或者有其他欺骗行"},{"i":18,"n":"第十八条","txt":"需要整改的，由全国动物卫生风险评估专家委员会办公室根据评估专家组建议，书面通知申请单位在规定期限内进行整改。"},{"i":19,"n":"第十九条","txt":"申请单位在规定期限内完成整改后，将整改报告及相关证明材料报评估专家组审核，必要时进行现场核查，形成评审结果。 申请单位未在规定期限内提交整改报告及相关证明材料的，按撤回申请处理。"},{"i":20,"n":"第二十条","txt":"评估专家组应当在现场评审或整改审核结束后20个工作日内向全国动物卫生风险评估专家委员会提交评估报告，全国动物卫生风险评估专家委员会组织召开全体委员会议或专题会议审核后报农业部。"},{"i":21,"n":"第二十一条","txt":"评估专家组在评审过程中，应当遵守有关法律法规和工作制度，坚持原则，认真负责，廉洁自律，客观公正，对被评估单位提供的信息资料保密。评估专家组成员不得有下列行为： （一）接受被评估单位或与被评估单位有关的中介机构或人员的馈赠； （二）私下与上述单位或人员进行不当接触； （三）评估结果未公布前，泄露评估结果及相关信息； （四）其他可能影响公正评估的行为。"},{"i":22,"n":"第二十二条","txt":"农业部自收到评估报告后20个工作日内完成审核，并作出无规定动物疫病区是否合格的决定。"},{"i":23,"n":"第二十三条","txt":"农业部将审核合格的无规定动物疫病区列入国家无规定动物疫病区名录，并对外公布。不合格的，书面通知申请单位并说明理由。"},{"i":24,"n":"第二十四条","txt":"农业部根据需要向有关国际组织、国家和地区通报评估情况，并根据无规定动物疫病区所在地省级人民政府兽医主管部门的意见，申请国际评估认可。"},{"i":25,"n":"第二十五条","txt":"农业部对已公布无规定动物疫病区的建设维持情况开展监督检查，发现问题的，通知所在地省级人民政府兽医主管部门限期整改。"},{"i":26,"n":"第二十六条","txt":"有下列情形之一的，农业部暂停无规定动物疫病区资格： （一）在无规定动物疫病区内发生有限疫情，按照《无规定动物疫病区管理技术规范》在规定时间内可以建立感染控制区的； （二）区域区划发生变化，且屏障体系不能满足区域管理要求的； （三）兽医机构体系及财政保障能力发生重大变化，不能支持无规定动物疫病区管理、维持和运行的； （四）监测证据不能证明规定动物疫病无疫状况的； （五）其他不符合《无规定动物疫病区管理技术规范》要求，需要暂停的情形。"},{"i":27,"n":"第二十七条","txt":"出现第二十六条第一项规定情形的，省级人民政府兽医主管部门应当在规定动物疫病发生后24小时内开始建设感染控制区。 有限疫情控制后，感染控制区在规定动物疫病的2个潜伏期内未再发生规定动物疫病，且符合《无规定动物疫病区管理技术规范》要求的，全国动物卫生风险评估专家委员会根据省级人民政府兽医主管部门的申请，按照《无规定动物疫病区管理技术规范》对感染控制区建设情况组织开展评估。评估合格的，农业部对外宣布建成感染控制区，并恢复感染控制区外的无规定动物疫病区资格。 感染控制区建成后，在规定时间内未发生规定动物疫病的，全国动物卫生风险评估专家委员会根据省级人民政府兽医主管部门的申请，按照《无规定动物疫病区管理技术规范》进行评估。评估合格的，农业部恢复其无规定动物疫病区资格。"},{"i":28,"n":"第二十八条","txt":"出现第二十六条第二项至第五项规定情形的，省级人民政府兽医主管部门应当根据农业部要求限期整改，经全国动物卫生风险评估专家委员会对整改情况评估合格的，农业部恢复其无规定动物疫病区资格。"},{"i":29,"n":"第二十九条","txt":"有下列情形之一的，农业部撤销无规定动物疫病区资格： （一）发生规定动物疫病，且未在规定时间内建成感染控制区的； （二）出现第二十六条第二项至第五项规定情形，且未能在规定时间内完成整改的； （三）伪造、隐藏、毁灭有关证据或者提供虚假证明材料，妨碍无规定动物疫病区检查评估的； （四）其他不符合《无规定动物疫病区管理技术规范》要求，需要撤销的情形。"},{"i":30,"n":"第三十条","txt":"被撤销资格的无规定动物疫病区，重新达到《无规定动物疫病区管理技术规范》要求的，由所在地省级人民政府兽医主管部门提出申请，申请材料应包括与资格撤销原因有关的整改说明、规定动物疫病状况、疫病防控措施等。经全国动物卫生风险评估专家委员会评估通过的，农业部重新认定其无规定动物疫病区资格。"},{"i":31,"n":"第三十一条","txt":"境外无规定动物疫病区的无疫等效评估，参照本办法执行。"},{"i":32,"n":"第三十二条","txt":"无规定动物疫病小区（无规定动物疫病生物安全隔离区）是指处于同一生物安全管理体系下的养殖场区，在一定期限内没有发生一种或几种规定动物疫病的若干动物养殖和其他辅助生产单元所构成的特定小型区域。无规定动物疫病小区的评估原则、程序及要求由农业部另行制定发布。"},{"i":33,"n":"第三十三条","txt":"本办法自2017年7月1日起施行。农业部2007年1月23日发布的《无规定动物疫病区评估管理办法》（农业部令第1号）同时废止。"}],"zhiwujianyitiaolishishixize-2":[{"i":1,"n":"第一条","txt":"根据《植物检疫条例》第二十三条的规定，制定本细则。"},{"i":2,"n":"第二条","txt":"本细则适用于国内农业植物检疫，不包括林业和进出境植物检疫。"},{"i":3,"n":"第三条","txt":"农业部主管全国农业植物检疫工作，其执行机构是所属的植物检疫机构；各省、自治区、直辖市农业主管部门主管本地区的农业植物检疫工作；县级以上地方各级农业主管部门所属的植物检疫机构负责执行本地区的植物检疫任务。"},{"i":4,"n":"第四条","txt":"各级植物检疫机构的职责范围： (一)农业部所属植物检疫机构的主要职责： 1.提出有关植物检疫法规、规章及检疫工作长远规划的建议; 2.贯彻执行《植物检疫条例》，协助解决执行中出现的问题； 3.调查研究和总结推广植物检疫工作经验，汇编全国植物检疫资料，拟定全国重点植物检疫对象的普查、疫区划定、封锁和防治消灭措施的实施方案; 4.负责国外引进种子、苗木和其他繁殖材料(国家禁止进境的除外)的检疫审批； 5.组织植物检疫技术的研究和示范； 6.培训、管理植物检疫干部及技术人员。 (二)省级植物检疫机构的主要职责： 1.贯彻《植物检疫条例》及国家发布的各项植物检疫法令、规章制度，制定本省的实施计划和措施； 2.检查并指导地、县级植物检疫机构的工作； 3.拟订本省的《植物检疫实施办法》、《补充的植物检疫对象及应施检疫的植物、植物产品名单》和其他植物检疫规章制度； 4.拟订省内划定疫区和保护区的方案"},{"i":5,"n":"第五条","txt":"各级植物检疫机构必须配备一定数量的专职植物检疫人员，并逐步建立健全相应的检疫实验室和检验室。 专职植物检疫员应当是具有助理农艺师以上技术职务、或者虽无技术职务而具有中等专业学历、从事植保工作三年以上的技术人员，并经培训考核合格，由省级农业主管部门批准，报农业部备案后，发给专职植物检疫员证。各级植物检疫机构可根据工作需要，在种苗繁育、生产及科研等有关单位聘请兼职植物检疫员或特邀植物检疫员协助开展工作。兼职检疫员由所在单位推荐，经聘请单位审查合格后，发给聘书。 省级植物检疫机构应充实、健全植物检疫实验室，地(市)、县级植物检疫机构应根据情况逐步建立健全检验室，按照《植物检疫操作规程》进行检验，为植物检疫签证提供科学依据。"},{"i":6,"n":"第六条","txt":"植物检疫证书的签发： (一)省间调运种子、苗木等繁殖材料及其他应施检疫的植物、植物产品，由省级植物检疫机构及其授权的地(市)、县级植物检疫机构签发植物检疫证书；省内种子、苗木及其他应施检疫的植物、植物产品的调运，由地(市)、县级植物检疫机构签发检疫证书。 (二)植物检疫证书应加盖签证机关植物检疫专用章，并由专职植物检疫员署名签发；授权签发的省间调运植物检疫证书还应当盖有省级植物检疫机构的植物检疫专用章。 (三)植物检疫证书式样由农业部统一制定。证书一式四份，正本一份，副本三份。正本交货主随货单寄运，副本一份由货主交收寄、托运单位留存，一份交收货单位或个人所在地(县)植物检疫机构(省间调运寄给调入省植物检疫机构)，一份留签证的植物检疫机构。"},{"i":7,"n":"第七条","txt":"植物检疫机构应当自受理检疫申请之日起20日内作出审批决定，检疫和专家评审所需时间除外。"},{"i":8,"n":"第八条","txt":"植物检疫人员着装办法以及服装、标志式样等由农业部、财政部统一制定。"},{"i":9,"n":"第九条","txt":"农业植物检疫范围包括粮、棉、油、麻、桑、茶、糖、菜、烟、果(干果除外)、药材、花卉、牧草、绿肥、热带作物等植物、植物的各部分，包括种子、块根、块茎、球茎、鳞茎、接穗、砧木、试管苗、细胞繁殖体等繁殖材料，以及来源于上述植物、未经加工或者虽经加工但仍有可能传播疫情的植物产品。 全国植物检疫对象和应施检疫的植物、植物产品名单，由农业部统一制定；各省、自治区、直辖市补充的植物检疫对象和应施检疫的植物、植物产品名单，由各省、自治区、直辖市农业主管部门制定，并报农业部备案。"},{"i":10,"n":"第十条","txt":"根据《植物检疫条例》第七条和第八条第三款的规定，省间调运植物、植物产品，属于下列情况的必须实施检疫： (一)凡种子、苗木和其他繁殖材料，不论是否列入应施检疫的植物、植物产品名单和运往何地，在调运之前，都必须经过检疫； (二)列入全国和省、自治区、直辖市应施检疫的植物、植物产品名单的植物产品，运出发生疫情的县级行政区域之前，必须经过检疫； (三)对可能受疫情污染的包装材料、运载工具、场地、仓库等也应实施检疫。"},{"i":11,"n":"第十一条","txt":"各级植物检疫机构对本辖区的植物检疫对象原则上每隔三至五年调查一次，重点对象要每年调查。根据调查结果编制检疫对象分布资料，并报上一级植物检疫机构。"},{"i":12,"n":"第十二条","txt":"全国植物检疫对象、国外新传入和国内突发性的危险性病、虫、杂草的疫情，由农业部发布；各省、自治区、直辖市补充的植物检疫对象的疫情，由各省、自治区、直辖市农业主管部门发布，并报农业部备案。"},{"i":13,"n":"第十三条","txt":"划定疫区和保护区，要同时制定相应的封锁、控制、消灭或保护措施。在发生疫情的地区，植物检疫机构可以按照《植物检疫条例》第五条第三款的规定，派人参加道路联合检查站或者经省、自治区、直辖市人民政府批准，设立植物检疫检查站，开展植物检疫工作。各省、自治区、直辖市植物检疫机构应当就本辖区内设立或者撤销的植物检疫检查站名称、地点等报农业部备案。 疫区内的种子、苗木及其他繁殖材料和应施检疫的植物、植物产品，只限在疫区内种植、使用，禁止运出疫区；如因特殊情况需要运出疫区的，必须事先征得所在地省级植物检疫机构批准，调出省外的，应经农业部批准。"},{"i":14,"n":"第十四条","txt":"疫区内的检疫对象，在达到基本消灭或已取得控制蔓延的有效办法以后，应按照疫区划定时的程序，办理撤销手续，经批准后明文公布。"},{"i":15,"n":"第十五条","txt":"根据《植物检疫条例》第九条和第十条规定，省间调运应施检疫的植物、植物产品，按照下列程序实施检疫： (一)调入单位或个人必须事先征得所在地的省、自治区、直辖市植物检疫机构或其授权的地(市)、县级植物检疫机构同意，并取得检疫要求书； (二)调出地的省、自治区、直辖市植物检疫机构或其授权的当地植物检疫机构，凭调出单位或个人提供的调入地检疫要求书受理报检，并实施检疫。 (三)邮寄、承运单位一律凭有效的植物检疫证书正本收寄、承运应施检疫的植物、植物产品。"},{"i":16,"n":"第十六条","txt":"调出单位所在地的省、自治区、直辖市植物检疫机构或其授权的地(市)、县级植物检疫机构，按下列不同情况签发植物检疫证书： (一)在无植物检疫对象发生地区调运植物、植物产品，经核实后签发植物检疫证书； (二)在零星发生植物检疫对象的地区调运种子、苗木等繁殖材料时，应凭产地检疫合格证签发植物检疫证书； (三)对产地植物检疫对象发生情况不清楚的植物、植物产品，必须按照《调运检疫操作规程》进行检疫，证明不带植物检疫对象后，签发植物检疫证书。 在上述调运检疫过程中，发现有检疫对象时，必须严格进行除害处理，合格后，签发植物检疫证书；未经除害处理或处理不合格的，不准放行。"},{"i":17,"n":"第十七条","txt":"调入地植物检疫机构，对来自发生疫情的县级行政区域的应检植物、植物产品，或者其他可能带有检疫对象的应检植物、植物产品可以进行复检。复检中发现问题的，应当与原签证植物检疫机构共同查清事实，分清责任，由复检的植物检疫机构按照《植物检疫条例》的规定予以处理。"},{"i":18,"n":"第十八条","txt":"各级植物检疫机构对本辖区的原种场、良种场、苗圃以及其他繁育基地，按照国家和地方制定的《植物检疫操作规程》实施产地检疫，有关单位或个人应给予必要的配合和协助。"},{"i":19,"n":"第十九条","txt":"种苗繁育单位或个人必须有计划地在无植物检疫对象分布的地区建立种苗繁育基地。新建的良种场、原种场、苗圃等，在选址以前，应征求当地植物检疫机构的意见；植物检疫机构应帮助种苗繁育单位选择符合检疫要求的地方建立繁育基地。 已经发生检疫对象的良种场、原种场、苗圃等，应立即采取有效措施封锁消灭。在检疫对象未消灭以前，所繁育的材料不准调入无病区，经过严格除害处理并经植物检疫机构检疫合格的，可以调运。"},{"i":20,"n":"第二十条","txt":"试验、示范、推广的种子、苗木和其他繁殖材料，必须事先经过植物检疫机构检疫，查明确实不带植物检疫对象的，发给植物检疫证书后，方可进行试验、示范和推广。"},{"i":21,"n":"第二十一条","txt":"从国外引进种子、苗木和其他繁殖材料(国家禁止进境的除外)，实行农业部和省、自治区、直辖市农业主管部门两级审批。 种苗的引进单位或者代理进口单位应当在对外签订贸易合同、协议三十日前向种苗种植地的省、自治区、直辖市植物检疫机构提出申请，办理国外引种检疫审批手续。引种数量较大的，由种苗种植地的省、自治区、直辖市植物检疫机构审核并签署意见后，报农业部农业司或其授权单位审批。 国务院有关部门所属的在京单位、驻京部队单位、外国驻京机构等引种，应当在对外签订贸易合同、协议三十日前向农业部农业司或其授权单位提出申请，办理国外引种检疫审批手续。 国外引种检疫审批管理办法由农业部另行制定。"},{"i":22,"n":"第二十二条","txt":"从国外引进种子、苗木等繁殖材料，必须符合下列检疫要求： (一)引进种子、苗木和其他繁殖材料的单位或者代理单位必须在对外贸易合同或者协议中订明中国法定的检疫要求，并订明输出国家或者地区政府植物检疫机关出具检疫证书，证明符合中国的检疫要求。 (二)引进单位在申请引种前，应当安排好试种计划。引进后，必须在指定的地点集中进行隔离试种，隔离试种的时间，一年生作物不得少于一个生育周期，多年生作物不得少于二年。 在隔离试种期内，经当地植物检疫机关检疫，证明确实不带检疫对象的，方可分散种植。如发现检疫对象或者其他危险性病、虫、杂草，应认真按植物检疫机构的意见处理。"},{"i":23,"n":"第二十三条","txt":"各省、自治区、直辖市农业主管部门应根据需要逐步建立植物检疫隔离试种场(圃)。"},{"i":24,"n":"第二十四条","txt":"凡执行《植物检疫条例》有下列突出成绩之一的单位和个人，由农业部、各省、自治区、直辖市人民政府或者农业主管部门给予奖励。 (一)在开展植物检疫对象和危险性病、虫、杂草普查方面有显著成绩的； (二)在植物检疫对象的封锁、控制、消灭方面有显著成绩的； (三)在积极宣传和模范执行《植物检疫条例》、植物检疫规章制度、与违反《植物检疫条例》行为作斗争等方面成绩突出的； (四)在植物检疫技术的研究和应用上有重大突破的； (五)铁路、交通、邮政、民航等部门和当地植物检疫机构密切配合，贯彻执行《植物检疫条例》成绩显著的。"},{"i":25,"n":"第二十五条","txt":"有下列违法行为之一，尚未构成犯罪的，由植物检疫机构处以罚款： (一)在报检过程中故意谎报受检物品种类、品种，隐瞒受检物品数量、受检作物面积，提供虚假证明材料的； (二)在调运过程中擅自开拆检讫的植物、植物产品，调换或者夹带其他未经检疫的植物、植物产品，或者擅自将非种用植物、植物产品作种用的； (三)伪造、涂改、买卖、转让植物检疫单证、印章、标志、封识的； (四)违反《植物检疫条例》第七条、第八条第一款、第十条规定之一，擅自调运植物、植物产品的； (五)违反《植物检疫条例》第十一条规定，试验、生产、推广带有植物检疫对象的种子、苗木和其他繁殖材料，或者违反《植物检疫条例》第十三条规定，未经批准在非疫区进行检疫对象活体试验研究的； (六)违反《植物检疫条例》第十二条第二款规定，不在指定地点种植或者不按要求隔离试种，或者隔离试种期间擅自分散种子、苗木和其他繁殖材料的。 罚款按以下标准执行： 对"},{"i":26,"n":"第二十六条","txt":"国内植物检疫收费按照国家有关规定执行。"},{"i":27,"n":"第二十七条","txt":"本实施细则所称“以上”、“以下”，均包括本数在内。 本实施细则所称“疫情”，是指全国植物检疫对象、各省、自治区、直辖市补充的植物检疫对象、国外新传入的和国内突发性的危险性病、虫、杂草以及植物检疫对象和危险性病虫杂草的发生、分布情况。"},{"i":28,"n":"第二十八条","txt":"植物检疫规章和规范性文件的制定，必须以国务院发布的《植物检疫条例》为准，任何与《植物检疫条例》相违背的规章和规范性文件，均属无效。"},{"i":29,"n":"第二十九条","txt":"本实施细则由农业部负责解释。"},{"i":30,"n":"第三十条","txt":"本实施细则自公布之日起施行。1983年10月20日农牧渔业部发布的《植物检疫条例实施细则(农业部分)》同时废止。"}],"shuichanyangzhizhilianganquanguanliguiding":[{"i":1,"n":"第一条","txt":"为提高养殖水产品质量安全水平，保护渔业生态环境，促进水产养殖业的健康发展，根据《中华人民共和国渔业法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事水产养殖的单位和个人，应当遵守本规定。"},{"i":3,"n":"第三条","txt":"农业部主管全国水产养殖质量安全管理工作。 县级以上地方各级人民政府渔业行政主管部门主管本行政区域内水产养殖质量安全管理工作。"},{"i":4,"n":"第四条","txt":"国家鼓励水产养殖单位和个人发展健康养殖，减少水产养殖病害发生；控制养殖用药，保证养殖水产品质量安全；推广生态养殖，保护养殖环境。 国家鼓励水产养殖单位和个人依照有关规定申请无公害农产品认证。"},{"i":5,"n":"第五条","txt":"水产养殖用水应当符合农业部《无公害食品海水养殖用水水质》（NY5052-2001）或《无公害食品淡水养殖用水水质》（NY5051-2001）等标准，禁止将不符合水质标准的水源用于水产养殖。"},{"i":6,"n":"第六条","txt":"水产养殖单位和个人应当定期监测养殖用水水质。 养殖用水水源受到污染时，应当立即停止使用；确需使用的，应当经过净化处理达到养殖用水水质标准。 养殖水体水质不符合养殖用水水质标准时，应当立即采取措施进行处理。经处理后仍达不到要求的，应当停止养殖活动，并向当地渔业行政主管部门报告，其养殖水产品按本规定第十三条处理。"},{"i":7,"n":"第七条","txt":"养殖场或池塘的进排水系统应当分开。水产养殖废水排放应当达到国家规定的排放标准。"},{"i":8,"n":"第八条","txt":"县级以上地方各级人民政府渔业行政主管部门应当根据水产养殖规划要求，合理确定用于水产养殖的水域和滩涂，同时根据水域滩涂环境状况划分养殖功能区，合理安排养殖生产布局，科学确定养殖规模、养殖方式。"},{"i":9,"n":"第九条","txt":"使用水域、滩涂从事水产养殖的单位和个人应当按有关规定申领养殖证，并按核准的区域、规模从事养殖生产。"},{"i":10,"n":"第十条","txt":"水产养殖生产应当符合国家有关养殖技术规范操作要求。水产养殖单位和个人应当配置与养殖水体和生产能力相适应的水处理设施和相应的水质、水生生物检测等基础性仪器设备。 水产养殖使用的苗种应当符合国家或地方质量标准。"},{"i":11,"n":"第十一条","txt":"水产养殖专业技术人员应当逐步按国家有关就业准入要求，经过职业技能培训并获得职业资格证书后，方能上岗。"},{"i":12,"n":"第十二条","txt":"水产养殖单位和个人应当填写《水产养殖生产记录》（格式见附件1），记载养殖种类、苗种来源及生长情况、饲料来源及投喂情况、水质变化等内容。《水产养殖生产记录》应当保存至该批水产品全部销售后2年以上。"},{"i":13,"n":"第十三条","txt":"销售的养殖水产品应当符合国家或地方的有关标准。不符合标准的产品应当进行净化处理，净化处理后仍不符合标准的产品禁止销售。"},{"i":14,"n":"第十四条","txt":"水产养殖单位销售自养水产品应当附具《产品标签》（格式见附件2），注明单位名称、地址，产品种类、规格，出池日期等。"},{"i":15,"n":"第十五条","txt":"使用渔用饲料应当符合《饲料和饲料添加剂管理条例》和农业部《无公害食品渔用饲料安全限量》（NY5072-2002）。鼓励使用配合饲料。限制直接投喂冰鲜（冻）饵料，防止残饵污染水质。 禁止使用无产品质量标准、无质量检验合格证、无生产许可证和产品批准文号的饲料、饲料添加剂。禁止使用变质和过期饲料。"},{"i":16,"n":"第十六条","txt":"使用水产养殖用药应当符合《兽药管理条例》和农业部《无公害食品渔药使用准则》（NY5071-2002）。使用药物的养殖水产品在休药期内不得用于人类食品消费。 禁止使用假、劣兽药及农业部规定禁止使用的药品、其他化合物和生物制剂。原料药不得直接用于水产养殖。"},{"i":17,"n":"第十七条","txt":"水产养殖单位和个人应当按照水产养殖用药使用说明书的要求或在水生生物病害防治员的指导下科学用药。 水生生物病害防治员应当按照有关就业准入的要求，经过职业技能培训并获得职业资格证书后，方能上岗。"},{"i":18,"n":"第十八条","txt":"水产养殖单位和个人应当填写《水产养殖用药记录》（格式见附件3），记载病害发生情况，主要症状，用药名称、时间、用量等内容。《水产养殖用药记录》应当保存至该批水产品全部销售后2年以上。"},{"i":19,"n":"第十九条","txt":"各级渔业行政主管部门和技术推广机构应当加强水产养殖用药安全使用的宣传、培训和技术指导工作。"},{"i":20,"n":"第二十条","txt":"农业部负责制定全国养殖水产品药物残留监控计划，并组织实施。 县级以上地方各级人民政府渔业行政主管部门负责本行政区域内养殖水产品药物残留的监控工作。"},{"i":21,"n":"第二十一条","txt":"水产养殖单位和个人应当接受县级以上人民政府渔业行政主管部门组织的养殖水产品药物残留抽样检测。"},{"i":22,"n":"第二十二条","txt":"本规定用语定义： 健康养殖指通过采用投放无疫病苗种、投喂全价饲料及人为控制养殖环境条件等技术措施，使养殖生物保持最适宜生长和发育的状态，实现减少养殖病害发生、提高产品质量的一种养殖方式。 生态养殖指根据不同养殖生物间的共生互补原理，利用自然界物质循环系统，在一定的养殖空间和区域内，通过相应的技术和管理措施，使不同生物在同一环境中共同生长，实现保持生态平衡、提高养殖效益的一种养殖方式。"},{"i":23,"n":"第二十三条","txt":"违反本规定的，依照《中华人民共和国渔业法》、《兽药管理条例》和《饲料和饲料添加剂管理条例》等法律法规进行处罚。"},{"i":24,"n":"第二十四条","txt":"本规定由农业部负责解释。"},{"i":25,"n":"第二十五条","txt":"本规定自2003年9月1日起施行。"}],"shuichanyuanliangzhongshendingbanfa":[{"i":1,"n":"第一条","txt":"为加强对水产原、良种种质及其种苗生产的管理，科学、公正、及时地审定和推广水产原、良种，促进渔业生产的发展，根据《中华人民共和国渔业法》，特制定本审定办法。"},{"i":2,"n":"第二条","txt":"凡具备下列条件之一者，均可向农业部申请审定。 （一）现有主要养殖（栽培）对象； （二）育成养殖新对象，经连续二年生产性养殖对比试验，累计试验面积混养不低于5000亩，单养不低于500亩，并表现优异者； （三）养（增）殖开发利用新对象，经连续二年生产性养（增）殖试验，累计养殖面积混养不低于1万亩，增殖试验面积不低于20万亩，并表现优异者； （四）国外引进养（增）殖新对象，经连续二年生产性养（增）殖对比试验（试验面积与第3项同），表现优异者； （五）经证实具有育种应用价值的原种； （六）特殊养（增）殖对象。"},{"i":3,"n":"第三条","txt":"凡申请审定者，必须报送下列材料一式20份： （一）主件：水产原、良种审定申请书。 （二）附件： （1）研究报告（技术总结）； （2）养（增）殖繁殖制种技术报告； （3）品种标准； （4）专业单位的种质检测报告（复印件）； （5）专业单位的抗病性鉴定报告（复印件）； （6）连续二年生产性对比养（增）殖试验年度总结及承试单位评价意见（复印件）； （7）申请审定水产苗种的生产技术说明。"},{"i":4,"n":"第四条","txt":"审定程序如下： （一）向所在地省级人民政府渔业行政主管部门提出申请； （二）省级人民政府渔业行政主管部门应当自申请受理之日起20日内完成初审，并将初步审查意见和申请人的全部申请材料报农业部审批； （三）农业部自收到省级人民政府渔业行政主管部门报送的材料之日起5日内将材料送全国水产原、良种审定委员会（以下简称审委会）审定； （四）农业部自收到审委会的审定意见之日起15日内作出是否准予通过审定的决定。同意通过审定的，向申请人送达通过审定的书面证明文件，并予以公告。不同意通过审定的，书面通知申请人并说明理由。"},{"i":5,"n":"第五条","txt":"每年的12月31日为申请水产原、良种审定的截止日期（以寄出邮戳为准）。"},{"i":6,"n":"第六条","txt":"审委会根据《水产原、良种审定标准》和有关国家标准进行审定。"},{"i":7,"n":"第七条","txt":"审委会全体委员会议对申请审定的水产原、良种，以无记名投票方式决定其通过审定或缓予审定。通过审定或缓予审定的决定，应有三分之二以上委员到会，到会委员二分之一以上通过，方为有效。"},{"i":8,"n":"第八条","txt":"审定通过的水产原、良种，其中文名称前冠以“GS”两个拼音字母（“GS”为“国”和“审”两字的第一个拼音字母）。"},{"i":9,"n":"第九条","txt":"经审定通过的品种、杂交种等的育成者在申报各级奖励时，其审定证书可以视同专家鉴定证书。"},{"i":10,"n":"第十条","txt":"国家审定通过的水产原、良种，可在农业部公告的适宜养殖区域内推广养殖。审定通过的水产原、良种在生产利用过程中，如发现有不可克服的弱点，审委会应提出停止推广建议，报农业部公布。"},{"i":11,"n":"第十一条","txt":"未经审定或审定不合格的水产新品种、良种、国（境）外引进种，不得进行广告宣传，不准推广，不得报奖。"},{"i":12,"n":"第十二条","txt":"本办法由农业部负责解释。"},{"i":13,"n":"第十三条","txt":"本办法自发布之日起施行。"}],"shuichanpinpifashichangguanlibanfa":[{"i":1,"n":"第一条","txt":"为了引导、规范水产品市场主体，加强水产品市场管理，维护市场秩序，促进渔业经济协调发展，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于各类水产品批发市场。市场开办者和市场经营者必须遵守本办法的规定。"},{"i":3,"n":"第三条","txt":"批发市场的交易必须体现“公开、公正、公平、安全”的原则。"},{"i":4,"n":"第四条","txt":"渔业行政主管部门对水产品批发市场实施行业指导和管理，工商行政管理机关对水产品批发市场的交易行为实行监督管理。"},{"i":5,"n":"第五条","txt":"工商行政管理机关和渔业行政主管部门对《水产品批发市场管理办法》的实施情况进行监督检查，被检查的单位和个人应当予以配合。"},{"i":6,"n":"第六条","txt":"以水产品为主要经营对象的批发市场，必须统一使用“×××水产品批发市场”的名称。"},{"i":7,"n":"第七条","txt":"市场开办依照国家工商行政管理局《商品交易市场登记管理办法》进行。"},{"i":8,"n":"第八条","txt":"设立水产品批发市场必须具备以下条件： （一）具有批发市场的名称和章程，批发市场章程必须载明下列事项： 1.市场名称及场址； 2.经营范围及市场规划； 3.资金来源及投资方式； 4.法定代表人的产生程序和职责； 5.组织机构及其职责； 6.服务项目和收费标准； 7.其他需要明确的事项。 （二）符合地方的统一规划和布局。批发市场选点要符合水产品批发市场总体规划布局。批发市场在城市规划和渔港规划范围内的，各项建设必须符合城市规划和渔港规划的要求，服从规划管理。各项建设必须符合国家环境保护的法律、行政法规和标准。 （三）具有与经营规模相适应的交易设施，如固定的场地、码头、冷藏、加工、运输、结算、信息传递等设施，以及管理机构和其他条件。 （四）国家规定的其他条件。"},{"i":9,"n":"第九条","txt":"国家重点水产品批发市场的设立，应当由市场所在地的人民政府批准，由市场开办者向批发市场所在地的工商行政管理机关申请登记注册。"},{"i":10,"n":"第十条","txt":"地方水产品批发市场在登记注册后，其管理形式可以参照国家重点水产品批发市场的管理办法执行。"},{"i":11,"n":"第十一条","txt":"市场分立、合并、停业、迁移或者其他重要事项的变更，必须经本办法第七条、第九条、第十条规定的市场审批部门核准，权利、义务由变更后的法人享有和承担。"},{"i":12,"n":"第十二条","txt":"市场因下列原因之一终止： （一）批发市场提出申请，经原批准的政府同意后注销登记； （二）依法被撤销； （三）依法宣告破产； （四）其他合法终止。"},{"i":13,"n":"第十三条","txt":"批发市场终止后，应当依法成立资产清算组织，清算其资产及债权债务。"},{"i":14,"n":"第十四条","txt":"进入水产品批发市场的货物，必须在政府批准该市场经办的批发业务范围之内。进入市场的货物必须符合卫生、渔政部门的规定；腐坏变质、有毒及其他有可能对人体健康有害的货物，违法捕获的水产品，不得进入市场。"},{"i":15,"n":"第十五条","txt":"批发交易必须保证公正、合理、严禁垄断。 （一）批发交易一般应当以拍卖或者投标方式进行。但形不成拍卖或者投标条件的，也可以采取议价销售或者定价销售方式。登场货物较多，以拍卖或者投标方式批发后剩余的物品，也可以采取议价销售方式。 （二）市场开办者及其工作人员不得在批发市场内对其经营范围内的货物有买卖行为。 （三）批发交易开始前，应当公布上一日各主要货物成交的价格，并公布当日到货情况，包括各种货物的品名、数量及供货人。"},{"i":16,"n":"第十六条","txt":"市场经营者应当按照国家规定交纳市场管理费，并依法纳税。"},{"i":17,"n":"第十七条","txt":"批发市场应当组建相应的结算系统。货物成交后，由市场委派的专职人员开具销售货款票，其内容应当包括货物品名、数量、单价、货款总额、供货人、买货人等项，由买货人持票到市场财务结算处办理货款结算手续，并交纳费、税后，凭票取货。"},{"i":18,"n":"第十八条","txt":"各批发市场应当制定本市场交易规则及市场工作人员职责，公布于众，并对本市场工作人员定期考核，征求买卖双方对改进市场服务管理工作及对工作人员的意见。"},{"i":19,"n":"第十九条","txt":"批发市场有下列行为之一的，由工商行政管理机关、渔业行政主管部门依据有关法律、法规、规章给予行政处罚： （一）违反《商品交易市场登记管理办法》，未经审批、核准登记或者未按规定程序申请、审批、核准登记，擅自开办批发市场的； （二）登记时弄虚作假或者不按规定申请变更登记的； （三）批发出售变质水产品或者以次充好，以少充多的； （四）批发出售国家禁止上市的水产品和违反《中华人民共和国水生野生动物保护实施条例》的； （五）其他违反工商行政管理法规的行为。"},{"i":20,"n":"第二十条","txt":"批发市场管理人员违纪的，由主管部门根据情节予以从严处理。"},{"i":21,"n":"第二十一条","txt":"省、自治区、直辖市、计划单列市人民政府，可以根据本办法，结合本地实际情况，制定实施细则。"},{"i":22,"n":"第二十二条","txt":"本办法发布后，原有批发市场必须补办有关手续。"},{"i":23,"n":"第二十三条","txt":"本办法所指的“国家重点水产品批发市场”，是指中央参与投资建设的水产品批发市场。"},{"i":24,"n":"第二十四条","txt":"本办法所指的“地方水产品批发市场”，是指国家重点水产品批发市场以外的批发市场。"},{"i":25,"n":"第二十五条","txt":"本办法由农业部和国家工商行政管理局负责解释。"},{"i":26,"n":"第二十六条","txt":"本办法自公布之日起施行。"}],"shuichanzhongzhiziyuanbaohuquguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范水产种质资源保护区的设立和管理，加强水产种质资源保护，根据《渔业法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称水产种质资源保护区，是指为保护水产种质资源及其生存环境，在具有较高经济价值和遗传育种价值的水产种质资源的主要生长繁育区域，依法划定并予以特殊保护和管理的水域、滩涂及其毗邻的岛礁、陆域。 根据保护对象资源状况、自然环境及保护需要，水产种质资源保护区划分为核心区和实验区。对核心区应当采取严格保护措施。"},{"i":3,"n":"第三条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他水域内设立和管理水产种质资源保护区，从事涉及水产种质资源保护区的有关活动，应当遵守本办法。"},{"i":4,"n":"第四条","txt":"农业部主管全国水产种质资源保护区工作。 省级人民政府渔业行政主管部门负责辖区内水产种质资源保护区工作。"},{"i":5,"n":"第五条","txt":"农业部组织省级人民政府渔业行政主管部门制定全国水产种质资源保护区总体规划，加强水产种质资源保护区建设。 省级人民政府渔业行政主管部门应当根据全国水产种质资源保护区总体规划，科学制定本行政区域内水产种质资源保护区具体实施计划，并组织落实。"},{"i":6,"n":"第六条","txt":"对破坏、侵占水产种质资源保护区的行为，任何单位和个人都有权向渔业行政主管部门举报。接到举报的渔业行政主管部门应当依法调查处理，并将处理结果告知举报人。"},{"i":7,"n":"第七条","txt":"下列区域应当设立水产种质资源保护区： （一）国家或地方规定的重点保护水生生物物种的主要生长繁育区域； （二）我国特有或地方特有水产种质资源的主要生长繁育区域； （三）重要水产养殖对象的原种、苗种的主要天然生长繁育区域； （四）其他具有较高经济价值和遗传育种价值的水产种质资源的主要生长繁育区域。"},{"i":8,"n":"第八条","txt":"水产种质资源保护区分为国家级水产种质资源保护区和省级水产种质资源保护区。 农业部和省级人民政府渔业行政主管部门分别设立国家级和省级水产种质资源保护区评审委员会，对申报的水产种质资源保护区进行评审。 水产种质资源保护区评审委员会应当由渔业、环保、水利、交通、海洋、生物保护等方面的专家组成。"},{"i":9,"n":"第九条","txt":"设立省级水产种质资源保护区，由市、县级人民政府渔业行政主管部门向省级人民政府渔业行政主管部门申报，经省级水产种质资源保护区评审委员会评审后，由省级人民政府渔业行政主管部门批准设立，并公布水产种质资源保护区的名称、位置、范围和主要保护对象等内容。 省级人民政府渔业行政主管部门可以根据需要直接设立省级水产种质资源保护区。"},{"i":10,"n":"第十条","txt":"符合条件的省级水产种质资源保护区，可以由省级人民政府渔业行政主管部门向农业部申报国家级水产种质资源保护区，经国家级水产种质资源保护区评审委员会评审后，由农业部批准设立，并公布水产种质资源保护区的名称、位置、范围和主要保护对象等内容。 农业部可以根据需要直接设立国家级水产种质资源保护区。"},{"i":11,"n":"第十一条","txt":"拟设立的水产种质资源保护区跨行政区域或管辖水域的，由相关区域地方人民政府渔业行政主管部门协商后共同申报，按照本办法第九条、第十条规定的程序审批。"},{"i":12,"n":"第十二条","txt":"申报设立水产种质资源保护区，应当提交以下材料： （一）申报书，主要包括保护区的主要保护对象、保护价值、区域范围、管理机构、管理基础等概况； （二）综合考察报告，主要包括保护物种资源、生态环境、社会经济状况、保护区管理条件和综合评价等； （三）保护区规划方案，包括规划目标、规划内容（含核心区、实验区）等； （四）保护区大比例尺地图等其他必要材料。"},{"i":13,"n":"第十三条","txt":"水产种质资源保护区按照下列方式命名： （一）国家级水产种质资源保护区：水产种质资源保护区所在区域名称＋保护对象名称＋“国家级水产种质资源保护区”。 （二）省级水产种质资源保护区：水产种质资源保护区所在区域名称＋保护对象名称＋“省级水产种质资源保护区”。 （三）具有多种重要保护对象或具有重要生态功能的水产种质资源保护区：水产种质资源保护区所在区域名称＋“国家级水产种质资源保护区”或者“省级水产种质资源保护区”。 （四）主要保护物种属于地方或水域特有种类的保护区：水产种质资源保护区所在区域名称＋特有鱼类名称＋“国家级水产种质资源保护区”或者“省级水产种质资源保护区”。"},{"i":14,"n":"第十四条","txt":"经批准设立的水产种质资源保护区由所在地县级以上人民政府渔业行政主管部门管理。 县级以上人民政府渔业行政主管部门应当明确水产种质资源保护区的管理机构，配备必要的管理、执法和技术人员以及相应的设备设施，负责水产种质资源保护区的管理工作。"},{"i":15,"n":"第十五条","txt":"水产种质资源保护区管理机构的主要职责包括： （一）制定水产种质资源保护区具体管理制度； （二）设置和维护水产种质资源保护区界碑、标志物及有关保护设施； （三）开展水生生物资源及其生存环境的调查监测、资源养护和生态修复等工作； （四）救护伤病、搁浅或误捕的保护物种； （五）开展水产种质资源保护的宣传教育； （六）依法开展渔政执法工作； （七）依法调查处理影响保护区功能的事件，及时向渔业行政主管部门报告重大事项。"},{"i":16,"n":"第十六条","txt":"农业部和省级人民政府渔业行政主管部门应当分别针对国家级和省级水产种质资源保护区主要保护对象的繁殖期、幼体生长期等生长繁育关键阶段设定特别保护期。 特别保护期内不得从事捕捞、爆破作业以及其他可能对保护区生物资源和生态环境造成损害的活动。特别保护期外从事捕捞活动的，应当按照《渔业法》及有关法律法规规定执行。"},{"i":17,"n":"第十七条","txt":"禁止在水产种质资源保护区内从事围湖造田、围海造地或围填海工程。"},{"i":18,"n":"第十八条","txt":"禁止在水产种质资源保护区内新建排污口。 在水产种质资源保护区附近新建、改建、扩建排污口，应当保证保护区水体不受污染。"},{"i":19,"n":"第十九条","txt":"在水产种质资源保护区内从事修建水利工程、疏浚航道、建闸筑坝、勘探和开采矿产资源、港口建设等工程建设的，或者在水产种质资源保护区外从事可能损害保护区功能的工程建设活动的，应当按照国家有关规定编制建设项目对水产种质资源保护区的影响专题论证报告，并将其纳入环境影响评价报告书。"},{"i":20,"n":"第二十条","txt":"省级以上人民政府渔业行政主管部门依法参与涉及水产种质资源保护区的建设项目环境影响评价，组织专家审查建设项目对水产种质资源保护区的影响专题论证报告，并根据审查结论向建设单位和环境影响评价主管部门出具意见。 建设单位应当将渔业行政主管部门的意见纳入环境影响评价报告书，并根据渔业行政主管部门意见采取有关保护措施。"},{"i":21,"n":"第二十一条","txt":"单位和个人在水产种质资源保护区内从事水生生物资源调查、科学研究、教学实习、参观游览、影视拍摄等活动，应当遵守有关法律法规和保护区管理制度，不得损害水产种质资源及其生存环境。"},{"i":22,"n":"第二十二条","txt":"水产种质资源保护区的撤销、调整，按照设立程序由原申报单位报原批准机关批准公布。"},{"i":23,"n":"第二十三条","txt":"单位和个人违反本办法规定，对水产种质区内的水产种质资源及其生存环境造成损害的，由县级以上渔业行政主管部门或其所属的渔政监督管理机构依照有关法律法规予以处罚。"},{"i":24,"n":"第二十四条","txt":"省级人民政府渔业行政主管部门可以根据本办法制定实施细则。"},{"i":25,"n":"第二十五条","txt":"本办法自2011年3月1日起施行。"}],"shuichanzhongzhiziyuanbaohuquguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为规范水产种质资源保护区的设立和管理，加强水产种质资源保护，根据《渔业法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称水产种质资源保护区，是指为保护水产种质资源及其生存环境，在具有较高经济价值和遗传育种价值的水产种质资源的主要生长繁育区域，依法划定并予以特殊保护和管理的水域、滩涂及其毗邻的岛礁、陆域。"},{"i":3,"n":"第三条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他水域内设立和管理水产种质资源保护区，从事涉及水产种质资源保护区的有关活动，应当遵守本办法。"},{"i":4,"n":"第四条","txt":"农业部主管全国水产种质资源保护区工作。 县级以上地方人民政府渔业行政主管部门负责辖区内水产种质资源保护区工作。"},{"i":5,"n":"第五条","txt":"农业部组织省级人民政府渔业行政主管部门制定全国水产种质资源保护区总体规划，加强水产种质资源保护区建设。 省级人民政府渔业行政主管部门应当根据全国水产种质资源保护区总体规划，科学制定本行政区域内水产种质资源保护区具体实施计划，并组织落实。 渔业行政主管部门应当积极争取各级人民政府支持，加大水产种质资源保护区建设和管理投入。"},{"i":6,"n":"第六条","txt":"对破坏、侵占水产种质资源保护区的行为，任何单位和个人都有权向渔业行政主管部门或者其所属的渔政监督管理机构、水产种质资源保护区管理机构举报。接到举报的渔业行政主管部门或机构应当依法调查处理，并将处理结果告知举报人。"},{"i":7,"n":"第七条","txt":"下列区域应当设立水产种质资源保护区： （一）国家和地方规定的重点保护水生生物物种的主要生长繁育区域； （二）我国特有或者地方特有水产种质资源的主要生长繁育区域； （三）重要水产养殖对象的原种、苗种的主要天然生长繁育区域； （四）其他具有较高经济价值和遗传育种价值的水产种质资源的主要生长繁育区域。"},{"i":8,"n":"第八条","txt":"根据保护对象资源状况、自然环境及保护需要，水产种质资源保护区可以划分为核心区和实验区。 农业部设立国家级水产种质资源保护区评审委员会，对申报的水产种质资源保护区进行评审。水产种质资源保护区评审委员会应当由渔业、环保、水利、交通、海洋、生物保护等方面的专家组成。"},{"i":9,"n":"第九条","txt":"符合条件的水产种质资源保护区，可以由省级人民政府渔业行政主管部门向农业部申报国家级水产种质资源保护区，经国家级水产种质资源保护区评审委员会评审后，由农业部批准设立，并公布水产种质资源保护区的名称、位置、范围和主要保护对象等内容。 农业部可以根据需要直接设立国家级水产种质资源保护区。"},{"i":10,"n":"第十条","txt":"拟设立的水产种质资源保护区跨行政区域或者管辖水域的，由相关区域地方人民政府渔业行政主管部门协商后共同申报或者由其共同上级渔业主管部门申报，按照本办法第九条、第十条规定的程序审批。"},{"i":11,"n":"第十一条","txt":"申报设立水产种质资源保护区，应当提交以下材料： （一）申报书，主要包括保护区的主要保护对象、保护价值、区域范围、管理机构、管理基础等； （二）综合考察报告，主要包括保护物种资源、生态环境、社会经济状况、保护区管理条件和综合评价等； （三）保护区规划方案，包括规划目标、规划内容（含核心区和实验区划分情况）等； （四）保护区大比例尺地图等其他必要材料。"},{"i":12,"n":"第十二条","txt":"水产种质资源保护区按照下列方式命名： （一）国家级水产种质资源保护区：水产种质资源保护区所在区域名称＋保护对象名称＋“国家级水产种质资源保护区”。 （二）具有多种重要保护对象或者具有重要生态功能的水产种质资源保护区：水产种质资源保护区所在区域名称＋“国家级水产种质资源保护区”。 （三）主要保护物种属于地方或水域特有种类的保护区：水产种质资源保护区所在区域名称＋“特有鱼类”＋“国家级水产种质资源保护区”。"},{"i":13,"n":"第十三条","txt":"经批准设立的水产种质资源保护区由所在地县级以上人民政府渔业行政主管部门管理。 县级以上人民政府渔业行政主管部门应当明确水产种质资源保护区的管理机构，配备必要的管理、执法和技术人员以及相应的设备设施，负责水产种质资源保护区的管理工作。"},{"i":14,"n":"第十四条","txt":"水产种质资源保护区管理机构的主要职责包括： （一）制定水产种质资源保护区具体管理制度； （二）设置和维护水产种质资源保护区界碑、标志物及有关保护设施； （三）开展水生生物资源及其生存环境的调查监测、资源养护和生态修复等工作； （四）救护伤病、搁浅、误捕的保护物种； （五）开展水产种质资源保护的宣传教育； （六）依法开展渔政执法工作； （七）依法调查处理影响保护区功能的事件，及时向渔业行政主管部门报告重大事项。"},{"i":15,"n":"第十五条","txt":"农业部应当针对国家级水产种质资源保护区主要保护对象的繁殖期、幼体生长期等生长繁育关键阶段设定特别保护期。特别保护期内不得从事捕捞、爆破作业以及其他可能对保护区内生物资源和生态环境造成损害的活动。 特别保护期外从事捕捞活动，应当遵守«渔业法»及有关法律法规的规定。"},{"i":16,"n":"第十六条","txt":"在水产种质资源保护区内从事修建水利工程、疏浚航道、建闸筑坝、勘探和开采矿产资源、港口建设等工程建设的，或者在水产种质资源保护区外从事可能损害保护区功能的工程建设活动的，应当按照国家有关规定编制建设项目对水产种质资源保护区的影响专题论证报告，并将其纳入环境影响评价报告书。"},{"i":17,"n":"第十七条","txt":"省级以上人民政府渔业行政主管部门应当依法参与涉及水产种质资源保护区的建设项目环境影响评价，组织专家审查建设项目对水产种质资源保护区的影响专题论证报告，并根据审查结论向建设单位和环境影响评价主管部门出具意见。 建设单位应当将渔业行政主管部门的意见纳入环境影响评价报告书，并根据渔业行政主管部门意见采取有关保护措施。"},{"i":18,"n":"第十八条","txt":"单位和个人在水产种质资源保护区内从事水生生物资源调查、科学研究、教学实习、参观游览、影视拍摄等活动，应当遵守有关法律法规和保护区管理制度，不得损害水产种质资源及其生存环境。"},{"i":19,"n":"第十九条","txt":"禁止在水产种质资源保护区内从事围湖造田、围海造地或围填海工程。"},{"i":20,"n":"第二十条","txt":"禁止在水产种质资源保护区内新建排污口。 在水产种质资源保护区附近新建、改建、扩建排污口，应当保证保护区水体不受污染。"},{"i":21,"n":"第二十一条","txt":"水产种质资源保护区的撤销、调整，按照设立程序办理。"},{"i":22,"n":"第二十二条","txt":"单位和个人违反本办法规定，对水产种质资源保护区内的水产种质资源及其生存环境造成损害的，由县级以上人民政府渔业行政主管部门或者其所属的渔政监督管理机构、水产种质资源保护区管理机构依法处理。"},{"i":23,"n":"第二十三条","txt":"省级人民政府渔业行政主管部门可以根据本办法制定实施细则。"},{"i":24,"n":"第二十四条","txt":"本办法自2011年3月1日起施行。"}],"shuichanmiaozhongguanlibanfa":[{"i":1,"n":"第一条","txt":"为保护和合理利用水产种质资源，加强水产品种选育和苗种生产、经营、进出口管理，提高水产苗种质量，维护水产苗种生产者、经营者和使用者的合法权益，促进水产养殖业持续健康发展，根据《中华人民共和国渔业法》及有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称的水产苗种包括用于繁育、增养殖（栽培）生产和科研试验、观赏的水产动植物的亲本、稚体、幼体、受精卵、孢子及其遗传育种材料。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内从事水产种质资源开发利用，品种选育、培育，水产苗种生产、经营、管理、进口、出口活动的单位和个人，应当遵守本办法。 珍稀、濒危水生野生动植物及其苗种的管理按有关法律法规的规定执行。"},{"i":4,"n":"第四条","txt":"农业部负责全国水产种质资源和水产苗种管理工作。 县级以上地方人民政府渔业行政主管部门负责本行政区域内的水产种质资源和水产苗种管理工作。"},{"i":5,"n":"第五条","txt":"国家有计划地搜集、整理、鉴定、保护、保存和合理利用水产种质资源。禁止任何单位和个人侵占和破坏水产种质资源。"},{"i":6,"n":"第六条","txt":"国家保护水产种质资源及其生存环境，并在具有较高经济价值和遗传育种价值的水产种质资源的主要生长繁殖区域建立水产种质资源保护区。未经农业部批准，任何单位或者个人不得在水产种质资源保护区从事捕捞活动。 建设项目对水产种质资源产生不利影响的，依照《中华人民共和国渔业法》第三十五条的规定处理。"},{"i":7,"n":"第七条","txt":"省级以上人民政府渔业行政主管部门根据水产增养殖生产发展的需要和自然条件及种质资源特点，合理布局和建设水产原、良种场。 国家级或省级原、良种场负责保存或选育种用遗传材料和亲本，向水产苗种繁育单位提供亲本。"},{"i":8,"n":"第八条","txt":"用于杂交生产商品苗种的亲本必须是纯系群体。对可育的杂交种不得用作亲本繁育。 养殖可育的杂交个体和通过生物工程等技术改变遗传性状的个体及后代，其场所必须建立严格的隔离和防逃措施，禁止将其投放于河流、湖泊、水库、海域等自然水域。"},{"i":9,"n":"第九条","txt":"国家鼓励和支持水产优良品种的选育、培育和推广。县级以上人民政府渔业行政主管部门应当有计划地组织科研、教学和生产单位选育、培育水产优良新品种。"},{"i":10,"n":"第十条","txt":"农业部设立全国水产原种和良种审定委员会，对水产新品种进行审定。对审定合格的水产新品种，经农业部公告后方可推广。"},{"i":11,"n":"第十一条","txt":"单位和个人从事水产苗种生产，应当经县级以上地方人民政府渔业行政主管部门批准，取得水产苗种生产许可证。但是，渔业生产者自育、自用水产苗种的除外。 省级人民政府渔业行政主管部门负责水产原、良种场的水产苗种生产许可证的核发工作；其他水产苗种生产许可证发放权限由省级人民政府渔业行政主管部门规定。 水产苗种生产许可证由省级人民政府渔业行政主管部门统一印制。"},{"i":12,"n":"第十二条","txt":"从事水产苗种生产的单位和个人应当具备下列条件： （一）有固定的生产场地，水源充足，水质符合渔业用水标准； （二）用于繁殖的亲本来源于原、良种场，质量符合种质标准； （三）生产条件和设施符合水产苗种生产技术操作规程的要求； （四）有与水产苗种生产和质量检验相适应的专业技术人员。 申请单位是水产原、良种场的，还应当符合农业部《水产原良种场生产管理规范》的要求。"},{"i":13,"n":"第十三条","txt":"申请从事水产苗种生产的单位和个人应当填写水产苗种生产申请表，并提交证明其符合本办法第十二条规定条件的材料。 水产苗种生产申请表格式由省级人民政府渔业行政主管部门统一制订。"},{"i":14,"n":"第十四条","txt":"县级以上地方人民政府渔业行政主管部门应当按照本办法第十一条第二款规定的审批权限，自受理申请之日起20日内对申请人提交的材料进行审查，并经现场考核后作出是否发放水产苗种生产许可证的决定。"},{"i":15,"n":"第十五条","txt":"水产苗种生产单位和个人应当按照许可证规定的范围、种类等进行生产。需要变更生产范围、种类的，应当向原发证机关办理变更手续。 水产苗种生产许可证的许可有效期限为三年。期满需延期的，应当于期满三十日前向原发证机关提出申请，办理续展手续。"},{"i":16,"n":"第十六条","txt":"水产苗种的生产应当遵守农业部制定的生产技术操作规程，保证苗种质量。"},{"i":17,"n":"第十七条","txt":"县级以上人民政府渔业行政主管部门应当组织有关质量检验机构对辖区内苗种场的亲本和稚、幼体质量进行检验，检验不合格的，给予警告，限期整改；到期仍不合格的，由发证机关收回并注销水产苗种生产许可证。"},{"i":18,"n":"第十八条","txt":"县级以上地方人民政府渔业行政主管部门应当加强对水产苗种的产地检疫。 国内异地引进水产苗种的，应当先到当地渔业行政主管部门办理检疫手续，经检疫合格后方可运输和销售。 检疫人员应当按照检疫规程实施检疫，对检疫合格的水产苗种出具检疫合格证明。"},{"i":19,"n":"第十九条","txt":"禁止在水产苗种繁殖、栖息地从事采矿、挖沙、爆破、排放污水等破坏水域生态环境的活动。对水域环境造成污染的，依照《中华人民共和国水污染防治法》和《中华人民共和国海洋环境保护法》的有关规定处理。 在水生动物苗种主产区引水时，应当采取措施，保护苗种。"},{"i":20,"n":"第二十条","txt":"单位和个人从事水产苗种进口和出口，应当经农业部或省级人民政府渔业行政主管部门批准。"},{"i":21,"n":"第二十一条","txt":"农业部会同国务院有关部门制定水产苗种进口名录和出口名录，并定期公布。 水产苗种进口名录和出口名录分为Ⅰ、Ⅱ、Ⅲ类。列入进口名录Ⅰ类的水产苗种不得进口，列入出口名录Ⅰ类的水产苗种不得出口；列入名录Ⅱ类的水产苗种以及未列入名录的水产苗种的进口、出口由农业部审批，列入名录Ⅲ类的水产苗种的进口、出口由省级人民政府渔业行政主管部门审批。"},{"i":22,"n":"第二十二条","txt":"申请进口水产苗种的单位和个人应当提交以下材料： （一）水产苗种进口申请表； （二）水产苗种进口安全影响报告（包括对引进地区水域生态环境、生物种类的影响，进口水产苗种可能携带的病虫害及危害性等）； （三）与境外签订的意向书、赠送协议书复印件； （四）进口水产苗种所在国（地区）主管部门出具的产地证明； （五）营业执照复印件。"},{"i":23,"n":"第二十三条","txt":"进口未列入水产苗种进口名录的水产苗种的单位应当具备以下条件： （一）具有完整的防逃、隔离设施，试验池面积不少于3公顷； （二）具备一定的科研力量，具有从事种质、疾病及生态研究的中高级技术人员； （三）具备开展种质检测、疫病检疫以及水质检测工作的基本仪器设备。 进口未列入水产苗种进口名录的水产苗种的单位，除按第二十二条的规定提供材料外，还应当提供以下材料： （一）进口水产苗种所在国家或地区的相关资料：包括进口水产苗种的分类地位、生物学性状、遗传特性、经济性状及开发利用现状，栖息水域及该地区的气候特点、水域生态条件等； （二）进口水产苗种人工繁殖、养殖情况； （三）进口国家或地区水产苗种疫病发生情况。"},{"i":24,"n":"第二十四条","txt":"申请出口水产苗种的单位和个人应提交水产苗种出口申请表。"},{"i":25,"n":"第二十五条","txt":"进出口水产苗种的单位和个人应当向省级人民政府渔业行政主管部门提出申请。省级人民政府渔业行政主管部门应当自申请受理之日起15日内对进出口水产苗种的申报材料进行审查核实，按审批权限直接审批或初步审查后将审查意见和全部材料报农业部审批。 省级人民政府渔业行政主管部门应当将其审批的水产苗种进出口情况，在每年年底前报农业部备案。"},{"i":26,"n":"第二十六条","txt":"农业部收到省级人民政府渔业行政主管部门报送的材料后，对申请进口水产苗种的，在5日内委托全国水产原种和良种审定委员会组织专家对申请进口的水产苗种进行安全影响评估，并在收到安全影响评估报告后15日内作出是否同意进口的决定；对申请出口水产苗种的，应当在10日内作出是否同意出口的决定。"},{"i":27,"n":"第二十七条","txt":"申请水产苗种进出口的单位或个人应当凭农业部或省级人民政府渔业行政主管部门批准的水产苗种进出口审批表办理进出口手续。 水产苗种进出口申请表、审批表格式由农业部统一制定。"},{"i":28,"n":"第二十八条","txt":"进口、出口水产苗种应当实施检疫，防止病害传入境内和传出境外，具体检疫工作按照《中华人民共和国进出境动植物检疫法》等法律法规的规定执行。"},{"i":29,"n":"第二十九条","txt":"水产苗种进口实行属地监管。 进口单位和个人在进口水产苗种经出入境检验检疫机构检疫合格后，应当立即向所在地省级人民政府渔业行政主管部门报告，由所在地省级人民政府渔业行政主管部门或其委托的县级以上地方人民政府渔业行政主管部门具体负责入境后的监督检查。"},{"i":30,"n":"第三十条","txt":"进口未列入水产苗种进口名录的水产苗种的，进口单位和个人应当在该水产苗种经出入境检验检疫机构检疫合格后，设置专门场所进行试养，特殊情况下应在农业部指定的场所进行。 试养期间一般为进口水产苗种的一个繁殖周期。试养期间，农业部不再批准该水产苗种的进口，进口单位不得向试养场所外扩散该试养苗种。 试养期满后的水产苗种应当经过全国水产原种和良种审定委员会审定、农业部公告后方可推广。"},{"i":31,"n":"第三十一条","txt":"进口水产苗种投放于河流、湖泊、水库、海域等自然水域要严格遵守有关外来物种管理规定。"},{"i":32,"n":"第三十二条","txt":"本办法所用术语的含义： （一）原种：指取自模式种采集水域或取自其他天然水域的野生水生动植物种，以及用于选育的原始亲体。 （二）良种：指生长快、品质好、抗逆性强、性状稳定和适应一定地区自然条件，并适用于增养殖（栽培）生产的水产动植物种。 （三）杂交种：指将不同种、亚种、品种的水产动植物进行杂交获得的后代。 （四）品种：指经人工选育成的，遗传性状稳定，并具有不同于原种或同种内其他群体的优良经济性状的水生动植物。 （五）稚、幼体：指从孵出后至性成熟之前这一阶段的个体。 （六）亲本：指已达性成熟年龄的个体。"},{"i":33,"n":"第三十三条","txt":"违反本办法的规定应当给予处罚的，依照《中华人民共和国渔业法》等法律法规的有关规定给予处罚。"},{"i":34,"n":"第三十四条","txt":"转基因水产苗种的选育、培育、生产、经营和进出口管理，应当同时遵守《农业转基因生物安全管理条例》及国家其他有关规定。"},{"i":35,"n":"第三十五条","txt":"本办法自2005年4月1日起施行。"}],"shuiyutantuyangzhifazhengdengjibanfa":[{"i":1,"n":"第一条","txt":"为了保障养殖生产者合法权益，规范水域、滩涂养殖发证登记工作，根据《中华人民共和国物权法》、《中华人民共和国渔业法》、《中华人民共和国农村土地承包法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称水域、滩涂，是指经县级以上地方人民政府依法规划或者以其他形式确定可以用于水产养殖业的水域、滩涂。 本办法所称水域滩涂养殖权，是指依法取得的使用水域、滩涂从事水产养殖的权利。"},{"i":3,"n":"第三条","txt":"使用水域、滩涂从事养殖生产，由县级以上地方人民政府核发养殖证，确认水域滩涂养殖权。 县级以上地方人民政府渔业行政主管部门负责水域、滩涂养殖发证登记具体工作，并建立登记簿，记载养殖证载明的事项。"},{"i":4,"n":"第四条","txt":"水域滩涂养殖权人可以凭养殖证享受国家水产养殖扶持政策。"},{"i":5,"n":"第五条","txt":"使用国家所有的水域、滩涂从事养殖生产的，应当向县级以上地方人民政府渔业行政主管部门提出申请，并提交以下材料： （一）养殖证申请表； （二）公民个人身份证明、法人或其他组织资格证明、法定代表人或者主要负责人的身份证明； （三）依法应当提交的其他证明材料。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府渔业行政主管部门应当在受理后15个工作日内对申请材料进行书面审查和实地核查。符合规定的，应当将申请在水域、滩涂所在地进行公示，公示期为10日；不符合规定的，书面通知申请人。"},{"i":7,"n":"第七条","txt":"公示期满后，符合下列条件的，县级以上地方人民政府渔业行政主管部门应当报请同级人民政府核发养殖证，并将养殖证载明事项载入登记簿： （一）水域、滩涂依法可以用于养殖生产； （二）证明材料合法有效； （三）无权属争议。 登记簿应当准确记载养殖证载明的全部事项。"},{"i":8,"n":"第八条","txt":"国家所有的水域、滩涂，应当优先用于下列当地渔业生产者从事养殖生产： （一）以水域、滩涂养殖生产为主要生活来源的； （二）因渔业产业结构调整，由捕捞业转产从事养殖业的； （三）因养殖水域滩涂规划调整，需要另行安排养殖水域、滩涂从事养殖生产的。"},{"i":9,"n":"第九条","txt":"依法转让国家所有水域、滩涂的养殖权的，应当持原养殖证，依照本章规定重新办理发证登记。"},{"i":10,"n":"第十条","txt":"农民集体所有或者国家所有依法由农民集体使用的水域、滩涂，以家庭承包方式用于养殖生产的，依照下列程序办理发证登记： （一）水域、滩涂承包合同生效后，发包方应当在30个工作日内，将水域、滩涂承包方案、承包方及承包水域、滩涂的详细情况、水域、滩涂承包合同等材料报县级以上地方人民政府渔业行政主管部门； （二）县级以上地方人民政府渔业行政主管部门对发包方报送的材料进行审核。符合规定的，报请同级人民政府核发养殖证，并将养殖证载明事项载入登记簿；不符合规定的，书面通知当事人。"},{"i":11,"n":"第十一条","txt":"农民集体所有或者国家所有依法由农民集体使用的水域、滩涂，以招标、拍卖、公开协商等方式承包用于养殖生产，承包方申请取得养殖证的，依照下列程序办理发证登记： （一）水域、滩涂承包合同生效后，承包方填写养殖证申请表，并将水域、滩涂承包合同等材料报县级以上地方人民政府渔业行政主管部门； （二）县级以上地方人民政府渔业行政主管部门对承包方提交的材料进行审核。符合规定的，报请同级人民政府核发养殖证，并将养殖证载明事项载入登记簿；不符合规定的，书面通知申请人。"},{"i":12,"n":"第十二条","txt":"县级以上地方人民政府渔业行政主管部门应当在登记簿上准确记载养殖证载明的全部事项。"},{"i":13,"n":"第十三条","txt":"农民集体所有或者国家所有依法由农民集体使用的水域、滩涂，以家庭承包方式用于养殖生产，在承包期内采取转包、出租、入股方式流转水域滩涂养殖权的，不需要重新办理发证登记。 采取转让、互换方式流转水域滩涂养殖权的，当事人可以要求重新办理发证登记。申请重新办理发证登记的，应当提交原养殖证和水域滩涂养殖权流转合同等相关证明材料。 因转让、互换以外的其他方式导致水域滩涂养殖权分立、合并的，应当持原养殖证及相关证明材料，向原发证登记机关重新办理发证登记。"},{"i":14,"n":"第十四条","txt":"水域滩涂养殖权人、利害关系人有权查阅、复制登记簿，县级以上地方人民政府渔业行政主管部门应当提供，不得限制和拒绝。 水域滩涂养殖权人、利害关系人认为登记簿记载的事项错误的，可以申请更正登记。登记簿记载的权利人书面同意更正或者有证据证明登记确有错误的，县级以上地方人民政府渔业行政主管部门应当予以更正。"},{"i":15,"n":"第十五条","txt":"养殖权人姓名或名称、住所等事项发生变化的，当事人应当持原养殖证及相关证明材料，向原发证登记机关申请变更。"},{"i":16,"n":"第十六条","txt":"因被依法收回、征收等原因造成水域滩涂养殖权灭失的，应当由发证机关依法收回、注销养殖证。 实行家庭承包的农民集体所有或者国家所有依法由农民集体使用的水域、滩涂，在承包期内出现下列情形之一，发包方依法收回承包的水域、滩涂的，应当由发证机关收回、注销养殖证： （一）承包方全家迁入设区的市，转为非农业户口的； （二）承包方提出书面申请，自愿放弃全部承包水域、滩涂的； （三）其他依法应当收回养殖证的情形。"},{"i":17,"n":"第十七条","txt":"符合本办法第十六条规定，水域滩涂养殖权人拒绝交回养殖证的，县级以上地方人民政府渔业行政主管部门调查核实后，报请发证机关依法注销养殖证，并予以公告。"},{"i":18,"n":"第十八条","txt":"水域滩涂养殖权期限届满，水域滩涂养殖权人依法继续使用国家所有的水域、滩涂从事养殖生产的，应当在期限届满60日前，持养殖证向原发证登记机关办理延展手续，并按本办法第五条规定提交相关材料。 因养殖水域滩涂规划调整不得从事养殖的，期限届满后不再办理延展手续。"},{"i":19,"n":"第十九条","txt":"养殖证由农业部监制，省级人民政府渔业行政主管部门印制。"},{"i":20,"n":"第二十条","txt":"颁发养殖证，除依法收取工本费外，不得向水域、滩涂使用人收取任何费用。"},{"i":21,"n":"第二十一条","txt":"本办法施行前养殖水域、滩涂已核发养殖证或者农村土地承包经营权证的，在有效期内继续有效。"},{"i":22,"n":"第二十二条","txt":"本办法自2010年7月1日起施行。"}],"shuishengshengwuzengzhifangliuguanliguiding":[{"i":1,"n":"第一条","txt":"为规范水生生物增殖放流活动，科学养护水生生物资源，维护生物多样性和水域生态安全，促进渔业可持续健康发展，根据《中华人民共和国渔业法》、《中华人民共和国野生动物保护法》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称水生生物增殖放流，是指采用放流、底播、移植等人工方式向海洋、江河、湖泊、水库等公共水域投放亲体、苗种等活体水生生物的活动。"},{"i":3,"n":"第三条","txt":"在中华人民共和国管辖水域内进行水生生物增殖放流活动，应当遵守本规定。"},{"i":4,"n":"第四条","txt":"农业部主管全国水生生物增殖放流工作。 县级以上地方人民政府渔业行政主管部门负责本行政区域内水生生物增殖放流的组织、协调与监督管理。"},{"i":5,"n":"第五条","txt":"各级渔业行政主管部门应当加大对水生生物增殖放流的投入，积极引导、鼓励社会资金支持水生生物资源养护和增殖放流事业。 水生生物增殖放流专项资金应专款专用，并遵守有关管理规定。渔业行政主管部门使用社会资金用于增殖放流的，应当向社会、出资人公开资金使用情况。"},{"i":6,"n":"第六条","txt":"县级以上人民政府渔业行政主管部门应当积极开展水生生物资源养护与增殖放流的宣传教育，提高公民养护水生生物资源、保护生态环境的意识。"},{"i":7,"n":"第七条","txt":"县级以上人民政府渔业行政主管部门应当鼓励单位、个人及社会各界通过认购放流苗种、捐助资金、参加志愿者活动等多种途径和方式参与、开展水生生物增殖放流活动。对于贡献突出的单位和个人，应当采取适当方式给予宣传和鼓励。"},{"i":8,"n":"第八条","txt":"县级以上地方人民政府渔业行政主管部门应当制定本行政区域内的水生生物增殖放流规划，并报上一级渔业行政主管部门备案。"},{"i":9,"n":"第九条","txt":"用于增殖放流的人工繁殖的水生生物物种，应当来自有资质的生产单位。其中，属于经济物种的，应当来自持有《水产苗种生产许可证》的苗种生产单位；属于珍稀、濒危物种的，应当来自持有《水生野生动物驯养繁殖许可证》的苗种生产单位。 渔业行政主管部门应当按照“公开、公平、公正”的原则，依法通过招标或者议标的方式采购用于放流的水生生物或者确定苗种生产单位。"},{"i":10,"n":"第十条","txt":"用于增殖放流的亲体、苗种等水生生物应当是本地种。苗种应当是本地种的原种或者子一代，确需放流其他苗种的，应当通过省级以上渔业行政主管部门组织的专家论证。 禁止使用外来种、杂交种、转基因种以及其他不符合生态要求的水生生物物种进行增殖放流。"},{"i":11,"n":"第十一条","txt":"用于增殖放流的水生生物应当依法经检验检疫合格，确保健康无病害、无禁用药物残留。"},{"i":12,"n":"第十二条","txt":"渔业行政主管部门组织开展增殖放流活动，应当公开进行，邀请渔民、有关科研单位和社会团体等方面的代表参加，并接受社会监督。 增殖放流的水生生物的种类、数量、规格等，应当向社会公示。"},{"i":13,"n":"第十三条","txt":"单位和个人自行开展规模性水生生物增殖放流活动的，应当提前15日向当地县级以上地方人民政府渔业行政主管部门报告增殖放流的种类、数量、规格、时间和地点等事项，接受监督检查。 经审查符合本规定的增殖放流活动，县级以上地方人民政府渔业行政主管部门应当给予必要的支持和协助。 应当报告并接受监督检查的增殖放流活动的规模标准，由县级以上地方人民政府渔业行政主管部门根据本地区水生生物增殖放流规划确定。"},{"i":14,"n":"第十四条","txt":"增殖放流应当遵守省级以上人民政府渔业行政主管部门制定的水生生物增殖放流技术规范，采取适当的放流方式，防止或者减轻对放流水生生物的损害。"},{"i":15,"n":"第十五条","txt":"渔业行政主管部门应当在增殖放流水域采取划定禁渔区、确定禁渔期等保护措施，加强增殖资源保护，确保增殖放流效果。"},{"i":16,"n":"第十六条","txt":"渔业行政主管部门应当组织开展有关增殖放流的科研攻关和技术指导，并采取标志放流、跟踪监测和社会调查等措施对增殖放流效果进行评价。"},{"i":17,"n":"第十七条","txt":"县级以上地方人民政府渔业行政主管部门应当将辖区内本年度水生生物增殖放流的种类、数量、规格、时间、地点、标志放流的数量及方法、资金来源及数量、放流活动等情况统计汇总，于11月底以前报上一级渔业行政主管部门备案。"},{"i":18,"n":"第十八条","txt":"违反本规定的，依照《中华人民共和国渔业法》、《中华人民共和国野生动物保护法》等有关法律法规的规定处罚。"},{"i":19,"n":"第十九条","txt":"本规定自2009年5月1日起施行。"}],"shuishengyeshengdongwujiqizhipinjiazhipinggubanfa-2":[{"i":1,"n":"第一条","txt":"为了规范水生野生动物及其制品的价值评估方法和标准，根据《中华人民共和国野生动物保护法》规定，制定本办法。"},{"i":2,"n":"第二条","txt":"《中华人民共和国野生动物保护法》规定保护的珍贵濒危水生野生动物及其制品价值的评估，适用本办法。 本办法规定的水生野生动物，是指国家重点保护水生野生动物及《濒危野生动植物种国际贸易公约》附录水生物种的整体（含卵）。 本办法规定的水生野生动物制品，是指水生野生动物的部分及其衍生物。"},{"i":3,"n":"第三条","txt":"水生野生动物成年整体的价值，按照对应物种的基准价值乘以保护级别系数计算。 农业农村部负责制定、公布并调整《水生野生动物基准价值标准目录》。"},{"i":4,"n":"第四条","txt":"国家一级重点保护水生野生动物的保护级别系数为10。国家二级重点保护水生野生动物的保护级别系数为5。 《濒危野生动植物种国际贸易公约》附录所列水生物种，已被农业农村部核准为国家重点保护野生动物的，按照对应保护级别系数核算价值；未被农业农村部核准为国家重点保护野生动物的，保护级别系数为1。"},{"i":5,"n":"第五条","txt":"水生野生动物幼年整体的价值，按照该物种成年整体价值乘以发育阶段系数计算。 发育阶段系数不应超过1，由核算其价值的执法机关或者评估机构综合考虑该物种繁殖力、成活率、发育阶段等实际情况确定。"},{"i":6,"n":"第六条","txt":"水生野生动物卵的价值，有单独基准价值的，按照其基准价值乘以保护级别系数计算；没有单独基准价值的，按照该物种成年整体价值乘以繁殖力系数计算。 爬行类野生动物卵的繁殖力系数为十分之一；两栖类野生动物卵的繁殖力系数为千分之一；无脊椎、鱼类野生动物卵的繁殖力系数综合考虑该物种繁殖力、成活率进行确定。"},{"i":7,"n":"第七条","txt":"水生野生动物制品的价值，按照该物种整体价值乘以涉案部分系数计算。 涉案部分系数不应超过1；系该物种主要利用部分的，涉案部分系数不应低于0.7。具体由核算其价值的执法机关或者评估机构综合考虑该制品利用部分、对动物伤害程度等因素确定。"},{"i":8,"n":"第八条","txt":"人工繁育的水生野生动物及其制品的价值，根据本办法第四至七条规定计算后的价值乘以物种来源系数计算。 列入人工繁育国家重点保护水生野生动物名录物种的人工繁育个体及其制品，物种来源系数为0.25；其它物种的人工繁育个体及其制品，物种来源系数为0.5。"},{"i":9,"n":"第九条","txt":"水生野生动物及其制品有实际交易价格，且实际交易价格高于按照本办法评估价值的，按照实际交易价格执行。"},{"i":10,"n":"第十条","txt":"本办法施行后，新列入《国家重点保护野生动物名录》或《濒危野生动植物种国际贸易公约》附录，但尚未列入《水生野生动物基准价值标准目录》的水生野生动物，其基准价值参照与其同属、同科或同目的最近似水生野生动物的基准价值核算。"},{"i":11,"n":"第十一条","txt":"未被列入《濒危野生动植物种国际贸易公约》附录的地方重点保护水生野生动物，可参照本办法计算价值，保护级别系数可按1计算。"},{"i":12,"n":"第十二条","txt":"本办法自2019年10月1日起施行。 附表：水生野生动物基准价值标准目录"}],"shuishengyeshengdongwujiqizhipinjiazhipinggubanfa":[{"i":1,"n":"第一条","txt":"为了规范水生野生动物及其制品的价值评估方法和标准，根据《中华人民共和国野生动物保护法》规定，制定本办法。"},{"i":2,"n":"第二条","txt":"《中华人民共和国野生动物保护法》规定保护的珍贵濒危水生野生动物及其制品价值的评估，适用本办法。本办法规定的水生野生动物，是指国家重点保护水生野生动物及《濒危野生动植物种国际贸易公约》附录水生物种的整体（含卵）。 本办法规定的水生野生动物制品，是指水生野生动物的部分及其衍生物。"},{"i":3,"n":"第三条","txt":"水生野生动物成年整体的价值，按照对应物种的基准价值乘以保护级别系数计算。农业农村部负责制定、公布并调整《水生野生动物基准价值标准目录》。"},{"i":4,"n":"第四条","txt":"国家一级重点保护水生野生动物的保护级别系数为10。国家二级重点保护水生野生动物的保护级别系数为5。 《濒危野生动植物种国际贸易公约》附录所列水生物种，已被农业农村部核准为国家重点保护野生动物的，按照对应保护级别系数核算价值；未被农业农村部核准为国家重点保护野生动物的，保护级别系数为1。"},{"i":5,"n":"第五条","txt":"水生野生动物幼年整体的价值，按照该物种成年整体价值乘以发育阶段系数计算。 发育阶段系数不应超过1，由核算其价值的执法机关或者评估机构综合考虑该物种繁殖力、成活率、发育阶段等实际情况确定。"},{"i":6,"n":"第六条","txt":"水生野生动物卵的价值，有单独基准价值的，按照其基准价值乘以保护级别系数计算；没有单独基准价值的，按照该物种成年整体价值乘以繁殖力系数计算。 爬行类野生动物卵的繁殖力系数为十分之一；两栖类野生动物卵的繁殖力系数为千分之一；无脊椎、鱼类野生动物卵的繁殖力系数综合考虑该物种繁殖力、成活率进行确定。"},{"i":7,"n":"第七条","txt":"水生野生动物制品的价值，按照该物种整体价值乘以涉案部分系数计算。 涉案部分系数不应超过1；系该物种主要利用部分的，涉案部分系数不应低于0.7。具体由核算其价值的执法机关或者评估机构综合考虑该制品利用部分、对动物伤害程度等因素确定。"},{"i":8,"n":"第八条","txt":"人工繁育的水生野生动物及其制品的价值，根据本办法第三至七条规定计算后的价值乘以物种来源系数计算。 列入人工繁育国家重点保护水生野生动物名录物种的人工繁育个体及其制品，物种来源系数为0.25；其它物种的人工繁育个体及其制品，物种来源系数为0.5。"},{"i":9,"n":"第九条","txt":"水生野生动物及其制品有实际交易价格，且实际交易价格高于按照本方法评估价值的，按照实际交易价格执行。"},{"i":10,"n":"第十条","txt":"本办法施行后，新列入《国家重点保护野生动物名录》或《濒危野生动植物种国际贸易公约》附录，但尚未列入《水生野生动物基准价值标准目录》的水生野生动物，其基准价值参照与其同属、同科或同目的最近似水生野生动物的基准价值核算。"},{"i":11,"n":"第十一条","txt":"未被列入《濒危野生动植物种国际贸易公约》附录的地方重点保护水生野生动物，可参照本办法计算价值，保护级别系数可按1计算。"},{"i":12,"n":"第十二条","txt":"本办法自2019年10月1日起施行。 附表 　　 　　水生野生动物基准价值标准名录 物种名称 　　学名 　　单位 　　基准价值（元） 　　脊索动物门 Chordata 　　哺乳纲 Mammalia 　　食肉目 Carnivora 　　鼬科 Mustelidae 　　水獭亚科 Lutrinae 　　小爪水獭 　　Aonyx cinerea 　　只 　　2000 　　水獭亚科其他种 　　只 　　1800 　　鳍足类 Pinnipedia 　　海象科 Odobenidae 　　海象 　　Odobenus rosmarus 　　头 　　3000 　　海狗科 Otariidae 　　毛皮海狮属所有种 　　Arctocephalus spp. 　　头 　　8000 　　海豹科 Phocidae 　　斑海豹 　　Phoca largha 　　头 　　10000 　　僧海豹属所有种 　　Monachu"}],"yuyebulaoxukeguanliguiding-2":[{"i":1,"n":"第一条","txt":"为了保护、合理利用渔业资源，控制捕捞强度，维护渔业生产秩序，保障渔业生产者的合法权益，根据《中华人民共和国渔业法》，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国的公民、法人和其他组织从事渔业捕捞活动，以及外国人、外国渔业船舶在中华人民共和国领域及管辖的其他水域从事渔业捕捞活动，应当遵守本规定。 中华人民共和国缔结的条约、协定另有规定的，按条约、协定执行。"},{"i":3,"n":"第三条","txt":"国家对捕捞业实行船网工具控制指标管理，实行捕捞许可证制度和捕捞限额制度。 国家根据渔业资源变化与环境状况，确定船网工具控制指标，控制捕捞能力总量和渔业捕捞许可证数量。渔业捕捞许可证的批准发放，应当遵循公开、公平、公正原则，数量不得超过船网工具控制指标范围。"},{"i":4,"n":"第四条","txt":"渔业捕捞许可证、船网工具指标等证书文件的审批实行签发人负责制，相关证书文件经签发人签字并加盖公章后方为有效。 签发人对其审批签发证书文件的真实性及合法性负责。"},{"i":5,"n":"第五条","txt":"农业农村部主管全国渔业捕捞许可管理和捕捞能力总量控制工作。 县级以上地方人民政府渔业主管部门及其所属的渔政监督管理机构负责本行政区域内的渔业捕捞许可管理和捕捞能力总量控制的组织、实施工作。"},{"i":6,"n":"第六条","txt":"县级以上人民政府渔业主管部门应当在其办公场所和网上办理平台，公布船网工具指标、渔业捕捞许可证审批的条件、程序、期限以及需要提交的全部材料目录和申请书示范文本等事项。 县级以上人民政府渔业主管部门应当按照本规定自受理船网工具指标或渔业捕捞许可证申请之日起20个工作日内审查完毕或者作出是否批准的决定。不予受理申请或者不予批准的，应当书面通知申请人并说明理由。"},{"i":7,"n":"第七条","txt":"县级以上人民政府渔业主管部门应当加强渔船和捕捞许可管理信息系统建设，建立健全渔船动态管理数据库。海洋渔船船网工具指标和捕捞许可证的申请、审核审批及制发证书文件等应当通过全国统一的渔船动态管理系统进行。 申请人应当提供的户口簿、营业执照、渔业船舶检验证书、渔业船舶登记证等法定证照、权属证明在全国渔船动态管理系统或者部门间核查能够查询到有效信息的，可以不再提供纸质材料。"},{"i":8,"n":"第八条","txt":"海洋渔船按船长分为以下三类： （一）海洋大型渔船：船长大于或者等于24米； （二）海洋中型渔船：船长大于或者等于12米且小于24米； （三）海洋小型渔船：船长小于12米。 内陆渔船的分类标准由各省、自治区、直辖市人民政府渔业主管部门制定。"},{"i":9,"n":"第九条","txt":"国内海洋大中型捕捞渔船的船网工具控制指标由农业农村部确定并报国务院批准后，向有关省、自治区、直辖市下达。国内海洋小型捕捞渔船的船网工具控制指标由省、自治区、直辖市人民政府依据其渔业资源与环境承载能力、资源利用状况、渔民传统作业情况等确定，报农业农村部批准后下达。 县级以上地方人民政府渔业主管部门应当控制本行政区域内海洋捕捞渔船的数量、功率，不得超过国家或省、自治区、直辖市人民政府下达的船网工具控制指标，具体办法由省、自治区、直辖市人民政府规定。 内陆水域捕捞业的船网工具控制指标和管理，按照省、自治区、直辖市人民政府的规定执行。"},{"i":10,"n":"第十条","txt":"制造、更新改造、购置、进口海洋捕捞渔船，应当经有审批权的人民政府渔业主管部门在国家或者省、自治区、直辖市下达的船网工具控制指标内批准，并取得渔业船网工具指标批准书。"},{"i":11,"n":"第十一条","txt":"申请海洋捕捞渔船船网工具指标，应当向户籍所在地、法人或非法人组织登记地县级以上人民政府渔业主管部门提出，提交渔业船网工具指标申请书、申请人户口簿或者营业执照，以及申请人所属渔业组织出具的意见，并按以下情况提供资料： （一）制造海洋捕捞渔船的，提供经确认符合船机桨匹配要求的渔船建造设计图纸。 国内海洋捕捞渔船淘汰后申请制造渔船的，还应当提供渔船拆解所在地县级以上地方人民政府渔业主管部门与渔船定点拆解厂（点）共同出具的渔业船舶拆解、销毁或处理证明和现场监督管理的影像资料，以及原发证机关出具的渔业船舶证书注销证明。 国内海洋捕捞渔船因海损事故造成渔船灭失后申请制造渔船的，还应当提供船籍港登记机关出具的灭失证明和原发证机关出具的渔业船舶证书注销证明。 （二）购置海洋捕捞渔船的提供： 1.被购置渔船的渔业船舶检验证书、渔业船舶国籍证书和所有权登记证书； 2.被购置渔船的渔业捕捞许可证注销证明；"},{"i":12,"n":"第十二条","txt":"下列海洋捕捞渔船的船网工具指标，向省级人民政府渔业主管部门申请。省级人民政府渔业主管部门应当按照规定进行审查，并将审查意见和申请人的全部申请材料报农业农村部审批： （一）远洋渔船； （二）因特殊需要，超过国家下达的省、自治区、直辖市渔业船网工具控制指标的渔船； （三）其他依法应由农业农村部审批的渔船。"},{"i":13,"n":"第十三条","txt":"除第十二条规定情况外，制造或者更新改造国内海洋大中型捕捞渔船的船网工具指标，由省级人民政府渔业主管部门审批。 跨省、自治区、直辖市购置国内海洋捕捞渔船的，由买入地省级人民政府渔业主管部门审批。 其他国内渔船的船网工具指标的申请、审批，由省、自治区、直辖市人民政府规定。"},{"i":14,"n":"第十四条","txt":"制造、更新改造国内海洋捕捞渔船的，应当在本省、自治区、直辖市渔业船网工具控制指标范围内，通过淘汰旧捕捞渔船解决，船数和功率数应当分别不超过淘汰渔船的船数和功率数。国内海洋大中型捕捞渔船和小型捕捞渔船的船网工具指标不得相互转换。 购置国内海洋捕捞渔船的船网工具指标随船转移。国内海洋大中型捕捞渔船不得跨海区买卖，国内海洋小型和内陆捕捞渔船不得跨省、自治区、直辖市买卖。 国内现有海洋捕捞渔船经审批转为远洋捕捞作业的，其船网工具指标予以保留。因渔船发生重大改造，导致渔船主尺度、主机功率和作业类型发生变更的除外。 专业远洋渔船不计入省、自治区、直辖市的船网工具控制指标，由农业农村部统一管理，不得在我国管辖水域作业。"},{"i":15,"n":"第十五条","txt":"渔船灭失、拆解、销毁的，原船舶所有人可自渔船灭失、拆解、销毁之日起12个月内，按本规定申请办理渔船制造或更新改造手续；逾期未申请的，视为自行放弃，由渔业主管部门收回船网工具指标。渔船灭失依法需要调查处理的，调查处理所需时间不计算在此规定期限内。"},{"i":16,"n":"第十六条","txt":"申请人应当凭渔业船网工具指标批准书办理渔船制造、更新改造、购置或进口手续，并申请渔船检验、登记，办理渔业捕捞许可证。审批机关应当同时在渔业船网工具指标批准书上记载办理情况。 制造、更新改造、进口渔船的渔业船网工具指标批准书的有效期为18个月，购置渔船的渔业船网工具指标批准书的有效期为6个月。因特殊原因在规定期限内无法办理完毕相关手续的，可在有效期届满前3个月内申请有效期延展一次，延展期不得超过原船网工具指标批准书核准的有效期。 船网工具指标批准书有效期届满未依法延续的，审批机关应当予以注销并收回船网工具指标。"},{"i":17,"n":"第十七条","txt":"渔业船网工具指标批准书在有效期内遗失或者灭失的，船舶所有人应当在1个月内向原审批机关说明遗失或者灭失的时间、地点和原因等情况，由原审批机关在其官方网站上发布声明，自公告声明发布之日起15日后，船舶所有人可向原审批机关申请补发渔业船网工具指标批准书。补发的渔业船网工具指标批准书有效期限不变。"},{"i":18,"n":"第十八条","txt":"因继承、赠与、法院判决、拍卖等发生海洋渔船所有权转移的，参照购置海洋捕捞渔船的规定申请办理船网工具指标和渔业捕捞许可证。依法拍卖的，竞买人应当具备规定的条件。"},{"i":19,"n":"第十九条","txt":"有下列情形之一的，不予受理海洋渔船的渔业船网工具指标申请；已经受理的，不予批准： （一）渔船数量或功率数超过船网工具控制指标的； （二）从国外或香港、澳门、台湾地区进口，或以合作、合资等方式引进捕捞渔船在我国管辖水域作业的； （三）制造拖网、单锚张纲张网、单船大型深水有囊围网（三角虎网）作业渔船的； （四）户籍登记为一户的申请人已有两艘以上小型捕捞渔船，申请制造、购置的； （五）除专业远洋渔船外，申请人户籍所在地、法人或非法人组织登记地为非沿海县（市）的，或者企业法定代表人户籍所在地与企业登记地不一致的； （六）违反本规定第十四条第一款、第二款规定，以及不符合有关法律、法规、规章规定和产业发展政策的。"},{"i":20,"n":"第二十条","txt":"在中华人民共和国管辖水域从事渔业捕捞活动，以及中国籍渔船在公海从事渔业捕捞活动，应当经审批机关批准并领取渔业捕捞许可证，按照渔业捕捞许可证核定的作业类型、场所、时限、渔具数量和规格、捕捞品种等作业。对已实行捕捞限额管理的品种或水域，应当按照规定的捕捞限额作业。 禁止在禁渔区、禁渔期、自然保护区从事渔业捕捞活动。 渔业捕捞许可证应当随船携带，徒手作业的应当随身携带，妥善保管，并接受渔业行政执法人员的检查。"},{"i":21,"n":"第二十一条","txt":"渔业捕捞许可证分为下列八类： （一）海洋渔业捕捞许可证，适用于许可中国籍渔船在我国管辖海域的捕捞作业； （二）公海渔业捕捞许可证，适用于许可中国籍渔船在公海的捕捞作业。国际或区域渔业管理组织有特别规定的，应当同时遵守有关规定； （三）内陆渔业捕捞许可证，适用于许可在内陆水域的捕捞作业； （四）专项（特许）渔业捕捞许可证，适用于许可在特定水域、特定时间或对特定品种的捕捞作业，或者使用特定渔具或捕捞方法的捕捞作业； （五）临时渔业捕捞许可证，适用于许可临时从事捕捞作业和非专业渔船临时从事捕捞作业； （六）休闲渔业捕捞许可证，适用于许可从事休闲渔业的捕捞活动； （七）外国渔业捕捞许可证，适用于许可外国船舶、外国人在我国管辖水域的捕捞作业； （八）捕捞辅助船许可证，适用于许可为渔业捕捞生产提供服务的渔业捕捞辅助船，从事捕捞辅助活动。"},{"i":22,"n":"第二十二条","txt":"渔业捕捞许可证核定的作业类型分为刺网、围网、拖网、张网、钓具、耙刺、陷阱、笼壶、地拉网、敷网、抄网、掩罩等共12种。核定作业类型最多不得超过两种，并应当符合渔具准用目录和技术标准，明确每种作业类型中的具体作业方式。拖网、张网不得互换且不得与其他作业类型兼作，其他作业类型不得改为拖网、张网作业。 捕捞辅助船不得从事捕捞生产作业，其携带的渔具应当捆绑、覆盖。"},{"i":23,"n":"第二十三条","txt":"渔业捕捞许可证核定的海洋捕捞作业场所分为以下四类： A类渔区：黄海、渤海、东海和南海等海域机动渔船底拖网禁渔区线向陆地一侧海域； B类渔区：我国与有关国家缔结的协定确定的共同管理渔区、南沙海域、黄岩岛海域及其他特定渔业资源渔场和水产种质资源保护区； C类渔区：渤海、黄海、东海、南海及其他我国管辖海域中除 A类、B类渔区之外的海域。其中，黄渤海区为 C1、东海区为 C2、南海区为 C3； D类渔区：公海。 内陆水域捕捞作业场所按具体水域核定，跨行政区域的按该水域在不同行政区域的范围进行核定。 海洋捕捞作业场所要明确核定渔区的类别和范围，其中 B类渔区要明确核定渔区、渔场或保护区的具体名称。公海要明确海域的名称。内陆水域作业场所要明确具体的水域名称及其范围。"},{"i":24,"n":"第二十四条","txt":"渔业捕捞许可证的作业场所核定权限如下： （一）农业农村部：A类、B类、C类、D类渔区和内陆水域； （二）省级人民政府渔业主管部门：在海洋为本省、自治区、直辖市范围内的 A类渔区，农业农村部授权的 B类渔区、C类渔区。在内陆水域为本省、自治区、直辖市行政管辖水域； （三）市、县级人民政府渔业主管部门：由省级人民政府渔业主管部门在其权限内规定并授权。"},{"i":25,"n":"第二十五条","txt":"国内海洋大中型渔船捕捞许可证的作业场所应当核定在海洋 B类、C类渔区，国内海洋小型渔船捕捞许可证的作业场所应当核定在海洋 A 类渔区。因传统作业习惯需要，经作业水域所在地审批机关批准，海洋大中型渔船捕捞许可证的作业场所可核定在海洋A类渔区。 作业场所核定在 B类、C类渔区的渔船，不得跨海区界限作业，但我国与有关国家缔结的协定确定的共同管理渔区跨越海区界限的除外。作业场所核定在 A 类渔区或内陆水域的渔船，不得跨省、自治区、直辖市管辖水域界限作业。"},{"i":26,"n":"第二十六条","txt":"专项（特许）渔业捕捞许可证应当与海洋渔业捕捞许可证或内陆渔业捕捞许可证同时使用，但因教学、科研等特殊需要，可单独使用专项（特许）渔业捕捞许可证。在 B类渔区捕捞作业的，应当申请核发专项（特许）渔业捕捞许可证。"},{"i":27,"n":"第二十七条","txt":"渔业捕捞许可证的申请人应当是船舶所有人。 徒手作业的，渔业捕捞许可证的申请人应当是作业人本人。"},{"i":28,"n":"第二十八条","txt":"申请渔业捕捞许可证，申请人应当向户籍所在地、法人或非法人组织登记地县级以上人民政府渔业主管部门提出申请，并提交下列资料： （一）渔业捕捞许可证申请书； （二）船舶所有人户口簿或者营业执照； （三）渔业船舶检验证书、渔业船舶国籍证书和所有权登记证书，徒手作业的除外； （四）渔具和捕捞方法符合渔具准用目录和技术标准的说明。 申请海洋渔业捕捞许可证，除提供第一款规定的资料外，还应提供： （一）申请人所属渔业组织出具的意见； （二）首次申请和重新申请捕捞许可证的，提供渔业船网工具指标批准书； （三）申请换发捕捞许可证的，提供原捕捞许可证。 申请公海渔业捕捞许可证，除提供第一款规定的资料外，还需提供： （一）农业农村部远洋渔业项目批准文件； （二）首次申请和重新申请的，提供渔业船网工具指标批准书； （三）非专业远洋渔船需提供海洋渔业捕捞许可证暂存的凭据。 申请专项（特许）渔业捕捞许可证，除提供第"},{"i":29,"n":"第二十九条","txt":"下列作业渔船的渔业捕捞许可证，向船籍港所在地省级人民政府渔业主管部门申请。省级人民政府渔业主管部门应当审核并报农业农村部批准发放： （一）到公海作业的； （二）到我国与有关国家缔结的协定确定的共同管理渔区及南沙海域、黄岩岛海域作业的； （三）到特定渔业资源渔场、水产种质资源保护区作业的； （四）科研、教学单位的专业科研调查船、教学实习船从事渔业科研、教学实习活动的； （五）其他依法应当由农业农村部批准发放的。"},{"i":30,"n":"第三十条","txt":"下列作业的捕捞许可证，由省级人民政府渔业主管部门批准发放： （一）海洋大型拖网、围网渔船作业的； （二）因养殖或者其他特殊需要，捕捞农业农村部颁布的有重要经济价值的苗种或者禁捕的怀卵亲体的； （三）因教学、科研等特殊需要，在禁渔区、禁渔期从事捕捞作业的。"},{"i":31,"n":"第三十一条","txt":"因传统作业习惯或科研、教学及其他特殊情况，需要跨越本规定第二十五条第二款规定的界限从事捕捞作业的，由申请人所在地县级以上地方人民政府渔业主管部门审核同意后，报作业水域所在地审批机关批准发放。 在相邻交界水域作业的渔业捕捞许可证，由交界水域有关的县级以上地方人民政府渔业主管部门协商发放，或由其共同的上级人民政府渔业主管部门批准发放。"},{"i":32,"n":"第三十二条","txt":"除本规定第二十九条、第三十条、第三十一条情况外，其他作业的渔业捕捞许可证由县级以上地方人民政府渔业主管部门审批发放。 县级以上地方人民政府渔业主管部门审批发放渔业捕捞许可证，应当优先安排当地专业渔民和渔业企业。"},{"i":33,"n":"第三十三条","txt":"除专业远洋渔船外，申请渔业捕捞许可证，企业法定代表人户籍所在地与企业登记地不一致的；申请海洋渔业捕捞许可证，申请人户籍所在地、法人或非法人组织登记地为非沿海县（市）的，不予受理；已经受理的，不予批准。"},{"i":34,"n":"第三十四条","txt":"从事钓具、灯光围网作业渔船的子船与其主船（母船）使用同一本渔业捕捞许可证。"},{"i":35,"n":"第三十五条","txt":"海洋渔业捕捞许可证和内陆渔业捕捞许可证的使用期限为5年。其他种类渔业捕捞许可证的使用期限根据实际需要确定，但最长不超过3年。 使用达到农业农村部规定的老旧渔业船舶船龄的渔船从事捕捞作业的，发证机关核发其渔业捕捞许可证时，证书使用期限不得超过渔业船舶检验证书记载的有效期限。"},{"i":36,"n":"第三十六条","txt":"渔业捕捞许可证使用期届满，或者在有效期内有下列情形之一的，应当按规定申请换发渔业捕捞许可证： （一）因行政区划调整导致船名变更、船籍港变更的； （二）作业场所、作业方式变更的； （三）船舶所有人姓名、名称或地址变更的，但渔船所有权发生转移的除外； （四）渔业捕捞许可证污损不能使用的。 渔业捕捞许可证使用期届满的，船舶所有人应当在使用期届满前 3个月内，向原发证机关申请换发捕捞许可证。发证机关批准换发渔业捕捞许可证时，应当收回原渔业捕捞许可证，并予以注销。"},{"i":37,"n":"第三十七条","txt":"在渔业捕捞许可证有效期内有下列情形之一的，应当重新申请渔业捕捞许可证： （一）渔船作业类型变更的； （二）渔船主机、主尺度、总吨位变更的； （三）因购置渔船发生所有人变更的； （四）国内现有捕捞渔船经审批转为远洋捕捞作业的。 有前款第一项、第二项、第三项情形的，还应当办理原渔业捕捞许可证注销手续。"},{"i":38,"n":"第三十八条","txt":"渔业捕捞许可证遗失或者灭失的，船舶所有人应当在1个月内向原发证机关说明遗失或者灭失的时间、地点和原因等情况，由原发证机关在其官方网站上发布声明，自公告声明发布之日起15日后，船舶所有人可向原发证机关申请补发渔业捕捞许可证。补发的渔业捕捞许可证使用期限不变。"},{"i":39,"n":"第三十九条","txt":"有下列情形之一的，渔业捕捞许可证失效，发证机关应当予以注销： （一）渔业捕捞许可证、渔业船舶检验证书或者渔业船舶国籍证书有效期届满未依法延续的； （二）渔船灭失、拆解或销毁的，或者因渔船损毁且渔业捕捞许可证灭失的； （三）不再从事渔业捕捞作业的； （四）渔业捕捞许可证依法被撤销、撤回或者吊销的； （五）以贿赂、欺骗等不正当手段取得渔业捕捞许可证的； （六）依法应当注销的其他情形。 有前款第一项、第三项规定情形的，发证机关应当事先告知当事人。有前款第二项规定情形的，应当由船舶所有人提供相关证明。 渔业捕捞许可证注销后12个月内未按规定重新申请办理的，视为自行放弃，由渔业主管部门收回船网工具指标，更新改造渔船注销捕捞许可证的除外。"},{"i":40,"n":"第四十条","txt":"使用期一年以上的渔业捕捞许可证实行年审制度，每年审验一次。 渔业捕捞许可证的年审工作由发证机关负责，也可由发证机关委托申请人户籍所在地、法人或非法人组织登记地的县级以上地方人民政府渔业主管部门负责。"},{"i":41,"n":"第四十一条","txt":"同时符合下列条件的，为年审合格，由审验人签字，注明日期，加盖公章： （一）具有有效的渔业船舶检验证书和渔业船舶国籍证书，船舶所有人和渔船主尺度、主机功率、总吨位未发生变更，且与渔业船舶证书载明的一致； （二）渔船作业类型、场所、时限、渔具数量与许可内容一致； （三）按规定填写和提交渔捞日志，未超出捕捞限额指标（对实行捕捞限额管理的渔船）； （四）按规定缴纳渔业资源增殖保护费； （五）按规定履行行政处罚决定； （六）其他条件符合有关规定。 年审不合格的，由渔业主管部门责令船舶所有人限期改正，可以再审验一次。再次审验合格的，渔业捕捞许可证继续有效。"},{"i":42,"n":"第四十二条","txt":"渔业船网工具指标批准书、渔业船网工具指标申请不予许可决定书、渔业捕捞许可证、渔业捕捞许可证注销证明、渔业船舶拆解销毁或处理证明、渔业船舶灭失证明、渔业船网工具指标转移证明等证书文件，由农业农村部规定样式并统一印制。 渔业船网工具指标申请书、渔业船网工具指标申请审核变更说明、渔业捕捞许可证申请书、渔业捕捞许可证注销申请表、渔捞日志等，由县级以上人民政府渔业主管部门按照农业农村部规定的统一格式印制。"},{"i":43,"n":"第四十三条","txt":"县级以上人民政府渔业主管部门应当逐船建立渔业船网工具指标审批和渔业捕捞许可证核发档案。 渔业船网工具指标批准书使用和渔业捕捞许可证被注销后，其核发档案应当保存至少5年。"},{"i":44,"n":"第四十四条","txt":"签发人实行农业农村部和省级人民政府渔业主管部门报备制度，县级以上人民政府渔业主管部门应推荐一至两人为签发人。 省级人民政府渔业主管部门负责备案公布本省、自治区、直辖市县级以上地方人民政府渔业主管部门的签发人，农业农村部负责备案公布省、自治区、直辖市渔业主管部门的签发人。"},{"i":45,"n":"第四十五条","txt":"签发人越权、违规签发，或擅自更改渔业船网工具指标和渔业捕捞许可证书证件，或有其他玩忽职守、徇私舞弊等行为的，视情节对有关签发人给予警告、通报批评、暂停或取消签发人资格等处分；签发人及其所在单位应依法承担相应责任。 越权、违规签发或擅自更改的证书证件由其签发人所在单位的上级机关撤销，由原发证机关注销。"},{"i":46,"n":"第四十六条","txt":"禁止涂改、伪造、变造、买卖、出租、出借或以其他形式转让渔业船网工具指标批准书和渔业捕捞许可证。"},{"i":47,"n":"第四十七条","txt":"有下列情形之一的，为无效渔业捕捞许可证： （一）逾期未年审或年审不合格的； （二）证书载明的渔船主机功率与实际功率不符的； （三）以欺骗或者涂改、伪造、变造、买卖、出租、出借等非法方式取得的； （四）被撤销、注销的。 使用无效的渔业捕捞许可证或者在检查时不能提供渔业捕捞许可证，从事渔业捕捞活动的，视为无证捕捞。 涂改、伪造、变造、买卖、出租、出借或以其他形式转让的渔业船网工具指标批准书，为无效渔业船网工具指标批准书，由批准机关予以注销，并核销相应船网工具指标。"},{"i":48,"n":"第四十八条","txt":"依法被没收渔船的，海洋大中型捕捞渔船的船网工具指标由农业农村部核销，其他渔船的船网工具指标由省、自治区、直辖市人民政府渔业主管部门核销。"},{"i":49,"n":"第四十九条","txt":"依法被列入失信被执行人的，县级以上人民政府渔业主管部门应当对其渔业船网工具指标、捕捞许可证的申请按规定予以限制，并冻结失信被执行人及其渔船在全国渔船动态管理系统中的相关数据。"},{"i":50,"n":"第五十条","txt":"海洋大中型渔船从事捕捞活动应当填写渔捞日志，渔捞日志应当记载渔船捕捞作业、进港卸载渔获物、水上收购或转运渔获物等情况。其他渔船渔捞日志的管理由省、自治区、直辖市人民政府规定。"},{"i":51,"n":"第五十一条","txt":"国内海洋大中型渔船应当在返港后向港口所在地县级人民政府渔业主管部门或其指定的机构或渔业组织提交渔捞日志。公海捕捞作业渔船应当每月向农业农村部或其指定机构提交渔捞日志。使用电子渔捞日志的，应当每日提交。"},{"i":52,"n":"第五十二条","txt":"船长应当对渔捞日志记录内容的真实性、正确性负责。 禁止在 A类渔区转载渔获物。"},{"i":53,"n":"第五十三条","txt":"未按规定提交渔捞日志或者渔捞日志填写不真实、不规范的，由县级以上人民政府渔业主管部门或其所属的渔政监督管理机构给予警告，责令改正；逾期不改正的，可以处1000元以上1万元以下罚款。"},{"i":54,"n":"第五十四条","txt":"违反本规定的其他行为，依照《中华人民共和国渔业法》或其他有关法律法规规章进行处罚。"},{"i":55,"n":"第五十五条","txt":"本规定有关用语的定义如下： 渔业捕捞活动：捕捞或准备捕捞水生生物资源的行为，以及为这种行为提供支持和服务的各种活动。在尚未管理的滩涂或水域手工零星采集水产品的除外。 渔船：《中华人民共和国渔港水域交通安全管理条例》规定的渔业船舶。 船长：《渔业船舶国籍证书》中所载明的船长。 捕捞渔船：从事捕捞活动的生产船。 捕捞辅助船：渔获物运销船、冷藏加工船、渔用物资和燃料补给船等为渔业捕捞生产提供服务的船舶。 非专业渔船：从事捕捞活动的教学、科研调查船，特殊用途渔船，用于休闲捕捞活动的专业旅游观光船等船舶。 远洋渔船：在公海或他国管辖海域作业的捕捞渔船和捕捞辅助船，包括专业远洋渔船和非专业远洋渔船。专业远洋渔船，指专门用于在公海或他国管辖海域作业的捕捞渔船和捕捞辅助船；非专业远洋渔船，指具有国内有效的渔业捕捞许可证，转产到公海或他国管辖海域作业的捕捞渔船和捕捞辅助船。 船网工具控制指标：渔船的数量"},{"i":56,"n":"第五十六条","txt":"香港、澳门特别行政区持有广东省户籍的流动渔船的船网工具指标和捕捞许可证管理，按照农业农村部有关港澳流动渔船管理的规定执行。"},{"i":57,"n":"第五十七条","txt":"国内捕捞辅助船的总量控制应当与本行政区域内捕捞渔船数量和规模相匹配，其船网工具指标和捕捞许可证审批按照捕捞渔船进行管理。 国内捕捞辅助船、休闲渔船和徒手作业捕捞许可管理的具体办法，由省、自治区、直辖市人民政府渔业主管部门规定。"},{"i":58,"n":"第五十八条","txt":"我国渔船到他国管辖水域作业，应当经农业农村部批准。 中国籍渔业船舶以光船条件出租到境外申请办理光船租赁登记和非专业远洋渔船申请办理远洋渔业项目前，应当将海洋渔业捕捞许可证交回原发证机关暂存，原发证机关应当出具暂存凭据。渔业捕捞许可证暂存期不计入渔业捕捞许可证核定的使用期限，暂存期间不需要办理年审手续。渔船回国终止光船租赁和远洋渔业项目后，凭暂存凭据领回渔业捕捞许可证。"},{"i":59,"n":"第五十九条","txt":"本规定自2019年1月1日起施行。原农业部2002年8月23日发布，2004年7月1日、2007年11月8日和2013年12月31日修订的《渔业捕捞许可管理规定》同时废止。"}],"yuyebulaoxukeguanliguiding":[{"i":1,"n":"第一条","txt":"为了保护、合理利用渔业资源，控制捕捞强度，维护渔业生产秩序，保障渔业生产者的合法权益，根据《中华人民共和国渔业法》，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国的公民、法人和其他组织从事渔业捕捞活动，以及外国人、外国渔业船舶在中华人民共和国领域及管辖的其他水域从事渔业捕捞活动，应当遵守本规定。 中华人民共和国缔结的条约、协定另有规定的，按条约、协定执行。"},{"i":3,"n":"第三条","txt":"国家对捕捞业实行船网工具控制指标管理，实行捕捞许可证制度和捕捞限额制度。 国家根据渔业资源变化与环境状况，确定船网工具控制指标，控制捕捞能力总量和渔业捕捞许可证数量。渔业捕捞许可证的批准发放，应当遵循公开、公平、公正原则，数量不得超过船网工具控制指标范围。"},{"i":4,"n":"第四条","txt":"渔业捕捞许可证、船网工具指标等证书文件的审批实行签发人负责制，相关证书文件经签发人签字并加盖公章后方为有效。 签发人对其审批签发证书文件的真实性及合法性负责。"},{"i":5,"n":"第五条","txt":"农业农村部主管全国渔业捕捞许可管理和捕捞能力总量控制工作。 县级以上地方人民政府渔业主管部门及其所属的渔政监督管理机构负责本行政区域内的渔业捕捞许可管理和捕捞能力总量控制的组织、实施工作。"},{"i":6,"n":"第六条","txt":"县级以上人民政府渔业主管部门应当在其办公场所和网上办理平台，公布船网工具指标、渔业捕捞许可证审批的条件、程序、期限以及需要提交的全部材料目录和申请书示范文本等事项。 县级以上人民政府渔业主管部门应当按照本规定自受理船网工具指标或渔业捕捞许可证申请之日起20个工作日内审查完毕或者作出是否批准的决定。不予受理申请或者不予批准的，应当书面通知申请人并说明理由。"},{"i":7,"n":"第七条","txt":"县级以上人民政府渔业主管部门应当加强渔船和捕捞许可管理信息系统建设，建立健全渔船动态管理数据库。海洋渔船船网工具指标和捕捞许可证的申请、审核审批及制发证书文件等应当通过全国统一的渔船动态管理系统进行。 申请人应当提供的户口簿、营业执照、渔业船舶检验证书、渔业船舶登记证等法定证照、权属证明在全国渔船动态管理系统或者部门间核查能够查询到有效信息的，可以不再提供纸质材料。"},{"i":8,"n":"第八条","txt":"海洋渔船按船长分为以下三类： （一）海洋大型渔船：船长大于或者等于24米； （二）海洋中型渔船：船长大于或者等于12米且小于24米； （三）海洋小型渔船：船长小于12米。 内陆渔船的分类标准由各省、自治区、直辖市人民政府渔业主管部门制定。"},{"i":9,"n":"第九条","txt":"国内海洋大中型捕捞渔船的船网工具控制指标由农业农村部确定并报国务院批准后，向有关省、自治区、直辖市下达。国内海洋小型捕捞渔船的船网工具控制指标由省、自治区、直辖市人民政府依据其渔业资源与环境承载能力、资源利用状况、渔民传统作业情况等确定，报农业农村部批准后下达。 县级以上地方人民政府渔业主管部门应当控制本行政区域内海洋捕捞渔船的数量、功率，不得超过国家或省、自治区、直辖市人民政府下达的船网工具控制指标，具体办法由省、自治区、直辖市人民政府规定。 内陆水域捕捞业的船网工具控制指标和管理，按照省、自治区、直辖市人民政府的规定执行。"},{"i":10,"n":"第十条","txt":"制造、更新改造、购置、进口海洋捕捞渔船，应当经有审批权的人民政府渔业主管部门在国家或者省、自治区、直辖市下达的船网工具控制指标内批准，并取得渔业船网工具指标批准书。"},{"i":11,"n":"第十一条","txt":"申请海洋捕捞渔船船网工具指标，应当向户籍所在地、法人或非法人组织登记地县级以上人民政府渔业主管部门提出，提交渔业船网工具指标申请书、申请人户口簿或者营业执照，以及申请人所属渔业组织出具的意见，并按以下情况提供资料： （一）制造海洋捕捞渔船的，提供经确认符合船机桨匹配要求的渔船建造设计图纸。 国内海洋捕捞渔船淘汰后申请制造渔船的，还应当提供渔船拆解所在地县级以上地方人民政府渔业主管部门出具的渔业船舶拆解、销毁或处理证明和现场监督管理的影像资料，以及原发证机关出具的渔业船舶证书注销证明。 国内海洋捕捞渔船因海损事故造成渔船灭失后申请制造渔船的，还应当提供船籍港登记机关出具的灭失证明和原发证机关出具的渔业船舶证书注销证明。 （二）购置海洋捕捞渔船的提供： 1.被购置渔船的渔业船舶检验证书、渔业船舶国籍证书和所有权登记证书； 2.被购置渔船的渔业捕捞许可证注销证明； 3.渔业船网工具指标转移证"},{"i":12,"n":"第十二条","txt":"下列海洋捕捞渔船的船网工具指标，向省级人民政府渔业主管部门申请。省级人民政府渔业主管部门应当按照规定进行审查，并将审查意见和申请人的全部申请材料报农业农村部审批： （一）远洋渔船； （二）因特殊需要，超过国家下达的省、自治区、直辖市渔业船网工具控制指标的渔船； （三）其他依法应由农业农村部审批的渔船。"},{"i":13,"n":"第十三条","txt":"除第十二条规定情况外，制造或者更新改造国内海洋大中型捕捞渔船的船网工具指标，由省级人民政府渔业主管部门审批。 跨省、自治区、直辖市购置国内海洋捕捞渔船的，由买入地省级人民政府渔业主管部门审批。 其他国内渔船的船网工具指标的申请、审批，由省、自治区、直辖市人民政府规定。"},{"i":14,"n":"第十四条","txt":"制造、更新改造国内海洋捕捞渔船的，应当在本省、自治区、直辖市渔业船网工具控制指标范围内，通过淘汰旧捕捞渔船解决，船数和功率数应当分别不超过淘汰渔船的船数和功率数。国内海洋大中型捕捞渔船和小型捕捞渔船的船网工具指标不得相互转换。 购置国内海洋捕捞渔船的船网工具指标随船转移。国内海洋大中型捕捞渔船不得跨海区买卖，国内海洋小型和内陆捕捞渔船不得跨省、自治区、直辖市买卖。 国内现有海洋捕捞渔船经审批转为远洋捕捞作业的，其船网工具指标予以保留。因渔船发生重大改造，导致渔船主尺度、主机功率和作业类型发生变更的除外。 专业远洋渔船不计入省、自治区、直辖市的船网工具控制指标，由农业农村部统一管理，不得在我国管辖水域作业。"},{"i":15,"n":"第十五条","txt":"渔船灭失、拆解、销毁的，原船舶所有人可自渔船灭失、拆解、销毁之日起12个月内，按本规定申请办理渔船制造或更新改造手续；逾期未申请的，视为自行放弃，由渔业主管部门收回船网工具指标。渔船灭失依法需要调查处理的，调查处理所需时间不计算在此规定期限内。 专业远洋渔船因特殊原因无法按期申请办理渔船制造手续的，可在前款规定期限内申请延期，但最长不超过相应远洋渔业项目届满之日起36个月。"},{"i":16,"n":"第十六条","txt":"申请人应当凭渔业船网工具指标批准书办理渔船制造、更新改造、购置或进口手续，并申请渔船检验、登记，办理渔业捕捞许可证。 制造、更新改造、进口渔船的渔业船网工具指标批准书的有效期为18个月，购置渔船的渔业船网工具指标批准书的有效期为6个月。因特殊原因在规定期限内无法办理完毕相关手续的，可在有效期届满前3个月内申请有效期延展18个月。 已开工建造的到特殊渔区作业的专业远洋渔船，在延展期内仍无法办理完毕相关手续的，可在延展期届满前3个月内再申请延展18个月，且不得再次申请延展。 船网工具指标批准书有效期届满未依法延续的，审批机关应当予以注销并收回船网工具指标。"},{"i":17,"n":"第十七条","txt":"渔业船网工具指标批准书在有效期内遗失或者灭失的，船舶所有人应当在1个月内向原审批机关说明遗失或者灭失的时间、地点和原因等情况，由原审批机关在其官方网站上发布声明，自公告声明发布之日起15日后，船舶所有人可向原审批机关申请补发渔业船网工具指标批准书。补发的渔业船网工具指标批准书有效期限不变。"},{"i":18,"n":"第十八条","txt":"因继承、赠与、法院判决、拍卖等发生海洋渔船所有权转移的，参照购置海洋捕捞渔船的规定申请办理船网工具指标和渔业捕捞许可证。依法拍卖的，竞买人应当具备规定的条件。"},{"i":19,"n":"第十九条","txt":"有下列情形之一的，不予受理海洋渔船的渔业船网工具指标申请；已经受理的，不予批准： （一）渔船数量或功率数超过船网工具控制指标的； （二）从国外或香港、澳门、台湾地区进口，或以合作、合资等方式引进捕捞渔船在我国管辖水域作业的； （三）除他国政府许可或到特殊渔区作业有特别需求的专业远洋渔船外，制造拖网作业渔船的； （四）制造单锚张纲张网、单船大型深水有囊围网（三角虎网）作业渔船的； （五）户籍登记为一户的申请人已有两艘以上小型捕捞渔船，申请制造、购置的； （六）除专业远洋渔船外，申请人户籍所在地、法人或非法人组织登记地为非沿海县（市）的，或者企业法定代表人户籍所在地与企业登记地不一致的； （七）违反本规定第十四条第一款、第二款规定，以及不符合有关法律、法规、规章规定和产业发展政策的。"},{"i":20,"n":"第二十条","txt":"在中华人民共和国管辖水域从事渔业捕捞活动，以及中国籍渔船在公海从事渔业捕捞活动，应当经审批机关批准并领取渔业捕捞许可证，按照渔业捕捞许可证核定的作业类型、场所、时限、渔具数量和规格、捕捞品种等作业。对已实行捕捞限额管理的品种或水域，应当按照规定的捕捞限额作业。 禁止在禁渔区、禁渔期、自然保护区从事渔业捕捞活动。 渔业捕捞许可证应当随船携带，徒手作业的应当随身携带，妥善保管，并接受渔业行政执法人员的检查。"},{"i":21,"n":"第二十一条","txt":"渔业捕捞许可证分为下列八类： （一）海洋渔业捕捞许可证，适用于许可中国籍渔船在我国管辖海域的捕捞作业； （二）公海渔业捕捞许可证，适用于许可中国籍渔船在公海的捕捞作业。国际或区域渔业管理组织有特别规定的，应当同时遵守有关规定； （三）内陆渔业捕捞许可证，适用于许可在内陆水域的捕捞作业； （四）专项（特许）渔业捕捞许可证，适用于许可在特定水域、特定时间或对特定品种的捕捞作业，或者使用特定渔具或捕捞方法的捕捞作业； （五）临时渔业捕捞许可证，适用于许可临时从事捕捞作业和非专业渔船临时从事捕捞作业； （六）休闲渔业捕捞许可证，适用于许可从事休闲渔业的捕捞活动； （七）外国渔业捕捞许可证，适用于许可外国船舶、外国人在我国管辖水域的捕捞作业； （八）捕捞辅助船许可证，适用于许可为渔业捕捞生产提供服务的渔业捕捞辅助船，从事捕捞辅助活动。"},{"i":22,"n":"第二十二条","txt":"渔业捕捞许可证核定的作业类型分为刺网、围网、拖网、张网、钓具、耙刺、陷阱、笼壶、地拉网、敷网、抄网、掩罩等共12种。核定作业类型最多不得超过两种，并应当符合渔具准用目录和技术标准，明确每种作业类型中的具体作业方式。拖网、张网不得互换且不得与其他作业类型兼作，其他作业类型不得改为拖网、张网作业。 捕捞辅助船不得从事捕捞生产作业，其携带的渔具应当捆绑、覆盖。"},{"i":23,"n":"第二十三条","txt":"渔业捕捞许可证核定的海洋捕捞作业场所分为以下四类： A类渔区：黄海、渤海、东海和南海等海域机动渔船底拖网禁渔区线向陆地一侧海域； B类渔区：我国与有关国家缔结的协定确定的共同管理渔区、南沙海域、黄岩岛海域及其他特定渔业资源渔场和水产种质资源保护区； C类渔区：渤海、黄海、东海、南海及其他我国管辖海域中除A类、B类渔区之外的海域。其中，黄渤海区为C1、东海区为C2、南海区为C3； D类渔区：公海。 内陆水域捕捞作业场所按具体水域核定，跨行政区域的按该水域在不同行政区域的范围进行核定。 海洋捕捞作业场所要明确核定渔区的类别和范围，其中B类渔区要明确核定渔区、渔场或保护区的具体名称。公海要明确海域的名称。内陆水域作业场所要明确具体的水域名称及其范围。"},{"i":24,"n":"第二十四条","txt":"渔业捕捞许可证的作业场所核定权限如下： （一）农业农村部：A类、B类、C类、D类渔区和内陆水域； （二）省级人民政府渔业主管部门：在海洋为本省、自治区、直辖市范围内的A类渔区，农业农村部授权的B类渔区、C类渔区。在内陆水域为本省、自治区、直辖市行政管辖水域； （三）市、县级人民政府渔业主管部门：由省级人民政府渔业主管部门在其权限内规定并授权。"},{"i":25,"n":"第二十五条","txt":"国内海洋大中型渔船捕捞许可证的作业场所应当核定在海洋B类、C类渔区，国内海洋小型渔船捕捞许可证的作业场所应当核定在海洋A类渔区。因传统作业习惯需要，经作业水域所在地审批机关批准，海洋大中型渔船捕捞许可证的作业场所可核定在海洋A类渔区。 作业场所核定在B类、C类渔区的渔船，不得跨海区界限作业，但我国与有关国家缔结的协定确定的共同管理渔区跨越海区界限的除外。作业场所核定在A类渔区或内陆水域的渔船，不得跨省、自治区、直辖市管辖水域界限作业。"},{"i":26,"n":"第二十六条","txt":"专项（特许）渔业捕捞许可证应当与海洋渔业捕捞许可证或内陆渔业捕捞许可证同时使用，但因教学、科研等特殊需要，可单独使用专项（特许）渔业捕捞许可证。在B类渔区捕捞作业的，应当申请核发专项（特许）渔业捕捞许可证。"},{"i":27,"n":"第二十七条","txt":"渔业捕捞许可证的申请人应当是船舶所有人。 徒手作业的，渔业捕捞许可证的申请人应当是作业人本人。"},{"i":28,"n":"第二十八条","txt":"申请渔业捕捞许可证，申请人应当向户籍所在地、法人或非法人组织登记地县级以上人民政府渔业主管部门提出申请，并提交下列资料： （一）渔业捕捞许可证申请书； （二）船舶所有人户口簿或者营业执照； （三）渔业船舶检验证书、渔业船舶国籍证书和所有权登记证书，徒手作业的除外； （四）渔具和捕捞方法符合渔具准用目录和技术标准的说明。 申请海洋渔业捕捞许可证，除提供第一款规定的资料外，还应提供： （一）申请人所属渔业组织出具的意见； （二）首次申请和重新申请捕捞许可证的，提供渔业船网工具指标批准书； （三）申请换发捕捞许可证的，提供原捕捞许可证。 申请公海渔业捕捞许可证，除提供第一款规定的资料外，还需提供： （一）农业农村部远洋渔业项目批准文件； （二）首次申请和重新申请的，提供渔业船网工具指标批准书； （三）非专业远洋渔船需提供海洋渔业捕捞许可证暂存的凭据。 申请专项（特许）渔业捕捞许可证，除提供第"},{"i":29,"n":"第二十九条","txt":"下列作业渔船的渔业捕捞许可证，向船籍港所在地省级人民政府渔业主管部门申请。省级人民政府渔业主管部门应当审核并报农业农村部批准发放： （一）到公海作业的； （二）到我国与有关国家缔结的协定确定的共同管理渔区及南沙海域、黄岩岛海域作业的； （三）到特定渔业资源渔场、水产种质资源保护区作业的； （四）科研、教学单位的专业科研调查船、教学实习船从事渔业科研、教学实习活动的； （五）其他依法应当由农业农村部批准发放的。"},{"i":30,"n":"第三十条","txt":"下列作业的捕捞许可证，由省级人民政府渔业主管部门批准发放： （一）海洋大型拖网、围网渔船作业的； （二）因养殖或者其他特殊需要，捕捞农业农村部颁布的有重要经济价值的苗种或者禁捕的怀卵亲体的； （三）因教学、科研等特殊需要，在禁渔区、禁渔期从事捕捞作业的。"},{"i":31,"n":"第三十一条","txt":"因传统作业习惯或科研、教学及其他特殊情况，需要跨越本规定第二十五条第二款规定的界限从事捕捞作业的，由申请人所在地县级以上地方人民政府渔业主管部门审核同意后，报作业水域所在地审批机关批准发放。 在相邻交界水域作业的渔业捕捞许可证，由交界水域有关的县级以上地方人民政府渔业主管部门协商发放，或由其共同的上级人民政府渔业主管部门批准发放。"},{"i":32,"n":"第三十二条","txt":"除本规定第二十九条、第三十条、第三十一条情况外，其他作业的渔业捕捞许可证由县级以上地方人民政府渔业主管部门审批发放。 县级以上地方人民政府渔业主管部门审批发放渔业捕捞许可证，应当优先安排当地专业渔民和渔业企业。"},{"i":33,"n":"第三十三条","txt":"除专业远洋渔船外，申请渔业捕捞许可证，企业法定代表人户籍所在地与企业登记地不一致的；申请海洋渔业捕捞许可证，申请人户籍所在地、法人或非法人组织登记地为非沿海县（市）的，不予受理；已经受理的，不予批准。"},{"i":34,"n":"第三十四条","txt":"从事钓具、灯光围网作业渔船的子船与其主船（母船）使用同一本渔业捕捞许可证。"},{"i":35,"n":"第三十五条","txt":"海洋渔业捕捞许可证和内陆渔业捕捞许可证的使用期限为5年。其他种类渔业捕捞许可证的使用期限根据实际需要确定，但最长不超过3年。 使用达到农业农村部规定的老旧渔业船舶船龄的渔船从事捕捞作业的，发证机关核发其渔业捕捞许可证时，证书使用期限不得超过渔业船舶检验证书记载的有效期限。"},{"i":36,"n":"第三十六条","txt":"渔业捕捞许可证使用期届满，或者在有效期内有下列情形之一的，应当按规定申请换发渔业捕捞许可证： （一）因行政区划调整导致船名变更、船籍港变更的； （二）作业场所、作业方式变更的； （三）船舶所有人姓名、名称或地址变更的，但渔船所有权发生转移的除外； （四）渔业捕捞许可证污损不能使用的。 渔业捕捞许可证使用期届满的，船舶所有人应当在使用期届满前3个月内，向原发证机关申请换发捕捞许可证。发证机关批准换发渔业捕捞许可证时，应当收回原渔业捕捞许可证，并予以注销。"},{"i":37,"n":"第三十七条","txt":"在渔业捕捞许可证有效期内有下列情形之一的，应当重新申请渔业捕捞许可证： （一）渔船作业类型变更的； （二）渔船主机、主尺度、总吨位变更的； （三）因购置渔船发生所有人变更的； （四）国内现有捕捞渔船经审批转为远洋捕捞作业的。 有前款第一项、第二项、第三项情形的，还应当办理原渔业捕捞许可证注销手续。"},{"i":38,"n":"第三十八条","txt":"渔业捕捞许可证遗失或者灭失的，船舶所有人应当在1个月内向原发证机关说明遗失或者灭失的时间、地点和原因等情况，由原发证机关在其官方网站上发布声明，自公告声明发布之日起15日后，船舶所有人可向原发证机关申请补发渔业捕捞许可证。补发的渔业捕捞许可证使用期限不变。"},{"i":39,"n":"第三十九条","txt":"有下列情形之一的，渔业捕捞许可证失效，发证机关应当予以注销： （一）渔业捕捞许可证、渔业船舶检验证书或者渔业船舶国籍证书有效期届满未依法延续的； （二）渔船灭失、拆解或销毁的，或者因渔船损毁且渔业捕捞许可证灭失的； （三）不再从事渔业捕捞作业的； （四）渔业捕捞许可证依法被撤销、撤回或者吊销的； （五）以贿赂、欺骗等不正当手段取得渔业捕捞许可证的； （六）依法应当注销的其他情形。 有前款第一项、第三项规定情形的，发证机关应当事先告知当事人。有前款第二项规定情形的，应当由船舶所有人提供相关证明。 渔业捕捞许可证注销后12个月内未按规定重新申请办理的，视为自行放弃，由渔业主管部门收回船网工具指标，更新改造渔船注销捕捞许可证的除外。"},{"i":40,"n":"第四十条","txt":"使用期一年以上的渔业捕捞许可证实行年审制度，每年审验一次。 渔业捕捞许可证的年审工作由发证机关负责，也可由发证机关委托申请人户籍所在地、法人或非法人组织登记地的县级以上地方人民政府渔业主管部门负责。"},{"i":41,"n":"第四十一条","txt":"同时符合下列条件的，为年审合格，由审验人签字，注明日期，加盖公章： （一）具有有效的渔业船舶检验证书和渔业船舶国籍证书，船舶所有人和渔船主尺度、主机功率、总吨位未发生变更，且与渔业船舶证书载明的一致； （二）渔船作业类型、场所、时限、渔具数量与许可内容一致； （三）按规定填写和提交渔捞日志，未超出捕捞限额指标（对实行捕捞限额管理的渔船）； （四）按规定缴纳渔业资源增殖保护费； （五）按规定履行行政处罚决定； （六）其他条件符合有关规定。 年审不合格的，由渔业主管部门责令船舶所有人限期改正，可以再审验一次。再次审验合格的，渔业捕捞许可证继续有效。"},{"i":42,"n":"第四十二条","txt":"渔业船网工具指标批准书、渔业船网工具指标申请不予许可决定书、渔业捕捞许可证、渔业捕捞许可证注销证明、渔业船舶拆解销毁或处理证明、渔业船舶灭失证明、渔业船网工具指标转移证明等证书文件，由农业农村部规定样式并统一印制。 渔业船网工具指标申请书、渔业船网工具指标申请审核变更说明、渔业捕捞许可证申请书、渔业捕捞许可证注销申请表、渔捞日志等，由县级以上人民政府渔业主管部门按照农业农村部规定的统一格式印制。"},{"i":43,"n":"第四十三条","txt":"县级以上人民政府渔业主管部门应当逐船建立渔业船网工具指标审批和渔业捕捞许可证核发档案。 渔业船网工具指标批准书使用和渔业捕捞许可证被注销后，其核发档案应当保存至少5年。"},{"i":44,"n":"第四十四条","txt":"签发人实行农业农村部和省级人民政府渔业主管部门报备制度，县级以上人民政府渔业主管部门应推荐一至两人为签发人。 省级人民政府渔业主管部门负责备案公布本省、自治区、直辖市县级以上地方人民政府渔业主管部门的签发人，农业农村部负责备案公布省、自治区、直辖市渔业主管部门的签发人。"},{"i":45,"n":"第四十五条","txt":"签发人越权、违规签发，或擅自更改渔业船网工具指标和渔业捕捞许可证书证件，或有其他玩忽职守、徇私舞弊等行为的，视情节对有关签发人给予警告、通报批评、暂停或取消签发人资格等处分；签发人及其所在单位应依法承担相应责任。 越权、违规签发或擅自更改的证书证件由其签发人所在单位的上级机关撤销，由原发证机关注销。"},{"i":46,"n":"第四十六条","txt":"禁止涂改、伪造、变造、买卖、出租、出借或以其他形式转让渔业船网工具指标批准书和渔业捕捞许可证。"},{"i":47,"n":"第四十七条","txt":"有下列情形之一的，为无效渔业捕捞许可证： （一）逾期未年审或年审不合格的； （二）证书载明的渔船主机功率与实际功率不符的； （三）以欺骗或者涂改、伪造、变造、买卖、出租、出借等非法方式取得的； （四）被撤销、注销的。 使用无效的渔业捕捞许可证或者无正当理由不能提供渔业捕捞许可证的，视为无证捕捞。 涂改、伪造、变造、买卖、出租、出借或以其他形式转让的渔业船网工具指标批准书，为无效渔业船网工具指标批准书，由批准机关予以注销，并核销相应船网工具指标。"},{"i":48,"n":"第四十八条","txt":"依法被没收渔船的，海洋大中型捕捞渔船的船网工具指标由农业农村部核销，其他渔船的船网工具指标由省、自治区、直辖市人民政府渔业主管部门核销。"},{"i":49,"n":"第四十九条","txt":"依法被列入失信被执行人的，县级以上人民政府渔业主管部门应当对其渔业船网工具指标、捕捞许可证的申请按规定予以限制，并冻结失信被执行人及其渔船在全国渔船动态管理系统中的相关数据。"},{"i":50,"n":"第五十条","txt":"海洋大中型渔船从事捕捞活动应当填写渔捞日志，渔捞日志应当记载渔船捕捞作业、进港卸载渔获物、水上收购或转运渔获物等情况。其他渔船渔捞日志的管理由省、自治区、直辖市人民政府规定。"},{"i":51,"n":"第五十一条","txt":"国内海洋大中型渔船应当在返港后向港口所在地县级人民政府渔业主管部门或其指定的机构或渔业组织提交渔捞日志。公海捕捞作业渔船应当每月向农业农村部或其指定机构提交渔捞日志。使用电子渔捞日志的，应当每日提交。"},{"i":52,"n":"第五十二条","txt":"船长应当对渔捞日志记录内容的真实性、正确性负责。 禁止在A类渔区转载渔获物。"},{"i":53,"n":"第五十三条","txt":"未按规定提交渔捞日志或者渔捞日志填写不真实、不规范的，由县级以上人民政府渔业主管部门或其所属的渔政监督管理机构给予警告，责令改正；逾期不改正的，可以处1000元以上1万元以下罚款。"},{"i":54,"n":"第五十四条","txt":"违反本规定的其他行为，依照《中华人民共和国渔业法》或其他有关法律法规规章进行处罚。"},{"i":55,"n":"第五十五条","txt":"本规定有关用语的定义如下： 渔业捕捞活动：捕捞或准备捕捞水生生物资源的行为，以及为这种行为提供支持和服务的各种活动。在尚未管理的滩涂或水域手工零星采集水产品的除外。 渔船：《中华人民共和国渔港水域交通安全管理条例》规定的渔业船舶。 船长：《渔业船舶国籍证书》中所载明的船长。 捕捞渔船：从事捕捞活动的生产船。 捕捞辅助船：渔获物运销船、冷藏加工船、渔用物资和燃料补给船等为渔业捕捞生产提供服务的船舶。 非专业渔船：从事捕捞活动的教学、科研调查船，特殊用途渔船，用于休闲捕捞活动的专业旅游观光船等船舶。 远洋渔船：在公海或他国管辖海域作业的捕捞渔船和捕捞辅助船，包括专业远洋渔船和非专业远洋渔船。专业远洋渔船，指专门用于在公海或他国管辖海域作业的捕捞渔船和捕捞辅助船；非专业远洋渔船，指具有国内有效的渔业捕捞许可证，转产到公海或他国管辖海域作业的捕捞渔船和捕捞辅助船。 船网工具控制指标：渔船的数量"},{"i":56,"n":"第五十六条","txt":"香港、澳门特别行政区持有广东省户籍的流动渔船的船网工具指标和捕捞许可证管理，按照农业农村部有关港澳流动渔船管理的规定执行。"},{"i":57,"n":"第五十七条","txt":"国内捕捞辅助船的总量控制应当与本行政区域内捕捞渔船数量和规模相匹配，其船网工具指标和捕捞许可证审批按照捕捞渔船进行管理。 国内捕捞辅助船、休闲渔船和徒手作业捕捞许可管理的具体办法，由省、自治区、直辖市人民政府渔业主管部门规定。"},{"i":58,"n":"第五十八条","txt":"我国渔船到他国管辖水域作业，应当经农业农村部批准。 中国籍渔业船舶以光船条件出租到境外申请办理光船租赁登记和非专业远洋渔船申请办理远洋渔业项目前，应当将海洋渔业捕捞许可证交回原发证机关暂存，原发证机关应当出具暂存凭据。渔业捕捞许可证暂存期不计入渔业捕捞许可证核定的使用期限，暂存期间不需要办理年审手续。渔船回国终止光船租赁和远洋渔业项目后，凭暂存凭据领回渔业捕捞许可证。"},{"i":59,"n":"第五十九条","txt":"本规定自2019年1月1日起施行。原农业部2002年8月23日发布，2004年7月1日、2007年11月8日和2013年12月31日修订的《渔业捕捞许可管理规定》同时废止。"}],"yuyeshuiyuwuranshigudiaochachulichengxuguiding":[{"i":1,"n":"第一条","txt":"为及时、公正地调查处理渔业水域污染事故，维护国家、集体和公民的合法权益，根据《中华人民共和国环境保护法》、《中华人民共和国水污染防治法》、《中华人民共和国渔业法》等有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"任何公民、法人或其他组织造成渔业水域污染事故的，应当接受渔政监督管理机构（以下简称主管机构）的调查处理。 各级主管机构调查处理渔业水域污染事故适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称的渔业水域是指鱼虾贝类的产卵尝索饵尝越冬尝洄游通道和鱼虾贝藻类及其他水生动植物的增养殖场。"},{"i":4,"n":"第四条","txt":"本规定所称的渔业水域污染事故是指由于单位和个人将某种物质和能量引入渔业水域，损坏渔业水体使用功能，影响渔业水域内的生物繁殖、生长或造成该生物死亡、数量减少，以及造成该生物有毒有害物质积累、质量下降等，对渔业资源和渔业生产造成损害的事实。"},{"i":5,"n":"第五条","txt":"地（市）、县主管机构依法管辖其监督管理范围内的较大及一般性渔业水域污染事故。 省（自治区、直辖市）主管机构依法管辖其监督管理范围内直接经济损失额在百万元以上的重大渔业水域污染事故。 中华人民共和国渔政渔港监督管理局管辖或指定省级主管机构处理直接经济损失额在千万元以上的特大渔业水域污染事故和涉外渔业水域污染事故。"},{"i":6,"n":"第六条","txt":"中华人民共和国渔政渔港监督管理局成立渔业水域污染事故技术审定委员会，负责全国重大渔业水域污染事故的技术审定工作。"},{"i":7,"n":"第七条","txt":"下级主管机构对其处理范围内的渔业水域污染事故，认为需要由上级主管机构处理的，可报请上级主管机构处理。"},{"i":8,"n":"第八条","txt":"上级主管机构管辖的渔业水域污染事故必要时可以指定下级机构处理。"},{"i":9,"n":"第九条","txt":"对管辖权有争议的渔业水域污染事故，由争议双方协商解决，协商不成的，由共同的上一级主管机构指定机关调查处理。"},{"i":10,"n":"第十条","txt":"指定处理的渔业水域污染事故应办理书面手续。主管机构指定的单位，须在指定权限范围内行使权力。"},{"i":11,"n":"第十一条","txt":"跨行政区域的渔业水域污染纠纷，按照《中华人民共和国水污染防治法》第二十六条的规定，由有关地方人民政府协商解决，或者由其共同的上级人民政府协调解决，主管机构应积极配合有关地方人民政府做好事故的处理工作。"},{"i":12,"n":"第十二条","txt":"主管机构在发现或接到事故报告后，应做好下列工作： （一）填写事故报告表，内容包括报告人、事故发生时间、地点、污染损害原因及状况等。 （二）尽快组织渔业环境监测站或有关人员赴现场进行调查取证。重大、特大及涉外渔业水域污染事故应立即向同级人民政府及环境保护主管部门和上一级主管机构报告。 （三）对污染情况复杂、损失较重的污染事故，应参照农业部颁布的《污染死鱼调查方法（淡水）》的规定进行调查取证。"},{"i":13,"n":"第十三条","txt":"渔业执法人员调查处理渔业水域污染事故，应当收集与污染事故有关的各种证据，证据包括书证、物证、视听资料、证人证言、当事人陈述、鉴定结论、现场笔录。 证据必须查证属实，才能作为认定事实的依据。"},{"i":14,"n":"第十四条","txt":"调查渔业水域污染事故，必须制作现场笔录，内容包括：发生事故时间、地点、水体类型、气候、水文、污染物、污染源、污染范围、损失程度等。 笔录应当表述清楚，定量准确，如实记录，并有在场调查的两名渔业执法人员的签名和笔录时间。"},{"i":15,"n":"第十五条","txt":"渔业环境监测站出具的监测数据、鉴定结论或其他具备资格的有关单位出具的鉴定证明是主管机构处理污染事故的依据。 监测数据、鉴定结果报告书由监测鉴定人员签名，并加盖单位公章。"},{"i":16,"n":"第十六条","txt":"因渔业水域污染事故发生的赔偿责任和赔偿金额的纠纷，当事人可以向事故发生地的主管机构申请调解处理，当事人也可以直接向人民法院起诉。"},{"i":17,"n":"第十七条","txt":"主管机构受理当事人事故纠纷调解处理申请应符合下列条件： （一）必须是双方当事人同意调解处理； （二）申请人必须是与渔业损失事故纠纷有直接利害关系的单位或个人； （三）有明确的被申请人和具体的事实依据与请求； （四）不超越主管机构受理范围。"},{"i":18,"n":"第十八条","txt":"如属当事人一方申请调解的，主管机构有责任通知另一方接受调解，如另一方拒绝接受调解，当事人可直接向人民法院起诉。"},{"i":19,"n":"第十九条","txt":"请求主管机构调解处理的纠纷，当事人必须提交申请书，申请书应写明如下事实： （一）申请人与被申请人的姓名、性别、年龄、职业、住址、邮政编码等（单位的名称、地址、法定代表人的姓名）； （二）申请事项，事实和理由； （三）与事故纠纷有关的证据和其他资料； （四）请求解决的问题。 申请书一式三份，申请人自留一份，两份递交受理机构。"},{"i":20,"n":"第二十条","txt":"主管机构受理污染事故赔偿纠纷后，可根据需要邀请有关部门的人员参加调解处理工作。负责和参加处理纠纷的人员与纠纷当事人有利害关系时，应当自行回避，当事人也可提出回避请求。"},{"i":21,"n":"第二十一条","txt":"主管机构应在收到申请书十日内将申请书副本送达被申请人。被申请人在收到申请书副本之日起十五日内提交答辩书和有关证据。被申请人不按期或不提出答辩书的，视为拒绝调解处理，主管机构应告知申请人向人民法院起诉。"},{"i":22,"n":"第二十二条","txt":"调解处理过程中，应召集双方座谈协商。经协商可达成调解协议。"},{"i":23,"n":"第二十三条","txt":"调解协议书经当事人双方和主管机构三方签字盖章后生效。 当事人拒不履行调解协议的，主管机构应督促履行，同时当事人可向人民法院起诉。"},{"i":24,"n":"第二十四条","txt":"当事人对主管机构调解污染事故赔偿纠纷处理决定不服的，可以向人民法院起诉。"},{"i":25,"n":"第二十五条","txt":"调解处理过程中，当事人一方向法院起诉，调解处理终止。"},{"i":26,"n":"第二十六条","txt":"凡污染造成渔业损害事故的，都应赔偿渔业损失，并由主管机构根据情节依照《渔业行政处罚程序规定》对污染单位和个人给予罚款。"},{"i":27,"n":"第二十七条","txt":"凡污染造成人工增殖和天然渔业资源损失的，按污染对渔业资源的损失及渔业生产的损害程度，由主管机构依照《渔业行政处罚程序规定》责令赔偿渔业资源损失。"},{"i":28,"n":"第二十八条","txt":"本规定中渔业损失的计算，按农业部颁布的《水域污染事故渔业损失计算方法规定》执行。"},{"i":29,"n":"第二十九条","txt":"本规定中事故报告登记表、现场记录、渔业水域污染事故调解协议书等文书格式，由农业部统一制定。"},{"i":30,"n":"第三十条","txt":"本规定由农业部负责解释。"}],"yuyehangbiaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强渔业航标的管理和保护，保障船舶航行与作业安全，根据《中华人民共和国海上交通安全法》、《中华人民共和国航标条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"渔业航标的规划、设置、维护和管理，适用本办法。 本办法所称渔业航标，是指在渔港、进出港航道和渔业水域主要供渔业船舶定位、导航或者用于其他专用目的的助航设施，包括视觉渔业航标、无线电导航设施和音响渔业航标。"},{"i":3,"n":"第三条","txt":"农业部主管全国渔业航标管理和保护工作。 国家渔政渔港监督管理机构具体负责全国渔业航标的管理和保护工作。地方渔政渔港监督管理机构负责本行政区域内渔业航标的管理和保护工作。 农业部、国家渔政渔港监督管理机构和地方渔政渔港监督管理机构统称渔业航标管理机关。"},{"i":4,"n":"第四条","txt":"渔业航标管理机关应当加强渔业航标管理人员的业务培训工作，不断提高管理水平。"},{"i":5,"n":"第五条","txt":"国家渔政渔港监督管理机构负责组织编制、修订和调整全国渔业航标总体规划，报农业部批准。 地方渔业航标管理机关根据需要编制本地渔业航标规划，经省级渔业航标管理机关批准后报国家渔政渔港监督管理机构备案。 地方渔业航标规划应当符合全国渔业航标总体规划的要求。"},{"i":6,"n":"第六条","txt":"渔港水域的渔业航标规划与建设，应当纳入渔港总体规划并与渔港建设同步进行，保证按期投入使用。"},{"i":7,"n":"第七条","txt":"渔业航标由所在地渔业航标管理机关依照规划设置。 因航行安全确需对设置的渔业航标进行调整，已列入全国渔业航标总体规划的，应当报农业部批准；未列入全国渔业航标总体规划的，应当报省级渔业航标管理机关批准。"},{"i":8,"n":"第八条","txt":"经渔业航标管理机关同意，专业单位可以在渔港水域和其他渔业水域设置自用的专用航标。撤除、移动位置或变更专用航标其他状况的，设置单位应当报渔业航标管理机关批准。 设置专用航标，专业单位应当向所在地渔业航标管理机关提出申请，并提交下列书面材料： （一）专业单位法人营业执照复印件； （二）航标的设置方案及可行性报告； （三）航标种类、灯质和设置地点； （四）标体设计和位置图； （五）经费预算及来源； （六）渔业航标管理机关要求的其他材料。 撤除、移动位置或变更专用航标其他状况的，专业单位应当向所在地渔业航标管理机关提供变更原因的说明材料及原专用航标批准设置文件的复印件。"},{"i":9,"n":"第九条","txt":"渔业航标管理机关应当自受理申请之日起20日内作出是否批准的决定。不予批准的，书面通知当事人并说明理由。"},{"i":10,"n":"第十条","txt":"渔业航标管理机关应当加强对专业单位设置、变更专用航标的指导和监督，并及时将专用航标的设置和变更情况报省级渔业航标管理机关备案。"},{"i":11,"n":"第十一条","txt":"渔业航标管理机关设置的渔业航标和专业单位设置的专用航标，应当符合国家有关规定和技术标准。"},{"i":12,"n":"第十二条","txt":"渔业航标管理机关应当及时向有关部门通报渔业航标的设置、撤除或位置移动及其他变更情况。"},{"i":13,"n":"第十三条","txt":"渔业航标管理机关应当建立渔业航标管理档案，内容包括渔业航标设置、改造、维护与管理情况及有关批准文件、技术资料、图纸、维修项目和航行通告等。"},{"i":14,"n":"第十四条","txt":"渔业航标管理机关应当制定渔业航标维护保养计划，定期对渔业航标进行维护保养。 专业单位设置的专用航标，由设置单位负责维护保养。"},{"i":15,"n":"第十五条","txt":"渔业航标初次使用、停用、发生故障或功能改变，所在地渔业航标管理机关应当及时发布航行通告，同时上报省级渔业航标管理机关，以保障船舶航行安全。"},{"i":16,"n":"第十六条","txt":"任何单位或个人发现渔业航标损坏、失常、移位、漂失的，应当及时向所在地渔业航标管理机关报告。"},{"i":17,"n":"第十七条","txt":"任何单位和个人不得在渔业航标附近设置影响渔业航标工作效能的灯光或者其他装置。"},{"i":18,"n":"第十八条","txt":"在视觉渔业航标的通视方向或者无线电导航设施的发射方向，不得构筑影响渔业航标正常工作效能的建筑物、构筑物，不得种植影响渔业航标正常工作效能的植物。"},{"i":19,"n":"第十九条","txt":"因航道改变、被遮挡、背景等原因影响渔业航标导航功能的，渔业航标管理机关应当及时清除影响，必要时应当撤销另设，以保证其正常导航功能。"},{"i":20,"n":"第二十条","txt":"船舶航行、作业或停泊时，应当与渔业航标保持安全距离，避免对渔业航标造成损害。 船舶触碰渔业航标，应当立即向所在地渔业航标管理机关报告。必要时，船舶所有人或经营人应当及时设置临时性渔业助航标志。"},{"i":21,"n":"第二十一条","txt":"进行渔港建设或其他施工作业，需移动或者拆迁渔业航标的，应当经渔业航标管理机关同意，并采取替补措施后，方可移动或拆迁。移动、拆迁费用由工程建设单位承担。 依照前款规定移动或者拆迁渔业航标的，施工单位应当向渔业航标管理机关提交下列书面资料： （一）施工单位法人营业执照复印件； （二）渔业航标移动或者拆迁方案及可行性报告； （三）移动或者拆迁位置图； （四）临时性渔业助航标志设置方案； （五）渔业航标管理机关要求的其他材料。 渔业航标管理机关应当自受理申请之日起20日内作出是否批准的决定，并及时将渔业航标的移动、拆迁和重建情况报省级渔业航标管理机关备案。"},{"i":22,"n":"第二十二条","txt":"在渔港及其航道和其他渔业水域因沉船、沉物导致航行障碍，碍航物所有人或经营人应当立即将碍航物的名称、形状、尺寸、位置、深度等情况准确报告所在地渔业航标管理机关，并设置规定的临时标志或者采取其他应急措施。 碍航物所有人或经营人未采取前款规定措施的，渔业航标管理机关发现后应当立即设置临时标志或者采取其他应急措施，所需费用由碍航物所有人或经营人承担。"},{"i":23,"n":"第二十三条","txt":"禁止下列危害和损坏渔业航标的行为： （一）盗窃、哄抢或者以其他方式非法侵占渔业航标及其器材； （二）非法移动、攀登或者涂抹渔业航标； （三）向渔业航标射击或者投掷物品； （四）在渔业航标上攀架物品，拴系牲畜、船只、渔业捕捞器具、爆炸物品等； （五）损坏渔业航标的其他行为。"},{"i":24,"n":"第二十四条","txt":"禁止破坏渔业航标辅助设施的行为。 前款所称渔业航标辅助设施，是指为渔业航标及其管理人员提供能源、水和其他所需物资而设置的各类设施。"},{"i":25,"n":"第二十五条","txt":"禁止下列影响渔业航标工作效能的行为： （一）在渔业航标周围20米内或者在埋有渔业航标地下管道、线路的地面钻孔、挖坑、采掘土石、堆放物品或者进行明火作业； （二）在渔业航标周围150米内进行爆破作业； （三）在渔业航标周围500米内烧荒； （四）在无线电导航设施附近设置、使用影响导航设施工作效能的高频电磁辐射装置、设备； （五）在渔业航标架空线路上附挂其他电力、通信线路； （六）在渔业航标周围抛锚、拖锚、捕鱼或者养殖水生生物； （七）影响渔业航标工作效能的其他行为。"},{"i":26,"n":"第二十六条","txt":"对有下列行为之一的单位和个人，由渔业航标管理机关给予奖励： （一）检举、控告危害渔业航标的行为，对破案有功的； （二）及时制止危害渔业航标的行为，防止事故发生或者减少损失的； （三）捞获水上漂流渔业航标，主动送交渔业航标管理机关的。"},{"i":27,"n":"第二十七条","txt":"违反本办法第二十二条第一款的规定，不履行报告义务的，由渔业航标管理机关给予警告，可并处2000元以下的罚款。 其他违反本办法规定的行为，由渔业航标管理机关依照《中华人民共和国航标条例》等法律法规的有关规定进行处罚。"},{"i":28,"n":"第二十八条","txt":"本办法自2008年6月1日起施行。"}],"yuyechuanboshuishanganquanshigubaogaohediaochachul229097":[{"i":1,"n":"第一条","txt":"为加强渔业船舶水上安全管理，规范渔业船舶水上安全事故的报告和调查处理工作，落实渔业船舶水上安全事故责任追究制度，根据《中华人民共和国安全生产法》、《中华人民共和国海上交通安全法》、《生产安全事故报告和调查处理条例》、《中华人民共和国渔港水域交通安全管理条例》、《中华人民共和国海上交通事故调查处理条例》和《中华人民共和国内河交通安全管理条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"下列水上安全事故的报告和调查处理，适用本规定： （一）船舶、设施在中华人民共和国渔港水域内发生的水上安全事故； （二）在中华人民共和国渔港水域外从事渔业活动的渔业船舶以及渔业船舶之间发生的水上安全事故。 渔业船舶与非渔业船舶之间在渔港水域外发生的水上安全事故，按照有关规定调查处理。"},{"i":3,"n":"第三条","txt":"本规定所称水上安全事故，包括水上生产安全事故和自然灾害事故。 水上生产安全事故是指因碰撞、风损、触损、火灾、自沉、机械损伤、触电、急性工业中毒、溺水或其他情况造成渔业船舶损坏、沉没或人员伤亡、失踪的事故。 自然灾害事故是指台风或大风、龙卷风、风暴潮、雷暴、海啸、海冰或其他灾害造成渔业船舶损坏、沉没或人员伤亡、失踪的事故。"},{"i":4,"n":"第四条","txt":"渔业船舶水上安全事故分为以下等级： （一）特别重大事故，指造成30人以上死亡、失踪，或100人以上重伤（包括急性工业中毒，下同），或1亿元以上直接经济损失的事故； （二）重大事故，指造成10人以上30人以下死亡、失踪，或50人以上100人以下重伤，或5000万元以上1亿元以下直接经济损失的事故； （三）较大事故，指造成3人以上10人以下死亡、失踪，或10人以上50人以下重伤，或1000万元以上5000万元以下直接经济损失的事故； （四）一般事故，指造成3人以下死亡、失踪，或10人以下重伤，或1000万元以下直接经济损失的事故。"},{"i":5,"n":"第五条","txt":"县级以上人民政府渔业行政主管部门及其所属的渔政渔港监督管理机构（以下统称为渔船事故调查机关）负责渔业船舶水上安全事故的报告。 除特别重大事故外，碰撞、风损、触损、火灾、自沉等水上安全事故，由渔船事故调查机关组织事故调查组按本规定调查处理；机械损伤、触电、急性工业中毒、溺水和其他水上安全事故，经有调查权限的人民政府授权或委托，有关渔船事故调查机关按本规定调查处理。"},{"i":6,"n":"第六条","txt":"渔业船舶水上安全事故报告应当及时、准确、完整，任何单位或个人不得迟报、漏报、谎报或者瞒报。 渔业船舶水上安全事故调查处理应当实事求是、公平公正，在查清事故原因、查明事故性质、认定事故责任的基础上，总结事故教训，提出整改措施，并依法追究事故责任者的责任。"},{"i":7,"n":"第七条","txt":"任何单位和个人不得阻挠、干涉渔业船舶水上安全事故的报告和调查处理工作。"},{"i":8,"n":"第八条","txt":"各级渔船事故调查机关应当建立24小时应急值班制度，并向社会公布值班电话，受理事故报告。"},{"i":9,"n":"第九条","txt":"发生渔业船舶水上安全事故后，当事人或其他知晓事故发生的人员应当立即向就近渔港或船籍港的渔船事故调查机关报告。"},{"i":10,"n":"第十条","txt":"渔船事故调查机关接到渔业船舶水上安全事故报告后，应当立即核实情况，采取应急处置措施，并按下列规定及时上报事故情况： （一）特别重大事故、重大事故逐级上报至农业部及相关海区渔政局，由农业部上报国务院，每级上报时间不得超过1小时； （二）较大事故逐级上报至农业部及相关海区渔政局，每级上报时间不得超过2小时； （三）一般事故上报至省级渔船事故调查机关，每级上报时间不得超过2小时。 必要时渔船事故调查机关可以越级上报。 渔船事故调查机关在上报事故的同时，应当报告本级人民政府并通报安全生产监督管理等有关部门。 远洋渔业船舶发生水上安全事故，由船舶所属、代理或承租企业向其所在地省级渔船事故调查机关报告，并由省级渔船事故调查机关向农业部报告。中央企业所属远洋渔业船舶发生水上安全事故，由中央企业直接报告农业部。"},{"i":11,"n":"第十一条","txt":"渔船事故调查机关接到非本地管辖渔业船舶水上安全事故报告的，应当在1小时内通报该船船籍港渔船事故调查机关，由其逐级上报。"},{"i":12,"n":"第十二条","txt":"渔船事故调查机关上报事故时，应当包括下列内容： （一）接报时间； （二）当事船舶概况及救生、通讯设备配备情况； （三）事故发生时间、地点； （四）事故原因及简要经过； （五）已经造成或可能造成的人员伤亡（包括失踪人数）情况和初步估计的直接经济损失； （六）已经采取的措施； （七）需要上级部门协调的事项； （八）其他应当报告的情况。 情况紧急或短时间内难以掌握事故详细情况的，渔船事故调查机关应当首先报告事故主要情况或已掌握的情况，其他情况待核实后及时补报。重大、特别重大事故应当首先通过电话简要报告，并尽快提交书面报告。事故应急处置结束后，应当及时上报全面情况。"},{"i":13,"n":"第十三条","txt":"渔业船舶在渔港水域外发生水上安全事故，应当在进入第一个港口或事故发生后48小时内向船籍港渔船事故调查机关提交水上安全事故报告书和必要的文书资料。 船舶、设施在渔港水域内发生水上安全事故，应当在事故发生后24小时内向所在渔港渔船事故调查机关提交水上安全事故报告书和必要的文书资料。"},{"i":14,"n":"第十四条","txt":"水上安全事故报告书应当包括以下内容： （一）船舶、设施概况和主要性能数据； （二）船舶、设施所有人或经营人名称、地址、联系方式，船长及驾驶值班人员、轮机长及轮机值班人员姓名、地址、联系方式； （三）事故发生的时间、地点； （四）事故发生时的气象、水域情况； （五）事故发生详细经过（碰撞事故应附相对运动示意图）； （六）受损情况（附船舶、设施受损部位简图），提交报告时难以查清的，应当及时检验后补报； （七）已采取的措施和效果； （八）船舶、设施沉没的，说明沉没位置； （九）其他与事故有关的情况。"},{"i":15,"n":"第十五条","txt":"各级渔船事故调查机关按照以下权限组织调查： （一）农业部负责调查中央企业所属远洋渔业船舶水上安全事故和由国务院授权调查的特别重大事故，以及应当由农业部调查的渔业船舶与外籍船舶发生的水上安全事故； （二）省级渔船事故调查机关负责调查重大事故和辖区内企业所属、代理或承租的远洋渔业船舶水上安全较大、一般事故； （三）市级渔船事故调查机关负责调查较大事故； （四）县级渔船事故调查机关负责调查一般事故。 上级渔船事故调查机关认为有必要时，可以对下级渔船事故调查机关调查权限内的事故进行调查。"},{"i":16,"n":"第十六条","txt":"船舶、设施在渔港水域内发生的水上安全事故，由渔港所在地渔船事故调查机关调查。 渔业船舶在渔港水域外发生的水上安全事故，由船籍港所在地渔船事故调查机关调查。船籍港所在地渔船事故调查机关可以委托事故渔船到达渔港的渔船事故调查机关调查。不同船籍港渔业船舶间发生的事故由共同上一级渔船事故调查机关或其指定的渔船事故调查机关调查。"},{"i":17,"n":"第十七条","txt":"根据调查需要，渔船事故调查机关有权开展以下工作： （一）调查、询问有关人员； （二）要求被调查人员提供书面材料和证明； （三）要求当事人提供航海日志、轮机日志、报务日志、海图、船舶资料、航行设备仪器的性能以及其他必要的文书资料； （四）检查船舶、船员等有关证书，核实事故发生前船舶的适航状况； （五）核实事故造成的人员伤亡和财产损失情况； （六）勘查事故现场，搜集有关物证； （七）使用录音、照相、录像等设备及法律允许的其他手段开展调查。"},{"i":18,"n":"第十八条","txt":"渔船事故调查机关开展调查，应当由两名以上调查人员共同参加，并向被调查人员出示证件。 调查人员应当遵守相关法律法规和工作纪律，全面、客观、公正开展调查。 未经授权，调查人员不得发布事故有关信息。"},{"i":19,"n":"第十九条","txt":"事故当事人和有关人员应当配合调查，如实陈述事故的有关情节，并提供真实的文书资料。"},{"i":20,"n":"第二十条","txt":"渔船事故调查机关因调查需要，可以责令当事船舶驶抵指定地点接受调查。除危及自身安全的情况外，当事船舶未经渔船事故调查机关同意，不得驶离指定地点。"},{"i":21,"n":"第二十一条","txt":"渔船事故调查机关应当自接到事故报告之日起60日内制作完成水上安全事故调查报告。 特殊情况下，经上一级渔船事故调查机关批准，可以延长事故调查报告完成期限，但延长期限不得超过60日。 检验或鉴定所需时间不计入事故调查期限。"},{"i":22,"n":"第二十二条","txt":"水上安全事故调查报告应当包括以下内容： （一）船舶、设施概况和主要性能数据； （二）船舶、设施所有人或经营人名称、地址和联系方式； （三）事故发生时间、地点、经过、气象、水域、损失等情况； （四）事故发生原因、类型和性质； （五）救助及善后处理情况； （六）事故责任的认定； （七）要求当事人采取的整改措施； （八）处理意见或建议。"},{"i":23,"n":"第二十三条","txt":"渔船事故调查机关经调查，认定渔业船舶水上安全事故为自然灾害事故的，应当报上一级渔船事故调查机关批准。 在能够预见自然灾害发生或能够避免自然灾害不良后果的情况下，未采取应对措施或应对措施不当，造成人员伤亡或直接经济损失的，应当认定为渔业船舶水上生产安全事故。"},{"i":24,"n":"第二十四条","txt":"渔船事故调查机关应当自调查报告制作完成之日起10日内向当事人送达调查结案报告，并报上一级渔船事故调查机关。属于非本船籍港渔业船舶事故的，应当抄送当事船舶船籍港渔船事故调查机关。属于渔港水域内非渔业船舶事故的，应当抄送同级相关部门。"},{"i":25,"n":"第二十五条","txt":"在入渔国注册并悬挂该国国旗的远洋渔业船舶发生的水上安全事故，在入渔国相关部门调查处理后，远洋渔业船舶所属、代理或承租企业应当将调查结果经所在地省级渔船事故调查机关上报农业部。"},{"i":26,"n":"第二十六条","txt":"渔船事故调查机关应当按照有关规定归档保存水上安全事故报告书和水上安全事故调查报告等调查材料。"},{"i":27,"n":"第二十七条","txt":"对渔业船舶水上安全事故负有责任的人员和船舶、设施所有人、经营人，由渔船事故调查机关依据有关法律法规和《中华人民共和国渔业港航监督行政处罚规定》给予行政处罚，并可建议有关部门和单位给予处分。 对渔业船舶水上安全事故负有责任的人员不属于渔船事故调查机关管辖范围的，渔船事故调查机关可以将有关情况通报有关主管机关。"},{"i":28,"n":"第二十八条","txt":"根据渔业船舶水上安全事故发生的原因，渔船事故调查机关可以责令有关船舶、设施的所有人、经营人限期加强对所属船舶、设施的安全管理。对拒不加强安全管理或在期限内达不到安全要求的，渔船事故调查机关有权禁止有关船舶、设施离港，或责令其停航、改航、停止作业，并可依法采取其他必要的强制处置措施。"},{"i":29,"n":"第二十九条","txt":"渔业船舶水上安全事故当事人和有关人员涉嫌犯罪的，渔船事故调查机关应当依法移送司法机关追究刑事责任。"},{"i":30,"n":"第三十条","txt":"因渔业船舶水上安全事故引起的民事纠纷，当事人各方可以在事故发生之日起30日内，向负责事故调查的渔船事故调查机关共同书面申请调解。 已向仲裁机构申请仲裁或向人民法院提起诉讼，当事人申请调解的，不予受理。"},{"i":31,"n":"第三十一条","txt":"渔船事故调查机关开展调解，应当遵循公平自愿的原则。"},{"i":32,"n":"第三十二条","txt":"经调解达成协议的，当事人各方应当共同签署《调解协议书》，并由渔船事故调查机关签章确认。"},{"i":33,"n":"第三十三条","txt":"《调解协议书》应当包括以下内容： （一）当事人姓名或名称及住所； （二）法定代表人或代理人姓名及职务； （三）纠纷主要事实； （四）事故简况； （五）当事人责任； （六）协议内容； （七）调解协议履行的期限。"},{"i":34,"n":"第三十四条","txt":"已向渔船事故调查机关申请调解的民事纠纷，当事人中途不愿调解的，应当递交终止调解的书面申请，并通知其他当事人。"},{"i":35,"n":"第三十五条","txt":"自受理调解申请之日起3个月内，当事人各方未达成调解协议的，渔船事故调查机关应当终止调解，并告知当事人可以向仲裁机构申请仲裁或向人民法院提起诉讼。"},{"i":36,"n":"第三十六条","txt":"本规定第二条第一款中设施是指水上水下各种固定或浮动建筑、装置和固定平台。"},{"i":37,"n":"第三十七条","txt":"本规定第三条第二款中下列事故类型的含义： （一）碰撞，指船舶与船舶或船舶与排筏、水上浮动装置发生碰撞造成船舶损坏、沉没或人员伤亡、失踪，以及船舶航行产生的浪涌致使他船损坏、沉没或人员伤亡、失踪； （二）风损，指准许航行作业区为沿海航区（Ⅲ类）、近海航区（Ⅱ类）、远海航区（Ⅰ类）的渔业船舶分别遭遇八级、十级和十二级以下风力造成损坏、沉没或人员伤亡、失踪； （三）触损，指船舶触碰岸壁、码头、航标、桥墩、钻井平台等水上固定物和沉船、木桩、渔栅、潜堤等水下障碍物，以及船舶触碰礁石或搁置在礁石、浅滩上，造成船舶损坏、沉没或人员伤亡、失踪； （四）火灾，指船舶因非自然因素失火或爆炸，造成船舶损坏、沉没或人员伤亡、失踪； （五）自沉，指船舶因超载、装载不当、船体漏水等原因或不明原因，造成船舶沉没，人员伤亡、失踪； （六）机械损伤，指影响适航性能的船舶机件或重要属具的损坏、灭失，以及操作和使用机械或网"},{"i":38,"n":"第三十八条","txt":"本规定第三条第三款中下列事故类型的含义： （一）台风或大风，指在准许航行作业区为沿海航区（Ⅲ类）、近海航区（Ⅱ类）、远海航区（Ⅰ类）的渔业船舶分别遭遇八级、十级和十二级以上风力袭击，或在港口、锚地遭遇超过港口规定避风等级的风力袭击，或遭遇Ⅱ级警报标准以上海浪袭击，造成渔业船舶损坏、沉没或人员伤亡、失踪。 （二）龙卷风，指渔业船舶遭遇龙卷风袭击，造成渔业船舶损坏、沉没或人员伤亡、失踪。 （三）风暴潮，指渔业船舶在港口、锚地遭遇Ⅱ级警报标准以上风暴潮袭击，造成渔业船舶损坏、沉没或人员伤亡、失踪。 （四）雷暴，指渔业船舶遭遇雷电袭击，引起火灾、爆炸，造成渔业船舶损坏、沉没或人员伤亡、失踪。 （五）海啸，指渔业船舶遭遇Ⅱ级警报标准以上海啸袭击，造成渔业船舶损坏、沉没或人员伤亡、失踪。 （六）海冰，指渔业船舶在海（水）上遭遇预警标准以上海冰、冰山、凌汛袭击，造成渔业船舶损坏、沉没或人员伤亡、失踪"},{"i":39,"n":"第三十九条","txt":"渔业船舶水上安全事故报告和调查处理文书表格格式，由农业部统一制定。"},{"i":40,"n":"第四十条","txt":"本规定所称的“以上”包括本数，“以下”不包括本数。"},{"i":41,"n":"第四十一条","txt":"本规定自2013年2月1日起施行，1991年3月5日农业部发布、1997年12月25日修订的《中华人民共和国渔业海上交通事故调查处理规则》同时废止。"}],"yuyechuanbohangxingzhibanzhunze":[{"i":1,"n":"第一条","txt":"为保证渔业船舶航行作业的安全，规范渔业船舶值班标准，保护海洋环境，根据《中华人民共和国海上交通安全法》、《中华人民共和国海洋环境保护法》和《中华人民共和国渔港水域交通安全管理条例》制定本准则。"},{"i":2,"n":"第二条","txt":"渔业船舶所有人应根据本准则，并结合所属船舶的具体情况做到： 1.渔船所有值班人员都必须根据国家有关规定持有相应证书； 2.编制船舶的航行值班规则，并报所在地渔港监督机关批准； 3.值班规则应悬挂在船舶驾驶室、轮机舱和无线电通信室内，并确保船长和相应的值班人员遵守； 4.保证船长能组织和领导船上的一切工作，船长和其他所有船员都必须按国家有关规定进行培训、考试，并持有相应证书； 5.船上安装的通信和助航仪器以及保障船舶安全航行的任何设备都必须处于正常的使用状态。"},{"i":3,"n":"第三条","txt":"船长应当保证： 1.所有值班人员必须由持有相应适任证书的职务船员担任； 2.除航行值班人员外其他人员不得随意进入驾驶室； 3.所有值班人员上岗前必须经过充分休息，不能因值班人员疲劳而影响航行安全； 4.在航行期间值班人员不得饮酒； 5.不得安排正在值班的值班人员从事与值班无关的事项。"},{"i":4,"n":"第四条","txt":"船长和值班人员应有良好的职业道德，遇有海难事故时，在不危及本船安全的情况下，应全力进行救助。"},{"i":5,"n":"第五条","txt":"船长和值班人员应遵守国际、国内有关法律、法规、规章和当地港口港章的有关规定。并应采取一切可能的预防措施，防止污染海洋。"},{"i":6,"n":"第六条","txt":"值班驾驶员、轮机员和无线电报（话）务员必须按要求，及时和如实记录航海日志、渔捞日志、轮机日志。航海日志、渔捞日志和轮机日志记载的内容必须与船舶实际动态相符。"},{"i":7,"n":"第七条","txt":"本准则适用于24米及以上渔业船舶。24米以下渔业船舶可由省级渔港监督机关参照本准则和其作业范围及作业特点制定，报中华人民共和国渔政渔港监督管理局备案。"},{"i":8,"n":"第八条","txt":"航行值班要求： 1.渔船离港前，船长应主持研究本航次与航行有关的航海资料、制定安全可靠的航行计划。航行中应尽可能实施预定的航行计划； 2.渔船航行和作业时，只有船长或值班驾驶员才有权下达舵令；操舵员接到命令后要复诵舵令，执行完舵令后要报告；值班驾驶员接到报告后要回答。命令、复诵、报告和回答要清楚响亮（舵令、复诵、报告和回答词见附表一）； 3.在任何时候，驾驶室内必须有人值班，并在整个值班时间内保持正规了望；在夜间航行时驾驶台和有碍值班人员了望的灯光要进行管制； 4.正规了望应包括下列内容： （1）利用视觉、听觉和其他一切有效手段，持续地保持警惕状态，细心观察周围情况、海面漂浮物、周围环境、包括附近陆标和船舶动态等； （2）密切观测周围船舶相对方位的变化和动态； （3）正确辨别各种船舶灯光信号，核实浮标编号、灯标性质与岸灯等； （4）观察天气变化、风情、波浪，特别是能见度的变化等； （5"},{"i":9,"n":"第九条","txt":"渔船捕捞作业值班及要求： 1.拖网渔船作业时，应由船长、大副轮流值班，二副执行短程转移渔场时的值班；围网船作业，航测鱼群时，由船长、大副、二副轮流值班。不论何种作业方式，起放网时应由船长值班； 2.渔船在进行捕捞作业时，值班驾驶员除应考虑第八条所规定的内容外，还应考虑下列因素并正确地采取行动： （1）船舶操纵性能、尤其是停船距离、航行和拖带渔具作业时的回转半径； （2）甲板上船员的安全； （3）因捕捞作业、渔获物装卸和积载，异常海况和天气状况等而产生的外力对船舶安全带来的不利影响，以及稳性和干舷的降低对渔船安全带来的不利影响； （4）附近海上建筑物的安全区域、沉船和其他危及渔具的水下障碍物； （5）在装载渔获物时，应注意在整个航行期间内都应留有充分的干舷、保持渔船稳性和水密性，还应考虑燃料和备用品的消耗、可能遇到的异常天气状况和甲板连续结冰可能导致的危险。"},{"i":10,"n":"第十条","txt":"航道及有明确规定不得锚泊的水域不得锚泊：锚泊时要考虑水流、风向和潮汐情况，并检查周围水域是否有暗礁、沉船、水中障碍等危险物存在。"},{"i":11,"n":"第十一条","txt":"锚泊后要根据《1972年国际海上避碰规则》的要求，显示号灯、号型和呜放声号。"},{"i":12,"n":"第十二条","txt":"在锚泊期间，值班驾驶员要经常了解： 1.锚泊时的船位，经常检查船位的变化，检查是否有走锚的现象； 2.了解和观测气象、风向、风力、海流和潮汐情况的变化，并要及时根据风向、风力、潮汐、海流等的变化调整锚链； 3.密切注意周围船舶的动态，遇有可能迫近的危险时，要按《1972年国际海上避碰规则》的规定发出声、光信号。"},{"i":13,"n":"第十三条","txt":"发现走锚或危险迫近时，应立即通知船长，并不失时机地通知机舱备车和全船人员，特别是恶劣天气应提前通知。"},{"i":14,"n":"第十四条","txt":"交接班时，接班人员应提前10分钟上驾驶台做好接班准备。交班人员要确信接班者头脑清醒，并适应了驾驶台的环境后，方可办理交按班手续。"},{"i":15,"n":"第十五条","txt":"交接班时，必须交清以下内容： 1.船位、拖网与放网时间、航向、拖向、拖速、流速、风速、风、流压差等； 2.各种助航、助渔仪器的使用情况； 3.对拖网的主、副船或围网船和灯光船之间的动态，周围船舶的动态； 4.在望或即将在望的岛屿、航标、水面障碍物及海图标注的附近暗礁、沉船、水中障碍物等情况； 5.天气与海况变化； 6.航标的识别，下一班可能遇到的危险及有关注意事项的建议； 7.船长布置的且下一班应知道的事项，航行计划的变化和航海警告、通告等。"},{"i":16,"n":"第十六条","txt":"值班驾驶员遇有列情况不得交班： 1.正在采取避让措施时； 2.正在进行起、放网作业时； 3.接班人员不称职； 4.没有找到转向目标或船位不清； 5.接班者没有完全理解交班内容时。"},{"i":17,"n":"第十七条","txt":"在交接班过程中不免除原值班人员的值班责任。"},{"i":18,"n":"第十八条","txt":"船长应保证船舶在停港或航行期间，机舱始终有轮机人员值班，严格服从驾驶台的指令。如果发现机舱有影响航行安全和可能污染海洋的问题时，轮机值班人员要立刻通知驾驶台。"},{"i":19,"n":"第十九条","txt":"渔船出航前，船长应提前通知轮机长，轮机长接到指令后，应立即通知机舱和机电人员到位，并按照各自分工对机械设备、燃料、备件、工具等进行检查，出航前一个小时，备好车并通知船长。"},{"i":20,"n":"第二十条","txt":"航行和作业期间，机舱值班员严格遵守操作规程，经常检查主、辅机及其它机械运转情况，并保持机舱所有机械始终处于正常工作状态。并在轮机日志记录各种数据。如有异常，要及时处理，自己不能处理或对处理有疑问，应立即通知轮机长，如有必要还应直接通知驾驶室。"},{"i":21,"n":"第二十一条","txt":"轮机值班员在交接班时，必须交清下列情况： 1.主机、发电机、其它辅助机械及仪器、仪表的工作情况； 2.各种电压及油、水及排烟温度、压力情况； 3.轮机长有关指示和注意事项； 4.其他需要交待的情况。"},{"i":22,"n":"第二十二条","txt":"机舱值班员必须服从驾驶室的指令。"},{"i":23,"n":"第二十三条","txt":"按照无线电管理委员会的有关要求，船上无线电报务员或话务员应在船长的统一领导下，坚持值班，保持在各种情况下的无线电报或话务通畅。"},{"i":24,"n":"第二十四条","txt":"航海日志和轮机日志必须使用我部规定的统一格式。"},{"i":25,"n":"第二十五条","txt":"本准则自2000年6月1日起执行，由农业部负责解释。"}],"yuyechuanbochuanmingguiding":[{"i":1,"n":"第一条","txt":"为加强渔业船舶的监督管理工作，规范渔业船舶船名，根据《中华人民共和国海商法》、《中华人民共和国渔业船舶登记办法》等有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"凡具有中华人民共和国国籍的渔业船舶均应依照本规定标写船名、船籍港和悬挂船名牌。"},{"i":3,"n":"第三条","txt":"渔业船舶船名由以下4部分依次组成： （一）省（自治区、直辖市）名称的规范化简称。 （二）渔业船舶所在县（市、区）名称的规范化简称，取第一个汉字，如果第一个汉字与本省其他县（市、区）名称相同，则取前两个汉字。 （三）船舶种类（或用途）的代称： 1．捕捞船用“渔”； 2．养殖船用“渔养”； 3．渔业指导船用“渔指”； 4．供油船用“渔油”； 5．供水船用“渔水”； 6．渔业运输船用“渔运”； 7．渔业冷藏船用“渔冷”； 其他种类的渔业船舶由各省级渔业船舶登记机关规定，报中华人民共和国渔政局备案。 （四）顺序号由5位数的数码组成。"},{"i":4,"n":"第四条","txt":"国有渔业企业的渔业船舶的船名，可以用本企业名称的简称代替省、自治区、直辖市名称的简称和本企业所在县（市、区）名称的简称。"},{"i":5,"n":"第五条","txt":"远洋渔业船舶、科研船和教学实习船的船名，由简体汉字或‘简体汉字’和‘数字’依次组成。 国内现有捕捞渔船依法从事远洋作业的，船名保持不变。 前款规定的船名不得与登记在先的船舶同名或同音。"},{"i":6,"n":"第六条","txt":"渔政船、渔监船等国家公务船的船名，由其主管机关规定。"},{"i":7,"n":"第七条","txt":"渔业船舶取得船名后，应当在船首两舷和船尾部标写船名和船籍港名称。船首两侧的船名从左至右横向标写；船籍港名称应在船尾部中央从左至右水平标写。"},{"i":8,"n":"第八条","txt":"船名和船籍港名称的标写颜色为黑底白字，如果船体漆的颜色与白色反差较大，也可以以船体漆的颜色为底色。标写字型均为仿宋体，字迹必须工整、清晰。字体大小视船型而定，但船名字体尺寸不应小于300毫米×300毫米，船籍港的字体尺寸不应小于200毫米×200毫米。"},{"i":9,"n":"第九条","txt":"渔业船舶应当在驾驶台顶部两侧悬挂船名牌。船名牌制作要求如下： （一）颜色为蓝底白字； （二）形状为圆角矩形； （三）船名牌的型号分为ⅰ、ⅱ和ⅲ型。使用范围如下∶ 1．船长大于24米的渔业船舶使用ⅰ型牌； 2．船长在12至24米之间渔业船舶使用ⅱ型牌； 3．船长小于12米的渔业船舶使用ⅲ型牌。 （四）船牌内汉字采用仿宋体。 （五）ⅰ型船牌外型尺寸为：1400毫米×330毫米； ⅱ型船牌外型尺寸为：1000毫米×300毫米； ⅲ型船牌的规格由各省级渔业船舶登记机关规定。报中华人民共和国渔政渔港监督管理局备案。 （六）船名牌可以使用铝板、木板或玻璃钢板制作。 （七）ⅰ型船牌由海区渔政渔港监督管理局负责统一制做。"},{"i":10,"n":"第十条","txt":"船名牌必须固定安装，并保持完整无损，不得被其他物体遮挡。发现损坏、褪色等可能影响船名牌显示效能的情况时，应及时修复或更换。"},{"i":11,"n":"第十一条","txt":"本规定由农业部负责解释。"},{"i":12,"n":"第十二条","txt":"本规定自颁布之日起执行。"},{"i":13,"n":"第十三条","txt":"原农林部颁布的《关于渔船统一编号的通知》[（75）农林（渔）字第34号]从本规定颁布之日起废止。"}],"yuyexingzhengchufaguiding":[{"i":1,"n":"第一条","txt":"为严格执行渔业法律法规，规范渔业行政处罚，保障渔业生产者的合法权益，根据《中华人民共和国渔业法》（以下简称《渔业法》）《中华人民共和国渔业法实施细则》（以下简称《实施细则》）和《中华人民共和国行政处罚法》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"对渔业违法的行政处罚有以下种类： （一）罚款； （二）没收渔获物、违法所得、渔具； （三）暂扣、吊销捕捞许可证等渔业证照； （四）法律、法规规定的其他处罚。"},{"i":3,"n":"第三条","txt":"渔业违法行为轻微并及时改正，没有造成危害后果的，不予处罚。初次实施渔业违法行为且危害后果轻微并及时改正的，可以不予处罚。当事人有证据足以证明没有主观过错的，不予行政处罚。对当事人的违法行为依法不予行政处罚的，应当对当事人进行教育。有下列行为之一的，应当从轻或者减轻处罚： （一）主动消除或减轻渔业违法行为后果； （二）受他人胁迫或者诱骗实施渔业违法行为的； （三）主动供述渔业执法部门尚未掌握的违法行为的； （四）配合渔业执法部门查处渔业违法行为有立功表现的； （五）依法应当从轻、减轻的其他渔业违法行为。"},{"i":4,"n":"第四条","txt":"有下列行为之一的，从重处罚： （一）一年内渔业违法三次以上的； （二）对渔业资源破坏程度较重的； （三）渔业违法影响较大的； （四）同一个违法行为违反两项以上规定的； （五）逃避、抗拒检查的。"},{"i":5,"n":"第五条","txt":"本规定中需要处以罚款的计罚单位如下： （一）拖网、流刺网、钓钩等用船作业的，以单艘船计罚； （二）围网作业，以一个作业单位计罚； （三）定置作业，用船作业的以单艘船计罚，不用船作业的以一个作业单位计罚； （四）炸鱼、毒鱼、非法电力捕鱼和使用鱼鹰捕鱼的，用船作业的以单艘船计罚，不用船作业的以人计罚； （五）从事赶海、潜水等不用船作业的，以人计罚。"},{"i":6,"n":"第六条","txt":"依照《渔业法》第三十八条和《实施细则》第二十九条规定，有下列行为之一的，没收渔获物和违法所得，处以罚款；情节严重的，没收渔具、吊销捕捞许可证；情节特别严重的，可以没收渔船。罚款按以下标准执行： （一）使用炸鱼、毒鱼、电鱼等破坏渔业资源方法进行捕捞的，违反关于禁渔区、禁渔期的规定进行捕捞的，或者使用禁用的渔具、捕捞方法和小于最小网目尺寸的网具进行捕捞或者渔获物中幼鱼超过规定比例的，在内陆水域，处以三万元以下罚款；在海洋水域，处以五万元以下罚款。 （二）敲䑩作业的，处以一千元至五万元罚款。 （三）擅自捕捞国家规定禁止捕捞的珍贵、濒危水生动物，按《中华人民共和国野生动物保护法》和《中华人民共和国水生野生动物保护实施条例》执行。 （四）未经批准使用鱼鹰捕鱼的，处以五十元至二百元罚款。 在长江流域水生生物保护区内从事生产性捕捞，或者在长江干流和重要支流、大型通江湖泊、长江河口规定区域等重点水域禁"},{"i":7,"n":"第七条","txt":"按照《渔业法》第三十九条规定，对偷捕、抢夺他人养殖的水产品的，或者破坏他人养殖水体、养殖设施的，责令改正，可以处二万元以下的罚款；造成他人损失的，依法承担赔偿责任。"},{"i":8,"n":"第八条","txt":"按照《渔业法》第四十一条规定，对未取得捕捞许可证擅自进行捕捞的，没收渔获物和违法所得，并处罚款；情节严重的，并可以没收渔具和渔船。罚款按下列标准执行： （一）在内陆水域，处以五万元以下罚款。 （二）在海洋水域，处以十万元以下罚款。 无正当理由不能提供渔业捕捞许可证的，按本条前款规定处罚。"},{"i":9,"n":"第九条","txt":"按照《渔业法》第四十二条规定，对有捕捞许可证的渔船违反许可证关于作业类型、场所、时限和渔具数量的规定进行捕捞的，没收渔获物和违法所得，可以并处罚款；情节严重的，并可以没收渔具，吊销捕捞许可证。罚款按以下标准执行： （一）在内陆水域，处以二万元以下罚款。 （二）在海洋水域，处以五万元以下罚款。"},{"i":10,"n":"第十条","txt":"按照《渔业法》第四十三条规定，对涂改、买卖、出租或以其他形式非法转让捕捞许可证的，没收违法所得，吊销捕捞许可证，可以并处罚款。罚款按以下标准执行： （一）买卖、出租或以其他形式非法转让捕捞许可证的，对违法双方各处一万元以下罚款。 （二）涂改捕捞许可证的，处一万元以下罚款。"},{"i":11,"n":"第十一条","txt":"按照《中华人民共和国水污染防治法》第九十四条、《中华人民共和国海洋环境保护法》第九十条规定，造成渔业污染事故的，按以下规定处以罚款： （一）对造成一般或者较大污染事故，按照直接损失的百分之二十计算罚款。 （二）对造成重大或者特大污染事故的，按照直接损失的百分之三十计算罚款。"},{"i":12,"n":"第十二条","txt":"捕捞国家重点保护的渔业资源品种中未达到采捕标准的幼体超过规定比例的，没收超比例部分幼体，并可处以三万元以下罚款；从重处罚的，可以没收渔获物。"},{"i":13,"n":"第十三条","txt":"违反《渔业法》第三十一条和《实施细则》第二十四条、第二十五条规定，擅自捕捞有重要经济价值的水生动物苗种、怀卵亲体的，没收其苗种或怀卵亲体及违法所得，并可处以三万元以下罚款。"},{"i":14,"n":"第十四条","txt":"外商投资渔业企业的渔船，违反《实施细则》第十六条的规定，未经国务院有关主管部门批准，擅自从事近海捕捞的，依照《实施细则》第三十六条的规定，没收渔获物和违法所得，并可处以三千元至五万元罚款。"},{"i":15,"n":"第十五条","txt":"外国人、外国渔船违反《渔业法》第四十六条规定，擅自进入中华人民共和国管辖水域从事渔业生产或渔业资源调查活动的，责令其离开或将其驱逐，可以没收渔获物、渔具，并处五十万元以下的罚款；情节严重的，可以没收渔船；涉嫌犯罪的，及时将案件移送司法机关，依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"我国渔船违反我国缔结、参加的国际渔业条约和违反公认的国际关系准则的，可处以罚款。"},{"i":17,"n":"第十七条","txt":"违反《实施细则》第二十六条，在鱼、虾、贝、蟹幼苗的重点产区直接引水、用水的，未采取避开幼苗密集区、密集期或设置网栅等保护措施的，可处以一万元以下罚款。"},{"i":18,"n":"第十八条","txt":"按照《渔业法》第三十八条、第四十一条、第四十二条、第四十三条规定需处以罚款的，除按本规定罚款外，依照《实施细则》第三十四条规定，对船长或者单位负责人可视情节另处一百元至五百元罚款。"},{"i":19,"n":"第十九条","txt":"凡无船名号、无船舶证书，无船籍港而从事渔业活动的船舶，可对船主处以船价两倍以下的罚款，并可予以没收。凡未履行审批手续非法建造、改装的渔船，一律予以没收。"},{"i":20,"n":"第二十条","txt":"在海上执法时，对违反禁渔区、禁渔期的规定或者使用禁用的渔具、捕捞方法进行捕捞，以及未取得捕捞许可证进行捕捞的，事实清楚、证据充分，但是当场不能按照法定程序作出和执行行政处罚决定的，可以先暂时扣押捕捞许可证、渔具或者渔船，回港后依法作出和执行行政处罚决定。"},{"i":21,"n":"第二十一条","txt":"本规定由农业农村部负责解释。"}],"yugangfeishouguiding":[{"i":1,"n":"第一条","txt":"为保障渔港及渔港水域正常航行与作业秩序，充分发挥渔港效能，保证渔业航标等安全设施处于正常使用状态和保护渔港水域环境，制定本规定。"},{"i":2,"n":"第二条","txt":"凡进出渔港的船舶均应按本规定缴纳各项费用。从事非生产性经营或营利性服务的下列船舶除外： （一）国家公务船舶； （二）体育运动船； （三）科研调查船； （四）教学实习船。"},{"i":3,"n":"第三条","txt":"渔港费用由中华人民共和国渔港监督机关负责征收、使用和管理。"},{"i":4,"n":"第四条","txt":"计费单位： （一）机动捕捞渔船以主推进动力装置总功率为计费单位； （二）非机动捕捞渔船和渔业辅助船舶以净吨（无净吨的按载重吨，拖轮按主推进动力装置总功率）为计费单位。"},{"i":5,"n":"第五条","txt":"进整办法： （一）船舶以主推进动力装置功率为计费单位的，不足1千瓦按1千瓦计；以净吨（无净吨按载重吨）为计费单位的，不足1吨按1吨计。 （二）以月为计费单位的，按日历月计，不足1个月的，未超过当月15日的，按半个月计，超过的按1个月计；以小时为计费单位的，不足1小时按1小时计。 （三）以次为计费单位的，每进入或每驶出渔港各为一次计。 （四）货物的重量按毛重（包括包装重量）计算，以吨为计费单位。 （五）面积以平方米为计费单位，不足1平方米的按1平方米计。"},{"i":6,"n":"第六条","txt":"非渔业船舶的计费方法和计费标准可参照交通部门的有关规定执行。"},{"i":7,"n":"第七条","txt":"机动捕捞渔船每进港或出港一次，各按主推进动力装置总功率每千瓦征收船舶港务费0.10元；非机动捕捞船舶和渔业辅助船舶每进港或出港一次，各按船舶净吨（无净吨的按载重吨，拖轮按主推进动力装置总功率）每吨征收船舶港务费0.15元。征收办法如下： （一）本船籍港的渔业船舶，按每艘每月进入和驶出渔港各一次计收船舶港务费。机动渔业船舶最低收费每月每艘13元；非机动渔业船舶每月每艘8元。按季度或年度缴纳。 （二）非本船籍港的渔业船舶：机动渔业船舶最低收费每次每艘4元；非机动渔业船舶最低收费每次每艘2元。 非本船籍港的捕捞渔船，最多按每月进入和驶出渔港各二次计收船舶港务费。"},{"i":8,"n":"第八条","txt":"主推进动力装置总功率为351千瓦及以上机动捕捞渔船，超过部分减半收费。"},{"i":9,"n":"第九条","txt":"渔业船舶在港内停泊超过24小时的，每超过24小时（不足24小时的按24小时计），按以下标准加收停泊费： （一）机动渔业船舶按主推进动力装置总功率每千瓦0.03元，最低收费4元。 （二）非机动渔业船舶每净吨0.02元，最低收费2元。本船籍港的渔业船舶不再缴纳停泊费。"},{"i":10,"n":"第十条","txt":"经渔港监督机关批准在渔港内设置的养殖、海鲜酒舫等生产和服务设施，按其占用的水域面积每平方米每月征收停泊费0.10元。"},{"i":11,"n":"第十一条","txt":"船舶靠泊渔港码头超过6小时的，每超过6小时，按船舶港务费加收25%的停泊费；不足6小时的按6小时计算，以此类推。 本船籍港的渔业船舶靠泊渔港码头，24小时内免缴靠泊费；超过24小时的，超过部分按本条第一款规定缴纳靠泊费。"},{"i":12,"n":"第十二条","txt":"货物港务费：装卸每1吨货物（本船渔获物除外）收取0.20元，危险货物加倍收取。 本船籍港的渔业船舶不再缴纳货物港务费。"},{"i":13,"n":"第十三条","txt":"因紧急避险、接送伤病员进港的船舶，在险情解除24小时以后或送走伤病员4小时以后，开始按规定计收相应费用。但如在免缴费期间内从事补给或装卸货物，应按规定缴纳有关费用。"},{"i":14,"n":"第十四条","txt":"渔业船舶应当在规定的期限内缴纳渔港费用，逾期不缴纳的，由渔港监督机关依法申请人民法院强制执行，并可禁止其离港。"},{"i":15,"n":"第十五条","txt":"本船籍港的渔业船舶因自然灾害或航行事故造成严重经济损失的，可按月向本船船籍港的渔港监督机关申请减（免）缴或缓缴船舶港务费。经批准者，批准机关应在其航行签证簿中载明减（免）缴或缓缴的原因、时间和金额，并加盖财务印章。"},{"i":16,"n":"第十六条","txt":"渔港费收应按照规定的用途专款专用，其使用范围是： （一）渔港及渔港设施的管理和维护。 （二）渔业部门设置的航标和其他渔港水上交通安全设施的管理、维护和保养。 （三）渔港水域环境的监测和保护。"},{"i":17,"n":"第十七条","txt":"各级渔港监督机关应建立健全财务制度，不得擅自增加收费项目、提高收费标准。上级渔港监督机关有权监督检查下级渔港监督机关的渔港费用的征收、使用和管理工作。"},{"i":18,"n":"第十八条","txt":"各级渔业主管部门、物价管理部门及渔港监督机关应严格执行本规定。本规定自1993年12月1日起施行。"}],"yuchuanzuoyebirangguiding":[{"i":1,"n":"第一条","txt":"本规定适用于我国正在从事海上捕捞的船舶。"},{"i":2,"n":"第二条","txt":"本规定以不违背《1972年国际海上避碰规则》（以下简称《72规则》）为原则，从事各种捕捞作业的船舶除严格遵行《72规则》外，还必须遵守本规定。"},{"i":3,"n":"第三条","txt":"本规定各条不妨碍有关主管机关制定的渔业法规的实行。"},{"i":4,"n":"第四条","txt":"在解释和遵行本规定各条规定时，应适当考虑到当时渔场的特殊情况或其他原因，为避免发生网具纠缠、拖损或船舶发生碰撞的危险，而采取与本规定各条规定相背离的措施。"},{"i":5,"n":"第五条","txt":"本规定各条不免除任何从事捕捞作业中的船舶或当事船长、船员、船舶所属单位对执行本规定各条的任何疏忽而产生的各种后果应负担的责任。"},{"i":6,"n":"第六条","txt":"本规定除第六章能见度不良时的行动规则外，其他各章都为互见中的行动规则。"},{"i":7,"n":"第七条","txt":"本规定所指的避让行动，包括避让船舶及其渔具。"},{"i":8,"n":"第八条","txt":"本规定的解释权属于中华人民共和国农牧渔业部。"},{"i":9,"n":"第九条","txt":"拖网渔船应给下列渔船让路： 1.从事定置渔具捕捞的渔船； 2.漂流渔船； 3.围网渔船。"},{"i":10,"n":"第十条","txt":"围网渔船和漂流渔船应避让从事定置渔具捕捞的渔船。"},{"i":11,"n":"第十一条","txt":"各类渔船在放网过程中，后放网的船应避让先放网的船，并不得妨碍其正常作业。"},{"i":12,"n":"第十二条","txt":"正常作业的渔船，应避让作业中发生故障的渔船。"},{"i":13,"n":"第十三条","txt":"各类渔船在起、放渔具过程中，应保持一定的安全距离。"},{"i":14,"n":"第十四条","txt":"在按本规定采取避让措施时，应与被让路渔船及其渔具保持一定的安全距离。"},{"i":15,"n":"第十五条","txt":"在决定安全距离时，应充分考虑到下列因素： 1.船舶的操纵性能； 2.渔具尺度及其作业状况； 3.渔场的风、流、水深、障碍物及能见度等情况； 4.周围船舶的动态及其密集程度。"},{"i":16,"n":"第十六条","txt":"任何船舶在经过起网中的围网渔船附近时，严禁触及网具或从起网船与带围船之间通过。"},{"i":17,"n":"第十七条","txt":"让路船舶应距光诱渔船500米以外通过，并不得在该距离之内锚泊或其他有碍于该船光诱效果的行动。"},{"i":18,"n":"第十八条","txt":"围网渔船在放网时，应不妨碍漂流渔船或拖网渔船的正常作业。"},{"i":19,"n":"第十九条","txt":"漂流渔船在放出渔具时，应尽可能离开当时拖网渔船集中作业的渔场。"},{"i":20,"n":"第二十条","txt":"从事定置渔具作业的渔船在放置渔具时，应不妨碍其他从事捕捞船舶的正常作业。"},{"i":21,"n":"第二十一条","txt":"追越渔船应给被追越渔船让路，并不得抢占被追越渔船网档的正前方而妨碍其作业。"},{"i":22,"n":"第二十二条","txt":"机动拖网渔船应给非机动拖网渔船让路。"},{"i":23,"n":"第二十三条","txt":"多对渔船在相对拖网作业相遇时，如一方或双方两侧都有同向平行拖网中的渔船，转向避让确有困难，双方应及时缩小网档或采取其他有效的措施，谨慎地从对方网档的外侧通过，直到双方的网具让清为止。"},{"i":24,"n":"第二十四条","txt":"交叉相遇时： 1.应给本船右舷的另一方船让路； 2.当让路船不能按上款规定让路时，应预先用声号联系，以取得协调一致的避让行动； 3.如被让路船是对拖网船，被让路船应适当考虑到让路船的困难，尽量作到协同避让，必要时尽可能缩小网档，加速通过让路船网档的前方海区。"},{"i":25,"n":"第二十五条","txt":"采取大角度转向的拖网中渔船，不得妨碍附近渔船的正常作业。"},{"i":26,"n":"第二十六条","txt":"不得在拖网渔船的网档正前方放网、抛锚或有其他妨碍该渔船正常作业的行动。"},{"i":27,"n":"第二十七条","txt":"多艘单拖网渔船在同向并列拖网中，两船间应保持一定的安全距离。"},{"i":28,"n":"第二十八条","txt":"放网中渔船，应给拖网中或起网中的渔船让路。"},{"i":29,"n":"第二十九条","txt":"拖网中渔船，应给起网中渔船让路。同时起网船，应给正在从事卡包（分吊）起鱼的渔船让路。"},{"i":30,"n":"第三十条","txt":"准备起网的渔船，应在起网前10分钟显示起网信号，夜间应同时开亮甲板工作灯，以引起周围船舶的注意。"},{"i":31,"n":"第三十一条","txt":"船组在灯诱鱼群时，后下灯的船组与先下灯的船组间的距离应不少于1000米。"},{"i":32,"n":"第三十二条","txt":"围网渔船不得抢围他船用鱼群指示标（灯）所指示的、并准备围捕的鱼群。"},{"i":33,"n":"第三十三条","txt":"在追捕同一的起水鱼群时，只要有一船已开始放网，他船不得有妨碍该放网船正常作业的行动。"},{"i":34,"n":"第三十四条","txt":"围网渔船在起网过程中： 1.底纲已绞起的船应尽可能避让底纲未绞起的船； 2.同是底纲已绞起的船，有带围的船应避让无带围的船； 3.起（捞）鱼的船应避让正在绞（吊）网的船。"},{"i":35,"n":"第三十五条","txt":"船组在灯诱时，“拖灯诱鱼”的船应避让“漂灯诱鱼”和“锚泊灯诱”的船。"},{"i":36,"n":"第三十六条","txt":"漂流渔船在放出渔具时应与同类船保持一定的安全距离，并尽可能做到同向作业。"},{"i":37,"n":"第三十七条","txt":"当双方的渔具有可能发生纠缠时，各应主动起网，或采取其他有效措施，互相避开。"},{"i":38,"n":"第三十八条","txt":"各类渔船在放网前应充分掌握周围船舶的动态，并结合气象与海况谨慎操作。"},{"i":39,"n":"第三十九条","txt":"及时启用雷达，判断有无存在使本方或他方的船舶和渔具遭受损坏的危险，并采取合理的避让措施。"},{"i":40,"n":"第四十条","txt":"拖网渔船在放网时，应采取安全航速。"},{"i":41,"n":"第四十一条","txt":"拖网渔船在拖网中，应适当地缩小网档。"},{"i":42,"n":"第四十二条","txt":"拖网渔船在拖网中发现与他船网档互相穿插时，应立即停车，同时发出声号一短一长二短声（· —··），通知对方立即停车，并采取有效措施，直到双方互不影响拖网作业时为止。"},{"i":43,"n":"第四十三条","txt":"各类渔船除显示规定的号灯外，还可以开亮工作灯或探照灯。"},{"i":44,"n":"第四十四条","txt":"船组在起网过程中，当带围船拖带起网船时，应显示从事围网作业渔船的号灯、号型，当有他船临近时，可向拖缆方向照射探照灯。"},{"i":45,"n":"第四十五条","txt":"围网渔船在拖带灯船或舢板进行探测、搜索或追捕鱼群的过程中，应显示拖带船的号灯、号型；当开始放网时，应显示捕鱼作业中所规定的号灯和号型。"},{"i":46,"n":"第四十六条","txt":"灯诱中的围网渔船应按《72规则》显示捕鱼作业中的号灯。"},{"i":47,"n":"第四十七条","txt":"下列船舶应显示在航船的号灯： 1.未拖带灯船的围网船在航测鱼群时； 2.对拖渔船中等待他船起网的另一艘船； 3.其他脱离渔具的漂流中的船舶。"},{"i":48,"n":"第四十八条","txt":"停靠在围网渔船网圈旁或在围网渔船旁直接从网中起（捞）鱼的运输船舶，应显示围网渔船的号灯、号型。"},{"i":49,"n":"第四十九条","txt":"运输船靠在拖网中的渔船时，应按《72规则》显示“操纵能力受到限制的船舶”的号灯、号型。"},{"i":50,"n":"第五十条","txt":"围网渔船在夜间放网时： 1.网圈上应显示五只以上间距相等的白色闪光灯。 2.如不能按本条1款规定显示信号时，应采取一切可能措施，使网圈上有灯光或至少能表明该网圈的存在。"},{"i":51,"n":"第五十一条","txt":"漂流渔船除显示《72规则》有关号灯、号型外，还应在渔具上显示下列信号： 日间：每隔不大于500米的间距，显示顶端有红色三角旗的标志一面；其远离船的一端，应垂直显示红色三角旗两面。 夜间：每隔不大于1000米的间距，显示白色灯一盏，在远离船的一端显示红色灯一盏。 上述灯光的视距应不少于0.5海里。"},{"i":52,"n":"第五十二条","txt":"名词解释 1.“渔船”一词是指正在使用拖网、围网、灯诱、流刺网、延绳钓渔具和定置渔具进行捕捞作业的船舶（但不包括曳绳钓和手钓渔具捕鱼的船舶）。 2.“船组”一词是指由一艘围网渔船，一艘或一艘以上灯光船组成的一个生产单位。 3.“网档”一词是指两艘拖网渔船在平行同向拖曳同一渔具过程中，船舶之间的横距。 4.“带围船”一词是指拖带围网渔船的船舶。 5.“从事定置渔具捕捞的船舶”是指在破泊中设置渔具或正在起放定置渔具或系泊在定置渔具上等候潮水起网的船舶。 6.“漂流渔船”一词是指系带渔具随风流漂移而从事捕捞作业的船舶（包括流刺网、延绳钓渔船，但不包括手钓、曳绳钓渔船）。 7.“围网渔船”一词是指正在起、放围网或施放水下灯具或灯光诱集鱼群的船舶。 8.“拖网渔船”一词是指一艘或一艘以上从事拖网或正在起放拖网作业的船舶。"},{"i":53,"n":"第五十三条","txt":"本规定自1984年10月1日起施行。"}],"bohaishengwuziyuanyanghuguiding":[{"i":1,"n":"第一条","txt":"为保护、增殖和合理利用渤海生物资源，保护渤海水域生态环境，保障渔业生产者合法权益，促进渤海渔业可持续发展，根据《中华人民共和国渔业法》和《中华人民共和国海洋环境保护法》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称渤海是指老铁山灯塔（北纬38°43′41〃、东经121°07′43〃）与蓬莱灯塔（北纬37°49′54〃、东经120°44′13〃）两点连线以西的海域。"},{"i":3,"n":"第三条","txt":"在渤海从事养殖和捕捞水生动物、水生植物等渔业生产及其他相关活动的单位和个人，应当遵守本规定。从事涉及国家重点保护水生野生动物、野生植物相关活动的单位和个人，应当遵守《野生动物保护法》、《水生野生动物保护条例》、《野生植物保护条例》的有关规定。"},{"i":4,"n":"第四条","txt":"农业部主管渤海生物资源养护工作。农业部黄渤海区渔政渔港监督管理局负责渤海生物资源养护的组织、协调和监督管理工作。渤海沿岸县级以上地方人民政府渔业行政主管部门负责本行政区域内生物资源养护工作。"},{"i":5,"n":"第五条","txt":"渤海沿岸县级以上地方人民政府渔业行政主管部门应当根据国家水域利用规划和经批准的海洋功能区划、近岸海域环境功能区划，编制辖区渔业水域利用规划，经同级人民政府批准后组织实施。除渔港和渔业设施基地建设区外，渔业水域区分为养殖区、增殖区、捕捞区和重要渔业品种保护区。禁止将渤海生物资源的重要产卵场、索饵场、越冬场和洄游通道划为养殖区。不得在国家海上自然保护区、珍稀濒危海洋生物保护区等一类近岸海域环境功能区内划置养殖区。"},{"i":6,"n":"第六条","txt":"沿岸县级以上地方人民政府渔业行政主管部门应当采取措施，改善和恢复渤海生态状况，控制捕捞强度，增殖和养护渤海生物资源，发展生态渔业，促进渤海渔业可持续发展。"},{"i":7,"n":"第七条","txt":"沿岸县级以上地方人民政府渔业行政主管部门应当根据渤海生物资源状况，提出控制和压缩捕捞强度的措施，调整捕捞业生产结构，引导和扶持捕捞渔民转产转业。"},{"i":8,"n":"第八条","txt":"渤海沿岸县级以上地方人民政府渔业行政主管部门应当对养殖区统一规划，科学评估，确定养殖发展布局和养殖水域容量，发展和推广生态养殖。"},{"i":9,"n":"第九条","txt":"在渤海使用全民所有的水域、滩涂从事养殖生产的，应当向沿岸县级以上地方人民政府渔业行政主管部门提出申请，由本级人民政府核发养殖证。因结构调整转产转业的当地渔民享有取得养殖证的优先权。"},{"i":10,"n":"第十条","txt":"沿岸县级以上地方人民政府渔业行政主管部门受理养殖证申请时，应当根据养殖发展布局和养殖水域的容量，明确养殖证的水域滩涂范围、使用期限、用途等事项。新建、扩建和改建养殖场的，应当进行环境影响评价。"},{"i":11,"n":"第十一条","txt":"取得养殖证的单位和个人应当按照养殖证确定的水域滩涂范围和规定的用途从事养殖生产，遵守有关养殖技术规范。养殖废水排放应符合国家有关排放标准，池塘清淤应进行合理处理，防止水域污染。"},{"i":12,"n":"第十二条","txt":"禁止在渤海养殖未经全国水产原种和良种审定委员会审定、农业部批准推广的杂交种、转基因种和其他非渤海原有品种。养殖经全国水产原种和良种审定委员会审定、农业部批准推广的上述品种的，应当严格采取防逃等防护措施，防止其进入天然水域。"},{"i":13,"n":"第十三条","txt":"在渤海从事捕捞活动，应当依法申领捕捞许可证，按照捕捞许可证确定的作业场所、时限、作业类型等内容开展捕捞活动，并遵守国家有关资源保护规定。"},{"i":14,"n":"第十四条","txt":"沿岸县级以上地方人民政府渔业行政主管部门应当按照规定的权限和管辖范围发放捕捞许可证，不得超过上级下达的船网工具控制指标。禁止向非渔业生产者以及江河、湖泊、水库等内陆渔船发放渤海捕捞许可证。"},{"i":15,"n":"第十五条","txt":"从事海上渔获物运销、冷藏加工、渔用物资和燃料补给等为渔业捕捞生产提供服务的渔业辅助船舶，必须依法领取捕捞辅助船许可证。禁止捕捞辅助船直接从事捕捞生产。"},{"i":16,"n":"第十六条","txt":"国家鼓励发展休闲渔业。沿岸县级以上地方人民政府渔业行政主管部门应加强对休闲渔业活动的监督和管理。休闲渔业活动采捕天然渔业资源的，应领取专项（特许）捕捞许可证。具体管理办法由省、直辖市渔业行政主管部门规定。"},{"i":17,"n":"第十七条","txt":"国家鼓励单位和个人投资，采取人工增殖放流、人工鱼礁建设等多种形式，增殖渤海生物资源。"},{"i":18,"n":"第十八条","txt":"农业部黄渤海区渔政渔港监督管理局和沿岸省、直辖市人民政府渔业行政主管部门应当积极采取措施，统筹规划，制定本地区生物资源增殖计划，依法组织人工增殖放流、人工鱼礁建设。"},{"i":19,"n":"第十九条","txt":"大范围洄游性品种的人工增殖放流，由农业部黄渤海区渔政渔港监督管理局统一规划，统一组织实施。区域性和定居性品种的人工增殖放流可以由沿岸县级以上地方人民政府渔业行政主管部门在辖区渔业水域的非养殖区组织实施。"},{"i":20,"n":"第二十条","txt":"人工增殖放流的苗种应当由省级以上渔业行政主管部门指定的原良种场、增殖站和水生野生动物驯养繁殖基地提供。禁止在渤海放流杂交种、转基因种及其他非渤海原有品种。但放流经省级以上渔业行政主管部门组织生态安全评估合格、全国水产原种和良种审定委员会审定和农业部批准推广的上述品种的除外。"},{"i":21,"n":"第二十一条","txt":"禁止在种质资源保护区，重要经济鱼、虾、蟹类的产卵场等敏感水域进行放流。"},{"i":22,"n":"第二十二条","txt":"设置人工鱼礁，应当进行环境影响和增殖效果评估，并由农业部或沿岸省、直辖市人民政府渔业行政主管部门统一组织实施。在“机动渔船底拖网禁渔区线”外侧设置人工鱼礁的，应当依照《中华人民共和国渔业法实施细则》的规定，报请农业部批准；在“机动渔船底拖网禁渔区线”内侧设置人工鱼礁的，应当报请省、直辖市人民政府渔业行政主管部门或其授权单位批准。"},{"i":23,"n":"第二十三条","txt":"设置人工鱼礁不得妨碍船舶航行，不得影响海底管道、缆线等设施，并应事先公告。"},{"i":24,"n":"第二十四条","txt":"实行渤海重点渔业资源保护制度。重点保护的渤海渔业资源品种及其可捕标准按照附件1执行。附件1中未定标准的重点保护品种的可捕标准和地方重点保护品种及其可捕标准，由沿岸各省、直辖市人民政府渔业行政主管部门规定，报农业部和农业部黄渤海区渔政渔港监督管理局备案。在网次或航次渔获量中，未达可捕标准的重点保护品种比重不得超过同品种渔获量的百分之二十五，但定置张网作业除外。"},{"i":25,"n":"第二十五条","txt":"渤海秋汛对虾生产实行专项（特许）捕捞许可证制度。捕捞渤海秋汛对虾的，应当依法领取专项（特许）捕捞许可证，悬挂统一规定的标志，方可从事作业。"},{"i":26,"n":"第二十六条","txt":"禁止捕捞对虾春季亲虾和本规定附件1所列重点保护品种的天然苗种。因特殊需要捕捞本规定附件1已定可捕标准的重点保护品种天然苗种的，由农业部黄渤海区渔政渔港监督管理局批准；捕捞本规定附件1未定可捕标准的或地方自定重点保护品种天然苗种的，由省、直辖市人民政府渔业行政主管部门批准。经批准后，发放专项（特许）捕捞许可证。领取专项（特许）捕捞许可证后，应当按照指定的区域、时限和限额捕捞。"},{"i":27,"n":"第二十七条","txt":"禁止在潮间带外侧水域采捕兰蛤。在潮间带和其向陆一侧采捕兰蛤、沙蚕、卤虫，应当报经省、直辖市渔业行政主管部门批准，发放专项（特许）捕捞许可证。取得专项（特许）捕捞许可证的，应当按照指定的区域、时限，凭证限量采捕。"},{"i":28,"n":"第二十八条","txt":"禁止使用小于规定的最小网目尺寸的网具进行捕捞。渤海捕捞作业网具的最小网目尺寸按照附件2执行。沿岸各省、直辖市人民政府渔业行政主管部门可以规定未列入附件2的其他网具的最小网目尺寸，但应报农业部和农业部黄渤海区渔政渔港监督管理局备案。"},{"i":29,"n":"第二十九条","txt":"禁止借改变渔具名称或以革新为名使用损害生物资源的渔具。"},{"i":30,"n":"第三十条","txt":"禁止使用下列严重损害生物资源的渔具、渔法： （一）炸鱼、毒鱼和电力捕鱼；以渔船推进器、泵类采捕定居种生物资源； （二）三重流网、底拖网、浮拖网及变水层拖网作业，但网口网衣拉直周长小于30米的桁杆、框架型拖网类渔具除外； （三）规格不符合本规定附件2规定标准的网具；沿岸各省、直辖市人民政府渔业行政主管部门可以规定适用于本行政区域的其他禁止使用的渔具渔法，并报农业部和农业部黄渤海区渔政渔港监督管理局备案。"},{"i":31,"n":"第三十一条","txt":"渤海实行伏季休渔等禁渔期制度，并应当执行附件3的规定。沿岸各省、直辖市人民政府渔业行政主管部门可以对毛虾和海蜇规定适用于本行政区域的禁渔期，并报农业部和农业部黄渤海区渔政渔港监督管理局备案。"},{"i":32,"n":"第三十二条","txt":"禁止在禁渔区、禁渔期内收购、加工和销售非法捕捞的渔获物。在禁渔区或者禁渔期内收购、加工和销售非法捕捞的渔获物的，沿岸县级以上地方人民政府渔业行政主管部门及其所属的渔政渔港监督管理机构应当及时调查处理。"},{"i":33,"n":"第三十三条","txt":"沿岸的盐场、电厂、养殖场和其他利用海水的单位或个人，在纳水时应当采取防护或有效规避措施，保护幼鱼、幼虾资源。在伏季休渔期间引水用水时应设置凸面向外且网目不超过7毫米的“V”型防护网。未采取防护措施，对天然生物资源造成损害的，沿岸县级以上地方人民政府渔业行政主管部门应当责令限期消除危害。"},{"i":34,"n":"第三十四条","txt":"因科学研究特殊需要，在禁渔区、禁渔期捕捞或使用禁用的渔具、渔法，以及捕捞禁捕对象的，应当经农业部黄渤海区渔政渔港监督管理局审核后，报农业部批准。捕捞作业时应当悬挂统一规定的标志。"},{"i":35,"n":"第三十五条","txt":"沿岸县级以上地方人民政府渔业行政主管部门应当依法参加海岸工程、海洋工程、倾废区、入海排污口等项目的环境影响评价等工作，研究对生物资源和渔业水域环境的影响，提出保护生物资源和渔业水域环境的具体要求和措施。"},{"i":36,"n":"第三十六条","txt":"沿岸各级渔业生态环境监测机构应当依法加强对渔业水域的监测，及时向同级渔业行政主管部门和上一级监测机构报告监测情况。"},{"i":37,"n":"第三十七条","txt":"沿岸各级渔业生态环境监测机构应当建立健全机制，加强赤潮监测与预警工作，并及时向同级渔业行政主管部门和上一级监测机构报告监测情况。沿岸县级以上地方人民政府渔业行政主管部门应当积极会同或配合有关部门，加强赤潮防范，组织生产者防灾减灾，减少生产损失。"},{"i":38,"n":"第三十八条","txt":"进行水下爆破、勘探、施工作业，对生物资源有严重影响的，位于“机动渔船底拖网禁渔区线”内的，作业单位应当事先同沿岸省、直辖市人民政府渔业行政主管部门协商；位于“机动渔船底拖网禁渔区线”外的，作业单位应当事先同农业部黄渤海区渔政渔港监督管理局协商，并采取有关防护措施后，方能作业。因作业造成生物资源破坏或损失的，根据管辖范围，农业部黄渤海区渔政渔港监督管理局和沿岸省、直辖市人民政府渔业行政主管部门应当责令作业单位限期消除危害，并向有关人民政府提出责令作业单位赔偿的建议。"},{"i":39,"n":"第三十九条","txt":"因溢油、排污及倾倒废弃物等污染，造成渔业污染事故的，由沿岸县级以上地方人民政府渔业行政主管部门或其所属的渔政监督管理机构组织调查、评估，并依照《中华人民共和国海洋环境保护法》的有关规定处理。污染事故损害渤海天然生物资源的，沿岸县级以上地方人民政府渔业行政主管部门依法处理，并可以代表国家对责任者提出损害赔偿要求。"},{"i":40,"n":"第四十条","txt":"违反本规定的，由县级以上人民政府渔业行政主管部门或其所属的渔政监督管理机构依法处理，法律、法规另有规定的，从其规定。"},{"i":41,"n":"第四十一条","txt":"本规定由农业部负责解释。"},{"i":42,"n":"第四十二条","txt":"本规定自2004年5月1日起施行。农业部1991年4月13日发布的《渤海区渔业资源繁殖保护规定》同时废止。"}],"gancaohemahuangcaocaijiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对甘草和麻黄草资源的管理，保护草原生态环境，根据《中华人民共和国草原法》、《中华人民共和国野生植物保护条例》和国务院有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事野生和人工栽培甘草和麻黄草采集、出售的单位和个人，必须遵守本办法。"},{"i":3,"n":"第三条","txt":"农业部负责全国甘草和麻黄草采集管理工作。 县级以上地方人民政府农牧行政主管部门负责本行政区域内甘草和麻黄草采集管理工作。"},{"i":4,"n":"第四条","txt":"国家对甘草和麻黄草采集实行采集证制度。"},{"i":5,"n":"第五条","txt":"国家对甘草和麻黄草资源实行依法保护、科学规划、合理利用的方针。鼓励支持投资甘草和麻黄草的人工种植和围栏护育。"},{"i":6,"n":"第六条","txt":"甘草和麻黄草主要分布地区要编制甘草和麻黄草资源保护和建设规划。甘草和麻黄草资源保护和建设规划由县级以上地方人民政府农牧行政主管部门会同经贸、药品监督管理部门编制，经本级人民政府审核同意后，报上级人民政府批准。 农业部负责编制全国甘草和麻黄草保护和建设规划，并报国务院批准。"},{"i":7,"n":"第七条","txt":"保护和建设规划要明确甘草和麻黄草年度采集、保护和建设计划，分布的区域、面积和适宜采集量，限采轮采措施等，确定禁采区、封育区、采集区和建设区。 在禁采区内严禁一切采集活动。在封育区内，要规定允许采集的区域、时段、方式和工具。"},{"i":8,"n":"第八条","txt":"县级以上地方人民政府农牧行政主管部门要根据本级人民政府制定的甘草和麻黄草保护和建设规划，逐级上报下一年度采集计划，省级农牧行政主管部门于十一月底前将采集计划报农业部。 农业部会同国家经贸委、国家药品监督管理局于每年一月底前将年度采集计划下达各省、自治区、直辖市，各省、自治区、直辖市将采集计划下达各地。"},{"i":9,"n":"第九条","txt":"采集计划应当包括采集甘草、麻黄草的区域、面积、当年适宜采集量、计划采集量及保障措施。"},{"i":10,"n":"第十条","txt":"采集、出售甘草和麻黄草须凭采集证。"},{"i":11,"n":"第十一条","txt":"申请采集甘草和麻黄草的单位和个人须填写采集审批表，由采集地县级人民政府农牧行政主管部门签署意见后，向省级人民政府农牧行政主管部门申请办理采集证。"},{"i":12,"n":"第十二条","txt":"农牧行政主管部门应当严格按照采集地年度采集计划颁发采集证。"},{"i":13,"n":"第十三条","txt":"采集证、采集审批表由各省、自治区、直辖市农牧行政主管部门统一印制。 采集证须载明持证人年度采集数量、采集地点、采集时间和采集方式。采集证有效期为一年。"},{"i":14,"n":"第十四条","txt":"采集证不得涂改、伪造、转让、倒卖。"},{"i":15,"n":"第十五条","txt":"采集活动应当控制在属地范围内。严禁跨行政区域采集甘草和麻黄草。禁止非法进入他人享有使用权或承包经营权的草原上采集甘草和麻黄草。 有边界纠纷的地区按禁采区处理。"},{"i":16,"n":"第十六条","txt":"省级人民政府农牧行政主管部门应当根据当地实际确定禁采期，并报农业部备案。禁采期内严禁一切采集活动。"},{"i":17,"n":"第十七条","txt":"县级人民政府农牧行政主管部门应当对申请领取采集证者进行必要的法律、生态环境保护知识的宣传教育和采集技术培训。"},{"i":18,"n":"第十八条","txt":"单位和个人取得采集证后，必须按照采集证规定的时间、地点、种类、数量、采集工具和方法进行采集。禁止无证采集和违规采集。"},{"i":19,"n":"第十九条","txt":"采集甘草和麻黄草要本着\"采育结合，永续利用\"的原则，作好更新复壮工作。"},{"i":20,"n":"第二十条","txt":"采集甘草、麻黄草时，要保护草原生态环境。 采集甘草时，必须按自然土层随挖随填。 采集麻黄草必须保证其根部无损毁，不影响其再生。严禁连根采集。"},{"i":21,"n":"第二十一条","txt":"甘草和麻黄草分布地区的县级以上人民政府农牧行政主管部门应当建立甘草和麻黄草保护管理责任制度。"},{"i":22,"n":"第二十二条","txt":"落实草原承包责任制时，要把甘草和麻黄草的保护、利用、建设作为承包合同的重要内容，并明确保护甘草和麻黄草的责任和义务。"},{"i":23,"n":"第二十三条","txt":"县级以上人民政府农牧主管部门应当对本行政区域内甘草和麻黄草的采集、出售活动进行监督检查。"},{"i":24,"n":"第二十四条","txt":"县级以上人民政府农牧行政主管部门在履行监督检查职责时，有权采取下列措施： （一）检查采集者或出售单位和个人的采集证； （二）进入采集和出售甘草和麻黄草的现场进行勘测、拍照、摄像等取证活动； （三）询问违法案件的嫌疑人； （四）责令停止正在进行的违法采集、出售甘草和麻黄草行为。"},{"i":25,"n":"第二十五条","txt":"有关单位或个人对农牧行政主管部门进行的监督检查应当给予配合，不得拒绝或阻挠。"},{"i":26,"n":"第二十六条","txt":"违反本办法规定，采集甘草和麻黄草造成草原生态环境破坏的，根据国务院规定，由县级以上人民政府农牧行政主管部门取消采集证，并责令恢复植被，拒不恢复的，指定有关单位和个人代为恢复植被，所花费用由责任人承担。并可处以违法所得1倍以上3倍以下的罚款，但最高不得超过3万元。"},{"i":27,"n":"第二十七条","txt":"违反本办法规定，未取得采集证或不按采集证的规定采集、出售甘草和麻黄草的，由县级以上人民政府农牧行政主管部门处以违法所得1倍以上3倍以下的罚款，但最高不得超过3万元。"},{"i":28,"n":"第二十八条","txt":"仿造、倒卖、转让采集证，有违法所得的处以违法所得1倍以上3倍以下罚款，但最高不得超过3万元；没有违法所得的处以1万元以下的罚款。"},{"i":29,"n":"第二十九条","txt":"农牧行政主管部门的工作人员滥用职权、玩忽职守、徇私舞弊，依法给予行政处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"对苁蓉、雪莲、冬虫夏草等草原野生植物的采集管理，比照本办法的规定执行。"},{"i":31,"n":"第三十一条","txt":"本办法由农业部负责解释。"},{"i":32,"n":"第三十二条","txt":"本办法自发布之日起执行。"}],"shengxianrushengchanshougouguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强生鲜乳生产收购管理，保证生鲜乳质量安全，促进奶业健康发展，根据《乳品质量安全监督管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称生鲜乳，是指未经加工的奶畜原奶。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内从事生鲜乳生产、收购、贮存、运输、出售活动，应当遵守本办法。"},{"i":4,"n":"第四条","txt":"奶畜养殖者、生鲜乳收购者、生鲜乳运输者对其生产、收购、运输和销售的生鲜乳质量安全负责，是生鲜乳质量安全的第一责任者。"},{"i":5,"n":"第五条","txt":"县级以上人民政府畜牧兽医主管部门负责奶畜饲养以及生鲜乳生产环节、收购环节的监督管理。 县级以上人民政府其他有关部门在各自职责范围内负责生鲜乳质量安全监督管理的其他工作。"},{"i":6,"n":"第六条","txt":"生产、收购、贮存、运输、销售的生鲜乳，应当符合乳品质量安全国家标准。 禁止在生鲜乳生产、收购、贮存、运输、销售过程中添加任何物质。"},{"i":7,"n":"第七条","txt":"省级人民政府畜牧兽医主管部门会同发展改革部门、工业和信息化部门、商务部门，制定本行政区域的奶业发展规划，加强奶源基地建设，鼓励和支持标准化规模养殖，完善服务体系，促进奶业健康发展。 县级以上地方人民政府应当根据全国和省级奶业发展规划，合理确定本行政区域内奶畜养殖规模，科学安排生鲜乳的生产、收购布局。"},{"i":8,"n":"第八条","txt":"奶业协会应当加强行业自律，推动行业诚信建设，引导、规范奶畜养殖者、生鲜乳收购者依法生产经营。"},{"i":9,"n":"第九条","txt":"地方畜牧兽医技术推广机构，应当结合当地奶畜发展需要，向奶畜养殖者提供奶畜品种登记、奶牛生产性能测定、青粗饲料生产与利用、标准化养殖、奶畜疫病防治、粪便无害化处理等技术服务，并开展相关技术培训。 鼓励大专院校、科研院所、乳制品生产企业及其他相关生产经营者为养殖者提供所需的服务。"},{"i":10,"n":"第十条","txt":"奶畜养殖场、养殖小区，应当符合法律、行政法规规定的条件，并向县级人民政府畜牧兽医主管部门或者其委托的畜牧技术推广机构备案，获得奶畜养殖代码。 鼓励乳制品生产企业建立自己的奶源基地，按照良好规范要求实施标准化生产和管理。"},{"i":11,"n":"第十一条","txt":"奶畜养殖场应当按照《乳品质量安全监督管理条例》第十三条规定建立养殖档案，准确填写有关信息，做好档案保存工作。奶畜养殖小区应当逐步建立养殖档案。 县级人民政府畜牧兽医主管部门应当督促和指导奶畜养殖场、奶畜养殖小区依法建立科学、规范的养殖档案。"},{"i":12,"n":"第十二条","txt":"从事奶畜养殖，不得在饲料、饲料添加剂、兽药中添加动物源性成分（乳及乳制品除外），不得添加对动物和人体具有直接或者潜在危害的物质。"},{"i":13,"n":"第十三条","txt":"奶畜养殖者应当遵守农业部制定的生鲜乳生产技术规程。直接从事挤奶工作的人员应当持有有效的健康证明。 奶畜养殖者对挤奶设施、生鲜乳贮存设施等应当在使用前后及时进行清洗、消毒，避免对生鲜乳造成污染，并建立清洗、消毒记录。"},{"i":14,"n":"第十四条","txt":"挤奶完成后，生鲜乳应当储存在密封的容器中，并及时做降温处理，使其温度保持在0-4℃之间。超过2小时未冷藏的，不得销售。"},{"i":15,"n":"第十五条","txt":"奶畜养殖者可以向符合本办法规定的生鲜乳收购站出售自养奶畜产的生鲜乳。"},{"i":16,"n":"第十六条","txt":"禁止出售下列生鲜乳： （一）经检测不符合健康标准或者未经检疫合格的奶畜产的； （二）奶畜产犊7日内的初乳，但以初乳为原料从事乳制品生产的除外； （三）在规定用药期和休药期内的奶畜产的； （四）添加其他物质和其他不符合乳品质量安全国家标准的。"},{"i":17,"n":"第十七条","txt":"省级人民政府畜牧兽医主管部门应当根据当地奶源分布情况，按照方便奶畜养殖者、促进规模化养殖的原则，制定生鲜乳收购站建设规划，对生鲜乳收购站进行科学合理布局。 县级人民政府畜牧兽医主管部门应当根据本省的生鲜乳收购站建设规划，结合本地区奶畜存栏量、日产奶量、运输半径等因素,确定生鲜乳收购站的建设数量和规模，并报省级人民政府畜牧兽医主管部门批准。"},{"i":18,"n":"第十八条","txt":"取得工商登记的乳制品生产企业、奶畜养殖场、奶农专业生产合作社开办生鲜乳收购站，应当符合法定条件，向所在地县级人民政府畜牧兽医主管部门提出申请，并提交以下材料： （一）开办生鲜乳收购站申请； （二）生鲜乳收购站平面图和周围环境示意图； （三）冷却、冷藏、保鲜设施和低温运输设备清单； （四）化验、计量、检测仪器设备清单； （五）开办者的营业执照复印件和法定代表人身份证明复印件； （六）从业人员的培训证明和有效的健康证明； （七）卫生管理和质量安全保障制度。"},{"i":19,"n":"第十九条","txt":"县级人民政府畜牧兽医主管部门应当自受理申请材料之日起20日内，完成申请材料的审核和对生鲜乳收购站的现场核查。符合规定条件的，向申请人颁发生鲜乳收购许可证，并报省级人民政府畜牧兽医主管部门备案。不符合条件的，书面通知当事人，并说明理由。"},{"i":20,"n":"第二十条","txt":"生鲜乳收购许可证有效期2年。有效期满后，需要继续从事生鲜乳收购的，应当在生鲜乳收购许可证有效期满30日前，持原证重新申请。重新申请的程序与原申请程序相同。 生鲜乳收购站的名称或者负责人变更的，应当向原发证机关申请换发生鲜乳收购许可证，并提供相应证明材料。"},{"i":21,"n":"第二十一条","txt":"生鲜乳收购站的挤奶设施和生鲜乳贮存设施使用前应当消毒并晾干，使用后1小时候内应当清洗、消毒并晾干；不用时，用防止污染的方法存放好，避免对生鲜乳造成污染。 生鲜乳收购站使用的洗涤剂、消毒剂、杀虫剂和其他控制害虫的产品应当确保不对生鲜乳造成污染。"},{"i":22,"n":"第二十二条","txt":"生鲜乳收购站应当按照乳品质量安全国家标准对收购的生鲜乳进行感官、酸度、密度、含碱等常规检测。检测费用由生鲜乳收购站自行承担，不得向奶畜养殖者收取，或者变相转嫁给奶畜养殖者。"},{"i":23,"n":"第二十三条","txt":"生鲜乳收购站应当建立生鲜乳收购、销售和检测记录，并保存2年。 生鲜乳收购记录应当载明生鲜乳收购站名称及生鲜乳收购许可证编号、畜主姓名、单次收购量、收购日期和时点。 生鲜乳销售记录应当载明生鲜乳装载量、装运地、运输车辆牌照、承运人姓名、装运时间、装运时生鲜乳温度等内容。 生鲜乳检测记录应当载明检测人员、检测项目、检测结果、检测时间。"},{"i":24,"n":"第二十四条","txt":"生鲜乳收购站收购的生鲜乳应当符合乳品质量安全国家标准。不符合乳品质量安全国家标准的生鲜乳，经检测无误后，应当在当地畜牧兽医主管部门的监督下销毁或者采取其他无害化处理措施。"},{"i":25,"n":"第二十五条","txt":"贮存生鲜乳的容器，应当符合散装乳冷藏罐国家标准。"},{"i":26,"n":"第二十六条","txt":"运输生鲜乳的车辆应当取得所在地县级人民政府畜牧兽医主管部门核发的生鲜乳准运证明。无生鲜乳准运证明的车辆，不得从事生鲜乳运输。 生鲜乳运输车辆只能用于运送生鲜乳和饮用水，不得运输其他物品。 生鲜乳运输车辆使用前后应当及时清洗消毒。"},{"i":27,"n":"第二十七条","txt":"生鲜乳运输车辆应当具备以下条件： （一）奶罐隔热、保温，内壁由防腐蚀材料制造，对生鲜乳质量安全没有影响； （二）奶罐外壁用坚硬光滑、防腐、可冲洗的防水材料制造； （三）奶罐设有奶样存放舱和装备隔离箱，保持清洁卫生，避免尘土污染； （四）奶罐密封材料耐脂肪、无毒，在温度正常的情况下具有耐清洗剂的能力； （五）奶车顶盖装置、通气和防尘罩设计合理，防止奶罐和生鲜乳受到污染。"},{"i":28,"n":"第二十八条","txt":"生鲜乳运输车辆的所有者，应当向所在地县级人民政府畜牧兽医主管部门提出生鲜乳运输申请。县级人民政府畜牧兽医主管部门应当自受理申请之日起5日内，对车辆进行检查，符合规定条件的，核发生鲜乳准运证明。不符合条件的，书面通知当事人，并说明理由。"},{"i":29,"n":"第二十九条","txt":"从事生鲜乳运输的驾驶员、押运员应当持有有效的健康证明，并具有保持生鲜乳质量安全的基本知识。"},{"i":30,"n":"第三十条","txt":"生鲜乳运输车辆应当随车携带生鲜乳交接单。生鲜乳交接单应当载明生鲜乳收购站名称、运输车辆牌照、装运数量、装运时间、装运时生鲜乳温度等内容，并由生鲜乳收购站经手人、押运员、驾驶员、收奶员签字。"},{"i":31,"n":"第三十一条","txt":"生鲜乳交接单一式两份，分别由生鲜乳收购站和乳品生产者保存，保存时间2年。"},{"i":32,"n":"第三十二条","txt":"县级以上人民政府畜牧兽医主管部门应当加强对奶畜饲养以及生鲜乳生产、收购环节的监督检查，定期开展生鲜乳质量检测抽查，并记录监督抽查的情况和处理结果。需要对生鲜乳进行抽样检查的，不得收取任何费用。"},{"i":33,"n":"第三十三条","txt":"县级以上人民政府畜牧兽医主管部门在进行监督检查时，行使下列职权： （一）对奶畜养殖场所、生鲜乳收购站、生鲜乳运输车辆实施现场检查； （二）向有关人员调查、了解有关情况； （三）查阅、复制养殖档案、生鲜乳收购记录、购销合同、检验报告、生鲜乳交接单等资料； （四）查封、扣押有证据证明不符合乳品质量安全标准的生鲜乳； （五）查封涉嫌违法从事生鲜乳生产经营活动的场所，扣押用于违法生产、收购、贮存、运输生鲜乳的车辆、工具、设备； （六）法律、行政法规规定的其他职权。"},{"i":34,"n":"第三十四条","txt":"畜牧兽医主管部门应当建立生鲜乳生产者、收购者、运输者违法行为记录，及时提供给中国人民银行，由中国人民银行纳入企业信用信息基础数据库。"},{"i":35,"n":"第三十五条","txt":"省级以上人民政府畜牧兽医主管部门应当依法公布生鲜乳质量安全监督管理信息，并及时向同级卫生主管部门通报生鲜乳质量安全事故信息。"},{"i":36,"n":"第三十六条","txt":"县级以上人民政府畜牧兽医主管部门发现奶畜养殖者和生鲜乳收购者、运输者、销售者涉嫌犯罪的，应当及时移送公安机关立案侦查。"},{"i":37,"n":"第三十七条","txt":"任何单位和个人有权向畜牧兽医主管部门举报生鲜乳生产经营中的违法行为。各级畜牧兽医主管部门应当公布本单位的电子邮件地址或者举报电话；对接到的举报，应当完整地记录、保存。 各级畜牧兽医主管部门收到举报的，对属于本部门职责范围内的事项，应当及时依法查处，对于实名举报，应当及时答复；对不属于本部门职责范围内的事项，应当及时移交有权处理的部门。"},{"i":38,"n":"第三十八条","txt":"县级人民政府畜牧兽医主管部门在监督检查中发现生鲜乳运输车辆不符合规定条件的，应当收回生鲜乳准运证明，或者通报核发生鲜乳准运证明的畜牧兽医主管部门收回，同时通报有关乳制品加工企业。"},{"i":39,"n":"第三十九条","txt":"其他违反本办法规定的行为，依照《畜牧法》、《乳品质量安全监督管理条例》的有关规定进行处罚。"},{"i":40,"n":"第四十条","txt":"本办法自发布之日起施行。"}],"chuqinyangzhichangbeianguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范畜禽养殖行为，加强畜禽养殖场备案管理，根据《中华人民共和国畜牧法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在独立、固定的生产场所饲养列入《国家畜禽遗传资源目录》的畜禽，达到农业农村部规定的养殖规模标准的养殖场，应当按照本办法的规定进行备案。"},{"i":3,"n":"第三条","txt":"农业农村部负责全国畜禽养殖场备案管理工作，根据畜牧业发展情况适时调整畜禽养殖场规模标准。 县级以上地方人民政府农业农村主管部门负责本行政区域内畜禽养殖场备案管理工作，对畜禽养殖场备案情况开展监督检查。"},{"i":4,"n":"第四条","txt":"畜禽养殖场应当具备下列条件： （一）有与其饲养规模相适应的生产场所和配套的生产设施； （二）有为其服务的畜牧兽医技术人员； （三）具备法律、行政法规和农业农村部规定的防疫条件； （四）有与畜禽粪污无害化处理和资源化利用相适应的设施设备； （五）法律、行政法规规定的其他条件。"},{"i":5,"n":"第五条","txt":"畜禽养殖场兴办者应当提交下列材料，向养殖场所在地县级人民政府农业农村主管部门备案： （一）畜禽养殖场备案表； （二）养殖场所平面图或者实景照片。 畜禽养殖场兴办者应当对备案信息及相关材料的真实性负责。"},{"i":6,"n":"第六条","txt":"畜禽养殖场兴办者拥有两个以上畜禽养殖场的，应当分别备案。"},{"i":7,"n":"第七条","txt":"畜禽养殖场达到农业农村部规定的规模标准且备案材料齐全的，县级人民政府农业农村主管部门应当发放畜牧兽医生产经营主体代码；材料不齐全的，通知畜禽养殖场兴办者及时补正。"},{"i":8,"n":"第八条","txt":"畜禽养殖场备案后名称、养殖地址、畜禽品种或者养殖规模发生改变的，畜禽养殖场兴办者应当及时报告原备案部门变更备案信息。"},{"i":9,"n":"第九条","txt":"畜禽养殖场不再经营或者不再符合农业农村部规定的规模标准的，畜禽养殖场兴办者应当及时向原备案部门报告，原备案部门应当注销其畜牧兽医生产经营主体代码。 农业农村主管部门在监督检查中发现畜禽养殖场存在前款规定情形的，应当注销其畜牧兽医生产经营主体代码。"},{"i":10,"n":"第十条","txt":"畜禽养殖场应当按照农业农村部行业统计监测工作要求，在农业农村部畜牧业综合信息平台填报存栏量、出栏量等信息。"},{"i":11,"n":"第十一条","txt":"兴办畜禽养殖场未备案的，由县级以上地方人民政府农业农村主管部门责令限期改正；未在规定期限内改正或者存在其他严重情节的，可以处一万元以下罚款。"},{"i":12,"n":"第十二条","txt":"本办法所称的养殖规模，按照畜禽养殖场的设计生产能力进行测算。"},{"i":13,"n":"第十三条","txt":"畜禽养殖场的规模标准由农业农村部制定并公布。"},{"i":14,"n":"第十四条","txt":"本办法自2025年9月1日起施行。 符合农业农村部制定的规模标准且在本办法施行前已经按照省级人民政府规定备案的畜禽养殖场，不需要重新备案。"}],"chuqinxinpinzhongpeitaoxishendinghechuqinyichuanzieb040e":[{"i":1,"n":"第一条","txt":"为了规范畜禽新品种、配套系审定和畜禽遗传资源鉴定工作，促进优良畜禽品种选育与推广，根据《中华人民共和国畜牧法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称畜禽新品种是指通过人工选育，主要遗传性状具备一致性和稳定性，并具有一定经济价值的畜禽群体；配套系是指利用不同品种或种群之间杂种优势，用于生产商品群体的品种或种群的特定组合；畜禽遗传资源是指未列入《中国畜禽遗传资源目录》，通过调查新发现的畜禽遗传资源。"},{"i":3,"n":"第三条","txt":"培育的畜禽新品种、配套系和畜禽遗传资源在推广前，应当通过国家畜禽遗传资源委员会审定或者鉴定，并由农业部公告。"},{"i":4,"n":"第四条","txt":"农业部主管全国畜禽新品种、配套系审定和畜禽遗传资源鉴定工作。 农业部国家畜禽遗传资源委员会负责畜禽新品种、配套系审定和畜禽遗传资源鉴定。国家畜禽遗传资源委员会办公室设在全国畜牧总站。"},{"i":5,"n":"第五条","txt":"国家畜禽遗传资源委员会由科研、教学、生产、推广、管理等方面的专业人员组成，并设立牛、羊、家禽、猪、蜜蜂和其他动物等专业委员会，负责畜禽新品种、配套系审定和畜禽遗传资源鉴定的初审工作。"},{"i":6,"n":"第六条","txt":"申请审定和鉴定的畜禽新品种、配套系和畜禽遗传资源，应当具备下列条件，并符合相关技术规范要求： （一）主要特征一致、特性明显，遗传性稳定； （二）与其他品种、配套系、畜禽遗传资源有明显区别； （三）具有适当的名称。 畜禽新品种、配套系审定和畜禽遗传资源鉴定技术规范由农业部另行制定。"},{"i":7,"n":"第七条","txt":"申请畜禽新品种、配套系审定的，由该品种或配套系的培育单位或者个人向所在地省级人民政府畜牧行政主管部门提出，省级人民政府畜牧行政主管部门应当在20个工作日内完成审核，并将审核意见和相关材料报送国家畜禽遗传资源委员会。 申请畜禽遗传资源鉴定的，由该资源所在地省级人民政府畜牧行政主管部门向国家畜禽遗传资源委员会提出。 在中国没有经常住所或者营业场所的外国人、外国企业或者其他组织在中国申请畜禽新品种、配套系审定的，应当委托具有法人资格的中国育种科研、生产、经营单位代理。"},{"i":8,"n":"第八条","txt":"申请畜禽新品种、配套系审定的，应当向省级人民政府畜牧行政主管部门提交下列材料： （一）畜禽新品种、配套系审定申请表； （二）育种技术工作报告； （三）新品种、配套系标准； （四）具有法定资质的畜禽质量检验机构最近两年内出具的检测结果； （五）中试报告或者试验单位的证明材料； （六）声像、画册资料及必要的实物。"},{"i":9,"n":"第九条","txt":"申请畜禽遗传资源鉴定的，应当向国家畜禽遗传资源委员会提交下列材料： （一）畜禽遗传资源鉴定申请表； （二）遗传资源介绍； （三）遗传资源标准； （四）声像、画册资料及必要的实物。"},{"i":10,"n":"第十条","txt":"国家畜禽遗传资源委员会自收到申请材料之日起15个工作日内作出是否受理的决定，并书面通知申请人。不予受理的，应当说明理由。"},{"i":11,"n":"第十一条","txt":"国家畜禽遗传资源委员会受理申请后，应当组织专业委员会进行初审。初审专家不少于5人。"},{"i":12,"n":"第十二条","txt":"初审可以采取下列方式： （一）书面审查； （二）现场考察、测试或者演示； （三）答辩； （四）会议讨论。"},{"i":13,"n":"第十三条","txt":"初审结论应当经三分之二以上专家通过，不同意见应当载明。"},{"i":14,"n":"第十四条","txt":"国家畜禽遗传资源委员会每半年召开一次专门会议，对初审结论进行讨论和表决。出席会议的委员不少于全体委员的三分之二。 表决采取无记名投票方式。同意票数超过到会委员半数的，通过审定或者鉴定。"},{"i":15,"n":"第十五条","txt":"通过审定或者鉴定的畜禽新品种、配套系或者畜禽遗传资源，由国家畜禽遗传资源委员会在中国农业信息网（www.agri.gov.cn）公示，公示期为一个月。 公示期满无异议的，由国家畜禽遗传资源委员会颁发证书并报农业部公告。"},{"i":16,"n":"第十六条","txt":"未通过审定或鉴定的，国家畜禽遗传资源委员会办公室应当在30个工作日内书面通知申请人。申请人有异议的，应当在接到通知后30个工作日内申请复审。国家畜禽遗传资源委员会应当在6个月内作出复审决定，并通知申请人。"},{"i":17,"n":"第十七条","txt":"畜禽新品种、配套系申请审定前，培育者可以进行中间试验，对品种、配套系的生产性能、适应性、抗逆性等进行验证。"},{"i":18,"n":"第十八条","txt":"中间试验应当经试验所在地省级人民政府畜牧行政主管部门批准，培育者应当提交下列材料： （一）新品种、配套系暂定名； （二）新品种、配套系特征、特性； （三）拟进行中间试验的地点、期限和规模等。"},{"i":19,"n":"第十九条","txt":"省级人民政府畜牧行政主管部门应当自收到申请之日起15个工作日内做出是否批准的决定。决定批准的，应当明确中间试验的地点、期限、规模及培育者应承担的责任；不予批准的，书面通知申请人并说明理由。 培育者不得改变中间试验的地点、期限和规模。确需改变的，应当报原批准机关批准。 中间试验结束后，培育者应当向批准机关提交书面报告。"},{"i":20,"n":"第二十条","txt":"申请人隐瞒有关情况或者提供虚假材料的，不予受理，并给予警告，一年之内不得再次申请审定或者鉴定。已通过审定或者鉴定的，收回并注销证书，申请人三年之内不得再次申请审定或者鉴定。"},{"i":21,"n":"第二十一条","txt":"已审定通过的新品种、配套系在生产推广过程中发现有重大缺陷的，经国家畜禽遗传资源委员会论证，由农业部作出停止生产、推广的决定，并予以公告，国家畜禽遗传资源委员会收回证书。"},{"i":22,"n":"第二十二条","txt":"审定或者鉴定专家及其工作人员应当保守秘密，违反规定的，依照国家保密法有关规定处罚。"},{"i":23,"n":"第二十三条","txt":"其他违反本办法的行为，依照《中华人民共和国畜牧法》的有关规定处罚。"},{"i":24,"n":"第二十四条","txt":"审定或者鉴定所需的试验、检测等费用由申请人承担，具体标准按照国家有关规定执行。"},{"i":25,"n":"第二十五条","txt":"转基因畜禽品种的培育、试验、审定，还应当符合国家有关农业转基因生物安全管理的规定。"},{"i":26,"n":"第二十六条","txt":"本办法自2006年7月1日起施行。本办法施行前，省级人民政府畜牧行政主管部门审定通过的畜禽新品种、配套系，需要跨省推广的，应当依照本办法申请审定。"}],"chuqinbiaoshiheyangzhidanganguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范畜牧业生产经营行为，加强畜禽标识和养殖档案管理，建立畜禽及畜禽产品可追溯制度，有效防控重大动物疫病，保障畜禽产品质量安全，依据《中华人民共和国畜牧法》、《中华人民共和国动物防疫法》和《中华人民共和国农产品质量安全法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称畜禽标识是指经农业部批准使用的耳标、电子标签、脚环以及其他承载畜禽信息的标识物。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内从事畜禽及畜禽产品生产、经营、运输等活动，应当遵守本办法。"},{"i":4,"n":"第四条","txt":"农业部负责全国畜禽标识和养殖档案的监督管理工作。 县级以上地方人民政府畜牧兽医行政主管部门负责本行政区域内畜禽标识和养殖档案的监督管理工作。"},{"i":5,"n":"第五条","txt":"畜禽标识制度应当坚持统一规划、分类指导、分步实施、稳步推进的原则。"},{"i":6,"n":"第六条","txt":"畜禽标识所需费用列入省级人民政府财政预算。"},{"i":7,"n":"第七条","txt":"畜禽标识实行一畜一标，编码应当具有唯一性。"},{"i":8,"n":"第八条","txt":"畜禽标识编码由畜禽种类代码、县级行政区域代码、标识顺序号共15位数字及专用条码组成。 猪、牛、羊的畜禽种类代码分别为1、2、3。 编码形式为：×（种类代码）－××××××（县级行政区域代码）－××××××××（标识顺序号）。"},{"i":9,"n":"第九条","txt":"农业部制定并公布畜禽标识技术规范，生产企业生产的畜禽标识应当符合该规范规定。 省级动物疫病预防控制机构统一采购畜禽标识，逐级供应。"},{"i":10,"n":"第十条","txt":"畜禽标识生产企业不得向省级动物疫病预防控制机构以外的单位和个人提供畜禽标识。"},{"i":11,"n":"第十一条","txt":"畜禽养殖者应当向当地县级动物疫病预防控制机构申领畜禽标识，并按照下列规定对畜禽加施畜禽标识： （一）新出生畜禽，在出生后30天内加施畜禽标识；30天内离开饲养地的，在离开饲养地前加施畜禽标识；从国外引进畜禽，在畜禽到达目的地10日内加施畜禽标识。 （二）猪、牛、羊在左耳中部加施畜禽标识，需要再次加施畜禽标识的，在右耳中部加施。"},{"i":12,"n":"第十二条","txt":"畜禽标识严重磨损、破损、脱落后，应当及时加施新的标识，并在养殖档案中记录新标识编码。"},{"i":13,"n":"第十三条","txt":"动物卫生监督机构实施产地检疫时，应当查验畜禽标识。没有加施畜禽标识的，不得出具检疫合格证明。"},{"i":14,"n":"第十四条","txt":"动物卫生监督机构应当在畜禽屠宰前，查验、登记畜禽标识。 畜禽屠宰经营者应当在畜禽屠宰时回收畜禽标识，由动物卫生监督机构保存、销毁。"},{"i":15,"n":"第十五条","txt":"畜禽经屠宰检疫合格后，动物卫生监督机构应当在畜禽产品检疫标志中注明畜禽标识编码。"},{"i":16,"n":"第十六条","txt":"省级人民政府畜牧兽医行政主管部门应当建立畜禽标识及所需配套设备的采购、保管、发放、使用、登记、回收、销毁等制度。"},{"i":17,"n":"第十七条","txt":"畜禽标识不得重复使用。"},{"i":18,"n":"第十八条","txt":"畜禽养殖场应当建立养殖档案，载明以下内容： （一）畜禽的品种、数量、繁殖记录、标识情况、来源和进出场日期； （二）饲料、饲料添加剂等投入品和兽药的来源、名称、使用对象、时间和用量等有关情况； （三）检疫、免疫、监测、消毒情况； （四）畜禽发病、诊疗、死亡和无害化处理情况； （五）畜禽养殖代码； （六）农业部规定的其他内容。"},{"i":19,"n":"第十九条","txt":"县级动物疫病预防控制机构应当建立畜禽防疫档案，载明以下内容： （一）畜禽养殖场：名称、地址、畜禽种类、数量、免疫日期、疫苗名称、畜禽养殖代码、畜禽标识顺序号、免疫人员以及用药记录等。 （二）畜禽散养户：户主姓名、地址、畜禽种类、数量、免疫日期、疫苗名称、畜禽标识顺序号、免疫人员以及用药记录等。"},{"i":20,"n":"第二十条","txt":"畜禽养殖场、养殖小区应当依法向所在地县级人民政府畜牧兽医行政主管部门备案，取得畜禽养殖代码。 畜禽养殖代码由县级人民政府畜牧兽医行政主管部门按照备案顺序统一编号，每个畜禽养殖场、养殖小区只有一个畜禽养殖代码。 畜禽养殖代码由6位县级行政区域代码和4位顺序号组成，作为养殖档案编号。"},{"i":21,"n":"第二十一条","txt":"饲养种畜应当建立个体养殖档案，注明标识编码、性别、出生日期、父系和母系品种类型、母本的标识编码等信息。 种畜调运时应当在个体养殖档案上注明调出和调入地，个体养殖档案应当随同调运。"},{"i":22,"n":"第二十二条","txt":"养殖档案和防疫档案保存时间：商品猪、禽为2年，牛为20年，羊为10年，种畜禽长期保存。"},{"i":23,"n":"第二十三条","txt":"从事畜禽经营的销售者和购买者应当向所在地县级动物疫病预防控制机构报告更新防疫档案相关内容。 销售者或购买者属于养殖场的，应及时在畜禽养殖档案中登记畜禽标识编码及相关信息变化情况。"},{"i":24,"n":"第二十四条","txt":"畜禽养殖场养殖档案及种畜个体养殖档案格式由农业部统一制定。"},{"i":25,"n":"第二十五条","txt":"国家实施畜禽标识及养殖档案信息化管理，实现畜禽及畜禽产品可追溯。"},{"i":26,"n":"第二十六条","txt":"农业部建立包括国家畜禽标识信息中央数据库在内的国家畜禽标识信息管理系统。 省级人民政府畜牧兽医行政主管部门建立本行政区域畜禽标识信息数据库，并成为国家畜禽标识信息中央数据库的子数据库。"},{"i":27,"n":"第二十七条","txt":"县级以上人民政府畜牧兽医行政主管部门根据数据采集要求，组织畜禽养殖相关信息的录入、上传和更新工作。"},{"i":28,"n":"第二十八条","txt":"县级以上地方人民政府畜牧兽医行政主管部门所属动物卫生监督机构具体承担本行政区域内畜禽标识的监督管理工作。"},{"i":29,"n":"第二十九条","txt":"畜禽标识和养殖档案记载的信息应当连续、完整、真实。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，应当对畜禽、畜禽产品实施追溯： （一）标识与畜禽、畜禽产品不符； （二）畜禽、畜禽产品染疫； （三）畜禽、畜禽产品没有检疫证明； （四）违规使用兽药及其他有毒、有害物质； （五）发生重大动物卫生安全事件； （六）其他应当实施追溯的情形。"},{"i":31,"n":"第三十一条","txt":"县级以上人民政府畜牧兽医行政主管部门应当根据畜禽标识、养殖档案等信息对畜禽及畜禽产品实施追溯和处理。"},{"i":32,"n":"第三十二条","txt":"国外引进的畜禽在国内发生重大动物疫情，由农业部会同有关部门进行追溯。"},{"i":33,"n":"第三十三条","txt":"任何单位和个人不得销售、收购、运输、屠宰应当加施标识而没有标识的畜禽。"},{"i":34,"n":"第三十四条","txt":"违反本办法规定的，按照《中华人民共和国畜牧法》、《中华人民共和国动物防疫法》和《中华人民共和国农产品质量安全法》的有关规定处罚。"},{"i":35,"n":"第三十五条","txt":"本办法自2006年7月1日起施行，2002年5月24日农业部发布的《动物免疫标识管理办法》（农业部令第13号）同时废止。 猪、牛、羊以外其他畜禽标识实施时间和具体措施由农业部另行规定。"}],"chuqinyichuanziyuanbaozhongchangbaohuquhejiyinkugu218314":[{"i":1,"n":"第一条","txt":"为了加强畜禽遗传资源保护与管理，根据《中华人民共和国畜牧法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"畜禽遗传资源保种场、保护区、基因库的建立或者确定、监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"农业部负责全国畜禽遗传资源保种场、保护区、基因库的管理，并负责建立或者确定国家级畜禽遗传资源保种场、保护区和基因库. 省级人民政府畜牧行政主管部门负责本行政区域内畜禽遗传资源保种场、保护区、基因库的管理，并负责建立或者确定省级畜禽遗传资源保种场、保护区和基因库。"},{"i":4,"n":"第四条","txt":"全国畜牧总站承担国家级畜禽遗传资源保种场、保护区、基因库的具体管理工作。"},{"i":5,"n":"第五条","txt":"国家级畜禽遗传资源保种场应当具备下列条件： （一）场址在原产地或与原产地自然生态条件一致或相近的区域； （二）场区布局合理，生产区与办公区、生活区隔离分开。办公区设技术室、资料档案室等。生产区设置饲养繁育场地、兽医室、隔离舍、畜禽无害化处理、粪污排放处理等场所，配备相应的设施设备，防疫条件符合《中华人民共和国动物防疫法》等有关规定； （三）有与保种规模相适应的畜牧兽医技术人员。主管生产的技术负责人具备大专以上相关专业学历或中级以上技术职称；直接从事保种工作的技术人员需经专业技术培训，掌握保护畜禽遗传资源的基本知识和技能； （四）符合种用标准的单品种基础畜禽数量要求： 猪：母猪100头以上，公猪12头以上，三代之内没有血缘关系的家系数不少于6个。 牛、马、驴、骆驼：母畜150头（匹、峰）以上，公畜12头（匹、峰）以上，三代之内没有血缘关系的家系数不少于6个。 羊：母羊250只以上，公羊2"},{"i":6,"n":"第六条","txt":"国家级畜禽遗传资源保护区应当具备下列条件： （一）设在畜禽遗传资源的中心产区，范围界限明确； （二）保护区内应有2个以上保种群，保种群之间的距离不小于3公里；蜂种保护区具有自然交尾隔离区，其中，山区隔离区半径距离不小于12公里，平原隔离区半径距离不小于16公里； （三）保护区具备一定的群体规模，单品种资源保护数量不少于保种场群体规模的5倍，所保护的畜禽品种质量符合品种标准。"},{"i":7,"n":"第七条","txt":"国家级畜禽遗传资源基因库应当具备下列条件； （一）有固定的场所，所在地及附近地区无重大疫病发生史； （二）有遗传材料保存库、质量检测室、技术研究室、资料档案室等；有畜禽遗传材料制作、保存、检测、运输等设备；具备防疫、防火、防盗、防震等安全设施；水源、电源、液氮供应充足； （三）有从事遗传资源保护工作的专职技术人员。专业技术人员比例不低于70%；从事畜禽遗传材料制作和检测工作的技术人员需经专业技术培训，并取得相应的国家职业资格证书； （四）保存单品种遗传材料数量和质量要求： 牛羊单品种冷冻精液保存3000剂以上，精液质量达到国家有关标准；公畜必须符合其品种标准，级别为特级，系谱清楚，无传染性疾病和遗传疾病，三代之内没有血缘关系的家系数不少于6个。、牛羊单品种冷冻胚胎保存200枚以上，胚胎质量为A级；胚胎供体必须符合其品种标准，系谱清楚，无传染性疾病和遗传疾病；供体公畜为特级，供体母畜为1"},{"i":8,"n":"第八条","txt":"建立或者确定畜禽遗传资源保种场、保护区和基因库，应当符合全国畜禽遗传资源保护和利用规划以及国家级畜禽遗传资源保护名录的要求。"},{"i":9,"n":"第九条","txt":"从事国家级畜禽遗传资源保护名录内畜禽资源保护工作，符合本办法第二章要求的单位或者个人，可以申报国家级畜禽遗传资源保种场、保护区和基因库。"},{"i":10,"n":"第十条","txt":"申请国家级畜禽遗传资源保种场、保护区、基因库的单位或者个人，应当于每年3月底前向省级人民政府畜牧行政主管部门提交下列材料： （一）申请表（见附表）； （二）符合第二章规定条件的说明资料； （三）系谱、选育记录等有关证明材料； （四）保种场和活体保种的基因库还应当提交《种畜禽生产经营许可证》复印件。"},{"i":11,"n":"第十一条","txt":"省级人民政府畜牧行政主管部门应当自申请受理之日起20个工作日内完成初审，并将初审意见和相关材料报送农业部。 农业部自收到申请材料后20个工作日内做出决定，经审查符合条件的，确定为畜禽遗传资源保种场、保护区和基因库，并予以公告；不符合条件的，书面通知申请人并说明理由。 农业部或者省级人民政府畜牧行政主管部门必要时可组织现场审验。"},{"i":12,"n":"第十二条","txt":"畜禽遗传资源保种场、保护区、基因库经公告后，任何单位和个人不得擅自变更其名称、地址、性质或者保护内容；确需变更的，应当按原程序重新申请。"},{"i":13,"n":"第十三条","txt":"县级以上畜牧技术推广机构负责畜禽遗传资源保种场、保护区、基因库的技术指导工作。"},{"i":14,"n":"第十四条","txt":"畜禽遗传资源保种场应当严格实施保种规划，开展选种选配工作，确保保种群体的数量和质量，并准确、完整记录畜禽品种的基本信息。"},{"i":15,"n":"第十五条","txt":"畜禽遗传资源保护区周边交通要道、重要地段，应当由所在地县级以上地方人民政府设立保护标志。"},{"i":16,"n":"第十六条","txt":"畜禽遗传资源基因库应当根据保种计划和工作需要，定期采集、补充和更新畜禽遗传材料，并对保存的遗传材料进行备份。"},{"i":17,"n":"第十七条","txt":"享受中央和省级财政资金支持的畜禽遗传资源保种场、保护区和基因库，未经农业部或者省级人民政府畜牧行政主管部门批准，不得擅自处理受保护的畜禽遗传资源。"},{"i":18,"n":"第十八条","txt":"国家级畜禽遗传资源保种场、保护区、基因库应当在每年1月底前将上年度工作报告报送全国畜牧总站。工作报告内容包括： （一）群体规模数量； （二）主要性状的变化情况； （三）保护与选育的主要工作； （四）财政专项资金使用情况； （五）存在的主要问题、改进措施和建议。"},{"i":19,"n":"第十九条","txt":"全国畜牧总站负责对国家级畜禽遗传资源保种场、保护区、基因库的保种工作进行检查。发现保种工作中存在重大问题的，应当责令限期整改，并及时向农业部提出处理建议。"},{"i":20,"n":"第二十条","txt":"有下列行为之一的，取消国家级畜禽遗传资源保种场、保护区、基因库资格： （一）违反本办法第十七条规定，情节严重的； （二）截留、挤占、挪用专项资金，情节严重的； （三）擅自变更地址或者保护内容的，或者擅自变更名称、性质等且在规定期限内拒不改正的； （四）连续两年不提交工作报告的。"},{"i":21,"n":"第二十一条","txt":"本办法下列用语的含义： （一）保种场，是指有固定场所、相应技术人员、设施设备等基本条件，以活体保护为手段，以保护畜禽遗传资源为目的的单位。 （二）保护区，是指国家或地方为保护特定畜禽遗传资源，在其原产地中心产区划定的特定区域。 （三）基因库，是指在固定区域建立的，有相应人员、设施等基础条件，以低温生物学方法或活体保护为手段，保护多个畜禽遗传资源的单位。基因库保种范围包括活体、组织、胚胎、精液、卵、体细胞、基因物质等遗传材料。"},{"i":22,"n":"第二十二条","txt":"省级畜禽遗传资源保种场、保护区、基因库的基本条件、建立或者确定程序和管理，参照本办法执行。"},{"i":23,"n":"第二十三条","txt":"本办法自2006年7月1日起施行。"}],"bingsichuqinhebinghaichuqinchanpinwuhaihuachuliguaad4f2a":[{"i":1,"n":"第一条","txt":"为了加强病死畜禽和病害畜禽产品无害化处理管理，防控动物疫病，促进畜牧业高质量发展，保障公共卫生安全和人体健康，根据《中华人民共和国动物防疫法》（以下简称《动物防疫法》），制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于畜禽饲养、屠宰、经营、隔离、运输等过程中病死畜禽和病害畜禽产品的收集、无害化处理及其监督管理活动。 发生重大动物疫情时，应当根据动物疫病防控要求开展病死畜禽和病害畜禽产品无害化处理。"},{"i":3,"n":"第三条","txt":"下列畜禽和畜禽产品应当进行无害化处理： （一）染疫或者疑似染疫死亡、因病死亡或者死因不明的； （二）经检疫、检验可能危害人体或者动物健康的； （三）因自然灾害、应激反应、物理挤压等因素死亡的； （四）屠宰过程中经肉品品质检验确认为不可食用的； （五）死胎、木乃伊胎等； （六）因动物疫病防控需要被扑杀或销毁的； （七）其他应当进行无害化处理的。"},{"i":4,"n":"第四条","txt":"病死畜禽和病害畜禽产品无害化处理坚持统筹规划与属地负责相结合、政府监管与市场运作相结合、财政补助与保险联动相结合、集中处理与自行处理相结合的原则。"},{"i":5,"n":"第五条","txt":"从事畜禽饲养、屠宰、经营、隔离等活动的单位和个人，应当承担主体责任，按照本办法对病死畜禽和病害畜禽产品进行无害化处理，或者委托病死畜禽无害化处理场处理。 运输过程中发生畜禽死亡或者因检疫不合格需要进行无害化处理的，承运人应当立即通知货主，配合做好无害化处理，不得擅自弃置和处理。"},{"i":6,"n":"第六条","txt":"在江河、湖泊、水库等水域发现的死亡畜禽，依法由所在地县级人民政府组织收集、处理并溯源。 在城市公共场所和乡村发现的死亡畜禽，依法由所在地街道办事处、乡级人民政府组织收集、处理并溯源。"},{"i":7,"n":"第七条","txt":"病死畜禽和病害畜禽产品收集、无害化处理、资源化利用应当符合农业农村部相关技术规范, 并采取必要的防疫措施，防止传播动物疫病。"},{"i":8,"n":"第八条","txt":"农业农村部主管全国病死畜禽和病害畜禽产品无害化处理工作。 县级以上地方人民政府农业农村主管部门负责本行政区域病死畜禽和病害畜禽产品无害化处理的监督管理工作。"},{"i":9,"n":"第九条","txt":"省级人民政府农业农村主管部门结合本行政区域畜牧业发展规划和畜禽养殖、疫病发生、畜禽死亡等情况，编制病死畜禽和病害畜禽产品集中无害化处理场所建设规划，合理布局病死畜禽无害化处理场，经本级人民政府批准后实施，并报农业农村部备案。 鼓励跨县级以上行政区域建设病死畜禽无害化处理场。"},{"i":10,"n":"第十条","txt":"县级以上人民政府农业农村主管部门应当落实病死畜禽无害化处理财政补助政策和农机购置补贴与应用政策，协调有关部门优先保障病死畜禽无害化处理场用地、落实税收优惠政策，推动建立病死畜禽无害化处理和保险联动机制，将病死畜禽无害化处理作为保险理赔的前提条件。"},{"i":11,"n":"第十一条","txt":"畜禽养殖场、养殖户、屠宰厂（场）、隔离场应当及时对病死畜禽和病害畜禽产品进行贮存和清运。 畜禽养殖场、屠宰厂（场）、隔离场委托病死畜禽无害化处理场处理的，应当符合以下要求： （一）采取必要的冷藏冷冻、清洗消毒等措施； （二）具有病死畜禽和病害畜禽产品专用输出通道； （三）及时通知病死畜禽无害化处理场进行收集，或自行送至指定地点。"},{"i":12,"n":"第十二条","txt":"病死畜禽和病害畜禽产品集中暂存点应当具备下列条件： （一）有独立封闭的贮存区域，并且防渗、防漏、防鼠、防盗，易于清洗消毒； （二）有冷藏冷冻、清洗消毒等设施设备； （三）设置显著警示标识； （四）有符合动物防疫需要的其他设施设备。"},{"i":13,"n":"第十三条","txt":"专业从事病死畜禽和病害畜禽产品收集的单位和个人，应当配备专用运输车辆，并向承运人所在地县级人民政府农业农村主管部门备案。备案时应当通过农业农村部指定的信息系统提交车辆所有权人的营业执照、运输车辆行驶证、运输车辆照片。 县级人民政府农业农村主管部门应当核实相关材料信息，备案材料符合要求的，及时予以备案；不符合要求的，应当一次性告知备案人补充相关材料。"},{"i":14,"n":"第十四条","txt":"病死畜禽和病害畜禽产品专用运输车辆应当符合以下要求： （一）不得运输病死畜禽和病害畜禽产品以外的其他物品； （二）车厢密闭、防水、防渗、耐腐蚀，易于清洗和消毒； （三）配备能够接入国家监管监控平台的车辆定位跟踪系统、车载终端； （四）配备人员防护、清洗消毒等应急防疫用品； （五）有符合动物防疫需要的其他设施设备。"},{"i":15,"n":"第十五条","txt":"运输病死畜禽和病害畜禽产品的单位和个人，应当遵守下列规定： （一）及时对车辆、相关工具及作业环境进行消毒； （二）作业过程中如发生渗漏，应当妥善处理后再继续运输； （三）做好人员防护和消毒。"},{"i":16,"n":"第十六条","txt":"跨县级以上行政区域运输病死畜禽和病害畜禽产品的，相关区域县级以上地方人民政府农业农村主管部门应当加强协作配合，及时通报紧急情况，落实监管责任。"},{"i":17,"n":"第十七条","txt":"病死畜禽和病害畜禽产品无害化处理以集中处理为主，自行处理为补充。 病死畜禽无害化处理场的设计处理能力应当高于日常病死畜禽和病害畜禽产品处理量，专用运输车辆数量和运载能力应当与区域内畜禽养殖情况相适应。"},{"i":18,"n":"第十八条","txt":"病死畜禽无害化处理场应当符合省级人民政府病死畜禽和病害畜禽产品集中无害化处理场所建设规划并依法取得动物防疫条件合格证。"},{"i":19,"n":"第十九条","txt":"畜禽养殖场、屠宰厂（场）、隔离场在本场（厂）内自行处理病死畜禽和病害畜禽产品的，应当符合无害化处理场所的动物防疫条件，不得处理本场（厂）外的病死畜禽和病害畜禽产品。 畜禽养殖场、屠宰厂（场）、隔离场在本场（厂）外自行处理的，应当建设病死畜禽无害化处理场。"},{"i":20,"n":"第二十条","txt":"畜禽养殖场、养殖户、屠宰厂（场）、隔离场委托病死畜禽无害化处理场进行无害化处理的，应当签订委托合同，明确双方的权利、义务。 无害化处理费用由财政进行补助或者由委托方承担。"},{"i":21,"n":"第二十一条","txt":"对于边远和交通不便地区以及畜禽养殖户自行处理零星病死畜禽的，省级人民政府农业农村主管部门可以结合实际情况和风险评估结果，组织制定相关技术规范。"},{"i":22,"n":"第二十二条","txt":"病死畜禽和病害畜禽产品集中暂存点、病死畜禽无害化处理场应当配备专门人员负责管理。 从事病死畜禽和病害畜禽产品无害化处理的人员，应当具备相关专业技能，掌握必要的安全防护知识。"},{"i":23,"n":"第二十三条","txt":"鼓励在符合国家有关法律法规规定的情况下，对病死畜禽和病害畜禽产品无害化处理产物进行资源化利用。 病死畜禽和病害畜禽产品无害化处理场所销售无害化处理产物的，应当严控无害化处理产物流向，查验购买方资质并留存相关材料，签订销售合同。"},{"i":24,"n":"第二十四条","txt":"病死畜禽和病害畜禽产品无害化处理应当符合安全生产、环境保护等相关法律法规和标准规范要求，接受有关主管部门监管。 病死畜禽无害化处理场处理本办法第三条之外的病死动物和病害动物产品的，应当要求委托方提供无特殊风险物质的证明。"},{"i":25,"n":"第二十五条","txt":"农业农村部建立病死畜禽无害化处理监管监控平台，加强全程追溯管理。 从事畜禽饲养、屠宰、经营、隔离及病死畜禽收集、无害化处理的单位和个人，应当按要求填报信息。 县级以上地方人民政府农业农村主管部门应当做好信息审核，加强数据运用和安全管理。"},{"i":26,"n":"第二十六条","txt":"农业农村部负责组织制定全国病死畜禽和病害畜禽产品无害化处理生物安全风险调查评估方案，对病死畜禽和病害畜禽产品收集、无害化处理生物安全风险因素进行调查评估。 省级人民政府农业农村主管部门应当制定本行政区域病死畜禽和病害畜禽产品无害化处理生物安全风险调查评估方案并组织实施。"},{"i":27,"n":"第二十七条","txt":"根据病死畜禽无害化处理场规模、设施装备状况、管理水平等因素，推行分级管理制度。"},{"i":28,"n":"第二十八条","txt":"病死畜禽和病害畜禽产品无害化处理场所应当建立并严格执行以下制度： （一）设施设备运行管理制度； （二）清洗消毒制度； （三）人员防护制度； （四）生物安全制度； （五）安全生产和应急处理制度。"},{"i":29,"n":"第二十九条","txt":"从事畜禽饲养、屠宰、经营、隔离以及病死畜禽和病害畜禽产品收集、无害化处理的单位和个人，应当建立台账，详细记录病死畜禽和病害畜禽产品的种类、数量（重量）、来源、运输车辆、交接人员和交接时间、处理产物销售情况等信息。 病死畜禽和病害畜禽产品处理场所应当安装视频监控设备，对病死畜禽和病害畜禽产品进（出）场、交接、处理和处理产物存放等进行全程监控。 相关台账记录保存期不少于二年，相关监控影像资料保存期不少于三十天。"},{"i":30,"n":"第三十条","txt":"病死畜禽无害化处理场所应当于每年一月底前向所在地县级人民政府农业农村主管部门报告上一年度病死畜禽和病害畜禽产品无害化处理、运输车辆和环境清洗消毒等情况。"},{"i":31,"n":"第三十一条","txt":"县级以上地方人民政府农业农村主管部门执行监督检查任务时，从事病死畜禽和病害畜禽产品收集、无害化处理的单位和个人应当予以配合，不得拒绝或者阻碍。"},{"i":32,"n":"第三十二条","txt":"任何单位和个人对违反本办法规定的行为，有权向县级以上地方人民政府农业农村主管部门举报。接到举报的部门应当及时调查处理。"},{"i":33,"n":"第三十三条","txt":"未按照本办法第十一条、第十二条、第十五条、第十九条、第二十二条规定处理病死畜禽和病害畜禽产品的，按照《动物防疫法》第九十八条规定予以处罚。"},{"i":34,"n":"第三十四条","txt":"畜禽养殖场、屠宰厂（场）、隔离场、病死畜禽无害化处理场未取得动物防疫条件合格证或生产经营条件发生变化，不再符合动物防疫条件继续从事无害化处理活动的，分别按照《动物防疫法》第九十八条、第九十九条处罚。"},{"i":35,"n":"第三十五条","txt":"专业从事病死畜禽和病害畜禽产品运输的车辆，未经备案或者不符合本办法第十四条规定的，分别按照《动物防疫法》第九十八条、第九十四条处罚。"},{"i":36,"n":"第三十六条","txt":"违反本办法第二十八条、第二十九条规定，未建立管理制度、台账或者进行视频监控的，由县级以上地方人民政府农业农村主管部门责令改正；拒不改正或者情节严重的，处二千元以上二万元以下罚款。"},{"i":37,"n":"第三十七条","txt":"本办法下列用语的含义： （一）畜禽，是指《国家畜禽遗传资源目录》范围内的畜禽，不包括用于科学研究、教学、检定以及其他科学实验的畜禽。 （二）隔离场所，是指对跨省、自治区、直辖市引进的乳用种用动物或输入到无规定动物疫病区的相关畜禽进行隔离观察的场所，不包括进出境隔离观察场所。 （三）病死畜禽和病害畜禽产品无害化处理场所，是指病死畜禽无害化处理场以及畜禽养殖场、屠宰厂（场）、隔离场内的无害化处理区域。"},{"i":38,"n":"第三十八条","txt":"病死水产养殖动物和病害水产养殖动物产品的无害化处理，参照本办法执行。"},{"i":39,"n":"第三十九条","txt":"本办法自2022年7月1日起施行。"}],"zhongchuqinshengchanjingyingxukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强种畜禽生产经营许可管理，规范种畜禽生产经营秩序，促进畜禽种业高质量发展，根据《中华人民共和国畜牧法》，制定本办法。"},{"i":2,"n":"第二条","txt":"种畜禽生产经营许可证的申请、核发和监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"从事种畜禽或者商品代仔畜、雏禽生产经营，应当取得种畜禽生产经营许可证。 农户饲养的种畜禽用于自繁自养和有少量剩余仔畜、雏禽出售的，农户饲养种公畜进行互助配种的，不需要办理种畜禽生产经营许可证。"},{"i":4,"n":"第四条","txt":"从事家畜卵子、精液、胚胎等遗传材料和祖代以上种畜禽（含品种和配套系）生产经营的，种畜禽生产经营许可证由所在地省级人民政府农业农村主管部门核发。 从事父母代种畜禽（含品种和配套系）和商品代仔畜、雏禽生产经营的，种畜禽生产经营许可证由所在地县级以上地方人民政府农业农村主管部门核发，具体核发权限由省级人民政府农业农村主管部门确定并公布。"},{"i":5,"n":"第五条","txt":"申请取得种畜禽生产经营许可证，应当具备下列条件： （一）生产经营的种畜禽是通过国家畜禽遗传资源委员会审定或者鉴定的品种、配套系，或者是经批准引进的境外品种、配套系，来源清楚且符合种用标准； （二）生产经营规模符合种畜禽养殖场规模标准（从事家畜卵子、精液、胚胎等遗传材料生产经营的除外）； （三）有与生产经营规模相适应的繁育饲养、疫病防控等专业的畜牧兽医技术人员； （四）有与生产经营规模相适应的繁育饲养、生产性能测定等设施设备； （五）具备法律、行政法规和农业农村部规定的种畜禽防疫条件，并取得动物防疫条件合格证； （六）有完善的质量管理、育种记录制度； （七）法律、行政法规规定的其他条件。"},{"i":6,"n":"第六条","txt":"从事家畜卵子、精液、胚胎等遗传材料生产经营，除符合本办法第五条规定外，还应当具备下列条件： （一）有与生产经营规模相适应的家畜饲养、繁育、治疗场地和家畜遗传材料生产、质量检测、产品储存、档案管理场所； （二）有与生产经营规模相适应的家畜饲养和遗传材料生产、检测、保存、运输等设施设备； （三）饲养的种畜符合种用标准，并达到农业农村部规定的数量； （四）体外受精取得的胚胎、使用的卵子来源明确，三代系谱清楚，供体畜符合国家规定的种畜健康标准和质量要求； （五）符合有关国家强制性标准和农业农村部规定的其他技术要求。"},{"i":7,"n":"第七条","txt":"申请取得种畜禽生产经营许可证，应当提交以下材料： （一）种畜禽生产经营许可证申请表； （二）生产经营者基本情况说明，营业执照复印件，法定代表人（负责人）身份证复印件； （三）种畜禽生产群存栏规模情况说明； （四）畜牧兽医技术人员情况说明及证明材料； （五）生产经营场所平面图； （六）设施设备情况说明； （七）质量管理、档案记录、销售台账等制度材料； （八）种畜禽来源说明及系谱档案复印件； （九）动物防疫条件合格证复印件； （十）农业农村部规定的其他材料。"},{"i":8,"n":"第八条","txt":"县级以上地方人民政府农业农村主管部门对申请人提出的申请，应当根据下列情况分别作出处理： （一）不需要取得种畜禽生产经营许可的，应当即时告知申请人不受理； （二）不属于本部门职权范围的，应当即时作出不予受理的决定，并告知申请人向有审批权限的部门申请； （三）申请材料存在可以当场更正的错误的，应当允许申请人当场更正； （四）申请材料不齐全或者不符合法定形式的，应当当场或者在五个工作日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （五）申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正申请材料的，予以受理。"},{"i":9,"n":"第九条","txt":"县级以上地方人民政府农业农村主管部门应当成立专家组，对申请人的种畜禽来源、品种代别、饲养规模、技术人员条件、设施设备、档案记录等进行现场评审。专家组由三至五名专家组成，从种畜禽生产经营许可评审专家库中随机抽取，实行组长负责制。 种畜禽生产经营许可评审专家库由省级人民政府农业农村主管部门建立并报农业农村部备案。"},{"i":10,"n":"第十条","txt":"申请家畜卵子、精液、胚胎等遗传材料种畜禽生产经营许可证的，省级人民政府农业农村主管部门应当自受理申请之日起六十个工作日内（含现场评审时间）作出许可决定。 申请其他种畜禽生产经营许可证的，农业农村主管部门应当自受理申请之日起五个工作日内完成书面审查，书面审查合格的，应当在二十五个工作日内完成现场评审，并自收到评审意见后十五个工作日内作出许可决定。 农业农村主管部门作出的准予核发种畜禽生产经营许可证的决定，应当依法向社会公开。不予许可的，应当书面通知申请人并说明理由。"},{"i":11,"n":"第十一条","txt":"种畜禽生产经营许可证应当注明许可证编号、生产经营者名称、生产经营地址、法定代表人（负责人）、生产经营范围、生产经营类型、生产经营畜禽种类和品种、有效期、统一社会信用代码、生产经营主体代码、发证机关、发证日期等内容，具体样式由农业农村部制定并发布。 种畜禽生产经营许可证由农业农村部统一印制。"},{"i":12,"n":"第十二条","txt":"种畜禽生产经营许可证有效期为五年。有效期届满需要继续生产经营的，申请人应当在期满六个月前重新申请。"},{"i":13,"n":"第十三条","txt":"有效期内有下列情形之一的，应当向原发证机关申请变更许可证并提交变更申请表及证明材料，符合条件的，原发证机关应当在十五个工作日内予以变更： （一）变更生产经营者名称； （二）变更法定代表人（负责人）； （三）从事父母代种畜禽（含品种和配套系）和商品代仔畜、雏禽生产经营，需要变更其生产经营的畜禽品种。"},{"i":14,"n":"第十四条","txt":"有效期内有下列情形之一的，应当重新申请种畜禽生产经营许可： （一）变更生产经营类型； （二）变更生产经营畜禽种类； （三）变更生产经营场所； （四）从事家畜卵子、精液、胚胎等遗传材料和祖代以上种畜禽（含品种和配套系）生产经营，变更其生产经营的畜禽品种。"},{"i":15,"n":"第十五条","txt":"种畜禽生产经营许可证有下列情形之一的，发证机关应当注销并予以公告： （一）有效期届满未延续； （二）依法被撤销、撤回、吊销； （三）法律、法规规定应当注销行政许可的其他情形。"},{"i":16,"n":"第十六条","txt":"种畜禽生产经营许可证的申请、受理、审核、核发，在中国种业大数据平台办理。"},{"i":17,"n":"第十七条","txt":"种畜禽生产经营者应当建立生产经营档案。 生产经营档案应当包括以下内容： （一）畜禽种类、品种（配套系）名称、繁育生产记录、兽药使用及疫病检测记录、场内生产性能测定记录、种畜禽系谱等； （二）种畜禽销售对象姓名及地址、品种（配套系）名称、销售数量、销售时间、销售票据以及检疫证明、种畜禽合格证明； （三）生产经营遗传材料的，还应当包括生产时间地点、加工包装规格、标签标注说明、出入库数量、质量检验报告等。 种畜禽生产经营档案应当至少保存两年，档案记载信息应当连续、完整、真实，保证可追溯。"},{"i":18,"n":"第十八条","txt":"种畜禽生产经营者应当在每年1月31日前登录中国种业大数据平台填报年度种畜禽存栏量、销售量及种畜禽生产性能等信息。"},{"i":19,"n":"第十九条","txt":"申请人隐瞒有关情况或者提供虚假材料申请种畜禽生产经营许可证的，县级以上地方人民政府农业农村主管部门应当不予受理或者不予行政许可并给予警告；申请人在一年内不得再次申请种畜禽生产经营许可证。 申请人以欺骗、贿赂等不正当手段取得种畜禽生产经营许可证的，县级以上地方人民政府农业农村主管部门应当撤销种畜禽生产经营许可证；申请人在三年内不得再次申请种畜禽生产经营许可证。"},{"i":20,"n":"第二十条","txt":"县级以上人民政府农业农村主管部门应当加强种畜禽质量安全监督管理工作，组织开展种畜禽生产性能测定和遗传材料质量检验检测等监督抽查工作。发现有违法行为的，按照《中华人民共和国畜牧法》有关规定进行处理。"},{"i":21,"n":"第二十一条","txt":"种畜禽养殖场的养殖规模标准和生产经营许可审查规范，由农业农村部另行制定。"},{"i":22,"n":"第二十二条","txt":"本办法自2025年7月1日起施行。原农业部2010年1月21日发布、2015年10月30日修订的《家畜遗传材料生产许可办法》（农业部令2015年第3号）同时废止。 本办法实施之前取得的种畜禽生产经营许可证有效期不变，届满需要继续生产经营的，按照本办法办理。"}],"lvseshipinbiaozhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强绿色食品标志使用管理，确保绿色食品信誉，促进绿色食品事业健康发展，维护生产经营者和消费者合法权益，根据《中华人民共和国农业法》、《中华人民共和国食品安全法》、《中华人民共和国农产品质量安全法》和《中华人民共和国商标法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称绿色食品，是指产自优良生态环境、按照绿色食品标准生产、实行全程质量控制并获得绿色食品标志使用权的安全、优质食用农产品及相关产品。"},{"i":3,"n":"第三条","txt":"绿色食品标志依法注册为证明商标，受法律保护。"},{"i":4,"n":"第四条","txt":"县级以上人民政府农业农村主管部门依法对绿色食品及绿色食品标志进行监督管理。"},{"i":5,"n":"第五条","txt":"中国绿色食品发展中心负责全国绿色食品标志使用申请的审查、颁证和颁证后跟踪检查工作。 省级人民政府农业行政农村部门所属绿色食品工作机构（以下简称省级工作机构）负责本行政区域绿色食品标志使用申请的受理、初审和颁证后跟踪检查工作。"},{"i":6,"n":"第六条","txt":"绿色食品产地环境、生产技术、产品质量、包装贮运等标准和规范，由农业农村部制定并发布。"},{"i":7,"n":"第七条","txt":"承担绿色食品产品和产地环境检测工作的技术机构，应当具备相应的检测条件和能力，并依法经过资质认定，由中国绿色食品发展中心按照公平、公正、竞争的原则择优指定并报农业农村部备案。"},{"i":8,"n":"第八条","txt":"县级以上地方人民政府农业农村主管部门应当鼓励和扶持绿色食品生产，将其纳入本地农业和农村经济发展规划，支持绿色食品生产基地建设。"},{"i":9,"n":"第九条","txt":"申请使用绿色食品标志的产品，应当符合《中华人民共和国食品安全法》和《中华人民共和国农产品质量安全法》等法律法规规定，在国家知识产权局商标局核定的范围内，并具备下列条件： （一）产品或产品原料产地环境符合绿色食品产地环境质量标准； （二）农药、肥料、饲料、兽药等投入品使用符合绿色食品投入品使用准则； （三）产品质量符合绿色食品产品质量标准； （四）包装贮运符合绿色食品包装贮运标准。"},{"i":10,"n":"第十条","txt":"申请使用绿色食品标志的生产单位（以下简称申请人），应当具备下列条件： （一）能够独立承担民事责任； （二）具有绿色食品生产的环境条件和生产技术； （三）具有完善的质量管理和质量保证体系； （四）具有与生产规模相适应的生产技术人员和质量控制人员； （五）具有稳定的生产基地； （六）申请前三年内无质量安全事故和不良诚信记录。"},{"i":11,"n":"第十一条","txt":"申请人应当向省级工作机构提出申请，并提交下列材料： （一）标志使用申请书； （二）产品生产技术规程和质量控制规范； （三）预包装产品包装标签或其设计样张； （四）中国绿色食品发展中心规定提交的其他证明材料。"},{"i":12,"n":"第十二条","txt":"省级工作机构应当自收到申请之日起十个工作日内完成材料审查。符合要求的，予以受理，并在产品及产品原料生产期内组织有资质的检查员完成现场检查；不符合要求的，不予受理，书面通知申请人并告知理由。 现场检查合格的，省级工作机构应当书面通知申请人，由申请人委托符合第七条规定的检测机构对申请产品和相应的产地环境进行检测；现场检查不合格的，省级工作机构应当退回申请并书面告知理由。"},{"i":13,"n":"第十三条","txt":"检测机构接受申请人委托后，应当及时安排现场抽样，并自产品样品抽样之日起二十个工作日内、环境样品抽样之日起三十个工作日内完成检测工作，出具产品质量检验报告和产地环境监测报告，提交省级工作机构和申请人。 检测机构应当对检测结果负责。"},{"i":14,"n":"第十四条","txt":"省级工作机构应当自收到产品检验报告和产地环境监测报告之日起二十个工作日内提出初审意见。初审合格的，将初审意见及相关材料报送中国绿色食品发展中心。初审不合格的，退回申请并书面告知理由。 省级工作机构应当对初审结果负责。"},{"i":15,"n":"第十五条","txt":"中国绿色食品发展中心应当自收到省级工作机构报送的申请材料之日起三十个工作日内完成书面审查，并在二十个工作日内组织专家评审。必要时，应当进行现场核查。"},{"i":16,"n":"第十六条","txt":"中国绿色食品发展中心应当根据专家评审的意见，在五个工作日内作出是否颁证的决定。同意颁证的，与申请人签订绿色食品标志使用合同，颁发绿色食品标志使用证书，并公告；不同意颁证的，书面通知申请人并告知理由。"},{"i":17,"n":"第十七条","txt":"绿色食品标志使用证书是申请人合法使用绿色食品标志的凭证，应当载明准许使用的产品名称、商标名称、获证单位及其信息编码、核准产量、产品编号、标志使用有效期、颁证机构等内容。 绿色食品标志使用证书分中文、英文版本，具有同等效力。"},{"i":18,"n":"第十八条","txt":"绿色食品标志使用证书有效期三年。 证书有效期满，需要继续使用绿色食品标志的，标志使用人应当在有效期满三个月前向省级工作机构书面提出续展申请。省级工作机构应当在四十个工作日内组织完成相关检查、检测及材料审核。初审合格的，由中国绿色食品发展中心在十个工作日内作出是否准予续展的决定。准予续展的，与标志使用人续签绿色食品标志使用合同，颁发新的绿色食品标志使用证书并公告；不予续展的，书面通知标志使用人并告知理由。 标志使用人逾期未提出续展申请，或者申请续展未获通过的，不得继续使用绿色食品标志。"},{"i":19,"n":"第十九条","txt":"标志使用人在证书有效期内享有下列权利： （一）在获证产品及其包装、标签、说明书上使用绿色食品标志； （二）在获证产品的广告宣传、展览展销等市场营销活动中使用绿色食品标志； （三）在农产品生产基地建设、农业标准化生产、产业化经营、农产品市场营销等方面优先享受相关扶持政策。"},{"i":20,"n":"第二十条","txt":"标志使用人在证书有效期内应当履行下列义务： （一）严格执行绿色食品标准，保持绿色食品产地环境和产品质量稳定可靠； （二）遵守标志使用合同及相关规定，规范使用绿色食品标志； （三）积极配合县级以上人民政府农业农村主管部门的监督检查及其所属绿色食品工作机构的跟踪检查。"},{"i":21,"n":"第二十一条","txt":"未经中国绿色食品发展中心许可，任何单位和个人不得使用绿色食品标志。 禁止将绿色食品标志用于非许可产品及其经营性活动。"},{"i":22,"n":"第二十二条","txt":"在证书有效期内，标志使用人的单位名称、产品名称、产品商标等发生变化的，应当经省级工作机构审核后向中国绿色食品发展中心申请办理变更手续。 产地环境、生产技术等条件发生变化，导致产品不再符合绿色食品标准要求的，标志使用人应当立即停止标志使用，并通过省级工作机构向中国绿色食品发展中心报告。"},{"i":23,"n":"第二十三条","txt":"标志使用人应当健全和实施产品质量控制体系，对其生产的绿色食品质量和信誉负责。"},{"i":24,"n":"第二十四条","txt":"县级以上地方人民政府农业农村主管部门应当加强绿色食品标志的监督管理工作，依法对辖区内绿色食品产地环境、产品质量、包装标识、标志使用等情况进行监督检查。"},{"i":25,"n":"第二十五条","txt":"中国绿色食品发展中心和省级工作机构应当建立绿色食品风险防范及应急处置制度，组织对绿色食品及标志使用情况进行跟踪检查。 省级工作机构应当组织对辖区内绿色食品标志使用人使用绿色食品标志的情况实施年度检查。检查合格的，在标志使用证书上加盖年度检查合格章。"},{"i":26,"n":"第二十六条","txt":"标志使用人有下列情形之一的，由中国绿色食品发展中心取消其标志使用权，收回标志使用证书，并予公告： （一）生产环境不符合绿色食品环境质量标准的； （二）产品质量不符合绿色食品产品质量标准的； （三）年度检查不合格的； （四）未遵守标志使用合同约定的； （五）违反规定使用标志和证书的； （六）以欺骗、贿赂等不正当手段取得标志使用权的。 标志使用人依照前款规定被取消标志使用权的，三年内中国绿色食品发展中心不再受理其申请；情节严重的，永久不再受理其申请。"},{"i":27,"n":"第二十七条","txt":"任何单位和个人不得伪造、转让绿色食品标志和标志使用证书。"},{"i":28,"n":"第二十八条","txt":"国家鼓励单位和个人对绿色食品和标志使用情况进行社会监督。"},{"i":29,"n":"第二十九条","txt":"从事绿色食品检测、审核、监管工作的人员，滥用职权、徇私舞弊和玩忽职守的，依照有关规定给予行政处罚或行政处分；涉嫌犯罪的，及时将案件移送司法机关，依法追究刑事责任。 承担绿色食品产品和产地环境检测工作的技术机构伪造检测结果的，除依法予以处罚外，由中国绿色食品发展中心取消指定，永久不得再承担绿色食品产品和产地环境检测工作。"},{"i":30,"n":"第三十条","txt":"其他违反本办法规定的行为，依照《中华人民共和国食品安全法》、《中华人民共和国农产品质量安全法》和《中华人民共和国商标法》等法律法规处罚。"},{"i":31,"n":"第三十一条","txt":"绿色食品标志有关收费办法及标准，依照国家相关规定执行。"},{"i":32,"n":"第三十二条","txt":"本办法自2012年10月1日起施行。农业部1993年1月11日印发的《绿色食品标志管理办法》（1993农（绿）字第1号）同时废止。"}],"gengdizhiliangdiaochajianceyupingjiabanfa":[{"i":1,"n":"第一条","txt":"为加强耕地质量调查监测与评价工作，根据《农业法》《农产品质量安全法》《基本农田保护条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称耕地质量，是指由耕地地力、土壤健康状况和田间基础设施构成的满足农产品持续产出和质量安全的能力。"},{"i":3,"n":"第三条","txt":"农业部指导全国耕地质量调查监测体系建设。农业部所属相关耕地质量调查监测与保护机构（以下简称“农业部耕地质量监测机构”）组织开展全国耕地质量调查监测与评价工作，指导地方开展耕地质量调查监测与评价工作。 县级以上地方人民政府农业主管部门所属相关耕地质量调查监测与保护机构（以下简称“地方耕地质量监测机构”）负责本行政区域内耕地质量调查监测与评价具体工作。"},{"i":4,"n":"第四条","txt":"耕地质量调查监测与保护机构（以下简称“耕地质量监测机构”）应当具备开展耕地质量调查监测与评价工作的条件和能力。 各级人民政府农业主管部门应当加强耕地质量监测机构的能力建设，对从事耕地质量调查监测与评价工作的人员进行培训。"},{"i":5,"n":"第五条","txt":"农业部负责制定并发布耕地质量调查监测与评价工作的相关技术标准和规范。 省级人民政府农业主管部门可以根据本地区实际情况，制定本行政区域内耕地质量调查监测与评价技术标准和规范。"},{"i":6,"n":"第六条","txt":"各级人民政府农业主管部门应当加强耕地质量调查监测与评价数据的管理，保障数据的完整性、真实性和准确性。 农业部耕地质量监测机构对外提供调查监测与评价数据，须经农业部审核批准。地方耕地质量监测机构对外提供调查监测与评价数据，须经省级人民政府农业主管部门审核批准。"},{"i":7,"n":"第七条","txt":"农业部和省级人民政府农业主管部门应当建立耕地质量信息发布制度。农业部负责发布全国耕地质量信息，省级人民政府农业主管部门负责发布本行政区域内耕地质量信息。"},{"i":8,"n":"第八条","txt":"耕地质量调查包括耕地质量普查、专项调查和应急调查。"},{"i":9,"n":"第九条","txt":"耕地质量普查是以摸清耕地质量状况为目的，按照统一的技术规范，对全国耕地自下而上逐级实施现状调查、采样测试、数据统计、资料汇总、图件编制和成果验收的全面调查。"},{"i":10,"n":"第十条","txt":"耕地质量普查由农业部根据农业生产发展需要，会同有关部门制定工作方案，经国务院批准后组织实施。"},{"i":11,"n":"第十一条","txt":"耕地质量专项调查包括耕地质量等级调查、特定区域耕地质量调查、耕地质量特定指标调查和新增耕地质量调查。"},{"i":12,"n":"第十二条","txt":"耕地质量等级调查是为评价耕地质量等级情况而实施的调查。 各级耕地质量监测机构负责组织本行政区域内耕地质量等级调查。"},{"i":13,"n":"第十三条","txt":"特定区域耕地质量调查是在一定区域内实施的耕地质量及其相关情况的调查。 特定区域耕地质量调查由县级以上人民政府农业主管部门根据工作需要确定区域范围，报请同级人民政府同意后组织实施。"},{"i":14,"n":"第十四条","txt":"耕地质量特定指标调查是为了解耕地质量某些特定指标而实施的调查。 耕地质量特定指标调查由县级以上人民政府农业主管部门根据工作需要确定指标，报请同级人民政府同意后组织实施。"},{"i":15,"n":"第十五条","txt":"新增耕地质量调查是为了解新增耕地质量状况、农业生产基本条件和能力而实施的调查。 新增耕地质量调查与占补平衡补充耕地质量评价工作同步开展。"},{"i":16,"n":"第十六条","txt":"耕地质量应急调查是因重大事故或突发事件，发生可能污染或破坏耕地质量的情况时实施的调查。 各级人民政府农业主管部门应当根据事故或突发事件性质，配合相关部门确定应急调查的范围和内容。"},{"i":17,"n":"第十七条","txt":"耕地质量监测是通过定点调查、田间试验、样品采集、分析化验、数据分析等工作，对耕地土壤理化性状、养分状况等质量变化开展的动态监测。"},{"i":18,"n":"第十八条","txt":"以农业部耕地质量监测机构和地方耕地质量监测机构为主体，以相关科研教学单位的耕地质量监测站（点）为补充，构建覆盖面广、代表性强、功能完备的国家耕地质量监测网络。"},{"i":19,"n":"第十九条","txt":"农业部根据全国主要耕地土壤亚类、行政区划和农业生产布局建设耕地质量区域监测站。 耕地质量区域监测站负责土壤样品的集中检测，并做好数据审核和信息传输工作。"},{"i":20,"n":"第二十条","txt":"农业部耕地质量监测机构根据耕地土壤类型、种植制度和质量水平在全国布设国家耕地质量监测点。地方耕地质量监测机构根据需要布设本行政区域耕地质量监测点。 耕地质量监测点主要在粮食生产功能区、重要农产品生产保护区、耕地土壤污染区等区域布设，统一标识，建档立案。根据实际需要，可增加土壤墒情、肥料效应和产地环境等监测内容。"},{"i":21,"n":"第二十一条","txt":"农业部耕地质量监测机构负责耕地质量区域监测站、国家耕地质量监测点的监管，收集、汇总、分析耕地质量监测数据，跟踪国内外耕地质量监测技术发展动态。 地方耕地质量监测机构负责本行政区域内耕地质量区域监测站、耕地质量监测点的具体管理，收集、汇总、分析耕地质量监测数据，协助农业部耕地质量监测机构开展耕地质量监测。"},{"i":22,"n":"第二十二条","txt":"县级以上地方人民政府农业主管部门负责本行政区域内耕地质量监测点的设施保护工作。任何单位和个人不得损坏或擅自变动耕地质量监测点的设施及标志。 耕地质量监测点未经许可被占用或损坏的，应当根据有关规定对相关单位或个人实施处罚。"},{"i":23,"n":"第二十三条","txt":"耕地质量监测点确需变更的，应当经设立监测点的农业主管部门审核批准，相关费用由申请变更单位或个人承担。 耕地质量监测机构应当及时补充耕地质量监测点，并补齐基本信息。"},{"i":24,"n":"第二十四条","txt":"耕地质量评价包括耕地质量等级评价、耕地质量监测评价、特定区域耕地质量评价、耕地质量特定指标评价、新增耕地质量评价和耕地质量应急调查评价。"},{"i":25,"n":"第二十五条","txt":"各级耕地质量监测机构应当运用耕地质量调查和监测数据，对本行政区域内耕地质量等级情况进行评价。 农业部每5年发布一次全国耕地质量等级信息。 省级人民政府农业主管部门每5年发布一次本行政区域耕地质量等级信息，并报农业部备案。"},{"i":26,"n":"第二十六条","txt":"各级耕地质量监测机构应当运用监测数据，对本行政区域内耕地质量主要性状变化情况进行评价。 年度耕地质量监测报告由农业部和省级人民政府农业主管部门发布。"},{"i":27,"n":"第二十七条","txt":"各级耕地质量监测机构应当运用调查资料，根据需要对特定区域的耕地质量及其相关情况进行评价。"},{"i":28,"n":"第二十八条","txt":"各级耕地质量监测机构应当运用调查资料，对耕地质量特定指标现状及变化趋势进行评价。"},{"i":29,"n":"第二十九条","txt":"县级以上地方人民政府农业主管部门应当对新增耕地、占补平衡补充耕地开展耕地质量评价，并出具评价意见。"},{"i":30,"n":"第三十条","txt":"各级耕地质量监测机构应当根据应急调查结果，配合相关部门对耕地污染或破坏的程度进行评价，提出修复治理的措施建议。"},{"i":31,"n":"第三十一条","txt":"本办法自2016年8月1日起施行。"}],"lianheshougejikuaquzuoyeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强联合收割机跨区作业管理，规范跨区作业市场秩序，维护参与跨区作业各方的合法权益，保证农作物适时收获，促进农民增收和农业现代化建设，根据《中华人民共和国农业法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称联合收割机跨区作业（以下简称跨区作业），是指驾驶操作各类联合收割机跨越县级以上行政区域（邻县除外）进行小麦、水稻、玉米等农作物收获作业的活动。 本办法所称跨区作业中介服务组织，是指组织联合收割机外出作业或者引进联合收割机作业的单位。"},{"i":3,"n":"第三条","txt":"从事跨区作业的联合收割机驾驶员、辅助作业人员以及与跨区作业活动有关的单位和个人，应当遵守本办法。"},{"i":4,"n":"第四条","txt":"县级以上农机管理部门负责本辖区内跨区作业的组织、协调和监督管理。"},{"i":5,"n":"第五条","txt":"各级农机管理部门要遵循公正、公开、规范、方便的原则，建立统一开放、竞争有序的跨区作业市场。"},{"i":6,"n":"第六条","txt":"各级农机管理部门应当在本级人民政府统一领导下，会同公安、交通、物价、工商等有关部门，依法采取有效措施，保障跨区作业顺利进行。"},{"i":7,"n":"第七条","txt":"鼓励和扶持农机推广站、乡镇农机站、农机作业服务公司、农机合作社、农机大户等组建跨区作业中介服务组织，开展跨区作业中介服务活动。 跨区作业中介服务组织应当向县级以上农机管理部门备案，具体办法由各省、自治区、直辖市农机管理部门制定。"},{"i":8,"n":"第八条","txt":"跨区作业中介服务组织根据市场的需求，可以组建若干跨区作业队，组织联合收割机和驾驶员从事跨区作业。 跨区作业中介服务组织负责统一联系作业任务，保证联合收割机安全转移，及时协调解决作业纠纷，协助做好联合收割机的维修和油料供应等服务。 参加跨区作业队的联合收割机及驾驶员应服从跨区作业中介服务组织的管理和调度。"},{"i":9,"n":"第九条","txt":"跨区作业中介服务组织应当与联合收割机驾驶员签订中介服务合同，明确双方的权利和义务。 跨区作业中介服务组织应当配备相应的交通、通讯等服务设备和技术人员，为参加跨区作业的联合收割机及驾驶员提供优质服务，并遵守有关法律、法规和规章的规定。 跨区作业中介服务组织收取的服务费，按照当地省级价格主管部门的规定执行。尚未制定服务费标准的，由跨区作业中介服务组织和联合收割机驾驶员按公平、自愿的原则商定。严禁只收费不服务或多收费少服务。"},{"i":10,"n":"第十条","txt":"跨区作业的供需双方应当签订跨区作业合同，合理确定引进或外出联合收割机的数量和作业任务。跨区作业合同签订后，应当分别报当地农机管理部门备案。 跨区作业合同一般包括以下内容：联合收割机数量和型号、作业地点、作业面积、作业价格、作业时间、双方权利和义务以及违约责任等。"},{"i":11,"n":"第十一条","txt":"从事跨区作业的联合收割机，机主可向当地县级以上农机管理部门申领《联合收割机跨区收获作业证》(以下简称《作业证》)。对符合条件的，农机管理部门免费发放《作业证》，并逐级向农业部登记备案。"},{"i":12,"n":"第十二条","txt":"申领《作业证》的联合收割机应当具备以下条件： （一）具有农机监理机构核发的有效号牌和行驶证； （二）参加跨区作业队； （三）省级农机管理部门规定的其他条件。 不得对没有参加跨区作业队的联合收割机发放《作业证》，不得跨行政区域发放《作业证》。"},{"i":13,"n":"第十三条","txt":"《作业证》由农业部统一制作，全国范围内使用，当年有效。严禁涂改、转借、伪造和倒卖《作业证》。"},{"i":14,"n":"第十四条","txt":"严禁没有明确作业地点的联合收割机盲目流动，扰乱跨区作业秩序。"},{"i":15,"n":"第十五条","txt":"联合收割机驾驶员应熟练掌握联合收割机操作技能，熟悉基本农艺要求和作业质量标准，持有农机监理机构核发的有效驾驶证件。"},{"i":16,"n":"第十六条","txt":"联合收割机驾驶员必须按照国家及地方有关农机作业质量标准或当事人双方约定的标准进行作业。当事人双方对作业质量存在异议时，可申请作业地的县级以上农机管理部门协调解决。"},{"i":17,"n":"第十七条","txt":"联合收割机及驾驶员、辅助作业人员应严格按照《联合收割机及驾驶员安全监理规定》的要求进行作业，防止农机事故发生，做到安全生产。跨区作业期间发生农机事故的，应当及时向当地农机管理部门报告，并接受调查和处理。"},{"i":18,"n":"第十八条","txt":"任何单位和个人不得非法上路拦截过境的联合收割机，诱骗、强迫驾驶员进行收割作业。"},{"i":19,"n":"第十九条","txt":"跨区作业队在公路上长距离转移时，要统一编队，合理安排路线，注意交通安全，遵守道路交通管理法规，服从交警指挥，自觉维护交通秩序。"},{"i":20,"n":"第二十条","txt":"各级农机管理部门应当建立安全生产检查制度，加强安全生产宣传教育，纠正和处理违章作业，维护正常的跨区作业秩序。"},{"i":21,"n":"第二十一条","txt":"县级农机管理部门应根据农时季节在本县范围内设立跨区作业接待服务站，公布联系方式和工作规范，掌握进入本辖区联合收割机的数量和作业任务，做好有关接待和服务工作，保障外来跨区作业队的安全和合法权益。"},{"i":22,"n":"第二十二条","txt":"各级农机管理部门负责组织协调有关单位做好联合收割机的维修和零配件、油料的供应工作，严禁假冒伪劣的农机零配件和油料进入市场。"},{"i":23,"n":"第二十三条","txt":"各级农机管理部门应当建立跨区作业信息服务网络，建立跨区作业信息搜集、整理和发布制度，及时向农民、驾驶员和跨区作业中介服务组织等提供真实、有效的信息。"},{"i":24,"n":"第二十四条","txt":"县级农机管理部门负责对本辖区内的跨区作业信息进行调查和统计，逐级报农业部。 跨区作业信息包括农作物种植面积、收获时间、计划外出（引进）联合收割机数量、作业参考价格、农作物收获进度、农机管理部门的服务电话等内容。"},{"i":25,"n":"第二十五条","txt":"全国跨区作业信息由农业部在中国农业机械化信息网和有关新闻媒体上发布。地方跨区作业信息由当地农机管理部门负责发布。"},{"i":26,"n":"第二十六条","txt":"各级农机管理部门应当设立跨区作业服务热线电话，确定专人负责，接受农民、驾驶员的信息咨询和投诉。"},{"i":27,"n":"第二十七条","txt":"各级农机管理部门对在跨区作业的组织、管理和服务工作中做出显著贡献的有关单位和个人，给予表彰和奖励。"},{"i":28,"n":"第二十八条","txt":"跨区作业中介服务组织不配备相应的服务设施和技术人员，没有兑现服务承诺，只收费不服务或者多收费少服务的，由县级以上农机管理部门给予警告，责令退还服务费，可并处500元以上1000元以下的罚款；违反有关收费标准的，由县级以上农机管理部门配合价格主管部门依法查处。"},{"i":29,"n":"第二十九条","txt":"违规发放《作业证》的，由上级农机管理部门责令停止违法行为，给予通报批评；情节严重的，对直接负责的主管人员和其他直接责任人员，可以依法给予行政处分。"},{"i":30,"n":"第三十条","txt":"持假冒《作业证》或扰乱跨区作业秩序的，由县级以上农机管理部门责令停止违法行为，纳入当地农机管理部门统一管理，可并处50元以上100元以下的罚款；情节严重的，可并处100元以上200元以下的罚款。"},{"i":31,"n":"第三十一条","txt":"非法上路拦截过境联合收割机及驾驶员的，由事件发生地的农机管理部门采用说服教育的方式予以制止。砸抢机车、拦劫敲诈驾驶员的，移送公安机关依法惩处。"},{"i":32,"n":"第三十二条","txt":"各省、自治区、直辖市农机管理部门可以结合本地实际，制定本办法的实施细则。 组织其它农业机械从事跨区机耕、机播（机插）、机械化秸秆还田等作业的，参照本办法执行。"},{"i":33,"n":"第三十三条","txt":"本办法由农业部负责解释。"},{"i":34,"n":"第三十四条","txt":"本办法自2003年9月1日起施行。农业部2000年4月3日发布的《联合收割机跨区作业管理暂行办法》同时废止。"}],"feiliaodengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强肥料管理，保护生态环境，保障人畜安全，促进农业生产，根据《中华人民共和国农业法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内生产、经营、使用和宣传肥料产品，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称肥料，是指用于提供、保持或改善植物营养和土壤物理、化学性能以及生物活性，能提高农产品产量，或改善农产品品质，或增强植物抗逆性的有机、无机、微生物及其混合物料。"},{"i":4,"n":"第四条","txt":"国家鼓励研制、生产和使用安全、高效、经济的肥料产品。"},{"i":5,"n":"第五条","txt":"实行肥料产品登记管理制度，未经登记的肥料产品不得进口、生产、销售和使用，不得进行广告宣传。 肥料生产者生产大量元素水溶肥料、中量元素水溶肥料、微量元素水溶肥料、农用氯化钾镁、农用硫酸钾镁的，应当向农业农村部备案。"},{"i":6,"n":"第六条","txt":"农业农村部负责全国肥料登记、备案和监督管理工作。 省、自治区、直辖市人民政府农业农村主管部门协助农业农村部做好本行政区域内的肥料登记、备案工作。 县级以上地方人民政府农业农村主管部门负责本行政区域内的肥料监督管理工作。"},{"i":7,"n":"第七条","txt":"凡经工商注册，具有独立法人资格的肥料生产者均可提出肥料登记申请。"},{"i":8,"n":"第八条","txt":"农业农村部制定并发布《肥料登记资料要求》。 肥料生产者申请肥料登记，应按照《肥料登记资料要求》提供产品化学、肥效、安全性、标签等方面资料和有代表性的肥料样品。"},{"i":9,"n":"第九条","txt":"农业农村部负责办理肥料登记受理手续，并审查登记申请资料是否齐全。 境内生产者申请肥料登记，其申请登记资料应经其所在地省级农业农村主管部门初审后，向农业农村部提出申请。"},{"i":10,"n":"第十条","txt":"生产者申请肥料登记前，须在中国境内进行规范的田间试验。 对有国家标准或行业标准，或肥料登记评审委员会建议经农业农村部认定的产品类型，可相应减免田间试验。"},{"i":11,"n":"第十一条","txt":"生产者可按要求自行开展肥料田间试验，也可委托有关单位开展；生产者和试验单位应当对所出具试验报告的真实性承担法律责任。"},{"i":12,"n":"第十二条","txt":"有下列情形的肥料产品，登记申请不予受理： （一）没有生产国使用证明（登记注册）的国外产品； （二）不符合国家产业政策的产品； （三）知识产权有争议的产品； （四）不符合国家有关安全、卫生、环保等国家或行业标准要求的产品。"},{"i":13,"n":"第十三条","txt":"对经农田长期使用，有国家或行业标准的下列产品免予登记： 硫酸铵，尿素，硝酸铵，氰氨化钙，磷酸铵（磷酸一铵、二铵），硝酸磷肥，过磷酸钙，氯化钾，硫酸钾，硝酸钾，氯化铵， 碳酸氢铵，钙镁磷肥，磷酸二氢钾，单一微量元素肥，高浓度复合肥。"},{"i":14,"n":"第十四条","txt":"农业农村部负责全国肥料的登记审批、登记证发放和公告工作。"},{"i":15,"n":"第十五条","txt":"农业农村部聘请技术专家和管理专家组织成立肥料登记评审委员会，负责对申请登记肥料产品的产品化学、肥效和安全性等资料进行综合评审。"},{"i":16,"n":"第十六条","txt":"农业农村部根据肥料登记评审委员会的综合评审意见，在评审结束后20日内作出是否颁发肥料登记证的决定。 肥料登记证使用《中华人民共和国农业农村部肥料审批专用章》。"},{"i":17,"n":"第十七条","txt":"农业农村部对符合下列条件的产品直接审批、发放肥料登记证： （一）有国家或行业标准，经检验质量合格的产品。 （二）经肥料登记评审委员会建议并由农业农村部认定的产品类型，申请登记资料齐全，经检验质量合格的产品。"},{"i":18,"n":"第十八条","txt":"农业农村部根据具体情况决定召开肥料登记评审委员会全体会议。"},{"i":19,"n":"第十九条","txt":"肥料商品名称的命名应规范，不得有误导作用。"},{"i":20,"n":"第二十条","txt":"肥料登记证有效期为五年。肥料登记证有效期满，需要继续生产、销售该产品的，应当在有效期满六个月前提出续展登记申请，符合条件的经农业农村部批准续展登记。续展有效期为五年。 登记证有效期满没有提出续展登记申请的，视为自动撤销登记。登记证有效期满后提出续展登记申请的，应重新办理登记。"},{"i":21,"n":"第二十一条","txt":"经登记的肥料产品，在登记有效期内改变使用范围、商品名称、企业名称的，应申请变更登记；改变成分、剂型的，应重新申请登记。"},{"i":22,"n":"第二十二条","txt":"肥料产品包装应有标签、说明书和产品质量检验合格证。标签和使用说明书应当使用中文，并符合下列要求： （一）标明产品名称、生产企业名称和地址； （二）标明肥料登记证号、产品标准号、有效成分 名称和含量、净重、生产日期及质量保证期； （三）标明产品适用作物、适用区域、使用方法和注意事项； （四）产品名称和推荐适用作物、区域应与登记批准的一致； 禁止擅自修改经过登记批准的标签内容。"},{"i":23,"n":"第二十三条","txt":"取得登记证的肥料产品，在登记有效期内证实对人、畜、作物有害，经肥料登记评审委员会审议，由农业农村部宣布限制使用或禁止使用。"},{"i":24,"n":"第二十四条","txt":"农业农村主管部门应当按照规定对辖区内的肥料生产、经营和使用单位的肥料进行定期或不定期监督、检查，必要时按照规定抽取样品和索取有关资料，有关单位不得拒绝和隐瞒。对质量不合格的产品，要限期改进。对质量连续不合格的产品，肥料登记证有效期满后不予续展。"},{"i":25,"n":"第二十五条","txt":"肥料登记受理和审批单位及有关人员应为生产者提供的资料和样品保守技术秘密。"},{"i":26,"n":"第二十六条","txt":"有下列情形之一的，由县级以上农业农村主管部门给予警告，并处违法所得3倍以下罚款，但最高不得超过30000元； 没有违法所得的，处10000元以下罚款： （一）生产、销售未取得登记证的肥料产品； （二）假冒、伪造肥料登记证、登记证号的； （三）生产、销售的肥料产品有效成分或含量与登记批准的内容不符的。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一的，由县级以上农业农村主管部门给予警告，并处违法所得3倍以下罚款，但最高不得超过 20000元； 没有违法所得的，处10000元以下罚款： （一）转让肥料登记证或登记证号的； （二）登记证有效期满未经批准续展登记而继续生产该肥料产品的； （三）生产、销售包装上未附标签、标签残缺不清或者擅自修改标签内容的。"},{"i":28,"n":"第二十八条","txt":"肥料登记管理工作人员滥用职权，玩忽职守、徇私舞弊、索贿受贿，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予政务处分。"},{"i":29,"n":"第二十九条","txt":"生产者进行田间试验，应按规定提供有代表性的试验样品。试验样品须经法定质量检测机构检测确认样品有效成分及其含量与标明值相符，方可进行试验。"},{"i":30,"n":"第三十条","txt":"省、自治区、直辖市人民政府农业农村主管部门负责本行政区域内的精制有机肥、床土调酸剂的登记审批、登记证发放和公告工作，负责本行政区域内的复混肥、掺混肥备案工作。省、自治区、直辖市人民政府农业农村主管部门不得越权审批登记和备案管理。 省、自治区、直辖市人民政府农业农村主管部门参照本办法制定有关复混肥、掺混肥、精制有机肥、床土调酸剂的具体登记和备案管理办法，并报农业农村部备案。 省、自治区、直辖市人民政府农业农村主管部门可委托所属的土肥机构承担本行政区域内的具体肥料登记工作。"},{"i":31,"n":"第三十一条","txt":"下列产品适用本办法： （一）在生产、积造有机肥料过程中，添加的用于分解、熟化有机物的生物和化学制剂； （二）来源于天然物质，经物理或生物发酵过程加工提炼的，具有特定效应的有机或有机无机混合制品，这种效应不仅包括土壤、环境及植物营养元素的供应，还包括对植物生长的促进作用。"},{"i":32,"n":"第三十二条","txt":"下列产品不适用本办法： （一）肥料和农药的混合物； （二）农民自制自用的有机肥料； （三）植物生长调节剂。"},{"i":33,"n":"第三十三条","txt":"本办法下列用语定义为： （一）配方肥是指利用测土配方技术，根据不同作物的营养需要、土壤养分含量及供肥特点，以各种单质化肥为原料，有针对性地添加适量中、微量元素或特定有机肥料，采用造粒工艺加工而成的，具有很强的针对性和地域性的专用肥料。 （二）叶面肥是指施于植物叶片并能被其吸收利用的肥料。 （三）床土调酸剂是指在农作物育苗期，用于调节育苗床土酸度（或pH值）的制剂。 （四）微生物肥料是指应用于农业生产中，能够获得特定肥料效应的含有特定微生物活体的制品，这种效应不仅包括了土壤、环境及植物营养元素的供应，还包括了其所产生的代谢产物对植物的有益作用。 （五）有机肥料是指来源于植物和／或动物，经发酵、腐熟后，施于土壤以提供植物养分为其主要功效的含碳物料。 （六）精制有机肥是指经工厂化生产的，不含特定肥料效应微生物的，商品化的有机肥料。 （七）复混肥是指氮、磷、钾三种养分中，至少有两种养分标明量的"},{"i":34,"n":"第三十四条","txt":"本办法所称“违法所得”是指违法生产、经营肥料的销售收入。"},{"i":35,"n":"第三十五条","txt":"本办法由农业农村部负责解释。"},{"i":36,"n":"第三十六条","txt":"本办法自发布之日起施行。农业部1989年发布、1997 年修订的《中华人民共和国农业部关于肥料、土壤调理剂及植物生长调节剂检验登记的暂行规定》同时废止。"}],"caozhongguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范和加强草种管理，提高草种质量，维护草品种选育者和草种生产者、经营者、使用者的合法权益，促进草业的健康发展，根据《中华人民共和国种子法》和《中华人民共和国草原法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事草品种选育和草种生产、经营、使用、管理等活动，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称草种，是指用于动物饲养、生态建设、绿化美化等用途的草本植物及饲用灌木的籽粒、果实、根、茎、苗、叶、芽等种植材料或者繁殖材料。"},{"i":4,"n":"第四条","txt":"农业部主管全国草种管理工作。 县级以上地方人民政府草原行政主管部门主管本行政区域内的草种管理工作。"},{"i":5,"n":"第五条","txt":"草原行政主管部门及其工作人员不得参与和从事草种生产、经营活动；草种生产经营机构不得参与和从事草种行政管理工作。草种的行政主管部门与生产经营机构在人员和财务上必须分开。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府草原行政主管部门应当加强草种质资源保护和良种选育、生产、更新、推广工作，鼓励选育、生产、经营相结合，奖励在草种质资源保护和良种选育、推广等工作中成绩显著的单位和个人。"},{"i":7,"n":"第七条","txt":"国家保护草种质资源，任何单位和个人不得侵占和破坏。"},{"i":8,"n":"第八条","txt":"农业部根据需要编制国家重点保护草种质资源名录。"},{"i":9,"n":"第九条","txt":"农业部组织有关单位收集、整理、鉴定、登记、保存、交流和利用草种质资源，建立草种质资源库，并定期公布可供利用的草种质资源名录。"},{"i":10,"n":"第十条","txt":"农业部和省级人民政府草原行政主管部门根据需要建立国家和地方草种质资源保护区或者保护地。"},{"i":11,"n":"第十一条","txt":"禁止采集、采挖国家重点保护的天然草种质资源。确因科研等特殊情况需要采集、采挖的，应当经省级人民政府草原行政主管部门审核，报农业部审批。"},{"i":12,"n":"第十二条","txt":"从境外引进的草种质资源，应当依法进行检疫。 对首次引进的草种，应当进行隔离试种，并进行风险评估，经确认安全后方可使用。"},{"i":13,"n":"第十三条","txt":"国家对草种质资源享有主权，任何单位和个人向境外提供草种质资源的，应当经所在地省、自治区、直辖市人民政府草原行政主管部门审核，报农业部审批。"},{"i":14,"n":"第十四条","txt":"国家鼓励单位和个人从事草品种选育，鼓励科研单位与企业相结合选育草品种，鼓励企业投资选育草品种。"},{"i":15,"n":"第十五条","txt":"国家实行新草品种审定制度。新草品种未经审定通过的，不得发布广告，不得经营、推广。"},{"i":16,"n":"第十六条","txt":"农业部设立全国草品种审定委员会，负责新草品种审定工作。 全国草品种审定委员会由相关的科研、教学、技术推广、行政管理等方面具有高级专业技术职称或处级以上职务的专业人员组成。 全国草品种审定委员会主任、副主任、委员由农业部聘任。"},{"i":17,"n":"第十七条","txt":"审定通过的新草品种，由全国草品种审定委员会颁发证书，农业部公告。 审定公告应当包括审定通过的品种名称、选育者、适应地区等内容。 审定未通过的，由全国草品种审定委员会书面通知申请人并说明理由。"},{"i":18,"n":"第十八条","txt":"在中国没有经常居所或者营业场所的外国公民、外国企业或外国其他组织在中国申请新草品种审定的，应当委托具有法人资格的中国草种科研、生产、经营机构代理。"},{"i":19,"n":"第十九条","txt":"主要草种的商品生产实行许可制度。 草种生产许可证由草种生产单位或个人所在地省级人民政府草原行政主管部门核发。"},{"i":20,"n":"第二十条","txt":"申请领取草种生产许可证的单位和个人应当具备以下条件： （一）具有繁殖草种的隔离和培育条件； （二）具有无国家规定检疫对象的草种生产地点； （三）具有与草种生产相适应的资金和生产、检验设施； （四）具有相应的专业生产和检验技术人员； （五）法律、法规规定的其他条件。"},{"i":21,"n":"第二十一条","txt":"申请领取草种生产许可证的，应当提交以下材料： （一）草种生产许可证申请表； （二）专业生产和检验技术人员资格证明； （三）营业执照复印件； （四）检验设施和仪器设备清单、照片和产权或合法使用权证明； （五）草种晒场情况介绍或草种烘干设备照片及产权或合法使用权证明； （六）草种仓储设施照片及产权或合法使用权证明； （七）草种生产地点的检疫证明和情况介绍； （八）草种生产质量保证制度； （九）品种特性介绍。 品种为授权品种的，还应当提供品种权人同意的书面证明或品种转让合同；生产草种是转基因品种的，还应当提供农业转基因生物安全证书。"},{"i":22,"n":"第二十二条","txt":"审批机关应当自受理申请之日起20日内完成审查，作出是否核发草种生产许可证的决定。不予批准的，书面通知申请人并说明理由。 必要时，审批机关可以对生产地点、晾晒烘干设施、仓储设施、检验设施和仪器设备进行实地考察。"},{"i":23,"n":"第二十三条","txt":"草种生产许可证式样由农业部统一规定。 草种生产许可证有效期为3年，期满后需继续生产的，被许可人应当在期满3个月前持原证按原申请程序重新申领。 在草种生产许可证有效期内，许可证注明项目变更的，被许可人应当向原审批机关办理变更手续，并提供相应证明材料。"},{"i":24,"n":"第二十四条","txt":"禁止任何单位和个人无证从事主要草种的商品生产。 禁止伪造、变造、买卖、租借草种生产许可证。"},{"i":25,"n":"第二十五条","txt":"草种生产单位和个人应当按照《草种生产技术规程》生产草种，并建立草种生产档案，载明生产地点、生产地块环境、前茬作物、亲本种子来源和质量、技术负责人、田间检验记录、产地气象记录、种子流向等内容。生产档案应当保存至草种生产后2年。"},{"i":26,"n":"第二十六条","txt":"草种经营实行许可制度。草种经营单位和个人应当先取得草种经营许可证后，凭草种经营许可证向工商行政管理机关申请办理或者变更营业执照，但依照《种子法》规定不需要办理草种经营许可证的除外。 主要草种杂交种子及其亲本种子、常规原种种子的经营许可证，由草种经营单位和个人所在地县级人民政府草原行政主管部门审核，省级人民政府草原行政主管部门核发。 从事草种进出口业务的，草种经营许可证由草种经营单位或个人所在地省级人民政府草原行政主管部门审核，农业部核发。 其他草种经营许可证，由草种经营单位或个人所在地县级人民政府草原行政主管部门核发。"},{"i":27,"n":"第二十七条","txt":"申请领取草种经营许可证的单位和个人，应当具备下列条件： （一）具有与经营草种种类和数量相适应的资金及独立承担民事责任的能力； （二）具有能够正确识别所经营的草种、检验草种质量、掌握草种贮藏和保管技术的人员； （三）具有与经营草种的种类、数量相适应的经营场所及仓储设施； （四）法律、法规规定的其他条件。"},{"i":28,"n":"第二十八条","txt":"申请领取草种经营许可证的，应当提交以下材料： （一）草种经营许可证申请表； （二）经营场所照片、产权或合法使用权证明； （三）草种仓储设施清单、照片及产权或合法使用权的证明。"},{"i":29,"n":"第二十九条","txt":"审批机关应当自受理申请之日起20日内完成审查，作出是否核发草种经营许可证的决定。不予核发的，书面通知申请人并说明理由。 必要时，审批机关可以对营业场所及加工、包装、贮藏保管设施和检验草种质量的仪器设备进行实地考察。"},{"i":30,"n":"第三十条","txt":"草种经营许可证式样由农业部统一规定。 草种经营许可证有效期为5年，期满后需继续经营的，经营者应当在期满3个月前持原证按原申请程序重新申领。 在草种经营许可证有效期内，许可证注明项目变更的，被许可人应当向原审批机关办理变更手续，并提供相应证明材料。"},{"i":31,"n":"第三十一条","txt":"禁止任何单位和个人无证经营草种。 禁止伪造、变造、买卖、租借草种经营许可证。"},{"i":32,"n":"第三十二条","txt":"草种经营者应当对所经营草种的质量负责，并遵守有关法律、法规的规定，向草种使用者提供草种的特性、栽培技术等咨询服务。"},{"i":33,"n":"第三十三条","txt":"销售的草种应当包装。实行分装的，应当注明分装单位、原草种或草品种名、原产地。"},{"i":34,"n":"第三十四条","txt":"销售的草种应当附有标签。标签应当注明草种类别、品种名称、种子批号、产地、生产时间、生产单位名称和质量指标等事项。 标签注明的内容应当与销售的草种相符。 销售进口草种的，应当附有中文标签。"},{"i":35,"n":"第三十五条","txt":"草种经营者应当建立草种经营档案，载明草种来源、加工、贮藏、运输和质量检测各环节的简要说明及责任人、销售去向等内容。 经营档案应当保存至草种销售后2年。"},{"i":36,"n":"第三十六条","txt":"县级以上草原行政主管部门要加强当地草种广告的监督管理。草种广告的内容应当符合有关法律、法规，主要性状描述应当与审定公告一致，不得进行虚假、误导宣传。"},{"i":37,"n":"第三十七条","txt":"农业部负责制定全国草种质量监督抽查规划和本级草种质量监督抽查计划，县级以上地方人民政府草原行政主管部门根据全国规划和当地实际情况制定相应的监督抽查计划。 监督抽查所需费用列入草原行政主管部门的预算，不得向被抽查企业收取费用。 草原行政主管部门已经实施监督抽查的企业，自扦样之日起6个月内，本级或下级草原行政主管部门对该企业的同一作物种子不得重复进行监督抽查。"},{"i":38,"n":"第三十八条","txt":"草原行政主管部门可以委托草种质量检验机构对草种质量进行检验。 承担草种质量检验的机构应当具备相应的检测条件和能力，并经省级人民政府有关主管部门考核合格。"},{"i":39,"n":"第三十九条","txt":"草种质量检验机构的草种检验员应当符合下列条件： （一）具有相关专业大专以上文化水平或具有中级以上技术职称； （二）从事草种检验技术工作3年以上； （三）经省级人民政府草原行政主管部门考核合格。"},{"i":40,"n":"第四十条","txt":"监督抽查的草种应当依据《国家牧草种子检验规程》进行质量检验。《国家牧草种子检验规程》中未规定的，依据《国际种子检验规程》进行质量检验。"},{"i":41,"n":"第四十一条","txt":"《草种质量检验报告》应当标明草种名称、扦样日期、被检草种的数量、种子批号、检验结果等有关内容。 《草种质量检验报告》由持证上岗的草种检验员填写，检验机构负责人签发，加盖检验机构检验专用章。"},{"i":42,"n":"第四十二条","txt":"被抽查人对检验结果有异议的，应当在接到检验结果通知之日起15日内，向下达任务的草原行政主管部门提出书面的复检申请。逾期未申请的，视为认可检验结果。 收到复检申请的草原行政主管部门应当进行审查，需要复检的，应当及时安排。"},{"i":43,"n":"第四十三条","txt":"禁止生产和经营假、劣草种。 下列草种为假草种： （一）以非草种冒充草种或者以此品种草种冒充他品种草种的； （二）草种种类、品种、产地与标签标注的内容不符的。 下列草种为劣草种： （一）质量低于国家规定的种用标准的； （二）质量低于标签标注指标的； （三）因变质不能作草种使用的； （四）杂草种子的比率超过规定的； （五）带有国家规定检疫对象的。"},{"i":44,"n":"第四十四条","txt":"生产、经营的草种应当按照有关植物检疫法律、法规的规定进行检疫，防止植物危险性病、虫、杂草及其他有害生物的传播和蔓延。 禁止任何单位和个人在草种生产基地从事病虫害接种试验。"},{"i":45,"n":"第四十五条","txt":"从事草种进出口业务的单位，除具备草种经营许可证以外，还应当依照国家外贸法律、法规的有关规定取得从事草种进出口贸易的资格。"},{"i":46,"n":"第四十六条","txt":"草种进出口实行审批制度。 申请进出口草种的单位和个人，应当填写《进（出）口草种审批表》，经省级人民政府草原行政主管部门批准后，依法办理进出口手续。 草种进出口审批单有效期为3个月。"},{"i":47,"n":"第四十七条","txt":"进出口草种应当符合下列条件： （一）草种质量达到国家标准； （二）草种名称、数量、原产地等相关证明真实完备； （三）不属于国家禁止进出口的草种。 申请进出口草种的单位和个人应当提供以下材料： （一）《草种经营许可证》、营业执照副本和进出口贸易资格证明； （二）草种名称、数量、原产地证明材料； （三）引进草品种的国外审定证书或品种登记名录；"},{"i":48,"n":"第四十八条","txt":"为境外制种进口草种的，可以不受本办法第四十五条限制，但应当具有对外制种合同。进口的种子只能用于制种，其产品不得在国内销售。"},{"i":49,"n":"第四十九条","txt":"违反本办法规定的，依照《中华人民共和国种子法》和《中华人民共和国草原法》的有关规定予以处罚。"},{"i":50,"n":"第五十条","txt":"转基因草品种的选育、试验、推广、生产、加工、经营和进出口活动的管理，还应当遵守《农业转基因生物安全管理条例》的规定。"},{"i":51,"n":"第五十一条","txt":"采集、采挖、向境外提供以及从境外引进属于列入国家重点保护野生植物名录的草种质资源，除按本办法办理审批手续外，还应按照《中华人民共和国野生植物保护条例》和《农业野生植物保护办法》的规定，办理相关审批手续。"},{"i":52,"n":"第五十二条","txt":"本办法所称主要草种，是指苜蓿、沙打旺、锦鸡儿、红豆草、三叶草、岩黄芪、柱花草、狼尾草、老芒麦、冰草、羊草、羊茅、鸭茅、碱茅、披碱草、胡枝子、小冠花、无芒雀麦、燕麦、小黑麦、黑麦草、苏丹草、草木樨、早熟禾等以及各省、自治区、直辖市人民政府草原行政主管部门分别确定的其他2至3种草种。 本办法所称草种不含饲用玉米、饲用高粱等大田农作物。"},{"i":53,"n":"第五十三条","txt":"本办法自2006年3月1日起施行。1984年10月25日农牧渔业部颁发的《牧草种子暂行管理办法(试行)》同时废止。"}],"canzhongguanlibanfa":[{"i":1,"n":"第一条","txt":"为了保护和合理利用蚕遗传资源，规范蚕种生产经营行为，维护蚕品种选育者和蚕种生产经营者、使用者的合法权益，促进蚕桑业持续健康发展，根据《中华人民共和国畜牧法》，制定本办法。"},{"i":2,"n":"第二条","txt":"从事蚕品种资源保护、新品种选育和推广、蚕种生产经营和管理等活动，适用本办法。 本办法所称蚕种指桑蚕种和柞蚕种，包括原原母种、原原种、原种和一代杂交种；本办法所称蚕种生产包括蚕种繁育、冷藏和浸酸。"},{"i":3,"n":"第三条","txt":"农业农村部负责全国蚕种的管理工作；县级以上地方人民政府农业农村（蚕业）主管部门负责本行政区域内的蚕种管理工作。"},{"i":4,"n":"第四条","txt":"县级以上人民政府农业农村（蚕业）主管部门应当依照《中华人民共和国畜牧法》的规定，安排资金，支持良种繁育，改善生产条件，加强蚕种场建设，促进蚕种生产健康发展。"},{"i":5,"n":"第五条","txt":"蚕种生产、经营者可以依法自愿成立行业协会。行业协会应当为成员提供信息、技术、营销、培训等服务，加强行业自律，维护成员和行业合法权益。"},{"i":6,"n":"第六条","txt":"蚕遗传资源保护以国家为主，鼓励和支持有关单位、个人依法发展蚕遗传资源保护事业。"},{"i":7,"n":"第七条","txt":"农业农村部负责组织蚕遗传资源的调查，发布国家蚕遗传资源状况报告，制定全国蚕遗传资源保护和利用规划，公布国家级蚕遗传资源保护名录。 省级人民政府农业农村（蚕业）主管部门制定和公布省级蚕遗传资源保护名录，并报农业农村部备案。"},{"i":8,"n":"第八条","txt":"省级以上人民政府农业农村（蚕业）主管部门确定的蚕遗传资源保育单位（蚕种质资源库）承担蚕遗传资源保护任务。未经省级以上人民政府农业农村（蚕业）主管部门批准，不得擅自处理受保护的蚕遗传资源。 蚕遗传资源保育单位应当按照省级以上人民政府农业农村（蚕业）主管部门的有关规定，采集新增的蚕遗传材料，有关单位和个人应当提供新增加的蚕遗传材料。 提供新增加的蚕遗传材料，有权获得适当经济补偿。"},{"i":9,"n":"第九条","txt":"禁止除杂交一代蚕品种以外的蚕遗传资源出口。 因交换需要出口蚕遗传资源的，应当向省级人民政府农业农村（蚕业）主管部门提出申请，同时提出国家共享惠益方案。省级人民政府农业农村（蚕业）主管部门应当自受理申请之日起二十个工作日内完成审核，并报农业农村部批准。农业农村部在二十个工作日内做出审批决定，不予批准的，书面通知申请人并说明理由。 引进蚕遗传资源，应当办理检疫手续，并在引进后三十日内向农业农村部备案。 对外合作研究利用蚕遗传资源的，按照国务院规定的畜禽遗传资源对外合作研究利用的审批办法审批。"},{"i":10,"n":"第十条","txt":"国家扶持蚕品种选育和优良品种推广使用，支持企业、院校、科研机构和技术推广单位开展联合育种，建立蚕良种繁育体系，推进蚕种科技进步。"},{"i":11,"n":"第十一条","txt":"新选育的蚕品种在推广应用前应当通过国家级或者省级审定。 未经审定或者审定未通过的蚕品种，不得生产、经营或者发布广告推广。 农业农村部和蚕茧产区省级人民政府农业农村（蚕业）主管部门分别设立由专业人员组成的蚕品种审定委员会，负责蚕遗传资源的鉴定、评估和蚕品种的审定。"},{"i":12,"n":"第十二条","txt":"通过国家级审定的蚕品种，由农业农村部公告，可以在全国适宜的生态区域推广。通过省级审定的蚕品种，由省级人民政府农业农村（蚕业）主管部门公告，可以在本行政区域内推广。相邻省、自治区、直辖市属于同一适宜生态区的地域，经所在地省级人民政府农业农村（蚕业）主管部门同意后可以引进饲养。 审定未通过的蚕品种，申请人有异议的，可以向原蚕品种审定委员会或者上一级蚕品种审定委员会申请复审。"},{"i":13,"n":"第十三条","txt":"利用转基因技术选育的蚕品种和引进的转基因蚕遗传资源，还应当执行国家有关农业转基因生物安全管理的规定。"},{"i":14,"n":"第十四条","txt":"新选育或者引进的蚕品种，需要在申请审定前进行小规模（每季1000张或者1000把蚕种以内）中试的，应当经试验所在地省级人民政府农业农村（蚕业）主管部门同意。"},{"i":15,"n":"第十五条","txt":"蚕种生产分为三级繁育（原原种、原种、一代杂交种）和四级制种（原原母种、原原种、原种、一代杂交种）。 从事蚕种生产、经营活动的，应当取得蚕种生产、经营许可证。"},{"i":16,"n":"第十六条","txt":"申请蚕种生产许可证，应当具备下列条件： （一）符合国家与区域蚕业发展规划要求； （二）有与蚕种生产能力相适应的桑园（柞林）或者稳定安全的原蚕饲育区； （三）有与蚕种生产相适应的资金和检验等设施； （四）有与蚕种生产相适应的专业技术人员； （五）有能够有效控制蚕微粒子病的质量保证措施； （六）一代杂交种年生产能力5万张以上。 申请蚕种冷藏、浸酸生产许可证，应当具备与冷藏能力相适应的冷藏库房、浸酸设备仪器、场地和相关专业技术人员。"},{"i":17,"n":"第十七条","txt":"申请蚕种经营许可证，应当具备下列条件： （一）有与蚕种经营规模相适应的场所、资金和保藏、检验等设施； （二）有与蚕种经营相适应的专业技术人员； （三）经营的蚕种应当是通过审定的品种。"},{"i":18,"n":"第十八条","txt":"申请蚕种生产、经营许可证应当向所在地县级以上地方人民政府农业农村（蚕业）主管部门提出。受理申请的行政主管部门应当自收到申请之日起二十个工作日内完成审核，并报省级人民政府农业农村（蚕业）主管部门审批。 省级人民政府农业农村（蚕业）主管部门应当自收到申请之日起二十个工作日内做出审批决定。不予批准的，应当书面通知申请者，并说明理由。 蚕种生产、经营许可证证书样式由农业农村部规定。 蚕种生产、经营许可证工本费按照国务院财政、价格部门的规定执行。"},{"i":19,"n":"第十九条","txt":"蚕种生产、经营许可证有效期为三年。期满仍需继续生产、经营的，应当在有效期满前30日按原申请程序办理审批手续。 在许可证有效期内变更许可事项的，应当及时办理变更手续。 禁止伪造、变造、转让、租借蚕种生产、经营许可证。"},{"i":20,"n":"第二十条","txt":"发布蚕种广告的，应当提供蚕种生产、经营许可证复印件。广告内容应当符合有关法律法规的规定，注明蚕品种的审定名称，文字介绍符合该品种的实际性状。"},{"i":21,"n":"第二十一条","txt":"销售的蚕种应当经检疫、检验合格，并附具蚕种检疫合格证明、质量合格证和标签。 蚕种标签应当注明企业（种场）名称、企业（种场）地址、品种名称、期别、批次、执行标准、卵量等内容。"},{"i":22,"n":"第二十二条","txt":"蚕种生产、经营者应当建立蚕种生产、经营档案。 蚕种生产档案应当载明品种名称、亲本来源、繁制地点、生产数量、检疫检验结果、技术与质检负责人、销售去向等内容；蚕种经营档案应当载明蚕种来源、保藏地点、质量状况、销售去向等内容。 蚕种生产、经营档案应当保存二年以上。"},{"i":23,"n":"第二十三条","txt":"禁止销售下列蚕种： （一）以不合格蚕种冒充合格的蚕种； （二）冒充其他企业（种场）名称或者品种的蚕种； （三）未附具本办法第二十一条规定的蚕种检疫证明、蚕种质量合格证和标签的蚕种。"},{"i":24,"n":"第二十四条","txt":"禁止原原母种、原原种、原种出口。出口经过审定的一代杂交种，应当由省级人民政府农业农村（蚕业）主管部门批准，并报农业农村部备案。 《蚕一代杂交种出口审批表》样式，由农业农村部规定。"},{"i":25,"n":"第二十五条","txt":"蚕种检疫由省级以上人民政府农业农村（蚕业）主管部门确定的蚕种检验机构承担。检疫按照国家有关规定收取费用。 检疫不合格的蚕种，由县级以上地方人民政府农业农村（蚕业）主管部门监督销毁。"},{"i":26,"n":"第二十六条","txt":"省级以上人民政府农业农村（蚕业）主管部门应当制定蚕种质量监督抽查计划并组织实施。 农业农村部监督抽查的品种，省级农业农村（蚕业）主管部门不得重复抽查。监督抽查不得向被抽查者收取任何费用。 承担蚕种质量检验的机构应当符合国家规定的条件，并经有关部门考核合格。"},{"i":27,"n":"第二十七条","txt":"发生下列情形并严重影响蚕种供应的，蚕种生产者或者经营者应当及时向所在地人民政府农业农村（蚕业）主管部门报告，并采取相应措施： （一）微粒子病等蚕病虫害爆发； （二）遭受严重自然灾害； （三）生产基地受到较大面积污染和农药中毒； （四）其他可能严重影响蚕种供应的情形。"},{"i":28,"n":"第二十八条","txt":"由于不可抗力原因，需要使用低于国家或行业标准蚕种的，应当由所在地县级以上地方人民政府农业农村（蚕业）主管部门报经同级人民政府批准后方可使用。经营者应当向使用者说明并加强技术服务。"},{"i":29,"n":"第二十九条","txt":"违反本办法第八条规定，擅自处理受保护的蚕遗传资源，造成蚕遗传资源损失的，由省级以上人民政府农业农村（蚕业）主管部门处五万元以上五十万元以下罚款。"},{"i":30,"n":"第三十条","txt":"未经审批开展对外合作研究利用蚕遗传资源的，由省级以上人民政府农业农村（蚕业）主管部门责令停止违法行为，没收蚕遗传资源和违法所得，并处一万元以上五万元以下罚款。 未经审批向境外提供蚕遗传资源的，依照《中华人民共和国海关法》的有关规定追究法律责任。"},{"i":31,"n":"第三十一条","txt":"违反本办法第十一条第二款的规定，销售、推广未经审定蚕种的，由县级以上人民政府农业农村（蚕业）主管部门责令停止违法行为，没收蚕种和违法所得；违法所得在五万元以上的，并处违法所得一倍以上三倍以下罚款；没有违法所得或者违法所得不足五万元的，并处五千元以上五万元以下罚款。 未按照本办法第二十条规定发布蚕种广告宣传的，依照《中华人民共和国广告法》的有关规定追究法律责任。"},{"i":32,"n":"第三十二条","txt":"违反本办法有关规定，无蚕种生产、经营许可证或者违反蚕种生产、经营许可证的规定生产经营蚕种，或者转让、租借蚕种生产、经营许可证的，由县级以上人民政府农业农村（蚕业）主管部门责令停止违法行为，没收违法所得；违法所得在三万元以上的，并处违法所得一倍以上三倍以下罚款；没有违法所得或者违法所得不足三万元的，并处三千元以上三万元以下罚款。违反蚕种生产、经营许可证的规定生产经营蚕种或者转让、租借蚕种生产、经营许可证，情节严重的，并处吊销蚕种生产、经营许可证。"},{"i":33,"n":"第三十三条","txt":"销售的蚕种未附具蚕种检疫证明、质量合格证的，由县级以上地方人民政府农业农村（蚕业）主管部门责令改正，没收违法所得，可以处二千元以下罚款。"},{"i":34,"n":"第三十四条","txt":"违反本办法第二十三条第一项至第二项规定的，由县级以上地方人民政府农业农村（蚕业）主管部门责令停止销售，没收违法销售的蚕种和违法所得；违法所得在五万元以上的，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足五万元的，并处五千元以上五万元以下罚款；情节严重的，并处吊销蚕种生产、经营许可证。"},{"i":35,"n":"第三十五条","txt":"农业农村（蚕业）主管部门的工作人员利用职务上的便利，收受他人财物或者谋取其他利益，对不符合法定条件的单位、个人核发许可证或者有关批准文件，不履行监督职责，或者发现违法行为不予查处的，依法给予处分。 蚕种质量检验机构及其工作人员，不按要求检疫检验或者出具虚假检疫证明、检验报告的，依法给予处分。"},{"i":36,"n":"第三十六条","txt":"蚕种生产、经营许可证被吊销的，农业农村（蚕业）主管部门自吊销许可证之日起十日内通知工商行政管理部门。被吊销许可证的蚕种生产、经营者应当依法办理工商变更登记或者注销手续。"},{"i":37,"n":"第三十七条","txt":"本办法下列用语的含义： （一）原原种是指供生产原种用的蚕种，原种是指供生产一代杂交种用的蚕种，一代杂交种是指用原蚕按规定组合杂交繁育的蚕种。 （二）原蚕是指由原种孵化而来的蚕，原蚕饲育区是指利用桑园与设施专门饲养原蚕的区域。"},{"i":38,"n":"第三十八条","txt":"本办法自二○○六年七月一日起施行。"}],"jinchukounongzuowuzhongziguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了进一步贯彻有关种子管理法规，加强种质资源管理，促进我国农作物种子（苗）的对外贸易与合作交流，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法中进出口农作物种子（苗）（以下简称农作物种子）包括从国（境）外引进和与国（境）外交流研究用种质资源（以下简称进出口种质资源）、进出口生产用种子。 进出口生产用种子包括试验用种子、大田用商品种子和对外制种用种子。"},{"i":3,"n":"第三条","txt":"从事进出口生产用种子业务和向国（境）外提供种质资源的单位应当具备中国法人资格。禁止个人从事进出口生产用种子业务和向国（境）外提供种质资源。 进出口大田用商品种子，应当具有与其进出口种子类别相符的种子生产、经营权及进出口权；没有进出口权的，由农业农村部指定的具有农作物种子进出口权的单位代理。"},{"i":4,"n":"第四条","txt":"进出口生产用种子，由所在地省级农业农村主管部门审核，农业农村部审批。"},{"i":5,"n":"第五条","txt":"进口试验用种子应坚持少而精的原则。每个进口品种，种子以10亩播量，苗木以100株为限。"},{"i":6,"n":"第六条","txt":"进口试验用种子应在国家或省农作物品种审定委员会的统一安排指导下进行种植试验。"},{"i":7,"n":"第七条","txt":"申请进口大田用商品种子，应符合下列条件： （一）品种应当经国家或省级农作物品种审定委员会审定通过，国内暂时没有开展审定工作而生产上又急需的作物种类品种，应当提交至少2个生育周期的引种试验报告。 （二）种子质量应当达到国家标准或行业标准；对没有国家标准或行业标准的，可以在合同中约定或参考有关国际标准。"},{"i":8,"n":"第八条","txt":"进口对外制种用种子，不受本办法第九条限制，但繁殖的种子不得在国内销售。"},{"i":9,"n":"第九条","txt":"从事进口大田用商品种子业务的单位应当在每年8月底以前将下一年度进口种子计划上报所在省级农业农村主管部门，由省级农业农村主管部门汇总后于10月底前报农业农村部。"},{"i":10,"n":"第十条","txt":"国家鼓励种子出口，但列入种质资源“不对外交换的”和未列入目录的品种及杂交作物亲本种子原则上不允许出口。特殊情况，报经农业农村部批准。"},{"i":11,"n":"第十一条","txt":"进出口生产用种子的申请和审批： （一）进出口单位向审核机关提出申请，按规定的格式及要求填写《进（出）口农作物种子（苗）审批表》（见附件三），提交进出口种子品种说明；办理进出口对外制种用种子，应提交对外制种合同（或协议书）；办理进出口大田用商品种子，应提交有关《种子经营许可证》、《营业执照》和种子进出口权的有关证明文件。审核机关同意后，再转报审批机关审批。 （二）经审批机关审批同意，加盖“中华人民共和国农业农村部进出口农作物种子审批专用章”。种子进出口单位，持有效《进出口农作物种子（苗）审批表》批件到植物检疫机关办理检疫审批手续。办理进口农作物种子的，由农业农村部出具《动植物苗种进口免税审批证明》作为海关免税放行的依据。"},{"i":12,"n":"第十二条","txt":"品资所应当在每季度开始的第一个月10日前，将上一季度进出口种质资源审批情况报农业农村部；每年1月10日前向农业农村部报上一年度工作总结。"},{"i":13,"n":"第十三条","txt":"农业农村主管部门和有关部门工作人员违反本办法规定办理进出口审批或检疫审批的，由本单位或上级机关给予行政处分；涉嫌犯罪的，及时将案件移送司法机关，依法追究刑事责任。"},{"i":14,"n":"第十四条","txt":"《进出口农作物种子（苗）审批表》由农业农村部统一印制；《对外交流农作物种质资源申请表》、《对外提供农作物种质资源准许证》由农业农村部委托品资所统一印制。"},{"i":15,"n":"第十五条","txt":"《进出口农作物种子（苗）审批表》的有效期为6个月，《动植物苗种进口免税审批证明》、《对外交流农作物种质资源准许证》的有效期为3个月。超过有效期限或需要改变进出口种子的品种、数量、进出口国家或地区的，均需重新办理审批手续。"},{"i":16,"n":"第十六条","txt":"进出口农作物种子应办理植物检疫手续，具体办法按《中华人民共和国进出境动植物检疫法》、《中华人民共和国植物检疫条例》及有关植物检疫规章规定办理。"},{"i":17,"n":"第十七条","txt":"本办法由农业农村部负责解释。"},{"i":18,"n":"第十八条","txt":"本办法自发布之日起施行。"}],"jinkousiliaohesiliaotianjiajidengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强进口饲料、饲料添加剂监督管理，保障动物产品质量安全，根据《饲料和饲料添加剂管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称饲料，是指经工业化加工、制作的供动物食用的产品，包括单一饲料、添加剂预混合饲料、浓缩饲料、配合饲料和精料补充料。 本办法所称饲料添加剂，是指在饲料加工、制作、使用过程中添加的少量或者微量物质，包括营养性饲料添加剂和一般饲料添加剂。"},{"i":3,"n":"第三条","txt":"境外企业首次向中国出口饲料、饲料添加剂，应当向农业部申请进口登记，取得饲料、饲料添加剂进口登记证；未取得进口登记证的，不得在中国境内销售、使用。"},{"i":4,"n":"第四条","txt":"境外企业申请进口登记，由境外企业驻中国境内的办事机构或者委托的中国境内代理机构办理。"},{"i":5,"n":"第五条","txt":"申请进口登记的饲料、饲料添加剂，应当符合生产地和中国的相关法律法规、技术规范的要求。 生产地未批准生产、使用或禁止生产、使用的饲料、饲料添加剂，不予登记。"},{"i":6,"n":"第六条","txt":"申请饲料、饲料添加剂进口登记，应当向农业部提交真实、完整、规范的申请资料（中英文对照，一式两份）和样品。"},{"i":7,"n":"第七条","txt":"申请资料包括： （一）饲料、饲料添加剂进口登记申请表； （二）委托书和代理机构资质证明：境外企业委托其常驻中国代表机构代理登记的，应当提供委托书原件和《外国企业常驻中国代表机构登记证》复印件；委托境内其他机构代理登记的，应当提供委托书原件和代理机构法人营业执照复印件； （三）生产地批准生产、使用的证明，生产地以外其他国家、地区的登记资料，产品推广应用情况； （四）进口饲料的产品名称、组成成分、理化性质、适用范围、使用方法；进口饲料添加剂的产品名称、主要成分、理化性质、产品来源、使用目的、适用范围、使用方法； （五）生产工艺、质量标准、检测方法和检验报告； （六）生产地使用的标签、商标和中文标签式样； （七）微生物产品或者发酵制品，还应当提供生产所用菌株的保藏情况说明。 向中国出口本办法第十三条规定的饲料、饲料添加剂的，还应当提交以下申请资料： （一）有效组分的化学结构鉴定报告或动物、植"},{"i":8,"n":"第八条","txt":"产品样品应当符合以下要求： （一）每个产品提供3个批次、每个批次2份的样品，每份样品不少于检测需要量的5倍； （二）必要时提供相关的标准品或化学对照品。"},{"i":9,"n":"第九条","txt":"农业部自受理申请之日起10个工作日内对申请资料进行审查；审查合格的，通知申请人将样品交由农业部指定的检验机构进行复核检测。"},{"i":10,"n":"第十条","txt":"复核检测包括质量标准复核和样品检测。检测方法有国家标准和行业标准的，优先采用国家标准或行业标准；没有国家标准和行业标准的，采用企业提供的检测方法；必要时，检验机构可以根据实际情况对检测方法进行调整。 检验机构应当在3个月内完成复核检测工作，并将复核检测报告报送农业部，同时抄送申请人。"},{"i":11,"n":"第十一条","txt":"申请人对复核检测结果有异议的，可以自收到复核检测报告之日起15个工作日内申请复检。"},{"i":12,"n":"第十二条","txt":"复核检测合格的，农业部在10个工作日内核发饲料、饲料添加剂进口登记证，并予以公告。"},{"i":13,"n":"第十三条","txt":"申请进口登记的饲料、饲料添加剂有下列情形之一的，由农业部依照新饲料、新饲料添加剂的评审程序组织评审： （一）向中国出口中国境内尚未使用但生产地已经批准生产和使用的饲料、饲料添加剂的； （二）饲料添加剂扩大适用范围的； （三）饲料添加剂含量规格低于饲料添加剂安全使用规范要求的，但由饲料添加剂与载体或者稀释剂按照一定比例配制的除外； （四）饲料添加剂生产工艺发生重大变化的； （五）农业部已核发新饲料、新饲料添加剂证书的产品，自获证之日起超过3年未投入生产的； （六）存在质量安全风险的其他情形。"},{"i":14,"n":"第十四条","txt":"饲料、饲料添加剂进口登记证有效期为5年。 饲料、饲料添加剂进口登记证有效期满需要继续向中国出口饲料、饲料添加剂的，应当在有效期届满6个月前申请续展。"},{"i":15,"n":"第十五条","txt":"申请续展应当提供以下资料： （一）进口饲料、饲料添加剂续展登记申请表； （二）进口登记证复印件； （三）委托书和代理机构资质证明； （四）生产地批准生产、使用的证明； （五）质量标准、检测方法和检验报告； （六）生产地使用的标签、商标和中文标签式样。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，申请续展时还应当提交样品进行复核检测： （一）根据相关法律法规、技术规范，需要对产品质量和安全检测项目进行调整的； （二）产品检测方法发生改变的； （三）监督抽查中有不合格记录的。"},{"i":17,"n":"第十七条","txt":"进口登记证有效期内，进口饲料、饲料添加剂的生产场所迁址，或者产品质量标准、生产工艺、适用范围等发生变化的，应当重新申请登记。"},{"i":18,"n":"第十八条","txt":"进口饲料、饲料添加剂在进口登记证有效期内有下列情形之一的，应当申请变更登记： （一）产品中文或外文商品名称改变的； （二）申请企业名称改变的； （三）生产厂家名称改变的； （四）生产地址名称改变的。"},{"i":19,"n":"第十九条","txt":"申请变更登记应当提供以下资料： （一）进口饲料、饲料添加剂变更登记申请表； （二）委托书和代理机构资质证明； （三）进口登记证原件； （四）变更说明及相关证明文件。 农业部在受理变更登记申请后10个工作日内作出是否准予变更的决定。"},{"i":20,"n":"第二十条","txt":"从事进口饲料、饲料添加剂登记工作的相关单位和人员，应当对申请人提交的需要保密的技术资料保密。"},{"i":21,"n":"第二十一条","txt":"境外企业应当依法在中国境内设立销售机构或者委托符合条件的中国境内代理机构销售进口饲料、饲料添加剂。 境外企业不得直接在中国境内销售进口饲料、饲料添加剂。"},{"i":22,"n":"第二十二条","txt":"境外企业应当在取得饲料、饲料添加剂进口登记证之日起6个月内，在中国境内设立销售机构或确定委托销售代理机构并报农业部备案。 前款规定的销售机构或销售代理机构发生变更的，应当在1个月内报农业部重新备案。"},{"i":23,"n":"第二十三条","txt":"进口饲料、饲料添加剂应当包装，包装应当符合中国有关安全、卫生的规定，并附具符合规定的中文标签。"},{"i":24,"n":"第二十四条","txt":"进口饲料、饲料添加剂在使用过程中被证实对养殖动物、人体健康或环境有害的，由农业部公告禁用并撤销进口登记证。 饲料、饲料添加剂进口登记证有效期内，生产地禁止使用该饲料、饲料添加剂产品或者撤销其生产、使用许可的，境外企业应当立即向农业部报告，由农业部撤销进口登记证并公告。"},{"i":25,"n":"第二十五条","txt":"境外企业发现其向中国出口的饲料、饲料添加剂对养殖动物、人体健康有害或者存在其他安全隐患的，应当立即通知其在中国境内的销售机构或销售代理机构，并向农业部报告。 境外企业在中国境内的销售机构或销售代理机构应当主动召回前款规定的产品，记录召回情况，并向销售地饲料管理部门报告。 召回的产品应当在县级以上地方人民政府饲料管理部门监督下予以无害化处理或者销毁。"},{"i":26,"n":"第二十六条","txt":"农业部和县级以上地方人民政府饲料管理部门，应当根据需要定期或者不定期组织实施进口饲料、饲料添加剂监督抽查；进口饲料、饲料添加剂监督抽查检测工作由农业部或者省、自治区、直辖市人民政府饲料管理部门指定的具有相应技术条件的机构承担。 进口饲料、饲料添加剂监督抽查检测，依据进口登记过程中复核检测确定的质量标准进行。"},{"i":27,"n":"第二十七条","txt":"农业部和省级人民政府饲料管理部门应当及时公布监督抽查结果，并可以公布具有不良记录的境外企业及其销售机构、销售代理机构名单。"},{"i":28,"n":"第二十八条","txt":"从事进口饲料、饲料添加剂登记工作的相关人员，不履行本办法规定的职责或者滥用职权、玩忽职守、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"提供虚假资料、样品或者采取其他欺骗手段申请进口登记的，农业部对该申请不予受理或者不予批准，1年内不再受理该境外企业和登记代理机构的进口登记申请。 提供虚假资料、样品或者采取其他欺骗方式取得饲料、饲料添加剂进口登记证的，由农业部撤销进口登记证，对登记代理机构处5万元以上10万元以下罚款，3年内不再受理该境外企业和登记代理机构的进口登记申请。"},{"i":30,"n":"第三十条","txt":"其他违反本办法的行为，依照《饲料和饲料添加剂管理条例》的有关规定处罚。"},{"i":31,"n":"第三十一条","txt":"本办法自2014年7月1日起施行。农业部2000年8月17日公布、2004年7月1日修订的《进口饲料和饲料添加剂登记管理办法》同时废止。"}],"yuanyangyuyeguanliguiding-2":[{"i":1,"n":"第一条","txt":"为加强远洋渔业管理，维护国家和远洋渔业企业及从业人员的合法权益，养护和可持续利用海洋渔业资源，促进远洋渔业持续、健康发展，根据《中华人民共和国渔业法》及有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称远洋渔业，是指中华人民共和国公民、法人和其他组织到公海和他国管辖海域从事海洋捕捞以及与之配套的加工、补给和产品运输等渔业活动，但不包括到黄海、东海和南海从事的渔业活动。"},{"i":3,"n":"第三条","txt":"国家支持、促进远洋渔业可持续发展，建立规模合理、布局科学、装备优良、配套完善、管理规范、生产安全的现代化远洋渔业产业体系。"},{"i":4,"n":"第四条","txt":"农业农村部主管全国远洋渔业工作，负责全国远洋渔业的规划、组织和管理，会同国务院其他有关部门对远洋渔业企业执行国家有关法规和政策的情况进行监督。 省级人民政府渔业行政主管部门负责本行政区域内远洋渔业的规划、组织和监督管理。 市、县级人民政府渔业行政主管部门协助省级渔业行政主管部门做好远洋渔业相关工作。"},{"i":5,"n":"第五条","txt":"国家鼓励远洋渔业企业依法自愿成立远洋渔业协会，加强行业自律管理，维护成员合法权益。"},{"i":6,"n":"第六条","txt":"农业农村部对远洋渔业实行项目审批管理和企业资格认定制度，并依法对远洋渔业船舶和船员进行监督管理。"},{"i":7,"n":"第七条","txt":"远洋渔业项目审批和企业资格认定通过农业农村部远洋渔业管理系统办理。 申请人应当提供的渔业船舶检验证书、渔业船舶登记证等法定证照、权属证明，在全国渔船动态管理系统、远洋渔业管理系统或者部门间核查能够查询到有效信息的，可以不再提供纸质材料。"},{"i":8,"n":"第八条","txt":"同时具备下列条件的企业，可以从事远洋渔业，申请开展远洋渔业项目： （一）在我国市场监管部门登记，具有独立法人资格，经营范围包括海洋（远洋）捕捞； （二）拥有符合要求的适合从事远洋渔业的合法渔业船舶； （三）具有承担项目运营和意外风险的经济实力； （四）有熟知远洋渔业政策、相关法律规定、国外情况并具有3年以上远洋渔业生产及管理经验的专职经营管理人员； （五）申请前的3年内没有被农业农村部取消远洋渔业企业资格的记录，企业主要负责人和项目负责人申请前的3年内没有在被农业农村部取消远洋渔业企业资格的企业担任主要负责人和项目负责人的记录。"},{"i":9,"n":"第九条","txt":"符合本规定第八条条件的企业申请开展远洋渔业项目的，应当通过所在地省级人民政府渔业行政主管部门提出，经省级人民政府渔业行政主管部门审核同意后报农业农村部审批。 中央直属企业直接报农业农村部审批。 省级人民政府渔业行政主管部门应当在10日内完成审核。"},{"i":10,"n":"第十条","txt":"申请远洋渔业项目时，应当报送以下材料： （一）项目申请报告。 申请报告应当包括企业基本情况和条件、项目组织和经营管理计划、已开展远洋渔业项目（如有）的情况等内容，同时填写《申请远洋渔业项目基本情况表》（见附表一）。 （二）项目可行性研究报告。 （三）到他国管辖海域作业的，提供与外方的合作协议或他国政府主管部门同意入渔的证明、我驻项目所在国使（领）馆的意见；境外成立独资或合资企业的，还需提供我国商务行政主管部门出具的《企业境外投资证书》和入渔国有关政府部门出具的企业注册证明。到公海作业的，填报《公海渔业捕捞许可证申请书》（见附表二）。 （四）拟派渔船所有权证书、登记（国籍）证书、远洋渔船检验证书。属制造、更新改造、购置或进口的专业远洋渔船，需同时提供农业农村部《渔业船网工具指标批准书》；属非专业远洋渔船（具有国内有效渔业捕捞许可证转产从事远洋渔业的渔船），需同时提供国内《海洋渔业捕捞许可"},{"i":11,"n":"第十一条","txt":"农业农村部收到符合本规定第十条要求的远洋渔业项目申请后，在15个工作日内作出是否批准的决定。特殊情况需要延长决定期限的，应当及时告知申请企业延长决定期限的理由。 经审查批准远洋渔业项目申请的，农业农村部书面通知申请项目企业及其所在地省级人民政府渔业行政主管部门，并抄送国务院其他有关部门。 从事公海捕捞作业的，农业农村部批准远洋渔业项目的同时，颁发《公海渔业捕捞许可证》。 经审查不予批准远洋渔业项目申请的，农业农村部将决定及理由书面通知申请项目企业。"},{"i":12,"n":"第十二条","txt":"对已经实施的远洋渔业项目，农业农村部根据以下不同情况分别进行确认： （一）从国内港口离境的渔船，依据海事行政主管部门颁发的《国际航行船舶出口岸许可证》进行确认； （二）在海上转移渔场或变更渔船所有人的渔船，依据远洋渔业项目批准文件进行确认； （三）船舶证书到期的渔船，依据发证机关换发的有效证书进行确认； （四）因入渔需要变更渔船国籍的，依据渔船的中国国籍中止或注销证明、入渔国政府主管部门签发的捕捞许可证和渔船登记证书、检验证书及中文翻译件进行确认。"},{"i":13,"n":"第十三条","txt":"取得农业农村部远洋渔业项目批准后，企业持批准文件和其他有关材料，办理远洋渔业船舶和船员证书等有关手续。"},{"i":14,"n":"第十四条","txt":"到他国管辖海域从事捕捞作业的远洋渔业项目开始执行后，企业项目负责人应当持农业农村部远洋渔业项目批准文件到我驻外使（领）馆登记，接受使（领）馆的监督和指导。"},{"i":15,"n":"第十五条","txt":"企业在项目执行期间，应当按照农业农村部的规定及时、准确地向所在地省级人民政府渔业行政主管部门等单位报告下列情况，由省级人民政府渔业行政主管部门等单位汇总后报农业农村部： （一）投产各渔船渔获量、主要品种、产值等生产情况。除另有规定外，应当于每月10日前按要求报送上月生产情况； （二）自捕水产品运回情况，按照海关总署和农业农村部的要求报告； （三）农业农村部或国际渔业管理组织要求报告的其他情况。"},{"i":16,"n":"第十六条","txt":"远洋渔业项目执行过程中需要改变作业国家（地区）或海域、作业类型、入渔方式、渔船数量（包括更换渔船）、渔船所有人以及重新成立独资或合资企业的，应当提供本规定第十条规定的与变更内容有关的材料，按照本规定第九条规定的程序事先报农业农村部批准。其中改变作业国家的，除提供第十条第（三）项规定的材料外，还应当提供我驻原项目所在国使（领）馆的意见。"},{"i":17,"n":"第十七条","txt":"项目终止或执行完毕后，远洋渔业企业应当及时向省级人民政府渔业行政主管部门报告，提交项目执行情况总结，经省级人民政府渔业行政主管部门报农业农村部办理远洋渔业项目终止手续。 远洋渔业企业应当将终止项目的渔船开回国内，并在渔船入境之日起5个工作日内，将海事行政主管部门出具的《船舶进口岸手续办妥通知单》和渔政渔港监督部门出具的渔船停港证明报农业农村部。 远洋渔船终止远洋渔业项目或远洋渔业项目无法继续执行的，企业应于项目终止或停止之日起18个月内对渔船予以妥善处置，因客观原因未能在18个月内处置完毕的，可适当延长处置时间，但最长不得超过36个月。期限届满仍未妥善处置的，由省级人民政府渔业行政主管部门按《渔业船舶登记办法》等有关规定注销渔船登记。"},{"i":18,"n":"第十八条","txt":"对于已获农业农村部批准并开始实施远洋渔业项目的企业，其生产经营情况正常，认真遵守有关法律、法规和本规定，未发生严重违规事件的，农业农村部授予其远洋渔业企业资格，并颁发《农业农村部远洋渔业企业资格证书》。 取得《农业农村部远洋渔业企业资格证书》的企业，可以根据有关规定享受国家对远洋渔业的支持政策。"},{"i":19,"n":"第十九条","txt":"农业农村部对远洋渔业企业资格和远洋渔业项目进行年度审查。对审查合格的企业，换发当年度《农业农村部远洋渔业企业资格证书》；对审查合格的渔船，延续确认当年度远洋渔业项目。 申请年审的远洋渔业企业应当于每年1月15日以前向所在地省级人民政府渔业行政主管部门报送下列材料： （一）上年度远洋渔业项目执行情况报告。 （二）《远洋渔业企业资格和项目年审登记表》（见附表三）。 （三）有效的渔业船舶所有权证书、国籍证书和检验证书。其中，在他国注册登记的渔船需提供登记国政府主管部门签发的渔船登记和检验证书及中文翻译件。在他国注册登记的渔船如已更新改造，还应提供原船证书注销证明及中文翻译件。 （四）到他国管辖海域从事捕捞作业的，还应提供入渔国政府主管部门颁发的捕捞许可证和企业注册证明及中文翻译件，我驻入渔国使（领）馆出具的意见等。 省级人民政府渔业行政主管部门应当对有关材料进行认真审核，对所辖区域的远洋渔业"},{"i":20,"n":"第二十条","txt":"远洋渔船应当经渔业船舶检验机构技术检验合格、渔港监督部门依法登记，取得相关证书，符合我国法律、法规和有关国际条约的管理规定。 不得使用未取得相关证书的渔船从事远洋渔业生产。 不得使用被有关区域渔业管理组织公布的从事非法、不报告和不受管制渔业活动的渔船从事远洋渔业生产。"},{"i":21,"n":"第二十一条","txt":"制造、更新改造、购置、进口远洋渔船或更新改造非专业远洋渔船开展远洋渔业的，应当根据《渔业捕捞许可管理规定》事先报农业农村部审批。 淘汰的远洋渔船，应当实施报废处置。 根据他国法律规定，远洋渔船需要加入他国国籍方可在他国海域作业的，应当按《渔业船舶登记办法》有关规定，办理中止或注销中国国籍登记。"},{"i":22,"n":"第二十二条","txt":"远洋渔船应当从国家对外开放口岸出境和入境，随船携带登记（国籍）证书、检验证书、《公海捕捞许可证》以及该船适用的国际公约要求的有关证书。"},{"i":23,"n":"第二十三条","txt":"在我国注册登记的远洋渔船，悬挂中华人民共和国国旗，按国家有关规定进行标识；在他国注册登记的远洋渔船，按登记国规定悬挂旗帜、进行标识。 国际渔业组织对远洋渔船标识有规定的，按其规定执行。"},{"i":24,"n":"第二十四条","txt":"专业远洋渔船不得在我国管辖海域从事渔业活动。 经批准到公海或他国管辖海域从事捕捞作业的非专业远洋渔船，出境前应当将《海洋渔业捕捞许可证》交回原发证机关暂存，在实施远洋渔业项目期间禁止在我国管辖海域从事渔业活动。在终止远洋渔业项目并办妥相关手续后，按《渔业捕捞许可管理规定》从原发证机构领回《海洋渔业捕捞许可证》后，方可在国内海域从事渔业生产。"},{"i":25,"n":"第二十五条","txt":"远洋渔船应当按照规定填写渔捞日志，并接受渔业行政主管部门的监督检查。"},{"i":26,"n":"第二十六条","txt":"远洋渔船应当按规定配备与管理船员。 远洋渔业船员应当按规定接受培训，经考试或考核合格取得相应的渔业船员证书后才能上岗，并持有海员证或护照等本人有效出入境证件。外籍、港澳台船员的管理按照国家有关规定执行。 远洋渔业船员、远洋渔业企业及项目负责人和经营管理人员应当学习国际渔业法律法规、安全生产和涉外知识，参加渔业行政主管部门或其委托机构组织的培训。"},{"i":27,"n":"第二十七条","txt":"远洋渔业企业承担安全生产主体责任，应当按规定设置安全生产管理机构或配备安全生产管理人员，建立安全生产责任制。 远洋渔业企业的法定代表人和主要负责人，对本企业的安全生产工作全面负责；远洋渔业项目负责人，对项目的执行、生产经营管理、渔船活动和船员负监管责任；远洋渔船船长对渔船海上航行、生产作业和锚泊安全等负直接责任。"},{"i":28,"n":"第二十八条","txt":"远洋渔业企业应当与其聘用的远洋渔业船员或远洋渔业船员所在单位直接签订合同，为远洋渔业船员办理有关保险，按时发放工资，保障远洋渔业船员的合法权益，不得向远洋渔业船员收取不合理费用。 远洋渔业企业不得聘用未取得有效渔业船员证书的人员作为远洋渔业船员，聘用的远洋渔业船员不得超过农业农村部远洋渔业项目批准文件核定的船员数。"},{"i":29,"n":"第二十九条","txt":"远洋渔业企业应当在远洋渔业船员出境前对其进行安全生产、外事纪律和法律知识等培训教育。 远洋渔业船员在境外应当遵守所在国法律、法规和有关国际条约、协定的规定，尊重当地的风俗习惯。"},{"i":30,"n":"第三十条","txt":"远洋渔船船长应当认真履行《渔业船员管理办法》规定的有关职责，确保渔船正常航行和依法进行渔业生产，严禁违法进入他国管辖水域生产。 按照我国加入的国际公约或区域渔业组织要求，远洋渔船在公海或他国管辖水域被要求登临检查时，船长应当核实执法船舶及人员身份，配合经授权的执法人员对渔船实施登临检查。禁止逃避执法检查或以暴力、危险等方法抗拒执法检查。"},{"i":31,"n":"第三十一条","txt":"到公海作业的远洋渔船，应当按照农业农村部远洋渔业项目批准文件和《公海渔业捕捞许可证》限定的作业海域、类型、时限、品种和配额作业，遵守我国缔结或者参加的国际条约、协定。 到他国管辖海域作业的远洋渔船，应当遵守我国与该国签订的渔业协议及该国的法律法规。 远洋渔船作业时应当与未授权作业海域外部界限保持安全的缓冲距离，避免赴有关国家争议海域作业。"},{"i":32,"n":"第三十二条","txt":"远洋渔船在通过他国管辖水域前，应妥善保存渔获、捆绑覆盖渔具，并按有关规定提前通报。通过他国管辖水域时，应保持连续和匀速航行，填写航行日志，禁止从事捕捞、渔获物转运、补给等任何渔业生产活动。 渔船在他国港口内或通过他国管辖海域时，不得丢弃船上渔获物或其他杂物，不得排放油污、污水及从事其他损坏海洋生态环境的行为。"},{"i":33,"n":"第三十三条","txt":"禁止远洋渔业企业、渔船和船员从事、支持或协助非法、不报告和不受管制的渔业活动。"},{"i":34,"n":"第三十四条","txt":"农业农村部发布远洋渔业从业人员“黑名单”。存在严重违法违规行为、对重大安全生产责任事故负主要责任和引发远洋渔业涉外违规事件的企业主要管理人员、项目负责人和船长，纳入远洋渔业从业人员“黑名单”管理。 纳入远洋渔业从业人员“黑名单”的企业主要管理人员、项目负责人，3年内不得在远洋渔业企业担任主要管理人员或项目负责人。纳入远洋渔业从业人员“黑名单”的船长自被吊销职务船员证书之日起，5年内不得申请渔业船员证书。"},{"i":35,"n":"第三十五条","txt":"农业农村部根据管理需要对远洋渔船进行船位和渔获情况监测。远洋渔船应当根据农业农村部制定的监测计划安装渔船监测系统（VMS），并配备持有技术培训合格证的船员，保障系统正常工作，及时、准确提供真实信息。 农业农村部可根据有关国际组织的要求或管理需要向远洋渔船派遣国家观察员。远洋渔业企业和远洋渔船有义务接纳国家观察员或有关国际渔业组织派遣的观察员，协助并配合观察员工作，不得安排观察员从事与其职责无关的工作。"},{"i":36,"n":"第三十六条","txt":"两个以上远洋渔业企业在同一国家（地区）或海域作业，或从事同品种、同类型作业，应当建立企业自我协调和自律机制，接受行业协会的指导，配合政府有关部门进行协调和管理。"},{"i":37,"n":"第三十七条","txt":"远洋渔业企业、渔船和船员在国外发生涉外事件时，应当立即如实向农业农村部、企业所在地省级人民政府渔业行政主管部门和有关驻外使（领）馆报告，省级人民政府渔业行政主管部门接到报告后，应当立即核实情况，并提出处理意见报农业农村部和省级人民政府，由农业农村部协调提出处理意见通知驻外使领馆。发生重大涉外事件需要对外交涉的，由农业农村部商外交部提出处理意见，进行交涉。 远洋渔船发生海难等海上安全事故时，远洋渔业企业应当立即组织自救互救，并按规定向农业农村部、企业所在地省级人民政府渔业行政主管部门报告。需要紧急救助的，按照有关国际规则和国家规定执行。发生违法犯罪事件时，远洋渔业企业应当立即向所在地公安机关和边防部门报告，做好伤员救治、嫌疑人控制、现场保护等工作。 远洋渔业企业和所在地各级人民政府渔业行政主管部门应当认真负责、迅速、妥善处理涉外和海上安全事件。"},{"i":38,"n":"第三十八条","txt":"各级人民政府渔业行政主管部门及其所属的渔政渔港监督管理机构应当会同有关部门，加强远洋渔船在国内渔业港口的监督与管理，严格执行渔船进出渔港报告制度。 除因人员病急、机件故障、遇难、避风等特殊情况外，禁止被有关国际渔业组织纳入非法、不报告和不受管制渔业活动名单的船舶进入我国港口。因人员病急、机件故障、遇难、避风等特殊情况或非法进入我国港口的，由港口所在地省级人民政府渔业行政主管部门会同同级港口、海关、边防等部门，在农业农村部、外交部等国务院有关部门指导下，依据我国法律、行政法规及我国批准或加入的相关国际条约，进行调查处理。"},{"i":39,"n":"第三十九条","txt":"远洋渔业企业、渔船或船员有下列违法行为的，由省级以上人民政府渔业行政主管部门或其所属的渔政渔港监督管理机构根据《中华人民共和国渔业法》《中华人民共和国野生动物保护法》和有关法律、法规予以处罚。对已经取得农业农村部远洋渔业企业资格的企业，农业农村部视情节轻重和影响大小，暂停或取消其远洋渔业企业资格。 （一）未经农业农村部批准擅自从事远洋渔业生产，或未取得《公海渔业捕捞许可证》从事公海捕捞生产的； （二）申报或实施远洋渔业项目时隐瞒真相、弄虚作假的； （三）不按农业农村部批准的或《公海渔业捕捞许可证》规定的作业类型、场所、时限、品种和配额生产，或未经批准进入他国管辖水域作业的； （四）使用入渔国或有管辖权的区域渔业管理组织禁用的渔具、渔法进行捕捞，或捕捞入渔国或有管辖权的区域渔业管理组织禁止捕捞的鱼种、珍贵濒危水生野生动物或其他海洋生物的； （五）未取得有效的船舶证书，或不符合远洋渔船的有"},{"i":40,"n":"第四十条","txt":"被暂停农业农村部远洋渔业企业资格的企业，整改后经省级人民政府渔业行政主管部门和农业农村部审查合格的，可恢复其远洋渔业企业资格和所属渔船远洋渔业项目。 1年内经整改仍不合格的，取消其农业农村部远洋渔业企业资格。"},{"i":41,"n":"第四十一条","txt":"当事人对渔业行政处罚有异议的，可按《中华人民共和国行政复议法》和《中华人民共和国行政诉讼法》的有关规定申请行政复议或提起行政诉讼。"},{"i":42,"n":"第四十二条","txt":"各级人民政府渔业行政主管部门工作人员有不履行法定义务、玩忽职守、徇私舞弊等行为，尚不构成犯罪的，由所在单位或上级主管机关予以行政处分。"},{"i":43,"n":"第四十三条","txt":"本规定所称远洋渔船是指中华人民共和国公民、法人或其他组织所有并从事远洋渔业活动的渔业船舶，包括捕捞渔船和渔业辅助船。远洋渔业船员是指在远洋渔船上工作的所有船员，包括职务船员。 本规定所称省级人民政府渔业行政主管部门包括计划单列市人民政府渔业行政主管部门。"},{"i":44,"n":"第四十四条","txt":"本规定自2020年4月1日起施行。农业部2003年4月18日发布、2004年7月1日修正、2016年5月30日修正的《远洋渔业管理规定》同时废止。 　　附表：一、申请远洋渔业项目基本情况表 　　　　　二、公海渔业捕捞许可证申请书 　　　　　三、农业农村部远洋渔业企业资格和项目年审登记表 附表一 申请远洋渔业项目基本情况表 附表二 申请书受理编号： 公海渔业捕捞许可证申请书 附表三 农业农村部远洋渔业企业资格和项目年审登记表 附表三（续） 农业农村部远洋渔业企业资格和项目年审登记表"}],"yuanyangyuyeguanliguiding":[{"i":1,"n":"第一条","txt":"为加强远洋渔业管理，维护国家和远洋渔业企业及从业人员的合法权益，养护和可持续利用海洋渔业资源，促进远洋渔业持续、健康发展，根据《中华人民共和国渔业法》及有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称远洋渔业，是指中华人民共和国公民、法人和其他组织到公海和他国管辖海域从事海洋捕捞以及与之配套的加工、补给和产品运输等渔业活动，但不包括到黄海、东海和南海从事的渔业活动。"},{"i":3,"n":"第三条","txt":"国家支持、促进远洋渔业可持续发展，建立规模合理、布局科学、装备优良、配套完善、管理规范、生产安全的现代化远洋渔业产业体系。"},{"i":4,"n":"第四条","txt":"农业农村部主管全国远洋渔业工作，负责全国远洋渔业的规划、组织和管理，会同国务院其他有关部门对远洋渔业企业执行国家有关法规和政策的情况进行监督。 省级人民政府渔业行政主管部门负责本行政区域内远洋渔业的规划、组织和监督管理。 市、县级人民政府渔业行政主管部门协助省级渔业行政主管部门做好远洋渔业相关工作。"},{"i":5,"n":"第五条","txt":"国家鼓励远洋渔业企业依法自愿成立远洋渔业协会，加强行业自律管理，维护成员合法权益。"},{"i":6,"n":"第六条","txt":"农业农村部对远洋渔业实行项目审批管理和企业资格认定制度，并依法对远洋渔业船舶和船员进行监督管理。"},{"i":7,"n":"第七条","txt":"远洋渔业项目审批和企业资格认定通过农业农村部远洋渔业管理系统办理。 申请人应当提供的渔业船舶检验证书、渔业船舶登记证等法定证照、权属证明，在全国渔船动态管理系统、远洋渔业管理系统或者部门间核查能够查询到有效信息的，可以不再提供纸质材料。"},{"i":8,"n":"第八条","txt":"同时具备下列条件的企业，可以从事远洋渔业，申请开展远洋渔业项目： （一）在我国市场监管部门登记，具有独立法人资格，经营范围包括海洋（远洋）捕捞； （二）拥有符合要求的适合从事远洋渔业的合法渔业船舶； （三）具有承担项目运营和意外风险的经济实力； （四）有熟知远洋渔业政策、相关法律规定、国外情况并具有3年以上远洋渔业生产及管理经验的专职经营管理人员； （五）申请前的3年内没有被农业农村部取消远洋渔业企业资格的记录，企业主要负责人和项目负责人申请前的3年内没有在被农业农村部取消远洋渔业企业资格的企业担任主要负责人和项目负责人的记录。"},{"i":9,"n":"第九条","txt":"符合本规定第八条条件的企业申请开展远洋渔业项目的，应当通过所在地省级人民政府渔业行政主管部门提出，经省级人民政府渔业行政主管部门审核同意后报农业农村部审批。中央直属企业直接报农业农村部审批。 省级人民政府渔业行政主管部门应当在10日内完成审核。"},{"i":10,"n":"第十条","txt":"申请远洋渔业项目时，应当报送以下材料： （一）项目申请报告。申请报告应当包括企业基本情况和条件、项目组织和经营管理计划、已开展远洋渔业项目（如有）的情况等内容，同时填写《申请远洋渔业项目基本情况表》（见附表一）。 （二）项目可行性研究报告。 （三）到他国管辖海域作业的，提供与外方的合作协议或他国政府主管部门同意入渔的证明、我驻项目所在国使（领）馆的意见。境外成立独资或合资企业的，还需提供我国商务行政主管部门出具的《企业境外投资证书》和入渔国有关政府部门出具的企业注册证明；到公海作业的，填报《公海渔业捕捞许可证申请书》（见附表二）。 （四）拟派渔船所有权证书、登记（国籍）证书、远洋渔船检验证书。属制造、更新改造、购置或进口的专业远洋渔船，需同时提供农业农村部《渔业船网工具指标批准书》；属非专业远洋渔船（具有国内有效渔业捕捞许可证转产从事远洋渔业的渔船），需同时提供国内《海洋渔业捕捞许可证"},{"i":11,"n":"第十一条","txt":"农业农村部收到符合本规定第十条要求的远洋渔业项目申请后，在15个工作日内做出是否批准的决定。特殊情况需要延长决定期限的，应当及时告知申请企业延长决定期限的理由。 经审查批准远洋渔业项目申请的，农业农村部书面通知申请项目企业及其所在地省级人民政府渔业行政主管部门，并抄送国务院其他有关部门。 从事公海捕捞作业的，农业农村部批准远洋渔业项目的同时，颁发《公海渔业捕捞许可证》。 经审查不予批准远洋渔业项目申请的，农业农村部将决定及理由书面通知申请项目企业。"},{"i":12,"n":"第十二条","txt":"对已经实施的远洋渔业项目，农业农村部根据以下不同情况分别进行确认： （一）从国内港口离境的渔船，依据海事行政主管部门颁发的《国际航行船舶出口岸许可证》进行确认； （二）在海上转移渔场或变更渔船所有人的渔船，依据远洋渔业项目批准文件进行确认； （三）船舶证书到期的渔船，依据发证机关换发的有效证书进行确认； （四）因入渔需要变更渔船国籍的，依据渔船的中国国籍中止或注销证明、入渔国政府主管部门签发的捕捞许可证和渔船登记证书、检验证书及中文翻译件进行确认。"},{"i":13,"n":"第十三条","txt":"取得农业农村部远洋渔业项目批准后，企业持批准文件和其他有关材料，办理远洋渔业船舶和船员证书等有关手续。"},{"i":14,"n":"第十四条","txt":"到他国管辖海域从事捕捞作业的远洋渔业项目开始执行后，企业项目负责人应当持农业农村部远洋渔业项目批准文件到我驻外使（领）馆登记，接受使（领）馆的监督和指导。"},{"i":15,"n":"第十五条","txt":"企业在项目执行期间，应当按照农业农村部的规定及时、准确地向所在地省级人民政府渔业行政主管部门等单位报告下列情况，由省级人民政府渔业行政主管部门等单位汇总后报农业农村部： （一）投产各渔船渔获量、主要品种、产值等生产情况。除另有规定外，应当于每月10日前按要求报送上月生产情况； （二）自捕水产品运回情况，按照海关总署和农业农村部的要求报告； （三）农业农村部或国际渔业管理组织要求报告的其他情况。"},{"i":16,"n":"第十六条","txt":"远洋渔业项目执行过程中需要改变作业国家（地区）或海域、作业类型、入渔方式、渔船数量（包括更换渔船）、渔船所有人以及重新成立独资或合资企业的，应当提供本规定第十条规定的与变更内容有关的材料，按照本规定第九条规定的程序事先报农业农村部批准。其中改变作业国家的，除提供第十条第（三）项规定的材料外，还应当提供我驻原项目所在国使（领）馆的意见。"},{"i":17,"n":"第十七条","txt":"项目终止或执行完毕后，远洋渔业企业应当及时向省级人民政府渔业行政主管部门报告，提交项目执行情况总结，经省级人民政府渔业行政主管部门报农业农村部办理远洋渔业项目终止手续。 远洋渔业企业应当将终止项目的渔船开回国内，并在渔船入境之日起5个工作日内，将海事行政主管部门出具的《船舶进口岸手续办妥通知单》和渔政渔港监督部门出具的渔船停港证明报农业农村部。 远洋渔船终止远洋渔业项目或远洋渔业项目无法继续执行的，企业应于项目终止或停止之日起18个月内对渔船予以妥善处置，因客观原因未能在18个月内处置完毕的，可适当延长处置时间，但最长不得超过36个月。期限届满仍未妥善处置的，由省级人民政府渔业行政主管部门按《渔业船舶登记办法》等有关规定注销渔船登记。"},{"i":18,"n":"第十八条","txt":"对于已获农业农村部批准并开始实施远洋渔业项目的企业，其生产经营情况正常，认真遵守有关法律、法规和本规定，未发生严重违规事件的，农业农村部授予其远洋渔业企业资格，并颁发《农业农村部远洋渔业企业资格证书》。 取得《农业农村部远洋渔业企业资格证书》的企业，可以根据有关规定享受国家对远洋渔业的支持政策。"},{"i":19,"n":"第十九条","txt":"农业农村部对远洋渔业企业资格和远洋渔业项目进行年度审查。对审查合格的企业，换发当年度《农业农村部远洋渔业企业资格证书》；对审查合格的渔船，延续确认当年度远洋渔业项目。 申请年审的远洋渔业企业应当于每年1月15日以前向所在地省级人民政府渔业行政主管部门报送下列材料： （一）上年度远洋渔业项目执行情况报告。 （二）《远洋渔业企业资格和项目年审登记表》（见附表三）。 （三）有效的渔业船舶所有权证书、国籍证书和检验证书。其中，在他国注册登记的渔船需提供登记国政府主管部门签发的渔船登记和检验证书及中文翻译件。在他国注册登记的渔船如已更新改造，还应提供原船证书注销证明及中文翻译件。 （四）到他国管辖海域从事捕捞作业的，还应提供入渔国政府主管部门颁发的捕捞许可证和企业注册证明及中文翻译件，我驻入渔国使（领）馆出具的意见等。 省级人民政府渔业行政主管部门应当对有关材料进行认真审核，对所辖区域的远洋渔业"},{"i":20,"n":"第二十条","txt":"远洋渔船应当经渔业船舶检验机构技术检验合格、渔港监督部门依法登记，取得相关证书，符合我国法律、法规和有关国际条约的管理规定。 不得使用未取得相关证书的渔船从事远洋渔业生产。 不得使用被有关区域渔业管理组织公布的从事非法、不报告和不受管制渔业活动的渔船从事远洋渔业生产。"},{"i":21,"n":"第二十一条","txt":"制造、更新改造、购置、进口远洋捕捞渔船或更新改造非专业远洋渔船开展远洋渔业的，应当根据《渔业捕捞许可管理规定》事先报农业农村部审批。 淘汰的远洋渔船，应当实施报废处置。 根据他国法律规定，远洋渔船需要加入他国国籍方可在他国海域作业的，应当按《渔业船舶登记办法》有关规定，办理中止或注销中国国籍登记。"},{"i":22,"n":"第二十二条","txt":"远洋渔船应当从国家对外开放口岸出境和入境，随船携带登记（国籍）证书、检验证书、《公海捕捞许可证》以及该船适用的国际公约要求的有关证书。"},{"i":23,"n":"第二十三条","txt":"在我国注册登记的远洋渔船，悬挂中华人民共和国国旗，按国家有关规定进行标识；在他国注册登记的远洋渔船，按登记国规定悬挂旗帜、进行标识。国际渔业组织对远洋渔船标识有规定的，按其规定执行。"},{"i":24,"n":"第二十四条","txt":"专业远洋渔船不得在我国管辖海域从事渔业活动。 经批准到公海或他国管辖海域从事捕捞作业的非专业远洋渔船，出境前应当将《海洋渔业捕捞许可证》交回原发证机关暂存，在实施远洋渔业项目期间禁止在我国管辖海域从事渔业活动。在终止远洋渔业项目并办妥相关手续后，按《渔业捕捞许可管理规定》从原发证机构领回《海洋渔业捕捞许可证》后，方可在国内海域从事渔业生产。"},{"i":25,"n":"第二十五条","txt":"远洋渔船应当按照规定填写渔捞日志，并接受渔业行政主管部门的监督检查。"},{"i":26,"n":"第二十六条","txt":"远洋渔船应当按规定配备与管理船员。 远洋渔业船员应当按规定接受培训，经考试或考核合格取得相应的渔业船员证书后才能上岗，并持有海员证或护照等本人有效出入境证件。外籍、港澳台船员的管理按照国家有关规定执行。 远洋渔业船员、远洋渔业企业及项目负责人和经营管理人员应当学习国际渔业法律法规、安全生产和涉外知识，参加渔业行政主管部门或其委托机构组织的培训。"},{"i":27,"n":"第二十七条","txt":"远洋渔业企业承担安全生产主体责任，应当按规定设置安全生产管理机构或配备安全生产管理人员，建立安全生产责任制。 远洋渔业企业的法定代表人和主要负责人，对本企业的安全生产工作全面负责；远洋渔业项目负责人，对项目的执行、生产经营管理、渔船活动和船员负监管责任；远洋渔船船长对渔船海上航行、生产作业和锚泊安全等负直接责任。"},{"i":28,"n":"第二十八条","txt":"远洋渔业企业应当与其聘用的远洋渔业船员或远洋渔业船员所在单位直接签订合同，为远洋渔业船员办理有关保险，按时发放工资，保障远洋渔业船员的合法权益，不得向远洋渔业船员收取不合理费用。 远洋渔业企业不得聘用未取得有效渔业船员证书的人员作为远洋渔业船员，聘用的远洋渔业船员不得超过农业农村部远洋渔业项目批准文件核定的船员数。"},{"i":29,"n":"第二十九条","txt":"远洋渔业企业应当在远洋渔业船员出境前对其进行安全生产、外事纪律和法律知识等培训教育。 远洋渔业船员在境外应当遵守所在国法律、法规和有关国际条约、协定的规定，尊重当地的风俗习惯。"},{"i":30,"n":"第三十条","txt":"远洋渔船船长应当认真履行《渔业船员管理办法》规定的有关职责，确保渔船正常航行和依法进行渔业生产，严禁违法进入他国管辖水域生产。 按照我国加入的国际公约或区域渔业组织要求，远洋渔船在公海或他国管辖水域被要求登临检查时，船长应当核实执法船舶及人员身份，配合经授权的执法人员对渔船实施登临检查。禁止逃避执法检查或以暴力、危险等方法抗拒执法检查。"},{"i":31,"n":"第三十一条","txt":"到公海作业的远洋渔船，应当按照农业农村部远洋渔业项目批准文件和《公海渔业捕捞许可证》限定的作业海域、类型、时限、品种和配额作业，遵守我国缔结或者参加的国际条约、协定。 到他国管辖海域作业的远洋渔船，应当遵守我国与该国签订的渔业协议及该国的法律法规。 远洋渔船作业时应当与未授权作业海域外部界限保持安全的缓冲距离，避免赴有关国家争议海域作业。"},{"i":32,"n":"第三十二条","txt":"远洋渔船在通过他国管辖水域前，应妥善保存渔获、捆绑覆盖渔具，并按有关规定提前通报。通过他国管辖水域时，应保持连续和匀速航行，填写航行日志，禁止从事捕捞、渔获物转运、补给等任何渔业生产活动。 渔船在他国港口内或通过他国管辖海域时，不得丢弃船上渔获物或其他杂物，不得排放油污、污水及从事其他损坏海洋生态环境的行为。"},{"i":33,"n":"第三十三条","txt":"禁止远洋渔业企业、渔船和船员从事、支持或协助非法、不报告和不受管制的渔业活动。"},{"i":34,"n":"第三十四条","txt":"农业农村部发布远洋渔业从业人员“黑名单”。存在严重违法违规行为、对重大安全生产责任事故负主要责任和引发远洋渔业涉外违规事件的企业主要管理人员、项目负责人和船长，纳入远洋渔业从业人员“黑名单”管理。 纳入远洋渔业从业人员“黑名单”的企业主要管理人员、项目负责人，3年内不得在远洋渔业企业担任主要管理人员或项目负责人。纳入远洋渔业从业人员“黑名单”的船长自被吊销职务船员证书之日起，5年内不得申请渔业船员证书。"},{"i":35,"n":"第三十五条","txt":"农业农村部根据管理需要对远洋渔船进行船位和渔获情况监测。远洋渔船应当根据农业农村部制定的监测计划安装渔船监测系统（VMS），并配备持有技术培训合格证的船员，保障系统正常工作，及时、准确提供真实信息。 农业农村部可根据有关国际组织的要求或管理需要向远洋渔船派遣国家观察员。远洋渔业企业和远洋渔船有义务接纳国家观察员或有关国际渔业组织派遣的观察员，协助并配合观察员工作，不得安排观察员从事与其职责无关的工作。"},{"i":36,"n":"第三十六条","txt":"两个以上远洋渔业企业在同一国家（地区）或海域作业，或从事同品种、同类型作业，应当建立企业自我协调和自律机制，接受行业协会的指导，配合政府有关部门进行协调和管理。"},{"i":37,"n":"第三十七条","txt":"远洋渔业企业、渔船和船员在国外发生涉外事件时，应当立即如实向农业农村部、企业所在地省级人民政府渔业行政主管部门和有关驻外使（领）馆报告，省级人民政府渔业行政主管部门接到报告后，应当立即核实情况，并提出处理意见报农业农村部和本省级人民政府，由农业农村部协调提出处理意见通知驻外使领馆。发生重大涉外事件需要对外交涉的，由农业农村部商外交部提出处理意见，进行交涉。 远洋渔船发生海难等海上安全事故时，远洋渔业企业应当立即组织自救互救，并按规定向农业农村部、企业所在地省级人民政府渔业行政主管部门报告。需要紧急救助的，按照有关国际规则和国家规定执行。发生违法犯罪事件时，远洋渔业企业应当立即向所在地公安机关和边防部门报告，做好伤员救治、嫌疑人控制、现场保护等工作。 远洋渔业企业和所在地各级人民政府渔业行政主管部门应当认真负责、迅速、妥善处理涉外和海上安全事件。"},{"i":38,"n":"第三十八条","txt":"各级人民政府渔业行政主管部门及其所属的渔政渔港监督机构应当会同有关部门，加强远洋渔船在国内渔业港口的监督与管理，严格执行渔船进出渔港报告制度。 除因人员病急、机件故障、遇难、避风等特殊情况外，禁止被有关国际渔业组织纳入非法、不报告和不受管制渔业活动名单的船舶进入我国港口。因人员病急、机件故障、遇难、避风等特殊情况或非法进入我国港口的，由港口所在地省级人民政府渔业行政主管部门应当会同同级港口、海关、边防等部门，在农业农村部、外交部等国务院有关部门指导下，依据我国法律、行政规定及我国批准或加入的相关国际条约，进行调查处理。"},{"i":39,"n":"第三十九条","txt":"远洋渔业企业、渔船或船员发生下列违法行为的，由省级以上人民政府渔业行政主管部门或其所属的渔政渔港监督管理机构根据《中华人民共和国渔业法》《中华人民共和国野生动物保护法》和有关法律、法规予以处罚。对已经取得农业农村部远洋渔业企业资格的企业，农业农村部视情节轻重和影响大小，暂停或取消其远洋渔业企业资格。 （一）未经农业农村部批准擅自从事远洋渔业生产，或未取得《公海渔业捕捞许可证》从事公海捕捞生产的； （二）申报或实施远洋渔业项目时隐瞒真相、弄虚作假的； （三）不按农业农村部批准的或《公海渔业捕捞许可证》规定的作业类型、场所、时限、品种和配额生产，或未经批准进入他国管辖水域作业的； （四）使用入渔国或有管辖权的区域渔业管理组织禁用的渔具、渔法进行捕捞，或捕捞入渔国或有管辖权的区域渔业管理组织禁止捕捞的鱼种、珍贵濒危水生野生动物或其他海洋生物的； （五）未取得有效的船舶证书，或不符合远洋渔船的"},{"i":40,"n":"第四十条","txt":"被暂停农业农村部远洋渔业企业资格的企业，整改后经省级人民政府渔业行政主管部门和农业农村部审查合格的，可恢复其远洋渔业企业资格和所属渔船远洋渔业项目。1年内经整改仍不合格的，取消其农业农村部远洋渔业企业资格。"},{"i":41,"n":"第四十一条","txt":"当事人对渔业行政处罚有异议的，可按《中华人民共和国行政复议法》和《中华人民共和国行政诉讼法》的有关规定申请行政复议或提起行政诉讼。"},{"i":42,"n":"第四十二条","txt":"各级人民政府渔业行政主管部门工作人员有不履行法定义务、玩忽职守、徇私舞弊等行为，尚不构成犯罪的，由所在单位或上级主管机关予以行政处分。"},{"i":43,"n":"第四十三条","txt":"本规定所称远洋渔船是指中华人民共和国公民、法人或其他组织所有并从事远洋渔业活动的渔业船舶，包括捕捞渔船和渔业辅助船。远洋渔业船员是指在远洋渔船上工作的所有船员，包括职务船员。 本规定所称省级人民政府渔业行政主管部门包括计划单列市人民政府渔业行政主管部门。"},{"i":44,"n":"第四十四条","txt":"本规定自2020年4月1日起施行。农业部2003年4月18日发布、2004年7月1日修正、2016年5月30日修正的《远洋渔业管理规定》同时废止。 　　附表：一、申请远洋渔业项目基本情况表 　　　　　二、公海渔业捕捞许可证申请书 　　　　　三、农业农村部远洋渔业企业资格和项目年审登记表 附表一 申请远洋渔业项目基本情况表 注：渔船和人员情况表格不够用时可另加副页。 附表二 申请书受理编号： 公海渔业捕捞许可证申请书 注：申请书每船填写一份。申请书受理编号由受理申请的省级渔业行政主管部门填写。 附表三 农业农村部远洋渔业企业资格和项目年审登记表 （总表 — 附项目表共 页） 附表三（续） 农业农村部远洋渔业企业资格和项目年审登记表 （项目表） 注：1、每个项目填报一表；2、派出渔船情况表格不够用时可另加副页。"}],"changjiangshuishengshengwubaohuguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强长江流域水生生物保护和管理，维护生物多样性，保障流域生态安全，根据《中华人民共和国长江保护法》《中华人民共和国渔业法》《中华人民共和国野生动物保护法》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"长江流域水生生物及其栖息地的监测调查、保护修复、捕捞利用等活动及其监督管理，适用本规定。 本规定所称长江流域，是指由长江干流、支流和湖泊形成的集水区域所涉及的青海省、四川省、西藏自治区、云南省、重庆市、湖北省、湖南省、江西省、安徽省、江苏省、上海市，以及甘肃省、陕西省、河南省、贵州省、广西壮族自治区、广东省、浙江省、福建省的相关县级行政区域。"},{"i":3,"n":"第三条","txt":"长江流域水生生物保护和管理应当坚持统筹协调、科学规划，实行自然恢复为主、自然恢复与人工修复相结合的系统治理。"},{"i":4,"n":"第四条","txt":"农业农村部主管长江流域水生生物保护和管理工作。 农业农村部成立长江水生生物科学委员会，对长江水生生物保护和管理的重大政策、规划、措施等，开展专业咨询和评估论证。 长江流域县级以上地方人民政府农业农村主管部门负责本行政区域水生生物保护和管理工作。"},{"i":5,"n":"第五条","txt":"长江流域县级以上地方人民政府农业农村主管部门应当按规定统筹使用相关生态补偿资金，加强水生生物及其栖息地的保护修复、宣传教育和科普培训。 支持单位和个人参与长江流域水生生物及其栖息地保护，鼓励对破坏水生生物资源和水域生态环境的行为进行监督举报。"},{"i":6,"n":"第六条","txt":"对在长江水生生物保护管理工作中作出突出贡献的单位或个人，按照有关规定予以表彰和奖励。 农业农村部和长江流域省级人民政府农业农村主管部门对长江水生生物保护管理工作不力、问题突出、群众反映集中的地区，依法约谈所在地县级以上地方人民政府及其有关部门主要负责人，要求其采取措施及时整改。"},{"i":7,"n":"第七条","txt":"农业农村部制定长江水生生物及其栖息地调查监测的技术标准和程序规范，健全长江流域水生生物监测网络体系，建立调查监测信息共享平台。 长江流域省级人民政府农业农村主管部门应当定期对本行政区域内的水生生物分布区域、种群数量、结构及栖息地生态状况等开展调查监测，并及时将调查监测信息报农业农村部。"},{"i":8,"n":"第八条","txt":"农业农村部每十年组织一次长江水生野生动物及其栖息地状况普查，根据需要组织开展专项调查，建立水生野生动物资源档案，并向社会公布长江流域水生野生动物资源状况。"},{"i":9,"n":"第九条","txt":"对中华鲟、长江鲟、长江江豚等国家一级保护水生野生动物及其栖息地的专项调查监测，由农业农村部组织实施；其他重点保护水生野生动物及其栖息地的专项调查监测，由长江流域省级人民政府农业农村主管部门组织实施。"},{"i":10,"n":"第十条","txt":"长江流域县级以上地方人民政府农业农村主管部门会同本级人民政府有关部门定期对水生生物产卵场、索饵场、越冬场和洄游通道等重要栖息地开展生物多样性调查。"},{"i":11,"n":"第十一条","txt":"因科研、教学、环境影响评价等需要在禁渔期、禁渔区进行捕捞的，应当制定年度捕捞计划，并按规定申请专项（特许）渔业捕捞许可证；确需使用禁用渔具渔法的，长江流域省级人民政府农业农村主管部门应当组织论证。 在禁渔期、禁渔区开展调查监测的渔获物，不得进行市场交易或抵扣费用。"},{"i":12,"n":"第十二条","txt":"发生渔业水域污染、外来物种入侵等事件，对长江流域水生生物及其栖息地造成或可能造成严重损害的，发生地或受损地的地方人民政府农业农村主管部门应当及时开展应急调查、预警监测和评估，并按有关规定向同级人民政府或上级农业农村主管部门报告。"},{"i":13,"n":"第十三条","txt":"农业农村部会同国务院有关部门和长江流域省级人民政府建立长江流域水生生物完整性指数评价体系，组织开展评价工作，并将结果作为评估长江流域生态系统总体状况和水生生物保护责任落实情况的重要依据。长江流域水生生物完整性指数应当与长江流域水环境质量标准相衔接。 长江流域省级人民政府农业农村主管部门应当根据长江流域水生生物完整性指数评价体系，结合实际开展水生生物完整性指数评价工作。"},{"i":14,"n":"第十四条","txt":"农业农村部制定长江流域珍贵、濒危水生野生动植物保护计划，对长江流域珍贵、濒危水生野生动植物实行重点保护。 鼓励有条件的单位开展对长江流域江豚、白鱀豚、白鲟、中华鲟、长江鲟、鯮、鲥、四川白甲鱼、川陕哲罗鲑、胭脂鱼、鳤、圆口铜鱼、多鳞白甲鱼、华鲮、鲈鲤和葛仙米、弧形藻、眼子菜、水菜花等水生野生动植物生境特征和种群动态的研究，建设人工繁育和科普教育基地。"},{"i":15,"n":"第十五条","txt":"长江流域省级人民政府农业农村主管部门和农业农村部根据长江流域水生生物及其产卵场、索饵场、越冬场和洄游通道等栖息地状况的调查、监测和评估结果，发布水生生物重要栖息地名录及其范围，明确保护措施，实行严格的保护和管理。 对长江流域数量急剧下降或者极度濒危的水生野生动植物和受到严重破坏的栖息地、天然集中分布区、破碎化的典型生态系统，长江流域省级人民政府农业农村主管部门和农业农村部应当制定修复方案和行动计划，修建迁地保护设施，建立水生野生动植物遗传资源基因库，进行抢救性修复。"},{"i":16,"n":"第十六条","txt":"在长江流域水生生物重要栖息地应当实施生态环境修复和其他保护措施。 对鱼类等水生生物洄游或种质交流产生阻隔的涉水工程，建设或运行单位应当结合实际采取建设过鱼设施、河湖连通、生态调度、灌江纳苗、基因保存、增殖放流、人工繁育等多种措施，充分满足水生生物洄游、繁殖、种质交流等生态需求。"},{"i":17,"n":"第十七条","txt":"在长江流域水生生物重要栖息地依法科学划定限制航行区和禁止航行区域。 因国家发展战略和国计民生需要，在水生生物重要栖息地禁止航行区域内设置航道或进行临时航行的，应当依法征得农业农村部同意，并采取降速、降噪、限排、限鸣等必要措施，减少对重要水生生物的干扰。 严格限制在长江流域水生生物重要栖息地水域实施航道整治工程；确需整治的，应当经科学论证，并依法办理相关手续。"},{"i":18,"n":"第十八条","txt":"长江流域涉水开发规划或建设项目应当充分考虑水生生物及其栖息地的保护需求，涉及或可能对其造成影响的，建设单位在编制环境影响评价文件和开展公众参与调查时，应当书面征求农业农村主管部门的意见，并按有关要求进行专题论证。 涉及珍贵、濒危水生野生动植物及其重要栖息地、水产种质资源保护区的，由长江流域省级人民政府农业农村主管部门组织专题论证；涉及国家一级重点保护水生野生动植物及其重要栖息地或国家级水产种质资源保护区的，由农业农村部组织专题论证。"},{"i":19,"n":"第十九条","txt":"建设项目对水生生物及其栖息地造成不利影响的，建设单位应当编制专题报告，根据批准的环境影响评价文件及批复要求，落实避让、减缓、补偿、重建等措施，与主体工程同时设计、同时施工、同时投产使用，并在稳定运行一定时期后对其有效性进行周期性监测和回顾性评价，提出补救方案或者改进措施。 建设项目所在地县级以上地方人民政府农业农村主管部门应当对生态补偿措施的实施进展和落实效果进行跟踪监督。"},{"i":20,"n":"第二十条","txt":"长江流域省级人民政府农业农村主管部门和农业农村部建立中华鲟、长江鲟、长江江豚等重点保护水生野生动植物的应急救护体系。 重点保护水生野生动植物的野外物种或人工保种物种生存安全受到威胁的，所在地县级以上人民政府农业农村主管部门应当及时开展应急救护，并根据物种特性和受威胁程度，落实就地保护、迁地保护或种质资源保护等措施。"},{"i":21,"n":"第二十一条","txt":"长江流域县级以上地方人民政府农业农村主管部门应当根据农业农村部制定的水生生物增殖放流规划、计划或意见，制定本行政区域的增殖放流方案，并报上一级农业农村主管部门备案。长江流域省级农业农村主管部门应当制定中华鲟、长江鲟等国家一级重点保护水生野生动物的增殖放流年度计划并报农业农村部备案。 长江流域县级以上地方人民政府农业农村主管部门负责本行政区域内的水生生物增殖放流的组织、协调与监督管理，并采取措施加强增殖资源保护、跟踪监测和效果评估。"},{"i":22,"n":"第二十二条","txt":"禁止在长江流域开放水域养殖、投放外来物种或者其他非本地物种。 养殖外来物种或其他非本地物种的，应当采取有效隔离措施，防止逃逸进入开放水域。 发生外来物种或者其他非本地物种逃逸的，有关单位和个人应当采取捕回或其他紧急补救措施降低负面影响，并及时向所在地人民政府农业农村主管部门报告。"},{"i":23,"n":"第二十三条","txt":"长江流域水生生物保护区禁止生产性捕捞。在国家规定的期限内，长江干流和重要支流、大型通江湖泊、长江口禁捕管理区等重点水域禁止天然渔业资源的生产性捕捞。农业农村部根据长江流域水生生物资源状况，对长江流域重点水域禁捕管理制度进行适应性调整。 长江流域其他水域禁捕、限捕管理办法由县级以上地方人民政府制定。"},{"i":24,"n":"第二十四条","txt":"农业农村部和长江流域省级人民政府农业农村主管部门制定并发布长江流域重点水域禁用渔具渔法目录。 禁止在禁渔期携带禁用渔具进入禁渔区。"},{"i":25,"n":"第二十五条","txt":"禁止在长江流域以水生生物为主要保护对象的自然保护区、水产种质资源保护区核心区和水生生物重要栖息地垂钓。 倡导正确、健康、文明的休闲垂钓行为，禁止一人多杆、多线多钩、钓获物买卖等违规垂钓行为。"},{"i":26,"n":"第二十六条","txt":"因人工繁育、维持生态系统平衡或者特定物种种群调控等特殊原因，需要在禁渔期、禁渔区捕捞天然渔业资源的，应当按照《渔业捕捞许可管理规定》申请专项（特许）渔业捕捞许可证，并严格按照许可的技术标准、规范要求进行作业，严禁擅自更改作业范围、时间和捕捞工具、方法等。 县级以上地方人民政府农业农村主管部门应当加强对专项（特许）渔业捕捞行为的监督和管理。"},{"i":27,"n":"第二十七条","txt":"在长江流域发展大水面生态渔业应当科学规划，按照“一水一策”原则合理选择大水面生态渔业发展方式。开展增殖渔业的，按照水域承载力确定适宜的增殖种类、增殖数量、增殖方式、放捕比例和起捕时间、方式、规格、数量等。 严格区分增殖渔业的起捕活动与传统的非增殖渔业资源捕捞生产，增殖渔业起捕应当使用专门的渔具渔法，避免对非增殖渔业资源和重点保护水生野生动植物造成损害。"},{"i":28,"n":"第二十八条","txt":"长江流域县级以上地方人民政府农业农村主管部门应当加强执法队伍建设，落实执法经费，配备执法力量，组建协助巡护队伍，加强网格化管理，开展动态巡航巡查。"},{"i":29,"n":"第二十九条","txt":"长江流域县级以上地方人民政府农业农村主管部门应当加强长江流域禁捕执法工作，严厉打击电鱼、毒鱼、炸鱼及使用禁用渔具等非法捕捞行为，并会同有关部门按照职责分工依法查处收购、运输、加工、销售非法渔获物等违法违规行为；涉嫌构成犯罪的，应当依法移送公安机关查处。"},{"i":30,"n":"第三十条","txt":"违反本规定，在长江流域重点水域进行增殖放流、垂钓或者在禁渔期携带禁用渔具进入禁渔区的，责令改正，可以处警告或一千元以下罚款；构成其他违法行为的，按照《中华人民共和国长江保护法》《中华人民共和国渔业法》等法律或者行政法规予以处罚。"},{"i":31,"n":"第三十一条","txt":"本规定下列用语的含义是： （一）重点水域是指长江干流和重要支流、大型通江湖泊、长江河口规定区域等水域。 （二）水生生物保护区是指以水生生物为主要保护对象的自然保护区、水产种质资源保护区。 （三）重要栖息地是指水生生物野外种群的产卵场、索饵场、越冬场和洄游通道。 （四）开放水域是指水生生物通过水的自然流通能够到达长江流域重点水域的水域。"},{"i":32,"n":"第三十二条","txt":"本规定自2022年2月1日起施行。原农业部1995年9月28日发布、2004年7月1日修订的《长江渔业资源管理规定》同时废止。"}],"feizhuyaonongzuowupinzhongdengjibanfa":[{"i":1,"n":"第一条","txt":"为了规范非主要农作物品种管理，科学、公正、及时地登记非主要农作物品种，根据《中华人民共和国种子法》(以下简称《种子法》)，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内的非主要农作物品种登记，适用本办法。 法律、行政法规和农业农村部规章对非主要农作物品种管理另有规定的，依照其规定。"},{"i":3,"n":"第三条","txt":"本办法所称非主要农作物，是指稻、小麦、玉米、棉花、大豆五种主要农作物以外的其他农作物。"},{"i":4,"n":"第四条","txt":"列入非主要农作物登记目录的品种，在推广前应当登记。 应当登记的农作物品种未经登记的，不得发布广告、推广，不得以登记品种的名义销售。"},{"i":5,"n":"第五条","txt":"农业农村部主管全国非主要农作物品种登记工作，制定、调整非主要农作物登记目录和品种登记指南，建立全国非主要农作物品种登记信息平台（以下简称品种登记平台），具体工作由全国农业技术推广服务中心承担。"},{"i":6,"n":"第六条","txt":"省级人民政府农业农村主管部门负责品种登记的具体实施和监督管理，受理品种登记申请，对申请者提交的申请文件进行书面审查。 省级以上人民政府农业农村主管部门应当采取有效措施，加强对已登记品种的监督检查，履行好对申请者和品种测试、试验机构的监管责任，保证消费安全和用种安全。"},{"i":7,"n":"第七条","txt":"申请者申请品种登记，应当对申请文件和种子样品的合法性、真实性负责，保证可追溯，接受监督检查。给种子使用者和其他种子生产经营者造成损失的，依法承担赔偿责任。"},{"i":8,"n":"第八条","txt":"品种登记申请实行属地管理。一个品种只需要在一个省份申请登记。"},{"i":9,"n":"第九条","txt":"两个以上申请者分别就同一个品种申请品种登记的，优先受理最先提出的申请；同时申请的，优先受理该品种育种者的申请。"},{"i":10,"n":"第十条","txt":"申请者应当在品种登记平台上实名注册，可以通过品种登记平台提出登记申请，也可以向住所地的省级人民政府农业农村主管部门提出书面登记申请。"},{"i":11,"n":"第十一条","txt":"在中国境内没有经常居所或者营业场所的境外机构、个人在境内申请品种登记的，应当委托具有法人资格的境内种子企业代理。"},{"i":12,"n":"第十二条","txt":"申请登记的品种应当具备下列条件： （一）人工选育或发现并经过改良； （二）具备特异性、一致性、稳定性； （三）具有符合《农业植物品种命名规定》的品种名称。 申请登记具有植物新品种权的品种，还应当经过品种权人的书面同意。"},{"i":13,"n":"第十三条","txt":"对新培育的品种，申请者应当按照品种登记指南的要求提交以下材料： （一）申请表； （二）品种特性、育种过程等的说明材料； （三）特异性、一致性、稳定性测试报告，已具备DNA指纹检测行业技术标准的作物还应当提交品种DNA指纹检测报告； （四）种子、植株及果实等实物彩色照片； （五）品种权人的书面同意材料； （六）品种和申请材料合法性、真实性承诺书。"},{"i":14,"n":"第十四条","txt":"本办法实施前已审定或者已销售种植的品种，申请者可以按照品种登记指南的要求，提交申请表，已具备DNA指纹检测行业技术标准的作物还应当提交品种DNA指纹检测报告，已销售种植的品种还应当提供本办法实施前的品种销售发票。"},{"i":15,"n":"第十五条","txt":"省级人民政府农业农村主管部门对申请者提交的材料，应当根据下列情况分别作出处理： （一）申请品种不需要品种登记的，即时告知申请者不予受理； （二）申请材料存在错误的，允许申请者当场更正； （三）申请材料不齐全或者不符合法定形式的，应当当场或者在五个工作日内一次告知申请者需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （四）申请材料齐全、符合法定形式，或者申请者按照要求提交全部补正材料的，予以受理。"},{"i":16,"n":"第十六条","txt":"省级人民政府农业农村主管部门自受理品种登记申请之日起二十个工作日内，对申请者提交的申请材料进行书面审查，符合要求的，将审查意见报农业农村部，并通知申请者提交种子样品。经审查不符合要求的，书面通知申请者并说明理由。 申请品种登记的，应当按照品种登记指南要求提交种子样品；未按要求提供的，视为撤回申请。"},{"i":17,"n":"第十七条","txt":"省级人民政府农业农村主管部门在二十个工作日内不能作出审查决定的，经本部门负责人批准，可以延长十个工作日，并将延长期限理由告知申请者。"},{"i":18,"n":"第十八条","txt":"农业农村部自收到省级人民政府农业农村主管部门的审查意见之日起二十个工作日内进行复核。对符合规定并按规定完成种子样品入库的进行公示，公示期十五个工作日，公示无异议或异议不成立的，予以登记，颁发登记证书；不予登记的，通知申请者并说明理由。"},{"i":19,"n":"第十九条","txt":"登记证书内容包括：登记编号、作物种类、品种名称、申请者、育种者、品种来源、适宜种植区域及季节等。"},{"i":20,"n":"第二十条","txt":"农业农村部将品种登记信息进行公告，公告内容包括：登记编号、作物种类、品种名称、申请者、育种者、品种来源、特征特性、品质、抗性、产量、栽培技术要点、适宜种植区域及季节等。 登记编号格式为：GPD +作物种类+(年号)+ 2位数字的省份代号+ 4位数字顺序号。"},{"i":21,"n":"第二十一条","txt":"登记证书载明的品种名称为该品种的通用名称，禁止在生产、销售、推广过程中擅自更改。"},{"i":22,"n":"第二十二条","txt":"已登记品种，申请者要求变更登记内容的，应当向原受理的省级人民政府农业农村主管部门提出变更申请，并提交相关证明材料。 原受理的省级人民政府农业农村主管部门对申请者提交的材料进行书面审查，符合要求的，报农业农村部予以变更并公告，不再提交种子样品。 登记品种变更事项限于品种适宜种植区域，以及相关的栽培技术要点、注意事项等内容。"},{"i":23,"n":"第二十三条","txt":"农业农村部推进品种登记平台建设，逐步实行网上办理登记申请与受理，在统一的政府信息发布平台上发布品种登记、变更、撤销、监督管理等信息。"},{"i":24,"n":"第二十四条","txt":"农业农村部对省级人民政府农业农村主管部门开展品种登记工作情况进行监督检查，及时纠正违法行为，责令限期改正，对有关责任人员依法给予处分。"},{"i":25,"n":"第二十五条","txt":"省级人民政府农业农村主管部门发现已登记品种存在申请文件、种子样品不实，或者已登记品种出现不可克服的严重缺陷等情形的，应当向农业农村部提出撤销该品种登记的意见。 农业农村部撤销品种登记的，进行十五个工作日的公示，公示无异议或异议不成立的，发布撤销公告，相应品种停止推广；对于登记品种申请文件、种子样品不实的，按照规定将申请者的违法信息记入社会诚信档案，向社会公布。"},{"i":26,"n":"第二十六条","txt":"申请者在申请品种登记过程中有欺骗、贿赂等不正当行为的，三年内不受理其申请。"},{"i":27,"n":"第二十七条","txt":"品种测试、试验机构伪造测试、试验数据或者出具虚假证明的，省级人民政府农业农村主管部门应当依照《种子法》第七十二条规定，责令改正，对单位处五万元以上十万元以下罚款，对直接负责的主管人员和其他直接责任人员处一万元以上五万元以下罚款；有违法所得的，并处没收违法所得；给种子使用者和其他种子生产经营者造成损失的，与种子生产经营者承担连带责任。情节严重的，依法取消品种测试、试验资格。"},{"i":28,"n":"第二十八条","txt":"有下列行为之一的，由县级以上人民政府农业农村主管部门依照《种子法》第七十八条规定，责令停止违法行为，没收违法所得和种子，并处二万元以上二十万元以下罚款： （一）对应当登记未经登记的农作物品种进行推广，或者以登记品种的名义进行销售的； （二）对已撤销登记的农作物品种进行推广，或者以登记品种的名义进行销售的。"},{"i":29,"n":"第二十九条","txt":"品种登记工作人员应当忠于职守，公正廉洁，对在登记过程中获知的申请者的商业秘密负有保密义务，不得擅自对外提供登记品种的种子样品或者谋取非法利益。不依法履行职责，弄虚作假、徇私舞弊的，依法给予处分；自处分决定作出之日起五年内不得从事品种登记工作。"},{"i":30,"n":"第三十条","txt":"品种适应性、抗性鉴定以及特异性、一致性、稳定性测试，申请者可以自行开展，也可以委托其他机构开展。"},{"i":31,"n":"第三十一条","txt":"本办法自2017年5月1日起施行。"}],"shiyongjunjunzhongguanlibanfa":[{"i":1,"n":"第一条","txt":"为保护和合理利用食用菌种质资源，规范食用菌品种选育及食用菌菌种（以下简称菌种）的生产、经营、使用和管理，根据《中华人民共和国种子法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事食用菌品种选育和菌种生产、经营、使用、管理等活动，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称菌种是指食用菌菌丝体及其生长基质组成的繁殖材料。 菌种分为母种（一级种）、原种（二级种）和栽培种（三级种）三级。"},{"i":4,"n":"第四条","txt":"农业部主管全国菌种工作。县级以上地方人民政府农业（食用菌，下同）行政主管部门负责本行政区域内的菌种管理工作。"},{"i":5,"n":"第五条","txt":"县级以上地方人民政府农业行政主管部门应当加强食用菌种质资源保护和良种选育、生产、更新、推广工作，鼓励选育、生产、经营相结合。"},{"i":6,"n":"第六条","txt":"国家保护食用菌种质资源，任何单位和个人不得侵占和破坏。"},{"i":7,"n":"第七条","txt":"禁止采集国家重点保护的天然食用菌种质资源。确因科研等特殊情况需要采集的，应当依法申请办理采集手续。"},{"i":8,"n":"第八条","txt":"任何单位和个人向境外提供食用菌种质资源（包括长有菌丝体的栽培基质及用于菌种分离的子实体），应当报农业部批准。"},{"i":9,"n":"第九条","txt":"从境外引进菌种，应当依法检疫，并在引进后30日内，送适量菌种至中国农业微生物菌种保藏管理中心保存。"},{"i":10,"n":"第十条","txt":"国家鼓励和支持单位和个人从事食用菌品种选育和开发，鼓励科研单位与企业相结合选育新品种，引导企业投资选育新品种。 选育的新品种可以依法申请植物新品种权，国家保护品种权人的合法权益。"},{"i":11,"n":"第十一条","txt":"食用菌品种选育（引进）者可自愿向全国农业技术推广服务中心申请品种认定。全国农业技术推广服务中心成立食用菌品种认定委员会，承担品种认定的技术鉴定工作。"},{"i":12,"n":"第十二条","txt":"食用菌品种名称应当规范。具体命名规则由农业部另行规定。"},{"i":13,"n":"第十三条","txt":"从事菌种生产经营的单位和个人，应当取得《食用菌菌种生产经营许可证》。 仅从事栽培种经营的单位和个人，可以不办理《食用菌菌种生产经营许可证》，但经营者要具备菌种的相关知识，具有相应的菌种贮藏设备和场所，并报县级人民政府农业行政主管部门备案。"},{"i":14,"n":"第十四条","txt":"母种和原种《食用菌菌种生产经营许可证》，由所在地县级人民政府农业行政主管部门审核，省级人民政府农业行政主管部门核发，报农业部备案。 栽培种《食用菌菌种生产经营许可证》由所在地县级人民政府农业行政主管部门核发，报省级人民政府农业行政主管部门备案。"},{"i":15,"n":"第十五条","txt":"申请母种和原种《食用菌菌种生产经营许可证》的单位和个人，应当具备下列条件： （一）生产经营母种注册资本100万元以上，生产经营原种注册资本50万元以上； （二）省级人民政府农业行政主管部门考核合格的检验人员1名以上、生产技术人员2名以上； （三）有相应的灭菌、接种、培养、贮存等设备和场所，有相应的质量检验仪器和设施。生产母种还应当有做出菇试验所需的设备和场所。 （四）生产场地环境卫生及其他条件符合农业部《食用菌菌种生产技术规程》要求。"},{"i":16,"n":"第十六条","txt":"申请栽培种《食用菌菌种生产经营许可证》的单位和个人，应当具备下列条件： （一）注册资本10万元以上； （二）省级人民政府农业行政主管部门考核合格的检验人员1名以上、生产技术人员1名以上； （三）有必要的灭菌、接种、培养、贮存等设备和场所，有必要的质量检验仪器和设施； （四）栽培种生产场地的环境卫生及其他条件符合农业部《食用菌菌种生产技术规程》要求。"},{"i":17,"n":"第十七条","txt":"申请《食用菌菌种生产经营许可证》，应当向县级人民政府农业行政主管部门提交下列材料： （一）食用菌菌种生产经营许可证申请表； （二）营业执照复印件； （三）菌种检验人员、生产技术人员资格证明； （四）仪器设备和设施清单及产权证明，主要仪器设备的照片； （五）菌种生产经营场所照片及产权证明； （六）品种特性介绍； （七）菌种生产经营质量保证制度。 申请母种生产经营许可证的品种为授权品种的，还应当提供品种权人（品种选育人）授权的书面证明。"},{"i":18,"n":"第十八条","txt":"县级人民政府农业行政主管部门受理母种和原种的生产经营许可申请后，可以组织专家进行实地考查，但应当自受理申请之日起20日内签署审核意见，并报省级人民政府农业行政主管部门审批。省级人民政府农业行政主管部门应当自收到审核意见之日起20日内完成审批。符合条件的，发给生产经营许可证；不符合条件的，书面通知申请人并说明理由。 县级人民政府农业行政主管部门受理栽培种生产经营许可申请后，可以组织专家进行实地考查，但应当自受理申请之日起20日内完成审批。符合条件的，发给生产经营许可证；不符合条件的，书面通知申请人并说明理由。"},{"i":19,"n":"第十九条","txt":"菌种生产经营许可证有效期为3年。有效期满后需继续生产经营的，被许可人应当在有效期满2个月前，持原证按原申请程序重新办理许可证。 在菌种生产经营许可证有效期内，许可证注明项目变更的，被许可人应当向原审批机关办理变更手续，并提供相应证明材料。"},{"i":20,"n":"第二十条","txt":"菌种按级别生产，下一级菌种只能用上一级菌种生产，栽培种不得再用于扩繁菌种。 获得上级菌种生产经营许可证的单位和个人，可以从事下级菌种的生产经营。"},{"i":21,"n":"第二十一条","txt":"禁止无证或者未按许可证的规定生产经营菌种；禁止伪造、涂改、买卖、租借《食用菌菌种生产经营许可证》。"},{"i":22,"n":"第二十二条","txt":"菌种生产单位和个人应当按照农业部《食用菌菌种生产技术规程》生产，并建立菌种生产档案，载明生产地点、时间、数量、培养基配方、培养条件、菌种来源、操作人、技术负责人、检验记录、菌种流向等内容。生产档案应当保存至菌种售出后2年。"},{"i":23,"n":"第二十三条","txt":"菌种经营单位和个人应当建立菌种经营档案，载明菌种来源、贮存时间和条件、销售去向、运输、经办人等内容。经营档案应当保存至菌种销售后2年。"},{"i":24,"n":"第二十四条","txt":"销售的菌种应当附有标签和菌种质量合格证。标签应当标注菌种种类、品种、级别、接种日期、保藏条件、保质期、菌种生产经营许可证编号、执行标准及生产者名称、生产地点。标签标注的内容应当与销售菌种相符。 菌种经营者应当向购买者提供菌种的品种种性说明、栽培要点及相关咨询服务，并对菌种质量负责。"},{"i":25,"n":"第二十五条","txt":"农业部负责制定全国菌种质量监督抽查规划和本级监督抽查计划，县级以上地方人民政府农业行政主管部门负责对本行政区域内菌种质量的监督，根据全国规划和当地实际情况制定本级监督抽查计划。 菌种质量监督抽查不得向被抽查者收取费用。禁止重复抽查。"},{"i":26,"n":"第二十六条","txt":"县级以上人民政府农业行政主管部门可以委托菌种质量检验机构对菌种质量进行检验。 承担菌种质量检验的机构应当具备相应的检测条件和能力，并经省级人民政府有关主管部门考核合格。"},{"i":27,"n":"第二十七条","txt":"菌种质量检验机构应当配备菌种检验员。菌种检验员应当具备以下条件： （一）具有相关专业大专以上文化水平或者具有中级以上专业技术职称； （二）从事菌种检验技术工作3年以上； （三）经省级人民政府农业行政主管部门考核合格。"},{"i":28,"n":"第二十八条","txt":"禁止生产、经营假、劣菌种。 有下列情形之一的，为假菌种： （一）以非菌种冒充菌种； （二）菌种种类、品种、级别与标签内容不符的。 有下列情形之一的，为劣菌种： （一）质量低于国家规定的种用标准的； （二）质量低于标签标注指标的； （三）菌种过期、变质的。"},{"i":29,"n":"第二十九条","txt":"从事菌种进出口的单位，除具备菌种生产经营许可证以外，还应当依照国家外贸法律、行政法规的规定取得从事菌种进出口贸易的资格。"},{"i":30,"n":"第三十条","txt":"申请进出口菌种的单位和个人，应当填写《进（出）口菌种审批表》，经省级人民政府农业行政主管部门批准后，依法办理进出口手续。 菌种进出口审批单有效期为3个月。"},{"i":31,"n":"第三十一条","txt":"进出口菌种应当符合下列条件： （一）属于国家允许进出口的菌种质资源； （二）菌种质量达到国家标准或者行业标准； （三）菌种名称、种性、数量、原产地等相关证明真实完备； （四）法律、法规规定的其他条件。"},{"i":32,"n":"第三十二条","txt":"申请进出口菌种的单位和个人应当提交下列材料： （一）《食用菌菌种生产经营许可证》复印件、营业执照副本和进出口贸易资格证明； （二）食用菌品种说明； （三）符合第三十一条规定条件的其他证明材料。"},{"i":33,"n":"第三十三条","txt":"为境外制种进口菌种的，可以不受本办法第二十九条限制，但应当具有对外制种合同。进口的菌种只能用于制种，其产品不得在国内销售。 从境外引进试验用菌种及扩繁得到的菌种不得作为商品菌种出售。"},{"i":34,"n":"第三十四条","txt":"违反本办法规定的行为，依照《中华人民共和国种子法》的有关规定予以处罚。"},{"i":35,"n":"第三十五条","txt":"本办法所称菌种种性是指食用菌品种特性的简称，包括对温度、湿度、酸碱度、光线、氧气等环境条件的要求，抗逆性、丰产性、出菇迟早、出菇潮数、栽培周期、商品质量及栽培习性等农艺性状。"},{"i":36,"n":"第三十六条","txt":"野生食用菌菌种的采集和进出口管理，应当按照《农业野生植物保护办法》的规定，办理相关审批手续。"},{"i":37,"n":"第三十七条","txt":"本办法自2006年6月1日起施行。1996年7月1日农业部发布的《全国食用菌菌种暂行管理办法》（农农发〔1996〕6号）同时废止，依照《全国食用菌菌种暂行管理办法》领取的菌种生产、经营许可证自有效期届满之日起失效。"}],"siliaohesiliaotianjiajishengchanxukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强饲料、饲料添加剂生产许可管理，维护饲料、饲料添加剂生产秩序，保障饲料、饲料添加剂质量安全，根据《饲料和饲料添加剂管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内生产饲料、饲料添加剂，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"饲料和饲料添加剂生产许可证由省级人民政府饲料管理部门（以下简称省级饲料管理部门）核发。 省级饲料管理部门可以委托下级饲料管理部门承担单一饲料、浓缩饲料、配合饲料和精料补充料生产许可申请的受理工作。"},{"i":4,"n":"第四条","txt":"农业农村部设立饲料和饲料添加剂生产许可专家委员会，负责饲料和饲料添加剂生产许可的技术支持工作。 省级饲料管理部门设立饲料和饲料添加剂生产许可证专家审核委员会，负责本行政区域内饲料和饲料添加剂生产许可的技术评审工作。"},{"i":5,"n":"第五条","txt":"任何单位和个人有权举报生产许可过程中的违法行为，农业农村部和省级饲料管理部门应当依照权限核实、处理。"},{"i":6,"n":"第六条","txt":"设立饲料、饲料添加剂生产企业，应当符合饲料工业发展规划和产业政策，并具备下列条件： （一）有与生产饲料、饲料添加剂相适应的厂房、设备和仓储设施； （二）有与生产饲料、饲料添加剂相适应的专职技术人员； （三）有必要的产品质量检验机构、人员、设施和质量管理制度； （四）有符合国家规定的安全、卫生要求的生产环境； （五）有符合国家环境保护要求的污染防治措施； （六）农业农村部制定的饲料、饲料添加剂质量安全管理规范规定的其他条件。"},{"i":7,"n":"第七条","txt":"申请从事饲料、饲料添加剂生产的企业，申请人应当向生产地省级饲料管理部门提出申请。省级饲料管理部门应当自受理申请之日起10个工作日内进行书面审查；审查合格的，组织进行现场审核，并根据审核结果在10个工作日内作出是否核发生产许可证的决定。 生产许可证式样由农业农村部统一规定。"},{"i":8,"n":"第八条","txt":"取得饲料添加剂生产许可证的企业，应当向省级饲料管理部门申请核发产品批准文号。"},{"i":9,"n":"第九条","txt":"饲料、饲料添加剂生产企业委托其他饲料、饲料添加剂企业生产的，应当具备下列条件，并向各自所在地省级饲料管理部门备案： （一）委托产品在双方生产许可范围内；委托生产饲料添加剂的，双方还应当取得委托产品的产品批准文号； （二）签订委托合同，依法明确双方在委托产品生产技术、质量控制等方面的权利和义务。 受托方应当按照饲料、饲料添加剂质量安全管理规范和饲料添加剂安全使用规范及产品标准组织生产，委托方应当对生产全过程进行指导和监督。委托方和受托方对委托生产的饲料、饲料添加剂质量安全承担连带责任。 委托生产的产品标签应当同时标明委托企业和受托企业的名称、注册地址、许可证编号；委托生产饲料添加剂的，还应当标明受托方取得的生产该产品的批准文号。"},{"i":10,"n":"第十条","txt":"生产许可证有效期为5年。 生产许可证有效期满需继续生产的，应当在有效期届满6个月前向省级饲料管理部门提出续展申请，并提交相关材料。"},{"i":11,"n":"第十一条","txt":"饲料、饲料添加剂生产企业有下列情形之一的，应当按照企业设立程序重新办理生产许可证： （一）增加、更换生产线的； （二）增加单一饲料、饲料添加剂产品品种的； （三）生产场所迁址的； （四）农业农村部规定的其他情形。"},{"i":12,"n":"第十二条","txt":"饲料、饲料添加剂生产企业有下列情形之一的，应当在15日内向企业所在地省级饲料管理部门提出变更申请并提交相关证明，由发证机关依法办理变更手续，变更后的生产许可证证号、有效期不变： （一）企业名称变更； （二）企业法定代表人变更； （三）企业注册地址或注册地址名称变更； （四）生产地址名称变更。"},{"i":13,"n":"第十三条","txt":"生产许可证遗失或损毁的，应当在15日内向发证机关申请补发，由发证机关补发生产许可证。"},{"i":14,"n":"第十四条","txt":"饲料、饲料添加剂生产企业应当按照许可条件组织生产。生产条件发生变化，可能影响产品质量安全的，企业应当经所在地县级人民政府饲料管理部门报告发证机关。"},{"i":15,"n":"第十五条","txt":"县级以上人民政府饲料管理部门应当加强对饲料、饲料添加剂生产企业的监督检查，依法查处违法行为，并建立饲料、饲料添加剂监督管理档案，记录日常监督检查、违法行为查处等情况。"},{"i":16,"n":"第十六条","txt":"饲料、饲料添加剂生产企业有下列情形之一的，由发证机关注销生产许可证： （一）生产许可证依法被撤销、撤回或依法被吊销的； （二）生产许可证有效期届满未按规定续展的； （三）企业停产一年以上或依法终止的； （四）企业申请注销的； （五）依法应当注销的其他情形。"},{"i":17,"n":"第十七条","txt":"县级以上人民政府饲料管理部门工作人员，不履行本办法规定的职责或者滥用职权、玩忽职守、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"申请人隐瞒有关情况或者提供虚假材料申请生产许可的，饲料管理部门不予受理或者不予许可，并给予警告；申请人在1年内不得再次申请生产许可。"},{"i":19,"n":"第十九条","txt":"以欺骗、贿赂等不正当手段取得生产许可证的，由发证机关撤销生产许可证，申请人在3年内不得再次申请生产许可；以欺骗方式取得生产许可证的，并处5万元以上10万元以下罚款；涉嫌犯罪的，及时将案件移送司法机关，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"饲料、饲料添加剂生产企业有下列情形之一的，依照《饲料和饲料添加剂管理条例》第三十八条处罚： （一）超出许可范围生产饲料、饲料添加剂的； （二）生产许可证有效期届满后，未依法续展继续生产饲料、饲料添加剂的。"},{"i":21,"n":"第二十一条","txt":"饲料、饲料添加剂生产企业采购单一饲料、饲料添加剂、药物饲料添加剂、添加剂预混合饲料，未查验相关许可证明文件的，依照《饲料和饲料添加剂管理条例》第四十条处罚。"},{"i":22,"n":"第二十二条","txt":"其他违反本办法的行为，依照《饲料和饲料添加剂管理条例》的有关规定处罚。"},{"i":23,"n":"第二十三条","txt":"本办法所称添加剂预混合饲料，包括复合预混合饲料、微量元素预混合饲料、维生素预混合饲料。 复合预混合饲料，是指以矿物质微量元素、维生素、氨基酸中任何两类或两类以上的营养性饲料添加剂为主，与其他饲料添加剂、载体和（或）稀释剂按一定比例配制的均匀混合物，其中营养性饲料添加剂的含量能够满足其适用动物特定生理阶段的基本营养需求，在配合饲料、精料补充料或动物饮用水中的添加量不低于0.1%且不高于10%。 微量元素预混合饲料，是指两种或两种以上矿物质微量元素与载体和（或）稀释剂按一定比例配制的均匀混合物，其中矿物质微量元素含量能够满足其适用动物特定生理阶段的微量元素需求，在配合饲料、精料补充料或动物饮用水中的添加量不低于0.1%且不高于10%。 维生素预混合饲料，是指两种或两种以上维生素与载体和（或）稀释剂按一定比例配制的均匀混合物，其中维生素含量应当满足其适用动物特定生理阶段的维生素需求，在配合饲"},{"i":24,"n":"第二十四条","txt":"本办法自2012年7月1日起施行。农业部1999年12月9日发布的《饲料添加剂和添加剂预混合饲料生产许可证管理办法》、2004年7月14日发布的《动物源性饲料产品安全卫生管理办法》、2006年11月24日发布的《饲料生产企业审查办法》同时废止。 本办法施行前已取得饲料生产企业审查合格证、动物源性饲料产品生产企业安全卫生合格证的饲料生产企业，应当在2014年7月1日前依照本办法规定取得生产许可证。"}],"siliaotianjiajichanpinpizhunwenhaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强饲料添加剂批准文号管理，根据《饲料和饲料添加剂管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称饲料添加剂，是指在饲料加工、制作、使用过程中添加的少量或者微量物质，包括营养性饲料添加剂和一般饲料添加剂。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内生产的饲料添加剂产品，在生产前应当取得相应的产品批准文号。"},{"i":4,"n":"第四条","txt":"饲料添加剂生产企业为其他饲料、饲料添加剂生产企业生产定制产品的，定制产品可以不办理产品批准文号。 定制产品应当附具符合《饲料和饲料添加剂管理条例》第二十一条规定的标签，并标明“定制产品”字样和定制企业的名称、地址及其生产许可证编号。 定制产品仅限于定制企业自用，生产企业和定制企业不得将定制产品提供给其他饲料、饲料添加剂生产企业、经营者和养殖者。"},{"i":5,"n":"第五条","txt":"饲料添加剂生产企业应当向省级人民政府饲料管理部门（以下简称省级饲料管理部门）提出产品批准文号申请，并提交以下资料： （一）产品批准文号申请表； （二）生产许可证复印件； （三）产品配方、产品质量标准和检测方法； （四）产品标签样式和使用说明； （五）涵盖产品主成分指标的产品自检报告； （六）申请饲料添加剂产品批准文号的，还应当提供省级饲料管理部门指定的饲料检验机构出具的产品主成分指标检测方法验证结论，但产品有国家或行业标准的除外； （七）申请新饲料添加剂产品批准文号的，还应当提供农业农村部核发的新饲料添加剂证书复印件。"},{"i":6,"n":"第六条","txt":"省级饲料管理部门应当自受理申请之日起10个工作日内对申请资料进行审查，必要时可以进行现场核查。审查合格的，通知企业将产品样品送交指定的饲料质量检验机构进行复核检测，并根据复核检测结果在10个工作日内决定是否核发产品批准文号。 产品复核检测应当涵盖产品质量标准规定的产品主成分指标和卫生指标。"},{"i":7,"n":"第七条","txt":"企业同时申请多个产品批准文号的，提交复核检测的样品应当符合下列要求： 申请饲料添加剂产品批准文号的，每个产品均应当提交样品。"},{"i":8,"n":"第八条","txt":"省级饲料管理部门和饲料质量检验机构的工作人员应当对申请者提供的需要保密的技术资料保密。"},{"i":9,"n":"第九条","txt":"饲料添加剂产品批准文号格式为： ×饲添字（××××）×××××× ×：核发产品批准文号省、自治区、直辖市的简称 （××××）：年份 ××××××：前三位表示本辖区企业的固定编号，后三位表示该产品获得的产品批准文号序号。"},{"i":10,"n":"第十条","txt":"饲料添加剂产品质量复核检测收费，按照国家有关规定执行。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，应当重新办理产品批准文号： （一）产品主成分指标改变的； （二）产品名称改变的。"},{"i":12,"n":"第十二条","txt":"禁止假冒、伪造、买卖产品批准文号。"},{"i":13,"n":"第十三条","txt":"饲料管理部门工作人员不履行本办法规定的职责或者滥用职权、玩忽职守、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":14,"n":"第十四条","txt":"申请人隐瞒有关情况或者提供虚假材料申请产品批准文号的，省级饲料管理部门不予受理或者不予许可，并给予警告；申请人在1年内不得再次申请产品批准文号。 以欺骗、贿赂等不正当手段取得产品批准文号的，由发证机关撤销产品批准文号，申请人在3年内不得再次申请产品批准文号；以欺骗方式取得产品批准文号的，并处5万元以上10万元以下罚款；涉嫌犯罪的，及时将案件移送司法机关，依法追究刑事责任。"},{"i":15,"n":"第十五条","txt":"假冒、伪造、买卖产品批准文号的，依照《饲料和饲料添加剂管理条例》第三十七条、第三十八条处罚。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，由省级饲料管理部门注销其产品批准文号并予以公告： （一）企业的生产许可证被吊销、撤销、撤回、注销的； （二）新饲料添加剂产品证书被撤销的。"},{"i":17,"n":"第十七条","txt":"饲料添加剂生产企业违反本办法规定，向定制企业以外的其他饲料、饲料添加剂生产企业、经营者或养殖者销售定制产品的，依照《饲料和饲料添加剂管理条例》第三十八条处罚。 定制企业违反本办法规定，向其他饲料、饲料添加剂生产企业、经营者和养殖者销售定制产品的，依照《饲料和饲料添加剂管理条例》第四十三条处罚。"},{"i":18,"n":"第十八条","txt":"其他违反本办法的行为，依照《饲料和饲料添加剂管理条例》的有关规定处罚。"},{"i":19,"n":"第十九条","txt":"本办法自2012年7月1日起施行。1999年12月14日发布的《饲料添加剂和添加剂预混合饲料产品批准文号管理办法》同时废止。"}],"siliaozhilianganquanguanliguifan":[{"i":1,"n":"第一条","txt":"为规范饲料企业生产行为，保障饲料产品质量安全，根据《饲料和饲料添加剂管理条例》，制定本规范。"},{"i":2,"n":"第二条","txt":"本规范适用于添加剂预混合饲料、浓缩饲料、配合饲料和精料补充料生产企业（以下简称企业）。"},{"i":3,"n":"第三条","txt":"企业应当按照本规范的要求组织生产，实现从原料采购到产品销售的全程质量安全控制。"},{"i":4,"n":"第四条","txt":"企业应当及时收集、整理、记录本规范执行情况和生产经营状况，认真履行饲料统计义务。 有委托生产行为的，委托方和受托方应当分别向所在地省级人民政府饲料管理部门备案。"},{"i":5,"n":"第五条","txt":"县级以上人民政府饲料管理部门应当制定年度监督检查计划，对企业实施本规范的情况进行监督检查。"},{"i":6,"n":"第六条","txt":"企业应当加强对饲料原料、单一饲料、饲料添加剂、药物饲料添加剂、添加剂预混合饲料和浓缩饲料（以下简称原料）的采购管理，全面评估原料生产企业和经销商（以下简称供应商）的资质和产品质量保障能力，建立供应商评价和再评价制度，编制合格供应商名录，填写并保存供应商评价记录： （一）供应商评价和再评价制度应当规定供应商评价及再评价流程、评价内容、评价标准、评价记录等内容； （二）从原料生产企业采购的，供应商评价记录应当包括生产企业名称及生产地址、联系方式、许可证明文件编号（评价单一饲料、饲料添加剂、药物饲料添加剂、添加剂预混合饲料、浓缩饲料生产企业时填写）、原料通用名称及商品名称、评价内容、评价结论、评价日期、评价人等信息； （三）从原料经销商采购的，供应商评价记录应当包括经销商名称及注册地址、联系方式、营业执照注册号、原料通用名称及商品名称、评价内容、评价结论、评价日期、评价人等信息； （四）合格"},{"i":7,"n":"第七条","txt":"企业应当建立原料采购验收制度和原料验收标准，逐批对采购的原料进行查验或者检验： （一）原料采购验收制度应当规定采购验收流程、查验要求、检验要求、原料验收标准、不合格原料处置、查验记录等内容； （二）原料验收标准应当规定原料的通用名称、主成分指标验收值、卫生指标验收值等内容，卫生指标验收值应当符合有关法律法规和国家、行业标准的规定； （三）企业采购实施行政许可的国产单一饲料、饲料添加剂、药物饲料添加剂、添加剂预混合饲料、浓缩饲料的，应当逐批查验许可证明文件编号和产品质量检验合格证，填写并保存查验记录；查验记录应当包括原料通用名称、生产企业、生产日期、查验内容、查验结果、查验人等信息；无许可证明文件编号和产品质量检验合格证的，或者经查验许可证明文件编号不实的，不得接收、使用； （四）企业采购实施登记管理的进口单一饲料、饲料添加剂、药物饲料添加剂、添加剂预混合饲料、浓缩饲料的，应当逐批查验进"},{"i":8,"n":"第八条","txt":"企业应当填写并保存原料进货台账，进货台账应当包括原料通用名称及商品名称、生产企业或者供货者名称、联系方式、产地、数量、生产日期、保质期、查验或者检验信息、进货日期、经办人等信息。 进货台账保存期限不得少于2年。"},{"i":9,"n":"第九条","txt":"企业应当建立原料仓储管理制度，填写并保存出入库记录： （一）原料仓储管理制度应当规定库位规划、堆放方式、垛位标识、库房盘点、环境要求、虫鼠防范、库房安全、出入库记录等内容； （二）出入库记录应当包括原料名称、包装规格、生产日期、供应商简称或者代码、入库数量和日期、出库数量和日期、库存数量、保管人等信息。"},{"i":10,"n":"第十条","txt":"企业应当按照“一垛一卡”的原则对原料实施垛位标识卡管理，垛位标识卡应当标明原料名称、供应商简称或者代码、垛位总量、已用数量、检验状态等信息。"},{"i":11,"n":"第十一条","txt":"企业应当对维生素、微生物和酶制剂等热敏物质的贮存温度进行监控，填写并保存温度监控记录。监控记录应当包括设定温度、实际温度、监控时间、记录人等信息。 监控中发现实际温度超出设定温度范围的，应当采取有效措施及时处置。"},{"i":12,"n":"第十二条","txt":"按危险化学品管理的亚硒酸钠等饲料添加剂的贮存间或者贮存柜应当设立清晰的警示标识，采用双人双锁管理。"},{"i":13,"n":"第十三条","txt":"企业应当根据原料种类、库存时间、保质期、气候变化等因素建立长期库存原料质量监控制度，填写并保存监控记录： （一）质量监控制度应当规定监控方式、监控内容、监控频次、异常情况界定、处置方式、处置权限、监控记录等内容； （二）监控记录应当包括原料名称、监控内容、异常情况描述、处置方式、处置结果、监控日期、监控人等信息。"},{"i":14,"n":"第十四条","txt":"企业应当制定工艺设计文件，设定生产工艺参数。 工艺设计文件应当包括生产工艺流程图、工艺说明和生产设备清单等内容。 生产工艺应当至少设定以下参数：粉碎工艺设定筛片孔径，混合工艺设定混合时间，制粒工艺设定调质温度、蒸汽压力、环模规格、环模长径比、分级筛筛网孔径，膨化工艺设定调质温度、模板孔径。"},{"i":15,"n":"第十五条","txt":"企业应当根据实际工艺流程，制定以下主要作业岗位操作规程： （一）小料（指生产过程中，将微量添加的原料预先进行配料或者配料混合后获得的中间产品）配料岗位操作规程，规定小料原料的领取与核实、小料原料的放置与标识、称重电子秤校准与核查、现场清洁卫生、小料原料领取记录、小料配料记录等内容； （二）小料预混合岗位操作规程，规定载体或者稀释剂领取、投料顺序、预混合时间、预混合产品分装与标识、现场清洁卫生、小料预混合记录等内容； （三）小料投料与复核岗位操作规程，规定小料投放指令、小料复核、现场清洁卫生、小料投料与复核记录等内容； （四）大料投料岗位操作规程，规定投料指令、垛位取料、感官检查、现场清洁卫生、大料投料记录等内容； （五）粉碎岗位操作规程，规定筛片锤片检查与更换、粉碎粒度、粉碎料入仓检查、喂料器和磁选设备清理、粉碎作业记录等内容； （六）中控岗位操作规程，规定设备开启与关闭原则、微机配料"},{"i":16,"n":"第十六条","txt":"企业应当根据实际工艺流程，制定生产记录表单，填写并保存相关记录： （一）小料原料领取记录，包括小料原料名称、领用数量、领取时间、领取人等信息； （二）小料配料记录，包括小料名称、理论值、实际称重值、配料数量、作业时间、配料人等信息； （三）小料预混合记录，包括小料名称、重量、批次、混合时间、作业时间、操作人等信息； （四）小料投料与复核记录，包括产品名称、接收批数、投料批数、重量复核、剩余批数、作业时间、投料人等信息； （五）大料投料记录，包括大料名称、投料数量、感官检查、作业时间、投料人等信息； （六）粉碎作业记录，包括物料名称、粉碎机号、筛片规格、作业时间、操作人等信息； （七）大料配料记录，包括配方编号、大料名称、配料仓号、理论值、实际值、作业时间、配料人等信息； （八）中控作业记录，包括产品名称、配方编号、清洗料、理论产量、成品仓号、洗仓情况、作业时间、操作人等信息； （九）制"},{"i":17,"n":"第十七条","txt":"企业应当采取有效措施防止生产过程中的交叉污染： （一）按照“无药物的在先、有药物的在后”原则制定生产计划； （二）生产含有药物饲料添加剂的产品后，生产不含药物饲料添加剂或者改变所用药物饲料添加剂品种的产品的，应当对生产线进行清洗；清洗料回用的，应当明确标识并回置于同品种产品中； （三）盛放饲料添加剂、药物饲料添加剂、添加剂预混合饲料、含有药物饲料添加剂的产品及其中间产品的器具或者包装物应当明确标识，不得交叉混用； （四）设备应当定期清理，及时清除残存料、粉尘积垢等残留物。"},{"i":18,"n":"第十八条","txt":"企业应当采取有效措施防止外来污染： （一）生产车间应当配备防鼠、防鸟等设施，地面平整，无污垢积存； （二）生产现场的原料、中间产品、返工料、清洗料、不合格品等应当分类存放，清晰标识； （三）保持生产现场清洁，及时清理杂物； （四）按照产品说明书规范使用润滑油、清洗剂； （五）不得使用易碎、易断裂、易生锈的器具作为称量或者盛放用具； （六）不得在饲料生产过程中进行维修、焊接、气割等作业。"},{"i":19,"n":"第十九条","txt":"企业应当建立配方管理制度，规定配方的设计、审核、批准、更改、传递、使用等内容。"},{"i":20,"n":"第二十条","txt":"企业应当建立产品标签管理制度，规定标签的设计、审核、保管、使用、销毁等内容。 产品标签应当专库（柜）存放，专人管理。"},{"i":21,"n":"第二十一条","txt":"企业应当对生产配方中添加比例小于0.2%的原料进行预混合。"},{"i":22,"n":"第二十二条","txt":"企业应当根据产品混合均匀度要求，确定产品的最佳混合时间，填写并保存最佳混合时间实验记录。实验记录应当包括混合机编号、混合物料名称、混合次数、混合时间、检验结果、最佳混合时间、检验日期、检验人等信息。 企业应当每6个月按照产品类别（添加剂预混合饲料、配合饲料、浓缩饲料、精料补充料）进行至少1次混合均匀度验证，填写并保存混合均匀度验证记录。验证记录应当包括产品名称、混合机编号、混合时间、检验方法、检验结果、验证结论、检验日期、检验人等信息。 混合机发生故障经修复投入生产前，应当按照前款规定进行混合均匀度验证。"},{"i":23,"n":"第二十三条","txt":"企业应当建立生产设备管理制度和档案，制定粉碎机、混合机、制粒机、膨化机、空气压缩机等关键设备操作规程，填写并保存维护保养记录和维修记录： （一）生产设备管理制度应当规定采购与验收、档案管理、使用操作、维护保养、备品备件管理、维护保养记录、维修记录等内容； （二）设备操作规程应当规定开机前准备、启动与关闭、操作步骤、关机后整理、日常维护保养等内容； （三）维护保养记录应当包括设备名称、设备编号、保养项目、保养日期、保养人等信息； （四）维修记录应当包括设备名称、设备编号、维修部位、故障描述、维修方式及效果、维修日期、维修人等信息； （五）关键设备应当实行“一机一档”管理，档案包括基本信息表（名称、编号、规格型号、制造厂家、联系方式、安装日期、投入使用日期）、使用说明书、操作规程、维护保养记录、维修记录等内容。"},{"i":24,"n":"第二十四条","txt":"企业应当严格执行国家安全生产相关法律法规。 生产设备、辅助系统应当处于正常工作状态；锅炉、压力容器等特种设备应当通过安全检查；计量秤、地磅、压力表等测量设备应当定期检定或者校验。"},{"i":25,"n":"第二十五条","txt":"企业应当建立现场质量巡查制度，填写并保存现场质量巡查记录： （一）现场质量巡查制度应当规定巡查位点、巡查内容、巡查频次、异常情况界定、处置方式、处置权限、巡查记录等内容； （二）现场质量巡查记录应当包括巡查位点、巡查内容、异常情况描述、处置方式、处置结果、巡查时间、巡查人等信息。"},{"i":26,"n":"第二十六条","txt":"企业应当建立检验管理制度，规定人员资质与职责、样品抽取与检验、检验结果判定、检验报告编制与审核、产品质量检验合格证签发等内容。"},{"i":27,"n":"第二十七条","txt":"企业应当根据产品质量标准实施出厂检验，填写并保存产品出厂检验记录；检验记录应当包括产品名称或者编号、检验项目、检验方法、计算公式中符号的含义和数值、检验结果、检验日期、检验人等信息。 产品出厂检验记录保存期限不得少于2年。"},{"i":28,"n":"第二十八条","txt":"企业应当每周从其生产的产品中至少抽取5个批次的产品自行检验下列主成分指标： （一）维生素预混合饲料：两种以上维生素； （二）微量元素预混合饲料：两种以上微量元素； （三）复合预混合饲料：两种以上维生素和两种以上微量元素； （四）浓缩饲料、配合饲料、精料补充料：粗蛋白质、粗灰分、钙、总磷。主成分指标检验记录保存期限不得少于2年。"},{"i":29,"n":"第二十九条","txt":"企业应当根据仪器设备配置情况，建立分析天平、高温炉、干燥箱、酸度计、分光光度计、高效液相色谱仪、原子吸收分光光度计等主要仪器设备操作规程和档案，填写并保存仪器设备使用记录： （一）仪器设备操作规程应当规定开机前准备、开机顺序、操作步骤、关机顺序、关机后整理、日常维护、使用记录等内容； （二）仪器设备使用记录应当包括仪器设备名称、型号或者编号、使用日期、样品名称或者编号、检验项目、开始时间、完毕时间、仪器设备运行前后状态、使用人等信息； （三）仪器设备应当实行“一机一档”管理，档案包括仪器基本信息表（名称、编号、型号、制造厂家、联系方式、安装日期、投入使用日期）、使用说明书、购置合同、操作规程、使用记录等内容。"},{"i":30,"n":"第三十条","txt":"企业应当建立化学试剂和危险化学品管理制度，规定采购、贮存要求、出入库、使用、处理等内容。 化学试剂、危险化学品以及试验溶液的使用，应当遵循GB/T 601、GB/T 602、GB/T 603以及检验方法标准的要求。 企业应当填写并保存危险化学品出入库记录，记录应当包括危险化学品名称、入库数量和日期、出库数量和日期、保管人等信息。"},{"i":31,"n":"第三十一条","txt":"企业应当每年选择5个检验项目，采取以下一项或者多项措施进行检验能力验证，对验证结果进行评价并编制评价报告： （一）同具有法定资质的检验机构进行检验比对； （二）利用购买的标准物质或者高纯度化学试剂进行检验验证； （三）在实验室内部进行不同人员、不同仪器的检验比对； （四）对曾经检验过的留存样品进行再检验； （五）利用检验质量控制图等数理统计手段识别异常数据。"},{"i":32,"n":"第三十二条","txt":"企业应当建立产品留样观察制度，对每批次产品实施留样观察，填写并保存留样观察记录： （一）留样观察制度应当规定留样数量、留样标识、贮存环境、观察内容、观察频次、异常情况界定、处置方式、处置权限、到期样品处理、留样观察记录等内容； （二）留样观察记录应当包括产品名称或者编号、生产日期或者批号、保质截止日期、观察内容、异常情况描述、处置方式、处置结果、观察日期、观察人等信息。 留样保存时间应当超过产品保质期1个月。"},{"i":33,"n":"第三十三条","txt":"企业应当建立不合格品管理制度，填写并保存不合格品处置记录： （一）不合格品管理制度应当规定不合格品的界定、标识、贮存、处置方式、处置权限、处置记录等内容； （二）不合格品处置记录应当包括不合格品的名称、数量、不合格原因、处置方式、处置结果、处置日期、处置人等信息。"},{"i":34,"n":"第三十四条","txt":"企业应当建立产品仓储管理制度，填写并保存出入库记录： （一）仓储管理制度应当规定库位规划、堆放方式、垛位标识、库房盘点、环境要求、虫鼠防范、库房安全、出入库记录等内容； （二）出入库记录应当包括产品名称、规格或者等级、生产日期、入库数量和日期、出库数量和日期、库存数量、保管人等信息； （三）不同产品的垛位之间应当保持适当距离； （四）不合格产品和过期产品应当隔离存放并有清晰标识。"},{"i":35,"n":"第三十五条","txt":"企业应当在产品装车前对运输车辆的安全、卫生状况实施检查。"},{"i":36,"n":"第三十六条","txt":"企业使用罐装车运输产品的，应当专车专用，并随车附具产品标签和产品质量检验合格证。 装运不同产品时，应当对罐体进行清理。"},{"i":37,"n":"第三十七条","txt":"企业应当填写并保存产品销售台账。销售台账应当包括产品的名称、数量、生产日期、生产批次、质量检验信息、购货者名称及其联系方式、销售日期等信息。 销售台账保存期限不得少于2年。"},{"i":38,"n":"第三十八条","txt":"企业应当建立客户投诉处理制度，填写并保存客户投诉处理记录： （一）投诉处理制度应当规定投诉受理、处理方法、处理权限、投诉处理记录等内容； （二）投诉处理记录应当包括投诉日期、投诉人姓名和地址、产品名称、生产日期、投诉内容、处理结果、处理日期、处理人等信息。"},{"i":39,"n":"第三十九条","txt":"企业应当建立产品召回制度，填写并保存召回记录： （一）召回制度应当规定召回流程、召回产品的标识和贮存、召回记录等内容； （二）召回记录应当包括产品名称、召回产品使用者、召回数量、召回日期等信息。 企业应当每年至少进行1次产品召回模拟演练，综合评估演练结果并编制模拟演练总结报告。"},{"i":40,"n":"第四十条","txt":"企业应当在饲料管理部门的监督下对召回产品进行无害化处理或者销毁，填写并保存召回产品处置记录。处置记录应当包括处置产品名称、数量、处置方式、处置日期、处置人、监督人等信息。"},{"i":41,"n":"第四十一条","txt":"企业应当建立人员培训制度，制定年度培训计划，每年对员工进行至少2次饲料质量安全知识培训，填写并保存培训记录： （一）人员培训制度应当规定培训范围、培训内容、培训方式、考核方式、效果评价、培训记录等内容； （二）培训记录应当包括培训对象、内容、师资、日期、地点、考核方式、考核结果等信息。"},{"i":42,"n":"第四十二条","txt":"厂区环境卫生应当符合国家有关规定。"},{"i":43,"n":"第四十三条","txt":"企业应当建立记录管理制度，规定记录表单的编制、格式、编号、审批、印发、修订、填写、存档、保存期限等内容。 除本规范中明确规定保存期限的记录外，其他记录保存期限不得少于1年。"},{"i":44,"n":"第四十四条","txt":"本规范自2015年7月1日起施行。"}],"gaozhibingxingdongwubingyuanweishengwushiyanshishe4c85d2":[{"i":1,"n":"第一条","txt":"为了规范高致病性动物病原微生物实验室生物安全管理的审批工作，根据《病原微生物实验室生物安全管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"高致病性动物病原微生物的实验室资格、实验活动和运输的审批，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称高致病性动物病原微生物是指来源于动物的、《动物病原微生物分类名录》中规定的第一类、第二类病原微生物。 《动物病原微生物分类名录》由农业部商国务院有关部门后制定、调整并予以公布。"},{"i":4,"n":"第四条","txt":"农业部主管全国高致病性动物病原微生物实验室生物安全管理工作。 县级以上地方人民政府兽医行政管理部门负责本行政区域内高致病性动物病原微生物实验室生物安全管理工作。"},{"i":5,"n":"第五条","txt":"实验室从事高致病性动物病原微生物实验活动，应当取得农业部颁发的《高致病性动物病原微生物实验室资格证书》。"},{"i":6,"n":"第六条","txt":"实验室申请《高致病性动物病原微生物实验室资格证书》，应当具备下列条件： （一）依法从事动物疫病的研究、检测、诊断，以及菌（毒）种保藏等活动； （二）符合农业部颁发的《兽医实验室生物安全管理规范》； （三）取得国家生物安全三级或者四级实验室认可证书； （四）从事实验活动的工作人员具备兽医相关专业大专以上学历或中级以上技术职称，受过生物安全知识培训； （五）实验室工程质量经依法检测验收合格。"},{"i":7,"n":"第七条","txt":"符合前条规定条件的，申请人应当向所在地省、自治区、直辖市人民政府兽医行政管理部门提出申请，并提交下列材料： （一）高致病性动物病原微生物实验室资格申请表一式两份； （二）实验室管理手册； （三）国家实验室认可证书复印件； （四）实验室设立单位的法人资格证书复印件； （五）实验室工作人员学历证书或者技术职称证书复印件； （六）实验室工作人员生物安全知识培训情况证明材料； （七）实验室工程质量检测验收报告复印件。 省、自治区、直辖市人民政府兽医行政管理部门应当自收到申请之日起10日内，将初审意见和有关材料报送农业部。 农业部收到初审意见和有关材料后，组织专家进行评审，必要时可到现场核实和评估。农业部自收到专家评审意见之日起10日内作出是否颁发《高致病性动物病原微生物实验室资格证书》的决定；不予批准的，及时告知申请人并说明理由。"},{"i":8,"n":"第八条","txt":"《高致病性动物病原微生物实验室资格证书》有效期为5年。有效期届满，实验室需要继续从事高致病性动物病原微生物实验活动的，应当在届满6个月前，按照本办法的规定重新申请《高致病性动物病原微生物实验室资格证书》。"},{"i":9,"n":"第九条","txt":"一级、二级实验室不得从事高致病性动物病原微生物实验活动。三级、四级实验室需要从事某种高致病性动物病原微生物或者疑似高致病性动物病原微生物实验活动的，应当经农业部或者省、自治区、直辖市人民政府兽医行政管理部门批准。"},{"i":10,"n":"第十条","txt":"三级、四级实验室从事某种高致病性动物病原微生物或者疑似高致病性动物病原微生物实验活动的，应当具备下列条件： （一）取得农业部颁发的《高致病性动物病原微生物实验室资格证书》，并在有效期内； （二）实验活动限于与动物病原微生物菌（毒）种、样本有关的研究、检测、诊断和菌（毒）种保藏等。 农业部对特定高致病性动物病原微生物或疑似高致病性动物病原微生物实验活动的实验单位有明确规定的，只能在规定的实验室进行。"},{"i":11,"n":"第十一条","txt":"符合前条规定条件的，申请人应当向所在地省、自治区、直辖市人民政府兽医行政管理部门提出申请，并提交下列材料： （一）高致病性动物病原微生物实验活动申请表一式两份； （二）高致病性动物病原微生物实验室资格证书复印件； （三）从事与高致病性动物病原微生物有关的科研项目的，还应当提供科研项目立项证明材料。 从事我国尚未发现或者已经宣布消灭的动物病原微生物有关实验活动的，或者从事国家规定的特定高致病性动物病原微生物病原分离和鉴定、活病毒培养、感染材料核酸提取、动物接种试验等有关实验活动的，省、自治区、直辖市人民政府兽医行政管理部门应当自收到申请之日起7日内，将初审意见和有关材料报送农业部。农业部自收到初审意见和有关材料之日起8日内作出是否批准的决定；不予批准的，及时通知申请人并说明理由。 从事前款规定以外的其他高致病性动物病原微生物或者疑似高致病性动物病原微生物实验活动的，省、自治区、直辖市人民"},{"i":12,"n":"第十二条","txt":"实验室申报或者接受与高致病性动物病原微生物有关的科研项目前，应当向农业部申请审查，并提交以下材料： （一）高致病性动物病原微生物科研项目生物安全审查表一式两份； （二）科研项目建议书； （三）科研项目研究中采取的生物安全措施。 农业部自收到申请之日起20日内作出是否同意的决定。 科研项目立项后，需要从事与高致病性动物病原微生物有关的实验活动的，应当按照本办法第十条、第十一条的规定，经农业部或者省、自治区、直辖市人民政府兽医行政管理部门批准。"},{"i":13,"n":"第十三条","txt":"出入境检验检疫机构、动物防疫机构在实验室开展检测、诊断工作时，发现高致病性动物病原微生物或疑似高致病性动物病原微生物，需要进一步从事这类高致病性动物病原微生物病原分离和鉴定、活病毒培养、感染材料核酸提取、动物接种试验等相关实验活动的，应当按照本办法第十条、第十一条的规定，经农业部或者省、自治区、直辖市人民政府兽医行政管理部门批准。"},{"i":14,"n":"第十四条","txt":"出入境检验检疫机构为了检验检疫工作的紧急需要，申请在实验室对高致病性动物病原微生物或疑似高致病性动物病原微生物开展病原分离和鉴定、活病毒培养、感染材料核酸提取、动物接种试验等进一步实验活动的，应当具备下列条件，并按照本办法第十一条的规定提出申请。 （一）实验目的仅限于检疫； （二）实验活动符合法定检疫规程； （三）取得农业部颁发的《高致病性动物病原微生物实验室资格证书》，并在有效期内。 农业部或者省、自治区、直辖市人民政府兽医行政管理部门自收到申请之时起2小时内作出是否批准的决定；不批准的，通知申请人并说明理由。2小时内未作出决定的，出入境检验检疫机构实验室可以从事相应的实验活动。"},{"i":15,"n":"第十五条","txt":"实验室在实验活动期间，应当按照《病原微生物实验室生物安全管理条例》的规定，做好实验室感染控制、生物安全防护、病原微生物菌（毒）种保存和使用、安全操作、实验室排放的废水和废气以及其他废物处置等工作。"},{"i":16,"n":"第十六条","txt":"实验室在实验活动结束后，应当及时将病原微生物菌（毒）种、样本就地销毁或者送交农业部指定的保藏机构保藏，并将实验活动结果以及工作情况向原批准部门报告。"},{"i":17,"n":"第十七条","txt":"运输高致病性动物病原微生物菌（毒）种或者样本的，应当经农业部或者省、自治区、直辖市人民政府兽医行政管理部门批准。"},{"i":18,"n":"第十八条","txt":"运输高致病性动物病原微生物菌（毒）种或者样本的，应当具备下列条件： （一）运输的高致病性动物病原微生物菌（毒）种或者样本仅限用于依法进行的动物疫病的研究、检测、诊断、菌（毒）种保藏和兽用生物制品的生产等活动； （二）接收单位是研究、检测、诊断机构的，应当取得农业部颁发的《高致病性动物病原微生物实验室资格证书》，并取得农业部或者省、自治区、直辖市人民政府兽医行政管理部门颁发的从事高致病性动物病原微生物或者疑似高致病性动物病原微生物实验活动批准文件；接收单位是兽用生物制品研制和生产单位的，应当取得农业部颁发的生物制品批准文件；接收单位是菌（毒）种保藏机构的，应当取得农业部颁发的指定菌（毒）种保藏的文件； （三）盛装高致病性动物病原微生物菌（毒）种或者样本的容器或者包装材料应当符合农业部制定的《高致病性动物病原微生物菌（毒）种或者样本运输包装规范》。"},{"i":19,"n":"第十九条","txt":"符合前条规定条件的，申请人应当向出发地省、自治区、直辖市人民政府兽医行政管理部门提出申请，并提交以下材料： （一）运输高致病性动物病原微生物菌（毒）种（样本）申请表一式两份; （二）前条第二项规定的有关批准文件复印件； （三）接收单位同意接收的证明材料，但送交菌（毒）种保藏的除外。 在省、自治区、直辖市人民政府行政区域内运输的，省、自治区、直辖市人民政府兽医行政管理部门应当对申请人提交的申请材料进行审查，符合条件的，即时批准，发给《高致病性动物病原微生物菌（毒）种、样本准运证书》；不予批准的，应当即时告知申请人。 需要跨省、自治区、直辖市运输或者运往国外的，由出发地省、自治区、直辖市人民政府兽医行政管理部门进行初审，并将初审意见和有关材料报送农业部。农业部应当对初审意见和有关材料进行审查，符合条件的，即时批准，发给《高致病性动物病原微生物菌（毒）种、样本准运证书》；不予批准的，应当即时"},{"i":20,"n":"第二十条","txt":"申请人凭《高致病性动物病原微生物菌（毒）种、样本准运证书》运输高致病性动物病原微生物菌（毒）种或者样本；需要通过铁路、公路、民用航空等公共交通工具运输的，凭《高致病性动物病原微生物菌（毒）种、样本准运证书》办理承运手续；通过民航运输的，还需经过国务院民用航空主管部门批准。"},{"i":21,"n":"第二十一条","txt":"出入境检验检疫机构在检疫过程中运输动物病原微生物样本的，由国务院出入境检验检疫部门批准，同时向农业部通报。"},{"i":22,"n":"第二十二条","txt":"对违反本办法规定的行为，依照《病原微生物实验室生物安全管理条例》第五十六条、第五十七条、第五十八条、第五十九条、第六十条、第六十二条、第六十三条的规定予以处罚。"},{"i":23,"n":"第二十三条","txt":"本办法规定的《高致病性动物病原微生物实验室资格证书》、《从事高致病性动物病原微生物实验活动批准文件》和《高致病性动物病原微生物菌（毒）种、样本准运证书》由农业部印制。 《高致病性动物病原微生物实验室资格申请表》、《高致病性动物病原微生物实验活动申请表》、《运输高致病性动物病原微生物菌（毒）种、样本申请表》和《高致病性动物病原微生物科研项目生物安全审查表》可以从中国农业信息网（http://www.agri.gov.cn）下载。"},{"i":24,"n":"第二十四条","txt":"本办法自公布之日起施行。"}]};
